					{ kind = "collect", item = 12341, note = "Blackwood Fruit Sample" },
					{ kind = "collect", item = 12342, note = "Blackwood Grain Sample" },
					{ kind = "use", quest = 4763, objective = 1, item = 12347, map = 1439, x = 52.5, y = 33.4, note = "By the bonfire closest to the river: summons Xabraxxis" },
