				{ title = "Henze Faulk", tip = "On the road east, past the Tower of Azora, head north from the bridge to Stone Cairn Lake. Henze Faulk lies south of the lake: use the Symbol of Life on him. The Defias Rogue Wizards around him carry the Defias Script.", only = { races = { "Human" }, classes = { "Paladin" } }, when = { { test = "onquest", quests = { 1786, 1787 } } }, zone = 1429, goals = {
