					{ kind = "accept", quest = 226, note = "Lars" },
				} },
				{ title = "The Hushed Bank: kill these as you meet them", tip = "Rabid Dire Wolves roam the woods around the cemetery and Abercrombie, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders are the small spiders, and few: most crawl along the Hushed Bank west of Raven Hill, fewer up north towards Sven's camp; they drop the venom too. Every ghoul of the cemetery's northern half can drop a fang. Wolves and the bigger spiders share the Westfall border, so pull with care.", zone = 1431, goals = {
					{ kind = "kill", quest = 226, npc = 565, note = "Rabid Dire Wolf" },
					{ kind = "kill", quest = 226, npc = 213, note = "Starving Dire Wolf" },
					{ kind = "kill", quest = 245, npc = 539, map = 1431, x = 10.6, y = 55.4, note = "Pygmy Venom Web Spider" },
					{ kind = "collect", quest = 101, item = 1130, note = "Vial of Spider Venom: Pygmy Venom Web Spiders, Venom Web Spiders and Green Recluses" },
