					{ kind = "collect", quest = 98417, item = 281014, map = 1440, x = 81.7, y = 49.2, note = "Vine-Wrapped Scroll, from Kurothel's Knapsack" },
				} },
				{ title = "Kayneth Stillwind", tip = "Optional: Kayneth also offers Insane Druids, three level 32 druids deep in The Dor'Danil Barrow Den, a cave of quickly respawning, stealthed mobs, and back to her afterwards. It is above your level here: take it only if you are grouped or want the extra XP; the guide doesn't need it.", zone = 1440, goals = {
					{ kind = "turnin", quest = 1011 },
					{ kind = "accept", quest = 1012, optional = true },
					{ kind = "turnin", quest = 98417, note = "Maseara Autumnmoon, a few steps east" },
