				{ title = "The Dor'Danil Barrow Den's entrance", when = { { test = "onquest", quests = { 1012 } } }, zone = 1440, goals = {
					{ kind = "goto", label = "The Dor'Danil Barrow Den", map = 1440, x = 75.95, y = 75.45, frame = "live" },
				} },
				{ title = "Insane druids", tip = "The three druids are inside The Dor'Danil Barrow Den, apart from each other: go in at its mouth, south of the Forsaken camp, not over the hill above them. Taneel Darkwood is in the eastern halls, Uthil Mooncall deepest down at the north-east end and Mavoris Cloudsbreak at the western end.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight.", when = { { test = "onquest", quests = { 1012 } } }, zone = 1440, goals = {
					{ kind = "kill", quest = 1012, objective = 1, npc = 3940, note = "Taneel Darkwood, inside The Dor'Danil Barrow Den" },
					{ kind = "kill", quest = 1012, objective = 2, npc = 3941, note = "Uthil Mooncall, inside The Dor'Danil Barrow Den" },
					{ kind = "kill", quest = 1012, objective = 3, npc = 3942, note = "Mavoris Cloudsbreak, inside The Dor'Danil Barrow Den" },
