				} },
				{ title = "The Green Belt", tip = "Maddened Rotclaws roam the Green Belt around Rethiel; one of them drops the flesh. Rethiel takes the quest only with Carnage's head too.", when = { { item = 280330, test = "has" } }, zone = 1437, goals = {
					{ kind = "collect", quest = 98283, objective = 1, item = 280331, note = "Malignant Rotclaw Flesh" },
