				{ title = "Northfold Manor", tip = "The Syndicate hold the farm north-west of Refuge Pointe.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot.", zone = 1417, goals = {
					{ kind = "kill", quest = 681, objective = 1, npc = 2586, note = "Syndicate Highwayman" },
					{ kind = "kill", quest = 681, objective = 2, npc = 2589, note = "Syndicate Mercenary" },
				} },
				{ title = "Hay Weevil", tip = "Hay Weevils crawl about the north end of Northfold Manor's farm: catch one with the tool from Amaryllis Webb's Entomology Starter Kit.", when = { { test = "onquest", quests = { 93176 } } }, zone = 1417, goals = {
					{ kind = "collect", item = 213568, name = "Hay Weevil Specimen", map = 1417, x = 31.3, y = 27.2 },
				} },
				{ title = "Shards of Myzrael", tip = "East from Northfold Manor across the north of the Highlands; the shards glitter on the hill by the Circle of East Binding, north of Go'Shek Farm.", zone = 1417, goals = {
					{ kind = "turnin", quest = 635, optional = true, note = "Only if Gluggle gave you the pendant in Stranglethorn" },
					{ kind = "accept", quest = 642 },
				} },
				{ title = "Drywhisker Gorge: kill these as you meet them", tip = "The Drywhisker kobolds dig in the gorge east of Hammerfall (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need Mining 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", zone = 1417, goals = {
					{ kind = "collect", quest = 627, item = 4278, optional = true, note = "Lesser Bloodstone Ore" },
					{ kind = "collect", quest = 642, item = 4435, note = "Mote of Myzrael from Drywhisker Kobold, Drywhisker Surveyor and Drywhisker Digger, by this stop" },
				} },
				{ title = "Iridescent Shards", tip = "The shards lie at the far end of Drywhisker Gorge.", zone = 1417, goals = {
					{ kind = "turnin", quest = 642, note = "Below ground" },
					{ kind = "accept", quest = 651 },
				} },
				{ title = "Stones of Binding", tip = "Each key lies at one of the Highlands' standing-stone circles: east of the shards, near Refuge Pointe and in the west. The Stone of Inner Binding stands west of Refuge Pointe.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", zone = 1417, goals = {
					{ kind = "collect", quest = 651, objective = 2, item = 4484, note = "Cresting Key: Stone of East Binding" },
				} },
				{ title = "Witherbark Village", tip = "South from the Stone of East Binding, past Go'Shek Farm, to Witherbark Village in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk.", zone = 1417, goals = {
					{ kind = "collect", quest = 691, objective = 1, item = 4503, note = "Witherbark Tusk" },
					{ kind = "collect", quest = 691, objective = 2, item = 4522, note = "Witherbark Medicine Pouch" },
					{ kind = "collect", quest = 691, objective = 3, item = 5040, note = "Shadow Hunter Knife; below ground" },
				} },
