				{ title = "Faldir's Cove", tip = "South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it.", zone = 1417, goals = {
					{ kind = "accept", quest = 663, note = "Lolo the Lookout" },
					{ kind = "turnin", quest = 663, note = "Shakes O'Breen" },
