				{ title = "Kor'gresh Coldrage", tip = "East from Faldir's Cove through the southern hills: Kor'gresh, an ogre mage, holds the cave at the southern end of the Witherbark valley.", zone = 1417, goals = {
					{ kind = "collect", quest = 693, item = 4525, note = "Trelane's Wand of Invocation; below ground" },
				} },
				{ title = "Foggy MacKreel", tip = "South-west from Kor'gresh's cave to the Thandol Span: Foggy MacKreel stands on a broken section of the bridge; jump down to him from its north end. MacKreel's Moonshine must reach Brewmeister Bilger in Southshore within 15 minutes: go straight back to Refuge Pointe and fly to Southshore.", zone = 1417, goals = {
