				{ title = "Alterac Mountains", zone = 1416, goals = {
					{ kind = "goto", label = "Gavin's Naze", map = 1416, x = 45, y = 77.2 },
				} },
				{ title = "Gavin's Naze", tip = "Follow the road north out of Southshore into the mountains. Mountain lions roam the slopes; the Syndicate in Strahnbrad wear the signet rings. Baron Vardus (40) turns up in one spot at a time: the cellar of Strahnbrad's inn, or one of the Syndicate tent camps in the uplands north and north-west of the village.", zone = 1416, goals = {
