					{ kind = "kill", quest = 564, objective = 1, npc = 2406, map = 1416, x = 32.1, y = 82.8, note = "Mountain Lion" },
				} },
				{ title = "Ruins of Alterac: kill these as you meet them", tip = "The tomes lie in the ruined keep west of Strahnbrad; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up.", zone = 1416, goals = {
					{ kind = "collect", quest = 540, objective = 1, item = 3658, note = "Recovered Tome: Crushridge ogres" },
					{ kind = "collect", quest = 540, objective = 2, item = 3659, note = "Worn Leather Book: the Weathered Bookcase; inside" },
				} },
				{ title = "Ruins of Alterac: kill these as you meet them", tip = "These are elite mobs: grouping up is encouraged, look for people to do it with. Grel'borg the Miser is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nGrel'borg walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path.", when = { { quest = 543, test = "group" } }, zone = 1416, goals = {
					{ kind = "collect", quest = 543, objective = 1, item = 3684, map = 1416, x = 35.6, y = 54.4 },
				} },
				{ title = "Strahnbrad: kill these as you meet them", tip = "Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside Nagaz's house. Nagaz does not join when they are pulled, and a ranged attack through the doorway brings him out by himself.", zone = 1416, goals = {
					{ kind = "collect", quest = 512, item = 3505, note = "Alterac Signet Ring" },
					{ kind = "kill", quest = 537, objective = 1, npc = 2318, note = "Argus Shadow Mage" },
					{ kind = "collect", quest = 523, item = 3626, note = "Head of Baron Vardus" },
				} },
				{ title = "Crushridge ogres", tip = "The Crushridge ogres hold the hills north of Strahnbrad. Farther north, a worn wooden chest holds the Ensorcelled Parchment; Nagaz of the Dark Council stands right by it.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up.", zone = 1416, goals = {
					{ kind = "collect", quest = 500, item = 2843, note = "Dirty Knucklebones" },
					{ kind = "collect", item = 3706, name = "Ensorcelled Parchment", note = "Inside" },
					{ kind = "accept", quest = 551 },
					{ kind = "collect", quest = 537, objective = 2, item = 3672, note = "Head of Nagaz" },
				} },
