				{ title = "Agmond's End", tip = "The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south.", zone = 1418, goals = {
					{ kind = "turnin", quest = 738, note = "Battered Dwarven Skeleton" },
				} },
				{ title = "Agmond's End: kill these as you meet them", tip = "The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; Murdaloc, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use Battle Shout and Demoralizing Shout, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of Kargath.", zone = 1418, goals = {
					{ kind = "collect", quest = 733, item = 4630, note = "Scrap Metal" },
					{ kind = "collect", quest = 703, item = 3404, note = "Buzzard Wing" },
					{ kind = "collect", quest = 2500, item = 7847, note = "Buzzard Gizzard" },
					{ kind = "accept", quest = 739, note = "Battered Dwarven Skeleton" },
					{ kind = "note", text = "Murdaloc himself (42) walks among the Bonesnappers: leave him for the later Badlands guide at 43, and kill the Bonesnappers for this quest now." },
