			id = "forever/alliance/40-50/01-stranglethorn-vale", title = "Stranglethorn Vale, Dustwallow Marsh & Swamp of Sorrows", category = "Leveling", faction = "Alliance", levels = { 40, 43 }, zone = 1434, next = "forever/alliance/40-50/02-badlands", version = 1, revision = "63f5dbe357b97b8f39f0c91d73ee2694119ee3541421e4a3df41235ad636512b", legacyRevision = "1fec720b8dc2e32d72797b08712b4312fba90ae11292074074726b98388c2624",
			steps = {
				{ title = "Theramore", tip = "Morgan Stern stands near the inn; Helenia Olden, a trade supplier a few steps south, sells the spices Jarl wants.", zone = 1445, goals = {
