					{ kind = "turnin", quest = 1218, note = "with the spices from Theramore" },
					{ kind = "accept", quest = 1206 },
				} },
				{ title = "\"Stinky\" Ignatz", tip = "Stinky waits west of the manor, in the marsh below North Point Tower. Lead him to his Bogbean leaves and keep the swamp creatures off him.", zone = 1445, goals = {
					{ kind = "accept", quest = 1222 },
					{ kind = "complete", quest = 1222, map = 1445, x = 48.9, y = 24.6 },
				} },
				{ title = "North Point Tower", tip = "Private Hendel holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\nArchmage Tervosh and Lady Jaina Proudmoore wait beside the tower: once he yields, hand in to both on the spot.", zone = 1445, goals = {
					{ kind = "turnin", quest = 1266, note = "Private Hendel" },
					{ kind = "accept", quest = 1324 },
					{ kind = "complete", quest = 1324 },
					{ kind = "turnin", quest = 1324, map = 1445, x = 45.2, y = 24.4, note = "Archmage Tervosh" },
					{ kind = "turnin", quest = 1267, map = 1445, x = 45.2, y = 24.3, direct = true },
				} },
				{ title = "Darkmist Cavern", tip = "The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them.", zone = 1445, goals = {
