				{ title = "Level 42.16 at Zul'Mamwe", tip = "Alone, you skip Nesingwary's three elite hunts: take their experience from the Skullsplitter trolls of Zul'Mamwe instead, just east of the mine, so every kill also counts for Kebok's tusks. Or, with a group, run the Uldaman dungeon instead.", when = { { quest = 193, test = "group", negate = true }, { quest = 197, test = "group", negate = true }, { quest = 208, test = "group", negate = true }, { level = 42.16, test = "level", op = "<" } }, zone = 1434, goals = {
