					{ kind = "collect", quest = 98403, objective = 2, item = 281023, note = "Mature Fel Moss: Xethorr the Wicked" },
				} },
				{ title = "The Wellspring River", tip = "West from the webwoods to the Wellspring River, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.", zone = 1438, goals = {
					{ kind = "collect", quest = 923, objective = 1, item = 5170, note = "Mossy Tumor: timberlings" },
				} },
				{ title = "The Oracle Glade", tip = "The moonwell is in the middle of the glade. The Strange Fronded Plant grows at its north end.", zone = 1438, goals = {
					{ kind = "accept", quest = 937, note = "Sentinel Arynia Cloudsbreak, by the moonwell" },
