					{ kind = "accept", quest = 983, note = "Wizbang Cranktoggle, upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart" },
					{ kind = "getfp", place = "Auberdine" },
				} },
				{ title = "Return to Nessa", tip = "Fly back to Rut'theran Village from Caylais Moonfeather, hand Laird's Response to Nessa on the dock, then fly back to Auberdine.", only = { exceptClasses = { "Druid" } }, zone = 1438, goals = {
