		{
			id = "forever/class/druid/aquatic-form", title = "Aquatic Form", category = "Class", folder = "Druid", classes = { "Druid" }, levels = { 16, 22 }, zone = 1450, version = 1, revision = "9afbf9d4bb280c5ccd7f0bae4d8a9a0e561752660da6d9ecab3478ad49710fbe", legacyRevision = "97c4b8bd64b49bba26246f9caea3b755d848d3beb11b2ffbf3797cde08fdc124", keywords = { "Aquatic Form", "A Lesson to Learn", "Trial of the Lake", "Trial of the Sea Lion", "Pendant of the Sea Lion", "Strange Lockbox", "Shrine of Remulos", "Idol of Shifting Tides", "Moonglade", "class quest" }, rewards = { { spell = 1066, name = "Aquatic Form" }, { item = 263411 }, { item = 16608 } }, why = "Your water travel form: swim fast and breathe underwater, with a belt and an idol besides.",
			steps = {
				{ title = "Cenarion Enclave", tip = "Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. Skyborne: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1457, goals = {
					{ kind = "level", level = 16 },
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
				} },
				{ title = "A Lesson to Learn", tip = "Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. Skyborne: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1457, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 26, note = "Mathrengyl Bearwalker" },
				} },
				{ title = "Trial of the Lake", tip = "Cast Teleport: Moonglade to get here: Dendrite Starblaze stands upstairs in the building beside where you land. Trial of the Lake runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until Tajarri has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of Lake Elune'ara below Nighthaven, often near the bubbling fissures (the Bubbly Fissure in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the Shrine Bauble is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the Shrine of Remulos on the north-west shore, use it inside the shrine grounds and speak to Tajarri by the tree.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 26, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 29 },
					{ kind = "collect", item = 15877, count = 1, note = "Shrine Bauble, from a Bauble Container in the lake" },
					{ kind = "use", item = 15877, map = 1450, x = 36, y = 41.4, note = "At the Shrine of Remulos" },
					{ kind = "complete", quest = 29, map = 1450, x = 36, y = 41.4 },
					{ kind = "turnin", quest = 29, note = "Tajarri" },
					{ kind = "accept", quest = 272 },
				} },
				{ title = "Half Pendant of Aquatic Agility", tip = "Fly from Nighthaven to Auberdine. The Strange Lockbox lies far out on the sea floor off the north coast, between tall rocks west of where the Cliffspring River reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1439, goals = {
					{ kind = "fly", place = "Auberdine" },
					{ kind = "collect", item = 15883, count = 1, note = "Half Pendant of Aquatic Agility, from the Strange Lockbox" },
				} },
				{ title = "Half Pendant of Aquatic Endurance", tip = "Take the boat from Auberdine to Stormwind and fly to Sentinel Hill. Head west to the coast: the Strange Lockbox lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1436, goals = {
					{ kind = "fly", place = "Sentinel Hill" },
					{ kind = "collect", item = 15882, count = 1, note = "Half Pendant of Aquatic Endurance, from the Strange Lockbox" },
				} },
				{ title = "Pendant of the Sea Lion", tip = "Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the Half Pendant of Aquatic Agility to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by Dendrite Starblaze. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards Silva Fil'naveth, in the middle of Nighthaven, flies druids straight to Rut'theran Village.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1450, goals = {
					{ kind = "collect", quest = 272, objective = 1, item = 15885, note = "Pendant of the Sea Lion: join the halves at the shrine" },
					{ kind = "turnin", quest = 272, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 5061 },
					{ kind = "fly", place = "Rut'theran Village" },
				} },
				{ title = "Cenarion Enclave", tip = "Take the portal up to Mathrengyl in the Cenarion Enclave. Aquatic Form: swim fast and breathe underwater.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1457, goals = {
