				{ title = "Aquatic Form", tip = "Take the portal up to Mathrengyl in the Cenarion Enclave. Aquatic Form: swim fast and breathe underwater.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 5061, rewards = { { item = 16608 }, { item = 263411 } }, note = "Mathrengyl Bearwalker: Aquatic Form" },
				} },
				{ title = "A Lesson to Learn", tip = "Turak Runetotem stands in the druids' hut on Elder Rise.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1456, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 27, note = "Turak Runetotem" },
				} },
				{ title = "Trial of the Lake", tip = "Cast Teleport: Moonglade to get here: Dendrite Starblaze stands upstairs in the building beside where you land. Trial of the Lake runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until Tajarri has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of Lake Elune'ara below Nighthaven, often near the bubbling fissures (the Bubbly Fissure in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the Shrine Bauble is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the Shrine of Remulos on the north-west shore, use it inside the shrine grounds and speak to Tajarri by the tree.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 27, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 28 },
					{ kind = "collect", item = 15877, count = 1, note = "Shrine Bauble, from a Bauble Container in the lake" },
					{ kind = "use", item = 15877, map = 1450, x = 36, y = 41.4, note = "At the Shrine of Remulos" },
					{ kind = "complete", quest = 28, map = 1450, x = 36, y = 41.4 },
					{ kind = "turnin", quest = 28, note = "Tajarri" },
					{ kind = "accept", quest = 30 },
				} },
				{ title = "Half Pendant of Aquatic Agility", tip = "Take Bunthen Plainswind's flight to Thunder Bluff and fly on to Orgrimmar. The Strange Lockbox lies underwater in the Sludge Fen pond, a short walk out of Orgrimmar's west gate, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "fly", place = "Thunder Bluff" },
					{ kind = "fly", place = "Orgrimmar" },
					{ kind = "collect", item = 15883, count = 1, note = "Half Pendant of Aquatic Agility, from the Strange Lockbox" },
				} },
				{ title = "Zeppelin to Undercity", tip = "Back through Orgrimmar to the zeppelin towers outside its main gate: the zeppelin to the Undercity lands in Tirisfal Glades, and Silverpine Forest is south of the Undercity.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1411, goals = {
					{ kind = "goto", label = "Zeppelin to Undercity", map = 1411, x = 50.8, y = 13.5 },
				} },
				{ title = "Half Pendant of Aquatic Endurance", tip = "The Strange Lockbox lies at the bottom of very deep water off the coast north-west of the Sepulcher, beside an air fissure where you can breathe: watch your breath on the way down. Then Teleport: Moonglade takes you straight back.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1421, goals = {
					{ kind = "collect", item = 15882, count = 1, note = "Half Pendant of Aquatic Endurance, from the Strange Lockbox" },
				} },
				{ title = "Pendant of the Sea Lion", tip = "Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the Half Pendant of Aquatic Agility to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by Dendrite Starblaze. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Bunthen Plainswind flies druids to Thunder Bluff.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1450, goals = {
					{ kind = "collect", quest = 30, objective = 1, item = 15885, note = "Pendant of the Sea Lion: join the halves at the shrine" },
					{ kind = "turnin", quest = 30, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 31 },
					{ kind = "fly", place = "Thunder Bluff" },
				} },
				{ title = "Aquatic Form", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 31, rewards = { { item = 16608 }, { item = 263411 } }, note = "Turak Runetotem: Aquatic Form" },
				} },
			},
