		{
			id = "forever/class/druid/bear-form", title = "Bear Form and Moonglade", category = "Class", folder = "Druid", classes = { "Druid" }, levels = { 10, 12 }, zone = 1450, version = 1, revision = "58ba75c2634ec6a54c9fd4a5c7cac2a3a0120ae874137d1730372abc1e034e5a", legacyRevision = "cf12e62a1d7125c0c9490999881d5b5ac849dc6408c2b8b6015db07fd82d4b63", keywords = { "Bear Form", "Teleport: Moonglade", "Moonglade", "Heeding the Call", "Great Bear Spirit", "Body and Heart", "Moonkin Stone", "Lunaclaw", "Child of Nature", "Great Ursera Spirit", "Strength and Mercy", "Ur'endra", "Skyborne", "class quest" }, rewards = { { spell = 5487, name = "Bear Form" } }, why = "Your tanking form: Forever no longer trains Bear Form, these quests give it. Opens Moonglade too.",
			steps = {
				{ title = "Heeding the Call", tip = "At 10 a druid's call reaches you: Kal in Dolanaar, Denatharion in Darnassus or Theridran in Stormwind. Any one of them sends you to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 5925, optional = true, note = "Kal, Dolanaar; Denatharion's and Theridran's letters lead to the same place" },
				} },
				{ title = "Cenarion Enclave", tip = "Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
				} },
				{ title = "Mathrengyl Bearwalker", tip = "Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 5925, optional = true, note = "or whichever of the three letters you carry" },
					{ kind = "accept", quest = 5921 },
				} },
				{ title = "Moonglade", tip = "Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs, past the armor vendor. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Sindrayl, south of the lake) for later, then take Silva Fil'naveth's flight from the middle of Nighthaven: she flies druids straight to Rut'theran Village, no flight path needed. Take the portal up to Darnassus.", only = { races = { "NightElf" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 5921, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 5929 },
					{ kind = "complete", quest = 5929, map = 1450, x = 39.1, y = 27.5, note = "Speak with the Great Bear Spirit" },
					{ kind = "turnin", quest = 5929 },
					{ kind = "accept", quest = 5931 },
					{ kind = "getfp", place = "Moonglade" },
					{ kind = "fly", place = "Rut'theran Village" },
				} },
				{ title = "Cenarion Enclave", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
				} },
				{ title = "Back to Darnassus", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 5931, note = "Mathrengyl Bearwalker" },
					{ kind = "accept", quest = 6001 },
				} },
				{ title = "The Moonkin Stone", tip = "Fly from Rut'theran Village to Auberdine. The Moonkin Stone stands inside the nearest moonkin cave east of the village: the northern of two small rock-pile caves where the Auberdine road meets the main north-south road. Moonkin (level 11-13) stand outside, the cave is empty: slip past them. Use the Cenarion Moondust by the stone: Lunaclaw (level 12-13) walks in towards you and stays three minutes. Kill her, then speak to the Lunaclaw Spirit that appears and ask for the strength of her body and heart: the talk is the credit. Another druid's Lunaclaw gives you the spirit too.", only = { races = { "NightElf" } }, zone = 1439, goals = {
					{ kind = "fly", place = "Auberdine" },
					{ kind = "use", item = 15208, map = 1439, x = 43.5, y = 46, note = "Cenarion Moondust" },
					{ kind = "complete", quest = 6001 },
				} },
				{ title = "Body and Heart", tip = "Fly back to Rut'theran Village and take the portal up to Mathrengyl.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "fly", place = "Rut'theran Village" },
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
					{ kind = "turnin", quest = 6001, note = "Mathrengyl Bearwalker: Bear Form" },
				} },
				{ title = "Heeding the Call", tip = "At 10 a druid's call reaches you: Gennia Runetotem in Bloodhoof Village or Innkeeper Pala in Thunder Bluff (Innkeeper Gryshka's letter in Orgrimmar works too). Any one of them sends you to Turak Runetotem on Elder Rise in Thunder Bluff.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 5928, optional = true, note = "Gennia Runetotem, Bloodhoof Village; Pala's and Gryshka's letters lead to the same place" },
				} },
				{ title = "Turak Runetotem", tip = "Turak Runetotem stands in the druids' hut on Elder Rise, over the rope bridges east of the lifts. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).", only = { races = { "Tauren" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 5928, optional = true, note = "or whichever of the three letters you carry" },
					{ kind = "accept", quest = 5922 },
				} },
				{ title = "Moonglade", tip = "Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Faustron, south-west of the lake); Bunthen Plainswind in Nighthaven flies druids to Thunder Bluff.", only = { races = { "Tauren" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 5922, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 5930 },
					{ kind = "complete", quest = 5930, map = 1450, x = 39.1, y = 27.5, note = "Speak with the Great Bear Spirit" },
					{ kind = "turnin", quest = 5930 },
					{ kind = "accept", quest = 5932 },
					{ kind = "fly", place = "Thunder Bluff" },
				} },
				{ title = "Back to Thunder Bluff", only = { races = { "Tauren" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 5932, note = "Turak Runetotem" },
					{ kind = "accept", quest = 6002 },
				} },
				{ title = "The Moonkin Stone", tip = "The Moonkin Stone stands in the Barrens just south-west of Camp Taurajo, by the road out of Mulgore. Level 20 Thunderheads roam close by: clear the way first. Use the Cenarion Lunardust by the stone: Lunaclaw (level 12-13) appears for three minutes. Kill her, then speak to the Lunaclaw Spirit that appears and ask for the strength of her body and heart: the talk is the credit. Die in the fight? Lunaclaw stays by the stone: run back and finish her.", only = { races = { "Tauren" } }, zone = 1413, goals = {
					{ kind = "use", item = 15710, map = 1413, x = 42, y = 60.9, note = "Cenarion Lunardust" },
					{ kind = "complete", quest = 6002 },
				} },
				{ title = "Body and Heart", tip = "Back to Turak Runetotem on Elder Rise.", only = { races = { "Tauren" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 6002, note = "Turak Runetotem: Bear Form" },
				} },
				{ title = "Skyboat from Dalaran", tip = "Bear Form is taught on Zephras Isle. Skip this if you are still on the isle; otherwise take the skyboat from the north side of Dalaran.", only = { races = { "Skyborne" }, factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "goto", label = "Skyboat to Zephras Isle", map = 1416, x = 12.5, y = 51.8, frame = "live" },
				} },
				{ title = "Skyboat from Thunder Bluff", tip = "Bear Form is taught on Zephras Isle. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of Skywatcher Plateau, north of Thunder Bluff.", only = { races = { "Skyborne" }, factions = { "Horde" } }, zone = 1412, goals = {
					{ kind = "goto", label = "Skyboat to Zephras Isle", map = 1412, x = 34.3, y = 25.8, frame = "live" },
				} },
				{ title = "Lotheluum Starbreeze", tip = "Lotheluum Starbreeze stands in Valanaar.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94006 },
				} },
				{ title = "Urs'endris and Ur'endra", tip = "Urs'endris waits by the waterfall below the Shrine of Akir, north-east of Valanaar. Ur'endra (the bear you must defeat) lairs in an unmarked cave high on the cliff face west of him, where the Shen'dar Highlands meet the Gustberry Lowlands: take the path west out of Valanaar (not north), cross the river on the log bridge and reach the cave from the cliff's upper, northern side. The cave at the foot of the cliffs and the foggy cave are the wrong ones.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 94006, note = "Urs'endris" },
					{ kind = "accept", quest = 94638 },
					{ kind = "kill", quest = 94638, objective = 1, npc = 258443, note = "Ur'endra" },
				} },
				{ title = "Strength and Mercy", tip = "Back to Urs'endris by the falls.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 94638, note = "Urs'endris: Bear Form" },
				} },
				{ title = "Child of Nature", tip = "Muln Earthfury waits where the airship from Zephras Isle lands, in northern Mulgore beside Thunder Bluff.", only = { races = { "Skyborne" }, factions = { "Horde" } }, zone = 1412, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94911, note = "Muln Earthfury" },
				} },
				{ title = "Turak Runetotem", tip = "Turak Runetotem trains druids in the druids' hut on Elder Rise, over the rope bridges east of the lifts. He teaches you Teleport: Moonglade with the next quest (it stays in your spellbook, Balance tab).", only = { races = { "Skyborne" }, factions = { "Horde" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 94911 },
					{ kind = "accept", quest = 94913 },
				} },
				{ title = "Child of Nature", tip = "Alfina Nightgaze stands beside Denaaris Stargale and the Skyborne Portal, west of Dalaran, where the skycutter from Zephras Isle lands. Archmage Ansirem Runeweaver offers the same quest.", only = { races = { "Skyborne" }, factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94912, npc = 270459, note = "Alfina Nightgaze" },
				} },
				{ title = "Sheldras Moontree", tip = "The Skyborne Portal takes you to Stormwind. Sheldras Moontree is the city's druid trainer (the arrow points at him); he teaches you Teleport: Moonglade with the next quest (it stays in your spellbook, Balance tab).", only = { races = { "Skyborne" }, factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 94912 },
					{ kind = "accept", quest = 94914 },
				} },
				{ title = "Dendrite Starblaze", tip = "Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs, in Nighthaven. Learn the Moonglade flight path while you are here (Faustron for the Horde, south-west of the lake; Sindrayl for the Alliance, south of it).", only = { races = { "Skyborne" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 94913, only = { factions = { "Horde" } }, note = "Dendrite Starblaze" },
