				{ title = "Dendrite Starblaze", tip = "Cast Teleport: Moonglade: Dendrite Starblaze stands upstairs in the building beside you. He hands you the Empty Cliffspring Falls Sampler. Then fly to Auberdine (learn the Moonglade flight path at Sindrayl first if you have not).", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 6121, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 6122 },
					{ kind = "fly", place = "Auberdine" },
				} },
				{ title = "Cliffspring Falls", tip = "Head north-east from Auberdine to Cliffspring Falls. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the Empty Cliffspring Falls Sampler (not the Empty Sampling Tube of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1439, goals = {
					{ kind = "use", quest = 6122, objective = 1, item = 15844, map = 1439, x = 54.9, y = 33.3, note = "Empty Cliffspring Falls Sampler, at the cave mouth" },
					{ kind = "collect", quest = 6122, objective = 1, item = 15845, note = "Filled Cliffspring Falls Sampler" },
				} },
				{ title = "Alanndarian Nightsong", tip = "Back in Auberdine, at the north end of the village.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1439, goals = {
					{ kind = "turnin", quest = 6122, note = "Alanndarian Nightsong" },
					{ kind = "accept", quest = 6123 },
				} },
				{ title = "Lunar Fungus and Earthroot", tip = "The Lunar Fungal Blooms are tiny white-spotted mushrooms on the floors and walls of the small moonkin caves in the hills just east and south-east of Auberdine; each gives one or two fungus, and each cave holds only a few, so go from cave to cave (they regrow in three minutes). The moonkin there are irritable. No Herbalism needed for the blooms. Earthroot needs Herbalism: herbalists pick it all over Darkshore, anyone else buys it (Maria Lumere or Bernard Gump in Stormwind, or the Auction House).", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1439, goals = {
					{ kind = "collect", quest = 6123, objective = 2, item = 15851, count = 12, note = "Lunar Fungus" },
					{ kind = "collect", quest = 6123, objective = 1, item = 2449, count = 5, note = "Earthroot" },
				} },
				{ title = "Alanndarian Nightsong", tip = "She hands you the Curative Animal Salve: ten doses, one per deer. Destroy any leftover Lunar Fungus.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1439, goals = {
					{ kind = "turnin", quest = 6123, note = "Alanndarian Nightsong" },
					{ kind = "accept", quest = 6124 },
				} },
				{ title = "Sickly Deer", tip = "Use the Curative Animal Salve on living Sickly Deer (level 5, a green cloud over them): they roam Darkshore from the Cliffspring River to the Ashenvale border, many around the Blackwood furbolg camp north-east of Auberdine. Druid trick: root a deer with Entangling Roots, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from Alanndarian for a fresh salve.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1439, goals = {
					{ kind = "kill", quest = 6124, objective = 1, npc = 12298, text = "Use the Curative Animal Salve on Sickly Deer" },
				} },
				{ title = "Curing the Sick", tip = "Cast Teleport: Moonglade and see Dendrite Starblaze, then take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed) and the portal up to Darnassus. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 6124, note = "Dendrite Starblaze" },
					{ kind = "accept", quest = 6125 },
					{ kind = "fly", place = "Rut'theran Village" },
				} },
				{ title = "Cenarion Enclave", tip = "Mathrengyl Bearwalker, upstairs in the Cenarion Enclave, teaches you Cure Poison.", only = { races = { "NightElf", "Skyborne" }, factions = { "Alliance" } }, zone = 1457, goals = {
