					{ kind = "turnin", quest = 6125, note = "Mathrengyl Bearwalker: Cure Poison" },
				} },
				{ title = "Lessons Anew", tip = "Turak Runetotem stands in the druids' hut on Elder Rise; Hana Lighthoof, the Skyborne druid trainer where the airship from Zephras Isle lands in northern Mulgore, gives the same quest. No Herbalism? Hula'mahi at the Crossroads sells Earthroot later, or buy five on the Auction House now.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1456, goals = {
					{ kind = "level", level = 14 },
					{ kind = "accept", quest = 6126, note = "Turak Runetotem, or Hana Lighthoof in northern Mulgore" },
				} },
				{ title = "Dendrite Starblaze", tip = "Cast Teleport: Moonglade: Dendrite Starblaze stands upstairs in the building beside you. He hands you the Empty Dreadmist Peak Sampler. Bunthen Plainswind flies druids to Thunder Bluff; fly on to the Crossroads from there.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1450, goals = {
