					{ kind = "accept", quest = 6127 },
					{ kind = "fly", place = "Thunder Bluff" },
				} },
				{ title = "Dreadmist Peak", tip = "From the Crossroads head north to Dreadmist Peak and climb to the bubbling Dreadmist Peak Pool on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the Empty Dreadmist Peak Sampler: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "fly", place = "Crossroads" },
					{ kind = "use", quest = 6127, objective = 1, item = 15842, map = 1413, x = 48.4, y = 18.9, note = "Empty Dreadmist Peak Sampler, standing in the pool" },
					{ kind = "collect", quest = 6127, objective = 1, item = 15843, note = "Filled Dreadmist Peak Sampler" },
				} },
				{ title = "Tonga Runetotem", tip = "Tonga Runetotem stands in the Crossroads. No Herbalism? Hula'mahi, a few steps away by the wind rider master, sells Earthroot for 80 copper each, three at a time until he restocks.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 6127, note = "Tonga Runetotem" },
					{ kind = "accept", quest = 6128 },
					{ kind = "buy", npc = 3490, item = 2449, count = 5, optional = true, note = "Earthroot; herbalists pick it on the plains" },
				} },
				{ title = "Earthroot and Kodo Horns", tip = "Every Lost Barrens Kodo (level 14-15) drops a horn, but they are few and wander: search the far north near the Sludge Fen and the oases, above all the Stagnant Oasis south-east of the Crossroads. They charge from range and stomp. Herbalists find Earthroot all over the northern Barrens.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "collect", quest = 6128, objective = 2, item = 15852, count = 5, note = "Kodo Horn" },
					{ kind = "collect", quest = 6128, objective = 1, item = 2449, count = 5, note = "Earthroot" },
				} },
				{ title = "Tonga Runetotem", tip = "He hands you the Curative Animal Salve: ten doses, one per gazelle.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 6128, note = "Tonga Runetotem" },
					{ kind = "accept", quest = 6129 },
				} },
				{ title = "Sickly Gazelles", tip = "Use the Curative Animal Salve on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the Ashenvale border, north-west of the Crossroads and west of Ratchet. Druid trick: root a gazelle with Entangling Roots, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from Tonga for a fresh salve.", only = { races = { "Tauren", "Skyborne" }, factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "kill", quest = 6129, objective = 1, npc = 12296, text = "Use the Curative Animal Salve on Sickly Gazelles" },
