			steps = {
				{ title = "The Ancient Petrified Leaf", tip = "Molten Core is a 40-player raid inside Blackrock Mountain. When Majordomo Executus yields, the Cache of the Firelord appears; it holds the Ancient Petrified Leaf about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest.", zone = 1448, goals = {
					{ kind = "accept", quest = 7632, item = 18703, group = 40, note = "from the Ancient Petrified Leaf" },
				} },
				{ title = "Vartrus the Ancient", tip = "Vartrus, Stoma and Hastat the Ancient are petrified trees on a small island in a ring-shaped lake in Irontree Woods, north Felwood. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to Talonbranch Glade; Horde: fly to Bloodvenom Post. Vartrus gives Stave of the Ancients, Stoma A Proper String, Hastat the quiver; each can be handed in on its own.", zone = 1448, goals = {
					{ kind = "turnin", quest = 7632, note = "Vartrus the Ancient" },
					{ kind = "accept", quest = 7633 },
					{ kind = "turnin", quest = 7633 },
					{ kind = "accept", quest = 7636 },
					{ kind = "accept", quest = 7635, note = "Stoma the Ancient" },
					{ kind = "accept", quest = 7634, note = "Hastat the Ancient: the quiver, last in this guide" },
				} },
				{ title = "Before the demons", tip = "The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring a Potion of Demon Slaying (Alchemy or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. Track Demons, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head.", zone = 1448, goals = {
					{ kind = "task", text = "Learn Track Demons and get demon-slaying potions", optional = true },
				} },
				{ title = "Simone the Inconspicuous", tip = "Simone the Inconspicuous, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use Track Demons. Talk to her and she becomes Simone the Seductress, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her Chain Lightning hits hard, so drain her mana with Viper Sting (a 15-second cooldown on Forever) and keep her busy; her Temptress' Kiss cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free.", zone = 1449, goals = {
					{ kind = "talk", npc = 14527, note = "Simone the Inconspicuous" },
					{ kind = "collect", quest = 7636, objective = 1, item = 18952, note = "Simone's Head" },
				} },
				{ title = "Franklin the Friendly", tip = "Franklin the Friendly, a human, wanders the western Burning Steppes south of Blackrock Mountain. Talk to him and he becomes Klinfran the Crazed, the easiest of the four. Keep Scorpid Sting on him the whole fight: while it lasts he barely hurts you. When he goes into Demonic Frenzy, remove it with Tranquilizing Shot and never stand in melee while it is up; between frenzies you can fight him in melee with Wing Clip and Raptor Strike. He cannot leave the Burning Steppes, so kite him around the trees if needed.", zone = 1428, goals = {
					{ kind = "talk", npc = 14529, note = "Franklin the Friendly" },
					{ kind = "collect", quest = 7636, objective = 2, item = 18953, note = "Klinfran's Head" },
				} },
				{ title = "Nelson the Nice", tip = "Nelson the Nice, a gnome, walks around the gates of Ahn'Qiraj in the far south-west of Silithus. Talk to him and he becomes Solenor the Slayer. He enrages with Soul Flame as he turns: drop a Frost Trap, Feign Death, and he resets without the enrage. Wing Clip roots him for a long time; while rooted he fears you and sends beetles (Creeping Doom): kill them fast with traps and Multi-Shot before they wear you down.", zone = 1451, goals = {
					{ kind = "talk", npc = 14536, note = "Nelson the Nice" },
					{ kind = "collect", quest = 7636, objective = 3, item = 18954, note = "Solenor's Head" },
				} },
				{ title = "Artorius the Amiable", tip = "Artorius the Amiable, a tauren, walks a loop in the rocks of northern Winterspring, north of Everlook. Talk to him and he becomes Artorius the Doombringer. Within 30 yards of him Demonic Doom hits hard: keep your distance and kite him the whole fight, Aspect of the Cheetah on, south down the road. Serpent Sting on him adds Stinging Trauma, extra Nature damage, so keep it ticking while you run; his Demonic Frenzy can be removed with Tranquilizing Shot, but distance matters more. It is a long fight: bring mana potions and plan your kiting path.", zone = 1452, goals = {
					{ kind = "talk", npc = 14531, note = "Artorius the Amiable" },
					{ kind = "collect", quest = 7636, objective = 4, item = 18955, note = "Artorius's Head" },
				} },
				{ title = "Onyxia", tip = "Onyxia is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh; she returns once a week. She drops one Mature Black Dragon Sinew in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first.", zone = 1445, goals = {
					{ kind = "collect", quest = 7635, objective = 1, item = 18705, map = 1445, x = 52.1, y = 75.8, group = 40, note = "Mature Black Dragon Sinew, from Onyxia" },
				} },
				{ title = "Back to the Ancients", zone = 1448, goals = {
					{ kind = "turnin", quest = 7636, rewards = { { item = 18707 } }, note = "Vartrus the Ancient" },
					{ kind = "turnin", quest = 7635, rewards = { { item = 18724 } }, note = "Stoma the Ancient" },
				} },
				{ title = "Rhok'delar and Lok'delar", tip = "Not confirmed in Forever. In Classic, using the Ancient Rune Etched Stave with the Enchanted Black Dragon Sinew in your bags made Rhok'delar, and talking to Vartrus once more then gave Lok'delar, Stave of the Ancient Keepers, at no extra cost.", zone = 1448, goals = {
					{ kind = "use", item = 18707, map = 1448, x = 47.8, y = 24.1, note = "Ancient Rune Etched Stave, by Vartrus" },
					{ kind = "talk", npc = 14524, optional = true, note = "Vartrus the Ancient: Lok'delar in Classic" },
				} },
				{ title = "Azuregos", tip = "Hastat's quiver needs the Mature Blue Dragon Sinew. Azuregos, a world boss for a raid, stands in southern Azshara, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around Mazthoril, the cave south of Everlook in Winterspring, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver.", zone = 1447, goals = {
					{ kind = "collect", quest = 7634, objective = 1, item = 18704, map = 1447, x = 53.3, y = 80.4, group = 40, note = "Mature Blue Dragon Sinew, from Azuregos" },
				} },
				{ title = "Hastat the Ancient", zone = 1448, goals = {
					{ kind = "turnin", quest = 7634, rewards = { { item = 18714 } }, note = "Hastat the Ancient" },
				} },
			},
		},
		{
			id = "forever/class/hunter/taming-the-beast-alliance", title = "Taming the Beast (Alliance)", category = "Class", folder = "Hunter", faction = "Alliance", races = { "Human", "Dwarf", "NightElf", "Skyborne" }, classes = { "Hunter" }, levels = { 10, 10 }, zone = 1429, version = 1, revision = "e759ba11281946c8d84ef52990c5250815de5a936023b44e5ae6f77c2cbfd44b", keywords = { "Taming the Beast", "Training the Beast", "The Hunter's Path", "Taming Rod", "Tame Beast", "Beast Training", "pet", "Josephine Carson", "Isaac Chan", "Grif Wildheart", "Belia Thundergranite", "Dazalar", "Jocaste", "Quel'ana Quickgale", "Quel'dora Quickgale", "Goldshire", "Kharanos", "Dolanaar", "Valanaar", "pet trainer", "Hunter" }, rewards = { { spell = 1515, name = "Tame Beast" }, { spell = 5149, name = "Beast Training" } }, why = "Your own pet at 10: three practice tames with a Taming Rod teach Tame Beast, then Beast Training.",
			steps = {
				{ title = "Elayaa Easewind", tip = "At 10, Elayaa Easewind, a hunter trainer on Zephras Isle, may send you on to Valanaar with Taming the Beast. It is only a pointer: skip it if you are already in Valanaar.", only = { races = { "Skyborne" } }, jumps = { { label = "goldshire", when = { { name = "Zephras Isle", test = "zone", negate = true } } } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94007, optional = true, note = "Elayaa Easewind" },
				} },
				{ title = "Quel'ana Quickgale in Valanaar", tip = "Quel'ana Quickgale stands with the trainers by Valanaar's west gate, Quel'dora Quickgale beside her.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 94007, optional = true, note = "Quel'ana Quickgale" },
					{ kind = "accept", quest = 94978, note = "Quel'ana Quickgale: the first Taming Rod" },
				} },
				{ title = "Windsong Crawler", tip = "Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of Valanaar, among the crabs. How the rod works: target a living crawler, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to Quel'ana.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", quest = 94978, objective = 1, npc = 254588, text = "Tame Windsong Crawler", note = "Use the Taming Rod on a living crawler" },
					{ kind = "turnin", quest = 94978, note = "Quel'ana Quickgale" },
					{ kind = "accept", quest = 94979 },
				} },
				{ title = "Ornery Galestrider", tip = "Dismiss the crawler first (right-click the pet portrait, Dismiss Pet). Ornery Galestriders graze in the Gustberry Lowlands, the fields a short walk west and south-west of Valanaar.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", quest = 94979, objective = 1, npc = 251707, text = "Tame Ornery Galestrider", note = "Use the Taming Rod on a living galestrider" },
					{ kind = "turnin", quest = 94979, note = "Quel'ana Quickgale" },
					{ kind = "accept", quest = 94013 },
				} },
				{ title = "Vuldren Alpha", tip = "Dismiss the galestrider. Vuldren Alphas hunt in the same Gustberry Lowlands, a little further south.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", quest = 94013, objective = 1, npc = 250874, text = "Tame Vuldren Alpha", note = "Use the Taming Rod on a living alpha" },
					{ kind = "turnin", quest = 94013, note = "Quel'ana Quickgale: Tame Beast" },
					{ kind = "accept", quest = 94050 },
					{ kind = "turnin", quest = 94050, note = "Quel'dora Quickgale, beside her: Beast Training" },
				} },
				{ title = "Grif Wildheart in Kharanos", tip = "At 10 go to Grif Wildheart, the hunter trainer at the smithy in Kharanos. The Hunter's Path from Olmin Burningbeard in Ironforge, Tristane Shadowstone north-west of Kharanos or Einris Brightspear in Stormwind also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? Josephine Carson's chain in Goldshire teaches the same.", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1426, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 6064, note = "Grif Wildheart: the first Taming Rod" },
				} },
				{ title = "Large Crag Boar", tip = "Large Crag Boars (level 6-7) root around the fields west, south and north-west of Kharanos and respawn every 3 minutes. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from Grif. The boars use Rushing Charge from 25 yards, so start with the rod, not Auto Shot. Keep each rod: it goes back to Grif.", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1426, goals = {
					{ kind = "kill", quest = 6064, objective = 1, npc = 1126, text = "Tame Large Crag Boar", note = "Use the Taming Rod on a living boar" },
					{ kind = "turnin", quest = 6064, note = "Grif Wildheart" },
					{ kind = "accept", quest = 6084 },
				} },
				{ title = "Snow Leopard", tip = "Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of Kharanos, more north-west and west of it; the smaller Juvenile Snow Leopards do not count.", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1426, goals = {
					{ kind = "kill", quest = 6084, objective = 1, npc = 1201, text = "Tame Snow Leopard", note = "Use the Taming Rod on a living leopard" },
					{ kind = "turnin", quest = 6084, note = "Grif Wildheart" },
					{ kind = "accept", quest = 6085 },
				} },
				{ title = "Ice Claw Bear", tip = "Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around Kharanos, many south-east of it and more north-west toward Anvilmar; their Ice Claw hits hard, so start at full health.", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1426, goals = {
					{ kind = "kill", quest = 6085, objective = 1, npc = 1196, text = "Tame Ice Claw Bear", note = "Use the Taming Rod on a living bear" },
					{ kind = "turnin", quest = 6085, note = "Grif Wildheart: Tame Beast" },
					{ kind = "accept", quest = 6086 },
				} },
				{ title = "Belia Thundergranite in Ironforge", tip = "Belia Thundergranite, the pet trainer, stands in the Hall of Arms in Ironforge's Military Ward, by the hunter trainers.", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 6086, note = "Belia Thundergranite: Beast Training" },
				} },
				{ title = "Dazalar in Dolanaar", tip = "At 10 go to Dazalar, the hunter trainer in Dolanaar. The Hunter's Path from Ayanna Everstride at Aldrassil, Jocaste in Darnassus, Einris Brightspear in Stormwind, Olmin Burningbeard in Ironforge or Grif Wildheart in Kharanos also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? Josephine Carson's chain in Goldshire teaches the same.", only = { races = { "NightElf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1438, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 6063, note = "Dazalar: the first Taming Rod" },
				} },
				{ title = "Webwood Lurker", tip = "Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of Dolanaar. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their Web roots you but does not break the channel if you keep still. Keep each rod: it goes back to Dazalar.", only = { races = { "NightElf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1438, goals = {
					{ kind = "kill", quest = 6063, objective = 1, npc = 1998, text = "Tame Webwood Lurker", note = "Use the Taming Rod on a living spider" },
					{ kind = "turnin", quest = 6063, note = "Dazalar" },
					{ kind = "accept", quest = 6101 },
				} },
				{ title = "Nightsaber Stalker", tip = "Dismiss the spider first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of Lake Al'Ameth, south of Dolanaar; the plain Nightsabers by the village do not count.", only = { races = { "NightElf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1438, goals = {
					{ kind = "kill", quest = 6101, objective = 1, npc = 2043, text = "Tame Nightsaber Stalker", note = "Use the Taming Rod on a living stalker" },
					{ kind = "turnin", quest = 6101, note = "Dazalar" },
					{ kind = "accept", quest = 6102 },
				} },
				{ title = "Strigid Screecher", tip = "Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of Dolanaar.", only = { races = { "NightElf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1438, goals = {
					{ kind = "kill", quest = 6102, objective = 1, npc = 1996, text = "Tame Strigid Screecher", note = "Use the Taming Rod on a living owl" },
					{ kind = "turnin", quest = 6102, note = "Dazalar: Tame Beast" },
					{ kind = "accept", quest = 6103 },
				} },
				{ title = "Jocaste in Darnassus", tip = "Take the road west from Dolanaar to Darnassus. Jocaste stands inside the Cenarion Enclave with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her.", only = { races = { "NightElf" } }, when = { { test = "onquest", quests = { 94792, 94863, 94864, 94793 }, negate = true }, { quest = 94792, test = "turnedin", negate = true } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 6103, note = "Jocaste: Beast Training" },
				} },
				{ title = "Josephine Carson in Goldshire", tip = "At 10 go to Josephine Carson, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in Goldshire; Isaac Chan, the pet trainer, is beside her. Skyborne: this is for one who left Zephras Isle without taming; it teaches the same.", only = { races = { "Human", "Skyborne" } }, label = "goldshire", jumps = { { label = "pet", when = { { quest = 94013, test = "turnedin" } } } }, zone = 1429, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94792, note = "Josephine Carson: the first Taming Rod" },
				} },
				{ title = "Rockhide Boar", tip = "Rockhide Boars (level 7-8) graze in three herds south and south-east of Goldshire, toward the Maclure Vineyards. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use Rushing Charge, so start with the rod, not Auto Shot. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through Goldshire from here.", when = { { quest = 6064, test = "turnedin", negate = true }, { quest = 6063, test = "turnedin", negate = true } }, zone = 1429, goals = {
					{ kind = "kill", quest = 94792, objective = 1, npc = 524, text = "Tame Rockhide Boar", note = "Use the Taming Rod on a living boar" },
					{ kind = "turnin", quest = 94792, note = "Josephine Carson" },
					{ kind = "accept", quest = 94863 },
				} },
				{ title = "Gray Forest Wolf", tip = "Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of Goldshire, east of Crystal Lake.", when = { { quest = 6064, test = "turnedin", negate = true }, { quest = 6063, test = "turnedin", negate = true } }, zone = 1429, goals = {
					{ kind = "kill", quest = 94863, objective = 1, npc = 1922, text = "Tame Gray Forest Wolf", note = "Use the Taming Rod on a living wolf" },
					{ kind = "turnin", quest = 94863, note = "Josephine Carson" },
					{ kind = "accept", quest = 94864 },
				} },
				{ title = "Young Forest Bear", tip = "Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of Goldshire, with more south-west and south-east of town.", when = { { quest = 6064, test = "turnedin", negate = true }, { quest = 6063, test = "turnedin", negate = true } }, zone = 1429, goals = {
					{ kind = "kill", quest = 94864, objective = 1, npc = 822, text = "Tame Young Forest Bear", note = "Use the Taming Rod on a living bear" },
					{ kind = "turnin", quest = 94864, note = "Josephine Carson: Tame Beast" },
					{ kind = "accept", quest = 94793 },
					{ kind = "turnin", quest = 94793, note = "Isaac Chan, beside her: Beast Training" },
				} },
				{ title = "Your first pet", tip = "Tame Beast works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and Bite) and a boar takes more punishment.", label = "pet", zone = 1429, goals = {
					{ kind = "task", text = "Tame a beast of your level to keep", optional = true },
					{ kind = "note", text = "Near Goldshire there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the Westfall border; at 12-13, Young Goretusks (boars) graze the fields of northern Westfall.", only = { races = { "Human" } } },
					{ kind = "note", text = "Near Kharanos: Snow Leopards (cats, level 7-8) prowl all over Dun Morogh, Scarred Crag Boars (9-10) its east toward Loch Modan; at 10-11, Mountain Boars roam western Loch Modan.", only = { races = { "Dwarf" } } },
					{ kind = "note", text = "Near Dolanaar: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western Teldrassil.", only = { races = { "NightElf" } } },
					{ kind = "note", text = "Near Valanaar: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the Gustberry Lowlands; Shriekling Matriarchs (raptors, level 9) nest just west of Valanaar; Shadowgale Urseras (bears, 10-11) roam the north of Zephras Isle.", only = { races = { "Skyborne" } } },
					{ kind = "note", text = "Feed Pet: open your spellbook, cast Feed Pet and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in Goldshire, Jaeana in Darnassus and the innkeepers on Zephras Isle sell meat; the innkeepers of Kharanos and Dolanaar sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat." },
					{ kind = "note", text = "Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away." },
					{ kind = "note", text = "Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in Beast Training (pet level times loyalty rank minus one)." },
					{ kind = "note", text = "Beast Training (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in Goldshire, Shelby Stoneflint in Kharanos, Seriadne in Dolanaar, Genn Fairweather on Zephras Isle), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with Beast Training. A pet holds four active abilities at most." },
					{ kind = "note", text = "Pet trainers sell Growl ranks and resistances. Alliance: Isaac Chan in Goldshire, Karrina Mekenda by the hunter trainers in Stormwind's Dwarven District, Peria Lamenur in Kharanos, Belia Thundergranite in Ironforge's Hall of Arms, Keldas in Dolanaar, Silvaria in Darnassus' Cenarion Enclave, Quel'dora Quickgale in Valanaar." },
					{ kind = "note", text = "Call Pet, Dismiss Pet and Revive Pet are in your spellbook now; Mend Pet comes from your trainer at 12. A dead pet needs Revive Pet; one that is away more than about 100 yards is dismissed and comes back with Call Pet." },
				} },
			},
		},
		{
			id = "forever/class/hunter/taming-the-beast-horde", title = "Taming the Beast (Horde)", category = "Class", folder = "Hunter", faction = "Horde", races = { "Orc", "Troll", "Tauren", "Skyborne" }, classes = { "Hunter" }, levels = { 10, 10 }, zone = 1411, version = 1, revision = "80f9c18f9a2438fd76304516240ba69f0913a1ac2ae51904371e7e4e9f1b1839", keywords = { "Taming the Beast", "Training the Beast", "The Hunter's Path", "Taming Rod", "Tame Beast", "Beast Training", "pet", "Thotar", "Yaw Sharpmane", "Quel'ana Quickgale", "Ormak Grimshot", "Holt Thunderhorn", "Quel'dora Quickgale", "Razor Hill", "Bloodhoof Village", "Valanaar", "pet trainer", "Hunter" }, rewards = { { spell = 1515, name = "Tame Beast" }, { spell = 5149, name = "Beast Training" } }, why = "Your own pet at 10: three practice tames with a Taming Rod teach Tame Beast, then Beast Training.",
			steps = {
				{ title = "Thotar in Razor Hill", tip = "At 10 go to Thotar, the hunter trainer inside the barracks in Razor Hill. If Sian'dur in Orgrimmar, Kali Remik in Sen'jin Village or Kary Thunderhorn in Thunder Bluff hands you The Hunter's Path, take it and hand it to Thotar for a little experience; it is only a pointer, and you can take the first rod without it.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 6062, note = "Thotar: the first Taming Rod" },
				} },
				{ title = "Dire Mottled Boar", tip = "Dire Mottled Boars (level 6-7) roam just north and west of Razor Hill. How the rod works: target a living beast, use the Taming Rod from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from Thotar. The boars charge from 20 yards, so start with the rod, not Auto Shot. The tamed boar becomes your pet for practice. Keep each rod: it goes back to Thotar.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "kill", quest = 6062, objective = 1, npc = 3099, text = "Tame Dire Mottled Boar", note = "Use the Taming Rod on a living boar" },
					{ kind = "turnin", quest = 6062, note = "Thotar" },
					{ kind = "accept", quest = 6083 },
				} },
				{ title = "Surf Crawler", tip = "First dismiss the boar (right-click your pet's portrait, Dismiss Pet): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around Sen'jin Village and the Echo Isles; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "kill", quest = 6083, objective = 1, npc = 3107, text = "Tame Surf Crawler", note = "Use the Taming Rod on a living Surf Crawler" },
					{ kind = "turnin", quest = 6083, note = "Thotar" },
					{ kind = "accept", quest = 6082 },
				} },
				{ title = "Armored Scorpid", tip = "Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of Razor Hill, some just south of the road west out of town; Track Beasts shows them. Their hits can break the channel: start at full health and keep still.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "kill", quest = 6082, objective = 1, npc = 3126, text = "Tame Armored Scorpid", note = "Use the Taming Rod on a living scorpid" },
					{ kind = "turnin", quest = 6082, note = "Thotar: Tame Beast" },
					{ kind = "accept", quest = 6081 },
				} },
				{ title = "Ormak Grimshot in Orgrimmar", tip = "Follow the road north to Orgrimmar's gate. Ormak Grimshot stands with the hunter trainers in the Valley of Honor, up the ramp at the city's east side; Xao'tsu, the pet trainer, is a few steps north of him.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "turnin", quest = 6081, note = "Ormak Grimshot: Beast Training" },
				} },
				{ title = "Yaw Sharpmane at Bloodhoof", tip = "At 10 go to Yaw Sharpmane, who stands at the north edge of Bloodhoof Village. The Hunter's Path from Kary Thunderhorn in Thunder Bluff, Sian'dur in Orgrimmar or Thotar in Razor Hill also leads here, for a little experience; it is only a pointer.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 6061, note = "Yaw Sharpmane: the first Taming Rod" },
				} },
				{ title = "Adult Plainstrider", tip = "Adult Plainstriders (level 6-7) walk the plains south-west and north-west of Bloodhoof Village. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "kill", quest = 6061, objective = 1, npc = 2956, text = "Tame Adult Plainstrider", note = "Use the Taming Rod on a living plainstrider" },
					{ kind = "turnin", quest = 6061, note = "Yaw Sharpmane" },
					{ kind = "accept", quest = 6087 },
				} },
				{ title = "Prairie Stalker", tip = "Dismiss the plainstrider first (right-click the pet portrait, Dismiss Pet): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of Bloodhoof Village.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "kill", quest = 6087, objective = 1, npc = 2959, text = "Tame Prairie Stalker", note = "Use the Taming Rod on a living stalker" },
					{ kind = "turnin", quest = 6087, note = "Yaw Sharpmane" },
					{ kind = "accept", quest = 6088 },
				} },
				{ title = "Swoop", tip = "Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A Swoop's knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "kill", quest = 6088, objective = 1, npc = 2970, text = "Tame Swoop", note = "Use the Taming Rod on a living Swoop" },
					{ kind = "turnin", quest = 6088, note = "Yaw Sharpmane: Tame Beast" },
					{ kind = "accept", quest = 6089 },
				} },
				{ title = "Holt Thunderhorn in Thunder Bluff", tip = "Head north to Thunder Bluff and take a lift up. Holt Thunderhorn stands with the hunter trainers on Hunter Rise; Hesuwa Thunderhorn, the pet trainer, is nearby.", only = { races = { "Tauren" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 6089, note = "Holt Thunderhorn: Beast Training" },
				} },
				{ title = "Elayaa Easewind", tip = "At 10, Elayaa Easewind, a hunter trainer on Zephras Isle, may send you on to Valanaar with Taming the Beast. It is only a pointer: skip it if you are already in Valanaar.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94007, optional = true, note = "Elayaa Easewind" },
				} },
				{ title = "Quel'ana Quickgale in Valanaar", tip = "Quel'ana Quickgale stands with the trainers by Valanaar's west gate, Quel'dora Quickgale beside her.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 94007, optional = true, note = "Quel'ana Quickgale" },
					{ kind = "accept", quest = 94978, note = "Quel'ana Quickgale: the first Taming Rod" },
				} },
				{ title = "Windsong Crawler", tip = "Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of Valanaar, among the crabs. How the rod works: target a living crawler, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs a charge. Killing one does not count.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", quest = 94978, objective = 1, npc = 254588, text = "Tame Windsong Crawler", note = "Use the Taming Rod on a living crawler" },
					{ kind = "turnin", quest = 94978, note = "Quel'ana Quickgale" },
					{ kind = "accept", quest = 94979 },
				} },
				{ title = "Ornery Galestrider", tip = "Dismiss the crawler first (right-click the pet portrait, Dismiss Pet). Ornery Galestriders graze in the Gustberry Lowlands, the fields a short walk west and south-west of Valanaar.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", quest = 94979, objective = 1, npc = 251707, text = "Tame Ornery Galestrider", note = "Use the Taming Rod on a living galestrider" },
					{ kind = "turnin", quest = 94979, note = "Quel'ana Quickgale" },
					{ kind = "accept", quest = 94013 },
				} },
				{ title = "Vuldren Alpha", tip = "Dismiss the galestrider. Vuldren Alphas hunt in the same Gustberry Lowlands, a little further south.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", quest = 94013, objective = 1, npc = 250874, text = "Tame Vuldren Alpha", note = "Use the Taming Rod on a living alpha" },
					{ kind = "turnin", quest = 94013, note = "Quel'ana Quickgale: Tame Beast" },
					{ kind = "accept", quest = 94050 },
					{ kind = "turnin", quest = 94050, note = "Quel'dora Quickgale, beside her: Beast Training" },
				} },
				{ title = "Your first pet", tip = "Tame Beast works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and Bite) and a boar takes more punishment.", zone = 2521, goals = {
					{ kind = "task", text = "Tame a beast of your level to keep", optional = true },
					{ kind = "note", text = "Near Razor Hill: Durotar Tigers (cats, level 7-8) roam the south of Durotar, from Sen'jin Village down the coast; Venomtail Scorpids (9-10) the north-west toward Orgrimmar; at 11-12, Savannah Huntresses (cats) prowl the plains around the Crossroads in the Barrens.", only = { races = { "Orc", "Troll" } } },
					{ kind = "note", text = "Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern Mulgore; at 11-12, Savannah Huntresses (cats) prowl around the Crossroads in the Barrens.", only = { races = { "Tauren" } } },
					{ kind = "note", text = "Near Valanaar: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the Gustberry Lowlands; Shriekling Matriarchs (raptors, level 9) nest just west of Valanaar; Shadowgale Urseras (bears, 10-11) roam the north of Zephras Isle.", only = { races = { "Skyborne" } } },
					{ kind = "note", text = "Feed Pet: open your spellbook, cast Feed Pet and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Grimtak the butcher and Innkeeper Grosk in Razor Hill sell meat, Kaga Mistrunner in Thunder Bluff and the innkeepers on Zephras Isle too; Bloodhoof's innkeeper and bakers sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat." },
					{ kind = "note", text = "Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away." },
					{ kind = "note", text = "Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in Beast Training (pet level times loyalty rank minus one)." },
					{ kind = "note", text = "Beast Training (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Shoja'my in Razor Hill, Seikwa at Bloodhoof, Genn Fairweather on Zephras Isle, Xon'cha in Orgrimmar), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with Beast Training. A pet holds four active abilities at most." },
					{ kind = "note", text = "Pet trainers sell Growl ranks and resistances. Horde: Harruk in Razor Hill, Reban Freerunner at Bloodhoof, Xao'tsu in Orgrimmar's Valley of Honor, Hesuwa Thunderhorn on Thunder Bluff's Hunter Rise, Quel'dora Quickgale in Valanaar, later Grokor in Stonard and Zudd at Grom'gol." },
					{ kind = "note", text = "Call Pet, Dismiss Pet and Revive Pet are in your spellbook now; Mend Pet comes from your trainer at 12. A dead pet needs Revive Pet; one that is away more than about 100 yards is dismissed and comes back with Call Pet." },
				} },
			},
		},
		{
			id = "forever/class/hunter/the-hunters-charm", title = "The Hunter's Charm", category = "Class", folder = "Hunter", classes = { "Hunter" }, levels = { 50, 52 }, zone = 1447, version = 1, revision = "3a1c55716d234f502c17e4e388310310f69600681e6b1144513b8c15c4cdaee1", legacyRevision = "13a01b7ff9c4f4b838ec9ad0e77e3084476946169da55159718088af301f2792", keywords = { "Ogtinc", "Courser Antlers", "Wavethrashing", "The Green Drake", "Morphaz", "Mosshoof Courser", "Wavethrasher", "Sunken Temple", "Temple of Atal'Hakkar", "Azshara", "class quest" }, rewards = { { text = "Experience" } }, why = "Experience at 50 through Azshara and the Sunken Temple; Classic's item choice may be gone on Forever.",
			steps = {
				{ title = "The Hunter's Charm (Alliance)", tip = "At 50 any Alliance hunter trainer offers it: Ulfir Ironbeard in Stormwind's Dwarven District, Olmin Burningbeard in Ironforge's Hall of Arms or Dorion in Darnassus' Cenarion Enclave.", only = { factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8151, npc = 5516, note = "Ulfir Ironbeard" },
				} },
				{ title = "The Hunter's Charm (Horde)", tip = "At 50 any Horde hunter trainer offers it: Ormak Grimshot in Orgrimmar's Valley of Honor or Holt Thunderhorn on Hunter Rise in Thunder Bluff.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8151, npc = 3352, note = "Ormak Grimshot" },
				} },
				{ title = "Ogtinc", tip = "Ogtinc lives on a raised spot on the cliffs at the north-east rim of the Ruins of Eldarath, west-central Azshara. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to Talrendis Point; Horde: fly to Valormok, a short ride west of him.", zone = 1447, goals = {
					{ kind = "getfp", place = "Talrendis Point", only = { factions = { "Alliance" } } },
					{ kind = "getfp", place = "Valormok", only = { factions = { "Horde" } } },
					{ kind = "turnin", quest = 8151, note = "Ogtinc" },
					{ kind = "accept", quest = 8153 },
				} },
				{ title = "Courser Antlers", tip = "You need two Perfect Courser Antlers. Mosshoof Coursers (level 52-53, deer) graze all over Azshara and drop one about one kill in twelve, so expect two dozen kills. Good herds: north of the Thalassian Base Camp in the north, and the hills north-east and south-east of Valormok; the Lake Mennar area also has elite giants and dragonkin. They Enrage at 30% health. Coursers share spawn points with the Thunderhead hippogryphs: if none are around, kill the hippogryphs and coursers may spawn instead. Respawn is about five and a half minutes.", zone = 1447, goals = {
					{ kind = "collect", quest = 8153, objective = 1, item = 20017, count = 2, note = "Perfect Courser Antler, from Mosshoof Coursers" },
				} },
				{ title = "Ogtinc", zone = 1447, goals = {
					{ kind = "turnin", quest = 8153, note = "Ogtinc" },
					{ kind = "accept", quest = 8231 },
				} },
				{ title = "Wavethrashing", tip = "You need six Wavethrasher Scales. Wavethrashers (three-headed sea beasts) live along Azshara's coasts, mostly underwater: the Young Wavethrashers (level 51-52) of the north-east shore drop a scale about one kill in three, the Wavethrashers (52-53) of the east coast by the Tower of Eldara about as often (a few walk the beach there), the Great Wavethrashers (53-54) of the south-east shore about one in seven. Track Beasts does not show them; fight them where you can breathe, and bring water breathing if you can. Elite sharks swim the deeper water.", zone = 1447, goals = {
					{ kind = "collect", quest = 8231, objective = 1, item = 20087, count = 6, note = "Wavethrasher Scales" },
				} },
				{ title = "Ogtinc", zone = 1447, goals = {
					{ kind = "turnin", quest = 8231, note = "Ogtinc" },
					{ kind = "accept", quest = 8232 },
				} },
				{ title = "Morphaz in the Sunken Temple", tip = "Morphaz is an elite green drake (level 52) inside the Sunken Temple, a five-player dungeon: needs a group of five. The temple stands in the Pool of Tears in eastern Swamp of Sorrows: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep or Darkshire and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to Jammal'an the Prophet in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses Acid Breath and Wing Flap. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls.", zone = 1435, goals = {
					{ kind = "collect", quest = 8232, objective = 1, item = 20019, map = 1435, x = 69, y = 54, note = "Tooth of Morphaz, inside the Sunken Temple" },
				} },
				{ title = "The Green Drake", tip = "In Classic Ogtinc let you choose the Devilsaur Eye, the Devilsaur Tooth or the Hunting Spear here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in.", zone = 1447, goals = {
					{ kind = "turnin", quest = 8232, note = "Ogtinc" },
				} },
			},
		},
		{
			id = "forever/class/mage/arcane-refreshment", title = "Conjure Water (Arcane Refreshment)", category = "Class", folder = "Mage", classes = { "Mage" }, levels = { 60, 60 }, zone = 1444, version = 1, revision = "a26d8701e33e4cb0c4cf88faeb645422f4b1434e52abdaff00ac7a1ccb6577c5", legacyRevision = "1215f77165cbe199f969da1f3162058b228c6429112186d0d137c7d25d8a5568", keywords = { "Arcane Refreshment", "Conjure Water", "Lorekeeper Lydros", "Athenaeum", "Hydrospawn", "Hydrospawn Essence", "Warpwood Quarter", "Dire Maul", "Shen'dralar", "Mage", "class spell" }, rewards = { { spell = 10140, name = "Conjure Water" }, { text = "Shen'dralar reputation" } }, why = "The level 60 Conjure Water, from a Dire Maul library: drink for you and your group.",
			steps = {
				{ title = "Lorekeeper Lydros", tip = "Fly to Feathermoon (Alliance) or Camp Mojache (Horde) and ride to Dire Maul in central Feralas. Lorekeeper Lydros waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a Crescent Key (it drops from the imp Pusillin in the East wing; a Powerful Seaforium Charge also opens them; Blink no longer gets past). Other mages in your group can take it too: share it.", zone = 1444, goals = {
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 7463, map = 1444, x = 58, y = 44.5, note = "Lorekeeper Lydros" },
				} },
				{ title = "Hydrospawn", tip = "Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. Riptide hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets.", zone = 1444, goals = {
					{ kind = "collect", quest = 7463, objective = 1, item = 18299, map = 1444, x = 58, y = 44.5, group = 5, note = "Hydrospawn Essence: Hydrospawn" },
				} },
				{ title = "Back to Lydros", zone = 1444, goals = {
					{ kind = "turnin", quest = 7463, map = 1444, x = 58, y = 44.5, note = "Lorekeeper Lydros: Conjure Water, and 200 Shen'dralar reputation" },
				} },
			},
		},
		{
			id = "forever/class/mage/astral-knot-garment", title = "Astral Knot Garment", category = "Class", folder = "Mage", faction = "Alliance", classes = { "Mage" }, levels = { 26, 30 }, zone = 1453, version = 1, revision = "66e5822186199922964891eed35b9e0b6e81dc35614d75855da07cd21b6cb563", legacyRevision = "0ebf146058ca06285ab21629685b472cb3b49180970f2453a8e73936986f10db", keywords = { "High Sorcerer Andromath", "Ur's Treatise on Shadow Magic", "Tower of Ilgalar", "Redridge Mountains", "Pristine Spider Silk", "Carrion Recluse", "Duskwood", "Wynne Larson", "Astral Knot Robe", "Astral Knot Blouse", "Mage", "class robe" }, rewards = { { item = 7511, choice = true }, { item = 9516, choice = true } }, why = "A robe or a blouse for Alliance mages in their late 20s.",
			steps = {
				{ title = "Bink (Ironforge)", tip = "Bink teaches mages in Ironforge's Mystic Ward. Take the Deeprun Tram from Tinker Town to Stormwind afterwards.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 26 },
					{ kind = "accept", quest = 1939, npc = 5144, note = "Bink" },
				} },
				{ title = "Jennea Cannon (Stormwind)", tip = "Jennea Cannon stands at the top of the Wizard's Sanctum, the violet tower of the Mage Quarter; the portal near the top of the spiral ramp takes you to her.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "level", level = 26 },
					{ kind = "accept", quest = 1939, npc = 5497, note = "Jennea Cannon" },
				} },
				{ title = "High Sorcerer Andromath (Skyborne)", tip = "You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of Stormwind's Mage Quarter. High Sorcerer Andromath waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. (Jennea Cannon may also offer you High Sorcerer Andromath, the pointer quest; it is only a pointer and you can skip it.)", only = { races = { "Skyborne" } }, zone = 1453, goals = {
					{ kind = "level", level = 26 },
					{ kind = "accept", quest = 1938, npc = 5694, note = "High Sorcerer Andromath" },
				} },
				{ title = "High Sorcerer Andromath", tip = "High Sorcerer Andromath waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers.", only = { races = { "Human", "Gnome" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1939, note = "High Sorcerer Andromath" },
					{ kind = "accept", quest = 1938 },
				} },
				{ title = "The Tower of Ilgalar", tip = "Head east through Elwynn Forest into Redridge, or fly to Lakeshire. The Tower of Ilgalar stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' Mana Burn interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it.", zone = 1433, goals = {
					{ kind = "collect", quest = 1938, objective = 1, item = 7266, note = "Ur's Treatise on Shadow Magic" },
				} },
				{ title = "Back to Andromath", zone = 1453, goals = {
					{ kind = "turnin", quest = 1938, note = "High Sorcerer Andromath" },
					{ kind = "accept", quest = 1940 },
				} },
				{ title = "Carrion Recluses", tip = "Raven Hill Cemetery in western Duskwood: the six Carrion Recluses (level 25-26, green, Paralyzing Poison) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. Mor'Ladim, a level 35 elite skeleton, walks the cemetery: watch for him.", zone = 1431, goals = {
					{ kind = "collect", quest = 1940, objective = 1, item = 7267, count = 8, note = "Pristine Spider Silk" },
				} },
				{ title = "Wynne Larson", tip = "Wynne Larson works at Larson Clothiers in the Mage Quarter. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1940, note = "Wynne Larson" },
					{ kind = "accept", quest = 1942 },
					{ kind = "turnin", quest = 1942, choose = { { item = 7511 }, { item = 9516 } }, note = "Astral Knot Garment" },
				} },
			},
		},
		{
			id = "forever/class/mage/atiesh", title = "Atiesh, Greatstaff of the Guardian", category = "Class", folder = "Raid", classes = { "Priest", "Mage", "Warlock", "Druid" }, levels = { 60, 60 }, zone = 1446, version = 1, revision = "1dd36bb5a0b6b4bb6cf392af45fa436f266b0dd7ea7326d5be0f82646a27e878", keywords = { "Atiesh", "Greatstaff of the Guardian", "Splinter of Atiesh", "Frame of Atiesh", "Befouled Greatstaff", "Anachronos", "Caverns of Time", "Staff Head of Atiesh", "Base of Atiesh", "Kel'Thuzad", "C'Thun", "Naxxramas", "Ahn'Qiraj", "Stratholme", "Consecrated Earth", "Hand of Sargeras", "legendary", "Mage", "Priest", "Warlock", "Druid", "raid" }, rewards = { { item = 22589 }, { item = 22631 }, { item = 22630 }, { item = 22632 } }, why = "The legendary staff of the Guardian: forty splinters from Naxxramas, two raid bosses and a demon in Stratholme.",
			steps = {
				{ title = "Splinters of Atiesh", tip = "Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the Plaguewood in Eastern Plaguelands: each of its twelve bosses before Sapphiron and Kel'Thuzad, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack.", zone = 1446, goals = {
					{ kind = "level", level = 60 },
					{ kind = "collect", item = 22726, count = 40, group = 40, note = "Splinter of Atiesh" },
					{ kind = "use", item = 22726, note = "Forming Frame of Atiesh: forty splinters become the Frame of Atiesh" },
				} },
				{ title = "Anachronos", tip = "Right-click the Frame of Atiesh to start the quest, then take it to Anachronos, the bronze dragon in elf form who stands outside the Caverns of Time in eastern Tanaris. Fly to Gadgetzan and ride east.", zone = 1446, goals = {
					{ kind = "accept", quest = 9250, item = 22727, note = "Frame of Atiesh" },
					{ kind = "turnin", quest = 9250, note = "Anachronos" },
					{ kind = "accept", quest = 9251 },
				} },
				{ title = "The Staff Head and the Base", tip = "Two more raid bosses, a full 40-player raid each, both pieces always drop: the Staff Head of Atiesh from Kel'Thuzad on his throne at the top of Naxxramas, the Base of Atiesh from C'Thun at the bottom of the Temple of Ahn'Qiraj, behind the Gates of Ahn'Qiraj in southern Silithus. Each boss comes back once a week.", zone = 1446, goals = {
					{ kind = "collect", quest = 9251, objective = 1, item = 22733, note = "Staff Head of Atiesh: Kel'Thuzad, Naxxramas" },
					{ kind = "collect", quest = 9251, objective = 2, item = 22734, map = 1451, x = 29.1, y = 93.6, note = "Base of Atiesh: C'Thun, Temple of Ahn'Qiraj, past the Gate of Ahn'Qiraj" },
				} },
				{ title = "Back to Anachronos", zone = 1446, goals = {
					{ kind = "turnin", quest = 9251, note = "Anachronos" },
					{ kind = "accept", quest = 9270, only = { classes = { "Mage" } }, note = "your class's Atiesh quest; he hands you the befouled staff" },
					{ kind = "accept", quest = 9257, only = { classes = { "Priest" } } },
					{ kind = "accept", quest = 9271, only = { classes = { "Warlock" } } },
					{ kind = "accept", quest = 9269, only = { classes = { "Druid" } } },
				} },
				{ title = "Atiesh, Hand of Sargeras", tip = "Take the befouled staff to Stratholme, the dungeon at the north end of Eastern Plaguelands, through the main gate. On Festival Lane find the patch of Consecrated Earth with a small white flame on it, stand on it and use the staff: Atiesh, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his Unholy Aura hurts everyone and cannot be dispelled (shadow resistance helps), his Breath of Sargeras curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup.", zone = 1423, goals = {
					{ kind = "use", item = 22737, map = 1423, x = 26.11, y = 11.13, note = "the befouled staff, on the Consecrated Earth inside Stratholme" },
					{ kind = "kill", quest = 9270, objective = 1, npc = 16387, map = 1423, x = 26.11, y = 11.13, group = true, only = { classes = { "Mage" } }, note = "Atiesh, Hand of Sargeras" },
					{ kind = "kill", quest = 9257, objective = 1, npc = 16387, map = 1423, x = 26.11, y = 11.13, group = true, only = { classes = { "Priest" } } },
					{ kind = "kill", quest = 9271, objective = 1, npc = 16387, map = 1423, x = 26.11, y = 11.13, group = true, only = { classes = { "Warlock" } } },
					{ kind = "kill", quest = 9269, objective = 1, npc = 16387, map = 1423, x = 26.11, y = 11.13, group = true, only = { classes = { "Druid" } } },
				} },
				{ title = "The Greatstaff", tip = "Back to Anachronos at the Caverns of Time.", zone = 1446, goals = {
					{ kind = "turnin", quest = 9270, rewards = { { item = 22589 } }, only = { classes = { "Mage" } }, note = "Anachronos: Atiesh, Greatstaff of the Guardian" },
					{ kind = "turnin", quest = 9257, rewards = { { item = 22631 } }, only = { classes = { "Priest" } } },
					{ kind = "turnin", quest = 9271, rewards = { { item = 22630 } }, only = { classes = { "Warlock" } } },
					{ kind = "turnin", quest = 9269, rewards = { { item = 22632 } }, only = { classes = { "Druid" } } },
				} },
			},
		},
		{
			id = "forever/class/mage/celestial-orb", title = "Celestial Orb and Stave", category = "Class", folder = "Mage", classes = { "Mage" }, levels = { 35, 40 }, zone = 1445, version = 1, revision = "3bd7db008adaaddc9190b184e87f07ad011e76e061e8edec2d52d96f5018f7f3", legacyRevision = "0feca763b3886af52506fa55f674d3a7a92c74e1681bef2e4145d937cff2ef29", keywords = { "Return to the Marsh", "Tabetha", "The Infernal Orb", "Burning Blade Summoner", "Mannoroc Coven", "Desolace", "The Exorcism", "Demon of the Orb", "Power in Uldaman", "Obsidian Sentinel", "Uldaman", "Mana Surges", "Celestial Power", "Celestial Orb", "Celestial Stave", "Mage", "class weapon" }, rewards = { { item = 7515, choice = true }, { item = 9517, choice = true } }, why = "An off-hand orb or a staff for the late 30s, your pick.",
			steps = {
				{ title = "Return to the Marsh (Stormwind)", tip = "Jennea Cannon at the top of the Wizard's Sanctum, Stormwind's Mage Quarter, sends you back to Tabetha; Bink in Ironforge gives the same quest.", only = { factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 1953, npc = 5497, note = "Jennea Cannon" },
				} },
				{ title = "Return to the Marsh (Orgrimmar)", tip = "Deino, one of Orgrimmar's mage trainers in Darkbriar Lodge, sends you back to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 1953, npc = 5885, note = "Deino" },
				} },
				{ title = "Tabetha", tip = "Tabetha's cottage is deep in the marsh west of Theramore, just north of the Stonemaul Ruins; come in from the west road, the elites roam its east side.", zone = 1445, goals = {
					{ kind = "turnin", quest = 1953, note = "Tabetha" },
					{ kind = "accept", quest = 1954 },
				} },
				{ title = "The Infernal Orb", tip = "The Burning Blade Summoners (level 38-39, not elite) work the Mannoroc Coven in southern Desolace, east of Shadowprey Village, and every one carries an Infernal Orb. They cast Shadow Bolt from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western Mulgore, south-west of Thunder Bluff.", zone = 1443, goals = {
					{ kind = "collect", quest = 1954, objective = 1, item = 7291, note = "Infernal Orb: Burning Blade Summoner" },
				} },
				{ title = "The Exorcism", tip = "Back at Tabetha's. Hand in the orb now; The Exorcism waits for level 38. Kill the critters around the cottage first: they join the fight. Accepting The Exorcism starts a 3 minute timer, and Tabetha calls the Demon of the Orb out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again.", zone = 1445, goals = {
					{ kind = "turnin", quest = 1954, note = "Tabetha" },
					{ kind = "level", level = 38 },
					{ kind = "accept", quest = 1955 },
					{ kind = "kill", quest = 1955, objective = 1, npc = 6549, note = "Demon of the Orb (elite, 40)" },
					{ kind = "turnin", quest = 1955, note = "Tabetha" },
					{ kind = "accept", quest = 1956 },
				} },
				{ title = "Power in Uldaman", tip = "Uldaman is a dungeon in the northern Badlands: a group of five, from level 40 here. Go in by the rear entrance, a cave in Dustwind Gulch south-east of the main entrance (elite dragons fly nearby): the Obsidian Sentinel (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an Obsidian Shard, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back.", zone = 1418, goals = {
					{ kind = "level", level = 40 },
					{ kind = "collect", quest = 1956, objective = 1, item = 8053, map = 1418, x = 49.1, y = 13.7, note = "Obsidian Power Source: Obsidian Sentinel" },
				} },
				{ title = "Mana Surges", tip = "Back to Tabetha. Accepting Mana Surges opens a rift beside her cottage and starts a 10 minute timer: twelve Mana Surges (level 40, Shock and Lightning Bolt) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out.", zone = 1445, goals = {
					{ kind = "turnin", quest = 1956, note = "Tabetha" },
					{ kind = "accept", quest = 1957 },
					{ kind = "kill", quest = 1957, objective = 1, npc = 6550, count = 12, note = "Mana Surge" },
					{ kind = "turnin", quest = 1957, note = "Tabetha" },
					{ kind = "accept", quest = 1958 },
					{ kind = "turnin", quest = 1958, choose = { { item = 7515 }, { item = 9517 } }, note = "Celestial Power: the Celestial Orb (off-hand) or the Celestial Stave" },
				} },
				{ title = "Tabetha's Task (optional)", tip = "At 40 the mage trainers who send you to Tabetha (Jennea Cannon, Bink, Anastasia Hartwell, Deino) also have Tabetha's Task, a quest any class can do. Tabetha then wants the Tiara of the Deep from Hydromancer Velratha, a level 46 elite naga in Zul'Farrak, the troll dungeon in north-western Tanaris: a group of five, level 44-54. The reward window shows the Spellshifter Rod and the Gemshale Pauldrons.", zone = 1445, goals = {
					{ kind = "level", level = 40 },
					{ kind = "accept", quest = 2861, optional = true },
					{ kind = "turnin", quest = 2861, optional = true, note = "Tabetha" },
					{ kind = "accept", quest = 2846, optional = true },
				} },
				{ title = "Tiara of the Deep in Zul'Farrak", tip = "Zul'Farrak, the troll dungeon in north-western Tanaris, needs a group of five; the guide waits for level 44. Hydromancer Velratha is one of the bosses by the sacred pool, and the tiara always drops.", when = { { test = "onquest", quests = { 2846 } } }, zone = 1446, goals = {
					{ kind = "level", level = 44 },
					{ kind = "collect", quest = 2846, objective = 1, item = 9234, map = 1446, x = 38.7, y = 20, note = "Tiara of the Deep: Hydromancer Velratha, Zul'Farrak" },
					{ kind = "turnin", quest = 2846, note = "Tabetha" },
				} },
			},
		},
		{
			id = "forever/class/mage/destroy-morphaz", title = "Destroy Morphaz", category = "Class", folder = "Mage", classes = { "Mage" }, levels = { 50, 54 }, zone = 1447, version = 1, revision = "d2182115e39822dfda74657e92b6d3872d97ea65704d7529245366fcbab09c15", legacyRevision = "ddf729763919fe0f7c2f4418ba7a492c38891136c66cfbf6e19291b806cc3472", keywords = { "Magecraft", "Archmage Xylem", "Sanath Lim-yo", "Magic Dust", "Glittering Dust", "Blood Elf", "The Siren's Coral", "Enchanted Coral", "Spitelash Siren", "Destroy Morphaz", "Arcane Shard", "Sunken Temple", "Temple of Atal'Hakkar", "Mage" }, rewards = { { text = "Experience" } }, why = "Experience at 50 through Azshara and the Sunken Temple; Classic's item choice may be gone on Forever.",
			steps = {
				{ title = "Magecraft (Stormwind)", tip = "Maginor Dumas, the Master Mage, stands in the Wizard's Sanctum in Stormwind's Mage Quarter; Dink in Ironforge gives the same quest.", only = { factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8250, npc = 331, note = "Maginor Dumas" },
				} },
				{ title = "Magecraft (Orgrimmar)", tip = "Uthel'nay, one of Orgrimmar's mage trainers in Darkbriar Lodge, gives it; so do Pierce Shackleton in the Undercity and Archmage Shymm in Thunder Bluff.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8250, npc = 7311, note = "Uthel'nay" },
				} },
				{ title = "Sanath Lim-yo", tip = "Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below his master's tower, a short way east of Valormok: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to Archmage Xylem at the top of the tower; an attendant at the top sends you back down, as often as you like.", zone = 1447, goals = {
					{ kind = "turnin", quest = 8250, note = "Sanath Lim-yo" },
					{ kind = "accept", quest = 8251, note = "Archmage Xylem, in the tower" },
				} },
				{ title = "Glittering Dust", tip = "The blood elves hold the Thalassian Base Camp on the hills of north-eastern Azshara. Blood Elf Surveyors (51-52, Fire Nova up close) and Reclaimers (52-53, Fireball, and they heal and Renew each other) each drop the dust about one time in four; they spot you from far off, so pull at the edges. They come back after 5 1/2 minutes.", zone = 1447, goals = {
					{ kind = "collect", quest = 8251, objective = 1, item = 20028, count = 10, note = "Glittering Dust" },
				} },
				{ title = "Archmage Xylem", tip = "Back to Sanath Lim-yo, who teleports you up to the tower.", zone = 1447, goals = {
					{ kind = "turnin", quest = 8251, note = "Archmage Xylem" },
					{ kind = "accept", quest = 8252 },
				} },
				{ title = "Enchanted Coral", tip = "The Spitelash Sirens (level 50-52) walk the ruins and beaches around the Ruins of Eldarath and the bay east of Valormok, often three together, and a few stand inside the Temple of Zin-Malor; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. Lingering Highborne ghosts wander the ruins: watch your back.", zone = 1447, goals = {
					{ kind = "collect", quest = 8252, objective = 1, item = 20029, count = 6, note = "Enchanted Coral: Spitelash Siren" },
				} },
				{ title = "Archmage Xylem again", tip = "Back to Sanath Lim-yo and up to the tower.", zone = 1447, goals = {
					{ kind = "turnin", quest = 8252, note = "Archmage Xylem" },
					{ kind = "accept", quest = 8253 },
				} },
				{ title = "Morphaz", tip = "The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to Jammal'an the Prophet and Ogom the Wretched in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, Acid Breath and Wing Flap) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear.", zone = 1435, goals = {
					{ kind = "collect", quest = 8253, objective = 1, item = 20085, map = 1435, x = 69.9, y = 53.6, note = "Arcane Shard: Morphaz" },
				} },
				{ title = "The Arcane Shard", tip = "Back to Azshara, Sanath Lim-yo and the tower. Look at the reward window before you hand in: Classic offered the Arcane Crystal Pendant, the Fire Ruby or the Glacial Spike, and Forever's notes say the choice may be gone.", zone = 1447, goals = {
					{ kind = "turnin", quest = 8253, note = "Archmage Xylem" },
				} },
			},
		},
		{
			id = "forever/class/mage/ju-ju-heaps", title = "Ley or Arcane Staff or Orb (Horde)", category = "Class", folder = "Mage", faction = "Horde", classes = { "Mage" }, levels = { 10, 12 }, zone = 1411, version = 1, revision = "57bf3a5ef565aa8628a21ebff1f63bd93c0fde51f244133af0cef1a5349e8def", legacyRevision = "cc9e5db47843d6d9c97185fbf255e7173632c4b5516e70052fdd4e174f32a744", keywords = { "Speak with Un'thuwa", "Ju-Ju Heaps", "Un'thuwa", "Uthel'nay", "Thurston Xane", "Sen'jin Village", "Echo Isles", "Zalazane", "Speak with Anastasia", "The Balnir Farmstead", "Balnir Snapdragons", "Anastasia Hartwell", "Cain Firesong", "Brill", "Ley Staff", "Ley Orb", "Arcane Staff", "Arcane Orb", "Mage", "class weapon" }, rewards = { { item = 7508, choice = true }, { item = 9513, choice = true }, { item = 7507, choice = true }, { item = 9514, choice = true } }, why = "A staff or an off-hand orb at 10: Orcs and Trolls on the Echo Isles, the Undead at a Tirisfal farm.",
			steps = {
				{ title = "Un'thuwa", tip = "Un'thuwa, the troll mage trainer, stands in Sen'jin Village on the Durotar coast south of Razor Hill. Orcs coming from Orgrimmar can take Speak with Un'thuwa from Uthel'nay in the Valley of Spirits first; it is only a pointer and Un'thuwa gives Ju-Ju Heaps without it. Taking it shuts out the Undercity's Balnir Farmstead.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1884, npc = 5880, note = "Un'thuwa" },
				} },
				{ title = "Cain Firesong (Brill)", tip = "At 10 Cain Firesong, the Brill mage trainer upstairs in the Gallows' End Tavern, sends you to Anastasia Hartwell in the Undercity. Taking it shuts out Ju-Ju Heaps; if Speak with Un'thuwa (from Orgrimmar or Thunder Bluff) is in your log, abandon it first or Cain cannot give you this one. (A Troll who took this one in Brill follows the Balnir steps; an Undead who took Ju-Ju Heaps in Sen'jin, the Echo Isles steps.)", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1881, npc = 2128, note = "Cain Firesong" },
				} },
				{ title = "The Ju-Ju Heaps", tip = "Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed.", only = { races = { "Orc", "Troll", "Scourge" } }, when = { { test = "onquest", quests = { 1884 } } }, zone = 1411, goals = {
					{ kind = "interact", quest = 1884, objective = 1, object = 102986, note = "Ju-Ju Heap, four of them" },
				} },
				{ title = "Back to Un'thuwa", tip = "The orb is an off-hand for a one-hand weapon; the staff is a two-hander.", only = { races = { "Orc", "Troll", "Scourge" } }, when = { { test = "onquest", quests = { 1884 } } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1884, choose = { { item = 7508 }, { item = 9513 } }, note = "Un'thuwa: Ley Orb or Ley Staff" },
				} },
				{ title = "Anastasia Hartwell", tip = "Walk south from Brill to the Ruins of Lordaeron and take the lift down into the Undercity. Anastasia stands in the Magic Quarter, the north-east ring of the city.", only = { races = { "Scourge", "Troll" } }, when = { { test = "onquest", quests = { 1881 } } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1881, note = "Anastasia Hartwell" },
					{ kind = "accept", quest = 1882 },
				} },
				{ title = "The Balnir Farmstead", tip = "The Balnir Farmstead lies south-east of Brill, south of the road east to the Bulwark. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no Herbalism. They come back within seconds.", only = { races = { "Scourge", "Troll" } }, when = { { test = "onquest", quests = { 1882 } } }, zone = 1420, goals = {
					{ kind = "collect", quest = 1882, objective = 1, item = 7227, note = "Balnir Snapdragons" },
				} },
				{ title = "Back to Anastasia", only = { races = { "Scourge", "Troll" } }, when = { { test = "onquest", quests = { 1882 } } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1882, choose = { { item = 7507 }, { item = 9514 } }, note = "Anastasia Hartwell: Arcane Orb or Arcane Staff" },
				} },
			},
		},
		{
			id = "forever/class/mage/mages-wand", title = "Mage's Wand", category = "Class", folder = "Mage", classes = { "Mage" }, levels = { 30, 40 }, zone = 1445, version = 1, revision = "d23ffcb8e3d03f1b0a00462c2e75a2b3aef8997ebb62e6e7c4f235d2c833efaf", legacyRevision = "6a98e32a05ee0a3542e889d54a954ecfcb2a814f8aebc7ac5f9c47cd6b7177d3", keywords = { "Journey to the Marsh", "Tabetha", "Hidden Secrets", "Magus Tirth", "Get the Scoop", "Plucky Johnson", "Rituals of Power", "Scarlet Monastery", "Library", "Items of Power", "Jade", "Witherbark Totem Stick", "Bolt Charged Bramble", "Arathi Highlands", "Icefury Wand", "Nether Force Wand", "Ragefire Wand", "Mage", "class wand" }, rewards = { { item = 7514, choice = true }, { item = 11263, choice = true }, { item = 7513, choice = true } }, why = "A wand of your school for the 30s: frost, arcane or fire.",
			steps = {
				{ title = "Journey to the Marsh (Stormwind)", tip = "Jennea Cannon at the top of the Wizard's Sanctum, Stormwind's Mage Quarter, sends you to Tabetha; Bink in Ironforge gives the same quest.", only = { factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 1947, npc = 5497, note = "Jennea Cannon" },
				} },
				{ title = "Journey to the Marsh (Orgrimmar)", tip = "Deino, one of Orgrimmar's mage trainers in Darkbriar Lodge, sends you to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 1947, npc = 5885, note = "Deino" },
				} },
				{ title = "Tabetha", tip = "Tabetha, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the Stonemaul Ruins. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the Barrens. Her cottage is no refuge: mobs follow you inside. Take both her quests.", zone = 1445, goals = {
					{ kind = "turnin", quest = 1947, note = "Tabetha" },
					{ kind = "accept", quest = 1949 },
					{ kind = "accept", quest = 1948 },
				} },
				{ title = "Magus Tirth", tip = "Magus Tirth spends his days at the race track in the Shimmering Flats, south-east Thousand Needles.", zone = 1441, goals = {
					{ kind = "turnin", quest = 1949, note = "Magus Tirth" },
					{ kind = "accept", quest = 1950 },
				} },
				{ title = "\"Plucky\" Johnson", tip = "Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes.", zone = 1441, goals = {
					{ kind = "complete", quest = 1950, map = 1441, x = 79.6, y = 75.6, note = "\"Plucky\" Johnson" },
					{ kind = "turnin", quest = 1950, note = "Magus Tirth" },
					{ kind = "accept", quest = 1951 },
				} },
				{ title = "Witherbark trolls and the Bolt Charged Bramble", tip = "The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of Hammerfall; every kind of them drops a Witherbark Totem Stick about two times in five: you need ten. Then go to the Circle of Outer Binding (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the Bolt Charged Bramble forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more.", zone = 1417, goals = {
					{ kind = "collect", item = 7273, count = 10, note = "Witherbark Totem Stick" },
					{ kind = "use", quest = 1948, objective = 2, item = 7273, map = 1417, x = 52.04, y = 50.74, note = "at the middle stone of the Circle of Outer Binding" },
					{ kind = "collect", quest = 1948, objective = 2, item = 7272, map = 1417, x = 52.04, y = 50.74, note = "Bolt Charged Bramble" },
				} },
				{ title = "Jade", tip = "Tabetha also wants one Jade, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of Southshore drop one about every fifth kill. Do not sell it to a vendor by mistake.", zone = 1417, goals = {
					{ kind = "collect", quest = 1948, objective = 1, item = 1529, note = "Jade" },
				} },
				{ title = "Rituals of Power", tip = "Tirth sold the book to the Scarlet Crusade. The Scarlet Monastery stands in north-eastern Tirisfal Glades; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in Arcanist Doan's round room: on the left-hand shelf as you face his room, next to the Compendium of the Fallen. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read.", zone = 1420, goals = {
					{ kind = "collect", quest = 1951, objective = 1, item = 7274, map = 1420, x = 82.6, y = 33.8, note = "Rituals of Power: Scarlet Monastery Library" },
				} },
				{ title = "Tabetha's ritual", tip = "Back to Tabetha. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire).", zone = 1445, goals = {
					{ kind = "turnin", quest = 1951, note = "Tabetha" },
					{ kind = "turnin", quest = 1948 },
					{ kind = "accept", quest = 1952 },
					{ kind = "turnin", quest = 1952, choose = { { item = 7514 }, { item = 11263 }, { item = 7513 } }, note = "Mage's Wand" },
				} },
			},
		},
		{
			id = "forever/class/mage/manaweave-robe", title = "Manaweave Robe", category = "Class", folder = "Mage", faction = "Alliance", classes = { "Mage" }, levels = { 15, 17 }, zone = 1453, version = 1, revision = "c5ca562d3cd2903538e8c595fd98c453bc82d2790a7912ceb621482917ffd4f6", legacyRevision = "7dca26519ad982c9a3a16047e65e0911485e38882d6c15bf3808ed4090554746", keywords = { "Jennea Cannon", "Investigate the Blue Recluse", "Gathering Materials", "Wynne Larson", "Rift Spawn", "Charged Rift Gem", "Silver Stream Mine", "Loch Modan", "Manaweave Robe", "Mage", "class robe" }, rewards = { { item = 7509 } }, why = "A robe at 15 for Alliance mages, from Stormwind and Loch Modan.",
			steps = {
				{ title = "Zaldimar Wefhellt (Goldshire)", tip = "Zaldimar Wefhellt is the Goldshire mage trainer, upstairs in the Lion's Pride Inn.", only = { races = { "Human", "Skyborne" } }, zone = 1429, goals = {
					{ kind = "level", level = 15 },
					{ kind = "accept", quest = 1919, npc = 328, note = "Zaldimar Wefhellt" },
				} },
				{ title = "Dink (Ironforge)", tip = "Dink teaches mages in Ironforge's Mystic Ward. Take the Deeprun Tram from Tinker Town to Stormwind afterwards.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 15 },
					{ kind = "accept", quest = 1919, npc = 7312, note = "Dink" },
				} },
				{ title = "Jennea Cannon", tip = "Jennea Cannon stands at the top of the Wizard's Sanctum, the violet tower of the Mage Quarter: climb the spiral ramp and take the portal near the top. The Chest of Containment Coffers and the Cantation of Manifestation lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1919, note = "Jennea Cannon" },
					{ kind = "accept", quest = 1920 },
					{ kind = "collect", quest = 1920, objective = 2, item = 7247, note = "Chest of Containment Coffers" },
					{ kind = "collect", quest = 1920, objective = 3, item = 7308, note = "Cantation of Manifestation" },
				} },
				{ title = "The Blue Recluse", tip = "The Blue Recluse is the tavern in the Mage Quarter. Read the Cantation of Manifestation inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of Frost Nova fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the Chest of Containment Coffers on it while it is stunned, then click the Filled Containment Coffer it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds.", zone = 1453, goals = {
					{ kind = "use", item = 7308, map = 1453, x = 51.3, y = 93.3, frame = "live", optional = true, note = "Cantation of Manifestation" },
					{ kind = "kill", npc = 6492, optional = true, note = "Rift Spawn, down to the stun" },
					{ kind = "use", item = 7247, map = 1453, x = 51.3, y = 93.3, frame = "live", optional = true, note = "Chest of Containment Coffers, on the stunned Rift Spawn" },
					{ kind = "collect", quest = 1920, objective = 1, item = 7292, count = 3, map = 1453, x = 51.3, y = 93.3, frame = "live", note = "Filled Containment Coffer" },
				} },
				{ title = "Back to Jennea Cannon", zone = 1453, goals = {
					{ kind = "turnin", quest = 1920, note = "Jennea Cannon" },
					{ kind = "accept", quest = 1921 },
				} },
				{ title = "Linen Cloth", tip = "Any humanoid drops Linen Cloth, and the Tunnel Rats in the Silver Stream Mine drop it while you gather the gems; the Auction House in the Trade District sells it. You hand in ten.", zone = 1453, goals = {
					{ kind = "collect", quest = 1921, objective = 1, item = 2589, count = 10, note = "Linen Cloth" },
				} },
				{ title = "The Silver Stream Mine", tip = "Take the Deeprun Tram to Ironforge, then the road east through the South Gate tunnel into Loch Modan. The Silver Stream Mine is at the north end of the loch, north of Thelsamar; Tunnel Rat kobolds hold it. The gems come only from the tall stacked Miners' League Crates (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest.", zone = 1432, goals = {
					{ kind = "collect", quest = 1921, objective = 2, item = 7249, count = 6, note = "Charged Rift Gem: Miners' League Crates" },
				} },
				{ title = "Wynne Larson", tip = "Back to Stormwind by the tram. Wynne Larson works at Larson Clothiers in the Mage Quarter.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1921, note = "Wynne Larson" },
					{ kind = "accept", quest = 1941 },
					{ kind = "turnin", quest = 1941, note = "Wynne Larson: Manaweave Robe" },
				} },
			},
		},
		{
			id = "forever/class/mage/nether-lace-garment", title = "Nether-lace Garment", category = "Class", folder = "Mage", faction = "Horde", races = { "Orc", "Scourge", "Troll" }, classes = { "Mage" }, levels = { 26, 30 }, zone = 1454, version = 1, revision = "6620b144e85252ea66b3afe596732ac2cd7fa57d93a6ede9e12a5b393df7eb62", legacyRevision = "5450665c1d4c392307a59d5da40ea9e49810fdd090925107d58634c4eb00a4b5", keywords = { "Anastasia Hartwell", "Speak with Deino", "Waters of Xavian", "Laughing Sisters", "Raynewood Retreat", "Ashenvale", "Kil'hala", "Crossroads", "Nether-lace Robe", "Nether-lace Tunic", "Mage", "class robe" }, rewards = { { item = 7512, choice = true }, { item = 9515, choice = true } }, why = "A robe or a tunic for Horde mages in their late 20s.",
			steps = {
				{ title = "Anastasia Hartwell", tip = "Anastasia Hartwell stands in the Undercity's Magic Quarter. Orcs and Trolls use Teleport: Undercity or take the zeppelin from Orgrimmar to Tirisfal Glades for her.", zone = 1458, goals = {
					{ kind = "level", level = 26 },
					{ kind = "accept", quest = 1943, note = "Anastasia Hartwell" },
				} },
				{ title = "Deino", tip = "Take the zeppelin to Orgrimmar (or use Teleport: Orgrimmar, which lands you on the upper floor of Darkbriar Lodge). Deino stands with the mage trainers on the lower floor of Darkbriar Lodge in the Valley of Spirits. She hands you Deino's Flask.", zone = 1454, goals = {
					{ kind = "turnin", quest = 1943, note = "Deino" },
					{ kind = "accept", quest = 1944 },
				} },
				{ title = "The Xavian Waterfall", tip = "Fly to Splintertree Post and swim north up the river past the big lake to its far northern end, where the zone text reads Xavian; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work.", zone = 1440, goals = {
					{ kind = "use", quest = 1944, objective = 1, item = 7269, map = 1440, x = 76.29, y = 41.49, note = "Deino's Flask, under the falls" },
					{ kind = "collect", quest = 1944, objective = 1, item = 7268, note = "Xavian Water Sample" },
				} },
				{ title = "Back to Deino", zone = 1454, goals = {
					{ kind = "turnin", quest = 1944, note = "Deino" },
					{ kind = "accept", quest = 1945 },
				} },
				{ title = "The Laughing Sisters", tip = "The Laughing Sisters, dryads of level 24-25, roam around the Raynewood Retreat in central Ashenvale; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard.", zone = 1440, goals = {
					{ kind = "collect", quest = 1945, objective = 1, item = 7270, count = 12, note = "Laughing Sister's Hair" },
				} },
				{ title = "Kil'hala", tip = "Kil'hala, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1945, note = "Kil'hala" },
					{ kind = "accept", quest = 1946 },
					{ kind = "turnin", quest = 1946, choose = { { item = 7512 }, { item = 9515 } }, note = "Nether-lace Garment" },
				} },
			},
		},
		{
			id = "forever/class/mage/polymorph-pig", title = "Polymorph: Pig", category = "Class", folder = "Mage", classes = { "Mage" }, levels = { 60, 60 }, zone = 1447, version = 1, revision = "ccb70b59e593ee3a567d586ad6665a618c76f6c658e3336e16c43ca58836651f", legacyRevision = "64d90a8d64397bebd43c86b71c74121416f946a18784f5e433a6d611ff799e80", keywords = { "Fragmented Magic", "Archmage Xylem", "Sanath Lim-yo", "Warlord Krellian", "Prismatic Shell", "Ruins of Eldarath", "Temple of Zin-Malor", "Spitelash", "Polymorph Clone", "Polymorph", "pig", "Mage", "class spell" }, rewards = { { spell = 28272, name = "Polymorph: Pig" } }, why = "A new look for Polymorph: it turns the target into a pig rather than a sheep.",
			steps = {
				{ title = "Xylem's tower", tip = "Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below Archmage Xylem's tower, a short way east of Valormok: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower.", zone = 1447, goals = {
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 9362, note = "Archmage Xylem" },
				} },
				{ title = "Warlord Krellian", tip = "Warlord Krellian (level 55, not elite, Strike and Demoralizing Roar) hides behind his Spitelash guards in the Temple of Zin-Malor, the biggest building in the middle of the Ruins of Eldarath. He always drops the Prismatic Shell and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine.", zone = 1447, goals = {
					{ kind = "collect", quest = 9362, objective = 1, item = 23250, note = "Prismatic Shell: Warlord Krellian" },
				} },
				{ title = "Archmage Xylem", tip = "Back to Sanath Lim-yo and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags.", zone = 1447, goals = {
					{ kind = "turnin", quest = 9362, note = "Archmage Xylem" },
					{ kind = "accept", quest = 9364 },
				} },
				{ title = "Polymorph Clones", tip = "Back to the Ruins of Eldarath, full of Spitelash naga. Cast your sheep Polymorph (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with Frost Nova and Arcane Explosion. Fifty clones are needed, so it takes a while; not in a raid group.", zone = 1447, goals = {
					{ kind = "kill", quest = 9364, objective = 1, npc = 16479, count = 50, note = "Polymorph Clone" },
				} },
				{ title = "Fragmented Magic", tip = "Back to Sanath Lim-yo and up to the tower.", zone = 1447, goals = {
					{ kind = "turnin", quest = 9364, note = "Archmage Xylem: Polymorph (pig)" },
				} },
			},
		},
		{
			id = "forever/class/mage/spellfire-robes", title = "Spellfire Robes", category = "Class", folder = "Mage", faction = "Horde", classes = { "Mage" }, levels = { 15, 18 }, zone = 1458, version = 1, revision = "8cc515917f5fa60fc750e19d59e2320ccb9601905e1abea6dd04e8e400b62c13", legacyRevision = "333e5d21860b14479e77c08da551ea884cac93fbc44b700f2b1fa7b70f3f6e5b", keywords = { "Anastasia Hartwell", "Report to Anastasia", "Investigate the Alchemist Shop", "Gathering Materials", "Josef Gregorian", "Rift Spawn", "Dalaran Mana Gem", "Ambermill", "Silverpine Forest", "Lesser Spellfire Robes", "Mage", "class robe" }, rewards = { { item = 7510 } }, why = "A robe at 15 for Horde mages, from the Undercity and Silverpine Forest.",
			steps = {
				{ title = "Uthel'nay (Orgrimmar)", tip = "Uthel'nay is one of Orgrimmar's mage trainers, in Darkbriar Lodge in the Valley of Spirits. Then take the zeppelin to Tirisfal Glades from the tower outside Orgrimmar's main gate.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 15 },
					{ kind = "accept", quest = 1959, npc = 7311, note = "Uthel'nay" },
				} },
				{ title = "Cain Firesong (Brill)", tip = "Cain Firesong is the Brill mage trainer, upstairs in the Gallows' End Tavern: take the stairs inside, the arrow cannot tell the floors apart.", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "level", level = 15 },
					{ kind = "accept", quest = 1959, npc = 2128, note = "Cain Firesong" },
				} },
				{ title = "Anastasia Hartwell", tip = "Anastasia Hartwell stands in the Magic Quarter. The Chest of Containment Coffers and the Cantation of Manifestation lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.", zone = 1458, goals = {
					{ kind = "turnin", quest = 1959, note = "Anastasia Hartwell" },
					{ kind = "accept", quest = 1960 },
					{ kind = "collect", quest = 1960, objective = 2, item = 7247, note = "Chest of Containment Coffers" },
					{ kind = "collect", quest = 1960, objective = 3, item = 7308, note = "Cantation of Manifestation" },
				} },
				{ title = "The alchemist shop", tip = "Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the Cantation of Manifestation: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the Chest of Containment Coffers on it, then click the Filled Containment Coffer once it appears on the floor (clicking too early wastes a charge). Three are needed.", zone = 1458, goals = {
					{ kind = "use", item = 7308, map = 1458, x = 53.2, y = 74.5, optional = true, note = "Cantation of Manifestation" },
					{ kind = "kill", npc = 6492, optional = true, note = "Rift Spawn, down to the stun" },
					{ kind = "use", item = 7247, map = 1458, x = 53.2, y = 74.5, optional = true, note = "Chest of Containment Coffers, on the stunned Rift Spawn" },
					{ kind = "collect", quest = 1960, objective = 1, item = 7292, count = 3, map = 1458, x = 53.2, y = 74.5, note = "Filled Containment Coffer" },
				} },
				{ title = "Back to Anastasia Hartwell", zone = 1458, goals = {
					{ kind = "turnin", quest = 1960, note = "Anastasia Hartwell" },
					{ kind = "accept", quest = 1961 },
				} },
				{ title = "Ambermill", tip = "Leave the Undercity and follow the road south through Silverpine Forest. Every Dalaran human drops a Dalaran Mana Gem four times in five, and Linen Cloth too: the easiest are the Dalaran Apprentices (level 13-14, Frostbolt) on the hills south-east of the Sepulcher, either side of the road south; deeper in, the walled town of Ambermill in south-east Silverpine has Watchers (18-19, Fire Shield and Flamestrike) and Wizards (19-20, Frost Nova) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten Linen Cloth also come from any humanoid or the Undercity Auction House.", zone = 1421, goals = {
					{ kind = "collect", quest = 1961, objective = 2, item = 7293, count = 6, note = "Dalaran Mana Gem" },
					{ kind = "collect", quest = 1961, objective = 1, item = 2589, count = 10, note = "Linen Cloth" },
				} },
				{ title = "Josef Gregorian", tip = "Back to the Undercity. Josef Gregorian, Victor Ward and Rhiannon Davis keep the tailor's shop in the Magic Quarter. Hand the gems and cloth to Josef and let the three of them talk for a moment; then Josef offers Spellfire Robes: take it and hand it straight back to him for the robe.", zone = 1458, goals = {
					{ kind = "turnin", quest = 1961, note = "Josef Gregorian" },
					{ kind = "accept", quest = 1962, npc = 4576, note = "Josef Gregorian" },
					{ kind = "turnin", quest = 1962, note = "Lesser Spellfire Robes" },
				} },
			},
		},
		{
			id = "forever/class/mage/staff-or-orb-alliance", title = "Ley or Arcane Staff or Orb (Alliance)", category = "Class", folder = "Mage", faction = "Alliance", classes = { "Mage" }, levels = { 10, 15 }, zone = 1429, version = 1, revision = "5c592ef7126ba866b6d757078be79374055b0808385950f2f789506c02cc958b", keywords = { "Speak with Jennea", "Mirror Lake", "Jennea Cannon", "Zaldimar Wefhellt", "Jennea's Flask", "Speak with Bink", "Mage-tastic Gizmonitor", "Bink", "Magis Sparkmantle", "Bink's Toolbox", "Speak with Belann", "Boughs in the Wind", "Belann Windwood", "Anathamaas Aetherwind", "Windbough Wand", "Ley Staff", "Ley Orb", "Arcane Staff", "Arcane Orb", "Mage", "class weapon" }, rewards = { { item = 7508, choice = true }, { item = 9513, choice = true }, { item = 7507, choice = true }, { item = 9514, choice = true }, { item = 263430 } }, why = "A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand.",
			steps = {
				{ title = "Anathamaas Aetherwind (Valanaar)", tip = "At 10 Anathamaas Aetherwind, the Valanaar mage trainer, sends you to Belann Windwood, the staff merchant a few steps away in the same town.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 93791, npc = 252373, note = "Anathamaas Aetherwind" },
					{ kind = "turnin", quest = 93791, note = "Belann Windwood" },
					{ kind = "accept", quest = 93797 },
				} },
				{ title = "The Windstone Formations", tip = "The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of Falaath Village. It does not sparkle, so look at the ground by the stones; there are two spots for it.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "collect", quest = 93797, objective = 1, item = 262668, note = "Wind-Infused Bough" },
				} },
				{ title = "Back to Belann", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 93797, rewards = { { item = 263430 } }, note = "Belann Windwood: Windbough Wand" },
					{ kind = "note", text = "Mirror Lake (the next steps) waits for you with Jennea Cannon in Stormwind, at about 15." },
				} },
				{ title = "Zaldimar Wefhellt (Goldshire)", tip = "At 10 Zaldimar Wefhellt, the Goldshire mage trainer, upstairs in the Lion's Pride Inn, sends you to Jennea Cannon in Stormwind. Taking it shuts out Speak with Bink, the Kharanos trainer's errand; Mirror Lake and Bink's Gizmonitor shut out each other, so you get one staff or orb.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1860, npc = 328, note = "Zaldimar Wefhellt" },
				} },
				{ title = "Magis Sparkmantle (Kharanos)", tip = "At 10 Magis Sparkmantle, the Kharanos mage trainer in the Thunderbrew Distillery, sends you to Bink in Ironforge. Taking it shuts out Speak with Jennea, the Goldshire trainer's errand; Bink's Gizmonitor and Jennea's Mirror Lake shut out each other, so you get one staff or orb. (A Gnome who took Zaldimar's quest in Goldshire instead follows the Mirror Lake steps; a Human who took this one, the Gizmonitor steps.)", only = { races = { "Gnome" } }, zone = 1426, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1879, npc = 1228, note = "Magis Sparkmantle" },
				} },
				{ title = "Jennea Cannon", tip = "Follow the road north into Stormwind and west to the Mage Quarter. Jennea stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you Jennea's Flask. Skyborne mages take Mirror Lake from her when they first reach Stormwind, at about 15.", only = { races = { "Human", "Gnome", "Skyborne" } }, when = { { test = "onquest", quests = { 1879 }, negate = true } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1860, only = { races = { "Human", "Gnome" } }, note = "Jennea Cannon" },
					{ kind = "accept", quest = 1861 },
				} },
				{ title = "The Mirror Lake waterfall", tip = "Leave Stormwind by the main gate and head south-west to the waterfall that feeds Mirror Lake. Wade in under the falling water to the rock behind it and use Jennea's Flask there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water.", only = { races = { "Human", "Gnome", "Skyborne" } }, when = { { test = "onquest", quests = { 1861 } } }, zone = 1429, goals = {
					{ kind = "use", quest = 1861, objective = 1, item = 7207, map = 1429, x = 28.57, y = 61.39, note = "Jennea's Flask, under the falls" },
					{ kind = "collect", quest = 1861, objective = 1, item = 7206, note = "Mirror Lake Water Sample" },
				} },
				{ title = "Back to Jennea", tip = "Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander.", only = { races = { "Human", "Gnome", "Skyborne" } }, when = { { test = "onquest", quests = { 1861 } } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1861, choose = { { item = 7508 }, { item = 9513 } }, note = "Jennea Cannon: Ley Orb or Ley Staff" },
				} },
				{ title = "Bink", tip = "Bink teaches mages in the Mystic Ward, at the back of Ironforge past the Hall of Mysteries.", only = { races = { "Human", "Gnome" } }, when = { { test = "onquest", quests = { 1879 } } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1879, note = "Bink" },
					{ kind = "accept", quest = 1880 },
				} },
				{ title = "Bink's Toolbox", tip = "Head west along the road to Gnomeregan. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone.", only = { races = { "Human", "Gnome" } }, when = { { test = "onquest", quests = { 1880 } } }, zone = 1426, goals = {
					{ kind = "interact", object = 102984, note = "Bink's Toolbox" },
					{ kind = "collect", quest = 1880, objective = 1, item = 7226, note = "Mage-tastic Gizmonitor" },
				} },
				{ title = "Back to Bink", only = { races = { "Human", "Gnome" } }, when = { { test = "onquest", quests = { 1880 } } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1880, choose = { { item = 7507 }, { item = 9514 } }, note = "Bink: Arcane Orb or Arcane Staff" },
				} },
				{ title = "Belann's wand (optional)", tip = "Belann's quest is open to Human and Gnome mages too, if you ever visit Valanaar on Zephras Isle, the Skyborne home: Anathamaas Aetherwind, the town's mage trainer, sends you to Belann Windwood next door, who wants a Wind-Infused Bough from the ground by the Windstone Formations south of Falaath Village, for the Windbough Wand. It does not shut out the staff or the orb.", only = { races = { "Human", "Gnome" } }, zone = 2521, goals = {
					{ kind = "accept", quest = 93791, npc = 252373, optional = true, note = "Anathamaas Aetherwind" },
					{ kind = "turnin", quest = 93791, optional = true, note = "Belann Windwood" },
					{ kind = "accept", quest = 93797, optional = true },
					{ kind = "collect", quest = 93797, objective = 1, item = 262668, optional = true, note = "Wind-Infused Bough" },
					{ kind = "turnin", quest = 93797, optional = true, rewards = { { item = 263430 } }, note = "Belann Windwood: Windbough Wand" },
				} },
			},
		},
		{
			id = "forever/class/mage/teleports-alliance", title = "Teleports and Portals (Alliance)", category = "Class", folder = "Mage", faction = "Alliance", classes = { "Mage" }, levels = { 20, 50 }, zone = 1453, version = 1, revision = "0b9260eb06b57fb6e52a9e10a7885007723b8150a20626136a92c2fb6e9cb704", keywords = { "Teleport", "Portal", "Teleport: Stormwind", "Teleport: Ironforge", "Teleport: Darnassus", "Portal: Stormwind", "Portal: Ironforge", "Portal: Darnassus", "Larimaine Purdue", "Milstaff Stormeye", "Elissa Dumas", "Portal Trainer", "Rune of Teleportation", "Rune of Portals", "reagent vendor", "Mage", "class spell" }, rewards = { { spell = 3561, name = "Teleport: Stormwind" }, { spell = 3562, name = "Teleport: Ironforge" }, { spell = 3565, name = "Teleport: Darnassus" }, { spell = 10059, name = "Portal: Stormwind" }, { spell = 11416, name = "Portal: Ironforge" }, { spell = 11419, name = "Portal: Darnassus" } }, why = "Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer.",
			steps = {
				{ title = "Teleport: Stormwind", tip = "At 20 go to the Wizard's Sanctum, the violet tower of Stormwind's Mage Quarter. Larimaine Purdue, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches Teleport: Stormwind for 20 silver. Every teleport burns one Rune of Teleportation (10 silver at any reagent vendor; Owen Vaughn sells them at the foot of the tower), so carry a few.", zone = 1453, goals = {
					{ kind = "level", level = 20 },
					{ kind = "money", money = 3000 },
					{ kind = "train", npc = 2485, note = "Larimaine Purdue: Teleport: Stormwind" },
					{ kind = "buy", item = 17031, count = 5, nearest = true, note = "Rune of Teleportation, 10s each" },
				} },
				{ title = "Teleport: Ironforge", tip = "Take the Deeprun Tram from Stormwind's Dwarven District to Ironforge. Milstaff Stormeye, the portal trainer, stands with the mage trainers in the Mystic Ward at the back of the city: Teleport: Ironforge, 20 silver.", zone = 1455, goals = {
					{ kind = "money", money = 2000 },
					{ kind = "train", npc = 2489, note = "Milstaff Stormeye: Teleport: Ironforge" },
				} },
				{ title = "Teleport: Darnassus", tip = "At 30. Take the boat from Stormwind Harbor to Auberdine in Darkshore, then the boat to Rut'theran Village and the pink portal up into Darnassus. Elissa Dumas, the portal trainer, teaches Teleport: Darnassus for 80 silver.", zone = 1457, goals = {
					{ kind = "level", level = 30 },
					{ kind = "money", money = 8000 },
					{ kind = "train", npc = 4165, note = "Elissa Dumas: Teleport: Darnassus" },
				} },
				{ title = "Portals to Stormwind and Ironforge", tip = "At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one Rune of Portals (20 silver at any reagent vendor). Larimaine Purdue has Portal: Stormwind at the top of the Wizard's Sanctum; then the tram to Milstaff Stormeye in Ironforge's Mystic Ward for Portal: Ironforge.", zone = 1453, goals = {
					{ kind = "level", level = 40 },
					{ kind = "money", money = 30000 },
					{ kind = "train", npc = 2485, note = "Larimaine Purdue: Portal: Stormwind" },
					{ kind = "buy", item = 17032, count = 5, nearest = true, note = "Rune of Portals, 20s each" },
					{ kind = "train", npc = 2489, note = "Milstaff Stormeye, Ironforge: Portal: Ironforge" },
				} },
				{ title = "Portal: Darnassus", tip = "At 50 Elissa Dumas in Darnassus teaches the last one, Portal: Darnassus, for 3 gold 20 silver. Use your Teleport: Darnassus to get there.", zone = 1457, goals = {
					{ kind = "level", level = 50 },
					{ kind = "money", money = 32000 },
					{ kind = "train", npc = 4165, note = "Elissa Dumas: Portal: Darnassus" },
				} },
			},
		},
		{
			id = "forever/class/mage/teleports-horde", title = "Teleports and Portals (Horde)", category = "Class", folder = "Mage", faction = "Horde", classes = { "Mage" }, levels = { 20, 50 }, zone = 1454, version = 1, revision = "8213922efc9bfbe884262b27c3213b2ec87129ab515f58406eef901ec0206a4a", keywords = { "Teleport", "Portal", "Teleport: Orgrimmar", "Teleport: Undercity", "Teleport: Thunder Bluff", "Portal: Orgrimmar", "Portal: Undercity", "Portal: Thunder Bluff", "Thuul", "Lexington Mortaim", "Birgitte Cranston", "Portal Trainer", "Rune of Teleportation", "Rune of Portals", "reagent vendor", "Mage", "class spell" }, rewards = { { spell = 3567, name = "Teleport: Orgrimmar" }, { spell = 3563, name = "Teleport: Undercity" }, { spell = 3566, name = "Teleport: Thunder Bluff" }, { spell = 11417, name = "Portal: Orgrimmar" }, { spell = 11418, name = "Portal: Undercity" }, { spell = 11420, name = "Portal: Thunder Bluff" } }, why = "Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer.",
			steps = {
				{ title = "Teleport: Orgrimmar", tip = "At 20 go to Darkbriar Lodge in Orgrimmar's Valley of Spirits, where the mage trainers live. Thuul, the portal trainer, stands on the upper floor and teaches Teleport: Orgrimmar for 20 silver. Every teleport burns one Rune of Teleportation (10 silver at any reagent vendor), so carry a few.", zone = 1454, goals = {
					{ kind = "level", level = 20 },
					{ kind = "money", money = 3000 },
					{ kind = "train", npc = 5958, note = "Thuul: Teleport: Orgrimmar" },
					{ kind = "buy", item = 17031, count = 5, nearest = true, note = "Rune of Teleportation, 10s each" },
				} },
				{ title = "Teleport: Undercity", tip = "Take the zeppelin from the tower outside Orgrimmar's gate to Tirisfal Glades and walk into the Undercity. Lexington Mortaim, the portal trainer, stands in the Magic Quarter with the mage trainers: Teleport: Undercity, 20 silver. Hannah Akeley beside him sells the runes.", zone = 1458, goals = {
					{ kind = "money", money = 2000 },
					{ kind = "train", npc = 2492, note = "Lexington Mortaim: Teleport: Undercity" },
				} },
				{ title = "Teleport: Thunder Bluff", tip = "At 30. Thunder Bluff is in Mulgore: fly there from Orgrimmar or the Crossroads. Birgitte Cranston, the portal trainer, stands with the mage trainers in the Pools of Vision, the cave under Spirit Rise: go down inside, the arrow cannot tell the floors apart. She teaches Teleport: Thunder Bluff for 80 silver.", zone = 1456, goals = {
					{ kind = "level", level = 30 },
					{ kind = "money", money = 8000 },
					{ kind = "train", npc = 5957, note = "Birgitte Cranston: Teleport: Thunder Bluff" },
				} },
				{ title = "Portals to Orgrimmar and the Undercity", tip = "At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one Rune of Portals (20 silver at any reagent vendor). Thuul in Darkbriar Lodge has Portal: Orgrimmar; teleport to the Undercity for Lexington Mortaim's Portal: Undercity.", zone = 1454, goals = {
					{ kind = "level", level = 40 },
					{ kind = "money", money = 30000 },
					{ kind = "train", npc = 5958, note = "Thuul: Portal: Orgrimmar" },
					{ kind = "buy", item = 17032, count = 5, nearest = true, note = "Rune of Portals, 20s each" },
					{ kind = "train", npc = 2492, note = "Lexington Mortaim, Undercity: Portal: Undercity" },
				} },
				{ title = "Portal: Thunder Bluff", tip = "At 50 Birgitte Cranston, down in the Pools of Vision under Spirit Rise in Thunder Bluff, teaches the last one, Portal: Thunder Bluff, for 3 gold 20 silver. Use your Teleport: Thunder Bluff to get there.", zone = 1456, goals = {
					{ kind = "level", level = 50 },
					{ kind = "money", money = 32000 },
					{ kind = "train", npc = 5957, note = "Birgitte Cranston: Portal: Thunder Bluff" },
				} },
			},
		},
		{
			id = "forever/class/paladin/cloak-of-the-divine-storm", title = "Cloak of the Divine Storm", category = "Class", folder = "Paladin", faction = "Alliance", classes = { "Paladin" }, levels = { 22, 30 }, zone = 1439, version = 1, revision = "705f67a54a05a198c033fdd663aa2bf7102654bdf93c44e82ab93a22e0a81dbc", legacyRevision = "9eca83412dcb6fd4dbfdf86b393506dcf64c84fb367c94f79351e7b3172550ab", keywords = { "A Strange Artifact", "Strange Orb", "Althalaxx Orb", "Tower of Althalaxx", "Delgren the Purifier", "Katherine the Pure", "Ursula Deline", "Summoner's Salt", "Mote of Mannoroth", "Spear of Mannoroth", "Demon Fall Canyon", "Divine Storm", "Paladin", "class quest" }, collects = { 277205 }, rewards = { { item = 277205 } }, why = "Starts now at 22 at the Tower of Althalaxx; its mobs are 28-30, so go nearer 30 or with a friend. Alliance only for now.",
			steps = {
				{ title = "The Strange Orb", tip = "Climb to the top of the Tower of Althalaxx in northern Darkshore. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts Shadow Bolt from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the Spear of Mannoroth: three later quests need it.", zone = 1439, goals = {
					{ kind = "level", level = 22 },
					{ kind = "accept", quest = 78088, map = 1439, x = 56.2, y = 26.5, note = "Strange Orb atop the Tower of Althalaxx: right-click the Althalaxx Orb it gives" },
				} },
				{ title = "Delgren the Purifier", tip = "Delgren the Purifier stands at Maestra's Post in western Ashenvale, south of the Darkshore road. He sends you to Stormwind with the orb.", zone = 1440, goals = {
					{ kind = "turnin", quest = 78088, note = "Delgren the Purifier" },
					{ kind = "accept", quest = 78089 },
				} },
				{ title = "Katherine the Pure", tip = "Katherine the Pure stands in the Cathedral of Light; she sends you to a warlock for a second opinion.", zone = 1453, goals = {
					{ kind = "turnin", quest = 78089, note = "Katherine the Pure" },
					{ kind = "accept", quest = 78090 },
				} },
				{ title = "Ursula Deline", tip = "Ursula Deline, the warlock trainer, is in the Mage Quarter's warlock sanctum, down in the Slaughtered Lamb's cellar. She wants 14 Summoner's Salt to read the orb.", zone = 1453, goals = {
					{ kind = "turnin", quest = 78090, note = "Ursula Deline" },
					{ kind = "accept", quest = 78091 },
				} },
				{ title = "Summoner's Salt", tip = "The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the Summoner's Salt; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of Lakeshire drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is Gath'Ilzogg (26): stay in the north-west.", zone = 1433, goals = {
					{ kind = "collect", quest = 78091, objective = 1, item = 209778, map = 1433, x = 23.5, y = 12, frame = "live" },
				} },
				{ title = "Back to Ursula", zone = 1453, goals = {
					{ kind = "turnin", quest = 78091, note = "Ursula Deline" },
					{ kind = "accept", quest = 78092 },
				} },
				{ title = "Motes of Mannoroth", tip = "Demon Fall Canyon is in south-east Ashenvale, east of Splintertree Post (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast Shadow Bolt and Immolate, Infernals keep a fire shield up. They respawn in five minutes.", zone = 1440, goals = {
					{ kind = "collect", quest = 78092, objective = 1, item = 209779 },
				} },
				{ title = "The Spear of Mannoroth", tip = "The Spear of Mannoroth stands at the east end of Demon Fall Canyon. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the Shattered Orb beside it starts the last quest.", zone = 1440, goals = {
					{ kind = "turnin", quest = 78092, note = "Spear of Mannoroth" },
					{ kind = "accept", quest = 78093, note = "from the Shattered Orb" },
				} },
				{ title = "Return to Delgren", tip = "Back to Delgren at Maestra's Post in western Ashenvale, across the whole zone.", zone = 1440, goals = {
					{ kind = "turnin", quest = 78093, note = "Delgren the Purifier: Cloak of the Divine Storm" },
				} },
			},
		},
		{
			id = "forever/class/paladin/holy-mightstone", title = "Holy Mightstone", category = "Class", folder = "Paladin", faction = "Alliance", races = { "Human", "Dwarf" }, classes = { "Paladin" }, levels = { 50, 56 }, zone = 1453, version = 1, revision = "b5f08883b5428ef614a4e1d94ff8dbd295582523ad6a2d4b8a6821cd867113ec", legacyRevision = "6e54057893a3287b14cb290cc891ed4cc453ed10cfbe3efdb713d492109857d4", keywords = { "Chillwind Point", "Dispelling Evil", "Inert Scourgestones", "Forging the Mightstone", "Holy Mightstone", "Commander Ashlam Valorfist", "High Priest Thel'danis", "Lord Grayson Shadowbreaker", "Brandur Ironhammer", "Argent Dawn Commission", "Argent Officer Pureheart", "Minion's Scourgestone", "Voodoo Feather", "Sunken Temple", "Temple of Atal'Hakkar", "Paladin", "class quest" }, collects = { 20620 }, rewards = { { item = 20620 } }, why = "A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever.",
			steps = {
				{ title = "Lord Grayson Shadowbreaker", tip = "At 50 Lord Grayson Shadowbreaker, the paladin trainer in the Cathedral of Light, sends you to Chillwind Camp in the Western Plaguelands. Brandur Ironhammer in Ironforge gives the same quest.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8415, npc = 928, note = "Lord Grayson Shadowbreaker" },
				} },
				{ title = "Brandur Ironhammer", tip = "At 50 Brandur Ironhammer, the paladin trainer in the Mystic Ward, sends you to Chillwind Camp in the Western Plaguelands. Lord Grayson Shadowbreaker in Stormwind gives the same quest.", only = { races = { "Dwarf" } }, zone = 1455, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8415, npc = 5149, note = "Brandur Ironhammer" },
				} },
				{ title = "Chillwind Camp", tip = "Chillwind Camp is the Alliance camp at the south end of the Western Plaguelands, north of the Alterac foothills. Commander Ashlam Valorfist commands it; Argent Officer Pureheart stands in the same camp.", zone = 1422, goals = {
					{ kind = "turnin", quest = 8415, note = "Commander Ashlam Valorfist" },
					{ kind = "accept", quest = 8414 },
				} },
				{ title = "The Argent Dawn Commission", tip = "The Scourge drop no Scourgestones unless you wear an Argent Dawn Commission. Argent Officer Pureheart gives you one through her quest, Argent Dawn Commission, which you hand in straight away (if you already have one from Light's Hope Chapel, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones.", when = { { item = 12846, test = "has", negate = true } }, zone = 1422, goals = {
					{ kind = "accept", quest = 5401, note = "Argent Officer Pureheart: Argent Dawn Commission" },
					{ kind = "turnin", quest = 5401, note = "the Argent Dawn Commission trinket: equip it" },
				} },
				{ title = "Minion's Scourgestones", tip = "Kill the Scourge of the Western Plaguelands with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a Minion's Scourgestone about two kills in five. Sorrow Hill, just east of Chillwind Camp around Uther's Tomb, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast Cone of Cold and Arcane Explosion up close, Dark Summoners run for help at low health.", zone = 1422, goals = {
					{ kind = "collect", quest = 8414, objective = 1, item = 12840, note = "Minion's Scourgestone x20" },
				} },
				{ title = "High Priest Thel'danis", tip = "High Priest Thel'danis keeps watch at Uther's Tomb on Sorrow Hill, east of the camp. He turns your 20 stones into one Inert Scourgestone: keep it.", zone = 1422, goals = {
					{ kind = "turnin", quest = 8414, note = "High Priest Thel'danis" },
					{ kind = "accept", quest = 8416 },
				} },
				{ title = "Commander Ashlam Valorfist", tip = "Back to Chillwind Camp. Ashlam needs the voodoo of the Sunken Temple's trolls for the stone.", zone = 1422, goals = {
					{ kind = "turnin", quest = 8416, note = "Commander Ashlam Valorfist" },
					{ kind = "accept", quest = 8418 },
				} },
				{ title = "The Sunken Temple", tip = "The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears in eastern Swamp of Sorrows: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first.", zone = 1435, goals = {
					{ kind = "goto", label = "The Temple of Atal'Hakkar", map = 1435, x = 69.9, y = 53.6 },
					{ kind = "collect", quest = 8418, objective = 1, item = 20606, map = 1435, x = 69.9, y = 53.6, note = "Amber Voodoo Feather x2: Gasher, Zul'Lor" },
					{ kind = "collect", quest = 8418, objective = 2, item = 20607, map = 1435, x = 69.9, y = 53.6, note = "Blue Voodoo Feather x2: Hukku, Mijan" },
					{ kind = "collect", quest = 8418, objective = 3, item = 20608, map = 1435, x = 69.9, y = 53.6, note = "Green Voodoo Feather x2: Zolo, Loro" },
				} },
				{ title = "Forging the Mightstone", tip = "Back to Ashlam in Chillwind Camp: he forges the Holy Mightstone. Look at the reward window before you hand in: Classic also offered the Chivalrous Signet, the Lightforged Blade or the Sanctified Orb, and Forever's notes say that choice may be gone. Use the stone before a fight against undead (Stratholme, Scholomance): it lasts ten minutes and is gone after one use.", zone = 1422, goals = {
					{ kind = "turnin", quest = 8418, rewards = { { item = 20620 } }, note = "Commander Ashlam Valorfist: Holy Mightstone" },
				} },
			},
		},
		{
			id = "forever/class/paladin/lumina-windsinger", title = "Moonsilver Blade and Wolfsbane (Forsaken)", category = "Class", folder = "Paladin", faction = "Horde", races = { "Scourge" }, classes = { "Paladin" }, levels = { 18, 26 }, zone = 1420, version = 1, revision = "b396f3612f92d72a760d724499548da4e71e0fc79c028ea7301b586a8fe20a00", legacyRevision = "ca137506fb07a4b0a3e26fdec60b48ad4157d14c872b5a110e05fdff0098a902", keywords = { "Lumina Windsinger", "Diplomatic Incident", "Trevan Rol", "Deathguard Baldren", "Fenris Isle", "Fenris Keep", "Fenris Isle Key", "The Windshaper's Wrath", "The Debt", "A Moon-Kissed Blade", "Enchanted Silver Ingot", "Whitestone Oak Lumber", "Seeking the Kor Gem", "Ulric Frostveil", "Purified Kor Gem", "An Underrated Talent", "Ott", "Ott's Masterwork", "Moonsilver Blade", "Old Fire-Eye", "Wolfsbane", "Shadowfang Keep", "Deadmines", "Blackfathom Deeps", "Danitha Morr", "Forsaken Paladin", "class quest", "class weapon" }, rewards = { { item = 268484 }, { item = 267369 } }, why = "The Forsaken paladin's two-handed sword: rescue Lumina Windsinger, gather three parts, slay Old Fire-Eye.",
			steps = {
				{ title = "Danitha Morr", tip = "At 18 Danitha Morr, inside Bandarion Keep on the bluffs north-west of the Solliden Farmstead, sends you south to the Sepulcher in Silverpine Forest.", zone = 1420, goals = {
					{ kind = "level", level = 18 },
					{ kind = "accept", quest = 91858, note = "Danitha Morr" },
				} },
				{ title = "The Sepulcher", tip = "Trevan Rol stands in the lower part of the Sepulcher, below the surface; Deathguard Baldren keeps watch near the town's entrance.", zone = 1421, goals = {
					{ kind = "turnin", quest = 91858, note = "Trevan Rol" },
					{ kind = "accept", quest = 91859 },
					{ kind = "turnin", quest = 91859, note = "Deathguard Baldren" },
					{ kind = "accept", quest = 91860 },
				} },
				{ title = "The pyre on Fenris Isle", tip = "Fenris Isle lies in the lake north-east of the Sepulcher. The gnolls' pyre, with the Charred Remains, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's.", zone = 1421, goals = {
					{ kind = "turnin", quest = 91860, note = "Charred Remains" },
					{ kind = "accept", quest = 91861, note = "from the Charred Remains" },
				} },
				{ title = "Fenris Keep", tip = "Lumina Windsinger is caged in the basement of Fenris Keep, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the Fenris Isle Key (often the first kill); the rare Rot Hide Bruiser (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back.", zone = 1421, goals = {
					{ kind = "turnin", quest = 91861, note = "Lumina Windsinger" },
					{ kind = "accept", quest = 91862 },
					{ kind = "collect", quest = 91862, objective = 1, item = 267412, note = "Fenris Isle Key, from the Rot Hide gnolls" },
				} },
				{ title = "Free Lumina", tip = "Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: Lumina walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the Sepulcher. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage.", zone = 1421, goals = {
					{ kind = "turnin", quest = 91862, note = "Lumina Windsinger" },
					{ kind = "accept", quest = 96204 },
				} },
				{ title = "Back to the Sepulcher", tip = "Lumina waits beside Trevan Rol in the Sepulcher (a different Lumina from the one you escorted). For The Debt, click through every line of her story.", zone = 1421, goals = {
					{ kind = "turnin", quest = 96204, note = "Lumina Windsinger, the Sepulcher" },
					{ kind = "accept", quest = 95034 },
					{ kind = "talk", quest = 95034, objective = 1, npc = 259620, note = "Lumina Windsinger: hear her story to the end" },
					{ kind = "turnin", quest = 95034 },
				} },
				{ title = "A Moon-Kissed Blade", tip = "At 20 Lumina asks for a blade that can kill Old Fire-Eye. Talk to Trevan Rol beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third.", zone = 1421, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 95036, note = "Lumina Windsinger" },
					{ kind = "collect", npc = 248840, item = 267454, note = "Trevan's Weapon Notes: talk to Trevan Rol" },
				} },
				{ title = "The Enchanted Silver Ingot", tip = "Shadowfang Keep is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to Archmage Arugal at the very end. A friend's cleared instance works: walk in and run to the table.", zone = 1421, goals = {
					{ kind = "goto", label = "Shadowfang Keep", map = 1421, x = 44.8, y = 67.8, frame = "live" },
					{ kind = "collect", quest = 95036, objective = 3, item = 267361, map = 1421, x = 44.8, y = 67.8, frame = "live", note = "Enchanted Silver Ingot, on Arugal's table" },
				} },
				{ title = "Whitestone Oak Lumber", tip = "The Deadmines lies under Moonbrook in Westfall, Alliance land: a group of five at about 17-24. From the Undercity take the zeppelin to Grom'gol in Stranglethorn Vale and go north through Duskwood into Westfall. The way in is the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time.", zone = 1436, goals = {
					{ kind = "goto", label = "The Deadmines, in the Moonbrook mine", map = 1436, x = 42.5, y = 71.7, frame = "live" },
					{ kind = "collect", quest = 95036, objective = 2, item = 6994, map = 1436, x = 42.5, y = 71.7, frame = "live", note = "Goblin Woodcarvers, inside" },
				} },
				{ title = "Ulric Frostveil", tip = "Ulric Frostveil waits at Zoram'gar Outpost on Ashenvale's west coast: take the zeppelin from Grom'gol (or the Undercity) to Orgrimmar, then go north through the Barrens into Ashenvale and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take Ulric's quest before you hunt the naga: the Kor Gem only drops while you have it.", zone = 1440, goals = {
					{ kind = "accept", quest = 95042, note = "Ulric Frostveil, Zoram'gar Outpost" },
				} },
				{ title = "The Corrupted Kor Gem", tip = "The naga stand in the flooded ruins and passages around the Blackfathom Deeps entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the Corrupted Kor Gem, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group.", zone = 1440, goals = {
					{ kind = "collect", quest = 95042, objective = 1, item = 6995, note = "Corrupted Kor Gem" },
				} },
				{ title = "The Purified Kor Gem", tip = "Back to Ulric at Zoram'gar: he cleanses the gem. Keep the Purified Kor Gem for Trevan.", zone = 1440, goals = {
					{ kind = "turnin", quest = 95042, rewards = { { item = 272448 } }, note = "Ulric Frostveil: Purified Kor Gem" },
				} },
				{ title = "Trevan Rol", tip = "Bring the lumber, the ingot and the gem to Trevan in the Sepulcher. He gives you a Bundle of Blacksmithing Materials for a smith in Tarren Mill: keep it in your bags.", zone = 1421, goals = {
					{ kind = "turnin", quest = 95036, note = "Trevan Rol" },
					{ kind = "accept", quest = 95111 },
				} },
				{ title = "Ott", tip = "Ott, the weaponsmith, stands just south of Tarren Mill in Hillsbrad Foothills. Accepting Ott's Masterwork starts the forging: step back and wait near him until he is done.", zone = 1424, goals = {
					{ kind = "turnin", quest = 95111, note = "Ott, Tarren Mill" },
					{ kind = "accept", quest = 95125 },
					{ kind = "complete", quest = 95125, note = "Watch Ott forge the blade" },
					{ kind = "turnin", quest = 95125 },
					{ kind = "accept", quest = 95126, note = "Ott gives you Ott's Masterwork" },
				} },
				{ title = "The Moonsilver Blade", tip = "Back to Trevan Rol in the Sepulcher's lower part: he hands you the Moonsilver Blade, a two-handed sword.", zone = 1421, goals = {
					{ kind = "turnin", quest = 95126, rewards = { { item = 268484 } }, note = "Trevan Rol: Moonsilver Blade" },
				} },
				{ title = "Two-Handed Swords", tip = "The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. Archibald, the weapon master in the Undercity's War Quarter, teaches Two-Handed Swords for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level).", zone = 1458, goals = {
					{ kind = "train", npc = 11870, optional = true, note = "Archibald, War Quarter: Two-Handed Swords" },
				} },
				{ title = "Old Fire-Eye", tip = "Equip the Moonsilver Blade. Old Fire-Eye, the great worgen, roams the woods south of the Sepulcher toward the gates of Gilneas. He is elite (level 25): the guide waits for level 22 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke.", zone = 1421, goals = {
					{ kind = "accept", quest = 95140, note = "Lumina Windsinger, the Sepulcher" },
					{ kind = "level", level = 22 },
					{ kind = "kill", quest = 95140, objective = 1, npc = 259897, map = 1421, x = 47.91, y = 85.33, note = "Old Fire-Eye, with the Moonsilver Blade equipped" },
				} },
				{ title = "Wolfsbane", tip = "Back to Lumina in the Sepulcher with the Moonsilver Blade (the quest asks for it): she takes it and blesses it with the magic of her people into Wolfsbane.", zone = 1421, goals = {
					{ kind = "turnin", quest = 95140, rewards = { { item = 267369 } }, note = "Lumina Windsinger: Wolfsbane" },
				} },
			},
		},
		{
			id = "forever/class/paladin/tome-of-divinity", title = "Redemption (Alliance)", category = "Class", folder = "Paladin", faction = "Alliance", races = { "Human", "Dwarf" }, classes = { "Paladin" }, levels = { 12, 14 }, zone = 1453, version = 1, revision = "1dc39b1083fdbc4758d20d72aacb792e77175f9183ef574901069fb45fd2425f", keywords = { "The Tome of Divinity", "Tome of Divinity", "Redemption", "Symbol of Life", "Duthorian Rall", "Stephanie Turner", "Gazin Tenorm", "Henze Faulk", "Defias Script", "Tiza Battleforge", "John Turner", "Muiredon Battleforge", "Narm Faulk", "Dark Iron Script", "Brother Wilhelm", "Azar Stronghammer", "Brandur Ironhammer", "Linen Cloth", "Paladin", "class quest" }, rewards = { { spell = 7328, name = "Redemption" } }, why = "Redemption at 12, the paladin's resurrection: an easy chain through your capital and its home zone.",
			steps = {
				{ title = "The summons (Human)", tip = "At 12 Brother Wilhelm, the paladin trainer in Goldshire, sends you to Duthorian Rall in Stormwind's Cathedral of Light. The errand is optional, a little XP: Brandur Ironhammer in Ironforge gives the same one (taking one closes the other), and Duthorian starts the chain without it.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "level", level = 12 },
					{ kind = "accept", quest = 2998, optional = true, note = "Brother Wilhelm, Goldshire" },
				} },
				{ title = "The summons (Dwarf)", tip = "At 12 Brandur Ironhammer, the paladin trainer in Ironforge's Mystic Ward, sends you upstairs to Tiza Battleforge. The errand is optional, a little XP: Azar Stronghammer in Kharanos and Lord Grayson Shadowbreaker in Stormwind give the same one (taking one closes the others), and Tiza starts the chain without it.", only = { races = { "Dwarf" } }, zone = 1453, goals = {
					{ kind = "level", level = 12 },
					{ kind = "accept", quest = 2999, optional = true, note = "Brandur Ironhammer, Ironforge" },
				} },
				{ title = "Duthorian Rall", only = { races = { "Human" } }, when = { { test = "onquest", quests = { 2998 } } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 2998, note = "Duthorian Rall, Cathedral of Light" },
				} },
				{ title = "Duthorian Rall", only = { races = { "Human" } }, when = { { test = "onquest", quests = { 3681 } } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 3681, note = "Duthorian Rall, Cathedral of Light" },
				} },
				{ title = "The Tome of Divinity", tip = "Duthorian Rall stands inside the Cathedral of Light. He hands you the Tome of Divinity: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask Duthorian for a new copy. Bring 10 Linen Cloth for the next step if you have it.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1641, direct = true, note = "Duthorian Rall" },
					{ kind = "accept", quest = 1642, item = 6775, note = "Right-click the Tome of Divinity" },
					{ kind = "turnin", quest = 1642, note = "Duthorian Rall" },
					{ kind = "accept", quest = 1643 },
				} },
				{ title = "Stephanie Turner", tip = "Stephanie Turner stands at a corner in the middle of the Trade District, outside a general goods store. She wants 10 Linen Cloth: humanoids drop it (Riverpaw gnolls in Westfall about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the Trade District.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1643, note = "Stephanie Turner" },
					{ kind = "accept", quest = 1644 },
					{ kind = "collect", quest = 1644, objective = 1, item = 2589, note = "Linen Cloth x10" },
					{ kind = "turnin", quest = 1644 },
					{ kind = "accept", quest = 1780 },
				} },
				{ title = "The Symbol of Life", tip = "Back to the Cathedral. Duthorian gives you the Symbol of Life; Gazin Tenorm lies wounded by the altar of the same hall. Keep the symbol: you need it on Henze Faulk. If you lose it, Duthorian gives you another (The Symbol of Life).", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1780, note = "Duthorian Rall" },
					{ kind = "accept", quest = 1781 },
					{ kind = "turnin", quest = 1781, note = "Gazin Tenorm" },
					{ kind = "accept", quest = 1786 },
				} },
				{ title = "Henze Faulk", tip = "Henze Faulk lies dead on Heroes' Vigil, the island in Stone Cairn Lake in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the Symbol of Life to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast Frostbolt from far off: they stand apart, so pull one at a time.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "use", quest = 1786, objective = 1, item = 6866, map = 1429, x = 72.6, y = 51.41, note = "Symbol of Life on Henze Faulk's body" },
					{ kind = "turnin", quest = 1786, note = "Henze Faulk" },
					{ kind = "accept", quest = 1787 },
				} },
				{ title = "The Defias Script", tip = "The Defias Rogue Wizards around the big stone tablet east of Henze carry the Defias Script: about one kill in two drops it, but some players need many kills. They respawn in three minutes.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "collect", quest = 1787, objective = 1, item = 6846, map = 1429, x = 74.16, y = 52, note = "Defias Script: Defias Rogue Wizards" },
				} },
				{ title = "Redemption", tip = "Back to the Cathedral of Light: Gazin takes the script, Duthorian teaches you Redemption.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1787, note = "Gazin Tenorm" },
					{ kind = "accept", quest = 1788 },
					{ kind = "turnin", quest = 1788, note = "Duthorian Rall: Redemption" },
				} },
				{ title = "Tiza Battleforge", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 2997 } } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 2997, note = "Tiza Battleforge, upstairs in the Hall of Mysteries" },
				} },
				{ title = "Tiza Battleforge", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 2999 } } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 2999, note = "Tiza Battleforge, upstairs in the Hall of Mysteries" },
				} },
				{ title = "Tiza Battleforge", only = { races = { "Dwarf" } }, when = { { test = "onquest", quests = { 3000 } } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 3000, note = "Tiza Battleforge, upstairs in the Hall of Mysteries" },
				} },
				{ title = "The Tome of Divinity", tip = "Tiza Battleforge stands upstairs in the Hall of Mysteries, in the Mystic Ward: take the ramp at the back of the hall. She hands you the Tome of Divinity: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask Tiza for a new copy. Bring 10 Linen Cloth for the next step if you have it.", only = { races = { "Dwarf" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1645, direct = true, note = "Tiza Battleforge" },
					{ kind = "accept", quest = 1646, item = 6916, note = "Right-click the Tome of Divinity" },
					{ kind = "turnin", quest = 1646, note = "Tiza Battleforge" },
					{ kind = "accept", quest = 1647 },
				} },
				{ title = "John Turner", tip = "John Turner walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 Linen Cloth: humanoids drop it (Kogan Forgestone in Kharanos every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring.", only = { races = { "Dwarf" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1647, note = "John Turner" },
					{ kind = "accept", quest = 1648 },
					{ kind = "collect", quest = 1648, objective = 1, item = 2589, note = "Linen Cloth x10" },
					{ kind = "turnin", quest = 1648 },
					{ kind = "accept", quest = 1778 },
				} },
				{ title = "The Symbol of Life", tip = "Back upstairs in the Hall of Mysteries. Tiza gives you the Symbol of Life; her husband Muiredon Battleforge rests on the same floor. Keep the symbol: you need it on Narm Faulk. If you lose it, Tiza gives you another (The Symbol of Life).", only = { races = { "Dwarf" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1778, note = "Tiza Battleforge" },
					{ kind = "accept", quest = 1779 },
					{ kind = "turnin", quest = 1779, note = "Muiredon Battleforge" },
					{ kind = "accept", quest = 1783 },
				} },
				{ title = "Narm Faulk", tip = "Narm Faulk lies dead in Dun Morogh, not Loch Modan: east past Kharanos, north-east of Ironband's compound, on the smallest of three little hills between Helm's Bed Lake and the Dark Iron camp. Target his body and use the Symbol of Life to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes.", only = { races = { "Dwarf" } }, zone = 1426, goals = {
					{ kind = "use", quest = 1783, objective = 1, item = 6866, map = 1426, x = 78.32, y = 58.09, note = "Symbol of Life on Narm Faulk's body" },
					{ kind = "turnin", quest = 1783, note = "Narm Faulk" },
					{ kind = "accept", quest = 1784 },
				} },
				{ title = "The Dark Iron Script", tip = "The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the Dark Iron Script. They run for help at low health: finish them or step back. They respawn in three minutes.", only = { races = { "Dwarf" } }, zone = 1426, goals = {
					{ kind = "collect", quest = 1784, objective = 1, item = 6847, map = 1426, x = 77.53, y = 61.18, note = "Dark Iron Script: Dark Iron Spies" },
				} },
				{ title = "Redemption", tip = "Back up to the Hall of Mysteries: Muiredon takes the script, Tiza teaches you Redemption.", only = { races = { "Dwarf" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1784, note = "Muiredon Battleforge" },
					{ kind = "accept", quest = 1785 },
					{ kind = "turnin", quest = 1785, note = "Tiza Battleforge: Redemption" },
				} },
			},
		},
		{
			id = "forever/class/paladin/tyrs-watch", title = "Tyr's Watch and Redemption (Forsaken)", category = "Class", folder = "Paladin", faction = "Horde", races = { "Scourge" }, classes = { "Paladin" }, levels = { 1, 13 }, zone = 1420, version = 1, revision = "16f0a4707cb93ade5a8520970bc03764c485c03ef6cc999fe82c0cb900a2be96", legacyRevision = "7a3350aeba0caad0bee3c782690b3003540d8f4ecafce32fb1869950cc547e2f", keywords = { "Tyr's Watch", "Bandarion Keep", "Aramis Hammerhand", "Frightened Paladin", "Coming to Terms", "Continue Your Training", "Shari Stilwell", "Danitha Morr", "Breton Samuels", "Hilda the Breaker", "Ephram Barbaro", "As Above", "So Below", "The One That Got Away", "Shadowvale", "A Lesson in Divinity", "Redemption", "Symbol of Life", "Rudolph Gelhardt", "Forsaken Paladin", "class quest" }, rewards = { { spell = 7328, name = "Redemption" }, { item = 246164, choice = true }, { item = 246165, choice = true }, { item = 246265 } }, why = "Redemption to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin.",
			steps = {
				{ title = "Aramis Hammerhand", tip = "Shadow Priest Sarvis gives you a Consecrated Scroll after The Mindless Ones: read it, then bring it to Aramis Hammerhand by the church. He asks you to heal five Injured Deathguard lying around Deathknell. Holy Light hurts a Forsaken paladin a little each time: watch your health.", when = { { level = 9, test = "level", op = "<" } }, zone = 1420, goals = {
					{ kind = "accept", quest = 98601, note = "Shadow Priest Sarvis" },
					{ kind = "turnin", quest = 98601, note = "Aramis Hammerhand" },
					{ kind = "level", level = 2 },
					{ kind = "accept", quest = 90902 },
					{ kind = "complete", quest = 90902, map = 1420, x = 31.6, y = 65.8, note = "Heal 5 Injured Deathguard with Holy Light" },
					{ kind = "turnin", quest = 90902, note = "Aramis Hammerhand" },
				} },
				{ title = "Coming to Terms", tip = "At 4 Aramis sends you after a Frightened Paladin who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy).", when = { { level = 9, test = "level", op = "<" } }, zone = 1420, goals = {
					{ kind = "level", level = 4 },
					{ kind = "accept", quest = 91208, note = "Aramis Hammerhand" },
					{ kind = "accept", quest = 91209 },
					{ kind = "kill", quest = 91208, objective = 1, npc = 246143, note = "Talk to the Frightened Paladin, then defeat her" },
					{ kind = "turnin", quest = 91208, note = "Aramis Hammerhand" },
				} },
				{ title = "Shari Stilwell", tip = "Follow the road east out of Deathknell to Brill. Shari Stilwell, the paladin trainer, stands in town; she trains you from here on.", when = { { level = 9, test = "level", op = "<" } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 91209, note = "Shari Stilwell, Brill" },
					{ kind = "train", classTrainer = true },
				} },
				{ title = "A Second Home", tip = "At 8 Shari Stilwell in Brill sends you to the order's keep on the west coast. The Tarnished in Shadowvale and the crypt under it hit hard at 8-9: come at 10 or later.", zone = 1420, goals = {
					{ kind = "level", level = 8 },
					{ kind = "accept", quest = 91282, note = "Shari Stilwell, Brill" },
				} },
				{ title = "Bandarion Keep", tip = "{area:16602} stands on the bluffs north-west of the Solliden Farmstead (the road west starts near 29,46). Breton Samuels waits at the gate. Hilda the Breaker, the keep's trainer, and Ephram Barbaro, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after A Righteous Cause from Leonid at the keep, the end of Hadric Harlson's chain that starts south-east of Brill; take their quests when you see them.", zone = 1420, goals = {
					{ kind = "turnin", quest = 91282, note = "Breton Samuels" },
					{ kind = "accept", quest = 91285 },
					{ kind = "accept", quest = 99152, optional = true, note = "Hilda the Breaker: As Above, So Below" },
					{ kind = "accept", quest = 99153, optional = true, note = "Ephram Barbaro: The One That Got Away" },
				} },
				{ title = "Murlocs at the Gates", tip = "The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to Shadowvale.", zone = 1420, goals = {
					{ kind = "kill", quest = 91285, objective = 1, npc = 250283, note = "Vile Fin Attackers x8" },
					{ kind = "kill", quest = 91285, objective = 2, npc = 250282, note = "Vile Fin Seers x8" },
				} },
				{ title = "Touring the Grounds", tip = "Breton gives you a weapon, then sends you round the keep to speak with four of its people: Hilda the Breaker just south of the gate, Ander Solliden, the lookout, who walks the road south-east of the keep, then Jorin Croge and Danitha Morr inside the keep. Pick the conversation option with each.", zone = 1420, goals = {
					{ kind = "turnin", quest = 91285, choose = { { item = 246164 }, { item = 246165 } }, note = "Breton Samuels: Skullthumper or Driftwood Smasher" },
					{ kind = "accept", quest = 91294 },
					{ kind = "talk", quest = 91294, objective = 1, npc = 246389, note = "Hilda the Breaker" },
					{ kind = "talk", quest = 91294, objective = 3, npc = 246394, note = "Ander Solliden" },
					{ kind = "talk", quest = 91294, objective = 2, npc = 246393, note = "Jorin Croge" },
					{ kind = "talk", quest = 91294, objective = 4, npc = 246378, note = "Danitha Morr" },
				} },
				{ title = "Danitha Morr", tip = "Danitha Morr leads the order from inside the keep; Jorin Croge stands beside it. The Tarnished need level 9.", zone = 1420, goals = {
					{ kind = "turnin", quest = 91294, note = "Danitha Morr" },
					{ kind = "level", level = 9 },
					{ kind = "accept", quest = 91317 },
					{ kind = "accept", quest = 91316, note = "Jorin Croge" },
				} },
				{ title = "Shadowvale", tip = "The Tarnished (level 8-9) hold the ruined village of Shadowvale in the Whispering Forest, south-west of the keep. Commander Rudolph Gelhardt (level 10) stands on the upper floor of a house, with Drudges below him: clear the ground floor first.", zone = 1420, goals = {
					{ kind = "kill", quest = 91317, objective = 2, npc = 259434, note = "Tarnished Drudges x8" },
					{ kind = "kill", quest = 91317, objective = 3, npc = 259433, note = "Tarnished Zealots x6" },
					{ kind = "collect", quest = 91317, objective = 1, item = 270435, note = "Rudolph Gelhardt's Head" },
				} },
				{ title = "The crypt under Shadowvale", tip = "The cellar is under the village, not on the surface: the way down is inside a burned-out house, where the arrow points. Twelve Lumber Piles (stacked beams) lie in the cellar, each good for one Sturdy Lumber. Whispering Horror, an elite (level 11-13), sits at the far end: leave it alone.", zone = 1420, goals = {
					{ kind = "collect", quest = 91316, objective = 1, item = 246213, map = 1420, x = 12.9, y = 65.7, note = "Lumber Piles, in the cellar: the way down is here" },
				} },
				{ title = "Hilda's bones", tip = "The Shadowvale Lurchers and Mystics (level 8-10) in the crypt drop the Faintly Glowing Bones: about one in two from Lurchers, more from one kind of Mystic, less from the other.", when = { { test = "onquest", quests = { 99152 } } }, zone = 1420, goals = {
					{ kind = "collect", quest = 99152, objective = 1, item = 286259, map = 1420, x = 9.89, y = 66.36, note = "Faintly Glowing Bones x6" },
				} },
				{ title = "Ephram's crystal", tip = "The Glowing Crystal Fragment, a green crystal, lies on the floor in the left-hand part of the crypt.", when = { { test = "onquest", quests = { 99153 } } }, zone = 1420, goals = {
					{ kind = "collect", quest = 99153, objective = 1, item = 286269, map = 1420, x = 9.8, y = 69.3, note = "Glowing Crystal Fragment" },
				} },
				{ title = "Back to the keep", tip = "Danitha hands you Rudolph Gelhardt's head for Sylvanas: keep it in your bags, it is what you hand in.", zone = 1420, goals = {
					{ kind = "turnin", quest = 91316, choose = { { item = 246265 } }, note = "Jorin Croge: Salvaged Wooden Tower Shield" },
					{ kind = "turnin", quest = 91317, note = "Danitha Morr" },
					{ kind = "accept", quest = 95803 },
				} },
				{ title = "Hilda the Breaker", tip = "Hilda and Ephram wait at the forest's edge south of the gate.", when = { { test = "onquest", quests = { 99152 } } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 99152, note = "Hilda the Breaker" },
				} },
				{ title = "Ephram Barbaro", tip = "Ephram waits at the forest's edge south of the gate, a few steps west of Hilda.", when = { { test = "onquest", quests = { 99153 } } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 99153, note = "Ephram Barbaro" },
				} },
				{ title = "A Lesson in Divinity", tip = "Danitha offers the first Lesson in Divinity at level 12. Bring 10 Linen Cloth if you have it: the Undercity asks for it next.", zone = 1420, goals = {
					{ kind = "level", level = 12 },
					{ kind = "accept", quest = 94427, note = "Danitha Morr" },
				} },
				{ title = "The Undercity", tip = "Walk south from Brill to the Ruins of Lordaeron and down into the Undercity. Lady Sylvanas Windrunner holds court in the Royal Quarter; Tanis Alderwood begs in the Trade Quarter.", zone = 1458, goals = {
					{ kind = "turnin", quest = 95803, note = "Lady Sylvanas Windrunner" },
					{ kind = "turnin", quest = 94427, note = "Tanis Alderwood" },
					{ kind = "accept", quest = 94434 },
				} },
				{ title = "Linen Cloth", tip = "Tanis needs 10 Linen Cloth. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too.", zone = 1420, goals = {
					{ kind = "collect", quest = 94434, objective = 1, item = 2589, note = "Linen Cloth x10" },
				} },
				{ title = "Tanis Alderwood", zone = 1458, goals = {
					{ kind = "turnin", quest = 94434 },
					{ kind = "accept", quest = 94435 },
				} },
				{ title = "The Symbol of Life", tip = "Back to {area:16602}. Danitha gives you the Symbol of Life; Deathguard Billmuth waits downstairs in the keep. If you lose the symbol, Danitha gives you another.", zone = 1420, goals = {
					{ kind = "turnin", quest = 94435, note = "Danitha Morr" },
					{ kind = "accept", quest = 94436 },
					{ kind = "turnin", quest = 94436, note = "Deathguard Billmuth, downstairs" },
					{ kind = "accept", quest = 94438 },
				} },
				{ title = "Deathguard Falgan", tip = "Venomweb Vale is at the far east end of the glades, a long walk. Falgan lies dead among the Scarlet Crusaders there: target his body and use the Symbol of Life, then talk to him at once, as he does not stay alive long. If he is already up (another player), just talk to him; if he died again, raise him again.", zone = 1420, goals = {
					{ kind = "turnin", quest = 94438, note = "Deathguard Falgan" },
					{ kind = "accept", quest = 94440 },
				} },
				{ title = "The Scarlet attack plans", tip = "The Scarlet Zealots (level 8-9), Friars (9-10) and Tarnished around Venomweb Vale carry the attack plans. They run for help at low health and respawn in five minutes.", zone = 1420, goals = {
					{ kind = "collect", quest = 94440, objective = 1, item = 264693, note = "Scarlet Crusade Attack Plans" },
				} },
				{ title = "Redemption", tip = "Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then Danitha, back upstairs in the keep, teaches you Redemption.", zone = 1420, goals = {
					{ kind = "turnin", quest = 94440, note = "Deathguard Billmuth, downstairs" },
					{ kind = "accept", quest = 94441 },
					{ kind = "turnin", quest = 94441, note = "Danitha Morr, back upstairs: Redemption" },
				} },
			},
		},
		{
			id = "forever/class/paladin/verigans-fist", title = "Verigan's Fist", category = "Class", folder = "Paladin", faction = "Alliance", races = { "Human", "Dwarf" }, classes = { "Paladin" }, levels = { 20, 30 }, zone = 1453, version = 1, revision = "f069254d7cf24d9e56e0e91cd1e8feff53f2190b8e30d2a8dd58aeb6df8640a6", legacyRevision = "2c70a87e83e69685f973e278dc4e6d86b3e513d84b0b39253a9b63aee83a2dc7", keywords = { "The Tome of Valor", "The Test of Righteousness", "Verigan's Fist", "Bastion of Stormwind", "Sense Undead", "Duthorian Rall", "Tiza Battleforge", "Daphne Stilwell", "Jordan Stilwell", "Jordan's Weapon Notes", "Bailor Stonehand", "Bailor's Ore Shipment", "Thundris Windweaver", "Seeking the Kor Gem", "Whitestone Oak Lumber", "Jordan's Smithing Hammer", "Mo'grosh", "Deadmines", "Shadowfang Keep", "Blackfathom Deeps", "Paladin", "class weapon" }, collects = { 9607, 6953 }, rewards = { { item = 6953 }, { item = 9607 }, { spell = 5502, name = "Sense Undead" } }, why = "The Alliance paladin's rare two-handed mace for the 20s, with a shield and Sense Undead on the way.",
			steps = {
				{ title = "The Tome of Valor (Ironforge)", tip = "At 20 Tiza Battleforge, upstairs in the Hall of Mysteries in the Mystic Ward, gives you the Tome of Valor. Right-click it: it sends you to Duthorian Rall in Stormwind's Cathedral of Light. Take the Deeprun Tram from Ironforge to Stormwind.", only = { races = { "Dwarf" } }, zone = 1455, goals = {
					{ kind = "level", level = 20 },
					{ kind = "turnin", quest = 1794, direct = true, note = "Tiza Battleforge" },
				} },
				{ title = "The Tome of Valor", tip = "Duthorian Rall stands in the Cathedral of Light. Humans get the Tome of Valor from him. Right-click the book to start its quest and hand it straight back to him.", zone = 1453, goals = {
					{ kind = "level", level = 20 },
					{ kind = "turnin", quest = 1793, direct = true, only = { races = { "Human" } }, note = "Duthorian Rall" },
					{ kind = "accept", quest = 1649, item = 6776, note = "Right-click the Tome of Valor" },
					{ kind = "turnin", quest = 1649, note = "Duthorian Rall" },
					{ kind = "accept", quest = 1650 },
				} },
				{ title = "Daphne Stilwell", tip = "Daphne Stilwell's farmhouse stands on the south-west coast of Westfall, south of Moonbrook: take the path that runs south beside the Deadmines' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or Daphne die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24.", zone = 1436, goals = {
					{ kind = "turnin", quest = 1650, note = "Daphne Stilwell" },
					{ kind = "accept", quest = 1651 },
					{ kind = "complete", quest = 1651, note = "Protect Daphne Stilwell: three waves" },
					{ kind = "turnin", quest = 1651 },
					{ kind = "accept", quest = 1652 },
				} },
				{ title = "Duthorian Rall", tip = "Back to the Cathedral of Light: Duthorian gives you the Bastion of Stormwind shield and teaches you Sense Undead.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1652, rewards = { { item = 9607 } }, note = "Duthorian Rall: Bastion of Stormwind, Sense Undead" },
					{ kind = "accept", quest = 1653 },
				} },
				{ title = "Jordan Stilwell", tip = "Jordan Stilwell works outside the gates of Ironforge, not inside. He gives you Jordan's Weapon Notes: four parts, in any order. Keep the notes.", zone = 1426, goals = {
					{ kind = "turnin", quest = 1653, note = "Jordan Stilwell" },
					{ kind = "accept", quest = 1654 },
				} },
				{ title = "Bailor Stonehand", tip = "Bailor Stonehand is downstairs in the house of Thelsamar that has a tailoring merchant outside. His quest only opens once you hold Jordan's.", zone = 1432, goals = {
					{ kind = "accept", quest = 1655, note = "Bailor Stonehand" },
				} },
				{ title = "Bailor's Ore", tip = "The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east Loch Modan, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one.", zone = 1432, goals = {
					{ kind = "collect", quest = 1655, objective = 1, item = 6992, note = "Bailor's Ore crate" },
				} },
				{ title = "Back to Bailor", tip = "Bailor turns the ore into Jordan's Refined Ore Shipment, the part Jordan wants.", zone = 1432, goals = {
					{ kind = "turnin", quest = 1655, rewards = { { item = 6993 } }, note = "Bailor Stonehand" },
					{ kind = "collect", quest = 1654, objective = 2, item = 6993 },
				} },
				{ title = "Whitestone Oak Lumber", tip = "The Deadmines is a group of five under Moonbrook; the instance portal is at the bottom of the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time.", zone = 1436, goals = {
					{ kind = "goto", label = "The Deadmines, in the Moonbrook mine", map = 1436, x = 42.5, y = 71.7, frame = "live" },
					{ kind = "collect", quest = 1654, objective = 1, item = 6994, map = 1436, x = 42.5, y = 71.7, frame = "live", note = "Goblin Woodcarvers, inside" },
				} },
				{ title = "Jordan's Smithing Hammer", tip = "Shadowfang Keep is a dungeon for a group of five in the low to mid 20s, in southern Silverpine Forest, Horde land: a long trip for the Alliance, through the Wetlands, Arathi and Hillsbrad. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it.", zone = 1421, goals = {
					{ kind = "goto", label = "Shadowfang Keep", map = 1421, x = 44.8, y = 67.8, frame = "live" },
					{ kind = "collect", quest = 1654, objective = 3, item = 6895, map = 1421, x = 44.8, y = 67.8, frame = "live", note = "Jordan's Hammer, inside" },
				} },
				{ title = "Thundris Windweaver", tip = "Thundris Windweaver is in Auberdine. Take his quest before you hunt naga: the Kor Gem never drops without it.", zone = 1439, goals = {
					{ kind = "accept", quest = 1442, note = "Thundris Windweaver" },
				} },
				{ title = "The Corrupted Kor Gem", tip = "The Blackfathom naga in the flooded passages around the Blackfathom Deeps entrance, on Ashenvale's north-west coast, drop the Corrupted Kor Gem: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group.", zone = 1440, goals = {
					{ kind = "collect", quest = 1442, objective = 1, item = 6995 },
				} },
				{ title = "The Purified Kor Gem", tip = "Back to Thundris in Auberdine: he purifies the gem.", zone = 1439, goals = {
					{ kind = "turnin", quest = 1442, rewards = { { item = 7083 } }, note = "Thundris Windweaver" },
					{ kind = "collect", quest = 1654, objective = 4, item = 7083 },
				} },
				{ title = "Verigan's Fist", tip = "Bring the four parts to Jordan Stilwell outside Ironforge. Accept his last quest and wait by him while he forges the mace at his anvil.", zone = 1426, goals = {
					{ kind = "turnin", quest = 1654, note = "Jordan Stilwell" },
					{ kind = "accept", quest = 1806 },
					{ kind = "turnin", quest = 1806, rewards = { { item = 6953 } }, note = "Verigan's Fist" },
				} },
			},
		},
		{
			id = "forever/class/priest/benediction", title = "Benediction and Anathema", category = "Class", folder = "Priest", classes = { "Priest" }, levels = { 60, 60 }, zone = 1423, version = 1, revision = "de4447bc6ff4eae0ecef48702063ca65a2783e1a2e63aa824b8ee0f6228e0c18", legacyRevision = "0d370e042adb534c886b64ea2aee38fe952387c2ac6abd6cb1be5a2a2c8056ea", keywords = { "Benediction", "Anathema", "The Balance of Light and Shadow", "A Warning", "Eris Havenfire", "The Eye of Divinity", "The Eye of Shadow", "Splinter of Nordrassil", "Molten Core", "Majordomo Executus", "Cache of the Firelord", "Lord Kazzak", "epic staff", "class quest" }, collects = { 18608 }, rewards = { { item = 18608 }, { item = 18659 } }, why = "The epic priest staff: the Eye of Divinity from Molten Core, Eris's peasant rescue, then the Eye of Shadow.",
			steps = {
				{ title = "The Eye of Divinity", tip = "The Eye of Divinity comes from the Cache of the Firelord, the chest that appears when Majordomo Executus yields in Molten Core, a 40-player raid (it is in the cache about half the time). Molten Core's portal is at the bottom of Blackrock Depths; once you have done Attunement to the Core (a Core Fragment from beside that portal), Lothos Riftwaker inside Blackrock Mountain ports you straight in. Nothing in this chain starts without the Eye: Eris is invisible until you equip it.", zone = 1428, goals = {
					{ kind = "talk", npc = 14387, optional = true, note = "Lothos Riftwaker: the way into Molten Core once attuned" },
					{ kind = "collect", item = 18646, count = 1, map = 1428, x = 26.4, y = 24.5, group = 40, note = "The Eye of Divinity: Molten Core, through Blackrock Mountain" },
				} },
				{ title = "Eris Havenfire", tip = "Equip The Eye of Divinity, then find Eris Havenfire, a ghost on the hillside in the north-west of the Eastern Plaguelands, west of Stratholme's gate (if she does not show, take the Eye off and put it back on). A Warning is only talk; The Balance of Light and Shadow starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or Nightfin Soup, and a stack of Oil of Immolation or Stratholme Holy Water for the skeletons.", zone = 1423, goals = {
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 7621, note = "Eris Havenfire" },
					{ kind = "turnin", quest = 7621 },
					{ kind = "accept", quest = 7622 },
				} },
				{ title = "The Balance of Light and Shadow", tip = "Save 50 peasants before 15 die (the Death Post by the path counts the dead). They walk from the cave towards Eris in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first (Abolish Disease), keep Renew on the hurt ones, Flash Heal the nearly dead, and kill skeletons as they spawn: one Holy Nova of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and Eris is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back.", zone = 1423, goals = {
					{ kind = "complete", quest = 7622 },
				} },
				{ title = "Benediction", zone = 1423, goals = {
					{ kind = "turnin", quest = 7622, rewards = { { item = 18659 } }, note = "Eris Havenfire: Splinter of Nordrassil" },
				} },
				{ title = "The Eye of Shadow", tip = "The splinter needs The Eye of Shadow as well. Lord Kazzak, a world boss in the Blasted Lands (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first.", zone = 1419, goals = {
					{ kind = "collect", item = 18665, count = 1, note = "The Eye of Shadow" },
				} },
				{ title = "Benediction", tip = "With the Splinter of Nordrassil, The Eye of Divinity and The Eye of Shadow in your bags, use the splinter wherever you are: it becomes Benediction. Use Benediction to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown).", zone = 1419, goals = {
					{ kind = "task", text = "Use the Splinter of Nordrassil with both Eyes in your bags: Benediction" },
				} },
			},
		},
		{
			id = "forever/class/priest/blood-of-morphaz", title = "Blood of Morphaz", category = "Class", folder = "Priest", classes = { "Priest" }, levels = { 50, 52 }, zone = 1447, version = 1, revision = "a267023bd6503ad1789b7863799d5b2b5454d5bc4530276ca780faa764f83440", legacyRevision = "fb398190748132719c0b4b89676500c13da9bdb2b1ec476bcf73d521c698212d", keywords = { "Cenarion Aid", "Of Coursers We Know", "The Ichor of Undeath", "Blood of Morphaz", "Ogtinc", "Greta Mosshoof", "Morphaz", "Hazzas", "Sunken Temple", "Temple of Atal'Hakkar", "Healthy Courser Gland", "Ichor of Undeath", "Blessed Prayer Beads", "Circle of Hope", "Woestave", "class quest" }, rewards = { { text = "17,060 experience and 1 gold 55 silver" } }, why = "17,060 XP and 1g55s at 50: Azshara, then Morphaz in the Sunken Temple (group of 5). The item choice may be gone.",
			steps = {
				{ title = "Cenarion Aid: High Priest Rohan", tip = "At 50 in Ironforge, High Priest Rohan in the Hall of Mysteries (Mystic Ward) offers Cenarion Aid. Before you leave a city, buy an Ichor of Undeath at the Auction House (a few silver): the third quest asks for one and it drops rarely.", only = { factions = { "Alliance" } }, when = { { name = "Ironforge", test = "zone" }, { test = "onquest", quests = { 8254 }, negate = true } }, zone = 1455, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8254, npc = 11406, note = "High Priest Rohan" },
				} },
				{ title = "Cenarion Aid: Brother Joshua", tip = "At 50, Brother Joshua at the altar of Stormwind's Cathedral of Light offers Cenarion Aid (High Priest Rohan in Ironforge has it too). Before you leave, buy an Ichor of Undeath at the Auction House in the Trade District (a few silver): the third quest asks for one and it drops rarely.", only = { factions = { "Alliance" } }, when = { { test = "onquest", quests = { 8254 }, negate = true } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8254, npc = 5489, note = "Brother Joshua" },
				} },
				{ title = "Cenarion Aid: Ur'kyo", tip = "At 50, Ur'kyo in Orgrimmar's Valley of Spirits offers Cenarion Aid. Before you leave, buy an Ichor of Undeath at the Auction House (a few silver): the third quest asks for one and it drops rarely.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8254, npc = 6018, note = "Ur'kyo" },
				} },
				{ title = "Ogtinc", tip = "Ogtinc, a furbolg, lives on the clifftop north-east of the Ruins of Eldarath. Alliance: fly to Talrendis Point; Horde: fly to Valormok. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up.", zone = 1447, goals = {
					{ kind = "getfp", place = "Talrendis Point", only = { factions = { "Alliance" } } },
					{ kind = "getfp", place = "Valormok", only = { factions = { "Horde" } } },
					{ kind = "turnin", quest = 8254, note = "Ogtinc" },
					{ kind = "accept", quest = 8255 },
				} },
				{ title = "Of Coursers We Know", tip = "Mosshoof Coursers (level 52-53, not elite) graze all over Azshara, thickest north-east of Ogtinc and south of the mountains; about one in three drops a Healthy Courser Gland, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any Ichor of Undeath you loot.", zone = 1447, goals = {
					{ kind = "collect", quest = 8255, objective = 1, item = 20027, count = 4, note = "Healthy Courser Gland" },
				} },
				{ title = "Ogtinc", zone = 1447, goals = {
					{ kind = "turnin", quest = 8255, note = "Ogtinc" },
					{ kind = "accept", quest = 8256 },
				} },
				{ title = "The Ichor of Undeath", tip = "Carrying an Ichor of Undeath already? It counts at once. Otherwise any undead may drop one, rarely: the Lingering Highborne (level 48) in the Ruins of Eldarath below Ogtinc's cliff drop it about one kill in ten, the highborne ghosts on Azshara's border with Ashenvale (level 45-46) a little less, the Anguished and Suffering Highborne in Winterspring (54-55) about one in eight. The Auction House is usually quicker.", zone = 1447, goals = {
					{ kind = "collect", quest = 8256, objective = 1, item = 7972, note = "Ichor of Undeath" },
				} },
				{ title = "Ogtinc", zone = 1447, goals = {
					{ kind = "turnin", quest = 8256, note = "Ogtinc" },
					{ kind = "accept", quest = 8257 },
				} },
				{ title = "Morphaz in the Sunken Temple", tip = "Morphaz is a level 52 elite green dragon inside the Sunken Temple, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to Stonard; Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north. The temple stands in the middle of the Pool of Tears: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then Jammal'an the Prophet below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops.", zone = 1435, goals = {
					{ kind = "collect", quest = 8257, objective = 1, item = 20025, map = 1435, x = 69, y = 54, group = 5, note = "Blood of Morphaz: the Sunken Temple entrance" },
				} },
				{ title = "Greta Mosshoof", tip = "Greta Mosshoof is at the Emerald Sanctuary in southern Felwood. Horde: fly to Bloodvenom Post and ride south-east; Alliance: fly to Astranaar in Ashenvale and ride north into Felwood. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick Blessed Prayer Beads, Circle of Hope or Woestave, and Forever's notes say that choice may be gone.", zone = 1448, goals = {
					{ kind = "turnin", quest = 8257, note = "Greta Mosshoof" },
				} },
			},
		},
		{
			id = "forever/class/priest/confounding-flash-and-contingency-plan", title = "Confounding Flash and Contingency Plan", category = "Class", folder = "Priest", faction = "Alliance", races = { "Gnome" }, classes = { "Priest" }, levels = { 10, 20 }, zone = 1455, version = 1, revision = "0c110bba5779237f65333b79b02df4394ad646eb619143cadc569334c9840866", legacyRevision = "80a9a18cb9d06488c4144897c431cb22fb8870aecf2fe9f42c841e1d948daae6", keywords = { "Confounding Flash", "Contingency Plan", "High Priestess Mims", "Maxan Anvol", "Priestess Josetta", "High Priestess Laurena", "Hall of Mysteries", "Mystic Ward", "Gnome", "racial", "Priest" }, rewards = { { spell = 1277455, name = "Confounding Flash" }, { spell = 1277462, name = "Contingency Plan" } }, why = "The Gnome priest spells, new in Forever: Confounding Flash at 10, Contingency Plan at 20. Free, no objectives.",
			steps = {
				{ title = "Confounding Flash: Maxan Anvol", tip = "At 10, Maxan Anvol, the priest trainer inside the Thunderbrew Distillery in Kharanos, hands you a Confounding Flash letter for High Priestess Mims in Ironforge. Kharanos is on the road up to the city.", when = { { name = "Dun Morogh", test = "zone" }, { test = "onquest", quests = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 }, negate = true } }, zone = 1426, goals = {
					{ kind = "level", level = 10 },
