			id = "forever/class/priest/priest-robes-alliance", title = "Priest Robes at 5 (Alliance)", category = "Class", folder = "Priest", faction = "Alliance", races = { "Human", "Dwarf", "Gnome", "NightElf" }, classes = { "Priest" }, levels = { 5, 6 }, zone = 1429, version = 1, revision = "e89f95be7a0837226c0fedf5a18613d57c2a00e096a0fe634608507edbb8f77d", keywords = { "Garments of the Light", "Garments of the Moon", "In Favor of the Light", "In Favor of Elune", "Friar's Robes of the Light", "Moon Robes of Elune", "Guard Roberts", "Mountaineer Dolf", "Sentinel Shaya", "Lesser Heal", "Power Word: Fortitude", "robe", "Priest" }, rewards = { { item = 16605 }, { item = 16604 } }, why = "A free uncommon robe at 5: heal and fortify a wounded guard near your first town.",
			steps = {
				{ title = "In Favor of the Light", tip = "At 5, Priestess Anetta, the priest trainer inside Northshire Abbey, sends you to Priestess Josetta in Goldshire. Train Lesser Heal (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "level", level = 5 },
					{ kind = "accept", quest = 5623, note = "Priestess Anetta" },
				} },
				{ title = "Priestess Josetta", tip = "Follow the road south out of Northshire Valley to Goldshire. Priestess Josetta is upstairs in the Lion's Pride Inn.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "turnin", quest = 5623, note = "Priestess Josetta" },
					{ kind = "accept", quest = 5624 },
					{ kind = "train", classTrainer = true, note = "Lesser Heal (Rank 2), if Anetta did not teach it yet" },
				} },
				{ title = "Guard Roberts", tip = "Guard Roberts kneels by a tree on the lake shore east of Goldshire, off the road: walk along the shore, the minimap misses him from the road. Cast Lesser Heal (Rank 2) on him first, then Power Word: Fortitude. Rank 1 of Lesser Heal does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "kill", quest = 5624, objective = 1, npc = 12423, text = "Heal and fortify Guard Roberts" },
				} },
				{ title = "Priestess Josetta", tip = "Back upstairs in the Lion's Pride Inn: Josetta gives you Friar's Robes of the Light.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "turnin", quest = 5624, rewards = { { item = 16605 } }, note = "Priestess Josetta" },
				} },
				{ title = "In Favor of the Light", tip = "At 5, Branstock Khalder, the priest trainer inside Anvilmar in Coldridge Valley, sends you to Maxan Anvol in Kharanos. Train Lesser Heal (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "level", level = 5 },
					{ kind = "accept", quest = 5626, note = "Branstock Khalder" },
				} },
				{ title = "Maxan Anvol", tip = "Take the tunnel north-east out of Coldridge Valley and follow the road east to Kharanos. Maxan Anvol is inside the Thunderbrew Distillery.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "turnin", quest = 5626, note = "Maxan Anvol" },
					{ kind = "accept", quest = 5625 },
					{ kind = "train", classTrainer = true, note = "Lesser Heal (Rank 2), if Branstock did not teach it yet" },
				} },
				{ title = "Mountaineer Dolf", tip = "Mountaineer Dolf kneels on a ridge between two low walls just south of Kharanos, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast Lesser Heal (Rank 2) on him first, then Power Word: Fortitude; he speaks after each spell. Rank 1 of Lesser Heal does not count.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "kill", quest = 5625, objective = 1, npc = 12427, text = "Heal and fortify Mountaineer Dolf" },
				} },
				{ title = "Maxan Anvol", tip = "Back inside the Thunderbrew Distillery: Maxan gives you Friar's Robes of the Light.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "turnin", quest = 5625, rewards = { { item = 16605 } }, note = "Maxan Anvol" },
				} },
				{ title = "In Favor of Elune", tip = "At 5, Shanda, the priest trainer on the second level of Aldrassil, the great tree in Shadowglen, sends you to Laurna Morninglight in Dolanaar. Train Lesser Heal (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "level", level = 5 },
					{ kind = "accept", quest = 5622, note = "Shanda" },
				} },
				{ title = "Laurna Morninglight", tip = "Leave Shadowglen by the ramp and follow the road south-west to Dolanaar. Laurna Morninglight is in the building at the north edge of the village.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "turnin", quest = 5622, note = "Laurna Morninglight" },
					{ kind = "accept", quest = 5621 },
					{ kind = "train", classTrainer = true, note = "Lesser Heal (Rank 2), if Shanda did not teach it yet" },
				} },
				{ title = "Sentinel Shaya", tip = "Sentinel Shaya kneels on the rocks at the edge of Lake Al'Ameth, about 100 yards south of Dolanaar, with no quest mark over her. Cast Lesser Heal (Rank 2) on her first, then Power Word: Fortitude; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of Lesser Heal does not count.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "kill", quest = 5621, objective = 1, npc = 12429, text = "Heal and fortify Sentinel Shaya" },
				} },
				{ title = "Laurna Morninglight", tip = "Back at the north edge of Dolanaar: Laurna gives you the Moon Robes of Elune.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "turnin", quest = 5621, rewards = { { item = 16604 } }, note = "Laurna Morninglight" },
				} },
