					{ kind = "talk", npc = 11406, note = "High Priest Rohan: take his Elune's Grace letter" },
				} },
				{ title = "Elune's Grace: Priestess Alathea", tip = "At 20, Priestess Alathea on the upper balcony of the Temple of the Moon, beside Tyrande Whisperwind, teaches Elune's Grace with a quest she gives and takes back at once. In Forever, Elune's Grace halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss.", when = { { test = "onquest", quests = { 5672, 5673, 5674, 5675 }, negate = true } }, zone = 1457, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 5672, note = "Priestess Alathea" },
					{ kind = "turnin", quest = 5672, note = "Priestess Alathea: Elune's Grace" },
				} },
				{ title = "Elune's Grace: Laurena's letter", tip = "Hand Laurena's letter to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", when = { { test = "onquest", quests = { 5673 } } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 5673, note = "Priestess Alathea: Elune's Grace" },
				} },
				{ title = "Elune's Grace: Nara's letter", tip = "Hand Nara's letter to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", when = { { test = "onquest", quests = { 5674 } } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 5674, note = "Priestess Alathea: Elune's Grace" },
				} },
				{ title = "Elune's Grace: Rohan's letter", tip = "Hand Rohan's letter to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", when = { { test = "onquest", quests = { 5675 } } }, zone = 1457, goals = {
