				{ title = "Touch of Weakness: Miles Welsh", tip = "At 10 in Thunder Bluff, Miles Welsh, the priest trainer in the cave under Spirit Rise, hands you a Touch of Weakness letter for Aelthalyste in the Undercity.", when = { { name = "Thunder Bluff", test = "zone" }, { test = "onquest", quests = { 5658, 5660, 5661, 5662, 5663 }, negate = true } }, zone = 1456, goals = {
					{ kind = "level", level = 10 },
					{ kind = "talk", npc = 3044, note = "Miles Welsh: take his Touch of Weakness letter" },
				} },
				{ title = "Touch of Weakness: Aelthalyste", tip = "At 10, go to Aelthalyste, the priest trainer in the Undercity's War Quarter: she gives Touch of Weakness and takes it back at once. No letter needed. From Brill, follow the road south to the ruined city of Lordaeron; the Undercity's lifts are at the back of the throne room. Touch of Weakness strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes.", when = { { test = "onquest", quests = { 5658, 5660, 5661, 5662, 5663 }, negate = true } }, zone = 1458, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 5658, note = "Aelthalyste" },
					{ kind = "turnin", quest = 5658, note = "Aelthalyste: Touch of Weakness" },
				} },
				{ title = "Touch of Weakness: Tai'jin's letter", tip = "Hand the letter to Aelthalyste in the Undercity's War Quarter: the zeppelin from the tower outside Orgrimmar lands in Tirisfal Glades, a short walk from the Undercity.", when = { { test = "onquest", quests = { 5660 } } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 5660, note = "Aelthalyste: Touch of Weakness" },
