				{ title = "Dark Sacrifice: Ur'kyo", tip = "At 20 in Orgrimmar, Ur'kyo in the Valley of Spirits hands you a Dark Sacrifice letter for Aelthalyste in the Undercity.", when = { { name = "Orgrimmar", test = "zone" }, { test = "onquest", quests = { 5679, 5644, 5646 }, negate = true } }, zone = 1454, goals = {
