		{
			id = "forever/class/rogue/blade-of-cunning-alliance", title = "Blade of Cunning (Alliance)", category = "Class", folder = "Rogue", faction = "Alliance", classes = { "Rogue" }, levels = { 10, 12 }, zone = 1429, version = 1, revision = "74cc2aba735c87d6ab99d2722a56320125d5593cd34f6de667cae045df70d21a", legacyRevision = "c47e6e8dc8d1318f77c42a9c5060d77a886b7764e559af86f7be9035283ccb4c", keywords = { "Blade of Cunning", "Keryn Sylvius", "Seek out SI: 7", "Snatch and Grab", "Mathias Shaw", "Defias Dockmaster", "Hogral Bakkan", "Road to Salvation", "Simple Subterfugin'", "Onin's Report", "Hulfdan Blackbeard", "Onin MacHammar", "Jannok Breezesong", "The Apple Falls", "Destiny Calls", "Syurna", "Sethir the Ancient", "Rogue", "class weapon" }, rewards = { { item = 7298 } }, why = "A dagger at 10 from your home town's rogue quests.",
			steps = {
				{ title = "Seek out SI: 7", tip = "At 10 Keryn Sylvius, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, gives you a package for Master Mathias Shaw in Stormwind. Train Pick Pocket if you lack it: this chain needs it.", only = { races = { "Human", "Skyborne" } }, zone = 1429, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 2205, note = "Keryn Sylvius" },
				} },
				{ title = "Master Mathias Shaw", tip = "Head north to Stormwind. Shaw stands upstairs in the SI:7 building in Old Town (the quest says the Barracks; it means SI:7).", only = { races = { "Human", "Skyborne" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 2205, note = "Master Mathias Shaw" },
					{ kind = "accept", quest = 2206 },
				} },
				{ title = "Defias Dockmaster", tip = "The Defias Dockmaster (level 10, a goblin) works in the dock house at Jerod's Landing, on the river at Elwynn's southern edge, south of Goldshire. Stealth in and Pick Pocket him from behind: the schedule never drops from his corpse. Do not open with Sap or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death.", only = { races = { "Human", "Skyborne" } }, zone = 1429, goals = {
					{ kind = "collect", quest = 2206, objective = 1, item = 7675, text = "Pick Pocket the Defias Dockmaster for the Defias Shipping Schedule" },
				} },
				{ title = "Back to Mathias Shaw", only = { races = { "Human", "Skyborne" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 2206, rewards = { { item = 7298 } }, note = "Master Mathias Shaw, SI:7" },
				} },
				{ title = "Road to Salvation", tip = "At 10 Hogral Bakkan, the rogue trainer in the Thunderbrew Distillery in Kharanos, sends you to Hulfdan Blackbeard in Ironforge.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 2218, note = "Hogral Bakkan" },
				} },
				{ title = "Hulfdan Blackbeard", tip = "Hulfdan Blackbeard is in the Forlorn Cavern, the rogue quarter in the north of Ironforge: go into the building with a shady dealer outside and down the stairs.", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 2218, note = "Hulfdan Blackbeard" },
					{ kind = "accept", quest = 2238 },
				} },
				{ title = "Onin MacHammar", tip = "Head west to Gnomeregan. Beside the road to its entrance stands a wooden spiral tower: Onin waits stealthed on the top platform, next to a level 10 Leper Gnome, so you only see him up close.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "turnin", quest = 2238, note = "Onin MacHammar" },
					{ kind = "accept", quest = 2239 },
				} },
				{ title = "Back to Hulfdan", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 2239, rewards = { { item = 7298 } }, note = "Hulfdan Blackbeard, Ironforge" },
				} },
				{ title = "The Apple Falls", tip = "At 10 Jannok Breezesong, the rogue trainer in the Dolanaar inn, gives you a rose for Syurna in Darnassus. If you lose the rose, abandon the quest and take it again.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 2241, note = "Jannok Breezesong" },
				} },
				{ title = "Syurna", tip = "Head west to Darnassus. Syurna is below ground in the Cenarion Enclave: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 2241, note = "Syurna" },
					{ kind = "accept", quest = 2242 },
				} },
				{ title = "Sethir the Ancient", tip = "Sethir the Ancient (level 12 satyr) lives out on a great branch north of the Oracle Glade: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then Sprint away. He is back 8 1/2 minutes after a death.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "collect", quest = 2242, objective = 1, item = 7737, text = "Pick Pocket Sethir the Ancient for Sethir's Journal" },
				} },
				{ title = "Back to Syurna", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 2242, rewards = { { item = 7298 } }, note = "Syurna, Darnassus" },
				} },
			},
		},
		{
			id = "forever/class/rogue/blade-of-cunning-horde", title = "Blade of Cunning (Horde)", category = "Class", folder = "Rogue", faction = "Horde", classes = { "Rogue" }, levels = { 10, 13 }, zone = 1411, version = 1, revision = "54bbab504c9f9151f0133e0255df18fa41e04ce347affd9dc92a067a98f8583c", legacyRevision = "e92d2db12b24dea48aa953481227aca24596a399066f985b2f8a976863e253ac", keywords = { "Blade of Cunning", "Kaplak", "Therzok", "The Shattered Hand", "Tazan", "Tazan's Satchel", "Tazan's Key", "Gamon", "Marion Call", "Mennet Carkad", "The Deathstalkers", "Astor Hadren", "Andron Gant", "Andron's Ledger", "Varimathras", "Rogue", "class weapon" }, rewards = { { item = 7298 } }, why = "A dagger at 10 from your home town's rogue quests.",
			steps = {
				{ title = "Therzok", tip = "At 10 Kaplak, the rogue trainer in Razor Hill, sends you to Therzok in Orgrimmar. It is only a pointer: an Orc already in Orgrimmar can skip it and take The Shattered Hand from Therzok straight away.", only = { races = { "Orc" } }, zone = 1411, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1859, note = "Kaplak" },
				} },
				{ title = "The Shattered Hand", tip = "Therzok stands in the Cleft of Shadow, the canyon under the Valley of Strength. Trolls: take The Shattered Hand from him at 10.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 10 },
					{ kind = "turnin", quest = 1859, only = { races = { "Orc" } }, note = "Therzok" },
					{ kind = "accept", quest = 1963 },
				} },
				{ title = "Tazan", tip = "Tazan (level 13, not elite) is a troll pirate on the Merchant Coast south of Ratchet: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again.", only = { races = { "Orc", "Troll" } }, zone = 1413, goals = {
					{ kind = "collect", quest = 1963, objective = 1, item = 7209, note = "Tazan's Satchel: Tazan" },
				} },
				{ title = "Back to Therzok", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "turnin", quest = 1963, note = "Therzok, Cleft of Shadow" },
					{ kind = "accept", quest = 1858 },
				} },
				{ title = "Tazan's Key", tip = "Therzok hands the satchel back: now open it. Gamon (level 12) kneels by the innkeeper in the inn in the Valley of Strength; stealth up and pick his pocket for Tazan's Key (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on Tazan's Satchel in your bags. If you have trained Pick Lock, you can pick the satchel's lock instead.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "collect", item = 7208, count = 1, text = "Pick Pocket Gamon for Tazan's Key" },
					{ kind = "use", quest = 1858, objective = 1, item = 7209, map = 1454, x = 54, y = 68, note = "Tazan's Satchel, once you have the key" },
					{ kind = "collect", quest = 1858, objective = 1, item = 7295, map = 1454, x = 54, y = 68, note = "Tazan's Logbook, from the satchel" },
				} },
				{ title = "Therzok's reward", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "turnin", quest = 1858, rewards = { { item = 7298 } }, note = "Therzok, Cleft of Shadow" },
				} },
				{ title = "Mennet Carkad", tip = "At 10 Marion Call, the rogue trainer upstairs in the Gallows' End Tavern in Brill, sends you to Mennet Carkad in the Undercity.", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1885, note = "Marion Call" },
				} },
				{ title = "The Rogues' Quarter", tip = "Mennet Carkad stands in the Rogues' Quarter.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1885, note = "Mennet Carkad" },
					{ kind = "accept", quest = 1886 },
				} },
				{ title = "Astor Hadren", tip = "Astor Hadren (level 13) walks the road between the Sepulcher and the Undercity, north of the Sepulcher. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death.", only = { races = { "Scourge" } }, zone = 1421, goals = {
					{ kind = "collect", quest = 1886, objective = 1, item = 7231, note = "Astor's Letter of Introduction: Astor Hadren" },
				} },
				{ title = "Back to Mennet Carkad", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1886, note = "Mennet Carkad, Rogues' Quarter" },
					{ kind = "accept", quest = 1898 },
				} },
				{ title = "Andron Gant", tip = "Andron Gant is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1898, note = "Andron Gant" },
					{ kind = "accept", quest = 1899 },
					{ kind = "collect", quest = 1899, objective = 1, item = 7294, note = "Andron's Ledger: Andron's Bookshelf" },
				} },
				{ title = "Mennet and Varimathras", tip = "Mennet sends the ledger on to Varimathras, the big demon in the middle of the Hall of the Dark Lady in the Royal Quarter, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from Andron's bookshelf.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1899, note = "Mennet Carkad, Rogues' Quarter" },
					{ kind = "accept", quest = 1978 },
					{ kind = "turnin", quest = 1978, rewards = { { item = 7298 } }, note = "Varimathras, Royal Quarter" },
				} },
			},
		},
		{
			id = "forever/class/rogue/certificate-of-thievery", title = "Certificate of Thievery", category = "Class", folder = "Rogue", faction = "Alliance", classes = { "Rogue" }, levels = { 16, 20 }, zone = 1453, version = 1, revision = "831a9d2d03a689c51a6dfb16e28f9e52aef810ef29c0b29fcbff2d6de3ba322f", legacyRevision = "ad7fe2f1c5dd8f6a79cf59547757006b8fe8fa845d6508ee1cb8cc644401447d", keywords = { "Certificate of Thievery", "Lockpicking", "Pick Lock", "Thieves' Tools", "Renzik The Shiv", "Redridge Rendezvous", "Lucius", "Alther's Mill", "Lucius's Lockbox", "Practice Lockbox", "Token of Thievery", "Erion Shadewhisper", "Erion's Behest", "To Hulfdan!", "Kingly Shakedown", "SI:7", "Lakeshire", "Rogue", "lockpicking quest" }, rewards = { { item = 7907 } }, why = "Your first lockpicking job at 16: Lucius's lockbox at Alther's Mill, for SI:7.",
			steps = {
				{ title = "SI:7 (Goldshire)", tip = "At 16 Keryn Sylvius, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, sends you to Renzik \"The Shiv\" in Stormwind. Taking it shuts out the other towns' breadcrumbs.", only = { races = { "Human", "Skyborne" } }, zone = 1429, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 2300, note = "Keryn Sylvius" },
				} },
				{ title = "To Hulfdan! (Kharanos)", tip = "At 16 Hogral Bakkan in the Thunderbrew Distillery in Kharanos sends you to Hulfdan Blackbeard in Ironforge's Forlorn Cavern.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 2299, note = "Hogral Bakkan" },
				} },
				{ title = "Hulfdan Blackbeard", tip = "Hulfdan is in the house with a shady dealer outside, in the Forlorn Cavern, down the stairs. Then fly or take the Deeprun Tram to Stormwind.", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 2299, note = "Hulfdan Blackbeard" },
					{ kind = "accept", quest = 2298 },
				} },
				{ title = "Erion Shadewhisper (Dolanaar)", tip = "At 16 Jannok Breezesong in the Dolanaar inn sends you to Erion Shadewhisper in Darnassus.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 2259, note = "Jannok Breezesong" },
				} },
				{ title = "Erion Shadewhisper", tip = "Erion stands in the Cenarion Enclave. Then the boat from Rut'theran Village to Auberdine, and the boat from Auberdine to Stormwind Harbor.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 2259, note = "Erion Shadewhisper, Darnassus" },
					{ kind = "accept", quest = 2260 },
				} },
				{ title = "Renzik \"The Shiv\"", tip = "Renzik stands upstairs in the SI:7 building in Old Town, behind the rogue trainers. Before you leave: if you lack Pick Lock, Lord Tony Romano in the SI:7 building teaches it; Lockpicking is the test of the next quest.", zone = 1453, goals = {
					{ kind = "turnin", quest = 2300, only = { races = { "Human", "Skyborne" } }, note = "Renzik \"The Shiv\"" },
					{ kind = "turnin", quest = 2298, only = { races = { "Dwarf", "Gnome" } } },
					{ kind = "turnin", quest = 2260, only = { races = { "NightElf" } } },
					{ kind = "accept", quest = 2281 },
				} },
				{ title = "Lucius", tip = "Head east through Elwynn Forest into Redridge, or fly to Lakeshire. Lucius stands on a crate on one of the Lakeshire docks, south of town; he gives you Thieves' Tools with the job (Gerald Crawley in Lakeshire sells more). Pick Lock does not work without the tools in your bags.", zone = 1433, goals = {
					{ kind = "turnin", quest = 2281, note = "Lucius" },
					{ kind = "accept", quest = 2282 },
				} },
				{ title = "Alther's Mill", tip = "Alther's Mill stands east of Lakeshire, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until Lucius's Lockbox opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75.", zone = 1433, goals = {
					{ kind = "collect", quest = 2282, objective = 1, item = 7871, note = "Token of Thievery: Lucius's Lockbox" },
				} },
				{ title = "Back to Lucius", zone = 1433, goals = {
					{ kind = "turnin", quest = 2282, rewards = { { item = 7907 } }, note = "Lucius: Certificate of Thievery" },
				} },
			},
		},
		{
			id = "forever/class/rogue/plundering-the-plunderers", title = "Plundering the Plunderers", category = "Class", folder = "Rogue", faction = "Horde", classes = { "Rogue" }, levels = { 16, 20 }, zone = 1454, version = 1, revision = "7160e6336af7fb80c36c095d1095b175d5e7f9c3ddaf8cc982a1ac4eac74c456", legacyRevision = "c8ceeae8f353fbc42c4ba058c3da8dbb3b37834025485773ae90d4dd4dd99464", keywords = { "Plundering the Plunderers", "Find the Shattered Hand", "To Orgrimmar!", "Shenthul", "Zando'zan", "Wrenix of Ratchet", "Wrenix the Wretched", "Gizmotronic Apparatus", "E.C.A.C.", "Thieves' Tools", "Southsea Treasure", "Polly", "Jewel of the Southsea", "Tide Razor", "Buccaneer's Strongbox", "Thistle Tea", "Fenwick Thatros", "Tools of the Trade", "Ambermill Strongbox", "Dalaran Status Report", "Mennet Carkad", "Rogue", "lockpicking quest" }, rewards = { { item = 7676 } }, why = "Ten Thistle Tea, the rogue energy drink, from the Horde lockpicking jobs at 16.",
			steps = {
				{ title = "To Orgrimmar!", tip = "At 16 Kaplak, the rogue trainer in Razor Hill, sends you to Shenthul in Orgrimmar.", only = { races = { "Orc", "Troll", "Skyborne" } }, zone = 1411, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 2380, note = "Kaplak" },
				} },
				{ title = "Find the Shattered Hand", tip = "At 16 Mennet Carkad in the Rogues' Quarter sends you to Shenthul in Orgrimmar. Take Fenwick Thatros from him too; it is done in Silverpine Forest at the end of this guide.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "level", level = 16 },
					{ kind = "accept", quest = 2378, note = "Mennet Carkad" },
					{ kind = "accept", quest = 1998 },
				} },
				{ title = "Shenthul and Zando'zan", tip = "Undead take the zeppelin from the towers outside the Undercity to Durotar. Shenthul and Zando'zan stand in the Cleft of Shadow, the canyon under the Valley of Strength. Train Pick Lock from Shenthul (or any rogue trainer) now if you lack it: this job is a lockpicking test.", zone = 1454, goals = {
					{ kind = "turnin", quest = 2380, only = { races = { "Orc", "Troll", "Skyborne" } }, note = "Shenthul" },
					{ kind = "turnin", quest = 2378, only = { races = { "Scourge" } } },
					{ kind = "accept", quest = 2379 },
					{ kind = "turnin", quest = 2379, note = "Zando'zan" },
					{ kind = "accept", quest = 2382 },
				} },
				{ title = "Wrenix the Wretched", tip = "Fly or walk to Ratchet on the Barrens coast. Wrenix stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an E.C.A.C. and Thieves' Tools (Pick Lock does not work without the tools in your bags).", zone = 1413, goals = {
					{ kind = "getfp", place = "Ratchet", optional = true },
					{ kind = "turnin", quest = 2382, note = "Wrenix the Wretched" },
					{ kind = "accept", quest = 2381 },
					{ kind = "buy", npc = 7166, item = 7970, count = 1, note = "E.C.A.C.: Wrenix's Gizmotronic Apparatus" },
					{ kind = "buy", npc = 7166, item = 5060, count = 1, note = "Thieves' Tools" },
				} },
				{ title = "Southsea Treasure", tip = "Follow the coast south from Ratchet to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of The Jewel of the Southsea: it is empty, but opening it calls a giant level 50 Polly into the next room. Stay stealthed, put the E.C.A.C. on your action bar, target Polly and use it: the parrot shrinks to level 18. Kill it for the Southsea Treasure.", zone = 1413, goals = {
					{ kind = "collect", quest = 2381, objective = 1, item = 7968, note = "Southsea Treasure: Polly, after the E.C.A.C." },
				} },
				{ title = "Back to Wrenix", zone = 1413, goals = {
					{ kind = "turnin", quest = 2381, rewards = { { item = 7676 } }, note = "Wrenix the Wretched: ten Thistle Tea" },
				} },
				{ title = "Fenwick Thatros", tip = "Take the zeppelin from Orgrimmar to the Undercity and head south into Silverpine. Fenwick Thatros (level 16) stands alone on the old ferry dock on Lordamere Lake, north-east of the Sepulcher. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death.", only = { races = { "Scourge" } }, zone = 1421, goals = {
					{ kind = "collect", quest = 1998, objective = 1, item = 7306, note = "Fenwick's Head: Fenwick Thatros" },
				} },
				{ title = "Mennet Carkad", tip = "If you have no Thieves' Tools left, ask Estelle Gendry, the outfitter in the Rogues' Quarter.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1998, note = "Mennet Carkad, Rogues' Quarter" },
					{ kind = "accept", quest = 1999 },
				} },
				{ title = "Ambermill", tip = "The Kirin Tor keep their reports in walled Ambermill, in south-east Silverpine. Facing the town hall, take the building on the right: the Ambermill Strongbox is in a corner room upstairs (any Lockpicking opens it; the Thieves' Tools must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time.", only = { races = { "Scourge" } }, zone = 1421, goals = {
					{ kind = "collect", quest = 1999, objective = 1, item = 7309, note = "Dalaran Status Report: Ambermill Strongbox" },
				} },
				{ title = "Back to Mennet", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1999, note = "Mennet Carkad, Rogues' Quarter" },
				} },
			},
		},
		{
			id = "forever/class/rogue/poisons-alliance", title = "Poisons (Alliance)", category = "Class", folder = "Rogue", faction = "Alliance", classes = { "Rogue" }, levels = { 20, 24 }, zone = 1453, version = 1, revision = "b4ba9c29abb8ce70d2f007303e7cbc1da637e4e120d6909f22d7ac875fa3bba0", legacyRevision = "dddb9003f14c18e76f3f91bcfae212b21dabb1b23b0f12b04de04161607e6f19", keywords = { "Poisons", "Mathias and the Defias", "Klaven's Tower", "Agent Kearnen", "Klaven Mortwake", "Defias Tower Key", "Malformed Defias Drone", "Duskwood Chest", "The Touch of Zanzil", "Doc Mixilpixil", "Eau de Mixilpixil", "Thistle Tea", "Mathias Shaw", "SI:7", "Rogue", "class spell" }, rewards = { { spell = 2842, name = "Poisons" }, { item = 18160 }, { item = 8432 } }, why = "Forever teaches Poisons through this chain, not the trainer; the Thistle Tea recipe comes with it.",
			steps = {
				{ title = "Mathias and the Defias", tip = "At 20 Master Mathias Shaw, upstairs in the SI:7 building in Old Town, sends you to Agent Kearnen in Westfall. This chain is how you learn Poisons on Forever, so do not skip it.", zone = 1453, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 2360, note = "Master Mathias Shaw" },
				} },
				{ title = "Agent Kearnen", tip = "Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of Klaven Mortwake's Defias tower in the far east of Westfall, by the Duskwood border. Read Kearnen's Journal for the tower's layout if you like.", zone = 1436, goals = {
					{ kind = "turnin", quest = 2360, note = "Agent Kearnen" },
					{ kind = "accept", quest = 2359 },
				} },
				{ title = "The Defias Tower Key", tip = "Get the key first. The Malformed Defias Drone (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and Pick Pocket it from behind: it always has the key. It hits hard: if stealth breaks, Sprint away. Watch for the pair of Defias Drones that also patrol.", zone = 1436, goals = {
					{ kind = "collect", quest = 2359, objective = 2, item = 7923, text = "Pick Pocket the Malformed Defias Drone for the Defias Tower Key" },
				} },
				{ title = "Klaven's journal", tip = "Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. Klaven Mortwake, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The Duskwood Chest beside his desk needs Lockpicking of about 70-75 (practise on the boxes at Alther's Mill in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the Touch of Zanzil, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out.", zone = 1436, goals = {
					{ kind = "collect", quest = 2359, objective = 1, item = 7908, map = 1436, x = 70.4, y = 74, note = "Klaven Mortwake's Journal: the Duskwood Chest, top floor" },
				} },
				{ title = "Master Mathias Shaw", tip = "Head north through Elwynn to Stormwind; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the Thistle Tea recipe. Poisons are made, not bought: each batch of Instant Poison takes a Dust of Decay and an Empty Vial, which Jasper Fel and Sloan McCoy sell in Old Town next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon.", zone = 1453, goals = {
					{ kind = "turnin", quest = 2359, rewards = { { item = 18160 } }, note = "Master Mathias Shaw: Poisons" },
					{ kind = "accept", quest = 2607 },
				} },
				{ title = "Doc Mixilpixil", tip = "The Touch of Zanzil still sits on you. Doc Mixilpixil works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind Jasper Fel. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down.", zone = 1453, goals = {
					{ kind = "turnin", quest = 2607, note = "Doc Mixilpixil" },
					{ kind = "accept", quest = 2608 },
					{ kind = "complete", quest = 2608, map = 1453, x = 80.06, y = 69.9, frame = "live", note = "/lay with the Doc targeted" },
					{ kind = "turnin", quest = 2608 },
					{ kind = "accept", quest = 2609 },
				} },
				{ title = "The cure's ingredients", tip = "All four are in Stormwind. Simple Wildflowers: Bernard or Felicia Gump's flower shop by the Trade District canal. A Leaded Vial: many general goods and alchemy vendors (Keldric Boucher, Jasper Fel and others). A Bronze Tube: the Auction House in the Trade District; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The Spool of Light Chartreuse Silk Thread lies on the floor beside the left end of the counter in The Finest Thread, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an Anti-Venom (First Aid) or a druid's Cure Poison also clears the Touch of Zanzil.", zone = 1453, goals = {
					{ kind = "buy", item = 3421, count = 1, nearest = true, note = "Simple Wildflowers" },
					{ kind = "buy", item = 3372, count = 1, nearest = true, note = "Leaded Vial" },
					{ kind = "collect", item = 4371, count = 1, map = 1453, x = 61.2, y = 71.3, frame = "live", note = "Bronze Tube: the Auction House" },
					{ kind = "collect", quest = 2609, objective = 4, item = 8431, note = "Spool of Light Chartreuse Silk Thread" },
				} },
				{ title = "Back to Doc Mixilpixil", zone = 1453, goals = {
					{ kind = "turnin", quest = 2609, rewards = { { item = 8432 } }, note = "Doc Mixilpixil: Eau de Mixilpixil" },
				} },
			},
		},
		{
			id = "forever/class/rogue/poisons-horde", title = "Poisons (Horde)", category = "Class", folder = "Rogue", faction = "Horde", classes = { "Rogue" }, levels = { 20, 26 }, zone = 1454, version = 1, revision = "67f86b931ca55a68e9e29a65a352522cee67ec2c5876e380d37f8e0bde9d5744", legacyRevision = "161f61913595a40e8ae1fb80957441c64b49f052fdc665e66e314714eedf3df9", keywords = { "Poisons", "The Shattered Salute", "Deep Cover", "Shenthul", "Taskmaster Fizzule", "Flare Gun", "Fizzule's Whistle", "Mission: Possible But Not Probable", "Gallywix", "Foreman Silixiz", "Venture Co. tower", "Hinott's Assistance", "Serge Hinott", "Hinott's Oil", "Tarren Mill", "Thistle Tea", "Lockpicking", "Buccaneer's Strongbox", "Rogue", "class spell" }, rewards = { { spell = 2842, name = "Poisons" }, { item = 18160 }, { item = 8066 }, { item = 8095 } }, why = "Forever teaches Poisons through this chain, not the trainer; the Thistle Tea recipe comes with it.",
			steps = {
				{ title = "Lockpicking practice", tip = "Gallywix's Lockbox at the end of the tower job needs Lockpicking of about 70-75. Train Pick Lock from Gest or Shenthul in the Cleft of Shadow if you lack it, carry Thieves' Tools, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of Ratchet: they come back fast. Your cap rises 5 per level.", zone = 1413, goals = {
					{ kind = "level", level = 20 },
					{ kind = "goto", label = "Tide Razor", map = 1413, x = 64.4, y = 45.4 },
					{ kind = "task", text = "Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor", optional = true },
				} },
				{ title = "The Shattered Salute", tip = "Shenthul stands in the Cleft of Shadow, the canyon under the Valley of Strength. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the Cleft of Shadow, sells a Jambiya.", zone = 1454, goals = {
					{ kind = "accept", quest = 2460, note = "Shenthul" },
					{ kind = "complete", quest = 2460, map = 1454, x = 43.05, y = 53.74, note = "/salute Shenthul" },
					{ kind = "turnin", quest = 2460 },
					{ kind = "accept", quest = 2458, note = "Deep Cover: keep the Flare Gun" },
				} },
				{ title = "Taskmaster Fizzule", tip = "Fly to the Crossroads and head north to the Venture Co. tower above the Sludge Fen. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the Flare Gun twice, then walk up in front of him and /salute. In any other order he attacks. Lost the Flare Gun? Abandon and retake from Shenthul.", zone = 1413, goals = {
					{ kind = "use", item = 8051, map = 1413, x = 55.4, y = 5.6, note = "Flare Gun, twice, at Fizzule" },
					{ kind = "turnin", quest = 2458, rewards = { { item = 8066 } }, note = "Taskmaster Fizzule: Fizzule's Whistle" },
					{ kind = "accept", quest = 2478 },
				} },
				{ title = "Silixiz's Tower Key", tip = "Keep Fizzule's Whistle in your bags and use it on him every time you come near, or he turns hostile. Foreman Silixiz (level 22) walks by the tower: hug the wall, stealth up behind him and Pick Pocket the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back.", zone = 1413, goals = {
					{ kind = "collect", quest = 2478, objective = 5, item = 8072, text = "Pick Pocket Foreman Silixiz for Silixiz's Tower Key" },
				} },
				{ title = "The Venture Co. tower", tip = "Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point Rupture; the Lookouts on the open third floor from a one-point Eviscerate. Grand Foreman Puzik Gallywix waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then Gouge, Evasion, a healing potion and Thistle Tea; a friend makes it easy. One head per kill. Then pick Gallywix's Lockbox beside him for the cache: it poisons you with the Touch of Zanzil, which weakens your stealth and agility until Serge Hinott cures it.", zone = 1413, goals = {
					{ kind = "kill", quest = 2478, objective = 1, npc = 7310, count = 2, note = "Mutated Venture Co. Drone" },
					{ kind = "kill", quest = 2478, objective = 3, npc = 7308, count = 2, note = "Venture Co. Patroller" },
					{ kind = "kill", quest = 2478, objective = 2, npc = 7307, count = 2, note = "Venture Co. Lookout" },
					{ kind = "collect", quest = 2478, objective = 4, item = 8074, note = "Gallywix's Head: Grand Foreman Puzik Gallywix (elite)" },
					{ kind = "collect", quest = 2478, objective = 6, item = 8073, note = "Cache of Zanzil's Altered Mixture: Gallywix's Lockbox" },
				} },
				{ title = "Back to Shenthul", tip = "Fly back to Orgrimmar (Ratchet or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep Silixiz's Tower Key afterwards. Before you leave the Cleft, buy Dust of Decay and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of Instant Poison takes one of each.", zone = 1454, goals = {
					{ kind = "turnin", quest = 2478, rewards = { { item = 18160 } }, note = "Shenthul: Recipe: Thistle Tea" },
					{ kind = "accept", quest = 2479 },
				} },
				{ title = "Serge Hinott", tip = "Take the zeppelin from Orgrimmar to the Undercity and follow the road south through Silverpine Forest into Hillsbrad, to Tarren Mill. Serge Hinott works in the building next to the flight path, beside Apothecary Lydon, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from Shenthul. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make Instant Poison from Rekkul's dust and vials, and use it on your weapon.", zone = 1424, goals = {
					{ kind = "getfp", place = "Tarren Mill", optional = true },
					{ kind = "turnin", quest = 2479, note = "Serge Hinott" },
					{ kind = "accept", quest = 2480 },
					{ kind = "complete", quest = 2480, note = "Wait for the cure" },
					{ kind = "turnin", quest = 2480, rewards = { { item = 8095 } }, note = "Serge Hinott: Poisons" },
					{ kind = "use", item = 8095, map = 1424, x = 61.63, y = 19.19, optional = true, note = "Hinott's Oil: clears the Touch of Zanzil" },
				} },
			},
		},
		{
			id = "forever/class/rogue/ravenholdt", title = "Ravenholdt", category = "Class", folder = "Rogue", classes = { "Rogue" }, levels = { 24, 36 }, zone = 1424, version = 1, revision = "1fbf2d2a8a01b9b871d3f4a06b64172dc89a019e0ac97a5c22eb01569ce53543", legacyRevision = "c5768996d630a9daacb07d3521c8d940ccbf3fa87f85b325181e3d7368755eaf", keywords = { "Ravenholdt", "Ravenholdt Manor", "The Manor Ravenholdt", "Elegant Letter", "Seal of Ravenholdt", "Rite of Cunning", "Detect Traps", "Fahrad", "Myrokos Silentform", "Syndicate Sabotage", "Lord Tomas", "Durnholde Keep", "What's the Big Idea?", "Barton", "Barton's Scouting Report", "Strahnbrad", "Covert Extraction", "Blade of House Perenolde", "Royal Aegis of Perenolde", "Ruins of Alterac", "A Way In", "Northfold Manor", "Syndicate Footlocker", "Master of Disguise", "Syndicate Uniform", "Stromgarde", "Anastasia Miller", "Ain't No Telling", "Stolen Funds", "The Syndicate Sting", "Intercepted Shipment", "Thoradin's Wall", "Syndicate Emblems", "Rogue", "reputation" }, rewards = { { text = "Ravenholdt reputation" } }, why = "Opens Ravenholdt Manor, the hidden rogue house in the Alterac hills, and Myrokos's jobs against the Syndicate.",
			steps = {
				{ title = "The Elegant Letter", tip = "At 24 any capital's rogue trainer (Master Mathias Shaw or Osborne the Night Man in Stormwind, Gest or Ormok in Orgrimmar, and the others) has an Elegant Letter from Ravenholdt for you: ask for it in their talk window. Open it: the quest gives you the Seal of Ravenholdt for Fahrad. Learn Detect Traps from your trainer first if you have not; the way in is a test of it.", zone = 1424, goals = {
					{ kind = "level", level = 24 },
					{ kind = "accept", quest = 6681, item = 17126, note = "Elegant Letter" },
				} },
				{ title = "Ravenholdt Manor", tip = "Horde fly to Tarren Mill, Alliance to Southshore. The trail to the manor is hard to see: it starts behind the plateau north of Durnholde Keep, east of Tarren Mill, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast Detect Traps near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies Ravenholdt Manor: Fahrad is upstairs inside. Do not attack anyone at the manor: it costs Ravenholdt reputation.", zone = 1424, goals = {
					{ kind = "kill", quest = 6681, objective = 1, npc = 13936, note = "Rite of Cunning: Detect Traps beside the tunnel chest" },
					{ kind = "turnin", quest = 6681, note = "Fahrad" },
					{ kind = "accept", quest = 96779, note = "Myrokos Silentform" },
				} },
				{ title = "Lord Tomas", tip = "Lord Tomas is inside Durnholde Keep, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says Myrokos. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry Syndicate Emblems for the guards' repeatable reputation quest.", zone = 1424, goals = {
					{ kind = "kill", quest = 96779, objective = 1, npc = 266216, note = "Lord Tomas" },
					{ kind = "collect", item = 17124, text = "Pick Pocket Syndicate members for Syndicate Emblems", optional = true },
				} },
				{ title = "Myrokos Silentform", zone = 1416, goals = {
					{ kind = "turnin", quest = 96779, note = "Myrokos Silentform" },
					{ kind = "turnin", quest = 6701, optional = true, direct = true, note = "Ravenholdt Guard: one emblem each time, 100 reputation" },
				} },
				{ title = "What's the Big Idea?", tip = "In your mid 30s Myrokos has two more jobs; take both. Barton leads a Syndicate scouting party at Strahnbrad, in the east of the Alterac Mountains, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. Pick Pocket can miss several times in a row.", zone = 1416, goals = {
					{ kind = "level", level = 34 },
					{ kind = "accept", quest = 96781, note = "Myrokos Silentform" },
					{ kind = "accept", quest = 96783 },
					{ kind = "collect", quest = 96781, objective = 1, item = 275482, text = "Pick Pocket Barton for Barton's Scouting Report", map = 1416, x = 62.6, y = 46.9 },
				} },
				{ title = "Covert Extraction", tip = "Back to Myrokos; the report sends you after the Perenolde heirlooms. Two towers stand among the Ruins of Alterac, in the middle of the Alterac Mountains, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside.", zone = 1416, goals = {
					{ kind = "turnin", quest = 96781, note = "Myrokos Silentform" },
					{ kind = "accept", quest = 96782, npc = 13085 },
					{ kind = "collect", quest = 96782, objective = 2, item = 275636, map = 1416, x = 41.35, y = 40.16, note = "Royal Aegis of Perenolde, in the northern tower" },
					{ kind = "collect", quest = 96782, objective = 1, item = 275635, map = 1416, x = 38.5, y = 58, note = "Blade of House Perenolde, in the southern tower" },
					{ kind = "turnin", quest = 96782, note = "Myrokos Silentform" },
				} },
				{ title = "A Way In", tip = "Stromgarde Keep in western Arathi is a Syndicate stronghold; to get in you need a uniform. Northfold Manor, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the Syndicate Footlocker there and take the uniform; that ends A Way In.", zone = 1417, goals = {
					{ kind = "turnin", quest = 96783, object = 656157, map = 1417, x = 32.3, y = 26.6, note = "Syndicate Footlocker, Northfold Manor" },
					{ kind = "accept", quest = 96784, object = 656157, map = 1417, x = 32.3, y = 26.6, only = { factions = { "Horde" } }, note = "Master of Disguise: the Syndicate Uniform" },
				} },
				{ title = "Anastasia Miller", tip = "Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the Syndicate Uniform (Master of Disguise hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with Ain't No Telling. Anastasia Miller is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge.", zone = 1417, goals = {
					{ kind = "turnin", quest = 96784, map = 1417, x = 26.8, y = 64.4, only = { factions = { "Horde" } }, note = "Anastasia Miller" },
					{ kind = "accept", quest = 96785, npc = 266847, map = 1417, x = 26.8, y = 64.4, note = "Ain't No Telling" },
				} },
				{ title = "Ain't No Telling", tip = "She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the Stolen Funds. If it is already open, wait for it to come back.", zone = 1417, goals = {
					{ kind = "collect", quest = 96785, objective = 1, item = 275709, map = 1417, x = 29.5, y = 65.1, note = "Stolen Funds: Anastasia's Stash" },
					{ kind = "turnin", quest = 96785, map = 1417, x = 26.8, y = 64.4, note = "Anastasia Miller" },
					{ kind = "accept", quest = 96786, npc = 266847, map = 1417, x = 26.8, y = 64.4, note = "The Syndicate Sting" },
				} },
				{ title = "The Syndicate Sting", tip = "Falconcrest's men make the handoff at the southern end of Thoradin's Wall, the old wall between Arathi and Hillsbrad. Kill the two guarding the box and take the Intercepted Shipment. Keep the Syndicate Uniform: Myrokos wants it back with the shipment.", zone = 1417, goals = {
					{ kind = "collect", quest = 96786, objective = 1, item = 275882, map = 1417, x = 15.5, y = 43, note = "Intercepted Shipment" },
				} },
				{ title = "Back to Myrokos", zone = 1416, goals = {
					{ kind = "turnin", quest = 96786, note = "Myrokos Silentform: 70 silver, 300 Ravenholdt reputation" },
				} },
			},
		},
		{
			id = "forever/class/rogue/the-azure-key", title = "The Azure Key", category = "Class", folder = "Rogue", classes = { "Rogue" }, levels = { 50, 52 }, zone = 1416, version = 1, revision = "d31130e6d08b9e8bce695b469011593c30d94b572bba4a63ec50b1559b3f6a75", legacyRevision = "86d26d7687eb913d6362de73cfed581ec096352cda423ae0021520d3f005f7b3", keywords = { "The Azure Key", "A Simple Request", "Sealed Azure Bag", "Encoded Fragments", "Lord Jorach Ravenholdt", "Ravenholdt Manor", "Archmage Xylem", "Timbermaw Shaman", "Forest Ooze", "Morphaz", "Sunken Temple", "Temple of Atal'Hakkar", "Azshara", "Rogue", "class quest" }, rewards = { { text = "Ravenholdt reputation" } }, why = "Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever.",
			steps = {
				{ title = "A Simple Request (Alliance)", tip = "At 50 Osborne the Night Man in Stormwind's Old Town has it; so do Syurna in Darnassus and Hulfdan Blackbeard in Ironforge.", only = { factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8233, npc = 918, note = "Osborne the Night Man" },
				} },
				{ title = "A Simple Request (Horde)", tip = "At 50 Ormok in the Cleft of Shadow has it; so does Miles Dexter in the Undercity's Rogues' Quarter.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8233, npc = 3328, note = "Ormok" },
				} },
				{ title = "Lord Jorach Ravenholdt", tip = "Ravenholdt Manor hides in the hills east of Tarren Mill. Horde fly to Tarren Mill, Alliance to Southshore. The trail starts behind the plateau north of Durnholde Keep, climbs into the hills and runs through a small tunnel into the Alterac Mountains; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you.", zone = 1416, goals = {
					{ kind = "turnin", quest = 8233, note = "Lord Jorach Ravenholdt" },
					{ kind = "accept", quest = 8234 },
				} },
				{ title = "Sealed Azure Bag", tip = "Alliance fly to Talrendis Point, Horde to Valormok. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern Azshara carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. Pick Pocket them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with Timbermaw Hold, mark them At War in your reputation panel first. They cast Lightning Bolt and Lightning Cloud, heal each other and run at low health.", zone = 1447, goals = {
					{ kind = "getfp", place = "Talrendis Point", only = { factions = { "Alliance" } } },
					{ kind = "getfp", place = "Valormok", only = { factions = { "Horde" } } },
					{ kind = "collect", quest = 8234, objective = 1, item = 19775, note = "Sealed Azure Bag: Timbermaw Shaman" },
				} },
				{ title = "Archmage Xylem", tip = "Sanath Lim-yo, camped below the cliffs just east of Valormok, teleports you up (dismount first); a trail leads to Xylem's tower.", zone = 1447, goals = {
					{ kind = "turnin", quest = 8234, note = "Archmage Xylem" },
					{ kind = "accept", quest = 8235 },
				} },
				{ title = "Encoded Fragments", tip = "The Forest Oozes (level 52-53, Diseased Slime up close) drop a fragment four times in five: the biggest group, seven of them, is in the Bitter Reaches hills of north-eastern Azshara, four more south-east of Valormok. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear.", zone = 1447, goals = {
					{ kind = "collect", quest = 8235, objective = 1, item = 20023, count = 10, note = "Encoded Fragment: Forest Ooze" },
				} },
				{ title = "Back to Xylem", zone = 1447, goals = {
					{ kind = "turnin", quest = 8235, note = "Archmage Xylem" },
					{ kind = "accept", quest = 8236 },
				} },
				{ title = "Morphaz in the Sunken Temple", tip = "Morphaz, a level 52 elite green drake, lives deep in the Sunken Temple: a group of five, level 50-54. The temple stands in the Pool of Tears; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to Jammal'an the Prophet in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their Acid Breath is nature damage: nature protection potions help; poisons and Blind do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all.", zone = 1435, goals = {
					{ kind = "collect", quest = 8236, objective = 1, item = 20022, map = 1435, x = 69.9, y = 53.6, note = "Azure Key: Morphaz, inside the temple" },
				} },
				{ title = "Lord Ravenholdt", tip = "Look at the reward window before you hand in: Classic offered the Duskbat Drape, the Ebon Mask or the Whisperwalk Boots, and Forever's notes say the choice may be gone.", zone = 1416, goals = {
					{ kind = "turnin", quest = 8236, note = "Lord Jorach Ravenholdt" },
				} },
			},
		},
		{
			id = "forever/class/rogue/the-eye-of-bhossca", title = "The Eye of Bhossca", category = "Class", folder = "Rogue", classes = { "Rogue" }, levels = { 30, 35 }, zone = 1421, version = 1, revision = "f5d9b98c2b58365022c9a202a630328153b7e7c416ae91fc440df6c7308353f8", legacyRevision = "688393872f208cd6b5d66b2a0310e996091d62bf106e1b5a912234f98dcd4ad1", keywords = { "The Eye of Bhossca", "C's dead drop", "Dead Drop", "Pyrewood Village", "Scarlet Monastery", "disguise", "Ruby-Adorned Blade", "Rogue", "solo dungeon" }, rewards = { { item = 277246 } }, why = "The Ruby-Adorned Blade, C's payment for a solo job inside the Scarlet Monastery.",
			steps = {
				{ title = "C's dead drop", tip = "C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the Dead Drop near Pyrewood Village, in southern Silverpine just south of Shadowfang Keep, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30.", zone = 1421, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 78676, object = 410369, note = "Dead Drop" },
				} },
				{ title = "The Scarlet Monastery", tip = "The monastery stands in the far north-east of Tirisfal Glades. Go in alone, out of any group. Before entering, take the Scarlet Initiate's Uniform from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), Pick Pocket a Scarlet Scryer or Scarlet Crier for the Scryer's Key. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the Reliquary Key from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance.", zone = 1420, goals = {
					{ kind = "goto", label = "Scarlet Monastery", map = 1420, x = 82.6, y = 33.8, frame = "live" },
					{ kind = "note", text = "Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings." },
				} },
				{ title = "Back to the dead drop", tip = "Place the eye in the Dead Drop near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared.", zone = 1421, goals = {
					{ kind = "turnin", quest = 78676, object = 410369, note = "Dead Drop" },
					{ kind = "accept", quest = 78699, object = 410369 },
					{ kind = "turnin", quest = 78699, object = 410369, rewards = { { item = 277246 } }, note = "Ruby-Adorned Blade" },
				} },
			},
		},
		{
			id = "forever/class/rogue/the-horn-of-xelthos", title = "The Horn of Xelthos", category = "Class", folder = "Rogue", classes = { "Rogue" }, levels = { 23, 26 }, zone = 1421, version = 1, revision = "386db7747887d3a07aba8c1d89b5193622cc83bdafceada03da38d4ce4f9aa22", legacyRevision = "02e370398806b119641664789c4555970d1c1d359a36ea2f8f9796e3ef33a74f", keywords = { "The Horn of Xelthos", "C's dead drop", "Dead Drop", "Pyrewood Village", "Veenix", "Goblin Lockpicks", "Venture Co. Work Order", "Breaching Charge", "Shadowfang Keep", "Pyrewood Signet Ring", "Rogue", "solo dungeon" }, rewards = { { item = 277210 } }, why = "The Pyrewood Signet Ring, C's payment for a solo job inside Shadowfang Keep.",
			steps = {
				{ title = "C's dead drop", tip = "The Dead Drop is a chest in a house just outside Pyrewood Village in southern Silverpine, south of Shadowfang Keep. Open it and read C's note: the job has to be done alone, out of any group.", zone = 1421, goals = {
					{ kind = "level", level = 23 },
					{ kind = "accept", quest = 78261, object = 410369, note = "Dead Drop" },
				} },
				{ title = "Veenix", tip = "Veenix, a goblin friendly to both factions, stands among the Venture Co. in the Windshear Crag, east Stonetalon, a short way north-east of Sun Rock Retreat. Horde fly to Sun Rock Retreat; Alliance to Stonetalon Peak. He wants a Venture Co. Work Order before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and Pick Pocket it; killing them does not give it.", zone = 1442, goals = {
					{ kind = "talk", npc = 4086, note = "Veenix" },
					{ kind = "accept", quest = 78270 },
					{ kind = "collect", item = 210187, count = 1, text = "Pick Pocket a Venture Co. Logger for a Venture Co. Work Order" },
					{ kind = "turnin", quest = 78270, rewards = { { item = 210186, name = "Breaching Charge" } } },
				} },
				{ title = "Shadowfang Keep", tip = "Go in alone and use the Breaching Charge at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring Flash Powder and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the Sister's Half-Key, then the brother in the room reached by turning right at the top of the stairs for the Brother's Half-Key (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach.", zone = 1421, goals = {
					{ kind = "collect", quest = 78261, objective = 1, item = 210183, map = 1421, x = 44.8, y = 67.8, frame = "live", note = "Horn of Xelthos, inside Shadowfang Keep" },
				} },
				{ title = "Back to the dead drop", tip = "Place the horn in the Dead Drop near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered.", zone = 1421, goals = {
					{ kind = "turnin", quest = 78261, object = 410369, note = "Dead Drop" },
					{ kind = "accept", quest = 78307, object = 410369 },
					{ kind = "turnin", quest = 78307, object = 410369, rewards = { { item = 277210 } }, note = "Pyrewood Signet Ring" },
				} },
			},
		},
		{
			id = "forever/class/shaman/call-of-air-alliance", title = "Call of Air and the Tempest's Weapons (Alliance)", category = "Class", folder = "Shaman", faction = "Alliance", classes = { "Shaman" }, levels = { 30, 40 }, zone = 1455, version = 1, revision = "9b18ed7305a88bceca8dd8b985b7ecedc0d819b673f414ef844bbe594a469102", legacyRevision = "e3395e93a64aeb55d177999f1716201f4d1cd82fd5f5387f35738e0419a1da16", keywords = { "Air Totem", "Elemental Aid", "Storm", "Earth", "and Fire", "Heed My Call", "The Tempest's Weapons", "Eldrun Stormbreaker", "Veyric Thunderhame", "Bath'rah the Windwatcher", "Razorfen Kraul", "Charlga Razorflank", "Twisted Totem", "Ravaging Tempest", "Eye of the Tempest", "Lightning's Grasp", "Tidebringer's Claw", "Rage of the Storm", "Elementalist's Guard", "Shaman", "class quest", "totem", "weapon" }, rewards = { { item = 5178 }, { item = 280607, choice = true }, { item = 280605, choice = true }, { item = 280604, choice = true }, { item = 280696 } }, why = "The Air Totem that lets you place air totems, then a weapon of your choice at 40.",
			steps = {
				{ title = "Eldrun Stormbreaker", tip = "At 30 Eldrun Stormbreaker, the shaman trainer in Ironforge, sends you to Veyric Thunderhame in Arathi Highlands. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem he gives.", zone = 1455, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 94789, note = "Eldrun Stormbreaker" },
				} },
				{ title = "Veyric Thunderhame", tip = "Veyric Thunderhame camps in the hills just west of Hammerfall, the Horde town in the north-east of Arathi: mind its guards. Fly to Refuge Pointe and head north-east.", zone = 1417, goals = {
					{ kind = "turnin", quest = 94789, rewards = { { item = 5178 } }, note = "Veyric Thunderhame: your Air Totem" },
					{ kind = "accept", quest = 96264 },
				} },
				{ title = "Charlga Razorflank", tip = "Razorfen Kraul is a five-player dungeon at the southern edge of the Barrens (the arrow points at its entrance); Charlga Razorflank (level 33 elite) is its last boss. She casts Chain Bolt, Renew on her allies and Purity; the Tattered Note drops only from her.", zone = 1413, goals = {
					{ kind = "collect", quest = 96264, objective = 1, item = 274463, map = 1413, x = 42.9, y = 90.2, frame = "live", note = "Tattered Note, from Charlga Razorflank" },
				} },
				{ title = "Veyric Thunderhame", zone = 1417, goals = {
					{ kind = "turnin", quest = 96264, note = "Veyric Thunderhame" },
					{ kind = "accept", quest = 79358 },
				} },
				{ title = "Twisted Fire Totems", tip = "Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of Angor Fortress in the Badlands carry them; the Shamans drop Fire Nova Totems and a Healing Ward, the Bonesnappers run for help when hurt. Respawn about five minutes.", zone = 1418, goals = {
					{ kind = "level", level = 36 },
					{ kind = "collect", quest = 79358, objective = 3, item = 274044, count = 5, note = "Twisted Fire Totem" },
				} },
				{ title = "Twisted Earth Totems", tip = "Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of Stonard in the Swamp of Sorrows carry them; most run for help when hurt.", zone = 1435, goals = {
					{ kind = "level", level = 33 },
					{ kind = "collect", quest = 79358, objective = 2, item = 274045, count = 5, note = "Twisted Earth Totem" },
				} },
				{ title = "Twisted Water Totems", tip = "Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of Brackenwall Village in northern Dustwallow Marsh carry them.", zone = 1445, goals = {
					{ kind = "level", level = 34 },
					{ kind = "collect", quest = 79358, objective = 1, item = 274046, count = 5, note = "Twisted Water Totem" },
				} },
				{ title = "Twisted Air Totems", tip = "Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of Shadowprey Village in western Desolace carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw Jumping Lightning: pull one at a time. Respawn about five minutes.", zone = 1443, goals = {
					{ kind = "level", level = 36 },
					{ kind = "collect", quest = 79358, objective = 4, item = 274047, count = 5, note = "Twisted Air Totem" },
				} },
				{ title = "Veyric Thunderhame", zone = 1417, goals = {
					{ kind = "turnin", quest = 79358, npc = 259023, note = "Veyric Thunderhame" },
					{ kind = "accept", quest = 96135 },
				} },
				{ title = "The steam pools", tip = "Veyric hands you the Corrupted Totems. Thousand Needles is far: the boat to Theramore and the road west, or fly to Thalanaar on the Feralas border and head east into the canyon. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", zone = 1441, goals = {
					{ kind = "level", level = 38 },
					{ kind = "collect", quest = 96135, objective = 1, item = 212792, group = 3, note = "Eye of the Tempest, from the Ravaging Tempest" },
				} },
				{ title = "Veyric Thunderhame", zone = 1417, goals = {
					{ kind = "turnin", quest = 96135, note = "Veyric Thunderhame" },
					{ kind = "accept", quest = 96016 },
				} },
				{ title = "Bath'rah the Windwatcher", tip = "Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm.", zone = 1416, goals = {
					{ kind = "turnin", quest = 96016, choose = { { item = 280607 }, { item = 280605 }, { item = 280604 } }, rewards = { { item = 280696 } }, note = "Bath'rah the Windwatcher: the Elementalist's Guard and your weapon" },
				} },
			},
		},
		{
			id = "forever/class/shaman/call-of-air-horde", title = "Call of Air and the Tempest's Weapons (Horde)", category = "Class", folder = "Shaman", faction = "Horde", classes = { "Shaman" }, levels = { 30, 40 }, zone = 1454, version = 1, revision = "e839f6b44ecb083e1761cf8558a1f67f582ffac328b90a5004bbe5499886b592", legacyRevision = "ca3d1f5cefe4bd192af1eaa36a75ec762acedec78652106cb82f5db8538239fb", keywords = { "Air Totem", "Elemental Aid", "Eyes on the Sky", "Storm", "Earth", "and Fire", "Heed My Call", "The Tempest's Weapons", "Prate Cloudseer", "Rau Cliffrunner", "Bath'rah the Windwatcher", "Alaana Stormwalker", "Razorfen Kraul", "Charlga Razorflank", "Twisted Totem", "Corrupted Totems", "Ravaging Tempest", "Eye of the Tempest", "Lightning's Grasp", "Tidebringer's Claw", "Rage of the Storm", "Elementalist's Guard", "Skyborne", "Shaman", "class quest", "totem", "weapon" }, rewards = { { item = 5178 }, { item = 280607, choice = true }, { item = 280605, choice = true }, { item = 280604, choice = true }, { item = 280696 } }, why = "The Air Totem that lets you place air totems, then a weapon of your choice at 40.",
			steps = {
				{ title = "Searn Firewarder", tip = "At 30 Searn Firewarder in the Valley of Wisdom sends you to Prate Cloudseer in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem she gives.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 1531, note = "Searn Firewarder" },
				} },
				{ title = "Alaana Stormwalker", tip = "At 30 Skyborne shamans get their own Call of Air. Alaana Stormwalker waits where the airship from Zephras Isle lands, in northern Mulgore beside Thunder Bluff. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to Xanis Flameweaver in Thunder Bluff (next step): the trainers' Call of Air is open to Skyborne and gives the same totem.", only = { races = { "Skyborne" } }, zone = 1412, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 96136, npc = 259119, optional = true, note = "Alaana Stormwalker" },
				} },
				{ title = "Xanis Flameweaver", tip = "At 30 Xanis Flameweaver, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to Prate Cloudseer in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem Prate gives. Already carry Searn Firewarder's Call of Air from Orgrimmar? It goes to Prate too: skip Xanis.", only = { races = { "Tauren", "Skyborne" } }, when = { { test = "onquest", quests = { 96136 }, negate = true }, { test = "onquest", quests = { 1531 }, negate = true } }, zone = 1456, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 1532, note = "Xanis Flameweaver" },
				} },
				{ title = "Prate Cloudseer", tip = "Fly to Freewind Post. Prate Cloudseer stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running.", zone = 1441, goals = {
					{ kind = "goto", label = "Prate Cloudseer", map = 1441, x = 53.5, y = 42.6 },
				} },
				{ when = { { test = "onquest", quests = { 1531 } } }, zone = 1441, goals = {
					{ kind = "turnin", quest = 1531, rewards = { { item = 5178 } }, note = "Prate Cloudseer: your Air Totem" },
				} },
				{ when = { { test = "onquest", quests = { 1532 } } }, zone = 1441, goals = {
					{ kind = "turnin", quest = 1532, rewards = { { item = 5178 } }, note = "Prate Cloudseer: your Air Totem" },
				} },
				{ when = { { test = "onquest", quests = { 96136 } } }, zone = 1441, goals = {
					{ kind = "turnin", quest = 96136, npc = 5905, rewards = { { item = 5178 } }, note = "Prate Cloudseer: your Air Totem" },
				} },
				{ title = "Prate Cloudseer", zone = 1441, goals = {
					{ kind = "accept", quest = 79360, npc = 5905 },
				} },
				{ title = "Charlga Razorflank", tip = "Razorfen Kraul is a five-player dungeon at the southern edge of the Barrens (the arrow points at its entrance); Charlga Razorflank (level 33 elite) is its last boss. She casts Chain Bolt, Renew on her allies and Purity; the Tattered Note drops only from her.", zone = 1413, goals = {
					{ kind = "collect", quest = 79360, objective = 1, item = 274463, map = 1413, x = 42.9, y = 90.2, frame = "live", note = "Tattered Note, from Charlga Razorflank" },
				} },
				{ title = "Rau Cliffrunner", tip = "Rau Cliffrunner stands at Freewind Post.", zone = 1441, goals = {
					{ kind = "turnin", quest = 79360, npc = 4722, note = "Rau Cliffrunner" },
					{ kind = "accept", quest = 79364, npc = 4722 },
				} },
				{ title = "Prate Cloudseer", zone = 1441, goals = {
					{ kind = "turnin", quest = 79364, npc = 5905, note = "Prate Cloudseer" },
					{ kind = "accept", quest = 79361, npc = 5905 },
				} },
				{ title = "Twisted Air Totems", tip = "Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of Shadowprey Village in western Desolace carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw Jumping Lightning: pull one at a time. Respawn about five minutes.", zone = 1443, goals = {
					{ kind = "level", level = 36 },
					{ kind = "collect", quest = 79361, objective = 4, item = 274047, count = 5, note = "Twisted Air Totem" },
				} },
				{ title = "Twisted Water Totems", tip = "Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of Brackenwall Village in northern Dustwallow Marsh carry them.", zone = 1445, goals = {
					{ kind = "level", level = 34 },
					{ kind = "collect", quest = 79361, objective = 1, item = 274046, count = 5, note = "Twisted Water Totem" },
				} },
				{ title = "Twisted Fire Totems", tip = "Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of Angor Fortress in the Badlands carry them; the Shamans drop Fire Nova Totems and a Healing Ward, the Bonesnappers run for help when hurt. Respawn about five minutes.", zone = 1418, goals = {
					{ kind = "level", level = 36 },
					{ kind = "collect", quest = 79361, objective = 3, item = 274044, count = 5, note = "Twisted Fire Totem" },
				} },
				{ title = "Twisted Earth Totems", tip = "Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of Stonard in the Swamp of Sorrows carry them; most run for help when hurt.", zone = 1435, goals = {
					{ kind = "level", level = 33 },
					{ kind = "collect", quest = 79361, objective = 2, item = 274045, count = 5, note = "Twisted Earth Totem" },
				} },
				{ title = "Prate Cloudseer", zone = 1441, goals = {
					{ kind = "turnin", quest = 79361, npc = 5905, note = "Prate Cloudseer" },
					{ kind = "accept", quest = 79366, npc = 5905 },
				} },
				{ title = "The steam pools", tip = "Prate hands you the Corrupted Totems. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", zone = 1441, goals = {
					{ kind = "level", level = 38 },
					{ kind = "collect", item = 212792, count = 1, group = 3, note = "Eye of the Tempest, from the Ravaging Tempest" },
				} },
				{ title = "Rau Cliffrunner", zone = 1441, goals = {
					{ kind = "turnin", quest = 79366, npc = 4722, note = "Rau Cliffrunner" },
					{ kind = "accept", quest = 79442 },
				} },
				{ title = "Bath'rah the Windwatcher", tip = "Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm; the Elementalist's Guard shield comes with it.", zone = 1416, goals = {
					{ kind = "turnin", quest = 79442, choose = { { item = 280607 }, { item = 280605 }, { item = 280604 } }, rewards = { { item = 280696 } }, note = "Bath'rah the Windwatcher: the Elementalist's Guard and your weapon" },
				} },
			},
