		{
			id = "forever/class/shaman/call-of-earth-alliance", title = "Call of Earth (Alliance)", category = "Class", folder = "Shaman", faction = "Alliance", classes = { "Shaman" }, levels = { 4, 5 }, zone = 1426, version = 1, revision = "7a1acab302053a7cd0353b26bfe4086cb07b17b4f492f1a5e86678749e1197fb", keywords = { "Earth Totem", "Stoneskin Totem", "Earth Sapta", "Call of Earth", "Archaic Rune", "Teo Hammerstorm", "Sten Stoutarm", "Eldrun Stormbreaker", "Ingrid Dunwald", "Spirit Stone", "Minor Manifestation of Earth", "Iceclaw Bear Pendant", "Frostmane", "Rough Quartz", "Coldridge Valley", "Anvilmar", "Shaman", "class quest", "totem" }, rewards = { { item = 5175 }, { spell = 8071, name = "Stoneskin Totem" } }, why = "Your Earth Totem: without it no earth totem can be cast. Stoneskin Totem comes with it at level 4.",
			steps = {
				{ title = "Archaic Rune", tip = "Teo's Call of Earth needs the Archaic Rune handed in first: Sten Stoutarm, where you entered Coldridge Valley, gives it to Dwarf shamans after his Dwarven Outfitters. Bring it up the road to Teo Hammerstorm inside Anvilmar.", when = { { quest = 98581, test = "turnedin", negate = true } }, zone = 1426, goals = {
					{ kind = "accept", quest = 98581, note = "Sten Stoutarm" },
					{ kind = "turnin", quest = 98581, note = "Teo Hammerstorm" },
				} },
				{ title = "Teo Hammerstorm", tip = "Teo Hammerstorm trains shamans inside Anvilmar, the hall at the south end of Coldridge Valley. The quest opens at level 4. Never took it and now 10 or more? Eldrun Stormbreaker in Ironforge or Ingrid Dunwald in Kharanos gives you Call of Earth, a pointer back to Teo: take it for the experience on the way.", zone = 1426, goals = {
					{ kind = "level", level = 4 },
					{ kind = "accept", quest = 94373, note = "Teo Hammerstorm" },
				} },
				{ title = "Iceclaw Bear Pendants", tip = "The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of Anvilmar, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes.", zone = 1426, goals = {
					{ kind = "collect", quest = 94373, objective = 1, item = 264356, count = 2, note = "Iceclaw Bear Pendant" },
				} },
				{ title = "Teo Hammerstorm", tip = "Back to Teo inside Anvilmar. He hands you the Earth Sapta: do not drink it yet.", zone = 1426, goals = {
					{ kind = "turnin", quest = 94373, note = "Teo Hammerstorm" },
					{ kind = "accept", quest = 94374 },
				} },
				{ title = "Lost the Earth Sapta?", tip = "Only if the Earth Sapta is gone from your bags (drunk away from the stone, or sold): Teo gives you another.", when = { { test = "onquest", quests = { 94374 } }, { item = 6635, test = "has", negate = true } }, zone = 1426, goals = {
					{ kind = "turnin", quest = 94472, direct = true, note = "Teo Hammerstorm: a new Earth Sapta" },
				} },
				{ title = "The Spirit Stone", tip = "The Spirit Stone stands on a snowy ridge north-west of Anvilmar. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the Earth Sapta and speak to the Minor Manifestation of Earth before it fades.", zone = 1426, goals = {
					{ kind = "use", item = 6635, map = 1426, x = 24.8, y = 61.8, note = "Earth Sapta, beside the Spirit Stone" },
					{ kind = "turnin", quest = 94374, note = "Minor Manifestation of Earth" },
					{ kind = "accept", quest = 94375, note = "it hands you the Rough Quartz: keep it" },
				} },
				{ title = "Teo Hammerstorm", tip = "Bring the Rough Quartz back to Teo inside Anvilmar. Keep the Earth Totem in your bags for good: every earth totem needs it.", zone = 1426, goals = {
					{ kind = "turnin", quest = 94375, rewards = { { item = 5175 } }, note = "Teo Hammerstorm: Stoneskin Totem and your Earth Totem" },
					{ kind = "train", classTrainer = true, note = "the level 4 shaman spells" },
				} },
			},
		},
		{
			id = "forever/class/shaman/call-of-earth-horde", title = "Call of Earth (Horde)", category = "Class", folder = "Shaman", faction = "Horde", classes = { "Shaman" }, levels = { 4, 5 }, zone = 1411, version = 1, revision = "08b2025356cf653900136162c797f9edf48f1a697033ba28cf6d5d1a1d83f305", keywords = { "Earth Totem", "Stoneskin Totem", "Earth Sapta", "Call of Earth", "Canaga Earthcaller", "Seer Ravenfeather", "Windshaper Boro", "Spirit Rock", "Kodo Rock", "Rise of Spirits", "Minor Manifestation of Earth", "Felstalker Hoof", "Ritual Salve", "Signet of Akir", "Rough Quartz", "Shaman", "class quest", "totem" }, rewards = { { item = 5175 }, { spell = 8071, name = "Stoneskin Totem" } }, why = "Your Earth Totem: without it no earth totem can be cast. Stoneskin Totem comes with it at level 4.",
			steps = {
				{ title = "Canaga Earthcaller", tip = "Canaga Earthcaller stands just outside the Den, the cave in the middle of the Valley of Trials. The quest opens at level 4.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "level", level = 4 },
					{ kind = "accept", quest = 1516, note = "Canaga Earthcaller" },
				} },
				{ title = "Felstalker Hooves", tip = "Felstalkers (level 3-4) prowl the slope below the Burning Blade Coven, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every Felstalker drops a hoof (four kills in five); they respawn in a little over three minutes.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "collect", quest = 1516, objective = 1, item = 6640, count = 2, note = "Felstalker Hoof" },
				} },
				{ title = "Canaga Earthcaller", tip = "Back to Canaga outside the Den. She hands you the Earth Sapta: do not drink it yet.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1516, note = "Canaga Earthcaller" },
					{ kind = "accept", quest = 1517 },
				} },
				{ title = "Lost the Earth Sapta?", tip = "Only if the Earth Sapta is gone from your bags (drunk away from the rock, or sold): Canaga gives you another.", only = { races = { "Orc", "Troll" } }, when = { { test = "onquest", quests = { 1517 } }, { item = 6635, test = "has", negate = true } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1463, direct = true, note = "Canaga Earthcaller: a new Earth Sapta" },
				} },
				{ title = "Spirit Rock", tip = "Spirit Rock sits on a ledge in the hills just south of the Den. The Hidden Path up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the Earth Sapta: the Minor Manifestation of Earth appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "use", item = 6635, map = 1411, x = 44.1, y = 76.4, note = "Earth Sapta, beside Spirit Rock" },
					{ kind = "turnin", quest = 1517, note = "Minor Manifestation of Earth" },
					{ kind = "accept", quest = 1518, note = "it hands you the Rough Quartz: keep it" },
				} },
				{ title = "Canaga Earthcaller", tip = "Bring the Rough Quartz back to Canaga outside the Den. Keep the Earth Totem she gives you in your bags for good: every earth totem needs it.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1518, rewards = { { item = 5175 } }, note = "Canaga Earthcaller: Stoneskin Totem and your Earth Totem" },
					{ kind = "train", classTrainer = true, note = "the level 4 shaman spells" },
				} },
				{ title = "Seer Ravenfeather", tip = "Seer Ravenfeather stands in Camp Narache. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "level", level = 4 },
					{ kind = "accept", quest = 1519, note = "Seer Ravenfeather" },
				} },
				{ title = "Ritual Salve", tip = "The Bristleback Shamans (level 3-4) stand among the quilboar huts of Brambleblade Ravine, east of the camp, and throw the odd Lightning Bolt. Four kills in five drop a salve; they respawn in about four minutes.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "collect", quest = 1519, objective = 1, item = 6634, count = 2, note = "Ritual Salve" },
				} },
				{ title = "Seer Ravenfeather", tip = "Back to the Seer in Camp Narache. She hands you the Earth Sapta: do not drink it yet.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "turnin", quest = 1519, note = "Seer Ravenfeather" },
					{ kind = "accept", quest = 1520 },
				} },
				{ title = "Lost the Earth Sapta?", tip = "Only if the Earth Sapta is gone from your bags: the Seer gives you another.", only = { races = { "Tauren" } }, when = { { test = "onquest", quests = { 1520 } }, { item = 6635, test = "has", negate = true } }, zone = 1412, goals = {
					{ kind = "turnin", quest = 1462, direct = true, note = "Seer Ravenfeather: a new Earth Sapta" },
				} },
				{ title = "Kodo Rock", tip = "Kodo Rock is a small pillar on a low mound due east of Greatmother Hawkwind's well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the Earth Sapta, then speak to the Minor Manifestation of Earth before it fades (drink again if it does).", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "use", item = 6635, map = 1412, x = 52, y = 80.1, note = "Earth Sapta, beside Kodo Rock" },
					{ kind = "turnin", quest = 1520, note = "Minor Manifestation of Earth" },
					{ kind = "accept", quest = 1521, note = "it hands you the Rough Quartz: keep it" },
				} },
				{ title = "Seer Ravenfeather", tip = "Bring the Rough Quartz back to the Seer. Keep the Earth Totem in your bags for good: every earth totem needs it.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "turnin", quest = 1521, rewards = { { item = 5175 } }, note = "Seer Ravenfeather: Stoneskin Totem and your Earth Totem" },
					{ kind = "train", classTrainer = true, note = "the level 4 shaman spells" },
				} },
				{ title = "Windshaper Boro", tip = "Windshaper Boro, the shaman trainer, stands in Thendal Village. The quest opens at level 3.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 3 },
					{ kind = "accept", quest = 92466, note = "Windshaper Boro" },
				} },
				{ title = "Signet of Akir", tip = "Any Al'Aketh cultist can carry the Signet of Akir: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond Hanaa Nightwind, south-west of the village. Keep killing until one drops it.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "collect", quest = 92466, objective = 1, item = 251924, note = "Signet of Akir" },
				} },
				{ title = "Windshaper Boro", tip = "Back to Boro in Thendal Village. He hands you the Earth Sapta: do not drink it yet.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 92466, note = "Windshaper Boro" },
					{ kind = "accept", quest = 92467 },
				} },
				{ title = "The Rise of Spirits", tip = "The Rise of Spirits is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the Earth Sapta beside the shrine and speak to the Minor Manifestation of Earth before it fades.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "use", item = 6635, map = 2521, x = 49.7, y = 23.8, note = "Earth Sapta, beside the shrine" },
					{ kind = "turnin", quest = 92467, note = "Minor Manifestation of Earth" },
