		{
			id = "forever/class/shaman/call-of-fire-alliance", title = "Call of Fire (Alliance)", category = "Class", folder = "Shaman", faction = "Alliance", classes = { "Shaman" }, levels = { 10, 14 }, zone = 1426, version = 1, revision = "72c1780413eb52890c8be8d0f5ea6628616d2b7b6ecc0c9b242e569912a70050", keywords = { "Fire Totem", "Searing Totem", "Totem of Charged Flames", "Fire Sapta", "Call of Fire", "Ingrid Dunwald", "Eldrun Stormbreaker", "Bruegs Kindleborn", "Braldir Ashmantle", "Fire Tar", "Reagent Pouch", "Tunnel Rat Geomancer", "Stonesplinter Seer", "Silver Stream Mine", "Glowing Ember", "Brazier of the Dormant Flame", "Shrine of Eternal Flame", "Torch of Eternal Flame", "South Gate Outpost", "Loch Modan", "Shaman", "class quest", "totem" }, rewards = { { item = 5176 }, { spell = 3599, name = "Searing Totem" }, { item = 263412 } }, why = "Your Fire Totem for every fire totem, Searing Totem with it, and Forever's Totem of Charged Flames.",
			steps = {
				{ title = "Call of Fire", tip = "At 10 Ingrid Dunwald, the shaman trainer in Kharanos, or Eldrun Stormbreaker, the shaman trainer in Ironforge, sends you to Bruegs Kindleborn.", zone = 1426, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94449, note = "Ingrid Dunwald, Kharanos; or Eldrun Stormbreaker, Ironforge" },
				} },
				{ title = "Bruegs Kindleborn", tip = "Follow the road east to the tunnel towards South Gate Outpost. Out of the first tunnel, keep left past Mountaineer Barleybrew and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to Bruegs' cave above the farm. He hands you the Torch of the Dormant Flame: keep it until the end of the chain.", zone = 1426, goals = {
					{ kind = "turnin", quest = 94449, note = "Bruegs Kindleborn" },
					{ kind = "accept", quest = 94465 },
				} },
				{ title = "Braldir Ashmantle", tip = "From Bruegs' ledge you can drop carefully down the mountain into Loch Modan, or walk back through the tunnel. Braldir Ashmantle keeps the shrine on the peak just south of Thelsamar: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak.", zone = 1432, goals = {
					{ kind = "turnin", quest = 94465, note = "Braldir Ashmantle" },
					{ kind = "accept", quest = 94466 },
				} },
				{ title = "Reagent Pouch", tip = "The Stonesplinter Seers (level 13-14) stand among the troggs of Stonesplinter Valley in the south of the loch, and in the trogg camps north-east of Thelsamar. They throw Lightning Bolts from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes.", zone = 1432, goals = {
					{ kind = "collect", quest = 94466, objective = 2, item = 6652, note = "Reagent Pouch" },
				} },
				{ title = "Fire Tar", tip = "The Tunnel Rat Geomancers (level 12-13) work only inside the Silver Stream Mine at the north end of the loch, past Thelsamar. They cast Fire Blast behind a Fire Shield and run for help at low health.", zone = 1432, goals = {
					{ kind = "collect", quest = 94466, objective = 1, item = 5026, note = "Fire Tar" },
				} },
				{ title = "Braldir Ashmantle", tip = "Back up the trail to Braldir. He makes the Fire Sapta from the tar and the pouch: keep it with the torch.", zone = 1432, goals = {
					{ kind = "turnin", quest = 94466, note = "Braldir Ashmantle" },
					{ kind = "accept", quest = 94467 },
				} },
				{ title = "Lost the Fire Sapta?", tip = "Only if the Fire Sapta is gone from your bags: Braldir gives you another.", when = { { test = "onquest", quests = { 94467 } }, { item = 6636, test = "has", negate = true } }, zone = 1432, goals = {
					{ kind = "turnin", quest = 94473, direct = true, note = "Braldir Ashmantle: a new Fire Sapta" },
				} },
				{ title = "The Shrine of Eternal Flame", tip = "Climb on past Braldir to the peak. Drink the Fire Sapta beside the rock statue there to see the Minor Manifestation of Fire (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with Rockbiter Weapon and Earth Shock. Its Glowing Ember drops every time.", zone = 1432, goals = {
					{ kind = "use", quest = 94467, objective = 1, item = 6636, map = 1432, x = 31.9, y = 64.5, note = "Fire Sapta, beside the statue" },
					{ kind = "collect", quest = 94467, objective = 1, item = 6655, note = "Glowing Ember: Minor Manifestation of Fire" },
				} },
				{ title = "The Brazier of the Dormant Flame", tip = "Click the Brazier of the Dormant Flame atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit Torch of Eternal Flame.", zone = 1432, goals = {
					{ kind = "turnin", quest = 94467, note = "Brazier of the Dormant Flame" },
					{ kind = "accept", quest = 94468 },
				} },
				{ title = "Bruegs Kindleborn", tip = "Back through the South Gate tunnel and up the trail to Bruegs' cave. Keep the Fire Totem in your bags for good: every fire totem needs it.", zone = 1426, goals = {
					{ kind = "turnin", quest = 94468, rewards = { { item = 5176 }, { item = 263412 } }, note = "Bruegs Kindleborn: Searing Totem, your Fire Totem and the Totem of Charged Flames" },
					{ kind = "train", classTrainer = true },
