		{
			id = "forever/class/shaman/call-of-fire-horde", title = "Call of Fire (Horde)", category = "Class", folder = "Shaman", faction = "Horde", classes = { "Shaman" }, levels = { 10, 13 }, zone = 1413, version = 1, revision = "4d0f0e3395e7e0050391a8a0f75eb3a3e610a384dff43ca5bbdcd5087f2e6721", keywords = { "Fire Totem", "Searing Totem", "Totem of Charged Flames", "Fire Sapta", "Call of Fire", "Swart", "Searn Firewarder", "Narm Skychaser", "Xanis Flameweaver", "Kranal Fiss", "Telf Joolam", "Fire Tar", "Reagent Pouch", "Glowing Ember", "Brazier of the Dormant Flame", "Torch of Eternal Flame", "Sessaria Skystride", "Olariaan Swiftburn", "Skypriest Faladiel", "Kuramaa", "Shrine of Flames", "Shaman", "class quest", "totem" }, rewards = { { item = 5176 }, { spell = 3599, name = "Searing Totem" }, { item = 263412 } }, why = "Your Fire Totem for every fire totem, Searing Totem with it, and Forever's Totem of Charged Flames.",
			steps = {
				{ title = "Swart", tip = "At 10 Swart, the shaman trainer on the east side of Razor Hill, sends you to Kranal Fiss in the Barrens. Already carry Searn Firewarder's letter from Orgrimmar? It goes to Kranal too: skip Swart.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 2983, optional = true, note = "Swart, Razor Hill" },
				} },
				{ title = "Narm Skychaser", tip = "At 10 Narm Skychaser, the shaman trainer in Bloodhoof Village, sends you to Kranal Fiss in the Barrens. Already carry Xanis Flameweaver's letter from Thunder Bluff? It goes to Kranal too: skip Narm.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 2984, optional = true, note = "Narm Skychaser, Bloodhoof Village" },
				} },
				{ title = "Kranal Fiss", tip = "Kranal Fiss is not in the Crossroads: take the road north from the Crossroads and fork east towards Durotar; past Grol'dom Farm he paces by a tall tower east of the road (from Durotar: over the Southfury bridge, past Far Watch Post). If you reach Ashenvale you went too far.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1413, goals = {
					{ kind = "goto", label = "Kranal Fiss", map = 1413, x = 56, y = 19.9 },
				} },
				{ only = { races = { "Orc", "Troll", "Tauren" } }, when = { { test = "onquest", quests = { 2983 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 2983, note = "Kranal Fiss: Swart's letter" },
				} },
				{ only = { races = { "Orc", "Troll", "Tauren" } }, when = { { test = "onquest", quests = { 1522 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1522, note = "Kranal Fiss: Searn Firewarder's letter" },
				} },
				{ only = { races = { "Orc", "Troll", "Tauren" } }, when = { { test = "onquest", quests = { 2984 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 2984, note = "Kranal Fiss: Narm Skychaser's letter" },
				} },
				{ only = { races = { "Orc", "Troll", "Tauren" } }, when = { { test = "onquest", quests = { 1523 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1523, note = "Kranal Fiss: Xanis Flameweaver's letter" },
				} },
				{ title = "Kranal Fiss", tip = "Kranal hands you the Torch of the Dormant Flame: keep it until the end of the chain.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1413, goals = {
					{ kind = "accept", quest = 1524 },
				} },
				{ title = "Telf Joolam", tip = "Back east over the bridge, then south along the Durotar bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. Telf Joolam keeps the shrine at the top.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1524, note = "Telf Joolam" },
					{ kind = "accept", quest = 1525 },
				} },
				{ title = "Fire Tar", tip = "The Razormane casters north-east of the Crossroads drop the Fire Tar three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1413, goals = {
					{ kind = "collect", quest = 1525, objective = 1, item = 5026, note = "Fire Tar" },
				} },
				{ title = "Reagent Pouch", tip = "The Burning Blade Cultists (level 10-11, they call imps and cast Immolate) live deep in Dustwind Cave north of Razor Hill: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. Skull Rock by Orgrimmar is the wrong cave.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1411, goals = {
					{ kind = "collect", quest = 1525, objective = 2, item = 6652, note = "Reagent Pouch" },
				} },
				{ title = "Telf Joolam", tip = "Back up the trail to Telf. He makes the Fire Sapta from the tar and the pouch and hands it to you with the torch: keep both.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1525, note = "Telf Joolam" },
					{ kind = "accept", quest = 1526 },
				} },
				{ title = "Lost the Fire Sapta?", tip = "Only if the Fire Sapta is gone from your bags: Telf gives you another.", only = { races = { "Orc", "Troll", "Tauren" } }, when = { { test = "onquest", quests = { 1526 } }, { item = 6636, test = "has", negate = true } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1464, direct = true, note = "Telf Joolam: a new Fire Sapta" },
				} },
				{ title = "The Minor Manifestation of Fire", tip = "Drink the Fire Sapta beside the Shaman Shrine, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with Rockbiter Weapon and Earth Shock and leave the others alone. Its Glowing Ember drops every time.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1411, goals = {
					{ kind = "use", quest = 1526, objective = 1, item = 6636, map = 1411, x = 38.1, y = 58.5, note = "Fire Sapta, beside the Shaman Shrine" },
					{ kind = "collect", quest = 1526, objective = 1, item = 6655, note = "Glowing Ember: Minor Manifestation of Fire" },
				} },
				{ title = "The Brazier of the Dormant Flame", tip = "Click the Brazier of the Dormant Flame on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit Torch of Eternal Flame.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1526, note = "Brazier of the Dormant Flame" },
					{ kind = "accept", quest = 1527 },
				} },
				{ title = "Kranal Fiss", tip = "Down the trail, back over the bridge to Kranal Fiss by his tower. Keep the Fire Totem in your bags for good: every fire totem needs it.", only = { races = { "Orc", "Troll", "Tauren" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1527, rewards = { { item = 5176 }, { item = 263412 } }, note = "Kranal Fiss: Searing Totem, your Fire Totem and the Totem of Charged Flames" },
				} },
				{ title = "Sessaria Skystride", tip = "At 10 Sessaria Skystride, the shaman trainer beside Ayessa Dawnsinger in Valanaar, hands you the Torch of the Dormant Flame (Aarnor Galestrike offers the same quest). Already left the isle? A Call of Fire sends you back to them: take the skycutter from the cliffs south of Skywatcher Plateau, north of Thunder Bluff. Learn Flame Shock from her now: Kuramaa, later in the chain, only takes fire damage.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 97243, note = "Sessaria Skystride" },
					{ kind = "train", classTrainer = true },
				} },
				{ title = "Olariaan Swiftburn", tip = "The Shrine of Flames hides on the island's outer rim south-west of Valanaar, just south-east of Windfield Orchard: Olariaan Swiftburn keeps it.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 97243, note = "Olariaan Swiftburn" },
					{ kind = "accept", quest = 97244 },
				} },
				{ title = "Skypriest Faladiel", tip = "Skypriest Faladiel (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past Valanaar, just south of the Shrine of Akir, on the hill west of the falls north of the East Pylon Watchtower. Kill him and take his heart.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "collect", quest = 97244, objective = 1, item = 277267, note = "Faladiel's Heart" },
				} },
				{ title = "Olariaan Swiftburn", tip = "Back to Olariaan at the Shrine of Flames.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 97244, note = "Olariaan Swiftburn" },
					{ kind = "accept", quest = 97245 },
				} },
				{ title = "Kuramaa", tip = "Kuramaa's Stump is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of Valanaar, in the hills south of the Windsong Crawlers' lakes. Knock on it to call Kuramaa (level 10). The spirit shrugs off most magic: only fire hurts it, so keep Flame Shock on it. Take its wooden mask.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "interact", object = 660848, note = "Kuramaa's Stump: knock on the bark" },
					{ kind = "collect", quest = 97245, objective = 1, item = 277269, note = "Kuramaa's Mask" },
				} },
				{ title = "The Eternal Flame", tip = "Back to Olariaan. Accept the last quest, then wait by the Brazier of Offering while he performs the ritual; when the fire spirits light the Eternal Flame, hold the torch to it. From then you have six minutes: carry the flame straight to the Brazier of Eternal Flame beside Sessaria in Valanaar, with no detours or fights. Timer out? Abandon the quest and take it again from Olariaan.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 97245, note = "Olariaan Swiftburn" },
					{ kind = "accept", quest = 97257 },
					{ kind = "goto", label = "Brazier of Offering", map = 2521, x = 51.2, y = 85.9 },
					{ kind = "complete", quest = 97257, map = 2521, x = 58.4, y = 78.8, note = "the ritual, then the Brazier of Eternal Flame in Valanaar" },
				} },
				{ title = "Sessaria Skystride", tip = "Keep the Fire Totem in your bags for good: every fire totem needs it.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 97257, rewards = { { item = 5176 }, { item = 263412 } }, note = "Sessaria Skystride: Searing Totem, your Fire Totem and the Totem of Charged Flames" },
				} },
			},
		},
		{
			id = "forever/class/shaman/call-of-water-alliance", title = "Call of Water (Alliance)", category = "Class", folder = "Shaman", faction = "Alliance", classes = { "Shaman" }, levels = { 20, 23 }, zone = 1455, version = 1, revision = "b9a8cfabafba0913484f15a857d45ef1ee6b340a802d882406f001aae2433269", legacyRevision = "813e763d81f0dc71dcfff5ecdf80d4522ea8deea864e92747a1fdec55a2c58e5", keywords = { "Water Totem", "Healing Stream Totem", "Water Sapta", "Eldrun Stormbreaker", "Norric Lochthane", "Hervdana Saegrund", "waterskin", "Stonewatch Falls", "Astranaar", "Stendel's Pond", "Forgotten Shrine", "Minor Manifestation of Water", "Shaman", "class quest", "totem" }, rewards = { { item = 5177 }, { spell = 5394, name = "Healing Stream Totem" }, { item = 6637 } }, why = "The Water Totem that lets you place water totems, and Healing Stream Totem with it.",
			steps = {
				{ title = "Eldrun Stormbreaker", tip = "At 20 Eldrun Stormbreaker, the shaman trainer in Ironforge's Mystic Ward, sends you to Norric Lochthane in Loch Modan.", zone = 1455, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 94494, note = "Eldrun Stormbreaker" },
				} },
				{ title = "Norric Lochthane", tip = "Norric's burrow hut stands on the north-western shore of the loch, below Stonewrought Dam, north of Thelsamar.", zone = 1432, goals = {
					{ kind = "turnin", quest = 94494, note = "Norric Lochthane" },
					{ kind = "accept", quest = 94495 },
				} },
				{ title = "Hervdana Saegrund", tip = "Hervdana's family lives in a cave beneath the southern falls of the Wetlands, east of Dun Algaz: not in a town. Through the Algaz tunnel north of Loch Modan, then east off the road.", zone = 1437, goals = {
					{ kind = "turnin", quest = 94495, note = "Hervdana Saegrund" },
					{ kind = "accept", quest = 94497 },
				} },
				{ title = "The brown waterskin", tip = "Fill the Unfilled Brown Waterskin at the bottom of the waterfalls below Hervdana's cave, where the fresh water meets the brackish. Dark Iron dwarves roam near the falls.", zone = 1437, goals = {
					{ kind = "collect", quest = 94497, objective = 1, item = 265734, map = 1437, x = 65.8, y = 76.5, note = "Full Brown Waterskin" },
				} },
				{ title = "Hervdana Saegrund", zone = 1437, goals = {
					{ kind = "turnin", quest = 94497, note = "Hervdana Saegrund" },
					{ kind = "accept", quest = 94499 },
				} },
				{ title = "The red waterskin", tip = "Stonewatch Falls pour out of Lake Everstill at the east end of Redridge (fly from Ironforge to Lakeshire). Fill the Unfilled Red Waterskin at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from Hervdana for a new one.", zone = 1433, goals = {
					{ kind = "collect", quest = 94499, objective = 1, item = 265748, map = 1433, x = 71.9, y = 60.3, note = "Full Red Waterskin" },
				} },
				{ title = "Hervdana Saegrund", zone = 1437, goals = {
					{ kind = "turnin", quest = 94499, note = "Hervdana Saegrund" },
					{ kind = "accept", quest = 94500 },
				} },
				{ title = "The blue waterskin", tip = "Take the boat from Menethil Harbor to Auberdine (it stops in Southshore on the way), then fly or walk south through Darkshore to Astranaar in Ashenvale. Fill the Unfilled Blue Waterskin in the lake around the town, then the boat back to Menethil.", zone = 1440, goals = {
					{ kind = "collect", quest = 94500, objective = 1, item = 265773, map = 1440, x = 34.5, y = 48, note = "Full Blue Waterskin" },
				} },
				{ title = "Hervdana Saegrund", zone = 1437, goals = {
					{ kind = "turnin", quest = 94500, note = "Hervdana Saegrund" },
					{ kind = "accept", quest = 94501, note = "the Vial of Purest Water, for Norric" },
				} },
				{ title = "Norric Lochthane", tip = "Back to Norric by Stonewrought Dam with the Vial of Purest Water. He hands you the Water Sapta and the Remaining Drops of Purest Water: keep both for Westfall.", zone = 1432, goals = {
					{ kind = "turnin", quest = 94501, rewards = { { item = 6637 } }, note = "Norric Lochthane: your Water Sapta" },
					{ kind = "accept", quest = 94502 },
				} },
				{ title = "Lost the Water Sapta?", tip = "Only if the Water Sapta is gone from your bags: Norric gives you another before you leave for Westfall.", when = { { test = "onquest", quests = { 94502 } }, { item = 6637, test = "has", negate = true } }, zone = 1432, goals = {
					{ kind = "accept", quest = 94616 },
					{ kind = "turnin", quest = 94616, note = "Norric Lochthane: a new Water Sapta" },
				} },
				{ title = "Stendel's Pond", tip = "Fly to Sentinel Hill and head south to Moonbrook: Stendel's Pond and the Forgotten Shrine lie just north of it. Drink the Water Sapta by the shrine to see the Corrupt Minor Manifestation of Water (level 22, Frost Shock and Frost Nova; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the Remaining Drops of Purest Water on the Forgotten Shrine (this, not Norric, ends the quest). Click the shrine again: the Minor Manifestation of Water rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the Shard of Water.", zone = 1436, goals = {
					{ kind = "use", quest = 94502, objective = 1, item = 6637, map = 1436, x = 45.6, y = 59.9, note = "Water Sapta" },
					{ kind = "collect", quest = 94502, objective = 1, item = 7812, map = 1436, x = 45.6, y = 59.9, note = "Corrupt Manifestation's Bracers" },
					{ kind = "turnin", quest = 94502, note = "Forgotten Shrine" },
					{ kind = "accept", quest = 94503 },
					{ kind = "turnin", quest = 94503, map = 1436, x = 46.4, y = 59.2, note = "Minor Manifestation of Water, beside the shrine" },
					{ kind = "accept", quest = 94505, map = 1436, x = 46.4, y = 59.2 },
				} },
				{ title = "Norric Lochthane", tip = "Back to Norric with the Shard of Water. Keep the Water Totem in your bags for good: every water totem needs it.", zone = 1432, goals = {
					{ kind = "turnin", quest = 94505, rewards = { { item = 5177 } }, note = "Norric Lochthane: Healing Stream Totem and your Water Totem" },
				} },
			},
		},
		{
			id = "forever/class/shaman/call-of-water-horde", title = "Call of Water (Horde)", category = "Class", folder = "Shaman", faction = "Horde", classes = { "Shaman" }, levels = { 20, 23 }, zone = 1454, version = 1, revision = "51b52e389db21bbd50eb226887e9c73f532a2c23004378ed4f499f65b7f2da07", legacyRevision = "43756d6be21dabe7adbdef63dafd8dc900977248752104c0bd0e2a20f3b4f224", keywords = { "Water Totem", "Healing Stream Totem", "Water Sapta", "Searn Firewarder", "Xanis Flameweaver", "Swart", "Narm Skychaser", "Islen Waterseer", "Brine", "waterskin", "Quilboar Watering Hole", "Spring Well", "Ruins of Stardust", "Brazier of Everfount", "Minor Manifestation of Water", "Tiev Mordune", "Shaman", "class quest", "totem" }, rewards = { { item = 5177 }, { spell = 5394, name = "Healing Stream Totem" }, { item = 6637 } }, why = "The Water Totem that lets you place water totems, and Healing Stream Totem with it.",
			steps = {
				{ title = "Searn Firewarder", tip = "At 20 Searn Firewarder in the Valley of Wisdom sends you to Islen Waterseer in the Barrens. (Swart in Razor Hill gives the same letter: carry either.)", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1528, optional = true, note = "Searn Firewarder" },
				} },
				{ title = "Xanis Flameweaver", tip = "At 20 Xanis Flameweaver, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to Islen Waterseer in the Barrens. (Narm Skychaser in Bloodhoof Village gives the same letter: carry either.)", only = { races = { "Tauren", "Skyborne" } }, zone = 1456, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1529, optional = true, note = "Xanis Flameweaver" },
				} },
				{ title = "Islen Waterseer", tip = "Islen is not in Ratchet: take the small coast road south from Ratchet past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far.", zone = 1413, goals = {
					{ kind = "goto", label = "Islen Waterseer", map = 1413, x = 65.8, y = 43.8 },
				} },
				{ when = { { test = "onquest", quests = { 1528 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1528, note = "Islen Waterseer: Searn's letter" },
				} },
				{ when = { { test = "onquest", quests = { 1529 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1529, note = "Islen Waterseer: Xanis' letter" },
				} },
				{ when = { { test = "onquest", quests = { 2985 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 2985, note = "Islen Waterseer: Swart's letter" },
				} },
				{ when = { { test = "onquest", quests = { 2986 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 2986, note = "Islen Waterseer: Narm's letter" },
				} },
				{ title = "Islen Waterseer", zone = 1413, goals = {
					{ kind = "accept", quest = 1530 },
				} },
				{ title = "Brine", tip = "Brine lives in the southern Barrens, south of Camp Taurajo: her hut sits on a hilltop of Blackthorn Ridge with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1530, note = "Brine" },
					{ kind = "accept", quest = 1535 },
				} },
				{ title = "The Quilboar Watering Hole", tip = "The muddy pond below Brine's hut. Step right into the puddle before you use the Empty Brown Waterskin (too far away and it refuses). Filling it calls a hostile Razormane Pathfinder (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards.", zone = 1413, goals = {
					{ kind = "use", quest = 1535, objective = 1, item = 7766, map = 1413, x = 44.3, y = 76.8, note = "Empty Brown Waterskin, standing in the puddle" },
					{ kind = "collect", quest = 1535, objective = 1, item = 7769, note = "Filled Brown Waterskin" },
				} },
				{ title = "Brine", zone = 1413, goals = {
					{ kind = "turnin", quest = 1535, note = "Brine" },
					{ kind = "accept", quest = 1536 },
				} },
				{ title = "The Spring Well", tip = "The Spring Well stands in the middle of Tarren Mill, just outside the church. From the Barrens: the zeppelin from Orgrimmar to Tirisfal Glades, then south past the Undercity and through Silverpine Forest (or fly once you have the Tarren Mill flight path). Hillsbrad is contested: Alliance players may attack. Stand beside the well and use the Empty Red Waterskin.", zone = 1424, goals = {
					{ kind = "use", quest = 1536, objective = 1, item = 7768, map = 1424, x = 62.2, y = 20.8, note = "Empty Red Waterskin, beside the well" },
					{ kind = "collect", quest = 1536, objective = 1, item = 7771, note = "Filled Red Waterskin" },
				} },
				{ title = "Brine", zone = 1413, goals = {
					{ kind = "turnin", quest = 1536, note = "Brine" },
					{ kind = "accept", quest = 1534 },
				} },
				{ title = "The Ruins of Stardust", tip = "The right fountain stands in a ring of standing stones on the island of the small green lake south of Astranaar, west of Lake Mystral (not the island in Lake Mystral itself). From the Barrens take the road north through the Mor'shan Rampart and on west. Water elementals and walking treants guard the lake and root you in place; an elite Wandering Protector roams Ashenvale and can pass close by. Use the Empty Blue Waterskin beside the fountain.", zone = 1440, goals = {
					{ kind = "use", quest = 1534, objective = 1, item = 7767, map = 1440, x = 33.6, y = 67.5, note = "Empty Blue Waterskin, beside the fountain" },
					{ kind = "collect", quest = 1534, objective = 1, item = 7770, note = "Filled Blue Waterskin" },
				} },
				{ title = "Brine", tip = "Back to Brine. She gives you the Vial of Purest Water for Islen.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1534, note = "Brine" },
					{ kind = "accept", quest = 220, note = "the Vial of Purest Water, for Islen" },
				} },
				{ title = "Islen Waterseer", tip = "Islen hands you the Water Sapta and the Remaining Drops of Purest Water: take everything she offers before you leave for Silverpine, or you will be back for more.", zone = 1413, goals = {
					{ kind = "turnin", quest = 220, rewards = { { item = 6637 } }, note = "Islen Waterseer: your Water Sapta" },
					{ kind = "accept", quest = 63 },
				} },
				{ title = "Lost the Water Sapta?", tip = "Only if the Water Sapta is gone from your bags: Islen gives you another.", when = { { test = "onquest", quests = { 63 } }, { item = 6637, test = "has", negate = true } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 972, direct = true, note = "Islen Waterseer: a new Water Sapta" },
				} },
				{ title = "The Brazier of Everfount", tip = "Fly to the Sepulcher. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the Water Sapta beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The Corrupt Minor Manifestation of Water is level 22 and casts Frost Shock and Frost Nova; if someone just killed it, it is back in about three minutes. Its bracers always drop.", zone = 1421, goals = {
					{ kind = "use", quest = 63, objective = 1, item = 6637, map = 1421, x = 38.3, y = 44.6, note = "Water Sapta, beside the standing stone" },
					{ kind = "collect", quest = 63, objective = 1, item = 7812, note = "Corrupt Manifestation's Bracers" },
				} },
				{ title = "The Minor Manifestation of Water", tip = "Click the Brazier of Everfount to place the bracers and the drops. A few seconds later the pure Minor Manifestation of Water rises on the stone in the middle of the pool: speak to it while the Sapta Sight lasts (drink again by the stone if it has worn off). It gives you the Shard of Water for Islen. Gone before you could speak to it? Back at Islen ask for Call of Water (a fresh Water Sapta for Tiev Mordune, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it.", zone = 1421, goals = {
					{ kind = "turnin", quest = 63, note = "Brazier of Everfount" },
					{ kind = "accept", quest = 100 },
					{ kind = "turnin", quest = 100, note = "Minor Manifestation of Water" },
					{ kind = "accept", quest = 96 },
				} },
				{ title = "Islen Waterseer", tip = "Back to Islen south of Ratchet. Keep the Water Totem in your bags for good: every water totem needs it.", zone = 1413, goals = {
					{ kind = "turnin", quest = 96, rewards = { { item = 5177 } }, note = "Islen Waterseer: Healing Stream Totem and your Water Totem" },
				} },
			},
		},
		{
			id = "forever/class/shaman/darkreaver", title = "The Darkreaver Menace", category = "Class", folder = "Shaman", faction = "Horde", classes = { "Shaman" }, levels = { 58, 60 }, zone = 1454, version = 1, revision = "a295b6bb338613fdde6027f0b4b1c2d4376ef414f7d1c7bc41e62645f0fbddff", legacyRevision = "5cd9a301c80b3ce29c0899a23e2c9556e424704e39d4c775b177047f9086fde8", keywords = { "Material Assistance", "The Darkreaver Menace", "Sagorne Creststrider", "Azerothian Diamond", "Pristine Black Diamond", "Divination Scryer", "Death Knight Darkreaver", "Great Ossuary", "Scholomance", "Skyfury Helm", "Shaman", "class quest" }, rewards = { { text = "200 Horde reputation" } }, why = "A Scholomance fight at 60 for Horde reputation; the Skyfury Helm may be gone in Forever.",
			steps = {
				{ title = "Sagorne Creststrider", tip = "At 58 Sagorne Creststrider, the shaman trainer in the Valley of Wisdom, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds.", zone = 1454, goals = {
					{ kind = "accept", quest = 7667, note = "Sagorne Creststrider" },
				} },
				{ title = "Two diamonds", tip = "Both diamonds are rare: the auction house is the quick way. Miners find the Azerothian Diamond in about one Thorium vein in a hundred (the Small Thorium Veins north of Morgan's Vigil in the Burning Steppes respawn every five minutes). The Pristine Black Diamond drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine).", zone = 1422, goals = {
					{ kind = "collect", quest = 7667, objective = 1, item = 12800, note = "Azerothian Diamond" },
					{ kind = "collect", quest = 7667, objective = 2, item = 18335, note = "Pristine Black Diamond" },
				} },
				{ title = "Sagorne Creststrider", tip = "The Darkreaver Menace needs level 60.", zone = 1454, goals = {
					{ kind = "turnin", quest = 7667, note = "Sagorne Creststrider" },
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 8258, note = "he hands you the Divination Scryer" },
				} },
				{ title = "The Great Ossuary", tip = "A five-player dungeon event: Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands. In the Great Ossuary's basement, first clear every mob in the room, then use the Divination Scryer at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then Death Knight Darkreaver (level 62 elite) appears: he Cleaves, casts Shadow Bolt and Blood Leech, and Dominates a player's mind against the group. His head always drops.", zone = 1422, goals = {
					{ kind = "collect", quest = 8258, objective = 1, item = 18880, map = 1422, x = 68.9, y = 75.2, group = 5, note = "Darkreaver's Head" },
				} },
				{ title = "Sagorne Creststrider", zone = 1454, goals = {
					{ kind = "turnin", quest = 8258, note = "Sagorne Creststrider: 200 Horde reputation; the Skyfury Helm may be gone" },
				} },
			},
		},
		{
			id = "forever/class/shaman/spirit-totem", title = "Spirit Totem and Da Voodoo", category = "Class", folder = "Shaman", faction = "Horde", classes = { "Shaman" }, levels = { 50, 52 }, zone = 1454, version = 1, revision = "3043f70ad23983d9604e8412bab0cf324418a883e58c48d077792db8b9d02d2c", legacyRevision = "c07f959f02b285f287bf2ebd40d2a88fefd685967fb0d176b2b92628da9b462e", keywords = { "Elemental Mastery", "Mastering the Elements", "Spirit Totem", "Da Voodoo", "Bath'rah the Windwatcher", "Elemental Air", "Elemental Fire", "Elemental Earth", "Elemental Water", "Bloodshot Spider Eye", "Thick Black Claw", "Voodoo Feather", "Sunken Temple", "Temple of Atal'Hakkar", "Shaman", "class quest" }, rewards = { { text = "Experience and gold" } }, why = "Experience and gold at 50, ending in the Sunken Temple; the Classic item choice may be gone in Forever.",
			steps = {
				{ title = "Sagorne Creststrider", tip = "At 50 Sagorne Creststrider, the shaman trainer in the Valley of Wisdom, asks for the four elements for Bath'rah the Windwatcher.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8410, npc = 13417, note = "Sagorne Creststrider" },
				} },
				{ title = "Beram Skychaser", tip = "At 50 Beram Skychaser, a shaman trainer on Spirit Rise in Thunder Bluff, asks for the four elements for Bath'rah the Windwatcher. Skyborne: Forever's quest page lists Elemental Mastery and Spirit Totem for Orcs, Tauren and Trolls only; if Beram has nothing for you, Bath'rah's own Mastering the Elements is open to every Horde race, but Spirit Totem after it may still turn you away.", only = { races = { "Tauren", "Skyborne" } }, zone = 1456, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8410, npc = 3032, note = "Beram Skychaser" },
				} },
				{ title = "The four elements", tip = "One each of Elemental Air, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, Arathi Highlands has the exiles near Refuge Pointe (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the Summoned Guardian far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in Azshara (two in five) or Seeker Aqualon by Lakeshire in Redridge.", zone = 1417, goals = {
					{ kind = "collect", quest = 8410, objective = 1, item = 7069, note = "Elemental Air: Thundering Exiles" },
					{ kind = "collect", quest = 8410, objective = 2, item = 7068, note = "Elemental Fire: Burning Exiles" },
					{ kind = "collect", quest = 8410, objective = 3, item = 7067, note = "Elemental Earth: Rumbling Exiles" },
					{ kind = "collect", quest = 8410, objective = 4, item = 7070, note = "Elemental Water: the Summoned Guardian, or Azshara's water patches" },
				} },
				{ title = "Bath'rah the Windwatcher", tip = "Bath'rah camps in the ruins of the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills.", zone = 1416, goals = {
					{ kind = "turnin", quest = 8410, note = "Bath'rah the Windwatcher" },
					{ kind = "accept", quest = 8412 },
				} },
				{ title = "Spider eye and bear claw", tip = "Eight of each. Fly or ride to the Bulwark and on to the west edge of the Western Plaguelands, north-west of Chillwind Camp: the Venom Mist Lurkers (level 50-51, they poison) give the Bloodshot Spider Eye and the Diseased Black Bears (level 51-52, Infected Wound) the Thick Black Claw, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of Brill in Tirisfal.", zone = 1422, goals = {
					{ kind = "collect", quest = 8412, objective = 1, item = 20610, count = 8, note = "Bloodshot Spider Eye" },
					{ kind = "collect", quest = 8412, objective = 2, item = 20611, count = 8, note = "Thick Black Claw" },
				} },
				{ title = "Bath'rah the Windwatcher", zone = 1416, goals = {
					{ kind = "turnin", quest = 8412, note = "Bath'rah the Windwatcher" },
					{ kind = "accept", quest = 8413 },
				} },
				{ title = "The Sunken Temple", tip = "A five-player dungeon: needs a group of five, about level 50-55. Fly to Stonard and ride east. The Sunken Temple (Temple of Atal'Hakkar) stands in the middle of the Pool of Tears: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others (Renew, a Healing Ward): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys.", zone = 1435, goals = {
					{ kind = "collect", quest = 8413, objective = 1, item = 20606, count = 2, map = 1435, x = 69.9, y = 53.6, note = "Amber Voodoo Feather: Gasher, Zul'Lor" },
					{ kind = "collect", quest = 8413, objective = 2, item = 20607, count = 2, map = 1435, x = 69.9, y = 53.6, note = "Blue Voodoo Feather: Hukku, Mijan" },
					{ kind = "collect", quest = 8413, objective = 3, item = 20608, count = 2, map = 1435, x = 69.9, y = 53.6, note = "Green Voodoo Feather: Zolo, Loro" },
				} },
				{ title = "Bath'rah the Windwatcher", zone = 1416, goals = {
					{ kind = "turnin", quest = 8413, note = "Bath'rah the Windwatcher: the old item choice may be gone, count on the experience" },
				} },
			},
		},
		{
			id = "forever/class/warlock/dread-mage-hat", title = "Dread Mage Hat", category = "Class", folder = "Warlock", faction = "Alliance", races = { "Human", "Gnome" }, classes = { "Warlock" }, levels = { 25, 30 }, zone = 1453, version = 1, revision = "1dbbfe9272318729a04aedffadc5667802a01a8d756337bef65ae24de86b9014", keywords = { "A Noble Brew", "You Have Served Us Well", "Zardeth of the Black Claw", "Zggi", "Lord Baurles K. Wishock", "Tear of Tilloa", "Musquash Root", "Black Claw Stout", "Dread Mage Hat", "Slaughtered Lamb", "Duskwood", "Wetlands", "Warlock", "class armor" }, rewards = { { item = 3556 } }, why = "A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra.",
			steps = {
				{ title = "Zardeth of the Black Claw", tip = "At 25 Zardeth of the Black Claw, in the cellar of the Slaughtered Lamb in the Mage Quarter (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to Duskwood and the Wetlands.", zone = 1453, goals = {
					{ kind = "level", level = 25 },
					{ kind = "accept", quest = 335, note = "Zardeth of the Black Claw" },
				} },
				{ title = "Tear of Tilloa", tip = "Manor Mistmantle stands in the north-east of Duskwood, north of Darkshire. The Tear of Tilloa is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. Stalvan Mistmantle (32) is inside the house; leave him alone.", zone = 1431, goals = {
					{ kind = "collect", quest = 335, objective = 1, item = 2779, note = "Tear of Tilloa" },
				} },
				{ title = "Musquash Root", tip = "The root grows at the water's edge in the pool below the small falls east of Dun Algaz, beside the Dark Iron cave below the Stonewrought Dam: a tall, spiky wooden root, not at the foot of the dam itself.", zone = 1437, goals = {
					{ kind = "collect", quest = 335, objective = 2, item = 2784, note = "Musquash Root" },
				} },
				{ title = "A Noble Brew", tip = "Back to Zardeth. He brews the Black Claw Stout and gives it to you for Lord Baurles K. Wishock in the Hall of Petitioners, the first hall on the right inside Stormwind Keep.", zone = 1453, goals = {
					{ kind = "turnin", quest = 335, note = "Zardeth of the Black Claw" },
					{ kind = "accept", quest = 336 },
					{ kind = "turnin", quest = 336, note = "Lord Baurles K. Wishock, Stormwind Keep" },
				} },
				{ title = "You Have Served Us Well", tip = "Back to Zardeth once more: he offers warlocks a reward, which his imp Zggi, standing beside him, hands over.", zone = 1453, goals = {
					{ kind = "accept", quest = 397, note = "Zardeth of the Black Claw" },
					{ kind = "turnin", quest = 397, note = "Zggi: Dread Mage Hat" },
				} },
			},
		},
		{
			id = "forever/class/warlock/enchanted-gold-bloodrobe", title = "Enchanted Gold Bloodrobe", category = "Class", folder = "Warlock", classes = { "Warlock" }, levels = { 31, 38 }, zone = 1413, version = 1, revision = "805d77576fd811387415d46911e3b41a006f71038b1b01def3b73698e0fc7508", legacyRevision = "704885a6c4d5f6dd5bc7cd053d86ee49c12a8173a309b6db36a706113df0ad80", keywords = { "In Search of Menara Voidrender", "Components for the Enchanted Gold Bloodrobe", "Fine Gold Thread", "The Completed Robe", "Menara Voidrender", "Xizk Goodstitch", "Robes of Arcana", "Gold Bar", "Vial of Hatefury Blood", "Lesser Infernal Stone", "Smoldering Coal", "Burning Exile", "Sargeron", "Mannoroc Coven", "Circle of West Binding", "Warlock", "class armor" }, rewards = { { item = 6900 } }, why = "A rare cloth robe for your 30s from Menara Voidrender; its last parts wait for levels 35 and 37.",
			steps = {
				{ title = "In Search of Menara Voidrender (Stormwind)", tip = "At 31 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Menara Voidrender in Ratchet. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "level", level = 31 },
					{ kind = "accept", quest = 4738, note = "Demisette Cloyce" },
				} },
				{ title = "In Search of Menara Voidrender (Ironforge)", tip = "At 31 Briarthorn in Ironforge sends you to Menara Voidrender in Ratchet. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 31 },
					{ kind = "accept", quest = 4736, note = "Briarthorn" },
				} },
				{ title = "In Search of Menara Voidrender (Orgrimmar)", tip = "At 31 Zevrost in the Cleft of Shadow sends you to Menara Voidrender in Ratchet. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 31 },
					{ kind = "accept", quest = 4737, note = "Zevrost" },
				} },
				{ title = "In Search of Menara Voidrender (Undercity)", tip = "At 31 Kaal Soulreaper in the Magic Quarter sends you to Menara Voidrender in Ratchet; the zeppelin from Tirisfal Glades flies to Durotar. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "level", level = 31 },
					{ kind = "accept", quest = 4739, note = "Kaal Soulreaper" },
				} },
				{ title = "Robes of Arcana and a Gold Bar", tip = "Tailors sew the Robes of Arcana from a rare pattern; miners smelt Gold Bars from Gold Ore. Everyone else buys both at the Auction House. If you wear the robe, take it off: Menara keeps it.", zone = 1458, goals = {
					{ kind = "collect", item = 5770, map = 1453, x = 61.2, y = 71.3, frame = "live", only = { factions = { "Alliance" } }, note = "Robes of Arcana: the Auction House" },
					{ kind = "collect", item = 5770, map = 1454, x = 55.9, y = 62.7, only = { factions = { "Horde" } }, note = "Robes of Arcana: the Auction House" },
					{ kind = "collect", item = 3577, map = 1453, x = 61.2, y = 71.3, frame = "live", only = { factions = { "Alliance" } }, note = "Gold Bar: the Auction House" },
					{ kind = "collect", item = 3577, map = 1454, x = 55.9, y = 62.7, only = { factions = { "Horde" } }, note = "Gold Bar: the Auction House" },
				} },
				{ title = "Menara Voidrender", tip = "Menara Voidrender stands by Strahad Farsan's tower on the hill above Ratchet, behind the engineers' hut. She takes the robe, then sends the gold bar to Xizk Goodstitch in Booty Bay.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4738, only = { races = { "Human" } }, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4736, only = { races = { "Gnome" } }, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4737, only = { races = { "Orc", "Troll" } }, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4739, only = { races = { "Scourge" } }, note = "Menara Voidrender" },
					{ kind = "accept", quest = 1796 },
					{ kind = "turnin", quest = 1796, note = "Menara Voidrender" },
					{ kind = "accept", quest = 4781 },
				} },
				{ title = "Xizk Goodstitch", tip = "The boat from Ratchet sails to Booty Bay. Xizk Goodstitch runs A Tailor to Cities on an upper level of the town. Give him the Gold Bar; he will spin the thread later.", zone = 1434, goals = {
					{ kind = "turnin", quest = 4781, note = "Xizk Goodstitch" },
					{ kind = "accept", quest = 4782 },
				} },
				{ title = "Back to Menara", tip = "You need no thread yet: Menara wants demon parts from Desolace next.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4782, note = "Menara Voidrender" },
					{ kind = "accept", quest = 4783 },
				} },
				{ title = "Hatefury satyrs", tip = "The Hatefury satyrs (level 31-32) hold Sargeron in the far north-east of Desolace, past Nijel's Point: two kills in five give a vial, so plan on about 25.", zone = 1443, goals = {
					{ kind = "collect", quest = 4783, objective = 1, item = 6989, count = 10, note = "Vials of Hatefury Blood" },
				} },
				{ title = "Mannoroc Coven", tip = "The Lesser Infernals (36-37) and Demon Portal Guardians (38) of Mannoroc Coven, in the south of Desolace, drop the stone half the time. The guide waits for level 35 first: at 31 they are too strong to solo. They resist fire, so use Shadow Bolt and Corruption.", zone = 1443, goals = {
					{ kind = "level", level = 35 },
					{ kind = "collect", quest = 4783, objective = 2, item = 6990, note = "Lesser Infernal Stone" },
				} },
				{ title = "Menara again", zone = 1413, goals = {
					{ kind = "turnin", quest = 4783, note = "Menara Voidrender" },
					{ kind = "accept", quest = 4784 },
				} },
				{ title = "Fine Gold Thread", tip = "Back to Xizk in Booty Bay: he offers Fine Gold Thread as a quest you hand straight back to him. He may show no quest marker; talk to him anyway.", zone = 1434, goals = {
					{ kind = "turnin", quest = 4785, direct = true, note = "Xizk Goodstitch: Fine Gold Thread, handed straight back" },
					{ kind = "collect", quest = 4784, objective = 1, item = 12293, note = "Fine Gold Thread" },
				} },
				{ title = "Smoldering Coal", tip = "The Burning Exiles (level 38-39), fire elementals at the Circle of West Binding in western Arathi Highlands, drop the coal about one time in three. The guide waits for level 37 first: below it they hit too hard to solo. They resist fire: Shadow Bolt and Corruption. The Cresting Charms from the Cresting Exiles near Hammerfall finish one off once you have hurt it. Make a Soul Shard with Drain Soul on the way.", zone = 1417, goals = {
					{ kind = "level", level = 37 },
					{ kind = "collect", quest = 4784, objective = 2, item = 6991, count = 2, note = "Smoldering Coal" },
					{ kind = "collect", quest = 4784, objective = 3, item = 6265, map = 1417, x = 24.9, y = 30.5, note = "Soul Shard: Drain Soul on an Exile as it dies" },
				} },
				{ title = "The Completed Robe", tip = "Back to Menara with the thread, the coals and a Soul Shard. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4784, note = "Menara Voidrender" },
					{ kind = "accept", quest = 4786 },
					{ kind = "complete", quest = 4786, map = 1413, x = 62.5, y = 35.4, note = "Wait beside Menara while she finishes the robe" },
					{ kind = "turnin", quest = 4786, note = "Menara Voidrender: Enchanted Gold Bloodrobe" },
				} },
			},
		},
		{
			id = "forever/class/warlock/felhunter-alliance", title = "Felhunter (Alliance)", category = "Class", folder = "Warlock", faction = "Alliance", classes = { "Warlock" }, levels = { 30, 33 }, zone = 1413, version = 1, revision = "684ad08913abd8a5ed3be9318b7a3d433f8a240566d9224e8e0a7b2c01083c85", legacyRevision = "9745c8a29d72fbf101f1266dbd267c68c70a040c8b2263f3ebc0c8d5d35aff55", keywords = { "Summon Felhunter", "Tome of the Cabal", "Seeking Strahad", "Strahad Farsan", "Krom Stoutarm", "Moldy Tome", "Tattered Manuscript", "Damaged Chest", "Rod of Channeling", "Reconstructed Tome", "Dragonmaw Bonewarder", "Dragonmaw Shadowwarder", "Angerfang Encampment", "The Binding", "Box of Souls", "Warlock", "class pet" }, rewards = { { spell = 691, name = "Summon Felhunter" }, { item = 22244 } }, why = "The felhunter, the demon to bring against spellcasters, and a Box of Souls for your shards.",
			steps = {
				{ title = "Seeking Strahad (Stormwind)", tip = "At 30 Gakin the Darkbinder, in the cellar of the Slaughtered Lamb in the Mage Quarter, sends you to Strahad Farsan in Ratchet.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 1798, npc = 6122, note = "Gakin the Darkbinder" },
				} },
				{ title = "Seeking Strahad (Ironforge)", tip = "At 30 Lago Blackwrench, in the Forlorn Cavern, sends you to Strahad Farsan in Ratchet.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 1798, npc = 6120, note = "Lago Blackwrench" },
				} },
				{ title = "Strahad Farsan", tip = "Ratchet is a neutral goblin port on the Barrens coast: the boat from Booty Bay docks there. Strahad Farsan stands on the hill above the town, behind the engineers' hut, by his little tower; Menara Voidrender and two acolytes are with him. He sends you to Krom Stoutarm in Ironforge.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1798, note = "Strahad Farsan" },
					{ kind = "accept", quest = 1758 },
				} },
				{ title = "Krom Stoutarm", tip = "Krom Stoutarm is in the library of the Hall of Explorers. He wants two lost pieces of the Tome of the Cabal: one on the Hillsbrad coast, one in Thousand Needles.", zone = 1455, goals = {
					{ kind = "turnin", quest = 1758, note = "Krom Stoutarm" },
					{ kind = "accept", quest = 1802 },
				} },
				{ title = "Moldy Tome", tip = "The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of Southshore, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor.", zone = 1424, goals = {
					{ kind = "collect", quest = 1802, objective = 1, item = 6931, note = "Moldy Tome, from the Tome of the Cabal on the sand" },
				} },
				{ title = "Tattered Manuscript", tip = "The centaur cave opens in the cliffs north of Freewind Post, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out.", zone = 1441, goals = {
					{ kind = "collect", quest = 1802, objective = 2, item = 6997, note = "Tattered Manuscript, in the Damaged Chest" },
				} },
				{ title = "Back to Krom", tip = "Krom pieces the tome together and gives you the Reconstructed Tome: keep it, Strahad takes it with the rods.", zone = 1455, goals = {
					{ kind = "turnin", quest = 1802, note = "Krom Stoutarm" },
					{ kind = "accept", quest = 1804 },
				} },
				{ title = "Rods of Channeling", tip = "The Dragonmaw hold Angerfang Encampment in the hills east of the road from Menethil Harbor to Dun Algaz. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors.", zone = 1437, goals = {
					{ kind = "collect", quest = 1804, objective = 1, item = 6930, count = 3, note = "Rods of Channeling, from the Dragonmaw casters" },
				} },
				{ title = "The Binding", tip = "Back to Strahad in Ratchet. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the Tome of the Cabal on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon The Binding and take it again from Strahad. Keep the tome: Strahad takes it back.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1804, note = "Strahad Farsan" },
					{ kind = "accept", quest = 1795 },
					{ kind = "use", item = 6999, map = 1413, x = 62.6, y = 35.3, note = "Tome of the Cabal, on the circle" },
					{ kind = "kill", quest = 1795, objective = 1, npc = 6268, note = "Summoned Felhunter" },
					{ kind = "turnin", quest = 1795, note = "Strahad Farsan: Summon Felhunter" },
				} },
			},
