		{
			id = "forever/class/warlock/imp-alliance", title = "Imp (Alliance)", category = "Class", folder = "Warlock", faction = "Alliance", classes = { "Warlock" }, levels = { 1, 4 }, zone = 1429, version = 1, revision = "6a97fbd1fbab8bfe75b22057df20d1d8ee68b26fb15a9f953418e04106a2ebd8", keywords = { "Summon Imp", "The Stolen Tome", "Beginnings", "Drusilla La Salle", "Alamar Grimm", "Powers of the Void", "Stolen Books", "Feather Charm", "Frostmane Novice", "Northshire", "Coldridge Valley", "Anvilmar", "Tainted Letter", "Tainted Memorandum", "Warlock", "class pet" }, rewards = { { spell = 688, name = "Summon Imp" } }, why = "Your first demon at level 1-4: the imp, from your start zone's warlock trainer.",
			steps = {
				{ title = "Drusilla La Salle (Humans)", tip = "Your first letter (Tainted Letter, from Marshal McBride after Kobold Camp Cleanup) points you to Drusilla La Salle, the warlock trainer in the little graveyard beside Northshire Abbey. She asks for a book the Defias stole.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "accept", quest = 1598, note = "Drusilla La Salle" },
				} },
				{ title = "The Stolen Books", tip = "The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "collect", quest = 1598, objective = 1, item = 6785, note = "Powers of the Void, from the Stolen Books" },
				} },
				{ title = "Summon Imp", tip = "Drusilla teaches you Summon Imp at the hand-in: summon it right away, it costs nothing and fights beside you.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "turnin", quest = 1598, note = "Drusilla La Salle: Summon Imp" },
				} },
				{ title = "Alamar Grimm (Gnomes)", tip = "Your first letter (Tainted Memorandum, from Sten Stoutarm after Dwarven Outfitters) points you to Alamar Grimm, the warlock trainer upstairs inside Anvilmar. He asks for three Feather Charms.", only = { races = { "Gnome" } }, zone = 1426, goals = {
					{ kind = "accept", quest = 1599, note = "Alamar Grimm" },
				} },
				{ title = "Feather Charms", tip = "The Frostmane Novices (level 3-4) sit at the back of the troll cave south of Anvilmar, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to Coldridge Valley.", only = { races = { "Gnome" } }, zone = 1426, goals = {
					{ kind = "collect", quest = 1599, objective = 1, item = 6753, count = 3, note = "Feather Charms" },
				} },
				{ title = "Summon Imp", tip = "Alamar teaches you Summon Imp at the hand-in: summon it right away, it costs nothing and fights beside you.", only = { races = { "Gnome" } }, zone = 1426, goals = {
					{ kind = "turnin", quest = 1599, note = "Alamar Grimm: Summon Imp" },
				} },
			},
		},
		{
			id = "forever/class/warlock/imp-horde", title = "Imp (Horde)", category = "Class", folder = "Warlock", faction = "Horde", classes = { "Warlock" }, levels = { 1, 4 }, zone = 1411, version = 1, revision = "453de5e35905464e107e8032b7e8062734be31f2effabf56ef36e83136f8040d", keywords = { "Summon Imp", "Vile Familiars", "Piercing the Veil", "Ruzan", "Zureetha Fargaze", "Venya Marthand", "Vile Familiar Head", "Rattlecage Skull", "Burning Blade Coven", "Deathknell", "Tainted Parchment", "Tainted Tablet", "Tainted Scroll", "Primitive Hand Blade", "Primitive Walking Stick", "Warlock", "class pet" }, rewards = { { spell = 688, name = "Summon Imp" }, { item = 4925, choice = true }, { item = 5778, choice = true } }, why = "Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls.",
			steps = {
				{ title = "Ruzan (Orcs and Trolls)", tip = "Your first letter (Tainted Parchment for Orcs, Tainted Tablet for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. Ruzan stands just outside the Den in the Valley of Trials and asks for six Vile Familiar Heads.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "accept", quest = 1485, note = "Ruzan" },
				} },
				{ title = "Vile Familiars", tip = "The Vile Familiars (level 3-4) swarm the Burning Blade Coven, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own Vile Familiars quest.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "collect", quest = 1485, objective = 1, item = 6487, count = 6, note = "Vile Familiar Heads" },
				} },
				{ title = "Summon Imp", tip = "Ruzan teaches you Summon Imp when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with Zureetha Fargaze a few steps away for a starter weapon.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 1485, note = "Ruzan: Summon Imp" },
					{ kind = "accept", quest = 1499 },
					{ kind = "turnin", quest = 1499, choose = { { item = 4925 }, { item = 5778 } }, note = "Zureetha Fargaze" },
				} },
				{ title = "Venya Marthand (Undead)", tip = "Your first letter (Tainted Scroll, from Shadow Priest Sarvis after The Mindless Ones) points you to Maximillion, the warlock trainer in Deathknell. Venya Marthand waits inside the building beside him and asks for three Rattlecage Skulls.", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "accept", quest = 1470, note = "Venya Marthand" },
				} },
				{ title = "Rattlecage Skulls", tip = "The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of Deathknell, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes.", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "collect", quest = 1470, objective = 1, item = 6281, count = 3, note = "Rattlecage Skulls" },
				} },
				{ title = "Summon Imp", tip = "Venya teaches you Summon Imp when you hand in the skulls: summon it right away, it costs nothing and fights beside you.", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 1470, note = "Venya Marthand: Summon Imp" },
				} },
			},
		},
		{
			id = "forever/class/warlock/impsys-request", title = "An Imp's Request", category = "Class", folder = "Warlock", classes = { "Warlock" }, levels = { 50, 54 }, zone = 1448, version = 1, revision = "608e296de6fa298c6d3822340b769d54731e04a235f311f51eda61b24ba6fd44", legacyRevision = "1db207aa1be0cf13c372a119e3f5b1ebb24968eb6b44bd2ea5393308abc6f536", keywords = { "An Imp's Request", "Hot and Itchy", "The Wrong Stuff", "Trolls of a Feather", "Impsy", "Felcloth", "Rotting Wood", "Bloodvenom Essence", "Withered Protector", "Irontree", "Tainted Ooze", "Voodoo Feather", "Sunken Temple", "Temple of Atal'Hakkar", "Gasher", "Zul'Lor", "Hukku", "Mijan", "Zolo", "Loro", "Soul Harvester", "Abyss Shard", "Robes of Servitude", "Warlock", "class quest" }, rewards = { { item = 20536, choice = true }, { item = 20534, choice = true }, { item = 20530, choice = true } }, why = "A staff, off-hand or robe for your 50s; Impsy's own errand, not a step of the Dreadsteed chain.",
			steps = {
				{ title = "An Imp's Request (Stormwind)", tip = "At 50 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Impsy in Felwood with a piece of Felcloth.", only = { races = { "Human" } }, when = { { name = "Felwood", test = "zone", negate = true } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8419, npc = 461, note = "Demisette Cloyce" },
