				{ title = "An Imp's Request (Ironforge)", tip = "At 50 Briarthorn in Ironforge sends you to Impsy in Felwood with a piece of Felcloth.", only = { races = { "Gnome" } }, when = { { name = "Felwood", test = "zone", negate = true } }, zone = 1455, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8419, npc = 5172, note = "Briarthorn" },
				} },
				{ title = "An Imp's Request (Orgrimmar)", tip = "At 50 Zevrost in the Cleft of Shadow sends you to Impsy in Felwood with a piece of Felcloth.", only = { races = { "Orc", "Troll" } }, when = { { name = "Felwood", test = "zone", negate = true } }, zone = 1454, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8419, npc = 3326, note = "Zevrost" },
				} },
				{ title = "An Imp's Request (Undercity)", tip = "At 50 Kaal Soulreaper in the Magic Quarter sends you to Impsy in Felwood with a piece of Felcloth.", only = { races = { "Scourge" } }, when = { { name = "Felwood", test = "zone", negate = true } }, zone = 1458, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8419, npc = 4563, note = "Kaal Soulreaper" },
				} },
				{ title = "Felcloth", tip = "One Felcloth: the Jadefire satyrs of Felwood drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's An Imp's Request or for Impsy's own Hot and Itchy, the same errand: whichever you hold.", zone = 1448, goals = {
					{ kind = "collect", item = 14256, note = "Felcloth" },
				} },
				{ title = "Impsy", tip = "Impsy waits beside Niby the Almighty on a rise just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's An Imp's Request with the cloth. Next he wants ten Rotting Wood and four Bloodvenom Essence.", when = { { test = "onquest", quests = { 8419 } } }, zone = 1448, goals = {
					{ kind = "turnin", quest = 8419, note = "Impsy" },
				} },
				{ title = "Impsy: Hot and Itchy", tip = "Impsy waits beside Niby the Almighty on a rise just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Take his own Hot and Itchy and hand him the cloth at once. Next he wants ten Rotting Wood and four Bloodvenom Essence.", when = { { quest = 8419, test = "turnedin", negate = true } }, zone = 1448, goals = {
					{ kind = "accept", quest = 8420, note = "Impsy: Hot and Itchy" },
					{ kind = "turnin", quest = 8420, note = "Impsy" },
				} },
				{ title = "Rotting Wood and Bloodvenom", tip = "The Irontree treants (level 52) of Irontree Woods, in northern Felwood west of Talonbranch Glade, drop Rotting Wood one time in four; the big Withered Protector (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around Impsy and along the Bloodvenom drop the essence one time in five.", zone = 1448, goals = {
					{ kind = "accept", quest = 8421, note = "Impsy: The Wrong Stuff" },
					{ kind = "collect", quest = 8421, objective = 1, item = 20613, count = 10, note = "Rotting Wood" },
					{ kind = "collect", quest = 8421, objective = 2, item = 20614, count = 4, note = "Bloodvenom Essence" },
				} },
				{ title = "Impsy again", tip = "Impsy now wants six Voodoo Feathers from the Sunken Temple: a dungeon run.", zone = 1448, goals = {
					{ kind = "turnin", quest = 8421, note = "Impsy" },
					{ kind = "accept", quest = 8422 },
				} },
				{ title = "The Sunken Temple", tip = "The Sunken Temple (Temple of Atal'Hakkar, level 50-56, a group of five) stands in the middle of the Pool of Tears: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52.", zone = 1435, goals = {
					{ kind = "collect", quest = 8422, objective = 1, item = 20606, count = 2, map = 1435, x = 69, y = 54, group = 5, note = "Amber Voodoo Feathers: Gasher, Zul'Lor" },
					{ kind = "collect", quest = 8422, objective = 2, item = 20607, count = 2, map = 1435, x = 69, y = 54, group = 5, note = "Blue Voodoo Feathers: Hukku, Mijan" },
					{ kind = "collect", quest = 8422, objective = 3, item = 20608, count = 2, map = 1435, x = 69, y = 54, group = 5, note = "Green Voodoo Feathers: Zolo, Loro" },
				} },
				{ title = "Trolls of a Feather", tip = "Choose the Soul Harvester (staff), the Abyss Shard (off-hand) or the Robes of Servitude.", zone = 1448, goals = {
					{ kind = "turnin", quest = 8422, choose = { { item = 20536 }, { item = 20534 }, { item = 20530 } }, note = "Impsy" },
				} },
			},
