		{
			id = "forever/class/warlock/incubus-alliance", title = "Succubus and Incubus (Alliance)", category = "Class", folder = "Warlock", faction = "Alliance", classes = { "Warlock" }, levels = { 20, 25 }, zone = 1453, version = 1, revision = "44ea8bb42bb3da3be1515082cdf41f96538bb4a818de9abeee560b6690e69b7a", legacyRevision = "56dd0ec9d1cdb545515d85cf8fe33c1fbbbe23e1225d0363e7139571be7670c7", keywords = { "Summon Succubus", "Summon Incubus", "sayaad", "Gakin's Summons", "Devourer of Souls", "Heartswood", "Heartswood Core", "What Is Love?", "Unlit Torch", "Burning Torch", "Wooden Figurine", "Ordil'Aran", "Maestra's Post", "Lago Blackwrench", "Gakin the Darkbinder", "Takar the Seer", "The Binding", "Small Soul Pouch", "Warlock", "class pet" }, rewards = { { spell = 712, name = "Summon Succubus" }, { spell = 713, name = "Summon Incubus" }, { item = 22243 } }, why = "At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",
			steps = {
				{ title = "Gakin's Summons (Gnomes)", tip = "At 20 Lago Blackwrench, the warlock trainer in Ironforge's Forlorn Cavern, sends you to Gakin the Darkbinder in Stormwind. Take the Deeprun Tram.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1717, note = "Lago Blackwrench" },
				} },
				{ title = "Devourer of Souls", tip = "At 20 Gakin the Darkbinder, in the cellar of the Slaughtered Lamb in the Mage Quarter, sends you to Takar the Seer in the Barrens: a long trip for the Alliance. Take the boat from Menethil Harbor to Theramore and head west through Dustwallow Marsh, or the boat from Booty Bay to Ratchet.", zone = 1453, goals = {
					{ kind = "level", level = 20 },
					{ kind = "turnin", quest = 1717, only = { races = { "Gnome" } }, note = "Gakin the Darkbinder" },
					{ kind = "accept", quest = 1716, note = "Gakin the Darkbinder" },
				} },
				{ title = "Takar the Seer", tip = "Takar the Seer camps at a tent with a campfire just north-east of Camp Taurajo, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. Doan Karhan beside him starts the Orb of Soran'ruk. Takar offers both branches: take both.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1716, note = "Takar the Seer" },
					{ kind = "accept", quest = 1738, note = "the succubus" },
					{ kind = "accept", quest = 65602, note = "the incubus" },
				} },
				{ title = "Heartswood", tip = "Ordil'Aran lies in north-west Ashenvale, north of Astranaar along the road toward Darkshore. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the Heartswood from as far away as it lets you. It is turned in to Gakin, not to Takar.", zone = 1440, goals = {
					{ kind = "collect", quest = 1738, objective = 1, item = 6912, note = "Heartswood" },
				} },
				{ title = "The Wooden Figurine", tip = "The house stands alone in the trees of north-western Ashenvale, north-west of Ordil'Aran and well north of Maestra's Post: do it on the same trip as the Heartswood. Take the Unlit Torch from the table outside, light it at a campfire (a Basic Campfire of your own, or Talen's fire on Zoram Strand), and go straight back: the Burning Torch burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs.", zone = 1440, goals = {
					{ kind = "collect", item = 190307, optional = true, note = "Unlit Torch, on the table outside" },
					{ kind = "collect", quest = 65602, objective = 1, item = 190309, note = "Wooden Figurine, upstairs" },
				} },
				{ title = "The Binding: succubus", tip = "Back to Gakin with the Heartswood. He hands you the Heartswood Core: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, Gakin takes it back.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1738, note = "Gakin the Darkbinder" },
					{ kind = "accept", quest = 1739 },
					{ kind = "use", item = 6913, map = 1453, x = 39.1, y = 84.4, frame = "live", note = "Heartswood Core, on the circle in the crypt" },
					{ kind = "kill", quest = 1739, objective = 1, npc = 5677, note = "Summoned Succubus" },
					{ kind = "turnin", quest = 1739, note = "Gakin the Darkbinder: Summon Succubus" },
				} },
				{ title = "The Binding: incubus", tip = "Give Gakin the figurine, then use the Wooden Figurine at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: Gakin takes it back.", zone = 1453, goals = {
					{ kind = "turnin", quest = 65602, note = "Gakin the Darkbinder" },
					{ kind = "accept", quest = 65603 },
					{ kind = "kill", quest = 65603, objective = 1, npc = 185335, note = "Summoned Incubus, at the circle in the crypt" },
					{ kind = "turnin", quest = 65603, note = "Gakin the Darkbinder: Summon Incubus" },
				} },
			},
		},
		{
			id = "forever/class/warlock/incubus-horde", title = "Succubus and Incubus (Horde)", category = "Class", folder = "Warlock", faction = "Horde", classes = { "Warlock" }, levels = { 20, 28 }, zone = 1454, version = 1, revision = "515e62f9db224dd669b6210fd19a877cd8c472043d658f5e42603796280a17b5", legacyRevision = "ccdbacb2da97a1b179ea9e4d59fa3b6877c7f1ce71254b02234d0351aa3f648c", keywords = { "Summon Succubus", "Summon Incubus", "sayaad", "Devourer of Souls", "Blind Cazul", "News of Dogran", "Ken'zigla's Draught", "Dogran's Captivity", "Love's Gift", "Hearts of the Pure", "Love Hurts", "Wish You Were Here", "Hearts of the Lovers", "The Binding", "Gan'rul Bloodeye", "Cazul", "Zankaja", "Gazrog", "Ken'zigla", "Malaka'jin", "Grunt Logmar", "Grunt Dogran", "Dogran's Pendant", "Magar", "Krilge", "Withered Scarf", "Fallen Sky Lake", "Carendin Halgar", "Godrick Farsan", "Dalin Forgewright", "Corma Villard", "Avelina Lilly", "Isaac Pearson", "Ambermill", "Ratchet", "Small Soul Pouch", "Warlock", "class pet" }, rewards = { { spell = 712, name = "Summon Succubus" }, { spell = 713, name = "Summon Incubus" }, { item = 22243 } }, why = "At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",
			steps = {
				{ title = "Devourer of Souls (Orgrimmar)", tip = "At 20 Gan'rul Bloodeye, in the Cleft of Shadow under the Valley of Strength, sends you to Cazul a few steps away. Two trainers start these demons, Gan'rul here and Carendin Halgar in the Undercity, and you can take only one; this guide follows whichever Devourer of Souls you took. Cazul offers both of Orgrimmar's branches: take both.", zone = 1454, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1507, note = "Gan'rul Bloodeye" },
					{ kind = "turnin", quest = 1507, note = "Cazul" },
					{ kind = "accept", quest = 1508, note = "the succubus" },
					{ kind = "accept", quest = 65601, note = "the incubus" },
				} },
				{ title = "Zankaja", tip = "Zankaja lives in a hut up on the cliffs on the west side of the city, above the Valley of Strength: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads.", zone = 1454, goals = {
					{ kind = "turnin", quest = 1508, note = "Zankaja" },
					{ kind = "accept", quest = 1509 },
				} },
				{ title = "Magar", tip = "Magar keeps Magar's Cloth Goods on the main street east of the Cleft of Shadow. He asks you to look for his mate Krilge in Ashenvale.", zone = 1454, goals = {
					{ kind = "turnin", quest = 65601, note = "Magar" },
					{ kind = "accept", quest = 65610 },
				} },
				{ title = "Gazrog", tip = "Gazrog waits in front of the inn at the Crossroads. He sends you on to Ken'zigla at Malaka'jin, in Stonetalon Mountains.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1509, note = "Gazrog" },
					{ kind = "accept", quest = 1510 },
				} },
				{ title = "Ken'zigla", tip = "Take the road west from the Crossroads into Stonetalon Mountains and, just past the border, the faint trail up to the left (south): Malaka'jin cannot be reached from the main road. Ken'zigla hands you her draught for Grunt Logmar.", zone = 1442, goals = {
					{ kind = "turnin", quest = 1510, note = "Ken'zigla, Malaka'jin" },
					{ kind = "accept", quest = 1511 },
				} },
				{ title = "Grunt Dogran", tip = "Grunt Logmar stands at Camp Taurajo, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for Gan'rul. Keep it.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1511, note = "Grunt Logmar, Camp Taurajo" },
					{ kind = "accept", quest = 1515 },
					{ kind = "turnin", quest = 1515, note = "Grunt Dogran" },
					{ kind = "accept", quest = 1512 },
				} },
				{ title = "The Binding: succubus (Orgrimmar)", tip = "Back to Gan'rul with the pendant. He hands you Dogran's Pendant: take it across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: Gan'rul takes it back.", zone = 1454, goals = {
					{ kind = "turnin", quest = 1512, note = "Gan'rul Bloodeye" },
					{ kind = "accept", quest = 1513 },
					{ kind = "use", item = 6626, map = 1454, x = 49.4, y = 50, note = "Dogran's Pendant, on the circle in Neeru's tent" },
					{ kind = "kill", quest = 1513, objective = 1, npc = 5677, note = "Summoned Succubus" },
					{ kind = "turnin", quest = 1513, note = "Gan'rul Bloodeye: Summon Succubus" },
				} },
				{ title = "Fallen Sky Lake", tip = "Fallen Sky Lake lies in southern Ashenvale, south-west of Splintertree Post. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the Withered Scarf about one time in twenty, and the lone Shadethicket Oracle (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in Ashenvale. They respawn in five minutes.", when = { { test = "onquest", quests = { 65610 } } }, zone = 1440, goals = {
					{ kind = "level", level = 24 },
					{ kind = "collect", quest = 65610, objective = 1, item = 190232, note = "Withered Scarf" },
				} },
				{ title = "The Binding: incubus (Orgrimmar)", tip = "Back to Gan'rul with the scarf, then use the Withered Scarf on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: Gan'rul takes it back.", zone = 1454, goals = {
					{ kind = "turnin", quest = 65610, note = "Gan'rul Bloodeye" },
					{ kind = "accept", quest = 65604 },
					{ kind = "kill", quest = 65604, objective = 1, npc = 185335, note = "Summoned Incubus, at the circle in Neeru's tent" },
					{ kind = "turnin", quest = 65604, note = "Gan'rul Bloodeye: Summon Incubus" },
				} },
				{ title = "Devourer of Souls (Undercity)", tip = "The Undercity's version, for warlocks who took Carendin Halgar's Devourer of Souls instead of Gan'rul's. At 20 Carendin, in the Magic Quarter, sends you to Godrick Farsan close by. Godrick shows you an image of each quarry and offers both branches: take both.", zone = 1458, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1472, note = "Carendin Halgar" },
					{ kind = "turnin", quest = 1472, note = "Godrick Farsan" },
					{ kind = "accept", quest = 1476, note = "the succubus" },
					{ kind = "accept", quest = 65593, note = "the incubus" },
				} },
				{ title = "Silverpine hearts", tip = "Avelina Lilly (level 22) works as a tailor for the Dalaran wizards at Ambermill, in eastern Silverpine: the wizards around her are hostile. Dalin Forgewright (level 20, not elite) patrols near the Greymane Wall in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart.", zone = 1421, goals = {
					{ kind = "collect", quest = 65593, objective = 1, item = 190179, note = "Avelina's Heart" },
					{ kind = "collect", quest = 1476, objective = 1, item = 6312, note = "Dalin's Heart" },
				} },
				{ title = "Corma Villard", tip = "Corma Villard (level 22, not elite; Comar in older records) wanders the north of the Wetlands just past the Thandol Span, to the right as you come off the bridge. From the Undercity head through Hillsbrad and Arathi Highlands, where the mobs are 30 and up. Attacking her flags you for PvP.", zone = 1437, goals = {
					{ kind = "collect", quest = 1476, objective = 2, item = 6313, note = "Corma's Heart" },
				} },
				{ title = "The Binding: succubus (Undercity)", tip = "Back to Carendin with Dalin's and Corma's hearts. He hands you the Pure Hearts: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, Carendin takes them back.", zone = 1458, goals = {
					{ kind = "turnin", quest = 1476, note = "Carendin Halgar" },
					{ kind = "accept", quest = 1474 },
					{ kind = "use", item = 6286, map = 1458, x = 86.6, y = 27.1, note = "Pure Hearts, on the circle below Carendin" },
					{ kind = "kill", quest = 1474, objective = 1, npc = 5677, note = "Summoned Succubus" },
					{ kind = "turnin", quest = 1474, note = "Carendin Halgar: Summon Succubus" },
				} },
				{ title = "Isaac Pearson", tip = "Isaac Pearson (level 22) works in Ratchet, on the Barrens coast, at one of two spots in town: take the zeppelin to Durotar and head south, or fly from Orgrimmar. He is an Alliance-friendly human: attacking him can flag you for PvP.", zone = 1413, goals = {
					{ kind = "collect", quest = 65593, objective = 2, item = 190180, note = "Isaac's Heart" },
				} },
				{ title = "The Binding: incubus (Undercity)", tip = "Back to Carendin with the lovers' hearts, then place the Lovers' Hearts on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: Carendin takes them back.", zone = 1458, goals = {
					{ kind = "turnin", quest = 65593, note = "Carendin Halgar" },
					{ kind = "accept", quest = 65597 },
					{ kind = "kill", quest = 65597, objective = 1, npc = 185335, note = "Summoned Incubus, at the circle below Carendin" },
					{ kind = "turnin", quest = 65597, note = "Carendin Halgar: Summon Incubus" },
				} },
			},
		},
		{
			id = "forever/class/warlock/orb-of-orahil", title = "Orb of Orahil", category = "Class", folder = "Warlock", classes = { "Warlock" }, levels = { 35, 40 }, zone = 1413, version = 1, revision = "1ee52d34adeaaa133705e526bc01d0a0eb13e26efa7e3f2a0d0a1f0a93ffe260", legacyRevision = "ffbdfa4e7d921dc2d919f42d21221cb58efcdc5c93718c947e2508ce9e83f45d", keywords = { "The Orb of Orahil", "Knowledge of the Orb of Orahil", "Fragments of the Orb of Orahil", "Cleansing of the Orb of Orahil", "Returning the Cleansed Orb", "Menara Voidrender", "Infernal Orb", "Tabetha", "Demon of the Orb", "Shard of a Felhound", "Acolyte Wytula", "Felhas Ruby", "Imprisoned Felhound Spirit", "Mana Eater", "Shard of an Infernal", "Acolyte Magaz", "Infus Emerald", "Imprisoned Infernal Spirit", "Lesser Infernal", "Burning Blade Summoner", "Mannoroc Coven", "The Orb of Dar'Orahil", "The Orb of Noh'Orahil", "Orb of Dar'Orahil", "Orb of Noh'Orahil", "Staff of Dar'Orahil", "Staff of Noh'Orahil", "Warlock", "class weapon" }, rewards = { { item = 15108, choice = true }, { item = 15106, choice = true }, { item = 15107, choice = true }, { item = 15105, choice = true } }, why = "An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick.",
			steps = {
				{ title = "Knowledge of the Orb of Orahil (Stormwind)", tip = "At 35 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Menara Voidrender in Ratchet.", only = { races = { "Human" } }, zone = 1453, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 4968, note = "Demisette Cloyce" },
				} },
				{ title = "Knowledge of the Orb of Orahil (Ironforge)", tip = "At 35 Briarthorn in Ironforge sends you to Menara Voidrender in Ratchet.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 4965, note = "Briarthorn" },
				} },
				{ title = "Knowledge of the Orb of Orahil (Orgrimmar)", tip = "At 35 Zevrost in the Cleft of Shadow sends you to Menara Voidrender in Ratchet.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 4967, note = "Zevrost" },
				} },
				{ title = "Knowledge of the Orb of Orahil (Undercity)", tip = "At 35 Kaal Soulreaper in the Magic Quarter sends you to Menara Voidrender in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 4969, note = "Kaal Soulreaper" },
				} },
				{ title = "Menara Voidrender", tip = "Menara Voidrender and her two acolytes stand in Strahad Farsan's tower on the hill above Ratchet.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4968, only = { races = { "Human" } }, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4965, only = { races = { "Gnome" } }, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4967, only = { races = { "Orc", "Troll" } }, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4969, only = { races = { "Scourge" } }, note = "Menara Voidrender" },
					{ kind = "accept", quest = 1799 },
				} },
				{ title = "Choose an acolyte", tip = "Pick one acolyte: you can take only one of their quests. Acolyte Wytula's felhound path ends with the Orb or Staff of Dar'Orahil, the shadow versions; Acolyte Magaz's infernal path with the Orb or Staff of Noh'Orahil, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back.", zone = 1413, goals = {
					{ kind = "accept", quest = 4962, note = "Acolyte Wytula: she gives you the Felhas Ruby" },
					{ kind = "accept", quest = 4963, note = "Acolyte Magaz: he gives you the Infus Emerald" },
				} },
				{ title = "Mannoroc Coven", tip = "Mannoroc Coven fills south-central Desolace, east of Shadowprey Village. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the Infernal Orb every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with Drain Soul: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant).", zone = 1443, goals = {
					{ kind = "collect", quest = 1799, objective = 1, item = 7291, note = "Infernal Orb, from the Burning Blade Summoners" },
					{ kind = "collect", quest = 4962, objective = 1, item = 12648, note = "Imprisoned Felhound Spirit, from a Mana Eater, Mage Hunter or Ley Hunter" },
					{ kind = "collect", quest = 4963, objective = 1, item = 12649, note = "Imprisoned Infernal Spirit, from a Lesser Infernal" },
				} },
				{ title = "The demon's spirit", tip = "Back to Menara in the tower above Ratchet with the spirit and the gem first: her orb follows from it.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4962, note = "Menara Voidrender" },
					{ kind = "turnin", quest = 4963, note = "Menara Voidrender" },
				} },
				{ title = "Tabetha", tip = "Tabetha lives at her farm in the middle of Dustwallow Marsh, south of the road from the Barrens and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 38. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the Demon of the Orb out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or Banish and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from Tabetha again.", zone = 1445, goals = {
					{ kind = "turnin", quest = 1799, note = "Tabetha" },
					{ kind = "level", level = 38 },
					{ kind = "accept", quest = 4961 },
					{ kind = "kill", quest = 4961, objective = 1, npc = 6549, note = "Demon of the Orb" },
					{ kind = "turnin", quest = 4961, note = "Tabetha" },
					{ kind = "accept", quest = 4976 },
				} },
				{ title = "The Orb of Dar'Orahil", tip = "Back to Menara in the tower above Ratchet with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the Orb of Dar'Orahil (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4976, note = "Menara Voidrender" },
					{ kind = "accept", quest = 4964 },
					{ kind = "complete", quest = 4964, map = 1413, x = 62.5, y = 35.4, note = "Wait beside Menara while she makes the orb" },
					{ kind = "turnin", quest = 4964, choose = { { item = 15108 }, { item = 15106 } }, note = "Menara Voidrender" },
				} },
				{ title = "The Orb of Noh'Orahil", tip = "On the infernal path, accept her last quest and wait beside Menara while she completes the Orb of Noh'Orahil, then speak to her again and pick the off-hand orb or the staff.", zone = 1413, goals = {
					{ kind = "accept", quest = 4975 },
					{ kind = "complete", quest = 4975, map = 1413, x = 62.5, y = 35.4, note = "Wait beside Menara while she makes the orb" },
					{ kind = "turnin", quest = 4975, choose = { { item = 15107 }, { item = 15105 } }, note = "Menara Voidrender" },
				} },
			},
		},
		{
			id = "forever/class/warlock/orb-of-soranruk", title = "Orb of Soran'ruk", category = "Class", folder = "Warlock", classes = { "Warlock" }, levels = { 22, 30 }, zone = 1413, version = 1, revision = "c64d55578bd8fb692079655c8924224060df02330340d7b6c8d1be5149d523e5", legacyRevision = "4cc4521251b13dde43d72d6e453785527a30300edcd7368dd9ae775324e58f02", keywords = { "The Orb of Soran'ruk", "Doan Karhan", "Soran'ruk Fragment", "Large Soran'ruk Fragment", "Orb of Soran'ruk", "Staff of Soran'ruk", "Blackfathom Deeps", "Shadowfang Keep", "Twilight Acolyte", "Shadowfang Darksoul", "Warlock", "class weapon" }, rewards = { { item = 6898, choice = true }, { item = 15109, choice = true } }, why = "A rare off-hand orb or staff for your 20s, for fragments from two dungeons.",
			steps = {
				{ title = "Doan Karhan", tip = "Doan Karhan camps beside Takar the Seer, at a tent just north-east of Camp Taurajo in the southern Barrens. Alliance warlocks reach him from Ratchet or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your Blackfathom Deeps and Shadowfang Keep runs.", zone = 1413, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1740, note = "Doan Karhan" },
				} },
				{ title = "Blackfathom Deeps", tip = "Blackfathom Deeps (level 24-32, a group of five) opens in the ruins on the north-west coast of Ashenvale, under the water at Zoram Strand. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around Twilight Lord Kelris and the altar before Aku'mai; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest.", zone = 1440, goals = {
					{ kind = "collect", quest = 1740, objective = 1, item = 6914, count = 3, map = 1440, x = 14.5, y = 14.2, frame = "live", note = "Soran'ruk Fragments, from the Twilight Acolytes inside" },
				} },
				{ title = "Shadowfang Keep", tip = "Shadowfang Keep (level 22-30, a group of five) stands on the hill south of the Sepulcher. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop.", zone = 1421, goals = {
					{ kind = "collect", quest = 1740, objective = 2, item = 6915, map = 1421, x = 44.8, y = 67.8, frame = "live", note = "Large Soran'ruk Fragment, from the Shadowfang Darksouls inside" },
				} },
				{ title = "Back to Doan Karhan", tip = "Choose the off-hand Orb of Soran'ruk or the two-handed Staff of Soran'ruk.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1740, choose = { { item = 6898 }, { item = 15109 } }, note = "Doan Karhan" },
				} },
			},
		},
		{
			id = "forever/class/warlock/shard-of-the-green-flame", title = "Shard of the Green Flame", category = "Class", folder = "Warlock", classes = { "Warlock" }, levels = { 50, 56 }, zone = 1448, version = 1, revision = "ef5fdd1b02d45dce0bc9db17e57ce250de4529c662da4d56f5e240ecb979a988", legacyRevision = "c46ddfad880283700f94a518e4ad76b668987fc327783bad3c4e07f3d13c0f7f", keywords = { "Niby the Almighty", "What Niby Commands", "Flawless Fel Essence", "Kroshius' Infernal Core", "Kroshius", "Fel Fire", "Impsy", "Shard of the Green Flame", "Jaedenar", "Jaedenar Legionnaire", "Legashi", "Legash Encampment", "Felguard Sentry", "Dark Portal", "Shatter Scar Vale", "Warlock", "class quest" }, rewards = { { item = 18762 } }, why = "A rare off-hand for your 50s from Niby and Impsy in Felwood, the camp that also offers An Imp's Request.",
			steps = {
				{ title = "Niby the Almighty", tip = "At 50 Niby the Almighty and his imp Impsy wait on a rise in central Felwood just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Niby sends you to Impsy, beside him, who wants three Flawless Fel Essences from three places.", zone = 1448, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 7601, note = "Niby the Almighty" },
					{ kind = "turnin", quest = 7601, note = "Impsy" },
					{ kind = "accept", quest = 7602 },
				} },
				{ title = "Azshara", tip = "The Legashi satyrs (level 51-53) hold the Legash Encampment on Azshara's northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly.", zone = 1447, goals = {
					{ kind = "collect", quest = 7602, objective = 1, item = 18624, note = "Flawless Fel Essence (Azshara)" },
				} },
				{ title = "Jaedenar", tip = "Jaedenar lies just south of Bloodvenom Post, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, Shadow Hold is the northern one, further up the hill; the other has no Legionnaires. Shadow Hold's tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward Lord Banehollow's chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of Jaedenar and Shadow Hold are all hostile.", zone = 1448, goals = {
					{ kind = "level", level = 53 },
					{ kind = "collect", quest = 7602, objective = 2, item = 18622, note = "Flawless Fel Essence (Jaedenar)" },
				} },
				{ title = "The Dark Portal", tip = "The Felguard Sentries (level 54) walk around the Dark Portal in the south of the Blasted Lands, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest.", zone = 1419, goals = {
					{ kind = "collect", quest = 7602, objective = 3, item = 18623, note = "Flawless Fel Essence (Dark Portal)" },
				} },
				{ title = "Impsy", tip = "Back to Impsy. He hands you the Fel Fire: keep it, it wakes the infernal Kroshius.", zone = 1448, goals = {
					{ kind = "turnin", quest = 7602, note = "Impsy" },
					{ kind = "accept", quest = 7603 },
				} },
				{ title = "Kroshius", tip = "Kroshius' remains lie in Shatter Scar Vale, the burnt crater north of Niby: follow the road north from his camp; the remains lie a little east of it. Use the Fel Fire beside them and wait for him to rise. Kroshius is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull Kroshius away from it. He always drops his core. Lost the Fel Fire? Abandon the quest and take it again from Impsy.", zone = 1448, goals = {
					{ kind = "use", item = 18626, map = 1448, x = 45.7, y = 34.8, note = "Fel Fire, at Kroshius' Remains" },
					{ kind = "kill", quest = 7603, objective = 1, npc = 14467, note = "Kroshius" },
					{ kind = "collect", quest = 7603, objective = 2, item = 18625, note = "Kroshius' Infernal Core" },
				} },
				{ title = "Back to Niby", zone = 1448, goals = {
					{ kind = "turnin", quest = 7603, note = "Niby the Almighty: Shard of the Green Flame" },
				} },
			},
		},
		{
			id = "forever/class/warlock/tome-of-sacrifice", title = "Tome of Sacrifice", category = "Class", folder = "Warlock", classes = { "Warlock" }, levels = { 60, 60 }, zone = 1419, version = 1, revision = "e9e53cd7caa0b32c95d91b4577ea9ceda3a217be4a09d6823c3eb3e18b58c706", legacyRevision = "449bfa7cacf576246d84938583d17b52a02ae36004f70e22a4ad6f4de14531cf", keywords = { "The Prison's Bindings", "The Prison's Casing", "Suppression", "Daio the Decrepit", "Tainted Scar", "Satyr Blood", "Wildspawn", "Tears of the Hederine", "Hederine", "Glowing Crystal Prison", "Doomguard Commander", "Imprisoned Doomguard", "Tome of Sacrifice", "Dire Maul", "Warpwood Quarter", "Darkwhisper Gorge", "Warlock", "class quest" }, rewards = { { item = 18602 } }, why = "A rare off-hand at 60, Daio's payment for capturing a Doomguard Commander in the Blasted Lands.",
			steps = {
				{ title = "Daio the Decrepit", tip = "At 60 Daio the Decrepit waits in the Tainted Scar, the demon-filled hollow in the west of the Blasted Lands. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. Daio gives you two errands at once.", zone = 1419, goals = {
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 7581, note = "Daio the Decrepit" },
					{ kind = "accept", quest = 7582 },
				} },
				{ title = "Satyr Blood", tip = "The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, Dire Maul's eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at Lariss Pavilion needs the Crescent Key, which drops inside this wing; until someone has it, go in by Dire Maul's main gate in central Feralas.", zone = 1444, goals = {
					{ kind = "collect", quest = 7581, objective = 1, item = 18603, count = 15, map = 1444, x = 59.2, y = 45.1, group = 5, note = "Satyr Blood, from the Wildspawn inside" },
				} },
				{ title = "Tears of the Hederine", tip = "The Hederine demons (level 57-60, elite) hold Darkwhisper Gorge in the far south of Winterspring: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their Dominate Mind). A warlock can solo them one at a time with Fear or Banish and damage over time, but slowly. Any of them can drop the Tears, four kills in five.", zone = 1452, goals = {
					{ kind = "collect", quest = 7582, objective = 1, item = 18604, count = 5, note = "Tears of the Hederine" },
				} },
				{ title = "Suppression", tip = "Hand both in to Daio and take the Glowing Crystal Prison. Find a Doomguard Commander (level 61, elite) standing alone in the Tainted Scar, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his War Stomp can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the Imprisoned Doomguard: click it. If the channel breaks, kill him or run, and try another.", zone = 1419, goals = {
					{ kind = "turnin", quest = 7581, note = "Daio the Decrepit" },
					{ kind = "turnin", quest = 7582, note = "Daio the Decrepit" },
					{ kind = "accept", quest = 7583 },
					{ kind = "use", quest = 7583, objective = 1, item = 18601, map = 1419, x = 34.5, y = 63.7, note = "Glowing Crystal Prison, on a Doomguard Commander" },
					{ kind = "collect", quest = 7583, objective = 1, item = 18605, note = "Imprisoned Doomguard, click it" },
				} },
				{ title = "Back to Daio", zone = 1419, goals = {
					{ kind = "turnin", quest = 7583, note = "Daio the Decrepit: Tome of Sacrifice" },
				} },
			},
		},
		{
			id = "forever/class/warlock/voidwalker-alliance", title = "Voidwalker (Alliance)", category = "Class", folder = "Warlock", faction = "Alliance", classes = { "Warlock" }, levels = { 10, 12 }, zone = 1429, version = 1, revision = "3b5832b063fc2bd4e0a5826df5585cceb3d2235070eb4bdec936261ed4a44aff", keywords = { "Summon Voidwalker", "Gakin's Summons", "The Slaughtered Lamb", "Surena Caledon", "The Binding", "Remen Marcot", "Lago Blackwrench", "Gakin the Darkbinder", "Surena's Choker", "Bloodstone Choker", "Morgan the Collector", "Brackwell Pumpkin Patch", "Summoning Circle", "Warlock", "class pet" }, rewards = { { spell = 697, name = "Summon Voidwalker" } }, why = "Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in Gakin's crypt.",
			steps = {
				{ title = "Gakin's Summons (Humans)", tip = "At 10 Remen Marcot, in the cellar of the Lion's Pride Inn in Goldshire (the stairs down are in the back room past the butcher's table), sends you to Gakin the Darkbinder in Stormwind.", only = { races = { "Human" } }, zone = 1429, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1685, note = "Remen Marcot, Lion's Pride Inn cellar" },
				} },
				{ title = "The Slaughtered Lamb (Gnomes)", tip = "At 10 Lago Blackwrench, the warlock trainer in Ironforge's Forlorn Cavern, sends you to Gakin the Darkbinder in Stormwind. Take the Deeprun Tram from Tinker Town. If Lago does not offer it, go to Gakin anyway: he still gives you the next quest.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1715, note = "Lago Blackwrench, Forlorn Cavern" },
				} },
				{ title = "Gakin the Darkbinder", tip = "The Slaughtered Lamb is the tavern in the Mage Quarter; Gakin is in its cellar, down the stairs inside.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1685, only = { races = { "Human" } }, note = "Gakin the Darkbinder" },
					{ kind = "turnin", quest = 1715, only = { races = { "Gnome" } }, note = "Gakin the Darkbinder" },
					{ kind = "accept", quest = 1688 },
				} },
				{ title = "Surena Caledon", tip = "Surena Caledon (level 9) is inside the farmhouse at the Brackwell Pumpkin Patch, south-east Elwynn near the Redridge road. Morgan the Collector (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on Surena first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop.", zone = 1429, goals = {
					{ kind = "kill", npc = 881, optional = true, note = "Surena Caledon" },
					{ kind = "collect", quest = 1688, objective = 1, item = 6810, note = "Surena's Choker" },
				} },
				{ title = "The Binding", tip = "Back to Gakin. He hands you the Bloodstone Choker. The circle is hard to find: take the stairs behind Gakin down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: Curse of Agony, Corruption and Immolate with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: Gakin takes it back.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1688, note = "Gakin the Darkbinder" },
					{ kind = "accept", quest = 1689 },
					{ kind = "use", item = 6928, map = 1453, x = 39.1, y = 84.4, frame = "live", note = "Bloodstone Choker, on the circle in the crypt" },
					{ kind = "kill", quest = 1689, objective = 1, npc = 5676, note = "Summoned Voidwalker" },
					{ kind = "turnin", quest = 1689, note = "Gakin the Darkbinder: Summon Voidwalker" },
				} },
			},
		},
		{
			id = "forever/class/warlock/voidwalker-horde", title = "Voidwalker (Horde)", category = "Class", folder = "Warlock", faction = "Horde", classes = { "Warlock" }, levels = { 10, 12 }, zone = 1411, version = 1, revision = "c9ecf731a6d56d24ede9cdb648658f670416421532d9300cf4c263abbb30c596", keywords = { "Summon Voidwalker", "Gan'rul's Summons", "Halgar's Summons", "Creature of the Void", "The Binding", "Ophek", "Gan'rul Bloodeye", "Ageron Kargal", "Carendin Halgar", "Tablet of Verga", "Burning Blade Stash", "Skull Rock", "Egalin's Grimoire", "Perrine's Chest", "Glyphs of Summoning", "Runes of Summoning", "Neeru Fireblade", "Summoning Circle", "Warlock", "class pet" }, rewards = { { spell = 697, name = "Summon Voidwalker" } }, why = "Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle.",
			steps = {
				{ title = "Gan'rul's Summons (Orcs and Trolls)", tip = "At 10 Ophek sends you to Gan'rul Bloodeye. He stands outside at the back of Razor Hill's barracks, the big building on the east side of town (not the inn), a few steps from Dhugru Gorelust, the warlock trainer. Gan'rul stands with the senior warlocks in the Cleft of Shadow, the cavern under Orgrimmar's Valley of Strength. An Orc or Troll leveling in Tirisfal Glades can take the Undercity version from Ageron Kargal in Brill instead (the Undercity steps below): you can do only one of the two.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1506, note = "Ophek" },
					{ kind = "turnin", quest = 1506, note = "Gan'rul Bloodeye, Cleft of Shadow" },
					{ kind = "accept", quest = 1501 },
				} },
				{ title = "Skull Rock", tip = "Skull Rock is the cave in the cliffs just east of Orgrimmar's gate. Inside, take the right-hand ramp up and follow it to the top: the Burning Blade Stash sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and Gazz'uz, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet.", only = { races = { "Orc", "Troll" } }, zone = 1411, goals = {
					{ kind = "collect", quest = 1501, objective = 1, item = 6535, note = "Tablet of Verga, in the Burning Blade Stash" },
				} },
				{ title = "The Binding (Orgrimmar)", tip = "Back to Gan'rul. He hands you the Glyphs of Summoning: take them across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: Curse of Agony, Corruption and Immolate, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: Gan'rul takes them back.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "turnin", quest = 1501, note = "Gan'rul Bloodeye" },
					{ kind = "accept", quest = 1504 },
					{ kind = "use", item = 7464, map = 1454, x = 49.4, y = 50, note = "Glyphs of Summoning, on the circle in Neeru's tent" },
					{ kind = "kill", quest = 1504, objective = 1, npc = 5676, note = "Summoned Voidwalker" },
					{ kind = "turnin", quest = 1504, note = "Gan'rul Bloodeye: Summon Voidwalker" },
				} },
				{ title = "Halgar's Summons (Undercity)", tip = "At 10 Ageron Kargal, upstairs in the Gallows' End Tavern in Brill, sends you to Carendin Halgar: the version for the Undead, and for Orcs and Trolls who level in Tirisfal Glades instead of taking Gan'rul's. Carendin stands in the Undercity's Magic Quarter, by the Temple of the Damned.", only = { races = { "Orc", "Troll", "Scourge" } }, zone = 1420, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1478, note = "Ageron Kargal, upstairs in the Brill inn" },
					{ kind = "turnin", quest = 1478, note = "Carendin Halgar, Magic Quarter" },
					{ kind = "accept", quest = 1473 },
				} },
				{ title = "Perrine's Chest", tip = "The Scarlet tower stands in the fields west of the Undercity's ruins (not the tower near Deathknell). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. Captain Perrine (level 9) and a Scarlet Zealot guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it.", only = { races = { "Orc", "Troll", "Scourge" } }, zone = 1420, goals = {
					{ kind = "collect", quest = 1473, objective = 1, item = 6285, note = "Egalin's Grimoire, in Perrine's Chest" },
				} },
				{ title = "The Binding (Undercity)", tip = "Back to Carendin. He hands you the Runes of Summoning: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. Curse of Agony, Corruption and Immolate with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: Carendin takes them back.", only = { races = { "Orc", "Troll", "Scourge" } }, zone = 1458, goals = {
					{ kind = "turnin", quest = 1473, note = "Carendin Halgar" },
					{ kind = "accept", quest = 1471 },
					{ kind = "use", item = 6284, map = 1458, x = 86.6, y = 27.1, note = "Runes of Summoning, on the circle below Carendin" },
					{ kind = "kill", quest = 1471, objective = 1, npc = 5676, note = "Summoned Voidwalker" },
					{ kind = "turnin", quest = 1471, note = "Carendin Halgar: Summon Voidwalker" },
				} },
			},
		},
		{
			id = "forever/class/warrior/brutal-armor", title = "Brutal Armor", category = "Class", folder = "Warrior", faction = "Horde", classes = { "Warrior" }, levels = { 20, 32 }, zone = 1413, version = 1, revision = "1dbbccef7d3a1361038eae9ddea6a6de41244ec04c81e9de4642129e6a953a35", legacyRevision = "f7622fc261323fea640867ee0a7dd9ee045496e76c7fd520bc1223fc4bff041a", keywords = { "Ruga Ragetotem", "Trial at the Field of Giants", "Twitching Antenna", "Ruga's Bulwark", "Thun'grim Firegaze", "Brutal Armor", "Smoky Iron Ingot", "Powdered Azurite", "Iron Bar", "Vial of Phlogiston", "Brutal Hauberk", "Brutal Gauntlets", "Brutal Helm", "Brutal Legguards", "Ula'elek", "Satyr Hooves", "Orm Stonehoof", "Chimaeric Horn", "Velora Nitely", "Dragonmaw Shinbones", "Roogug", "Razorfen Kraul", "Warrior", "class armor" }, rewards = { { item = 7133 }, { item = 7130 }, { item = 7129 }, { item = 7132 }, { item = 7120 } }, why = "Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way.",
			steps = {
				{ title = "Speak with Ruga (Orgrimmar)", tip = "At 20, Sorek in the Valley of Honor sends you to Ruga Ragetotem in Camp Taurajo.", only = { races = { "Orc", "Troll", "Skyborne" } }, zone = 1454, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1823, npc = 3354, note = "Sorek" },
				} },
				{ title = "Speak with Ruga (Thunder Bluff)", tip = "At 20, Torm Ragetotem, the warrior trainer of Thunder Bluff, sends you to Ruga Ragetotem in Camp Taurajo.", only = { races = { "Tauren" } }, zone = 1456, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1823, npc = 3041, note = "Torm Ragetotem" },
				} },
				{ title = "Speak with Ruga (Undercity)", tip = "At 20, Baltus Fowler, a warrior trainer of the Undercity, sends you to Ruga Ragetotem in Camp Taurajo.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1823, npc = 4595, note = "Baltus Fowler" },
				} },
				{ title = "Ruga Ragetotem", tip = "Fly to Camp Taurajo. Ruga stands in the hut with the leatherworking and tailoring trainers.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1823, note = "Ruga Ragetotem" },
					{ kind = "accept", quest = 1824 },
				} },
				{ title = "Trial at the Field of Giants", tip = "You have 30 minutes, and each Twitching Antenna rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the Field of Giants south of Camp Taurajo; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. Ruga's Bulwark, a shield, is the reward.", zone = 1413, goals = {
					{ kind = "collect", quest = 1824, objective = 1, item = 7119, count = 5, note = "Twitching Antenna, from the silithid" },
					{ kind = "turnin", quest = 1824, rewards = { { item = 7120 } }, note = "Ruga Ragetotem: Ruga's Bulwark" },
					{ kind = "accept", quest = 1825 },
				} },
				{ title = "Thun'grim Firegaze", tip = "Thun'grim's hut sits on top of Thorn Hill, east of the Crossroads: climb the broad ridge on the north or east side. Brutal Armor is a level 30 quest; take it now and gather on the way. Thun'grim's Instructions list where each material comes from.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1825 },
					{ kind = "accept", quest = 1838 },
				} },
				{ title = "Windshear Mine", tip = "You need 15 Smoky Iron Ingots. The Windshear Mine lies at the east end of Windshear Crag, east of Sun Rock Retreat; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast Frostbolt.", zone = 1442, goals = {
					{ kind = "collect", quest = 1838, objective = 1, item = 7126, count = 15, note = "Smoky Iron Ingot, from the Windshear kobolds" },
				} },
				{ title = "Hillsbrad Miners", tip = "You need 10 Powdered Azurite. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of Southshore and drop the azurite four kills in five; they fight in Defensive Stance, sunder your armor and run for help at 30% health. Fly to Tarren Mill and head south-west.", zone = 1424, goals = {
					{ kind = "level", level = 25 },
					{ kind = "collect", quest = 1838, objective = 2, item = 7127, count = 10, note = "Powdered Azurite, from the Hillsbrad Miners" },
				} },
				{ title = "Roogug in Razorfen Kraul", tip = "Roogug is an elite quilboar (level 28) inside Razorfen Kraul, the dungeon at the south end of the Barrens; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts Lightning Bolt and calls Earth Rumblers. The vial always drops.", zone = 1413, goals = {
					{ kind = "level", level = 26 },
					{ kind = "collect", quest = 1838, objective = 4, item = 6841, map = 1413, x = 42.9, y = 90.2, frame = "live", group = 5, note = "Vial of Phlogiston, from Roogug" },
				} },
				{ title = "Iron Bars", tip = "You need 10 Iron Bars. Miners smelt them from Iron Ore (one ore a bar, Smelt Iron at Mining 125); everyone else buys them at the auction house in Orgrimmar.", zone = 1454, goals = {
					{ kind = "collect", quest = 1838, objective = 3, item = 3575, count = 10, map = 1454, x = 55.9, y = 62.7, note = "Iron Bars: Auctioneer Thathung" },
				} },
				{ title = "Brutal Hauberk", tip = "Back to Thun'grim on Thorn Hill. Brutal Hauberk is the first piece; he then sends you to three crafters, one per piece: take all three.", zone = 1413, goals = {
					{ kind = "turnin", quest = 1838, note = "Thun'grim Firegaze" },
					{ kind = "accept", quest = 1848 },
					{ kind = "turnin", quest = 1848, rewards = { { item = 7133 } } },
					{ kind = "accept", quest = 1839 },
					{ kind = "accept", quest = 1840 },
					{ kind = "accept", quest = 1841 },
				} },
				{ title = "Ula'elek", tip = "Ula'elek is in Sen'jin Village on the Durotar coast. He wants 7 Uncloven Satyr Hooves.", zone = 1411, goals = {
					{ kind = "turnin", quest = 1839, note = "Ula'elek" },
					{ kind = "accept", quest = 1842 },
				} },
				{ title = "Satyr Hooves", tip = "The satyrs of Satyrnaar, north-east of Splintertree Post (Xavian, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A Xavian satyr at 15% health may cast Gift of the Xavian and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%.", zone = 1440, goals = {
					{ kind = "collect", quest = 1842, objective = 1, item = 7128, count = 7, note = "Uncloven Satyr Hoof" },
				} },
				{ title = "Brutal Gauntlets", zone = 1411, goals = {
					{ kind = "turnin", quest = 1842, note = "Ula'elek, Sen'jin Village" },
					{ kind = "accept", quest = 1843 },
					{ kind = "turnin", quest = 1843, rewards = { { item = 7129 } } },
				} },
				{ title = "Orm Stonehoof", tip = "Orm Stonehoof works on Thunder Bluff's lowest level, close to the blacksmith.", zone = 1456, goals = {
					{ kind = "turnin", quest = 1840, note = "Orm Stonehoof" },
					{ kind = "accept", quest = 1844 },
				} },
				{ title = "Chimaeric Horn", tip = "The Chimaera Matriarch (level 28, not elite, larger than the young ones around her) roams the south edge of the Charred Vale in south-west Stonetalon, near the road to Desolace. She is the only one: she returns 5 minutes after dying and drops the Galvanized Horn four kills in five. She spits Corrosive Poison from 30 yards.", zone = 1442, goals = {
					{ kind = "collect", quest = 1844, objective = 1, item = 6840, note = "Galvanized Horn, from the Chimaera Matriarch" },
				} },
				{ title = "Brutal Helm", zone = 1456, goals = {
					{ kind = "turnin", quest = 1844, note = "Orm Stonehoof" },
					{ kind = "accept", quest = 1845 },
					{ kind = "turnin", quest = 1845, rewards = { { item = 7130 } } },
				} },
				{ title = "Velora Nitely", tip = "Take the zeppelin from Orgrimmar to Tirisfal Glades; Velora Nitely works in the Undercity's Trade Quarter. She wants 8 Sturdy Dragonmaw Shinbones.", zone = 1458, goals = {
					{ kind = "turnin", quest = 1841, note = "Velora Nitely" },
					{ kind = "accept", quest = 1846 },
				} },
				{ title = "Dragonmaw Shinbones", tip = "The Dragonmaw orcs (level 26-30) camp in the middle of the Wetlands; from Hammerfall in Arathi head south over the Thandol Span (Menethil Harbor is Alliance). With Dragonmaw Shinbones from Velora in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a Dragonmaw Shinbone (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast Shadow Bolt, Bonewarders raise skeletons.", when = { { test = "onquest", quests = { 1846 } } }, zone = 1437, goals = {
					{ kind = "collect", item = 7131, name = "Dragonmaw Shinbone", optional = true, note = "from the Dragonmaw orcs: right-click to test it" },
					{ kind = "collect", quest = 1846, objective = 1, item = 7134, count = 8, note = "Sturdy Dragonmaw Shinbone" },
				} },
				{ title = "Brutal Legguards", zone = 1458, goals = {
					{ kind = "turnin", quest = 1846, note = "Velora Nitely" },
					{ kind = "accept", quest = 1847 },
					{ kind = "turnin", quest = 1847, rewards = { { item = 7132 } } },
				} },
			},
		},
		{
			id = "forever/class/warrior/fire-hardened-armor", title = "Fire Hardened Armor", category = "Class", folder = "Warrior", faction = "Alliance", classes = { "Warrior" }, levels = { 20, 30 }, zone = 1433, version = 1, revision = "e23d2e857c76f69efbb9fd28d8acf4ce0f8f126c32f92abbf72af8381a14f3b5", legacyRevision = "a44116373bda8ef1f611dae364c0898974dc336a6216e764829bde1ea01bd3b3", keywords = { "Yorus Barleybrew", "The Rethban Gauntlet", "Rethban Caverns", "The Shieldsmith", "Furen Longbeard", "Furen's Favor", "Fire Hardened Mail", "Scorched Spider Fang", "Charred Horn", "Galvanized Horn", "Vial of Phlogiston", "Furen's Armor", "Grimand Elmore", "Burning Blood", "Gutspill", "Mathiel", "Sunscorched Shells", "Klockmort Spannerspan", "Iron Coral", "Fire Hardened Hauberk", "Fire Hardened Coif", "Fire Hardened Leggings", "Fire Hardened Gauntlets", "Roogug", "Razorfen Kraul", "Warrior", "class armor" }, rewards = { { item = 6972 }, { item = 6971 }, { item = 6973 }, { item = 6974 }, { item = 6970 } }, why = "Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths.",
			steps = {
				{ title = "Yorus Barleybrew (Stormwind)", tip = "At 20, Wu Shen, beside Ilsa Corbin in the warrior trainers' building of Old Town, sends you to Yorus Barleybrew in Redridge.", only = { races = { "Human", "Skyborne" } }, zone = 1453, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1698, npc = 5479, note = "Wu Shen" },
				} },
				{ title = "Yorus Barleybrew (Ironforge)", tip = "At 20, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to Yorus Barleybrew in Redridge.", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1698, npc = 5113, note = "Kelv Sternhammer" },
				} },
				{ title = "Yorus Barleybrew (Darnassus)", tip = "At 20, Darnath Bladesinger, the warrior trainer of Darnassus, sends you to Yorus Barleybrew in Redridge.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "level", level = 20 },
					{ kind = "accept", quest = 1698, npc = 7315, note = "Darnath Bladesinger" },
				} },
				{ title = "Yorus Barleybrew", tip = "Yorus Barleybrew sits in the inn at Lakeshire. His test is timed: before you take it, clear the Redridge gnolls on the path to the Rethban Caverns in the hills north-west of Lakeshire, including the two on the rock by the cave mouth (climb it from its right side).", zone = 1433, goals = {
					{ kind = "turnin", quest = 1698, note = "Yorus Barleybrew" },
					{ kind = "accept", quest = 1699 },
				} },
				{ title = "The Rethban Gauntlet", tip = "You have one hour, and Yorus's Barleybrew Scalder leaves you drunk for 8-10 minutes. Run north-west into the Rethban Caverns, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to Yorus (from the ridge you can jump down into Lakeshire). Dying and releasing your spirit fails the quest: abandon it and Yorus gives it again.", zone = 1433, goals = {
					{ kind = "complete", quest = 1699, note = "Enter the Rethban Caverns and come back" },
					{ kind = "turnin", quest = 1699 },
					{ kind = "accept", quest = 1702 },
				} },
				{ title = "The Shieldsmith", tip = "Furen Longbeard works in the Dwarven District of Stormwind. He takes the Cask of Scalder (lost it? abandon the quest and Yorus gives a new one) and gives you Furen's Favor, a shield; Fire Hardened Mail is a level 28 quest, with Furen's Instructions listing what it needs.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1702, rewards = { { item = 6970 } }, note = "Furen Longbeard" },
					{ kind = "accept", quest = 1701 },
				} },
				{ title = "Scorched Spider Fangs", tip = "You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the Wetlands, north of Dun Algaz; every one drops a fang. They poison; back in 5 minutes.", zone = 1437, goals = {
					{ kind = "collect", quest = 1701, objective = 1, item = 6838, count = 50, note = "Scorched Spider Fang" },
				} },
				{ title = "Charred and Galvanized Horns", tip = "The chimaeras live south-west of Sun Rock Retreat in the Charred Vale; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the Galvanized Horn from the Chimaera Matriarch (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit Corrosive Poison, the Young cast Lightning Bolt. Alliance: fly to Stonetalon Peak and head south.", zone = 1442, goals = {
					{ kind = "level", level = 26 },
					{ kind = "collect", quest = 1701, objective = 2, item = 6839, count = 12, note = "Charred Horn, from the young chimaeras" },
					{ kind = "collect", quest = 1701, objective = 3, item = 6840, note = "Galvanized Horn, from the Chimaera Matriarch" },
				} },
				{ title = "Roogug in Razorfen Kraul", tip = "Roogug is an elite quilboar (level 28) inside Razorfen Kraul, the dungeon at the south end of the Barrens; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts Lightning Bolt and calls Earth Rumblers. The vial always drops.", zone = 1413, goals = {
					{ kind = "collect", quest = 1701, objective = 4, item = 6841, map = 1413, x = 42.9, y = 90.2, frame = "live", group = 5, note = "Vial of Phlogiston, from Roogug" },
				} },
				{ title = "Furen's Armor", tip = "Back to Furen Longbeard in the Dwarven District for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly.", zone = 1453, goals = {
					{ kind = "turnin", quest = 1701, note = "Furen Longbeard" },
					{ kind = "accept", quest = 1782 },
					{ kind = "turnin", quest = 1782, rewards = { { item = 6972 } } },
					{ kind = "accept", quest = 1700, only = { races = { "Human" } } },
					{ kind = "accept", quest = 1703, only = { races = { "NightElf" } } },
					{ kind = "accept", quest = 1704, only = { races = { "Dwarf", "Gnome" } } },
				} },
				{ title = "Grimand Elmore", tip = "Grimand Elmore keeps the weapon shop in the north-west of the Dwarven District, a short walk from Furen. He wants 20 Burning Blood and the Burning Rock.", only = { races = { "Human", "Skyborne" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1700, only = { races = { "Human" } }, note = "Grimand Elmore" },
					{ kind = "accept", quest = 1705 },
				} },
				{ title = "Burning Blood", tip = "The Nightbane worgen of Duskwood (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of Darkshire drop the Burning Blood four kills in five. The Tainted Ones poison and howl; Vile Fangs cause Infected Wound.", only = { races = { "Human", "Skyborne" } }, zone = 1431, goals = {
					{ kind = "collect", quest = 1705, objective = 1, item = 6844, count = 20, note = "Burning Blood, from the Nightbane worgen" },
				} },
				{ title = "Gutspill", tip = "Gutspill (level 32, not elite) carries the Burning Rock, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the Roland's Doom mine south-east of Darkshire, so wait at the entrance and pull him outside. He poisons and howls.", only = { races = { "Human", "Skyborne" } }, zone = 1431, goals = {
					{ kind = "level", level = 30 },
					{ kind = "collect", quest = 1705, objective = 2, item = 6845, note = "Burning Rock, from Gutspill" },
				} },
				{ title = "Grimand's Armor", only = { races = { "Human", "Skyborne" } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1705, note = "Grimand Elmore" },
					{ kind = "accept", quest = 1706 },
					{ kind = "turnin", quest = 1706, rewards = { { item = 6971 } } },
				} },
				{ title = "Mathiel", tip = "Mathiel works on the south side of the Warrior's Terrace in Darnassus. He wants 20 Sunscorched Shells.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 1703, note = "Mathiel" },
					{ kind = "accept", quest = 1710 },
				} },
				{ title = "Sunscorched Shells", tip = "The shells lie on the ground under the wyvern nests at Highperch in western Thousand Needles, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once.", only = { races = { "NightElf" } }, zone = 1441, goals = {
					{ kind = "collect", quest = 1710, objective = 1, item = 6849, count = 20, note = "Sunscorched Shell" },
				} },
				{ title = "Mathiel's Armor", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 1710, note = "Mathiel" },
					{ kind = "accept", quest = 1711 },
					{ kind = "turnin", quest = 1711, rewards = { { item = 6973 } } },
				} },
				{ title = "Klockmort Spannerspan", tip = "Ride the Deeprun Tram from Stormwind to Ironforge. Klockmort Spannerspan, a gnome smith, works in Tinker Town near the engineering trainers. He wants 20 Searing Coral.", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1704, note = "Klockmort Spannerspan" },
					{ kind = "accept", quest = 1708 },
				} },
				{ title = "Iron Coral", tip = "The Iron Coral grows on the sea floor just south of Menethil Harbor, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a Draught of Water Breathing removes the risk.", only = { races = { "Dwarf", "Gnome" } }, zone = 1437, goals = {
					{ kind = "collect", quest = 1708, objective = 1, item = 6848, count = 20, note = "Searing Coral, from Iron Coral" },
				} },
				{ title = "Klockmort's Creation", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1708, note = "Klockmort Spannerspan" },
					{ kind = "accept", quest = 1709 },
					{ kind = "turnin", quest = 1709, rewards = { { item = 6974 } } },
				} },
			},
		},
		{
			id = "forever/class/warrior/haggards-weapons", title = "Defensive Stance and a Weapon (Alliance)", category = "Class", folder = "Warrior", faction = "Alliance", classes = { "Warrior" }, levels = { 10, 11 }, zone = 1429, version = 1, revision = "7c5c374a034d3040b8461ac7fdab49d9f38bb2b3804b013de437570cf44eba82", legacyRevision = "385ba6acb3286538bac21317e891c76066fba5fc9e1cc61f1259bec3b61f03a4", keywords = { "Defensive Stance", "A Warrior's Training", "Bartleby", "Harry Burlguard", "Marshal Haggard", "Dead-tooth Jack", "Haggard's Axe", "Haggard's Hammer", "Haggard's Dagger", "Haggard's Sword", "Muren Stormpike", "Vejrek", "Tormus Deepforge", "Ironband's Compound", "Umbral Ore", "Grey Iron Weapons", "Elanaria", "Vorlus Vilehoof", "The Shade of Elura", "Elunite", "Smith Mathiel", "Weapons of Elunite", "The Skybreaker Bulwark", "Seena Skybreaker", "Stormforged Protector", "Warrior", "class weapon" }, rewards = { { spell = 71, name = "Defensive Stance" }, { item = 6979, choice = true }, { item = 6983, choice = true }, { item = 6980, choice = true }, { item = 6985, choice = true }, { item = 6978, choice = true }, { item = 6982, choice = true }, { item = 6981, choice = true }, { item = 6984, choice = true }, { item = 6966, choice = true }, { item = 6968, choice = true }, { item = 6969, choice = true }, { item = 6967, choice = true }, { item = 275290 } }, why = "Defensive Stance at 10 and a one-hand weapon of your choice from Stormwind, Ironforge or Darnassus.",
			steps = {
				{ title = "Seena Skybreaker in Valanaar", tip = "At 10, Seena Skybreaker stands with the trainers by Valanaar's west gate. A cultist, Zaal Stormshield, holds her family's shield at the Shrine of Akir.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94003, note = "Seena Skybreaker" },
				} },
				{ title = "Zaal Stormshield", tip = "Head north-west from Valanaar to the Shrine of Akir. Zaal Stormshield stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the Skybreaker Bulwark.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", npc = 257196, note = "Zaal Stormshield" },
					{ kind = "collect", quest = 94003, objective = 1, item = 263993, note = "Skybreaker Bulwark, from Zaal Stormshield" },
				} },
				{ title = "The Skybreaker Bulwark", tip = "Back to Seena in Valanaar. She teaches Defensive Stance and gives you the Stormforged Protector, a shield to use it with. Bartleby's road below still gives a weapon, once you reach Stormwind.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 94003, rewards = { { item = 275290 } }, note = "Seena Skybreaker: Defensive Stance" },
				} },
				{ title = "Muren Stormpike", tip = "At 10, Granis Swiftaxe, the warrior trainer in Kharanos, sends you to Muren Stormpike in Ironforge. Any Alliance warrior may take one of the three roads, never two: in Stormwind at 10 anyway? Ilsa Corbin's A Warrior's Training is the quickest stance (one fight in a tavern), with a Haggard's weapon after it.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1679, note = "Granis Swiftaxe" },
				} },
				{ title = "Muren Stormpike in Ironforge", tip = "Muren Stormpike stands in the Hall of Arms in the Military Ward.", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1679, note = "Muren Stormpike" },
					{ kind = "accept", quest = 1678 },
				} },
				{ title = "Vejrek", tip = "Vejrek (level 11, a lone troll) waits at his hut on a hill south of Frostmane Hold, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of Frostmane Hold is the wrong one. He fights in Defensive Stance and sunders your armor; Thunder Clap slows him. His head always drops; he returns about 8 minutes after dying.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "collect", quest = 1678, objective = 1, item = 6799, note = "Vejrek's Head" },
				} },
				{ title = "Tormus Deepforge", tip = "Back to Muren for Defensive Stance, then to Tormus Deepforge at the Great Forge in the middle of Ironforge.", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1678, note = "Muren Stormpike: Defensive Stance" },
					{ kind = "accept", quest = 1680 },
					{ kind = "turnin", quest = 1680, note = "Tormus Deepforge" },
					{ kind = "accept", quest = 1681 },
				} },
				{ title = "Ironband's Compound", tip = "Ironband's Compound lies in eastern Dun Morogh, below Helm's Bed Lake on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. Ironband's Strongbox is in the basement of the southernmost house; Captain Beld (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening.", only = { races = { "Dwarf", "Gnome" } }, zone = 1426, goals = {
					{ kind = "collect", quest = 1681, objective = 1, item = 6800, note = "Umbral Ore, from Ironband's Strongbox" },
				} },
				{ title = "Grey Iron Weapons", only = { races = { "Dwarf", "Gnome" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 1681, note = "Tormus Deepforge" },
					{ kind = "accept", quest = 1682 },
					{ kind = "turnin", quest = 1682, choose = { { item = 6978 }, { item = 6982 }, { item = 6981 }, { item = 6984 } }, note = "Tormus Deepforge" },
				} },
				{ title = "Elanaria", tip = "At 10, Kyra Windblade, the warrior trainer in Dolanaar, or Moon Priestess Amara, who patrols the road west of Dolanaar, sends you to Elanaria on the Warrior's Terrace in Darnassus. Any Alliance warrior may take one of the three roads, never two: in Stormwind at 10 anyway? Ilsa Corbin's A Warrior's Training teaches the same stance after one fight in a tavern.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1684, npc = 3598, note = "Kyra Windblade" },
				} },
				{ title = "Elanaria in Darnassus", tip = "Elanaria stands on the Warrior's Terrace.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 1684, note = "Elanaria" },
					{ kind = "accept", quest = 1683 },
				} },
				{ title = "Vorlus Vilehoof", tip = "Vorlus Vilehoof (level 10, a satyr) stands at a hidden moonwell up a hillside west of Dolanaar. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying.", only = { races = { "NightElf" } }, zone = 1438, goals = {
					{ kind = "collect", quest = 1683, objective = 1, item = 6805, note = "Horn of Vorlus" },
				} },
				{ title = "The Shade of Elura", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 1683, note = "Elanaria: Defensive Stance" },
					{ kind = "accept", quest = 1686 },
				} },
				{ title = "Elunite under Auberdine", tip = "Take the boat from Rut'theran Village to Auberdine. The wreck lies underwater just south of Auberdine's southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey Shade of Elura (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in.", only = { races = { "NightElf" } }, zone = 1439, goals = {
					{ kind = "collect", quest = 1686, objective = 1, item = 6808, count = 8, note = "Elunite Ore, from Crates of Elunite" },
					{ kind = "collect", quest = 1686, objective = 2, item = 6809, note = "Elura's Medallion, from the Shade of Elura" },
				} },
				{ title = "Smith Mathiel", tip = "Back on the Warrior's Terrace: Elanaria hands you the Case of Elunite; Mathiel works on the far, south side of the same terrace, easy to miss.", only = { races = { "NightElf" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 1686, note = "Elanaria" },
					{ kind = "accept", quest = 1692 },
					{ kind = "turnin", quest = 1692, note = "Mathiel" },
					{ kind = "accept", quest = 1693 },
					{ kind = "turnin", quest = 1693, choose = { { item = 6966 }, { item = 6968 }, { item = 6969 }, { item = 6967 } }, note = "Mathiel" },
				} },
				{ title = "A Warrior's Training", tip = "At 10, Lyria Du Lac, the warrior trainer by the inn in Goldshire, sends you to Harry Burlguard in Stormwind; Ilsa Corbin, the warrior trainer in Stormwind's Old Town, offers it too.", only = { races = { "Human", "Skyborne" } }, zone = 1429, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1638, npc = 913, note = "Lyria Du Lac" },
				} },
				{ title = "Bartleby", tip = "Harry Burlguard and Bartleby are in the Pig and Whistle tavern in Old Town; Bartleby is the drunk at the far end of the bar. Bartleby (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took A Warrior's Training from Ilsa Corbin instead of their home road is led through Stormwind from here.", when = { { quest = 1679, test = "turnedin", negate = true }, { quest = 1684, test = "turnedin", negate = true } }, zone = 1453, goals = {
					{ kind = "turnin", quest = 1638, note = "Harry Burlguard" },
					{ kind = "accept", quest = 1639 },
					{ kind = "turnin", quest = 1639, note = "Bartleby" },
					{ kind = "accept", quest = 1640 },
					{ kind = "kill", quest = 1640, objective = 1, npc = 6090, note = "Beat Bartleby" },
					{ kind = "turnin", quest = 1640, note = "Bartleby" },
					{ kind = "accept", quest = 1665 },
					{ kind = "turnin", quest = 1665, note = "Harry Burlguard: Defensive Stance" },
					{ kind = "accept", quest = 1666 },
				} },
				{ title = "Marshal Haggard", tip = "Marshal Haggard's manor stands at the south-east edge of the Eastvale Logging Camp in eastern Elwynn, at the end of a short road that does not join the main one.", when = { { quest = 1679, test = "turnedin", negate = true }, { quest = 1684, test = "turnedin", negate = true } }, zone = 1429, goals = {
					{ kind = "turnin", quest = 1666, note = "Marshal Haggard" },
					{ kind = "accept", quest = 1667 },
				} },
				{ title = "Dead-tooth Jack", tip = "Dead-Tooth Jack (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops Dead-tooth's Key; open Dead-tooth's Strongbox in the crates by him for Marshal Haggard's Badge. Jack returns 3 minutes after dying, the box 1 minute after opening.", when = { { quest = 1679, test = "turnedin", negate = true }, { quest = 1684, test = "turnedin", negate = true } }, zone = 1429, goals = {
					{ kind = "collect", item = 6783, name = "Dead-tooth's Key", note = "from Dead-Tooth Jack" },
					{ kind = "collect", quest = 1667, objective = 1, item = 6782, note = "Marshal Haggard's Badge, from Dead-tooth's Strongbox" },
				} },
				{ title = "Back to Marshal Haggard", when = { { quest = 1679, test = "turnedin", negate = true }, { quest = 1684, test = "turnedin", negate = true } }, zone = 1429, goals = {
					{ kind = "turnin", quest = 1667, choose = { { item = 6979 }, { item = 6983 }, { item = 6980 }, { item = 6985 } }, note = "Marshal Haggard" },
				} },
			},
		},
		{
			id = "forever/class/warrior/heirloom-weapon", title = "Defensive Stance and a Weapon (Horde)", category = "Class", folder = "Warrior", faction = "Horde", classes = { "Warrior" }, levels = { 10, 11 }, zone = 1413, version = 1, revision = "b3e4e54c9cd6d00fb53b0d17000a88a9c0f667b8616ad14cbf4552d39df22e34", legacyRevision = "a496e4b2d059c1ed751e3b6c18611686e73ebcccef96a1fcdf827389aac43e58", keywords = { "Defensive Stance", "Veteran Uzzek", "Path of Defense", "Singed Scale", "Thun'grim Firegaze", "Forged Steel", "Thun'grim's Axe", "Thun'grim's Mace", "Thun'grim's Dagger", "Thun'grim's Sword", "Speak with Dillinger", "Ulag the Cleaver", "Deathguard Dillinger", "Coleman Farthing", "Agamand Heirlooms", "Agamand Mills", "Heirloom Axe", "Heirloom Hammer", "Heirloom Dagger", "Heirloom Sword", "The Skybreaker Bulwark", "Seena Skybreaker", "Zaal Stormshield", "Stormforged Protector", "Warrior", "class weapon" }, rewards = { { spell = 71, name = "Defensive Stance" }, { item = 7326, choice = true }, { item = 7328, choice = true }, { item = 7327, choice = true }, { item = 7329, choice = true }, { item = 7115, choice = true }, { item = 7117, choice = true }, { item = 7116, choice = true }, { item = 7118, choice = true }, { item = 275290 } }, why = "Defensive Stance at 10 and a one-hand weapon of your choice: Uzzek's road, Brill's crypt, or the Skybreaker shield.",
			steps = {
				{ title = "Seena Skybreaker in Valanaar", tip = "At 10, Seena Skybreaker stands with the trainers by Valanaar's west gate. A cultist, Zaal Stormshield, holds her family's shield at the Shrine of Akir.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 94003, note = "Seena Skybreaker" },
				} },
				{ title = "Zaal Stormshield", tip = "Head north-west from Valanaar to the Shrine of Akir. Zaal Stormshield stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the Skybreaker Bulwark.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "kill", npc = 257196, note = "Zaal Stormshield" },
					{ kind = "collect", quest = 94003, objective = 1, item = 263993, note = "Skybreaker Bulwark, from Zaal Stormshield" },
				} },
				{ title = "The Skybreaker Bulwark", tip = "Back to Seena in Valanaar. She teaches Defensive Stance and gives you the Stormforged Protector, a shield to use it with. Uzzek's road below still gives a weapon later, once you reach Kalimdor.", only = { races = { "Skyborne" } }, zone = 2521, goals = {
					{ kind = "turnin", quest = 94003, rewards = { { item = 275290 } }, note = "Seena Skybreaker: Defensive Stance" },
				} },
				{ title = "Veteran Uzzek (Razor Hill)", tip = "At 10, Tarshaw Jaggedscar, the warrior trainer in the barracks of Razor Hill, sends you to Uzzek in the Barrens. Sorek in Orgrimmar's Valley of Honor offers it too. Any Horde warrior may take one of the two roads, never both: heading to Tirisfal Glades at 10 anyway? Austil de Mon in Brill's inn offers the other: one fight by Brill's graveyard for the same stance, then the Agamand crypt for an heirloom weapon.", only = { races = { "Orc", "Troll", "Skyborne" } }, zone = 1411, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1505, npc = 3169, note = "Tarshaw Jaggedscar" },
				} },
				{ title = "Veteran Uzzek (Mulgore)", tip = "At 10, Krang Stonehoof, the warrior trainer of Bloodhoof Village, sends you to Uzzek in the Barrens. Torm Ragetotem in Thunder Bluff offers it too.", only = { races = { "Tauren" } }, zone = 1412, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1505, npc = 3063, note = "Krang Stonehoof" },
				} },
				{ title = "Uzzek at Far Watch Post", tip = "Uzzek is easy to miss: he stands under a small canopy by a large tree just west of Far Watch Post, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From Durotar cross the bridge west; from Mulgore head north past the Crossroads.", only = { races = { "Orc", "Troll", "Tauren", "Skyborne" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1505, note = "Uzzek" },
					{ kind = "accept", quest = 1498 },
				} },
				{ title = "Singed Scales in Thunder Ridge", tip = "You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the Thunder Ridge crevasse in north-west Durotar, south of Orgrimmar: from the Barrens bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast Lizard Bolt.", only = { races = { "Orc", "Troll", "Tauren", "Skyborne" } }, zone = 1411, goals = {
					{ kind = "collect", quest = 1498, objective = 1, item = 6486, count = 5, note = "Singed Scale, from the lizards" },
				} },
				{ title = "Path of Defense", tip = "Back to Uzzek under his tree west of Far Watch Post.", only = { races = { "Orc", "Troll", "Tauren", "Skyborne" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1498, note = "Uzzek: Defensive Stance" },
					{ kind = "accept", quest = 1502 },
				} },
				{ title = "Thun'grim Firegaze", tip = "Thun'grim's hut sits on top of Thorn Hill, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side.", only = { races = { "Orc", "Troll", "Tauren", "Skyborne" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 1502, note = "Thun'grim Firegaze" },
					{ kind = "accept", quest = 1503 },
				} },
				{ title = "Forged Steel", tip = "The Stolen Iron Chest stands by a broken wagon in the Razormane camp north-west of Thun'grim, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too).", only = { races = { "Orc", "Troll", "Tauren", "Skyborne" } }, zone = 1413, goals = {
					{ kind = "collect", quest = 1503, objective = 1, item = 6534, note = "Forged Steel Bars, from the Stolen Iron Chest" },
					{ kind = "turnin", quest = 1503, choose = { { item = 7326 }, { item = 7328 }, { item = 7327 }, { item = 7329 } }, note = "Thun'grim Firegaze" },
				} },
				{ title = "Speak with Dillinger", tip = "At 10, Austil de Mon, the warrior trainer inside the inn of Brill, sends you to Deathguard Dillinger by the graveyard on Brill's west edge. This road and Uzzek's exclude each other: drop Veteran Uzzek or Path of Defense from your log if you hold one.", only = { races = { "Scourge" } }, zone = 1420, goals = {
					{ kind = "level", level = 10 },
					{ kind = "accept", quest = 1818, note = "Austil de Mon" },
				} },
				{ title = "Deathguard Dillinger", tip = "Dillinger stands by the graveyard on Brill's west edge. An Orc, Troll, Tauren or Skyborne who took Speak with Dillinger from Austil de Mon instead of Uzzek's road is led through Brill from here.", when = { { quest = 1505, test = "turnedin", negate = true } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 1818, note = "Deathguard Dillinger" },
					{ kind = "accept", quest = 1819 },
				} },
				{ title = "Ulag the Cleaver", tip = "Ulag sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and Ulag (level 11, not elite) walks out. Start at full health.", when = { { quest = 1505, test = "turnedin", negate = true } }, zone = 1420, goals = {
					{ kind = "kill", quest = 1819, objective = 1, npc = 6390, note = "Ulag the Cleaver" },
					{ kind = "turnin", quest = 1819, note = "Deathguard Dillinger: Defensive Stance" },
					{ kind = "accept", quest = 1820 },
				} },
				{ title = "Coleman Farthing", tip = "Coleman Farthing is in the Gallows' End Tavern, the inn on Brill's east side.", when = { { quest = 1505, test = "turnedin", negate = true } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 1820, note = "Coleman Farthing" },
					{ kind = "accept", quest = 1821 },
				} },
				{ title = "The Agamand Family Crypt", tip = "The four Agamand Weapon Racks are inside the Agamand Family Crypt at the north end of Agamand Mills, north of Brill, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them.", when = { { quest = 1505, test = "turnedin", negate = true } }, zone = 1420, goals = {
					{ kind = "collect", quest = 1821, objective = 1, item = 7567, note = "Agamand Family Axe" },
					{ kind = "collect", quest = 1821, objective = 2, item = 7568, note = "Agamand Family Dagger" },
					{ kind = "collect", quest = 1821, objective = 3, item = 7569, note = "Agamand Family Mace" },
					{ kind = "collect", quest = 1821, objective = 4, item = 7566, note = "Agamand Family Sword" },
				} },
				{ title = "Back to Coleman Farthing", when = { { quest = 1505, test = "turnedin", negate = true } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 1821, note = "Coleman Farthing" },
					{ kind = "accept", quest = 1822 },
					{ kind = "turnin", quest = 1822, choose = { { item = 7115 }, { item = 7117 }, { item = 7116 }, { item = 7118 } }, note = "Coleman Farthing" },
				} },
			},
		},
		{
			id = "forever/class/warrior/quelserrar", title = "Quel'Serrar", category = "Class", folder = "Raid", classes = { "Warrior", "Paladin" }, levels = { 60, 60 }, zone = 1444, version = 1, revision = "01f291378ed336b2a5871c46e4a7049464f5c958e970e1cee94c2dfb3637b615", keywords = { "Quel'Serrar", "Foror's Compendium", "Nostro's Compendium of Dragon Slaying", "The Forging of Quel'Serrar", "Lorekeeper Lydros", "Athenaeum", "Dire Maul", "Crescent Key", "Onyxia", "Unfired Ancient Blade", "Heated Ancient Blade", "Treated Ancient Blade", "Shen'dralar", "tank sword", "Warrior", "Paladin", "class weapon" }, rewards = { { item = 18348 }, { text = "Shen'dralar reputation" } }, why = "A tank sword at 60: a Dire Maul book, then Onyxia's breath tempers the blade (the sword is not in Forever's items yet).",
			steps = {
				{ title = "Nostro's Compendium of Dragon Slaying", tip = "The book is a rare random drop from the bosses of all three Dire Maul wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, Immol'thar and the West, King Gordok and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. Dire Maul is a five-player dungeon in the ruins of central Feralas: needs a group of five. Right-click the book to start the quest; it stays in your bags.", zone = 1444, goals = {
					{ kind = "accept", quest = 7507, item = 18401, group = 5, note = "from Nostro's Compendium of Dragon Slaying" },
				} },
				{ title = "Lorekeeper Lydros", tip = "Lorekeeper Lydros stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the Crescent Key, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you A Dull and Flat Elven Blade to give straight back, then the Unfired Ancient Blade. Keep that blade: lose it, and you must abandon the quest and take it again.", zone = 1444, goals = {
					{ kind = "turnin", quest = 7507, map = 1444, x = 59.2, y = 45.1, group = 5, note = "Lorekeeper Lydros, in the Athenaeum" },
					{ kind = "accept", quest = 7508, map = 1444, x = 59.2, y = 45.1 },
					{ kind = "turnin", quest = 7508, map = 1444, x = 59.2, y = 45.1, note = "Lorekeeper Lydros: hand back the Dull and Flat Elven Blade" },
					{ kind = "accept", quest = 7509, map = 1444, x = 59.2, y = 45.1 },
				} },
				{ title = "Onyxia's breath", tip = "Onyxia is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the Unfired Ancient Blade to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the Ancient Heated Blade to take the Heated Ancient Blade: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade.", zone = 1445, goals = {
					{ kind = "use", item = 18489, map = 1445, x = 52.1, y = 75.8, group = 40, note = "Unfired Ancient Blade: plant it in her breath" },
					{ kind = "collect", item = 18488, name = "Heated Ancient Blade", map = 1445, x = 52.1, y = 75.8, note = "click the heated blade on the ground" },
				} },
				{ title = "Onyxia's corpse", tip = "Kill Onyxia, then target her corpse and use the Heated Ancient Blade on it before the 20 minutes run out. It becomes the Treated Ancient Blade, with no time limit.", zone = 1445, goals = {
					{ kind = "kill", npc = 10184, map = 1445, x = 52.1, y = 75.8, group = 40, note = "Onyxia" },
					{ kind = "use", quest = 7509, objective = 1, item = 18488, map = 1445, x = 52.1, y = 75.8, note = "Heated Ancient Blade, on her corpse" },
					{ kind = "collect", quest = 7509, objective = 1, item = 18492, map = 1445, x = 52.1, y = 75.8, note = "Treated Ancient Blade" },
				} },
				{ title = "The Forging of Quel'Serrar", tip = "Back to Lorekeeper Lydros in the Athenaeum of Dire Maul West: through the West door with the Crescent Key again, and a group to reach the library.", zone = 1444, goals = {
					{ kind = "turnin", quest = 7509, map = 1444, x = 59.2, y = 45.1, group = 5, rewards = { { item = 18348 } }, note = "Lorekeeper Lydros: Quel'Serrar" },
				} },
			},
		},
		{
			id = "forever/class/warrior/voodoo-feathers", title = "Voodoo Feathers", category = "Class", folder = "Warrior", classes = { "Warrior" }, levels = { 50, 52 }, zone = 1435, version = 1, revision = "5f47dee122b569481e90fc04d6b1d1bd84e649bd9f86d88dc37e99eca23b262c", legacyRevision = "bc358b1df6cecb26c7aae561f0872464bfe359660625a35e2757b26876ae2542", keywords = { "A Troubled Spirit", "Fallen Hero of the Horde", "Warrior Kinship", "War on the Shadowsworn", "Voodoo Feathers", "Sunken Temple", "Temple of Atal'Hakkar", "Blasted Lands", "Helboar", "Warrior", "class quest" }, rewards = { { text = "Experience" } }, why = "Experience at 50, ending in the Sunken Temple; Classic's item choice may be gone on Forever.",
			steps = {
				{ title = "A Troubled Spirit (Stormwind)", tip = "At 50, Wu Shen, beside Ilsa Corbin in the warrior trainers' building of Old Town, sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", only = { races = { "Human", "Skyborne" }, factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "level", level = 50 },
