				{ title = "Mor'zul Bloodbringer (Undercity)", tip = "At 60 Martha Strain, the demon trainer in the Magic Quarter, sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 7562, npc = 5753, note = "Martha Strain" },
				} },
				{ title = "Mor'zul Bloodbringer", tip = "Mor'zul Bloodbringer and his goblin Gorzeeki Wildeyes camp on the hill across the road from the Altar of Storms, in the far north-west of the Burning Steppes, west of Blackrock Mountain. The chain is long: about 420 gold in Gorzeeki's and Ur'dan's goods, a pile of crafted materials, the Scholomance and Dire Maul. Start buying or gathering the materials of the next steps now.", zone = 1428, goals = {
					{ kind = "turnin", quest = 7562, note = "Mor'zul Bloodbringer" },
					{ kind = "accept", quest = 7563 },
				} },
				{ title = "Raging Beast's Blood", tip = "Every owlbeast of Winterspring (level 53-58, none elite) drops the blood about one time in three: about ninety kills for thirty. Owl Wing Thicket, in the north-east, and the Hidden Grove's surroundings are packed with them, and they respawn in five and a half minutes.", zone = 1452, goals = {
					{ kind = "collect", quest = 7563, objective = 1, item = 18590, count = 30, note = "Raging Beast's Blood" },
				} },
				{ title = "Wildeyes", tip = "Back to Mor'zul: he gives you the Case of Blood for Gorzeeki beside him. Then Mor'zul asks for the bell, the wheel and the candle, and Gorzeeki sends you to Lord Banehollow in Jaedenar: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after Ulathek, and a spare in case one runs out) and bring 150 gold for the stardust.", zone = 1428, goals = {
					{ kind = "turnin", quest = 7563, note = "Mor'zul Bloodbringer" },
					{ kind = "accept", quest = 7564, note = "he gives you the Case of Blood" },
					{ kind = "turnin", quest = 7564, note = "Gorzeeki Wildeyes" },
					{ kind = "accept", quest = 7626, note = "Mor'zul Bloodbringer: Bell of Dethmoora" },
					{ kind = "accept", quest = 7627, note = "Mor'zul Bloodbringer: Wheel of the Black March" },
					{ kind = "accept", quest = 7628, note = "Mor'zul Bloodbringer: Doomsday Candle" },
					{ kind = "accept", quest = 7623, note = "Gorzeeki Wildeyes: Lord Banehollow" },
					{ kind = "buy", npc = 14437, item = 18802, count = 3, note = "Shadowy Potion, from Gorzeeki" },
				} },
				{ title = "The ritual pieces", tip = "Gorzeeki wants 10 Elixirs of Shadow Power (Alchemy: 3 Ghost Mushrooms and a Crystal Vial each), 6 Large Brilliant Shards (Enchanting: disenchant level 51+ blue items), 25 Dark Iron Ore (Mining 230: the Dark Iron Deposits of the Burning Steppes and Blackrock Depths) and 35 Black Dragonscales (Skinning: the black dragonkin of the Burning Steppes, a few percent a kill, best from the Flamescale Wyrmkin). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales.", zone = 1428, goals = {
					{ kind = "collect", quest = 7626, objective = 1, item = 9264, count = 10, map = 1453, x = 61.2, y = 71.3, frame = "live", only = { factions = { "Alliance" } }, note = "Elixir of Shadow Power: the Auction House" },
					{ kind = "collect", quest = 7626, objective = 1, item = 9264, count = 10, map = 1454, x = 55.9, y = 62.7, only = { factions = { "Horde" } }, note = "Elixir of Shadow Power: the Auction House" },
					{ kind = "collect", quest = 7627, objective = 1, item = 14344, count = 6, map = 1453, x = 61.2, y = 71.3, frame = "live", only = { factions = { "Alliance" } }, note = "Large Brilliant Shard: the Auction House" },
					{ kind = "collect", quest = 7627, objective = 1, item = 14344, count = 6, map = 1454, x = 55.9, y = 62.7, only = { factions = { "Horde" } }, note = "Large Brilliant Shard: the Auction House" },
