				} },
				{ title = "Summon Felsteed (Ironforge)", tip = "At 40 Briarthorn, by the warlock trainers in Ironforge, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = { "Gnome" } }, zone = 1455, goals = {
					{ kind = "level", level = 40 },
					{ kind = "accept", quest = 4487, note = "Briarthorn" },
				} },
				{ title = "Summon Felsteed (Orgrimmar)", tip = "At 40 Zevrost, in the Cleft of Shadow, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = { "Orc", "Troll" } }, zone = 1454, goals = {
					{ kind = "level", level = 40 },
					{ kind = "accept", quest = 3631, note = "Zevrost" },
				} },
				{ title = "Summon Felsteed (Undercity)", tip = "At 40 Kaal Soulreaper, in the Magic Quarter, sends you to Strahad Farsan in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar; Ratchet is a short flight from Orgrimmar. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = { "Scourge" } }, zone = 1458, goals = {
					{ kind = "level", level = 40 },
					{ kind = "accept", quest = 4489, note = "Kaal Soulreaper" },
				} },
				{ title = "Strahad Farsan in Ratchet", tip = "Ratchet is the goblin port on the Barrens coast, east of the Crossroads; from the Alliance side take the boat from Booty Bay. Strahad Farsan stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own Summon Felsteed and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing.", zone = 1413, goals = {
					{ kind = "turnin", quest = 4488, only = { races = { "Human" } }, note = "Strahad Farsan" },
					{ kind = "turnin", quest = 4487, only = { races = { "Gnome" } }, note = "Strahad Farsan" },
					{ kind = "turnin", quest = 3631, only = { races = { "Orc", "Troll" } }, note = "Strahad Farsan" },
					{ kind = "turnin", quest = 4489, only = { races = { "Scourge" } }, note = "Strahad Farsan" },
					{ kind = "accept", quest = 4490 },
					{ kind = "turnin", quest = 4490, note = "Strahad Farsan: Summon Felsteed" },
				} },
