		{
			id = "forever/collectibles/pets/baby-crocolisk", title = "Baby Crocolisk", category = "Collectibles", folder = "Companion pets · Drops", levels = { 50, 60 }, zone = 1453, version = 1, revision = "7d28316d42eb7f502571db9bee2aa9ca0d447bd3528a21500163b58ad4fa4edb", legacyRevision = "a0c5e18fdb0c7f69b45a42c8cd35f5d3067f2cadeb3bb437c3b6f188a02774d6", keywords = { "Sewer Beast", "Stormwind canals", "crocolisk", "rare" }, collects = { 282047 },
			steps = {
				{ title = "Sewer Beast", tip = "The Sewer Beast is a rare level 50 crocolisk, much tougher than a normal mob of its level. It swims Stormwind's canals and appears at one of six spots, about two hours after it last died; the arrow takes you round them. Below 60, bring a group; at 60, a well-geared character can try it alone. It drops the Baby Crocolisk about once in 70 kills, and the pet binds when picked up, so the Auction House never has it. Horde players can farm it too, but inside an enemy capital.", loop = true, zone = 1453, goals = {
					{ kind = "goto", map = 1453, x = 32.4, y = 62.5 },
					{ kind = "goto", map = 1453, x = 49.8, y = 69.8 },
					{ kind = "goto", map = 1453, x = 66.9, y = 57.3 },
					{ kind = "goto", map = 1453, x = 66.4, y = 31.8 },
					{ kind = "goto", map = 1453, x = 49.9, y = 22.2 },
					{ kind = "goto", map = 1453, x = 35.5, y = 45.4 },
					{ kind = "collect", item = 282047, name = "Baby Crocolisk", note = "Sewer Beast" },
				} },
			},
		},
		{
			id = "forever/collectibles/pets/bitter-baitling", title = "Bitter Baitling", category = "Collectibles", folder = "Companion pets · Vendors", levels = { 1, 60 }, zone = 1434, version = 1, revision = "10e14f094b6ee9ac53d6bb05ec7f6250508ac3978d8fc497526a9143055c6b88", legacyRevision = "a4420bc97366895f60ee49bb99868f6c59fc977d1fd2f1672fcf08253d98dedf", keywords = { "Jang", "Riggle Bassbait", "Extravagant Extravaganza Coin", "Master Angler", "Speckled Tastyfish", "fishing", "Booty Bay", "Stranglethorn Fishing Extravaganza" }, collects = { 276275 },
			steps = {
				{ title = "Riggle Bassbait", tip = "The Bitter Baitling costs one Extravagant Extravaganza Coin, the prize for winning the Stranglethorn Fishing Extravaganza. The contest runs on Sundays from 2 to 4 pm server time: be on the Booty Bay docks by Riggle Bassbait when it starts. Master Angler is not a quest you take: Riggle takes the fish straight from his window when you bring them. Bring your best Fishing skill and lures so no fish gets away, a mount and empty bags, and bind your hearthstone in Booty Bay.", zone = 1434, goals = {
					{ kind = "goto", label = "Riggle Bassbait", map = 1434, x = 27.4, y = 76.9 },
				} },
				{ title = "Schools of Tastyfish", tip = "While the contest runs, schools of Speckled Tastyfish appear along the Stranglethorn coast, none inside Booty Bay. Fish 40 Speckled Tastyfish from them; each school lasts only a few casts, so ride on to the next as soon as one is gone. The arrow takes you up the west coast north of Booty Bay; more schools lie further north and just south of Booty Bay.", loop = true, zone = 1434, goals = {
					{ kind = "goto", map = 1434, x = 24.9, y = 66.2 },
					{ kind = "goto", map = 1434, x = 23.8, y = 62.5 },
					{ kind = "goto", map = 1434, x = 26.2, y = 58.3 },
					{ kind = "goto", map = 1434, x = 22.9, y = 56.4 },
					{ kind = "goto", map = 1434, x = 26, y = 48.8 },
					{ kind = "goto", map = 1434, x = 27, y = 44.3 },
					{ kind = "collect", item = 19807, count = 40, note = "Speckled Tastyfish" },
				} },
				{ title = "Back to Riggle", tip = "Hurry back and hand the 40 Tastyfish to Riggle: the first players to do so win, and the winners get the coin with their prize. If you are too late to win, Jang still pays a little gold for every 5 Tastyfish.", zone = 1434, goals = {
					{ kind = "turnin", quest = 8193, direct = true },
					{ kind = "collect", item = 274026, name = "Extravagant Extravaganza Coin", map = 1434, x = 27.4, y = 76.9, note = "The winner's coin, from Riggle" },
				} },
				{ title = "Jang", tip = "Jang, Riggle's apprentice, stands beside him on the Booty Bay docks and trades the Bitter Baitling for the coin.", zone = 1434, goals = {
					{ kind = "vendor", npc = 15078, note = "Jang" },
					{ kind = "buy", npc = 15078, item = 276275, name = "Bitter Baitling", note = "1 Extravagant Extravaganza Coin" },
				} },
			},
		},
		{
			id = "forever/collectibles/pets/black-tabby", title = "Black Tabby", category = "Collectibles", folder = "Companion pets · Drops", faction = "Horde", levels = { 21, 60 }, zone = 1421, version = 1, revision = "79679c6d01307c078ef0fd4663f4a613d7c167595c0375b6e7a163124ee1753b", legacyRevision = "e2cd9f9ec63284f8ecf645d370fab6a4a324278ec59ac5986280861d4736d8d0", keywords = { "Cat Carrier (Black Tabby)", "Maine Coon", "Dalaran Spellscribe", "Ambermill", "Silverpine Forest", "Alterac Mountains", "Dalaran", "cat" }, collects = { 8491 },
			steps = {
				{ title = "Dalaran mages", tip = "The Dalaran Spellscribe, a rare level 21 mage at Ambermill in southern Silverpine Forest, drops the Black Tabby about once in 6 kills. It has a single spot and can take hours to come back, so check it whenever you pass. While it is down, the Dalaran Shield Guards, Theurgists and Summoners (level 31-35) at the Dalaran crater, where Alterac Mountains meet Hillsbrad Foothills, drop it too, but only about once in 500 kills. The cat can be traded: look at the Auction House as well.", zone = 1421, goals = {
					{ kind = "collect", item = 8491, name = "Cat Carrier (Black Tabby)", map = 1421, x = 63.5, y = 63.3, note = "Dalaran Spellscribe, Ambermill" },
				} },
			},
		},
		{
			id = "forever/collectibles/pets/chicken-egg", title = "Chicken Egg", category = "Collectibles", folder = "Companion pets · Quests", faction = "Alliance", levels = { 1, 60 }, zone = 1436, version = 1, revision = "f825976b228d432045bb64c22dddd6e78a783749aebd6d516379e6440c5060dc", legacyRevision = "5af9319858d421b3ab18c38003d4f0a8634c46f2a38d0c20f0d01a5504c0113f", keywords = { "CLUCK!", "Farm Chicken Egg", "chicken", "Westfall", "Farmer Saldean", "Special Chicken Feed", "/chicken", "/cheer" }, collects = { 11110 },
			steps = {
				{ title = "Special Chicken Feed", tip = "Buy one Special Chicken Feed (25 copper) from Farmer Saldean at his farm first: it is not a quest item, and the chicken stays friendly only for a short while.", zone = 1436, goals = {
					{ kind = "buy", npc = 233, item = 11109, note = "Special Chicken Feed" },
				} },
				{ title = "CLUCK!", tip = "Target one of the chickens around Saldean's farm and type /chicken at it, again and again, until it offers CLUCK!; this can take several minutes. Then /cheer at a chicken until it turns friendly (green) and hand in the feed; right-clicking a chicken before it is friendly attacks it. The chicken lays an egg on the ground: loot it for your Chicken Egg.", zone = 1436, goals = {
					{ kind = "accept", quest = 3861, map = 1436, x = 56.1, y = 30 },
					{ kind = "turnin", quest = 3861, map = 1436, x = 56.1, y = 30 },
					{ kind = "collect", item = 11110, map = 1436, x = 56.1, y = 30, note = "Loot the Farm Chicken Egg the chicken lays" },
				} },
			},
		},
		{
			id = "forever/collectibles/pets/condor-hatchling", title = "Condor Hatchling", category = "Collectibles", folder = "Companion pets · Drops", levels = { 14, 60 }, zone = 1432, version = 1, revision = "6b9c746f0f39cbe4875f43ca4ff6a188ef2a83ba0abdcff8028990dd14bea8ad", legacyRevision = "f757569151f20b58d8270a93b541ec3fc49142bb279a3e061996d16141c31172", keywords = { "Shaking Egg", "Lord Condar", "Loch Modan", "condor", "rare" }, collects = { 282637 },
			steps = {
				{ title = "Lord Condar", tip = "Lord Condar is a rare level 15-16 condor in south-eastern Loch Modan. He appears at one of four spots, hours after he last died; the arrow takes you round them. He drops the Shaking Egg only about once in 500 kills, so this is a pet for players who pass through Loch Modan often: check his spots each time, and kill him whenever you see him.", loop = true, zone = 1432, goals = {
