		{
			id = "forever/collectibles/pets/dark-whelpling", title = "Dark Whelpling", category = "Collectibles", folder = "Companion pets · Drops", levels = { 41, 60 }, zone = 1445, version = 1, revision = "0ff6c289d401c6bb66f2213d356e0f3829df213d2892a5b3f04a65256fd71a2f", legacyRevision = "413f847167331029eb626c55e6a2efa26a9b5a2c1d9ec2aa378c61d4428bbb91", keywords = { "Tiny Black Whelpling", "Searing Whelp", "Scalding Whelp", "Wyrmbog", "Dustwallow Marsh", "Badlands", "dragon", "whelp" }, collects = { 10822 },
			steps = {
				{ title = "Black whelps", tip = "The Searing Whelps of the Wyrmbog in southern Dustwallow Marsh (level 42-43) and the Scalding Whelps of eastern Badlands (level 41-43) drop it about once in 900 kills. The waypoint is the Wyrmbog, where the whelps stand thickest; the Badlands whelps are the same grind. The whelpling can be traded, so the Auction House may be quicker.", zone = 1445, goals = {
					{ kind = "collect", item = 10822, name = "Dark Whelpling", map = 1445, x = 46.9, y = 72.5, note = "The Wyrmbog" },
