		{
			id = "forever/collectibles/pets/disgusting-oozeling", title = "Disgusting Oozeling", category = "Collectibles", folder = "Companion pets · Drops", levels = { 54, 60 }, zone = 1422, version = 1, revision = "f8913e0fc49aeccc7b31206d81c5860999d18049ff3a8f38994c2758632df5b3", legacyRevision = "ba7592dd4fe250f54c489eb7b1266409ea55f7d97180fb8c2f20e1f3b9d47cc1", keywords = { "Oozing Bag", "ooze", "slime", "Vile Slime", "Large Vile Slime", "Devouring Ooze", "Western Plaguelands", "Eastern Plaguelands", "Felwood", "Un'Goro Crater" }, collects = { 20768, 20769 },
			steps = {
				{ title = "Oozes", tip = "Oozes drop the Oozing Bag about once in 20-30 kills; the best are the Vile Slimes, Devouring Oozes and the Large Vile Slime in the ooze field of eastern Western Plaguelands (level 54-57). Open every bag: most hold potions or herbs, and only about one bag in 50 holds the Disgusting Oozeling, so expect over a thousand kills. Both the bags and the pet can be traded: unopened bags on the Auction House are lottery tickets, the pet itself the sure buy.", zone = 1422, goals = {
					{ kind = "collect", item = 20769, name = "Disgusting Oozeling", map = 1422, x = 64.9, y = 38.7, note = "Open your Oozing Bags" },
				} },
