			steps = {
				{ title = "Nutritious Slime Sludge", tip = "Buy Nutritious Slime Sludge from Boyle in the Undercity canals first (25 copper for a stack of 5): you hand it in as soon as the slime offers its quest.", zone = 1458, goals = {
					{ kind = "buy", npc = 4612, item = 278265, count = 1, note = "Nutritious Slime Sludge: Boyle, in the canals" },
