		{
			id = "forever/collectibles/pets/lil-timmy", title = "White Kitten", category = "Collectibles", folder = "Companion pets · Vendors", levels = { 1, 60 }, zone = 1453, version = 1, revision = "82aa8accd8795c53fa6de2298b55692f0d92f30c96f2e7f7cad00aa1269cfe25", legacyRevision = "df2fc65901623271bd88f5e181958b8c18a5fd6626f05474ca2fda3c34c689c7", keywords = { "Lil Timmy", "Xaphod Bizznox", "Malaka'jin", "Cat Carrier (White Kitten)", "cat", "kitten" }, collects = { 8489 },
			steps = {
				{ title = "Lil Timmy", tip = "Lil Timmy sells the White Kitten (60s). He starts at Cathedral Square and walks through the Trade District, Old Town and the Dwarven District before he vanishes near the square again; if he is not around, wait for him at Cathedral Square. By beta reports he carries one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards.", only = { factions = { "Alliance" } }, zone = 1453, goals = {
					{ kind = "vendor", npc = 8666, note = "Lil Timmy" },
					{ kind = "buy", npc = 8666, item = 8489, optional = true, note = "Cat Carrier (White Kitten), 60s" },
				} },
				{ title = "Xaphod Bizznox", tip = "Horde players buy the White Kitten (60s) from Xaphod Bizznox, a trader new in Forever, at Malaka'jin, the Darkspear camp at the southern tip of Stonetalon Mountains, on the way up from the Barrens. He keeps one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards.", only = { factions = { "Horde" } }, zone = 1442, goals = {
