		{
			id = "forever/collectibles/pets/magus-tirth", title = "Ancona Chicken", category = "Collectibles", folder = "Companion pets · Vendors", levels = { 1, 60 }, zone = 1441, version = 1, revision = "37dd0b77a02734c3f82d9811741c90e62ab0442c2cd49d49020b61350aa06f35", legacyRevision = "7005d9961537a7b2bf673ba54a2a0d0127d1cb17c43ffaa9eedae73f95236600", keywords = { "Magus Tirth", "Ancona Chicken", "chicken", "Mirage Raceway", "Shimmering Flats" }, collects = { 11023 },
			steps = {
				{ title = "Magus Tirth", tip = "Magus Tirth at the Mirage Raceway, the goblin and gnome racetrack in the Shimmering Flats of south-eastern Thousand Needles, sells the Ancona Chicken (1g) to both sides. The nearest flight paths are Freewind Post (Horde) and Gadgetzan in Tanaris (both sides); from Gadgetzan, ride north into the Shimmering Flats. Each pet item teaches its companion when you use it; the goal stays ticked afterwards.", zone = 1441, goals = {
