		{
			id = "forever/collectibles/pets/mayhoa-skyhoof", title = "Prairie Wolf Pup", category = "Collectibles", folder = "Companion pets · Vendors", faction = "Horde", levels = { 1, 60 }, zone = 1454, version = 1, revision = "93f3d1695ebad50d3da4e7d24865ea20001b8f143bf5d4806690beec0b844b08", legacyRevision = "f948e5a6f3627aa2a8eb6c812c0043f7d96210a5f56b3122e54d6db9c7a17b80", keywords = { "Mayhoa Skyhoof", "Prairie Wolf Pup Carrier", "wolf pup", "wolf" }, collects = { 277508 },
			steps = {
				{ title = "Mayhoa Skyhoof", tip = "Mayhoa Skyhoof, the girl with puppies, walks a long loop through Orgrimmar: from the Valley of Wisdom through the Drag to the Valley of Honor and back. The waypoint is where she is seen most, on the road between the Drag and the Valley of Honor; if she is not there, walk the loop. The carrier costs 60s. She carries one pup at a time: if she has none, another player just bought it, so come back later. Each pet item teaches its companion when you use it; the goals stay ticked afterwards.", zone = 1454, goals = {
					{ kind = "vendor", npc = 268745, name = "Mayhoa Skyhoof", map = 1454, x = 65, y = 38.4, frame = "live" },
					{ kind = "buy", npc = 268745, item = 277508, name = "Prairie Wolf Pup Carrier", map = 1454, x = 65, y = 38.4, frame = "live", note = "60s" },
