		{
			id = "forever/collectibles/pets/mechanical-chicken", title = "Mechanical Chicken", category = "Collectibles", folder = "Companion pets · Quests", levels = { 43, 60 }, zone = 1444, version = 1, revision = "e758dc7fb01c645cc9cc9e06c83ec1ba74e8135b12dd84f1fedc729692dc10c3", legacyRevision = "dd15e1da43cadb7dfa0e7ecdd4fc64e2000c608ce9b35ee3b40f283694b1c2d0", keywords = { "An OOX of Your Own", "Oglethorpe Obnoticus", "OOX", "homing robot", "distress beacon", "Feralas", "Tanaris", "Hinterlands", "Booty Bay" }, collects = { 10398 },
			steps = {
				{ title = "OOX-22/FE Distress Beacon in Feralas", tip = "Each robot starts with a distress beacon that mobs in its zone drop, about one kill in 40 to 100 in Classic's data. In Feralas the best are the Coast Crawl Snapclaws and Deepseers (levels 43-45) on the Forgotten Coast and the Sprite Dragons (47-48), about 2.5%; ogres, harpies, naga and Grimtotems drop it about 1%. You can loot it from level 40.", zone = 1444, goals = {
					{ kind = "collect", item = 8705, count = 1, nearest = true },
				} },
				{ title = "Rescue OOX-22/FE", tip = "Right-click the beacon. OOX-22/FE sits in a cave near Feral Scar Vale, among yetis and apes. Its escort runs west along the road to the dock on the Forgotten Coast with three ambushes: three yetis, then three gorillas, then four or five gnolls with a caster. Bring a friend if you are under 47. The robot keeps walking unless it is hit, so stay close; if it will not move, another player has it: wait for it to come back. Its turn-in is in Booty Bay; keep the quest for later.", zone = 1444, goals = {
					{ kind = "accept", quest = 2766 },
					{ kind = "turnin", quest = 2766 },
					{ kind = "accept", quest = 2767 },
					{ kind = "complete", quest = 2767, note = "Escort OOX-22/FE" },
				} },
				{ title = "OOX-17/TN Distress Beacon in Tanaris", tip = "Tanaris mobs drop OOX-17/TN's beacon about one kill in 50 to 150. Best: the Treasure Hunting Pirates and Buccaneers on the south shore (44-45) and the Ground Pounders in the north (41-43), about 2%. You can loot it from level 43.", zone = 1446, goals = {
					{ kind = "collect", item = 8623, count = 1, nearest = true },
				} },
				{ title = "Rescue OOX-17/TN", tip = "OOX-17/TN stands in the hills near the Gaping Chasm in south-east Tanaris. Its escort to Steamwheedle Port has two ambushes: three scorpids near the start, three Wastewander bandits near the end. The robot has about 3,000 health and stops to fight what you attack, so it can tank for a moment while you recover. Its turn-in is in Booty Bay too.", zone = 1446, goals = {
					{ kind = "accept", quest = 351 },
					{ kind = "turnin", quest = 351 },
					{ kind = "accept", quest = 648 },
					{ kind = "complete", quest = 648, note = "Escort OOX-17/TN" },
				} },
				{ title = "OOX-09/HL Distress Beacon in the Hinterlands", tip = "Most Hinterlands mobs drop OOX-09/HL's beacon about once in 100 kills: Silvermane wolves, owlbeasts, Highvale elves, Witherbark and Vilebranch trolls. You can loot it from level 43.", zone = 1425, goals = {
					{ kind = "collect", item = 8704, count = 1, nearest = true },
				} },
				{ title = "Rescue OOX-09/HL", tip = "OOX-09/HL waits on the largest island of the lake west of Skulk Rock. Its escort to the shore beyond Overlook Cliff has two ambushes of three: Marauding Owlbeasts, then Vilebranch Ambushers; the robot warns you just before each.", zone = 1425, goals = {
					{ kind = "accept", quest = 485 },
					{ kind = "turnin", quest = 485 },
					{ kind = "accept", quest = 836 },
					{ kind = "complete", quest = 836, note = "Escort OOX-09/HL" },
				} },
				{ title = "Oglethorpe Obnoticus in Booty Bay", tip = "Oglethorpe Obnoticus is in Booty Bay, upstairs in the building north of the inn, above First Mate Crazz. Hand in all three rescues; at level 45 he then offers An OOX of Your Own, which you turn straight back in for the Mechanical Chicken.", zone = 1434, goals = {
					{ kind = "turnin", quest = 2767 },
					{ kind = "turnin", quest = 648 },
					{ kind = "turnin", quest = 836 },
					{ kind = "level", level = 45 },
					{ kind = "accept", quest = 3721 },
					{ kind = "turnin", quest = 3721 },
					{ kind = "collect", item = 10398, map = 1434, x = 28.4, y = 76.4, note = "Mechanical Chicken" },
				} },
			},
