		{
			id = "forever/collectibles/pets/minimule", title = "Minimule", category = "Collectibles", folder = "Companion pets · Vendors", levels = { 10, 60 }, zone = 1433, version = 1, revision = "c2b4f33de59d4277bce54e8d73a78005b36a2bc955c725e2d2f522a30d5fa1ab", legacyRevision = "9aa94f0333f57ddd423af9ef00e005fc4fed740c53aecc2bd2facdd9b86df4c1", keywords = { "Packmule Treat", "Minimule", "mule", "Merchant's Favor", "Azeroth Commerce Authority", "Durotar Supply and Logistics", "Tamelyn Aldridge", "Gishah", "Marcy Baker", "Dokimi", "Waylaid Crate" }, collects = { 284664 },
			steps = {
				{ title = "Azeroth Commerce Authority", tip = "The Alliance camp is at Three Corners in western Redridge Mountains. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Marcy Baker, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with the Azeroth Commerce Authority. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there.", only = { factions = { "Alliance" } }, zone = 1433, goals = {
					{ kind = "vendor", npc = 256389, name = "Tamelyn Aldridge", map = 1433, x = 10.6, y = 71.3, frame = "live" },
					{ kind = "buy", npc = 256389, item = 284664, name = "Packmule Treat", map = 1433, x = 10.6, y = 71.3, frame = "live", note = "1,500 Merchant's Favor" },
				} },
				{ title = "Durotar Supply and Logistics", tip = "The Horde camp is just outside the west gate of the Crossroads. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Dokimi, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with Durotar Supply and Logistics. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there. (Another Gishah stands in the Undercity; this is the one at the camp.)", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "vendor", npc = 256384, name = "Gishah", map = 1413, x = 49.4, y = 29.4 },
					{ kind = "buy", npc = 256384, item = 284664, name = "Packmule Treat", map = 1413, x = 49.4, y = 29.4, note = "1,500 Merchant's Favor" },
				} },
			},
