			steps = {
				{ title = "Skyboat from Dalaran", tip = "Zephras Isle is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the north side of Dalaran about every five minutes (another flies from north of Thunder Bluff; either faction may take either).", only = { factions = { "Alliance" } }, when = { { name = "Zephras Isle", test = "zone", negate = true } }, zone = 1416, goals = {
