		{
			id = "forever/collectibles/pets/spectral-bear-cub", title = "Spectral Bear Cub", category = "Collectibles", folder = "Companion pets · Legacy", levels = { 25, 60 }, zone = 1413, version = 1, revision = "32e7760de9784c0dd5cef0a9aece191bc041add9c58ea98e7b2ebeb82fd80f16", legacyRevision = "5f56dead92ddd088141d051933eca46a3106d3110a703de4cc4144fef1834537", keywords = { "Legacy", "Legacy Points", "Legacy Progress Track", "Legacy Reward", "Innkeeper Wiley", "Ratchet", "bear cub", "bear" }, collects = { 277714 },
			steps = {
				{ title = "Innkeeper Wiley in Ratchet", tip = "Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, a crafting profession at 150, 225 and 300, PvP ranks and battleground reputations, exploring, dungeons and raids) is worth one, and the track counts points earned, not spent. It gives the Replica Ironforge Air Rifle at 15, the Spectral Bear Cub at 25, the Spectral Bear Tabard at 40 and the Reins of the Spectral Bear at 55. The rewards are claimed as quests from Innkeeper Wiley in the inn at Ratchet, the goblin port on the Barrens coast (Alliance players come by the boat from Booty Bay): with 25 points he offers Legacy Reward: Spectral Bear Cub; hand it straight back for the cub.", zone = 1413, goals = {
					{ kind = "note", text = "Without PvP one character can earn 17 points: its class at 25, 45 and 60, two professions to 300, the two adventure challenges, the three dungeon tiers and the three raids. A second class or more professions on an alt make up the rest; the Legacy Challenges guide plans them." },
					{ kind = "accept", quest = 96383 },
					{ kind = "turnin", quest = 96383 },
					{ kind = "collect", item = 277714, name = "Spectral Bear Cub", map = 1413, x = 62, y = 39.4 },
				} },
			},
		},
