					{ kind = "turnin", quest = 901 },
					{ kind = "accept", quest = 902, note = "Sputtervalve in Ratchet: on the next Ratchet stop" },
				} },
				{ title = "The Disruption Ends", tip = "Back to the Razormane camp. Geomancers and Defenders hold its eastern half; Kreenig Snarlsnout walks among them.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near Kreenig: pull Kreenig and the quilboar away from them one at a time.", zone = 1413, goals = {
					{ kind = "kill", quest = 872, objective = 2, npc = 3266 },
					{ kind = "kill", quest = 872, objective = 1, npc = 3269 },
