					{ kind = "collect", quest = 1525, objective = 1, item = 5026, only = { races = { "Tauren" }, classes = { "Shaman" } } },
				} },
				{ title = "Durotar", only = { races = { "Tauren" }, classes = { "Shaman" } }, zone = 1411, goals = {
