					{ kind = "turnin", quest = 870, note = "Tonga Runetotem" },
					{ kind = "accept", quest = 877, note = "Tonga Runetotem: the bubbling fissure at the Stagnant Oasis, on the Verog pass" },
				} },
				{ title = "Harpy Lieutenants", tip = "North-west to the Dry Hills: the Witchwing Slayers hold their western end; they wear the rings.\nCareful: Some stealthed harpy ambushers wait in the area and stay hidden until you get close. A level 19 elite harpy also patrols there.", zone = 1413, goals = {
					{ kind = "collect", quest = 875, objective = 1, item = 5065 },
				} },
