					{ kind = "goto", label = "Cast Teleport: Moonglade", map = 1450, x = 56.3, y = 32.5 },
				} },
				{ title = "Trial of the Lake", tip = "Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of Lake Elune'ara and fade within minutes: swim one straight to the Shrine of Remulos on the north-west shore, use it there and speak to Tajarri. Trial of the Lake runs on a timer: no teleport or Hearthstone until Tajarri has it.", only = { races = { "Tauren", "Skyborne" }, classes = { "Druid" } }, zone = 1450, goals = {
					{ kind = "turnin", quest = 27, only = { races = { "Tauren", "Skyborne" } }, note = "Dendrite Starblaze" },
					{ kind = "turnin", quest = 6126, only = { races = { "Tauren", "Skyborne" } } },
					{ kind = "accept", quest = 6127, only = { races = { "Tauren", "Skyborne" } }, note = "The Principal Source: Dreadmist Peak, next guide" },
