					{ kind = "interact", quest = 905, objective = 3, object = 6906 },
				} },
				{ title = "Raptor Grounds: kill these as you meet them", tip = "Sunscale Scytheclaws hunt the plains around the Raptor Grounds; they drop the horns. Mebok takes them when the escort brings you back to Ratchet.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of Northwatch Hold.", zone = 1413, goals = {
					{ kind = "collect", quest = 865, objective = 1, item = 5055 },
					{ kind = "collect", quest = 3281, objective = 1, item = 5061 },
				} },
				{ title = "Stolen Booty", tip = "East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, a short walk north of Northwatch Hold.", zone = 1413, goals = {
					{ kind = "collect", quest = 888, objective = 1, item = 5076, map = 1413, x = 62.6, y = 49.6 },
					{ kind = "collect", quest = 888, objective = 2, item = 5077, map = 1413, x = 63.6, y = 49.3 },
				} },
				{ title = "Northwatch Hold: kill these as you meet them", tip = "Northwatch Hold, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier.", zone = 1413, goals = {
					{ kind = "collect", quest = 891, objective = 4, item = 5078 },
					{ kind = "kill", quest = 891, objective = 1, npc = 3393, note = "On the top floor" },
					{ kind = "kill", quest = 891, objective = 2, npc = 3455, note = "On the top floor" },
					{ kind = "kill", quest = 891, objective = 3, npc = 3454, note = "Upstairs" },
				} },
				{ title = "Free From the Hold", tip = "Gilthares Firebough is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to Ratchet.", zone = 1413, goals = {
