				{ title = "Wrongly Blamed, Justly Corrected", tip = "A few steps east of Sulhasa's tree, a small camp: two Encroaching Soldiers and the Outraged Pillager for Logmar. The Outraged Pillager is elite: grouping up is advised.", when = { { quest = 97250, test = "group" } }, zone = 1413, goals = {
					{ kind = "kill", quest = 97250, objective = 1, npc = 268622, map = 1413, x = 48.8, y = 77 },
					{ kind = "kill", quest = 97250, objective = 2, npc = 268623, map = 1413, x = 48.8, y = 77 },
				} },
				{ title = "Bael Modan", tip = "South of Gann, the Bael'dun dwarves dig at Bael Modan. Excavators and Foremen work the pit; Prospector Khazgorm (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight.", zone = 1413, goals = {
					{ kind = "kill", quest = 843, objective = 1, npc = 3374 },
					{ kind = "kill", quest = 843, objective = 2, npc = 3375, note = "Bael'dun Foreman walks around Bael Modan: look inside the circle on the map" },
					{ kind = "collect", quest = 843, objective = 3, item = 5006 },
				} },
				{ title = "Blackthorn Ridge", tip = "West of Gann, the Razormane hold Blackthorn Ridge. Kuz is on the east side, Nak to the south, Lok Orcbane at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; Hagg Taurenbane, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. Washte Pawne, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with Sinister Strike, so they can join a fight without warning.", zone = 1413, goals = {
					{ kind = "collect", quest = 879, objective = 2, item = 5073 },
					{ kind = "collect", quest = 893, objective = 2, item = 5092 },
					{ kind = "collect", quest = 893, objective = 3, item = 5094 },
					{ kind = "collect", quest = 879, objective = 3, item = 5072 },
					{ kind = "collect", item = 5103, optional = true, note = "Washte Pawne's Feather" },
					{ kind = "accept", quest = 885, optional = true },
					{ kind = "goto", label = "Blackthorn Ridge", map = 1413, x = 42.5, y = 81 },
					{ kind = "collect", quest = 893, objective = 1, item = 5093 },
					{ kind = "collect", quest = 879, objective = 1, item = 5074 },
				} },
