		{
			id = "forever/horde/05-stonetalon-mountains", title = "Ashenvale & Silverpine Forest", category = "Leveling", faction = "Horde", levels = { 21, 23 }, zone = 1440, next = "forever/horde/06-hillsbrad-foothills", version = 1, revision = "f0208a8e900496c86da81b558c80c7bdba445104923566de3eea4b3130e7ddc8", legacyRevision = "425ded726db2941f0d2f8c248ca9fd84c520f3036e174e60c01fd8f94fa7370d",
			steps = {
				{ title = "Taskmaster Fizzule", tip = "On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the Sludge Fen. Before you go near Fizzule, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first.", only = { classes = { "Rogue" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 2458, note = "Taskmaster Fizzule" },
					{ kind = "accept", quest = 2478, optional = true },
					{ kind = "note", text = "Mission: Possible But Not Probable is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)." },
				} },
				{ title = "Kadrak", tip = "From Seereth's camp head north-east across the Barrens to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. Kadrak stands on the watch tower of the Mor'shan Rampart where the road enters Ashenvale.", zone = 1413, goals = {
					{ kind = "turnin", quest = 6541, note = "Kadrak" },
				} },
				{ title = "Into Ashenvale", zone = 1440, goals = {
					{ kind = "goto", label = "The road north to Splintertree Post", map = 1440, x = 71.1, y = 68.1 },
				} },
				{ title = "Splintertree Post", tip = "Splintertree Post is just north up the road. Coming in from the south, the flight master and Senani Thunderheart's hunt board at Night Run come first, then the vendors. Kuray'bin at the lumber camp offers Ashenvale Outrunners: leave it for the next Ashenvale visit, at 26.", zone = 1440, goals = {
					{ kind = "getfp", place = "Splintertree Post" },
					{ kind = "turnin", quest = 6382, note = "Senani Thunderheart" },
					{ kind = "turnin", quest = 6383, direct = true },
					{ kind = "note", text = "Senani's hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next Ashenvale visit, at 26." },
					{ kind = "vendor", nearest = true },
				} },
				{ title = "Va'xug Firefure", tip = "On the way west, Va'xug Firefure is stuck in a ravine south of the main road, south-east of Astranaar. Shadowhorn Stags and Ashenvale Bears roam the woods all around it.", zone = 1440, goals = {
					{ kind = "accept", quest = 98251, map = 1440, x = 40.4, y = 61.5, note = "Va'xug Firefure" },
					{ kind = "kill", quest = 98251, objective = 1, npc = 3817 },
					{ kind = "kill", quest = 98251, objective = 2, npc = 3809 },
					{ kind = "turnin", quest = 98251 },
					{ kind = "accept", quest = 98252 },
				} },
				{ title = "A Void Path", tip = "Steer Va'xug's Eye of Kilrogg out of the ravine to the main road within four minutes; if the channel breaks, ask Va'xug again.", zone = 1440, goals = {
					{ kind = "turnin", quest = 98252, map = 1440, x = 38.2, y = 58.1, note = "Eye of Kilrogg, on the road" },
				} },
				{ title = "Zoram'gar Outpost", tip = "Head west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai, Mitsuwa and Karang Amakkar stand around it, the Warsong Runner beside the flight master. Its other quests are for the next visit, at 26.", zone = 1440, goals = {
					{ kind = "getfp", place = "Zoram'gar Outpost" },
					{ kind = "accept", quest = 6442, note = "Marukai" },
					{ kind = "accept", quest = 6462, note = "Mitsuwa: the troll charms are in Thistlefur Hold, east of the outpost" },
					{ kind = "accept", quest = 216, note = "Karang Amakkar" },
					{ kind = "accept", quest = 6641, note = "Muglash: take it last, his escort starts at once" },
				} },
				{ title = "Vorsha the Lasher", tip = "Muglash walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads Marukai wants.", zone = 1440, goals = {
					{ kind = "goto", label = "Naga brazier", map = 1440, x = 9.6, y = 27.6 },
					{ kind = "complete", quest = 6641 },
				} },
				{ title = "Naga heads", tip = "Every Wrathtail naga along the strand north of the outpost drops heads.", zone = 1440, goals = {
					{ kind = "collect", quest = 6442, item = 5490 },
				} },
				{ title = "Zoram'gar Outpost", tip = "Back to the outpost before heading east to Thistlefur.", zone = 1440, goals = {
					{ kind = "turnin", quest = 6641, note = "Warsong Runner" },
					{ kind = "turnin", quest = 6442, note = "Marukai" },
				} },
				{ title = "Thistlefur Village", tip = "East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs.", zone = 1440, goals = {
					{ kind = "kill", quest = 216, objective = 1, npc = 3925 },
					{ kind = "kill", quest = 216, objective = 2, npc = 3924 },
				} },
				{ title = "Thistlefur Hold", tip = "Inside the hold, Troll Chests lie along the tunnels. Ruul Snowhoof is held deep inside: free him and protect him all the way out, then he runs home to Night Run.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where Dal Bloodclaw roams.", zone = 1440, goals = {
					{ kind = "collect", quest = 6462, item = 16602, note = "Below ground" },
					{ kind = "accept", quest = 6482, note = "Ruul Snowhoof, below ground" },
					{ kind = "complete", quest = 6482 },
				} },
				{ title = "Zoram'gar Outpost", tip = "Back west to Zoram'gar. Karang offers King of the Foulweald now; leave it for the next Ashenvale visit at 26, when the walk east passes the Foulweald.", zone = 1440, goals = {
					{ kind = "turnin", quest = 216, note = "Karang Amakkar" },
					{ kind = "turnin", quest = 6462, note = "Mitsuwa" },
				} },
				{ title = "Splintertree Post", tip = "Fly to Splintertree Post: Yama Snowhoof waits in the inn for news of Ruul.", zone = 1440, goals = {
					{ kind = "fly", place = "Splintertree Post" },
					{ kind = "turnin", quest = 6482, note = "Yama Snowhoof, inside the inn" },
				} },
				{ title = "Fly to Orgrimmar", tip = "Out of the inn to the Splintertree Post flight master and fly to Orgrimmar.", zone = 1440, goals = {
					{ kind = "goto", label = "Splintertree Post flight master", map = 1440, x = 73.26, y = 61.67 },
					{ kind = "fly", place = "Orgrimmar" },
				} },
