				{ title = "Zeppelin to Undercity", zone = 1411, goals = {
					{ kind = "goto", label = "Zeppelin to Undercity", map = 1411, x = 50.8, y = 13.5 },
				} },
				{ title = "Brill", tip = "Shari Stilwell trains Paladins in Brill, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine.", only = { classes = { "Paladin" } }, zone = 1420, goals = {
					{ kind = "train", classTrainer = true },
				} },
				{ title = "Strange Lockbox", tip = "From the zeppelin towers, run south into Silverpine and west past the Dead Field to the coast: the Strange Lockbox lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the Half Pendant of Aquatic Endurance for Trial of the Sea Lion. Then on to the Sepulcher.", only = { races = { "Tauren", "Skyborne" }, classes = { "Druid" } }, when = { { test = "onquest", quests = { 30 } } }, zone = 1421, goals = {
					{ kind = "collect", item = 15882, note = "Half Pendant of Aquatic Endurance, from the Strange Lockbox" },
				} },
				{ title = "The Sepulcher", tip = "Down the road through Silverpine to the Sepulcher: from the zeppelin towers, south through Tirisfal; from the Strange Lockbox, south-east from the coast to the road. Shadow Priest Allister and Apothecary Renferrel stand by the crypt entrance.", zone = 1421, goals = {
					{ kind = "accept", quest = 493, note = "Apothecary Renferrel: Lydon in Tarren Mill, next guide" },
					{ kind = "accept", quest = 95981, note = "Shadow Priest Allister" },
					{ kind = "accept", quest = 516, note = "Shadow Priest Allister: Beren's Peril, south-east of Ambermill" },
				} },
				{ title = "Deathguard Podrig", tip = "Deathguard Podrig stands just west of the crypt entrance: hand him Gordon's Crate from the Undercity.", only = { races = { "Scourge" } }, when = { { test = "onquest", quests = { 6324 } } }, zone = 1421, goals = {
					{ kind = "turnin", quest = 6324, note = "Deathguard Podrig" },
				} },
				{ title = "Silverpine Forest: kill these as you meet them", tip = "South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around Ambermill, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of Beren's Peril in the south-east of the forest.", zone = 1421, goals = {
					{ kind = "kill", quest = 95981, objective = 2, npc = 1889 },
					{ kind = "kill", quest = 95981, objective = 1, npc = 1888 },
					{ kind = "kill", quest = 516, objective = 2, npc = 1973, note = "Below ground" },
					{ kind = "kill", quest = 516, objective = 1, npc = 1974 },
				} },
				{ title = "Beren's Peril", tip = "The Ravenclaw undead haunt the ruins of Beren's Peril, east of the road in the south-east of the forest; a Ravenclaw Guardian drops the Note Scrap that leads to the Offering Stone.\nAn elite spirit (20) often stands beside the Offering Stone: pull the Ravenclaws away from the stone before you fight them.", zone = 1421, goals = {
					{ kind = "accept", quest = 95884, item = 271343, note = "Note Scrap, from a Ravenclaw Guardian" },
					{ kind = "turnin", quest = 95884, map = 1421, x = 58.1, y = 69.8, note = "Offering Stone" },
					{ kind = "accept", quest = 95883, note = "the Offering Stone offers The Tortured Soul once the Note Scrap is in; below ground" },
					{ kind = "collect", quest = 95883, objective = 1, item = 271350, map = 1421, x = 58.1, y = 69.9, note = "Tortured Soul, from the Tortured Souls among the ruins; below ground" },
					{ kind = "turnin", quest = 95883, note = "Below ground" },
				} },
				{ title = "The Offering of Blood", tip = "The quest hands you a Tortured Soul: use it beside the Offering Stone to offer your blood, then kill the elite spirit that answers.\nThe Tortured Soul is elite: grouping up is advised.", zone = 1421, goals = {
					{ kind = "goto", label = "Offering Stone", map = 1421, x = 58.1, y = 69.8 },
					{ kind = "accept", quest = 95885, optional = true, note = "Below ground" },
					{ kind = "use", item = 210713, map = 1421, x = 58.1, y = 69.8, optional = true, note = "Tortured Soul, beside the Offering Stone: summons the elite spirit" },
					{ kind = "kill", quest = 95885, objective = 3, npc = 212753, optional = true },
					{ kind = "turnin", quest = 95885, optional = true, note = "Below ground" },
				} },
				{ title = "Into Hillsbrad", zone = 1424, goals = {
					{ kind = "goto", label = "The road east to Southpoint Tower", map = 1424, x = 20.8, y = 47.4 },
