					{ kind = "accept", quest = 98070, note = "Jandia, the trade supplies vendor: the Screeching harpies of Roguefeather Den; inside the inn" },
					{ kind = "accept", quest = 98069, note = "Jandia: her stolen supplies lie in the same harpy den" },
