				{ title = "Rau Cliffrunner", tip = "Rau Cliffrunner stands in Freewind Post: Zangen's filled phial is for him.", when = { { test = "onquest", quests = { 1196 } } }, zone = 1441, goals = {
					{ kind = "turnin", quest = 1196, note = "Rau Cliffrunner" },
