				{ title = "Darkcloud Pinnacle", tip = "West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps.", zone = 1441, goals = {
					{ kind = "interact", quest = 5064, objective = 3, object = 190484, map = 1441, x = 39.3, y = 41.5, note = "Document Chest, south-east camp" },
