					{ kind = "interact", quest = 5064, objective = 1, object = 176344, map = 1441, x = 31.8, y = 32.6, note = "Document Chest, north-west camp" },
				} },
				{ title = "Level 28.9", tip = "Short of 28.9? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to Lakota. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon or the Razorfen Kraul dungeon instead.", when = { { level = 28.9, test = "level", op = "<" } }, zone = 1441, goals = {
					{ kind = "goto", label = "Grimtotem camps below Darkcloud Pinnacle", map = 1441, x = 35, y = 31.5 },
					{ kind = "level", level = 28.9, grind = 10759, note = "grind on Grimtotem Stomper" },
				} },
				{ title = "Lakota Windsong", tip = "Climb the path to the top of Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way.", zone = 1441, goals = {
					{ kind = "collect", quest = 5147, item = 12884, map = 1441, x = 38.1, y = 26.9, note = "Arnak Grimtotem" },
					{ kind = "accept", quest = 4904, map = 1441, x = 37.95, y = 26.45, note = "Lakota Windsong" },
					{ kind = "complete", quest = 4904 },
				} },
				{ title = "Highperch", tip = "West of Whitereach the wyverns nest on the Highperch cliffs; the eggs lie in the nests. Pao'ka Swiftmountain waits on the east side of the nesting grounds: free him and keep him alive on the walk back to Whitereach Post.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom.", zone = 1441, goals = {
					{ kind = "collect", quest = 4767, item = 12356 },
					{ kind = "accept", quest = 4770, note = "Pao'ka Swiftmountain" },
					{ kind = "complete", quest = 4770 },
				} },
