				{ title = "Kanati Greycloud", tip = "Only if the Galak Messenger dropped his plot for you: Kanati Greycloud stands at Whitereach Post.", when = { { test = "onquest", quests = { 4881, 4966 } } }, zone = 1441, goals = {
					{ kind = "turnin", quest = 4881, note = "Kanati Greycloud" },
