				{ title = "Level 29.49", tip = "If you skipped Hypercapacitor Gizmo and are still short of 29.49, kill harpies here first: Roguefeather Den is your next stop anyway. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon or the Scarlet Monastery dungeon (Graveyard) instead.", when = { { quest = 5151, test = "group", negate = true }, { level = 29.49, test = "level", op = "<" } }, zone = 1441, goals = {
					{ kind = "goto", label = "Screeching Roguefeather", map = 1441, x = 27, y = 51.9 },
					{ kind = "level", level = 29.49, grind = 4101, note = "grind on Screeching Roguefeather" },
				} },
				{ title = "The Screeching Canyon: kill these as you meet them", tip = "South of Darkcloud, the harpies of Roguefeather Den. Grenka Bloodscreech (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are Jandia's; her Stolen Freewind Supplies lie on the ground along the foot of the cliff and in the cave up on top.", zone = 1441, goals = {
					{ kind = "kill", quest = 98070, objective = 2, npc = 4101 },
					{ kind = "kill", quest = 98070, objective = 3, npc = 4104 },
					{ kind = "kill", quest = 98070, objective = 1, npc = 4100 },
					{ kind = "collect", quest = 98069, item = 279383, count = 8, map = 1441, x = 27, y = 51.9, note = "Stolen Freewind Supplies, on the ground around the den" },
					{ kind = "collect", quest = 1150, item = 5843 },
				} },
				{ title = "Freewind Post", tip = "Back east to Freewind Post: it lies on the way from Roguefeather Den to Dorn's mesa.", zone = 1441, goals = {
