				{ title = "The Undercity", tip = "Elixir of Agony needs a Lesser Troll's Blood Elixir, an Alchemy item: buy one at the auction house if you can (or ask an alchemist). The quest text says Strong, but it takes a Lesser Troll's Blood Elixir. No elixir: skip the Elixir steps in Hillsbrad.", zone = 1458, goals = {
					{ kind = "note", text = "Lesser Troll's Blood Elixir: auction house or an alchemist, for Elixir of Agony." },
				} },
				{ title = "Garen Largo", tip = "Garen Largo trains Paladins in the Undercity.", only = { classes = { "Paladin" } }, zone = 1458, goals = {
					{ kind = "train", classTrainer = true },
				} },
				{ title = "Undercity flight master", only = { classes = { "Shaman" } }, zone = 1458, goals = {
					{ kind = "goto", label = "Undercity flight master", map = 1458, x = 63.1, y = 48.3 },
				} },
				{ title = "Brazier of Everfount", tip = "Fly to the Sepulcher. The Brazier of Everfount stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the Minor Manifestation of Water and keep the Shard of Water for Islen. Fly on to Tarren Mill from the Sepulcher.", only = { classes = { "Shaman" } }, zone = 1421, goals = {
					{ kind = "fly", place = "The Sepulcher" },
					{ kind = "use", quest = 63, objective = 1, item = 6637, map = 1421, x = 38.5, y = 44.4, note = "Water Sapta: drink it by the standing stone to see the elemental" },
					{ kind = "collect", quest = 63, objective = 1, item = 7812 },
					{ kind = "turnin", quest = 63, note = "Brazier of Everfount" },
					{ kind = "accept", quest = 100 },
					{ kind = "turnin", quest = 100, note = "Minor Manifestation of Water" },
					{ kind = "accept", quest = 96, note = "for Islen Waterseer, next guide" },
				} },
				{ title = "Fly to Tarren Mill", only = { classes = { "Shaman" } }, zone = 1421, goals = {
