				{ title = "High Executor Darthalia", tip = "You missed Darthalia's first errands, from the 22-25 Hillsbrad guide: they come first now. They are a few levels below you and quick, and they open the rest of the Battle of Hillsbrad in this guide.", when = { { quest = 529, test = "turnedin", negate = true } }, zone = 1424, goals = {
					{ kind = "accept", quest = 527, note = "High Executor Darthalia" },
