					{ kind = "accept", quest = 498, note = "Krusk, inside" },
				} },
				{ title = "Hillsbrad Fields", tip = "West past the hills to the farms east of Hillsbrad town. Farmer Ray works the field by the northern farmhouse, Farmer Getz the one further south-east; Farmhands and Farmers are everywhere.", when = { { quest = 529, test = "turnedin", negate = true } }, zone = 1424, goals = {
