					{ kind = "turnin", quest = 527, note = "High Executor Darthalia" },
					{ kind = "accept", quest = 528 },
				} },
				{ title = "Hillsbrad Peasants", tip = "Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping.", when = { { quest = 529, test = "turnedin", negate = true } }, zone = 1424, goals = {
