					{ kind = "interact", quest = 498, objective = 2, object = 1722, note = "Tog'thar's ball and chain" },
				} },
				{ title = "The smithy", tip = "West across the foothills to Hillsbrad town: the smithy stands in the middle of it. Blacksmith Verringtan and his apprentices work at the forge; the Shipment of Iron is stacked beside it.", when = { { quest = 529, test = "turnedin", negate = true } }, zone = 1424, goals = {
