					{ kind = "buy", npc = 2388, item = 3703, count = 1, note = "Southshore Stout, for Henchman Valik" },
				} },
				{ title = "Helcular's Rod", tip = "South-west, the Cave and Ferocious Yetis (30-32) fill the Foothill Caverns in the hills west of Tarren Mill; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs.", zone = 1424, goals = {
					{ kind = "collect", quest = 552, item = 3708, map = 1424, x = 44.5, y = 29.4 },
				} },
				{ title = "Level 30", tip = "Tarren Mill's Prison Break In, Stone Tokens and The Hammer May Fall are offered from level 30. Below it? Keep killing the yetis in these caves until level 30. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.", when = { { level = 30, test = "level", op = "<" } }, zone = 1424, goals = {
					{ kind = "goto", label = "Foothill Caverns", map = 1424, x = 44, y = 28 },
					{ kind = "level", level = 30, grind = 2248, note = "grind on Cave Yeti" },
				} },
				{ title = "Town hall", tip = "On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.", zone = 1424, goals = {
					{ kind = "kill", quest = 532, objective = 2, npc = 2387 },
					{ kind = "interact", quest = 532, objective = 3, object = 1761, note = "Hillsbrad Proclamation, inside" },
					{ kind = "collect", quest = 532, objective = 4, item = 3657, note = "Inside" },
					{ kind = "kill", quest = 567, objective = 1, npc = 2448, note = "Inside" },
					{ kind = "kill", quest = 532, objective = 1, npc = 2335, note = "Inside" },
				} },
				{ title = "Tarren Mill", tip = "Back east to Tarren Mill.", zone = 1424, goals = {
