					{ kind = "accept", quest = 556, note = "Keeper Bel'varil, inside: offered from level 30" },
					{ kind = "accept", quest = 676, note = "Tallow: for Drum Fel in Hammerfall, later in this guide (from level 30)" },
				} },
				{ title = "Foothill Caverns", tip = "Back into the yeti caves west of Tarren Mill with the Rod of Helcular. The path splits just inside: the Flame of Azel burns on the upper level to the right, the Flame of Veraz on the lower level to the left, past more yetis.", zone = 1424, goals = {
					{ kind = "use", quest = 553, objective = 1, item = 3710, map = 1424, x = 43.9, y = 28.1, note = "Flame of Azel" },
					{ kind = "use", quest = 553, objective = 2, item = 3710, map = 1424, x = 44.1, y = 26.6, note = "Flame of Veraz" },
				} },
				{ title = "Flame of Uzel", tip = "The third flame burns in the smaller cave up in the hills north of the caverns.\nCareful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in.", zone = 1424, goals = {
					{ kind = "use", quest = 553, objective = 3, item = 3710, map = 1424, x = 41.7, y = 6.4, note = "Flame of Uzel" },
				} },
				{ title = "Alterac Mountains", zone = 1416, goals = {
					{ kind = "goto", label = "The Dalaran crater's eastern rim", map = 1416, x = 24.5, y = 82.8 },
				} },
				{ title = "The Dalaran crater", tip = "Head west along the foot of the mountains to the violet dome of Dalaran. Ricter, Alina and Dermot (33-34) stand together inside the crater's eastern rim, Kegan Darkmar (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens. Careful: Many guards stand in linked pairs and others patrol alone around the camp.", zone = 1416, goals = {
					{ kind = "collect", quest = 544, objective = 1, item = 3691, note = "Dermot" },
					{ kind = "collect", quest = 544, objective = 2, item = 3689, note = "Ricter" },
