				{ title = "Elixir of Agony with a group", tip = "Lydon's next errand is a keg of Shindigger Stout from the cellar of Dun Garok, the elite dwarven keep south-east of Southshore: take it only if you go there with a group.", when = { { quest = 517, test = "group" }, { quest = 515, test = "turnedin" } }, zone = 1424, goals = {
