				{ title = "Undercity trainers", tip = "Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", only = { classes = { "Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock" } }, zone = 1458, goals = {
