				{ title = "Alliance Relations", tip = "The zeppelin lands at the tower outside Orgrimmar's main gate. Craven Drok walks the Drag: if he isn't at the arrow, look along its streets to the south-west. Keldran stands in the Valley of Spirits on the west side of the city.", zone = 1454, goals = {
					{ kind = "accept", quest = 1431, note = "Craven Drok: offered from level 30" },
					{ kind = "turnin", quest = 1431, note = "Keldran" },
					{ kind = "accept", quest = 1432, note = "for Takata Steelblade in Desolace, later in this guide" },
				} },
				{ title = "Orgrimmar trainers", tip = "Train while you are in the city.", only = { classes = { "Hunter", "Shaman" } }, zone = 1454, goals = {
					{ kind = "train", classTrainer = true },
				} },
				{ title = "Searn Firewarder", tip = "Searn Firewarder stands in the Valley of Wisdom.", only = { classes = { "Shaman" } }, zone = 1454, goals = {
					{ kind = "accept", quest = 1531, note = "Searn Firewarder: for Prate Cloudseer by Freewind Post, later in this guide" },
				} },
				{ title = "Nogg", tip = "Nogg's workshop is in the Valley of Honor. Rig Wars is Gnomeregan's last boss: great XP if you run it with a group. Run it whenever your group is ready; hand it in on a later Orgrimmar stop.", when = { { name = "Gnomeregan", test = "dungeon" } }, zone = 1454, goals = {
					{ kind = "accept", quest = 2841, note = "Nogg" },
				} },
				{ title = "Gnomeregan", when = { { name = "Gnomeregan", test = "dungeon" } }, zone = 1454, goals = {
					{ kind = "note", text = "Run Gnomeregan with a group when it suits you: Mekgineer Thermaplugg at the end drops his Safe Combination; open his safe behind the northern bomb pillar for the Rig Blueprints." },
				} },
				{ title = "Orgrimmar flight master", zone = 1454, goals = {
