				{ title = "Islen Waterseer", tip = "Fly from Orgrimmar to Ratchet. Islen Waterseer camps on the coast a short walk south of the town; fly on to Freewind Post from Ratchet.", only = { classes = { "Shaman" } }, zone = 1413, goals = {
					{ kind = "fly", place = "Ratchet" },
					{ kind = "turnin", quest = 96, note = "Islen Waterseer: Healing Stream Totem and your Water Totem" },
