				{ title = "Prate Cloudseer", tip = "Prate Cloudseer hides in a small cave in the canyon wall north-east of the post, on the way east.", only = { classes = { "Shaman" } }, zone = 1441, goals = {
					{ kind = "turnin", quest = 1531, note = "Prate Cloudseer: your Air Totem" },
					{ kind = "note", text = "Prate also starts Elemental Aid (Razorfen Kraul), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde." },
				} },
				{ title = "Moktar Krin", tip = "Take the lift down and follow the canyon east. Moktar Krin camps on the north-western edge of the salt flats.", zone = 1441, goals = {
					{ kind = "turnin", quest = 1146, note = "Moktar Krin" },
					{ kind = "accept", quest = 1147 },
				} },
				{ title = "Mirage Raceway", tip = "The goblins and gnomes of the Mirage Raceway are neutral and give quests to both factions.", zone = 1441, goals = {
					{ kind = "accept", quest = 1110, note = "Kravel Koalbeard" },
					{ kind = "accept", quest = 5762, note = "Kravel's crate for Hemet Nesingwary in Stranglethorn, later on the route" },
					{ kind = "accept", quest = 1104, note = "Fizzle Brassbolts" },
					{ kind = "accept", quest = 1105, note = "Wizzle Brassbolts" },
					{ kind = "accept", quest = 1176, note = "Pozzik" },
					{ kind = "accept", quest = 1175, note = "Trackmaster Zherin" },
				} },
				{ title = "The southern flats", tip = "South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats.", zone = 1441, goals = {
					{ kind = "kill", quest = 1175, objective = 2, npc = 4151, map = 1441, x = 78.4, y = 87.9 },
					{ kind = "kill", quest = 1175, objective = 3, npc = 4150, map = 1441, x = 77.1, y = 88.4 },
				} },
				{ title = "The Rustmaul Dig Site", tip = "West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a Cracked Silithid Carapace: open it.\nCareful: Hive Drones call for help when they fall to 20% health.", zone = 1441, goals = {
					{ kind = "kill", quest = 1147, objective = 1, npc = 4130, map = 1441, x = 69.8, y = 83.3 },
					{ kind = "kill", quest = 1147, objective = 2, npc = 4133, map = 1441, x = 68, y = 85.7 },
					{ kind = "kill", quest = 1147, objective = 3, npc = 4131, map = 1441, x = 64.8, y = 86 },
					{ kind = "collect", item = 5877, count = 1 },
					{ kind = "accept", quest = 1148, item = 5877 },
				} },
				{ title = "Parts of the Swarm", tip = "Keep killing silithid at the dig site for the heart, the talons and the carapaces.", zone = 1441, goals = {
					{ kind = "collect", quest = 1148, objective = 1, item = 5855 },
					{ kind = "collect", quest = 1148, objective = 2, item = 5854 },
					{ kind = "collect", quest = 1148, objective = 3, item = 5853 },
				} },
				{ title = "Moktar Krin", tip = "North from the dig to Moktar Krin's camp on the western edge of the flats.", zone = 1441, goals = {
					{ kind = "turnin", quest = 1147 },
				} },
				{ title = "Shimmering Flats: kill these as you meet them", tip = "East onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.", zone = 1441, goals = {
					{ kind = "kill", quest = 1175, objective = 1, npc = 4147, map = 1441, x = 75.7, y = 57.3 },
					{ kind = "collect", quest = 1105, item = 5795, map = 1441, x = 82.1, y = 55, note = "Hardened Tortoise Shell" },
					{ kind = "collect", quest = 1176, item = 5848, map = 1441, x = 87.9, y = 65.4, note = "Hollow Vulture Bone" },
					{ kind = "collect", quest = 1110, item = 5798, note = "Rocket Car Rubble, all over the northern flats" },
					{ kind = "collect", quest = 1104, item = 5794, note = "Salt Flat Venom, from the Scorpid Reavers of the north half" },
				} },
				{ title = "Mirage Raceway", tip = "South-west back to the raceway.", zone = 1441, goals = {
					{ kind = "turnin", quest = 1110, note = "Kravel Koalbeard" },
					{ kind = "accept", quest = 1111, note = "Kravel Koalbeard: his parts order goes to Wharfmaster Dizzywig in Ratchet, later on the route" },
					{ kind = "turnin", quest = 1104, note = "Fizzle Brassbolts" },
					{ kind = "turnin", quest = 1105, note = "Wizzle Brassbolts" },
					{ kind = "accept", quest = 1106, note = "Fizzle Brassbolts: his letter goes to Martek in the Badlands, at 39" },
					{ kind = "turnin", quest = 1176, note = "Pozzik" },
					{ kind = "accept", quest = 1178, note = "Pozzik: for Gazlowe in Ratchet, later on the route" },
					{ kind = "turnin", quest = 1175, note = "Trackmaster Zherin" },
				} },
				{ title = "Level 32.5", tip = "Desolace's quests are 33-38. Still below 32.5 after the raceway's hand-ins? Keep killing the Sparkleshell Snappers on the flats just north of the raceway until level 32.5. Or, with a group, run the Scarlet Monastery dungeon (Graveyard or Library) instead.", when = { { level = 32.5, test = "level", op = "<" } }, zone = 1441, goals = {
					{ kind = "goto", label = "Sparkleshell Snappers", map = 1441, x = 77.5, y = 70.5 },
					{ kind = "level", level = 32.5, grind = 4143, note = "grind on Sparkleshell Snapper" },
				} },
				{ title = "Freewind Post", tip = "West back to Freewind Post. Cliffwatcher Longhorn stands in the middle of the post, on the way to the flight master.", zone = 1441, goals = {
					{ kind = "accept", quest = 5361, note = "Cliffwatcher Longhorn: for Nataka Longhorn in Desolace, next" },
					{ kind = "vendor", nearest = true },
				} },
				{ title = "Fly to Sun Rock Retreat", zone = 1441, goals = {
					{ kind = "goto", label = "Freewind Post flight master", map = 1441, x = 45, y = 49.1 },
					{ kind = "fly", place = "Sun Rock Retreat" },
