				{ title = "Desolace", zone = 1443, goals = {
					{ kind = "goto", label = "Scrabblescrew's Camp", map = 1443, x = 60.9, y = 61.9 },
				} },
				{ title = "Scrabblescrew's Camp", tip = "Head south out of Stonetalon into Desolace and follow the road south to Smeed's camp.", zone = 1443, goals = {
					{ kind = "accept", quest = 5561, note = "Smeed Scrabblescrew" },
				} },
				{ title = "Ghost Walker Post", tip = "Felgur stands in the post, Nataka Longhorn up on its rise; Takata Steelblade and Maurin Bonesplitter wait on the rise west of it, above the Kodo Graveyard.", zone = 1443, goals = {
					{ kind = "accept", quest = 1365, note = "Felgur Twocuts" },
					{ kind = "turnin", quest = 5361, note = "Nataka Longhorn, up on the rise" },
					{ kind = "turnin", quest = 1432, note = "Takata Steelblade" },
					{ kind = "accept", quest = 1433 },
					{ kind = "accept", quest = 1434 },
					{ kind = "turnin", quest = 1433, note = "Maurin Bonesplitter" },
					{ kind = "accept", quest = 1435 },
				} },
				{ title = "Kodo Graveyard", tip = "Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time.", zone = 1443, goals = {
					{ kind = "use", item = 13892, text = "Kodo Kombobulator", map = 1443, x = 51, y = 58.5, note = "on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it" },
					{ kind = "talk", quest = 5561, objective = 1, npc = 4700, map = 1443, x = 60.6, y = 61.6, note = "the tamed kodo, at Smeed's camp: talk to it, five times" },
				} },
				{ title = "Scrabblescrew's Camp", zone = 1443, goals = {
					{ kind = "turnin", quest = 5561, note = "Smeed Scrabblescrew" },
				} },
				{ title = "Level 33", tip = "Shadowprey's Hand of Iruxos and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of Smeed's camp are on your way west: kill them until level 33. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", when = { { level = 33, test = "level", op = "<" } }, zone = 1443, goals = {
					{ kind = "goto", label = "Scorpashi Lashers", map = 1443, x = 59.9, y = 54.6 },
					{ kind = "level", level = 33, grind = 4697, note = "grind on Scorpashi Lasher" },
				} },
				{ title = "Shadowprey Village", tip = "Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.\nAka'rai may not be here on Forever: if Aka'rai doesn't offer Hate the Hatefury, skip it.", zone = 1443, goals = {
					{ kind = "accept", quest = 97265, optional = true, note = "Aka'rai: the Hatefury satyrs of Sargeron, later in this guide" },
					{ kind = "accept", quest = 5381, note = "Taiga Wisemane" },
					{ kind = "sethome", place = "Shadowprey Village", note = "Innkeeper Sikewa" },
					{ kind = "accept", quest = 5763, note = "Roon Wildmane: for Hemet Nesingwary in Stranglethorn, next guide" },
					{ kind = "accept", quest = 6143, note = "Drulzegar Skraghook" },
					{ kind = "accept", quest = 6142, note = "Mai'Lahii" },
					{ kind = "getfp", place = "Shadowprey Village", note = "Thalon, at the village's south-west end" },
				} },
				{ title = "Ethel Rethor", tip = "Head north along the coast, then inland to the ruined tower of Ethel Rethor: Azore Aldamort waits inside. The coast's clams and naga come after Thunder Axe Fortress, on one walk north to Ranazjar Isle.", zone = 1443, goals = {
					{ kind = "accept", quest = 5741, note = "Azore Aldamort" },
				} },
				{ title = "Thunder Axe Fortress", tip = "Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Hand of Iruxos: clear the middle of the largest building, then use the Demon Pick on the red Hand of Iruxos Crystal there. A Demon Spirit (37) comes out: kill it for the Demon Box.", zone = 1443, goals = {
					{ kind = "collect", quest = 1435, item = 6435, map = 1443, x = 55, y = 26.5 },
					{ kind = "collect", quest = 5741, item = 15750, map = 1443, x = 55.2, y = 30.1, note = "On the top floor" },
					{ kind = "use", quest = 5381, objective = 1, item = 14523, map = 1443, x = 55, y = 26.7, note = "Demon Pick, on the Hand of Iruxos Crystal" },
					{ kind = "collect", quest = 5381, item = 13542 },
					{ kind = "collect", item = 20310, count = 1, optional = true },
					{ kind = "accept", quest = 1480, optional = true },
				} },
				{ title = "Ethel Rethor", tip = "Back west to Azore.", zone = 1443, goals = {
					{ kind = "turnin", quest = 5741, note = "Azore Aldamort" },
					{ kind = "accept", quest = 6027 },
				} },
				{ title = "Rackmore's Log", tip = "Rackmore's Log lies on the ground just south-west of Azore's tower, on the way down to the shore: read it. Its two keys drop only while you have the quest.", zone = 1443, goals = {
					{ kind = "accept", quest = 6161, object = 177787, note = "Rackmore's Log" },
				} },
				{ title = "Clam beds", tip = "West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a Soft-shelled Clam. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry Rackmore's Silver Key, about one in seven.", zone = 1443, goals = {
					{ kind = "interact", quest = 6142, objective = 1, object = 177784, map = 1443, x = 30.6, y = 31.9, note = "Giant Softshell Clams, on the sea floor" },
					{ kind = "use", quest = 6142, objective = 1, item = 15874, map = 1443, x = 30.6, y = 31.9, note = "Soft-shelled Clam: open it in your bags" },
					{ kind = "collect", quest = 6142, item = 15924, note = "Underwater" },
					{ kind = "collect", quest = 6161, objective = 1, item = 15878, map = 1443, x = 33.4, y = 30.1, note = "Rackmore's Silver Key, from the Drysnap crabs" },
				} },
				{ title = "Sar'theris Strand", tip = "Keep north to Sar'theris Strand. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop Rackmore's Golden Key.", zone = 1443, goals = {
					{ kind = "kill", quest = 6143, objective = 1, npc = 4714 },
					{ kind = "kill", quest = 6143, objective = 2, npc = 4711 },
					{ kind = "kill", quest = 6143, objective = 3, npc = 4712 },
					{ kind = "collect", quest = 6161, objective = 2, item = 15881, note = "Rackmore's Golden Key, from the Slitherblade naga" },
				} },
				{ title = "The Book of the Ancients", tip = "Swim out to Ranazjar Isle off the far northern tip and use the Gem of the Serpent on the Serpent Statue: Lord Kragaru (38) rises; kill him for the Book of the Ancients. He is well above you: rest to full first. Rackmore's Chest stands on the shore beside the statue: open it with both keys.", zone = 1443, goals = {
					{ kind = "use", quest = 6027, objective = 1, item = 15766, map = 1443, x = 28.2, y = 6.7, note = "Gem of the Serpent, on the Serpent Statue" },
					{ kind = "collect", quest = 6027, item = 15803 },
					{ kind = "turnin", quest = 6161, map = 1443, x = 30, y = 8.7, note = "Rackmore's Chest" },
				} },
				{ title = "Azore Aldamort", tip = "Back south to Azore's tower.", zone = 1443, goals = {
					{ kind = "turnin", quest = 6027 },
				} },
				{ title = "Sargeron", tip = "Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", zone = 1443, goals = {
					{ kind = "kill", quest = 1434, objective = 1, npc = 4670 },
					{ kind = "kill", quest = 1434, objective = 2, npc = 4672 },
					{ kind = "kill", quest = 1434, objective = 3, npc = 4673 },
					{ kind = "kill", quest = 1434, objective = 4, npc = 4675 },
					{ kind = "kill", quest = 97265, objective = 3, npc = 4674, map = 1443, x = 75.7, y = 15.8, optional = true, note = "Hatefury Shadowstalker" },
					{ kind = "kill", quest = 97265, objective = 2, npc = 4675, optional = true },
					{ kind = "kill", quest = 97265, objective = 1, npc = 4671, map = 1443, x = 76.5, y = 20.5, optional = true, note = "Hatefury Trickster, on the way south" },
					{ kind = "kill", quest = 97265, objective = 4, npc = 4672, optional = true },
					{ kind = "kill", quest = 97265, objective = 5, npc = 4670, optional = true },
				} },
				{ title = "Khan Dez'hepah", tip = "South to Kolkar Village. Khan Dez'hepah (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health.\nCareful: Kolkar Battle Lords call nearby allies within 30 yd once they fall to 20% health.", zone = 1443, goals = {
					{ kind = "collect", quest = 1365, item = 6066 },
				} },
				{ title = "Ghost Walker Post", tip = "South-west down the road to the post.", zone = 1443, goals = {
					{ kind = "turnin", quest = 1434, note = "Takata Steelblade" },
					{ kind = "turnin", quest = 1435, note = "Maurin Bonesplitter" },
					{ kind = "turnin", quest = 1480, optional = true },
					{ kind = "accept", quest = 1436, note = "Takata Steelblade: for Keldran in Orgrimmar, next guide" },
					{ kind = "note", text = "Takata's next errand sends you after a demon lord with an elite guard: skip it." },
					{ kind = "turnin", quest = 1365, note = "Felgur Twocuts" },
					{ kind = "accept", quest = 1366, note = "for the second Desolace visit, in forever/horde/30-40/04-dustwallow-marsh" },
				} },
				{ title = "Shadowprey Village", tip = "West to Shadowprey: your hearthstone is bound there.", zone = 1443, goals = {
					{ kind = "turnin", quest = 97265, npc = 268705, optional = true, note = "Aka'rai, on the path just north of the village" },
					{ kind = "turnin", quest = 5381, note = "Taiga Wisemane" },
					{ kind = "turnin", quest = 6142, note = "Mai'Lahii" },
					{ kind = "turnin", quest = 6143, note = "Drulzegar Skraghook" },
					{ kind = "note", text = "Taiga's Portals of the Legion and Desolace's other 38-40 quests wait for the second visit, at 38: the next guides fly to Orgrimmar and take the zeppelin to Stranglethorn Vale." },
				} },
			},
