		{
			id = "forever/horde/30-40/05-arathi-highlands", title = "Alterac Mountains & Arathi Highlands", category = "Leveling", faction = "Horde", levels = { 38, 39 }, zone = 1417, next = "forever/horde/30-40/06-badlands", version = 1, revision = "43e2db0d398d67b2f9544a8ab210f602972d38d4b0c54c049a2cffa7db50ecaa",
			steps = {
