				{ title = "Gol'dir", tip = "Head north past Valik's camp to Strahnbrad, the Syndicate-held village (35-37). Jailor Borhuin carries the Rusted Iron Key; Gol'dir sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam Strahnbrad, and the buildings hold many Syndicate mobs, mages among them.", zone = 1416, goals = {
					{ kind = "collect", quest = 503, objective = 1, item = 3704, note = "Inside" },
					{ kind = "complete", quest = 503, map = 1416, x = 60.6, y = 43.8, note = "Find where Gol'dir is held, on the top floor" },
					{ kind = "turnin", quest = 503, note = "Gol'dir, on the top floor" },
