				} },
				{ title = "Lord Aliden Perenolde", tip = "Head north-west through the mountains to the Perenolde manor on the northern shore of Lordamere Lake. Lord Aliden Perenolde (41) waits in a room upstairs: he shields himself, puts you to sleep and heals below half health. Elysa stands beside him.", zone = 1416, goals = {
					{ kind = "kill", quest = 507, objective = 1, npc = 2423, map = 1416, x = 39.3, y = 14.6 },
					{ kind = "turnin", quest = 507, note = "Elysa" },
					{ kind = "accept", quest = 508 },
				} },
				{ title = "Old Dalaran Ruins: kill these as you meet them", tip = "South along the lake shore to the ruins around the Dalaran crater. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves.", zone = 1416, goals = {
					{ kind = "kill", quest = 545, objective = 2, npc = 2359, map = 1416, x = 22.4, y = 58.6 },
