				{ title = "Tarren Mill", tip = "Head back east to Tarren Mill.", zone = 1424, goals = {
					{ kind = "turnin", quest = 557, note = "Keeper Bel'varil, inside" },
					{ kind = "turnin", quest = 545, note = "Magus Wordeen Voidglare, inside" },
