				{ title = "Foul Magics with a group", tip = "Tor'gan's next Foul Magics is Marez Cowl, a level 40 elite warlock in Stromgarde's Syndicate quarter.", when = { { quest = 673, test = "group" } }, zone = 1417, goals = {
					{ kind = "accept", quest = 673, note = "Tor'gan" },
				} },
				{ title = "Drywhisker Gorge", tip = "North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", zone = 1417, goals = {
					{ kind = "collect", quest = 642, item = 4435 },
				} },
				{ title = "Iridescent Shards", tip = "The Iridescent Shards lie at the far end of the gorge.", zone = 1417, goals = {
					{ kind = "turnin", quest = 642, note = "Below ground" },
					{ kind = "accept", quest = 651 },
				} },
				{ title = "The Stone of East Binding", tip = "Each Circle of Binding is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of Hammerfall.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", zone = 1417, goals = {
					{ kind = "collect", quest = 651, item = 4484, note = "Cresting Key" },
				} },
				{ title = "Boulderfist Hall", tip = "The Boulderfist Brutes camp outside the ogres' hall, far south-west of Hammerfall; the Magus stand among them. Pull them one at a time.", zone = 1417, goals = {
					{ kind = "kill", quest = 678, objective = 1, npc = 2566 },
					{ kind = "kill", quest = 678, objective = 2, npc = 2567 },
				} },
				{ title = "Fleshstalker raptors", tip = "Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of Boulderfist Hall and another on the plain to its west. Pull them one at a time.", zone = 1417, goals = {
					{ kind = "collect", quest = 701, item = 4513 },
				} },
				{ title = "Go'shek Farm", tip = "Apothecary Jorell's lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to Hammerfall; the case of Packaged Tonics is inside.", zone = 1417, goals = {
					{ kind = "collect", quest = 92519, item = 278462, map = 1417, x = 60.1, y = 59.3, note = "Packaged Tonics" },
