		{
			id = "forever/horde/30-40/06-badlands", title = "Badlands", category = "Leveling", faction = "Horde", levels = { 39, 40 }, zone = 1418, next = "forever/horde/40-50/01-stranglethorn-vale", version = 1, revision = "a9f134a57341cc6b5af19dabf185f2361e2a996d8e18a1bcadf70485f90f2e4a",
			steps = {
				{ title = "Into the Badlands", tip = "Head for the Thandol Span, the great bridge at Arathi's southern edge, cross it and follow the road south through the Wetlands to the Dun Algaz tunnel into Loch Modan. Thelsamar, the dwarf town on the road in the middle of Loch Modan, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves Loch Modan to the south into the Badlands; follow it to the goblin camp in the Valley of Fangs.", zone = 1418, goals = {
					{ kind = "goto", label = "Valley of Fangs", map = 1418, x = 42.3, y = 52.8 },
				} },
				{ title = "Valley of Fangs", zone = 1418, goals = {
					{ kind = "turnin", quest = 1106, note = "Martek the Exiled: Fizzle's letter from the Shimmering Flats" },
					{ kind = "accept", quest = 1108 },
					{ kind = "accept", quest = 703, note = "Rigglefuzz" },
				} },
