					{ kind = "accept", quest = 710, note = "Lotwil Veriatus" },
				} },
				{ title = "Kargath", tip = "Kargath is the Horde fortress built into the cliffs at the zone's western edge. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", zone = 1418, goals = {
					{ kind = "getfp", place = "Kargath" },
					{ kind = "sethome", place = "Kargath" },
					{ kind = "accept", quest = 1419, note = "Neeka Bloodscar" },
					{ kind = "accept", quest = 1420, note = "for Helgrum in Stonard, around level 42" },
					{ kind = "accept", quest = 2258, note = "Jarkal Mossmeld, inside" },
					{ kind = "vendor", nearest = true },
				} },
				{ title = "Lesser Rock Elementals", tip = "The small elementals drift across the flats between Kargath and Lotwil's camp, on the road back east. Every rock elemental in the zone can drop Jarkal's Rock Elemental Shards.", zone = 1418, goals = {
					{ kind = "collect", quest = 710, item = 4626 },
					{ kind = "collect", quest = 2258, objective = 3, item = 7848 },
				} },
				{ title = "Lotwil Veriatus", zone = 1418, goals = {
					{ kind = "turnin", quest = 710 },
					{ kind = "accept", quest = 711 },
				} },
				{ title = "Badlands: kill these as you meet them", tip = "The Elder Crag Coyotes and Giant Buzzards roam the basin south of the Dustbowl. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards.", zone = 1418, goals = {
					{ kind = "collect", quest = 1419, item = 6166 },
					{ kind = "collect", quest = 2258, objective = 2, item = 7846 },
					{ kind = "collect", quest = 2258, objective = 1, item = 7847 },
				} },
				{ title = "Rock Elementals", tip = "South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of Agmond's End; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards.", zone = 1418, goals = {
					{ kind = "collect", quest = 711, item = 4627, map = 1418, x = 40.4, y = 77.1 },
					{ kind = "collect", quest = 2258, objective = 3, item = 7848 },
				} },
				{ title = "Agmond's End", tip = "Theldurin sits among the dwarven ruins at Agmond's End, just east of the elementals.", zone = 1418, goals = {
