				{ title = "Rogue Vale screechers", tip = "Rogue Vale opens just north of Zorbin's dock. Kill a Rogue Vale Screecher, use Yeh'kinya's Bramble on its body and kill the spirit that rises.", zone = 1444, goals = {
					{ kind = "use", quest = 3520, objective = 1, item = 10699, name = "Yeh'kinya's Bramble", map = 1444, x = 45, y = 38 },
					{ kind = "kill", quest = 3520, objective = 1, npc = 8612 },
				} },
				{ title = "The Forgotten Coast: kill these as you meet them", tip = "Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with Zorbin's Ultra-Shrinker first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north.", zone = 1444, goals = {
