					{ kind = "use", quest = 7003, objective = 1, item = 18904, map = 1444, x = 40.1, y = 38.6 },
				} },
				{ title = "Northspring harpies", tip = "The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time.", zone = 1444, goals = {
