			id = "forever/horde/40-50/05-the-hinterlands", title = "The Hinterlands & Blasted Lands", category = "Leveling", faction = "Horde", levels = { 48, 50 }, zone = 1425, next = "forever/horde/40-50/06-azshara", version = 1, revision = "6d40b38861707996c0ae6d473fbc49f28af265b82402d6ada77e3adf44b78ddc", legacyRevision = "4942d51403cabb0ac565a1fb9829586f1432c9f89261d2b299f857df07b5bbc0",
			steps = {
				{ title = "Fly to Tarren Mill", zone = 1427, goals = {
