				{ title = "Revantusk Village", when = { { quest = 7816, test = "group" } }, zone = 1425, goals = {
					{ kind = "accept", quest = 7816 },
				} },
				{ title = "Revantusk Village", tip = "Separation Anxiety, Kidnapped Elder Torntusk! and Dark Vessels are group quests: they send you into Jintha'Alor, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\nPrimal Torntusk stands up on top of the inn, above Lard: go up, the arrow cannot tell the levels apart.", when = { { quest = 7849, test = "group" } }, zone = 1425, goals = {
					{ kind = "accept", quest = 7849, note = "Huntsman Markhor" },
					{ kind = "accept", quest = 7845, note = "Primal Torntusk" },
					{ kind = "accept", quest = 7850 },
				} },
				{ title = "The Overlook Cliffs: kill these as you meet them", tip = "The big turtles crawl along the beaches north of the village, and Whiskey Slim's bottles of port lie on the same beaches, from the village up to the Overlook Cliffs: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.", zone = 1425, goals = {
					{ kind = "kill", quest = 7815, objective = 1, npc = 2505 },
					{ kind = "collect", quest = 580, objective = 1, item = 3900, count = 12, note = "Pupellyverbos Port, on the beaches" },
					{ kind = "collect", item = 8704, optional = true, note = "OOX-09/HL Distress Beacon, a rare drop" },
				} },
				{ title = "The Overlook Cliffs: kill these as you meet them", tip = "These are elite mobs: grouping up is encouraged, look for people to do it with. Gammerita is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nGammerita walks the shore below the Overlook Cliffs, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore.", when = { { quest = 7816, test = "group" } }, zone = 1425, goals = {
					{ kind = "collect", quest = 7816, objective = 1, item = 19023, map = 1425, x = 80.4, y = 58.2 },
				} },
				{ title = "Rin'ji's Secret", tip = "The secret lies on the Overlook Cliffs, above the beach.", zone = 1425, goals = {
					{ kind = "turnin", quest = 2742, object = 142127 },
					{ kind = "accept", quest = 2782, object = 142127, note = "for Oran Snakewrithe in the Undercity, around level 50" },
				} },
				{ title = "Lard's lunch", tip = "North along the coast, Lard's picnic basket is on the small island; a Vilebranch Kidnapper guards it.", zone = 1425, goals = {
					{ kind = "collect", quest = 7840, objective = 1, item = 19034, map = 1425, x = 84.5, y = 41.2 },
				} },
				{ title = "Cortello's Riddle", when = { { test = "onquest", quests = { 626 } } }, zone = 1425, goals = {
					{ kind = "turnin", quest = 626, note = "Underwater" },
				} },
				{ title = "Shaol'watha: kill these as you meet them", tip = "West of the island, the Vilebranch scalpers hold the temples of Agol'watha and Shaol'watha. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and Skulk Rock. Use the Wildkin Muisek Vessel on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for Otho's second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use Infected Bite. When a Silvermane Howler falls to 50% health or lower, it calls for help from anything within 25 yd.", zone = 1425, goals = {
					{ kind = "kill", quest = 7828, objective = 1, npc = 2926 },
					{ kind = "collect", quest = 7839, objective = 1, item = 19033 },
					{ kind = "kill", quest = 7844, objective = 1, npc = 4466 },
					{ kind = "kill", quest = 7844, objective = 2, npc = 4467 },
					{ kind = "collect", quest = 7830, objective = 1, item = 19025 },
					{ kind = "kill", quest = 7829, objective = 1, npc = 2929 },
				} },
				{ title = "Skulk Rock", tip = "The crates of Hinterlands Honey Ripple lie around the abandoned Horde camp at Skulk Rock, among the oozes.", zone = 1425, goals = {
					{ kind = "collect", quest = 77, objective = 1, item = 8684 },
				} },
				{ title = "Wildkin Muisek", tip = "Careful: Stealthed wolves and griffons roam the Valorwind Lake area.", zone = 1425, goals = {
					{ kind = "collect", quest = 3123, objective = 1, item = 9594 },
					{ kind = "use", quest = 3123, objective = 1, item = 9618, map = 1425, x = 61, y = 42.8 },
					{ kind = "collect", item = 4589, count = 10, text = "Long Elegant Feather" },
				} },
				{ title = "The Altar of Zul: kill these as you meet them", tip = "South-west of the lake, the Vilebranch soothsayers hold the Altar of Zul, the troll temple south of the central hills. Qiaga and Morta'gya the Keeper (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages.", zone = 1425, goals = {
					{ kind = "kill", quest = 7844, objective = 1, npc = 4466 },
					{ kind = "kill", quest = 7844, objective = 2, npc = 4467 },
					{ kind = "kill", quest = 7828, objective = 2, npc = 2925 },
				} },
				{ title = "OOX-09/HL", tip = "Only with the distress beacon: the robot sits at the head of the river west of Skulk Rock. Escort it east to the shore beyond the Overlook Cliffs; its reward waits with Oglethorpe in Booty Bay.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand.", zone = 1425, goals = {
					{ kind = "accept", quest = 485, optional = true },
					{ kind = "turnin", quest = 485, optional = true, note = "Homing Robot OOX-09/HL" },
					{ kind = "accept", quest = 836, optional = true },
					{ kind = "complete", quest = 836, optional = true },
				} },
