				{ title = "Gorillas", tip = "The gorillas live on the north-east plateau. Stay out of the deepest cave: U'cha lives there.", zone = 1449, goals = {
					{ kind = "turnin", quest = 4243, note = "A-Me 01, the robot on the plateau; below ground" },
					{ kind = "note", text = "A-Me 01 then wants a Mithril Casing, an Engineering item. Skip it unless you have one." },
				} },
				{ title = "Un'Goro Crater: kill these as you meet them", tip = "Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast Silithid Pox and Tunnelers and the Hive Guard use Tunneler Acid.", zone = 1449, goals = {
					{ kind = "collect", quest = 3761, item = 11018 },
					{ kind = "collect", quest = 4496, objective = 2, item = 11018 },
