				{ title = "Into the Searing Gorge", tip = "Take the pass out of Kargath's west side into the Searing Gorge, then ride south across the gorge to the long bridge into Blackrock Mountain. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals.", zone = 1427, goals = {
					{ kind = "goto", label = "Bridge into Blackrock Mountain", map = 1427, x = 34.8, y = 83 },
				} },
				{ title = "Flame Crest", tip = "The mountain lets you out beside Blackrock Stronghold, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at Flame Crest.", zone = 1428, goals = {
					{ kind = "getfp", place = "Flame Crest" },
