				{ title = "Kirsta Deepshadow", tip = "Ride back west over the river and on to the Northridge Lumber Camp; Kirsta hides on the hill north-east of it.", zone = 1422, goals = {
					{ kind = "accept", quest = 6004 },
				} },
				{ title = "Level 52.63", tip = "Top up here to level 52.63 before the hand-ins at Dalson's Tears: they take you to level 53. The Scarlet Mages and Knights here count for Kirsta's Unfinished Business. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", when = { { level = 52.63, test = "level", op = "<" } }, zone = 1422, goals = {
