		{
			id = "forever/legacy/legacy-challenges", title = "Legacy Challenges", category = "Legacy", levels = { 1, 60 }, zone = 1428, version = 1, revision = "e292cf1030089d073803becd69495e905a26a1ab25a88fb1f8ee1171fb121abf", legacyRevision = "0a73ecd65dff4a2c23dba7288d8598379a2a3a3245dd1f1dc0aec7ceb23f212a",
			steps = {
				{ title = "Classes: level 25", tip = "Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself.", zone = 1428, goals = {
					{ kind = "level", level = 25 },
				} },
				{ title = "Classes: level 45", tip = "Level 45 with this character's class.", zone = 1428, goals = {
