				{ title = "PvP: Field of Honor", tip = "The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself.", zone = 1428, goals = {
					{ kind = "kill", name = "enemy players and finish the Field of Honor week 4 journey quest" },
					{ kind = "kill", name = "enemy players and finish the Field of Honor week 7 journey quest" },
					{ kind = "kill", name = "enemy players and finish the Field of Honor week 10 journey quest" },
				} },
				{ title = "Adventure: explore the world map", tip = "Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the Riverglades, Shen'dralas and Mount Hyjal, a level 60 zone.", zone = 1428, goals = {
					{ kind = "note", text = "Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet." },
					{ kind = "note", text = "This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded." },
				} },
				{ title = "Adventure: Lord Valthalak", tip = "The Lord Valthalak questline is a point. It is the level 60 dungeon-set chain, from An Earnest Proposition to your class's Saving the Best for Last: Deliana (Ironforge) or Mokvar (Orgrimmar) send you through In Search of Anthion and Anthion's Parting Words to Bodley at Blackrock Mountain, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and Mea Culpa, Lord Valthalak end with Return to Bodley. Back to the Beginning then leads to Saving the Best for Last.", zone = 1428, goals = {
					{ kind = "accept", quest = 8996, map = 1428, x = 32.2, y = 25.8, optional = true, note = "Spirit of Lord Valthalak, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to Bodley's Blackrock Mountain)" },
