					{ kind = "kill", npc = 261319, optional = true, note = "Hall of Thanes: Durgen Dirgehammer (or Ragefire Chasm)" },
					{ kind = "kill", npc = 256035, note = "Ruins of Lordaeron (Forever's, Tirisfal Glades): Viktor the Vile" },
