			id = "forever/miscellaneous/cozy-sleeping-bag", title = "Cozy Sleeping Bag", category = "Miscellaneous", levels = { 14, 32 }, zone = 1436, version = 1, revision = "d11bcace75ebf725fc2d3994b7069a942a988880c37486848a127d5e2385fe22", legacyRevision = "e075a0ceeae4a603bd3938184d9b363402d483237fbc56ecf0af9e8c163ee984", keywords = { "Cozy Sleeping Bag", "Old Toolbox", "Student Fodder", "... and that note you found", "Stepping Stones", "Scramble", "Wet Job", "Eagle's Fist", "This Must Be The Place", "Burned-Out Remains", "Nailed Plank", "Thoradin's Wall" }, collects = { 211527, 221498 }, rewards = { { item = 211527 }, { item = 221498 } }, why = "A trail of hidden notes across both continents: the Cozy Sleeping Bag at the end, a 12-slot Old Toolbox on the way.",
			steps = {
				{ title = "The note in Westfall", tip = "The chain opens at level 14. A burned-out campfire in western Westfall, with a nailed plank beside it.", only = { factions = { "Alliance" } }, zone = 1436, goals = {
					{ kind = "level", level = 14 },
					{ kind = "accept", quest = 79008 },
				} },
				{ title = "Its twin in the Barrens", tip = "The note's \"twin land\" is the Barrens: the same burned-out campfire stands in the southern Barrens.", only = { factions = { "Alliance" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 79008 },
					{ kind = "accept", quest = 79192, object = 417072 },
				} },
				{ title = "The note in the Barrens", tip = "The chain opens at level 14. A burned-out campfire in the southern Barrens, with a nailed plank beside it.", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "level", level = 14 },
					{ kind = "accept", quest = 79007 },
				} },
				{ title = "Its twin in Westfall", tip = "The note's \"twin land\" is Westfall: the same burned-out campfire stands in western Westfall.", only = { factions = { "Horde" } }, zone = 1436, goals = {
					{ kind = "turnin", quest = 79007 },
					{ kind = "accept", quest = 79192, object = 424010 },
				} },
				{ title = "Stonetalon from the north", tip = "The Barrens' way into Stonetalon runs through Honor's Stand, and the road on to the hills passes Malaka'jin and Sun Rock Retreat: all Horde posts. Come in from the north instead. With the Stonetalon Peak flight path, fly there and follow the road south. Otherwise fly to Astranaar and walk south-west to the Talondeep Path, the tunnel from Ashenvale into Stonetalon.", only = { factions = { "Alliance" } }, when = { { name = "Stonetalon Mountains", test = "zone", negate = true } }, zone = 1440, goals = {
					{ kind = "goto", label = "The Talondeep Path", map = 1440, x = 42.4, y = 71, radius = 25 },
				} },
				{ title = "Stonetalon Mountains", tip = "The next hideout is a small camp in the hills north-west of Sun Rock Retreat, in the middle of the Stonetalon Mountains. Leave the road where a path climbs west into the hills and follow it to the camp; the Pocket Litter lies on a crate beside its tent.", zone = 1442, goals = {
					{ kind = "goto", label = "Path into the hills", map = 1442, x = 50.9, y = 52.3 },
					{ kind = "turnin", quest = 79192 },
					{ kind = "accept", quest = 79980 },
				} },
				{ title = "A hundred paces north", tip = "Walk north through the camp and drop carefully down the steep slope to the Mound of Dirt on the ledge below. A missed jump only slides you down: hug the cliff and walk back up.", zone = 1442, goals = {
					{ kind = "turnin", quest = 79980 },
					{ kind = "accept", quest = 79974 },
				} },
				{ title = "The dam in Loch Modan", tip = "The figurine is on a ledge just below the top of the Stonewrought Dam, on its north face. Step off slowly; walking backwards keeps you from overshooting the ledge.", zone = 1432, goals = {
					{ kind = "turnin", quest = 79974 },
					{ kind = "accept", quest = 79975 },
				} },
				{ title = "Out of the river", tip = "Careful: off the dam's ledge you land in the river below it, in the Wetlands. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over Thandol Span into Arathi.", zone = 1437, goals = {
					{ kind = "goto", label = "West bank, before the waterfall", map = 1437, x = 64.4, y = 79.4, radius = 12 },
					{ kind = "goto", label = "West bank", map = 1437, x = 62.2, y = 76.8, radius = 15 },
				} },
				{ title = "Thoradin's Wall", tip = "At the gate in Thoradin's Wall between Arathi and Hillsbrad, turn north and follow the wall on the Hillsbrad side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through.", zone = 1424, goals = {
					{ kind = "goto", label = "Fallen cart", map = 1424, x = 87.5, y = 47.7 },
				} },
				{ title = "The hidden camp", zone = 1417, goals = {
					{ kind = "turnin", quest = 79975 },
					{ kind = "accept", quest = 79976 },
					{ kind = "turnin", quest = 79976 },
				} },
			},
		},
