			id = "forever/miscellaneous/library-books", title = "Library Books", category = "Miscellaneous", levels = { 15, 60 }, zone = 1453, version = 1, revision = "62c53e9e6d4dc978c06ada14e8901a5ebe6ce6f7978b1b3dd9f1daaa78892a86", legacyRevision = "0c5f9abc8f4dfbb4ec3e927ea517e297b1f5aaa22fdf99d4088a38a5e89a3b25", keywords = { "Library", "books", "Friend of the Library", "Greater Friend of the Library", "Garion Wendell", "Owen Thadd", "Comprehension Charm", "Scholarly Pendant", "Erudite's Amulet", "Field Researcher's Loop", "Philanthropist's Ring", "Truthseeker's Bow", "Crest of Elucidation", "Researcher's Night Light" }, rewards = { { item = 277203, choice = true }, { item = 277204, choice = true }, { item = 281634, choice = true }, { item = 281635, choice = true }, { item = 277254, choice = true }, { item = 277258, choice = true }, { item = 277260, choice = true } }, why = "Lost books and scrolls all over the world: each pays experience at the library, and 10, 20 and 25 of them earn a necklace, a ring and an off-hand.",
