		{
			id = "forever/miscellaneous/stalk-with-the-earthmother", title = "Stalk With The Earthmother", category = "Miscellaneous", faction = "Horde", races = { "Tauren" }, levels = { 8, 12 }, zone = 1456, version = 1, revision = "d9e28b20ee674b67ef3ad8b19ba09a7544e357926e07259c6787fa575090f0ab", keywords = { "Stalk With The Earthmother", "Boarton Shadetotem", "Hoof-Holstered Blade", "Valley Cosh", "Venture Co Disguise", "Seaforium Mining Charge", "Blasting Supplies", "Windfury Cone", "Mortar and Pestle", "Raw Brilliant Smallfish", "Knife Set", "Fish Chunks", "Venture Co. Mine", "Windfury Ridge", "Thunder Bluff", "weapon" }, rewards = { { item = 277988, choice = true }, { item = 278002, choice = true } }, why = "A one-hand blade or mace at 11 from Boarton Shadetotem's three tests in and around Thunder Bluff, for a Tauren of any class.",
			steps = {
				{ title = "Boarton Shadetotem", tip = "Boarton Shadetotem hides in stealth on the main mesa of Thunder Bluff, south of its pool: walk to where the arrow points until his outline shows. He hands you the Venture Co Disguise. The quest opens at level 4, but the mine holds Venture Co. Workers (level 8-9), Supervisors (9-10) and Supervisor Fizsprocket (12): go at 9 or 10.", zone = 1456, goals = {
					{ kind = "accept", quest = 76156, note = "Boarton Shadetotem" },
				} },
				{ title = "The Venture Co. Mine", tip = "Ride down the lift and south-east across Mulgore to the Venture Co. Mine. Put on the disguise, then open the carts of Blasting Supplies inside the mine and on the slope outside it; stay on the upper levels where you can, the lower tunnels are packed. Five charges.", zone = 1412, goals = {
					{ kind = "collect", quest = 76156, objective = 1, item = 206157, count = 5, note = "Seaforium Mining Charge, from the Blasting Supplies" },
				} },
				{ title = "Boarton Shadetotem", tip = "Back to Boarton in Thunder Bluff. He gives you the Mortar and Pestle for his next test.", zone = 1456, goals = {
					{ kind = "turnin", quest = 76156, note = "Boarton Shadetotem" },
					{ kind = "accept", quest = 76160 },
				} },
				{ title = "Windfury Cones", tip = "Windfury Cones lie on the ground under the harpies' nest trees on Windfury Ridge, north-west of Thunder Bluff; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the Mortar and Pestle to grind them.", zone = 1412, goals = {
					{ kind = "collect", item = 206170, name = "Windfury Cone", count = 8, map = 1412, x = 31.9, y = 32, frame = "live", optional = true, note = "the mortar takes all eight" },
					{ kind = "use", quest = 76160, objective = 1, item = 206176, name = "Mortar and Pestle", map = 1412, x = 31.9, y = 32, frame = "live", note = "grind the eight cones into the Pine Salve" },
				} },
				{ title = "Boarton Shadetotem", tip = "Back to Boarton. He hands you the Knife Set for the last test.", zone = 1456, goals = {
					{ kind = "turnin", quest = 76160, note = "Boarton Shadetotem" },
					{ kind = "accept", quest = 76240 },
				} },
				{ title = "Raw Brilliant Smallfish", tip = "Buy a Raw Brilliant Smallfish at the Auction House (Auctioneer Stampi, north of the pool), or fish one yourself: Kah Mistrunner trains Fishing and Sewa Mistrunner beside him sells the Fishing Pole and a Shiny Bauble; the pool on the main mesa gives smallfish at any skill. Then use the Knife Set on it, wherever you are.", zone = 1456, goals = {
					{ kind = "collect", item = 6291, count = 1, map = 1456, x = 40.4, y = 51.8, optional = true, note = "Raw Brilliant Smallfish: the Auction House, or the pool; the knife takes it" },
