					{ kind = "collect", item = 2838, count = 28, map = 1413, x = 45.2, y = 94.5 },
				} },
				{ title = "Heavy Stone (Arathi Highlands)", tip = "28 Heavy Stone for Heavy Sharpening Stone: Mining: Iron Deposit (skill 125); or the Auction House. The densest cluster of Iron Deposit in Arathi Highlands is marked.", only = { races = { "Scourge" } }, section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 1417, goals = {
					{ kind = "collect", item = 2838, count = 28, map = 1417, x = 15.8, y = 63.2 },
				} },
				{ title = "Rough Grinding Stone to 83", tip = "Rough Grinding Stone is green at 75 (yellow 45, green 65, grey 85): about 58 crafts to 83. Each takes 2 Rough Stone. Two Rough Stone a craft. Grinding stones are parts for later plans; the extras sell to vendors.", section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 3320, untilSkill = 83 },
				} },
				{ title = "Runed Copper Belt to 100", tip = "Runed Copper Belt is orange at 83 (yellow 85, green 105, grey 125): about 21 crafts to 100. Each takes 10 Copper Bar. Forever teaches Runed Copper Belt from 45; it stays orange to 85. Ten Copper Bars a craft: smelt your Copper Ore. Needs an anvil nearby. Blacksmith Hammer is a tool: keep it in your bags. Copper Bar (210 for 75-150): Mining: smelt Copper Ore; or the Auction House.", section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 2666, untilSkill = 100 },
				} },
				{ title = "Blacksmithing recipes at 100", tip = "Back to a Blacksmithing trainer: Heavy Sharpening Stone (from 100, 10s).", section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 2674 },
				} },
				{ title = "Heavy Sharpening Stone to 113", tip = "Heavy Sharpening Stone is yellow at 100 (yellow 100, green 107, grey 115): about 28 crafts to 113. Each takes 1 Heavy Stone. Heavy Stone comes from Iron Deposits; one a craft.", section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 2674, untilSkill = 113 },
				} },
				{ title = "Blacksmithing recipes at 113", tip = "Back to a Blacksmithing trainer: Patterned Bronze Bracers (from 95, 5s).", section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 2672 },
				} },
				{ title = "Patterned Bronze Bracers to 150", tip = "Patterned Bronze Bracers is orange at 113 (yellow 125, green 140, grey 155): about 64 crafts to 150. Each takes 5 Bronze Bar and 2 Coarse Grinding Stone. Make the 128 Coarse Grinding Stone first. Each bracer takes two Coarse Grinding Stones (Coarse Stone from Tin Veins): make them first; they give points too. Needs an anvil nearby. Bronze Bar (320 for 75-150): Mining: smelt Copper Bar and Tin Bar; or the Auction House. Blacksmithing 150 is a Legacy System milestone.", section = { title = "Blacksmithing 75-150", min = 75, max = 150, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 3326, count = 128 },
					{ kind = "craft", spell = 2672, untilSkill = 150 },
					{ kind = "skill", profession = "Blacksmithing", value = 150 },
				} },
				{ title = "Expert Blacksmithing", tip = "Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs Blacksmithing 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Bengus Deepforge (Ironforge); Horde Saru Steelfury (Orgrimmar). The arrow picks the nearest of your faction. Learn now: Green Iron Bracers (from 140) and Heavy Grinding Stone (from 100, 10s). 150-225 takes about 10s of recipes and 28s of vendor goods, plus 234 Heavy Stone, 168 Iron Bar, 195 Steel Bar, 320 Mithril Bar and 30 Solid Stone to gather or buy.", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "level", level = 20 },
					{ kind = "train", profession = "Blacksmithing", rank = "Expert" },
					{ kind = "learn", spell = 3501 },
					{ kind = "learn", spell = 3337 },
				} },
				{ title = "Blacksmithing 150-225: vendor goods", tip = "Buy the whole bracket's share in one go: 28 Green Dye (28s); about 28s in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra). If you smelt the 195 Steel Bar yourself (Mining 165: an Iron Bar and a Coal each), buy 195 Coal too (9g 75s, trade and blacksmithing suppliers); skip them if you buy the bars.", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "buy", item = 2605, count = 28, nearest = true },
					{ kind = "buy", item = 3857, count = 195, nearest = true, optional = true },
				} },
				{ title = "Heavy Stone (Alliance)", tip = "234 Heavy Stone for Golden Scale Bracers: Mining: Iron Deposit (skill 125) in Arathi Highlands (30-40), Stranglethorn Vale (30-45) and Desolace (30-40); or the Auction House. The densest cluster of Iron Deposit in Arathi Highlands is marked.", only = { factions = { "Alliance" } }, section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 1417, goals = {
					{ kind = "collect", item = 2838, count = 234, map = 1417, x = 15.8, y = 63.2 },
				} },
				{ title = "Heavy Stone (Horde)", tip = "234 Heavy Stone for Golden Scale Bracers: Mining: Iron Deposit (skill 125) in Thousand Needles (25-35), Arathi Highlands (30-40) and Stranglethorn Vale (30-45); or the Auction House. The densest cluster of Iron Deposit in Thousand Needles is marked.", only = { factions = { "Horde" } }, section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 1441, goals = {
					{ kind = "collect", item = 2838, count = 234, map = 1441, x = 8.9, y = 34.3 },
				} },
				{ title = "Solid Stone (Alliance)", tip = "30 Solid Stone for Solid Sharpening Stone: Mining: Mithril Deposit (skill 175) in Stranglethorn Vale (30-45), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Stranglethorn Vale is marked.", only = { factions = { "Alliance" } }, section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 1434, goals = {
					{ kind = "collect", item = 7912, count = 30, map = 1434, x = 29.4, y = 60.1 },
				} },
				{ title = "Solid Stone (Horde)", tip = "30 Solid Stone for Solid Sharpening Stone: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = { "Horde" } }, section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 1443, goals = {
					{ kind = "collect", item = 7912, count = 30, map = 1443, x = 31.5, y = 59.4 },
				} },
				{ title = "Green Iron Bracers to 175", tip = "Green Iron Bracers is orange at 150 (yellow 165, green 177, grey 190): about 28 crafts to 175. Each takes 6 Iron Bar and 1 Green Dye. Six Iron Bars and a Green Dye a craft; Green Dye comes from tailoring, leatherworking and trade supplies vendors. Orange to 165 on Forever, so a point every craft for the first fifteen. Needs an anvil nearby. Iron Bar (168 for 150-225): Mining: smelt Iron Ore; or the Auction House.", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 3501, untilSkill = 175 },
				} },
				{ title = "Blacksmithing recipes at 175", tip = "Back to a Blacksmithing trainer: Solid Sharpening Stone (from 175).", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 9918 },
				} },
				{ title = "Solid Sharpening Stone to 185", tip = "Solid Sharpening Stone is yellow at 175 (yellow 175, green 180, grey 185): about 30 crafts to 185. Each takes 1 Solid Stone. One Solid Stone a craft (Mithril Deposits): cheap points between the iron and the steel bracers. Use the stones on your weapons or sell them.", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 9918, untilSkill = 185 },
				} },
				{ title = "Blacksmithing recipes at 185", tip = "Back to a Blacksmithing trainer: Golden Scale Bracers (from 160).", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 7223 },
				} },
				{ title = "Golden Scale Bracers to 205", tip = "Golden Scale Bracers is yellow at 185 (yellow 185, green 197, grey 210): about 39 crafts to 205. Each takes 5 Steel Bar and 2 Heavy Grinding Stone. Make the 78 Heavy Grinding Stone first. Steel Bars are smelted from an Iron Bar and a Coal (Mining 165; Coal from trade and blacksmithing suppliers), so each bracer is five of each. Each bracer takes two Heavy Grinding Stones: make them first. Specialisation (optional): at 200 and character level 40, Grumnus Steelshaper (Ironforge) or Okothos Ironrager (Orgrimmar) starts The Art of the Armorsmith: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots and an Ornate Mithril Breastplate, whose plans come from a Mithril Order quest chain. Ironus Coldsteel (Ironforge) or Borgosh Corebender (Orgrimmar) starts The Way of the Weaponsmith: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes and 2 Big Black Maces; on Forever the Moonsteel Broadsword plans (Zarena Cromwind, Booty Bay) and Massive Iron Axe plans bind when picked up, so buy and use them yourself. You can take only one; neither is needed for 300, and the beta never tested them (it stopped at level 30). Needs an anvil nearby. Steel Bar (195 for 150-225): Mining: smelt Iron Bar and Coal; or the Auction House.", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 3337, count = 78 },
					{ kind = "craft", spell = 7223, untilSkill = 205 },
				} },
				{ title = "Blacksmithing recipes at 205", tip = "Back to a Blacksmithing trainer: Heavy Mithril Breastplate (from 205).", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 9959 },
				} },
				{ title = "Heavy Mithril Breastplate to 225", tip = "Heavy Mithril Breastplate is orange at 205 (yellow 225, green 235, grey 245): about 20 crafts to 225, a point every craft. Each takes 16 Mithril Bar. Sixteen Mithril Bars a craft and nothing else; orange to 225 on Forever, so a point every craft to the Artisan cap. Needs an anvil nearby. Mithril Bar (320 for 150-225): Mining: smelt Mithril Ore; or the Auction House. Blacksmithing 225 is a Legacy System milestone.", section = { title = "Blacksmithing 150-225", min = 150, max = 225, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 9959, untilSkill = 225 },
					{ kind = "skill", profession = "Blacksmithing", value = 225 },
				} },
				{ title = "Artisan Blacksmithing", tip = "Artisan raises the cap from 225 to 300 for 5g (Classic's price; Forever's is not in the data); it needs Blacksmithing 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance Brikk Keencraft (Stranglethorn Vale); Horde Brikk Keencraft (Stranglethorn Vale). The arrow picks the nearest of your faction. Learn now: Dense Weightstone (from 225), Heavy Mithril Boots (from 210), Solid Grinding Stone (from 175), Big Black Mace (from 205) and Dense Grinding Stone (from 225). 225-300 takes about 3g 60s of recipes, plus 44 Shadowgem, 596 Mithril Bar, 142 Thick Leather, 19 Aquamarine, 19 Star Ruby, 44 Solid Stone, 11 Black Pearl, 206 Rugged Leather, 2026 Thorium Bar, 801 Dense Stone and 10 Large Opal to gather or buy.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "level", level = 35 },
					{ kind = "train", profession = "Blacksmithing", rank = "Artisan" },
					{ kind = "learn", spell = 16640 },
					{ kind = "learn", spell = 9968 },
					{ kind = "learn", spell = 9920 },
					{ kind = "learn", spell = 10001 },
					{ kind = "learn", spell = 16639 },
				} },
				{ title = "Plans: Ornate Thorium Handaxe", tip = "Plans: Ornate Thorium Handaxe teaches Ornate Thorium Handaxe (Blacksmithing 250) for 1g 60s. Sold by Magnus Frostwake (Western Plaguelands).", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "buy", item = 12819, nearest = true },
				} },
				{ title = "Plans: Huge Thorium Battleaxe", tip = "Plans: Huge Thorium Battleaxe teaches Huge Thorium Battleaxe (Blacksmithing 255) for 2g. Sold by Magnus Frostwake (Western Plaguelands).", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "buy", item = 12823, nearest = true },
				} },
				{ title = "Thick Leather (Alliance)", tip = "142 Thick Leather for Heavy Mithril Boots and Big Black Mace: Skinning: beasts of level 38-50; or the Auction House. Skin Elder Crag Coyote, Rabid Crag Coyote, Ridge Huntress and Ridge Stalker Patriarch here (level 38-50); the Skinning guide routes this.", only = { factions = { "Alliance" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1418, goals = {
					{ kind = "collect", item = 4304, count = 142, map = 1418, x = 35, y = 64.3 },
				} },
				{ title = "Thick Leather (Horde)", tip = "142 Thick Leather for Heavy Mithril Boots and Big Black Mace: Skinning: beasts of level 38-50; or the Auction House. Skin Feral Scar Yeti, Frayfeather Hippogryph, Frayfeather Stagwing, Grizzled Ironfur Bear, Groddoc Ape, Groddoc Thunderer, Ironfur Bear, Ironfur Patriarch, Longtooth Howler, Longtooth Runner and Rage Scar Yeti here (level 38-50); the Skinning guide routes this.", only = { factions = { "Horde" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1444, goals = {
					{ kind = "collect", item = 4304, count = 142, map = 1444, x = 54.9, y = 60.8 },
				} },
				{ title = "Solid Stone (Alliance)", tip = "44 Solid Stone for Big Black Mace: Mining: Mithril Deposit (skill 175) in The Hinterlands (40-50), Feralas (40-50) and Azshara (45-55); or the Auction House. The densest cluster of Mithril Deposit in The Hinterlands is marked.", only = { factions = { "Alliance" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1425, goals = {
					{ kind = "collect", item = 7912, count = 44, map = 1425, x = 20.8, y = 58.8 },
				} },
				{ title = "Solid Stone (Horde)", tip = "44 Solid Stone for Big Black Mace: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = { "Horde" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1443, goals = {
					{ kind = "collect", item = 7912, count = 44, map = 1443, x = 31.5, y = 59.4 },
				} },
				{ title = "Rugged Leather (Alliance)", tip = "206 Rugged Leather for Ornate Thorium Handaxe and Huge Thorium Battleaxe: Skinning: beasts of level 48-60; or the Auction House. Skin Frenzied Plaguehound, Plaguehound and Plaguehound Runt here (level 48-60); the Skinning guide routes this.", only = { factions = { "Alliance" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1423, goals = {
					{ kind = "collect", item = 8170, count = 206, map = 1423, x = 56, y = 46.8, frame = "live" },
				} },
				{ title = "Rugged Leather (Horde)", tip = "206 Rugged Leather for Ornate Thorium Handaxe and Huge Thorium Battleaxe: Skinning: beasts of level 48-60; or the Auction House. Skin Coralshell Tortoise, Mosshoof Stag, Thunderhead Consort, Thunderhead Patriarch, Thunderhead Skystormer and Thunderhead Stagwing here (level 48-60); the Skinning guide routes this.", only = { factions = { "Horde" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1447, goals = {
					{ kind = "collect", item = 8170, count = 206, map = 1447, x = 58.8, y = 21.5 },
				} },
				{ title = "Dense Stone (Alliance)", tip = "801 Dense Stone for Dense Weightstone, Ornate Thorium Handaxe and Huge Thorium Battleaxe: Mining: Small Thorium Vein (skill 245) in Blasted Lands (45-55), Felwood (48-55) and Winterspring (55-60); or the Auction House. The densest cluster of Small Thorium Vein in Blasted Lands is marked.", only = { factions = { "Alliance" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1419, goals = {
					{ kind = "collect", item = 12365, count = 801, map = 1419, x = 43.5, y = 30.8 },
				} },
				{ title = "Dense Stone (Horde)", tip = "801 Dense Stone for Dense Weightstone, Ornate Thorium Handaxe and Huge Thorium Battleaxe: Mining: Small Thorium Vein (skill 245) in Felwood (48-55), Silithus (55-60) and Winterspring (55-60); or the Auction House. The densest cluster of Small Thorium Vein in Felwood is marked.", only = { factions = { "Horde" } }, section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1448, goals = {
					{ kind = "collect", item = 12365, count = 801, map = 1448, x = 34.7, y = 61.8 },
				} },
				{ title = "Dense Weightstone to 235", tip = "Dense Weightstone is orange at 225 (yellow 230, green 232, grey 235): about 17 crafts to 235. Each takes 1 Dense Stone. One Dense Stone a craft (Thorium veins): cheap points at the start of Artisan.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 16640, untilSkill = 235 },
				} },
				{ title = "Heavy Mithril Boots to 247", tip = "Heavy Mithril Boots is yellow at 235 (yellow 230, green 240, grey 250): about 30 crafts to 247. Each takes 14 Mithril Bar and 4 Thick Leather. Mithril Bars from Mithril Deposits; Thick Leather from skinners or the Auction House. Needs an anvil nearby. Mithril Bar (596 for 225-300): Mining: smelt Mithril Ore; or the Auction House.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 9968, untilSkill = 247 },
				} },
				{ title = "Big Black Mace to 250", tip = "Big Black Mace is green at 247 (yellow 230, green 242, grey 255): about 11 crafts to 250. Each takes 16 Mithril Bar, 1 Black Pearl, 4 Shadowgem, 1 Solid Grinding Stone and 2 Thick Leather. Make the 11 Solid Grinding Stone first. Only about 11 crafts to bridge 247-250, but each wants four Shadowgems (about one Tin Vein in a hundred) and a Black Pearl: buy those at the Auction House unless your bags already hold them. Needs an anvil nearby. Shadowgem (44 for 225-300): Shadowgem turns up in about one Copper Vein, Tin Vein or Silver Vein in 100: buy it at the Auction House, or keep the ones you find while mining. Black Pearl (11 for 225-300): Black Pearl is a rare drop (no mob gives it one time in 50): buy it at the Auction House, or keep the ones you find.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "craft", spell = 9920, count = 11 },
					{ kind = "craft", spell = 10001, untilSkill = 250 },
				} },
				{ title = "Ornate Thorium Handaxe to 255", tip = "Ornate Thorium Handaxe is orange at 250 (yellow 275, green 287, grey 300): about 5 crafts to 255, a point every craft. Each takes 20 Thorium Bar, 2 Large Opal, 2 Dense Grinding Stone and 4 Rugged Leather. Make the 10 Dense Grinding Stone first. Large Opal turns up in about one Thorium vein in 130: buy the ten at the Auction House. Five crafts only, until the battleaxe plans can be used at 255. Needs an anvil nearby. Thorium Bar (2026 for 225-300): Mining: smelt Thorium Ore; or the Auction House. Large Opal (10 for 225-300): Large Opal turns up in about one Rich Thorium Vein, Ooze Covered Rich Thorium Vein or Hakkari Thorium Vein in 143: buy it at the Auction House, or keep the ones you find while mining.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 16969, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 16639, count = 10 },
					{ kind = "craft", spell = 16969, untilSkill = 255 },
				} },
				{ title = "Huge Thorium Battleaxe to 285", tip = "Huge Thorium Battleaxe is orange at 255 (yellow 280, green 292, grey 305): about 31 crafts to 285. Each takes 40 Thorium Bar, 6 Dense Grinding Stone and 6 Rugged Leather. Make the 186 Dense Grinding Stone first. Plans from Magnus Frostwake (Caer Darrow, Western Plaguelands), unlimited stock, but they bind when picked up. Forty Thorium Bars and six Dense Grinding Stones a craft: the dearest stretch, so stop where the Imperial Plate Boots take over. Other ways through: world-drop plans from the Auction House (the Radiant pieces: about 820 Thorium Bars and 190 Hearts of Fire for the Radiant route) or the Merchant's Favor sets. Needs an anvil nearby.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 16971, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 16639, count = 186 },
					{ kind = "craft", spell = 16971, untilSkill = 285 },
				} },
				{ title = "Plans: Imperial Plate Boots", tip = "Derotain Mudsipper (Tanaris) trades Plans: Imperial Plate Boots (Blacksmithing 270) for 40 Thorium Bar in Imperial Plate Boots, which needs Blacksmithing 265 and character level 50; take A Blue Light Bargain first (it asks for nothing). The plans bind when picked up.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 1446, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 7652 },
					{ kind = "turnin", quest = 7652 },
					{ kind = "accept", quest = 7654 },
					{ kind = "turnin", quest = 7654 },
				} },
				{ title = "Imperial Plate Boots to 300", tip = "Imperial Plate Boots is orange at 285 (yellow 290, green 300, grey 310): about 19 crafts to 300. Each takes 34 Thorium Bar, 1 Star Ruby and 1 Aquamarine. About 34 Thorium Bars a craft against the battleaxe's 40 and its grinding stones, orange to 290. Below character level 50 Derotain has no quest for you: keep making Huge Thorium Battleaxes to 300 instead (yellow to 292, grey at 305: about twice the Thorium Bars). Needs an anvil nearby. Aquamarine (19 for 225-300): Aquamarine turns up in about one Truesilver Deposit or Ooze Covered Truesilver Deposit in 500: buy it at the Auction House, or keep the ones you find while mining. Star Ruby (19 for 225-300): Star Ruby turns up in about one Truesilver Deposit or Ooze Covered Truesilver Deposit in 143: buy it at the Auction House, or keep the ones you find while mining. Blacksmithing 300 is a Legacy System milestone.", section = { title = "Blacksmithing 225-300", min = 225, max = 300, profession = "Blacksmithing" }, zone = 947, goals = {
					{ kind = "learn", spell = 16657, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 16657, untilSkill = 300 },
					{ kind = "skill", profession = "Blacksmithing", value = 300 },
				} },
			},
		},
		{
			id = "forever/professions/cooking", title = "Cooking 1-300", category = "Professions", levels = { 5, 60 }, zone = 1455, version = 1, revision = "3da5cbeb8845637c8888fe5f69217a05420067aec10939dfcae5235ec0b7dc6e", legacyRevision = "4ba44c4a9f6c585b62792b0019c5c954bdac3ce165edf768d6113a992dff2106",
			steps = {
				{ title = "Learn Cooking", tip = "Any Cooking trainer of your faction teaches Apprentice Cooking (any character level, 1s); the arrow picks the nearest. Forever: every cook knows Basic Campfire. Craft a Basic Campfire Kit from one Simple Wood (38c) with Flint and Tinder (1s 35c, kept in your bags), then place the kit to light a cooking fire anywhere; make a few in advance (one use every 5 minutes). The first kits also raise Cooking to about 5. The Camping 101: Cooking quest at your starting area's camp sends you to this trainer.", section = { title = "Cooking 1-50", min = 1, max = 50, profession = "Cooking" }, zone = 1455, goals = {
					{ kind = "train", profession = "Cooking", rank = "Apprentice" },
