				{ title = "Monster Omelet: shopping", tip = "The arrow picks the nearest vendor of your faction for each item. You need 240 Soothing Spices (3g 84s).", section = { title = "Cooking 225-300", min = 225, max = 300, profession = "Cooking" }, zone = 1446, goals = {
					{ kind = "buy", item = 16110, count = 1, nearest = true },
					{ kind = "buy", item = 3713, count = 240, nearest = true },
				} },
				{ title = "Monster Omelet: ingredients", section = { title = "Cooking 225-300", min = 225, max = 300, profession = "Cooking" }, zone = 1425, goals = {
					{ kind = "collect", item = 12207, count = 120, nearest = true, note = "Savage Owlbeast (54%) in The Hinterlands, or wherever the arrow points" },
				} },
				{ title = "Monster Omelet (225-300)", tip = "Monster Omelet is orange from 225 (yellow at 265, green at 285, grey at 305): about 120 crafts to 300. Cook at any fire: a town hearth or your own Basic Campfire. Recipe: Monster Omelet costs 1g 20s at its vendor; the arrow picks the nearest one of your faction. Monster Omelet is orange to 265 and green from 285, yet it still carries you to 300. Fishers can finish on Nightfin Soup (Gikkix, Steamwheedle Port; yellow to 310) instead; Poached Sunscale Salmon needs an Iron Oven on Forever.", section = { title = "Cooking 225-300", min = 225, max = 300, profession = "Cooking" }, zone = 1425, goals = {
					{ kind = "learn", spell = 15933 },
					{ kind = "craft", spell = 15933, untilSkill = 300 },
				} },
			},
		},
		{
			id = "forever/professions/enchanting", title = "Enchanting 1-300", category = "Professions", levels = { 5, 60 }, zone = 947, version = 1, revision = "3c8593082cba01781733d5dd1be11c524d659bba8a4ca0583bc43fbfbe6676ff", legacyRevision = "1375c70a014f188f971aeb741c633caafb393c986b1991184f42925969007c3c",
			steps = {
				{ title = "Learn Enchanting", tip = "Apprentice Enchanting lets you craft up to 75 for 10c, at any character level. Not every Enchanting trainer teaches it: Alliance Alanna Raveneye (Teldrassil), Betty Quin (Stormwind City), Eaysaa Brightgust (Zephras Isle), Lalina Summermoon (Darnassus), Nasalanna Windsinger (Zephras Isle) and Thonys Pillarstone (Ironforge); Horde Eaysaa Brightgust (Zephras Isle), Jhag (Orgrimmar), Malcomb Wynn (Undercity), Mot Dawnstrider (Thunder Bluff), Nasalanna Windsinger (Zephras Isle), Pa'zula (Durotar) and Vance Undergloom (Tirisfal Glades). The arrow picks the nearest of your faction. Buy a Copper Rod and Mote of Magic from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from Kitta Firewind (Tower of Azora, Elwynn Forest) and A Pain in the Neck from Pa'zula (Sen'jin Village, Durotar). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 Strange Dust to gather or buy.", section = { title = "Enchanting 1-75", min = 1, max = 75, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "train", profession = "Enchanting", rank = "Apprentice" },
					{ kind = "skill", profession = "Enchanting", value = 1 },
				} },
				{ title = "Enchanting 1-75: vendor goods", tip = "Buy the whole bracket's share in one go: 1 Copper Rod (1s 24c) and 32 Mote of Magic (3s 20c); about 4s 44c in all. The arrow picks the nearest seller of your faction (Stormwind City: Edna Mullby and Jessara Cordell; Orgrimmar: Felika, Kithas and Shimra).", section = { title = "Enchanting 1-75", min = 1, max = 75, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "buy", item = 6217, count = 1, nearest = true },
					{ kind = "buy", item = 247786, count = 32, nearest = true },
				} },
				{ title = "Enchant Bracer - Inferior Stamina to 25", tip = "Enchant Bracer - Inferior Stamina is orange at 1 (yellow 20, green 22, grey 25): about 31 crafts to 25. Each takes 1 Mote of Magic. One Mote of Magic (10c) a craft; grey at 25 on Forever. Make the Runed Copper Rod first: the recipe needs it in your bags, so keep it there. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 1-75", min = 1, max = 75, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 7421, count = 1, note = "a tool: keep it in your bags" },
					{ kind = "craft", spell = 7418, untilSkill = 25 },
				} },
				{ title = "Enchanting recipes at 25", tip = "Back to an Enchanting trainer: Enchant Chest - Inferior Stamina (from 15, 50c). Also learn Enchanted Lute (1s): Forever's Enchanting camp item, 1 Simple Wood and 1 Strange Dust, placed at a campsite beside a campfire for its buff. The Camping 101: Enchanting quest from your starting area's camping guide (after The Great Outdoors) sends you to an enchanting trainer who teaches it free.", section = { title = "Enchanting 1-75", min = 1, max = 75, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "learn", spell = 7420 },
					{ kind = "learn", spell = 1230643 },
				} },
				{ title = "Enchant Chest - Inferior Stamina to 75", tip = "Enchant Chest - Inferior Stamina is orange at 25 (yellow 70, green 90, grey 110): about 51 crafts to 75. Each takes 1 Strange Dust. One Strange Dust a craft: the dust most level 5-20 greens break into, armour above all. Lesser Magic Essence (from weapons) does the same job through Bracer - Minor Deflect or Chest - Minor Absorption if you have more of it. Strange Dust (51 for 1-75): Enchanting: disenchant green items of item level 5-20; or the Auction House. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 1-75", min = 1, max = 75, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 7420, untilSkill = 75 },
					{ kind = "skill", profession = "Enchanting", value = 75 },
				} },
				{ title = "Journeyman Enchanting", tip = "Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs Enchanting 50 and character level 10, so you can take it on any visit from 50. Not every Enchanting trainer teaches it: Alliance Gimble Thistlefuzz (Ironforge), Lucan Cordell (Stormwind City), Taladan (Darnassus) and Xylinnia Starshine (Feralas); Horde Godan (Orgrimmar), Lavinia Crowe (Undercity) and Teg Dawnstrider (Thunder Bluff). The arrow picks the nearest of your faction. Learn now: Enchant Cloak - Minor Protection (from 70, 2s). 75-150 takes about 2s of recipes, plus 1 Shadowgem, 1 Silver Rod, 4 Lesser Magic Essence, 121 Strange Dust and 20 Soul Dust to gather or buy.", section = { title = "Enchanting 75-150", min = 75, max = 150, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "level", level = 10 },
					{ kind = "train", profession = "Enchanting", rank = "Journeyman" },
					{ kind = "learn", spell = 7771 },
				} },
				{ title = "Enchant Chest - Inferior Stamina to 90", tip = "Enchant Chest - Inferior Stamina is yellow at 75 (yellow 70, green 90, grey 110): about 22 crafts to 90. Each takes 1 Strange Dust. One Strange Dust a craft: the dust most level 5-20 greens break into, armour above all. Lesser Magic Essence (from weapons) does the same job through Bracer - Minor Deflect or Chest - Minor Absorption if you have more of it. Strange Dust (121 for 75-150): Enchanting: disenchant green items of item level 5-20; or the Auction House. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 75-150", min = 75, max = 150, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 7420, untilSkill = 90 },
				} },
				{ title = "Enchant Cloak - Minor Protection to 130", tip = "Enchant Cloak - Minor Protection is orange at 90 (yellow 110, green 130, grey 150): about 48 crafts to 130. Each takes 2 Strange Dust. Two Strange Dust a craft (the trainer teaches it from 70 for 2s); keep disenchanting the greens of the 10-20 zones. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 75-150", min = 75, max = 150, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 7771, untilSkill = 130 },
				} },
				{ title = "Enchanting recipes at 130", tip = "Back to an Enchanting trainer: Runed Silver Rod (from 100) and Enchant Bracer - Lesser Stamina (from 130).", section = { title = "Enchanting 75-150", min = 75, max = 150, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "learn", spell = 7795 },
					{ kind = "learn", spell = 13501 },
				} },
				{ title = "Enchant Bracer - Lesser Stamina to 150", tip = "Enchant Bracer - Lesser Stamina is orange at 130 (yellow 155, green 175, grey 195): about 20 crafts to 150, a point every craft. Each takes 1 Soul Dust. One Soul Dust a craft (level 21-30 greens). Make the Runed Silver Rod first: the recipe needs it in your bags, so keep it there. Shadowgem (1 for 75-150): Shadowgem turns up in about one Copper Vein, Tin Vein or Silver Vein in 100: buy it at the Auction House, or keep the ones you find while mining. Silver Rod (1 for 75-150): Blacksmithing: Silver Rod; or the Auction House. Lesser Magic Essence (4 for 75-150): Enchanting: disenchant green items of item level 5-15; or the Auction House. Soul Dust (20 for 75-150): Enchanting: disenchant green items of item level 21-30; or the Auction House. Enchant any item for that slot in your bags, even a grey one. Enchanting 150 is a Legacy System milestone.", section = { title = "Enchanting 75-150", min = 75, max = 150, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 7795, count = 1, note = "a tool: keep it in your bags" },
					{ kind = "craft", spell = 13501, untilSkill = 150 },
					{ kind = "skill", profession = "Enchanting", value = 150 },
				} },
				{ title = "Iridescent Pearl (Alliance)", tip = "1 Iridescent Pearl for Runed Golden Rod: open the Giant Clams at the marked spot, or buy it at the Auction House.", only = { factions = { "Alliance" } }, section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 1437, goals = {
					{ kind = "collect", item = 5500, count = 1, map = 1437, x = 20.7, y = 18.1 },
				} },
				{ title = "Iridescent Pearl (Horde)", tip = "1 Iridescent Pearl for Runed Golden Rod: open the Giant Clams at the marked spot, or buy it at the Auction House.", only = { factions = { "Horde" } }, section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 1440, goals = {
					{ kind = "collect", item = 5500, count = 1, map = 1440, x = 12.3, y = 10 },
				} },
				{ title = "Expert Enchanting", tip = "Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs Enchanting 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Kitta Firewind (Elwynn Forest); Horde Hgarth (Stonetalon Mountains). The arrow picks the nearest of your faction. Learn now: Runed Golden Rod (from 150). 150-225 takes 1 Iridescent Pearl, 1 Black Pearl, 1 Greater Astral Essence, 71 Soul Dust, 1 Golden Rod, 1 Greater Mystic Essence, 21 Vision Dust and 1 Truesilver Rod to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach Enchant Boots - Lesser Agility (from 160), Runed Truesilver Rod (from 200) and Enchant Cloak - Greater Defense (from 205), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3.", section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "level", level = 20 },
					{ kind = "train", profession = "Enchanting", rank = "Expert" },
					{ kind = "learn", spell = 13628 },
				} },
				{ title = "Enchant Bracer - Lesser Stamina to 160", tip = "Enchant Bracer - Lesser Stamina is orange at 150 (yellow 155, green 175, grey 195): about 11 crafts to 160. Each takes 1 Soul Dust. One Soul Dust a craft (level 21-30 greens). Make the Runed Golden Rod now, while it still gives a point: a later recipe needs it in your bags, so keep it there. Greater Astral Essence (1 for 150-225): Enchanting: disenchant green items of item level 16-25; or the Auction House. Soul Dust (71 for 150-225): Enchanting: disenchant green items of item level 21-30; or the Auction House. Golden Rod (1 for 150-225): Blacksmithing: Golden Rod; or the Auction House. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 13628, count = 1, note = "a tool: keep it in your bags" },
					{ kind = "craft", spell = 13501, untilSkill = 160 },
				} },
				{ title = "Enchanting recipes at 160", tip = "Still at the Expert trainer: Enchant Boots - Lesser Agility (from 160).", section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "learn", spell = 13637 },
				} },
				{ title = "Enchant Boots - Lesser Agility to 205", tip = "Enchant Boots - Lesser Agility is orange at 160 (yellow 180, green 200, grey 220): about 59 crafts to 205. Each takes 1 Soul Dust. Soul Dust again. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 13637, untilSkill = 205 },
				} },
				{ title = "Enchanting recipes at 205", tip = "Still at the Expert trainer: Runed Truesilver Rod (from 200) and Enchant Cloak - Greater Defense (from 205).", section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "learn", spell = 13702 },
					{ kind = "learn", spell = 13746 },
				} },
				{ title = "Enchant Cloak - Greater Defense to 225", tip = "Enchant Cloak - Greater Defense is orange at 205 (yellow 225, green 245, grey 265): about 20 crafts to 225, a point every craft. Each takes 1 Vision Dust. One Vision Dust a craft (level 31-40 greens). Make the Runed Truesilver Rod first: the recipe needs it in your bags, so keep it there. Black Pearl (1 for 150-225): Black Pearl is a rare drop (no mob gives it one time in 50): buy it at the Auction House, or keep the ones you find. Greater Mystic Essence (1 for 150-225): Enchanting: disenchant green items of item level 26-35; or the Auction House. Vision Dust (21 for 150-225): Enchanting: disenchant green items of item level 31-40; or the Auction House. Truesilver Rod (1 for 150-225): Blacksmithing: Truesilver Rod; or the Auction House. Enchant any item for that slot in your bags, even a grey one. Enchanting 225 is a Legacy System milestone.", section = { title = "Enchanting 150-225", min = 150, max = 225, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 13702, count = 1, note = "a tool: keep it in your bags" },
					{ kind = "craft", spell = 13746, untilSkill = 225 },
					{ kind = "skill", profession = "Enchanting", value = 225 },
				} },
				{ title = "Artisan Enchanting", tip = "Artisan raises the cap from 225 to 300 for 5g (Classic's price; Forever's is not in the data); it needs Enchanting 200 and character level 35, so you can take it on any visit from 200. Annora teaches Artisan Enchanting inside the Uldaman dungeon (Badlands); bring a group. Learn now: Enchant Gloves - Agility (from 210). 225-300 takes about 2g 20s of recipes and 1g 70s of vendor goods, plus 34 Purple Lotus, 39 Vision Dust and 208 Dream Dust to gather or buy.", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "level", level = 35 },
					{ kind = "train", npc = 11073 },
					{ kind = "learn", npc = 11073, spell = 13815 },
				} },
				{ title = "Enchanting 225-300: vendor goods", tip = "Buy the whole bracket's share in one go: 34 Crystal Vial (1g 70s); about 1g 70s in all. The arrow picks the nearest seller of your faction (Stormwind City: Edna Mullby, Eldraeith and Jasper Fel; Orgrimmar: Felika, Kor'geld and Rekkul).", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "buy", item = 8925, count = 34, nearest = true },
				} },
				{ title = "Formula: Lesser Mana Oil", tip = "Formula: Lesser Mana Oil teaches Lesser Mana Oil (Enchanting 250) for 1g. Sold by Kania (Silithus).", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "buy", item = 20754, nearest = true },
				} },
				{ title = "Formula: Enchant Shield - Greater Stamina", tip = "Formula: Enchant Shield - Greater Stamina teaches Enchant Shield - Greater Stamina (Enchanting 265) for 1g 20s. Sold by Alliance: Mythrin'dir (Darnassus), limited stock; Horde: Daniel Bartlett (Undercity), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "buy", item = 16217, nearest = true },
				} },
				{ title = "Purple Lotus (Alliance)", tip = "34 Purple Lotus for Lesser Mana Oil: Herbalism: Purple Lotus (skill 210) in The Hinterlands (40-50), Feralas (40-50) and Azshara (45-55); or the Auction House. The densest patch of Purple Lotus in The Hinterlands is marked.", only = { factions = { "Alliance" } }, section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 1425, goals = {
					{ kind = "collect", item = 8831, count = 34, map = 1425, x = 66.3, y = 71.6 },
				} },
				{ title = "Purple Lotus (Horde)", tip = "34 Purple Lotus for Lesser Mana Oil: Herbalism: Purple Lotus (skill 210) in The Hinterlands (40-50), Feralas (40-50) and Azshara (45-55); or the Auction House. The densest patch of Purple Lotus in Feralas is marked.", only = { factions = { "Horde" } }, section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 1444, goals = {
					{ kind = "collect", item = 8831, count = 34, map = 1444, x = 56.7, y = 68.9 },
				} },
				{ title = "Enchant Gloves - Agility to 253", tip = "Enchant Gloves - Agility is orange at 225 (yellow 230, green 250, grey 270): about 39 crafts to 253. Each takes 1 Vision Dust. Annora teaches it with Artisan: learn it on that visit. Vision Dust again; bring about 40. Vision Dust (39 for 225-300): Enchanting: disenchant green items of item level 31-40; or the Auction House. Enchant any item for that slot in your bags, even a grey one.", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "craft", spell = 13815, untilSkill = 253 },
				} },
				{ title = "Lesser Mana Oil to 275", tip = "Lesser Mana Oil is orange at 253 (yellow 260, green 270, grey 280): about 34 crafts to 275. Each takes 1 Dream Dust, 1 Purple Lotus and 1 Crystal Vial. One Dream Dust (level 41-50 greens) and one Purple Lotus (herbalists) a craft; the oil sells well. Kania sells the formula at the inn of Cenarion Hold (Silithus): fly there, the mobs around it are level 55 and up. Dream Dust (208 for 225-300): Enchanting: disenchant green items of item level 41-50; or the Auction House.", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "learn", spell = 25127, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 25127, untilSkill = 275 },
				} },
				{ title = "Enchant Shield - Greater Stamina to 300", tip = "Enchant Shield - Greater Stamina is orange at 275 (yellow 285, green 305, grey 325): about 29 crafts to 300. Each takes 6 Dream Dust. Six Dream Dust a craft: the dearest stretch, so disenchant every level 41-50 green you find. Enchant any item for that slot in your bags, even a grey one. Enchanting 300 is a Legacy System milestone.", section = { title = "Enchanting 225-300", min = 225, max = 300, profession = "Enchanting" }, zone = 947, goals = {
					{ kind = "learn", spell = 20017, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 20017, untilSkill = 300 },
					{ kind = "skill", profession = "Enchanting", value = 300 },
				} },
			},
		},
