				{ title = "Rough Stone (Tirisfal Glades)", tip = "46 Rough Stone for Rough Blasting Powder: Mining: Copper Vein (skill 1); or the Auction House. The densest cluster of Copper Vein in Tirisfal Glades is marked.", only = { races = { "Scourge" } }, section = { title = "Engineering 1-75", min = 1, max = 75, profession = "Engineering" }, zone = 1420, goals = {
					{ kind = "collect", item = 2835, count = 46, map = 1420, x = 50.7, y = 34.3 },
				} },
				{ title = "Rough Blasting Powder to 35", tip = "Rough Blasting Powder is orange at 1 (yellow 20, green 30, grey 40): about 46 crafts to 35. Each takes 1 Rough Stone. One Rough Stone a craft; Rough Stone comes with the Copper Ore from Copper Veins.", section = { title = "Engineering 1-75", min = 1, max = 75, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 3918, untilSkill = 35 },
				} },
				{ title = "Engineering recipes at 35", tip = "Back to an Engineering trainer: Handful of Copper Bolts (from 30, 1s 15c). Also learn Reagent Bot (1s): Forever's Engineering camp item, placed at a campsite beside a campfire. It takes a Handful of Copper Bolts and a Copper Tube, which you learn at 30 and 50, so it gives no points. The Camping 101: Engineering quest from your starting area's camping guide (after The Great Outdoors) sends you to an engineering trainer who teaches it free.", section = { title = "Engineering 1-75", min = 1, max = 75, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 3922 },
					{ kind = "learn", spell = 1230656 },
				} },
				{ title = "Handful of Copper Bolts to 57", tip = "Handful of Copper Bolts is orange at 35 (yellow 45, green 52, grey 60): about 33 crafts to 57. Each takes 1 Copper Bar. One Copper Bar a craft. Keep the bolts: Practice Locks and later gadgets take them. Needs an anvil nearby. Blacksmith Hammer is a tool: keep it in your bags. Copper Bar (75 for 1-75): Mining: smelt Copper Ore; or the Auction House.", section = { title = "Engineering 1-75", min = 1, max = 75, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 3922, untilSkill = 57 },
				} },
				{ title = "Engineering recipes at 57", tip = "Back to an Engineering trainer: Arclight Spanner (from 50, 1s 50c) and Copper Tube (from 50, 1s 50c).", section = { title = "Engineering 1-75", min = 1, max = 75, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 7430 },
					{ kind = "learn", spell = 3924 },
				} },
				{ title = "Copper Tube to 75", tip = "Copper Tube is orange at 57 (yellow 80, green 95, grey 110): about 18 crafts to 75, a point every craft. Each takes 2 Copper Bar and 1 Weak Flux. Two Copper Bars and a Weak Flux a craft (blacksmithing and engineering suppliers). Needs an anvil nearby. Make the Arclight Spanner now, while it still gives a point: a later recipe needs it in your bags, so keep it there.", section = { title = "Engineering 1-75", min = 1, max = 75, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 7430, count = 1, note = "a tool: keep it in your bags" },
					{ kind = "craft", spell = 3924, untilSkill = 75 },
					{ kind = "skill", profession = "Engineering", value = 75 },
				} },
				{ title = "Journeyman Engineering", tip = "Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs Engineering 50 and character level 10, so you can take it on any visit from 50. Not every Engineering trainer teaches it: Alliance Finbus Geargrind (Duskwood), Lilliam Sparkspindle (Stormwind City) and Trixie Quikswitch (Ironforge); Horde Franklin Lloyd (Undercity) and Nogg (Orgrimmar). The arrow picks the nearest of your faction. Learn now: Coarse Blasting Powder (from 75, 2s 50c) and Crafted Heavy Shot (from 75, 2s 50c). 75-150 takes about 5s of recipes and 45s of vendor goods, plus 15 Coarse Stone, 27 Heavy Stone, 72 Copper Bar, 61 Bronze Bar and 2 Silver Bar to gather or buy.", section = { title = "Engineering 75-150", min = 75, max = 150, profession = "Engineering" }, zone = 947, goals = {
