				{ title = "Engineering recipes at 125", tip = "Back to an Engineering trainer: Heavy Blasting Powder (from 125).", section = { title = "Engineering 75-150", min = 75, max = 150, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 3945 },
				} },
				{ title = "Heavy Blasting Powder to 140", tip = "Heavy Blasting Powder is yellow at 125 (yellow 125, green 135, grey 145): about 27 crafts to 140. Each takes 1 Heavy Stone. One Heavy Stone a craft (Iron Deposits). Keep some: Iron Grenades take one each.", section = { title = "Engineering 75-150", min = 75, max = 150, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 3945, untilSkill = 140 },
