					{ kind = "train", profession = "Engineering", rank = "Expert" },
					{ kind = "learn", spell = 9271 },
					{ kind = "learn", spell = 3953 },
				} },
				{ title = "Engineering 150-225: vendor goods", tip = "Buy the whole bracket's share in one go: 31 Nightcrawlers (31s); about 31s in all. The arrow picks the nearest seller of your faction (Stormwind City: Catherine Leland and Edna Mullby; Orgrimmar: Felika, Shankys and Shimra).", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "buy", item = 6530, count = 31, nearest = true },
				} },
				{ title = "Medium Leather (Alliance)", tip = "19 Medium Leather for Bronze Framework: Skinning: beasts of level 18-30; or the Auction House. Skin Cave Yeti, Elder Gray Bear, Feral Mountain Lion, Gray Bear, Snapjaw, Starving Mountain Lion and Vicious Gray Bear here (level 18-30); the Skinning guide routes this.", only = { factions = { "Alliance" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1424, goals = {
					{ kind = "collect", item = 2319, count = 19, map = 1424, x = 45.4, y = 34.9 },
				} },
				{ title = "Medium Leather (Horde)", tip = "19 Medium Leather for Bronze Framework: Skinning: beasts of level 18-30; or the Auction House. Skin Ashenvale Bear, Elder Ashenvale Bear, Elder Shadowhorn Stag, Ghostpaw Runner, Giant Ashenvale Bear and Shadowhorn Stag here (level 18-30); the Skinning guide routes this.", only = { factions = { "Horde" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1440, goals = {
					{ kind = "collect", item = 2319, count = 19, map = 1440, x = 68.7, y = 50.2 },
				} },
				{ title = "Wool Cloth", tip = "19 Wool Cloth for Bronze Framework: humanoids of level 15-30 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "collect", item = 2592, count = 19, anywhere = true },
				} },
				{ title = "Coarse Stone (Alliance)", tip = "31 Coarse Stone for Aquadynamic Fish Attractor: Mining: Tin Vein (skill 65) in Loch Modan (10-20), Ashenvale (18-30) and Hillsbrad Foothills (20-30); or the Auction House. The densest cluster of Tin Vein in Loch Modan is marked.", only = { factions = { "Alliance" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1432, goals = {
					{ kind = "collect", item = 2836, count = 31, map = 1432, x = 23.1, y = 24.5 },
				} },
				{ title = "Coarse Stone (Horde)", tip = "31 Coarse Stone for Aquadynamic Fish Attractor: Mining: Tin Vein (skill 65) in The Barrens (10-25), Ashenvale (18-30) and Hillsbrad Foothills (20-30); or the Auction House. The densest cluster of Tin Vein in Ashenvale is marked.", only = { factions = { "Horde" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1440, goals = {
					{ kind = "collect", item = 2836, count = 31, map = 1440, x = 88.7, y = 86.1 },
				} },
				{ title = "Heavy Stone (Alliance)", tip = "74 Heavy Stone for Big Iron Bomb: Mining: Iron Deposit (skill 125) in Arathi Highlands (30-40), Stranglethorn Vale (30-45) and Desolace (30-40); or the Auction House. The densest cluster of Iron Deposit in Arathi Highlands is marked.", only = { factions = { "Alliance" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1417, goals = {
					{ kind = "collect", item = 2838, count = 74, map = 1417, x = 15.8, y = 63.2 },
				} },
				{ title = "Heavy Stone (Horde)", tip = "74 Heavy Stone for Big Iron Bomb: Mining: Iron Deposit (skill 125) in Thousand Needles (25-35), Arathi Highlands (30-40) and Stranglethorn Vale (30-45); or the Auction House. The densest cluster of Iron Deposit in Thousand Needles is marked.", only = { factions = { "Horde" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1441, goals = {
					{ kind = "collect", item = 2838, count = 74, map = 1441, x = 8.9, y = 34.3 },
				} },
				{ title = "Solid Stone (Alliance)", tip = "62 Solid Stone for Solid Blasting Powder: Mining: Mithril Deposit (skill 175) in Stranglethorn Vale (30-45), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Stranglethorn Vale is marked.", only = { factions = { "Alliance" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1434, goals = {
					{ kind = "collect", item = 7912, count = 62, map = 1434, x = 29.4, y = 60.1 },
				} },
				{ title = "Solid Stone (Horde)", tip = "62 Solid Stone for Solid Blasting Powder: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = { "Horde" } }, section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 1443, goals = {
					{ kind = "collect", item = 7912, count = 62, map = 1443, x = 31.5, y = 59.4 },
				} },
				{ title = "Aquadynamic Fish Attractor to 166", tip = "Aquadynamic Fish Attractor is yellow at 150 (yellow 150, green 160, grey 170): about 31 crafts to 166. Each takes 2 Bronze Bar, 1 Nightcrawlers and 1 Coarse Blasting Powder and makes 3. Make the 31 Coarse Blasting Powder first. Nightcrawlers come from trade and fishing suppliers; the attractors sell to fishermen. Bronze Bar (100 for 150-225): Mining: smelt Copper Bar and Tin Bar; or the Auction House.", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 3929, count = 31 },
					{ kind = "craft", spell = 9271, untilSkill = 166 },
				} },
				{ title = "Bronze Framework to 175", tip = "Bronze Framework is yellow at 166 (yellow 145, green 170, grey 195): about 19 crafts to 175. Each takes 2 Bronze Bar, 1 Medium Leather and 1 Wool Cloth. Bronze Frameworks are parts for later gadgets; the extras sell to vendors.", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 3953, untilSkill = 175 },
				} },
				{ title = "Engineering recipes at 175", tip = "Back to an Engineering trainer: Solid Blasting Powder (from 175).", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 12585 },
				} },
				{ title = "Solid Blasting Powder to 191", tip = "Solid Blasting Powder is yellow at 175 (yellow 175, green 185, grey 195): about 31 crafts to 191. Each takes 2 Solid Stone. Two Solid Stone a craft (Mithril Deposits). Make plenty: the triggers, slugs and Gyro-Shot all use it.", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 12585, untilSkill = 191 },
				} },
				{ title = "Engineering recipes at 191", tip = "Back to an Engineering trainer: Big Iron Bomb (from 190).", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 3967 },
				} },
				{ title = "Big Iron Bomb to 210", tip = "Big Iron Bomb is yellow at 191 (yellow 190, green 210, grey 230): about 27 crafts to 210. Each takes 3 Iron Bar, 3 Heavy Blasting Powder and 1 Silver Contact and makes 2. Make the 74 Heavy Blasting Powder and 30 Silver Contact (6 crafts) first. Use the 7 Heavy Blasting Powder you made earlier; the counts above leave them out. A Silver Bar makes five Silver Contacts (grey by now: no points, but no trip to a vendor either); the Heavy Blasting Powder comes from Heavy Stone. Each craft makes two bombs. Specialisation (optional): at 200 and character level 30, Springspindle Fizzlegear (Ironforge), Lilliam Sparkspindle (Stormwind), Graham Van Talen (Undercity) or Tinkerwiz (Ratchet) sends you to Gnomish Engineering (Tinkmaster Overspark, Ironforge, or Oglethorpe Obnoticus, Booty Bay: 6 Mithril Tubes, an Accurate Scope and 2 Advanced Target Dummies) or Goblin Engineering (Nixx Sprocketspring, Gadgetzan: 20 Big Iron Bombs, 20 Solid Dynamite and 5 Explosive Sheep). The Accurate Scope schematic now binds when picked up, but the quest takes a scope someone else made. The membership card lasts 14 days of play; renewing it costs 2g. You can take only one; neither is needed for 300, and the beta never tested them (it stopped at level 30). Needs an anvil nearby. Silver Bar (6 for 150-225): Mining: smelt Silver Ore; or the Auction House. Iron Bar (81 for 150-225): Mining: smelt Iron Ore; or the Auction House.", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 3945, count = 74 },
					{ kind = "craft", spell = 3973, count = 6 },
					{ kind = "craft", spell = 3967, untilSkill = 210 },
				} },
				{ title = "Engineering recipes at 210", tip = "Back to an Engineering trainer: Hi-Impact Mithril Slugs (from 210).", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 12596 },
				} },
				{ title = "Hi-Impact Mithril Slugs to 225", tip = "Hi-Impact Mithril Slugs is yellow at 210 (yellow 210, green 230, grey 250): about 19 crafts to 225. Each takes 1 Mithril Bar and 1 Solid Blasting Powder and makes 200. Use the 19 Solid Blasting Powder you made earlier; the counts above leave them out. One Mithril Bar and one Solid Blasting Powder a craft; hunters buy the slugs. Needs an anvil nearby. Mithril Bar (19 for 150-225): Mining: smelt Mithril Ore; or the Auction House. Engineering 225 is a Legacy System milestone.", section = { title = "Engineering 150-225", min = 150, max = 225, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 12596, untilSkill = 225 },
					{ kind = "skill", profession = "Engineering", value = 225 },
				} },
				{ title = "Artisan Engineering", tip = "Artisan raises the cap from 225 to 300 for 4g 50s (Classic's price; Forever's is not in the data); it needs Engineering 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance Buzzek Bracketswing (Tanaris); Horde Buzzek Bracketswing (Tanaris). The arrow picks the nearest of your faction. 225-300 takes about 2g 80s of recipes, plus 118 Mithril Bar, 212 Solid Stone, 156 Thorium Bar and 24 Runecloth to gather or buy.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "level", level = 35 },
					{ kind = "train", profession = "Engineering", rank = "Artisan" },
				} },
				{ title = "Schematic: Thorium Widget", tip = "Schematic: Thorium Widget teaches Thorium Widget (Engineering 260) for 1g 20s. Sold by Alliance: Gearcutter Cogspinner (Ironforge), limited stock; Horde: Sovik (Orgrimmar), limited stock. Its sellers keep one or two in stock that come back some time after a sale; the Auction House often has it too.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "buy", item = 16042, nearest = true },
				} },
				{ title = "Schematic: Thorium Tube", tip = "Schematic: Thorium Tube teaches Thorium Tube (Engineering 275) for 1g 60s. Sold by Kor'gar (Riverglades) and Xizzer Fizzbolt (Winterspring), limited stock.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "buy", item = 16047, nearest = true },
				} },
				{ title = "Solid Stone (Alliance)", tip = "212 Solid Stone for Hi-Impact Mithril Slugs and Mithril Gyro-Shot: Mining: Mithril Deposit (skill 175) in The Hinterlands (40-50), Feralas (40-50) and Azshara (45-55); or the Auction House. The densest cluster of Mithril Deposit in The Hinterlands is marked.", only = { factions = { "Alliance" } }, section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 1425, goals = {
					{ kind = "collect", item = 7912, count = 212, map = 1425, x = 20.8, y = 58.8 },
				} },
				{ title = "Solid Stone (Horde)", tip = "212 Solid Stone for Hi-Impact Mithril Slugs and Mithril Gyro-Shot: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = { "Horde" } }, section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 1443, goals = {
					{ kind = "collect", item = 7912, count = 212, map = 1443, x = 31.5, y = 59.4 },
				} },
				{ title = "Runecloth", tip = "24 Runecloth for Thorium Widget: humanoids of level 45-60 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "collect", item = 14047, count = 24, anywhere = true },
				} },
				{ title = "Hi-Impact Mithril Slugs to 245", tip = "Hi-Impact Mithril Slugs is yellow at 225 (yellow 210, green 230, grey 250): about 62 crafts to 245. Each takes 1 Mithril Bar and 1 Solid Blasting Powder and makes 200. Make the 50 Solid Blasting Powder first. Use the 12 Solid Blasting Powder you made earlier; the counts above leave them out. One Mithril Bar and one Solid Blasting Powder a craft; hunters buy the slugs. Needs an anvil nearby. Mithril Bar (118 for 225-300): Mining: smelt Mithril Ore; or the Auction House.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 12585, count = 50 },
					{ kind = "craft", spell = 12596, untilSkill = 245 },
				} },
				{ title = "Engineering recipes at 245", tip = "Back to an Engineering trainer: Mithril Gyro-Shot (from 245).", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 12621 },
				} },
				{ title = "Mithril Gyro-Shot to 265", tip = "Mithril Gyro-Shot is yellow at 245 (yellow 245, green 265, grey 285): about 28 crafts to 265. Each takes 2 Mithril Bar and 2 Solid Blasting Powder and makes 200. Make the 56 Solid Blasting Powder first. Two Mithril Bars and two Solid Blasting Powder a craft. Needs an anvil nearby.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "craft", spell = 12585, count = 56 },
					{ kind = "craft", spell = 12621, untilSkill = 265 },
				} },
				{ title = "Thorium Widget to 287", tip = "Thorium Widget is orange at 265 (yellow 280, green 290, grey 300): about 24 crafts to 287. Each takes 3 Thorium Bar and 1 Runecloth. Three Thorium Bars and a Runecloth a craft; the widgets are parts for the later Thorium gadgets. Needs an anvil nearby. Thorium Bar (156 for 225-300): Mining: smelt Thorium Ore; or the Auction House.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
					{ kind = "learn", spell = 19791, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 19791, untilSkill = 287 },
				} },
				{ title = "Thorium Tube to 300", tip = "Thorium Tube is orange at 287 (yellow 295, green 305, grey 315): about 14 crafts to 300. Each takes 6 Thorium Bar. The schematic binds when picked up; six Thorium Bars a craft. Needs an anvil nearby. Engineering 300 is a Legacy System milestone.", section = { title = "Engineering 225-300", min = 225, max = 300, profession = "Engineering" }, zone = 947, goals = {
