			id = "forever/professions/fishing", title = "Fishing 1-300", category = "Professions", levels = { 5, 60 }, zone = 1455, version = 1, revision = "218717de830fe934ddbe7d83964be35ac8127fa32b121bb131502660e066e2f4", legacyRevision = "7142715ac4ff144d3c6708c79f23729bc49c76cea18eccaa60839112fb6107d6",
			steps = {
				{ title = "Learn Fishing", tip = "Any Fishing trainer of your faction teaches Apprentice Fishing at any character level (1s); the arrow picks the nearest, and every starting area has one on its lake or shore. Buy a Fishing Pole (23c) from a trade goods or fishing vendor and equip it (you can only fish with a pole in your hands), and two or three Shiny Baubles (+25, 50c each): a lure adds its bonus to your skill for ten minutes, so fewer fish get away at the start. If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: Fishing, handed in to the fishing trainer it names at skill 20 for the Fish Bowl recipe.", section = { title = "Fishing 1-50", min = 1, max = 50, profession = "Fishing" }, zone = 1455, goals = {
					{ kind = "train", profession = "Fishing", rank = "Apprentice" },
					{ kind = "buy", item = 6256, count = 1, nearest = true },
				} },
				{ title = "Fishing: Elwynn Forest (1-50)", tip = "Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast Fishing from your spellbook, click the bobber when it splashes. Keep the fish: they are your first Cooking ingredients. Fish get away here below skill 25; a lure on the pole adds to your skill for ten minutes and closes the gap.", only = { races = { "Human" } }, section = { title = "Fishing 1-50", min = 1, max = 50, profession = "Fishing" }, zone = 1429, goals = {
