					{ kind = "goto", label = "Valanaar shore", map = 2521, x = 63.3, y = 75.7, frame = "live", radius = 25 },
					{ kind = "skill", profession = "Fishing", value = 50 },
				} },
				{ title = "Journeyman Fishing", tip = "Journeyman Fishing raises the cap to 150; it needs skill 50 and character level 10 (Forever's sniffed trainer lists ask for that level), and costs 5s. The arrow picks the nearest Fishing trainer of your faction. Fish Bowl, Forever's camping item for Fishing (from skill 20, 1s or free from Camping 101: Fishing), is a Raw Brilliant Smallfish in an Empty Vial: it gives no skill, but placed beside a campfire it gives everyone at the camp a buff for an hour.", section = { title = "Fishing 50-125", min = 50, max = 125, profession = "Fishing" }, zone = 2521, goals = {
					{ kind = "level", level = 10 },
					{ kind = "train", profession = "Fishing", rank = "Journeyman" },
					{ kind = "learn", spell = 1229745 },
				} },
				{ title = "Fishing: Westfall (50-125)", tip = "Fish the pools and open water here until skill 125, about 120 catches: from 75 a catch raises the skill less often (about one in two by 100, one in three by 125). Pools (floating wreckage, schools of fish) also give extra loot. Nightcrawlers (+50 from skill 50, 1s each) are twice as strong as a Shiny Bauble. The Strong Fishing Pole (+5 from skill 10, 9s 1c) is in limited stock at fishing vendors: buy it when you see it. Fish get away here below skill 75; a lure on the pole adds to your skill for ten minutes and closes the gap.", only = { races = { "Human", "Skyborne" }, factions = { "Alliance" } }, section = { title = "Fishing 50-125", min = 50, max = 125, profession = "Fishing" }, zone = 1436, goals = {
