				} },
				{ title = "Expert Fishing", tip = "Expert Fishing (cap 225) is a book, not a trainer rank: Old Man Heming sells Expert Fishing - The Bass and You (1g) on the lowest dock of Booty Bay, at the south tip of Stranglethorn Vale, to both factions. Buy it and read it; it needs skill 125 and level 20. At level 20 the safe way in is the boat from Ratchet in The Barrens, not the road through Stranglethorn. He also sells Bright Baubles (+75 from skill 100, 2s 50c each), the lure for the rest of the way.", section = { title = "Fishing 125-225", min = 125, max = 225, profession = "Fishing" }, zone = 1421, goals = {
					{ kind = "level", level = 20 },
					{ kind = "train", profession = "Fishing", rank = "Expert", text = "Buy and read Expert Fishing - The Bass and You (Expert Fishing)" },
				} },
