			id = "forever/professions/leatherworking", title = "Leatherworking 1-300", category = "Professions", levels = { 5, 60 }, zone = 947, version = 1, revision = "b32d2b2b914d407d7f4a7f4cd8c80a2b76be219cc585560f4c8e0a9dd0ff9b0a", legacyRevision = "72bd9588f72be551870d9377eec5c3fef0ecb9b3b4718c5c90283cc8acf91efb",
			steps = {
				{ title = "Learn Leatherworking", tip = "Apprentice Leatherworking lets you craft up to 75 for 10c, at any character level. Not every Leatherworking trainer teaches it: Alliance Adele Fielder (Elwynn Forest), Darianna (Darnassus), Emerii Tallgust (Zephras Isle), Gretta Finespindle (Ironforge), Indari Sunseam (Zephras Isle), Nadyia Maneweaver (Teldrassil) and Randal Worth (Stormwind City); Horde Chaw Stronghide (Mulgore), Dan Golthas (Undercity), Emerii Tallgust (Zephras Isle), Indari Sunseam (Zephras Isle), Kamari (Orgrimmar), Mak (Thunder Bluff) and Shelene Rhobart (Tirisfal Glades). The arrow picks the nearest of your faction. Pair it with Skinning: Light Leather comes from the beasts of every starting zone. Coarse Thread and Salt are sold by leatherworking and trade supplies vendors. 1-75 takes about 1s 50c of recipes and 5s of vendor goods, plus 349 Light Leather to gather or buy.", section = { title = "Leatherworking 1-75", min = 1, max = 75, profession = "Leatherworking" }, zone = 947, goals = {
					{ kind = "train", profession = "Leatherworking", rank = "Apprentice" },
					{ kind = "skill", profession = "Leatherworking", value = 1 },
				} },
				{ title = "Leatherworking 1-75: vendor goods", tip = "Buy the whole bracket's share in one go: 50 Coarse Thread (5s); about 5s in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = { title = "Leatherworking 1-75", min = 1, max = 75, profession = "Leatherworking" }, zone = 947, goals = {
					{ kind = "buy", item = 2320, count = 50, nearest = true },
				} },
				{ title = "Light Leather (Elwynn Forest)", tip = "349 Light Leather for Light Armor Kit, Embossed Leather Gloves and Fine Leather Belt (210 of them for 75-150: pick them all now): Skinning: beasts of level 5-20; or the Auction House. Skin Gray Forest Wolf, Mangy Wolf, Prowler, Rockhide Boar, Stonetusk Boar and Young Forest Bear here (level 5-20); the Skinning guide routes this.", only = { races = { "Human" } }, section = { title = "Leatherworking 1-75", min = 1, max = 75, profession = "Leatherworking" }, zone = 1429, goals = {
					{ kind = "collect", item = 2318, count = 349, map = 1429, x = 55.5, y = 76.6 },
