				{ title = "Thick Leather (Alliance)", tip = "373 Thick Leather for Nightscape Headband and Nightscape Pants: Skinning: beasts of level 38-50; or the Auction House. Skin Elder Crag Coyote, Rabid Crag Coyote, Ridge Huntress and Ridge Stalker Patriarch here (level 38-50); the Skinning guide routes this.", only = { factions = { "Alliance" } }, section = { title = "Leatherworking 150-225", min = 150, max = 225, profession = "Leatherworking" }, zone = 1418, goals = {
