				} },
				{ title = "Pattern: Wicked Leather Gauntlets", tip = "Pattern: Wicked Leather Gauntlets teaches Wicked Leather Gauntlets (Leatherworking 235) for 1g 20s. Sold by Alliance: Leonard Porter (Western Plaguelands), limited stock; Horde: Werg Thickblade (Western Plaguelands), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = { title = "Leatherworking 225-300", min = 225, max = 300, profession = "Leatherworking" }, zone = 947, goals = {
					{ kind = "buy", item = 15725, nearest = true },
				} },
				{ title = "Pattern: Runic Leather Headband", tip = "Pattern: Runic Leather Headband teaches Runic Leather Headband (Leatherworking 265) for 2g 20s. Sold by Jase Farlane (Eastern Plaguelands), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = { title = "Leatherworking 225-300", min = 225, max = 300, profession = "Leatherworking" }, zone = 947, goals = {
					{ kind = "buy", item = 15756, nearest = true },
				} },
				{ title = "Rugged Leather (Alliance)", tip = "1029 Rugged Leather for Rugged Armor Kit, Wicked Leather Gauntlets and Runic Leather Headband: Skinning: beasts of level 48-60; or the Auction House. Skin Frenzied Plaguehound, Plaguehound and Plaguehound Runt here (level 48-60); the Skinning guide routes this.", only = { factions = { "Alliance" } }, section = { title = "Leatherworking 225-300", min = 225, max = 300, profession = "Leatherworking" }, zone = 1423, goals = {
