			id = "forever/professions/skinning", title = "Skinning 1-300", category = "Professions", levels = { 1, 60 }, zone = 1455, version = 1, revision = "3335cdad549e645050936a75ae32c176fc4931ed6224f002eea64546ef36da4a", legacyRevision = "68cbb188d4116d72f6b8cd067c01af24f2e191f8a7eb5dc65d60e11db1187032",
			steps = {
				{ title = "Learn Skinning", tip = "Any Skinning trainer of your faction teaches Apprentice Skinning at any level (10c), and so does the Junior Skinning Trainer in each starting area; the arrow picks the nearest. Buy a Skinning Knife from a trade goods or general vendor: keep it in your bags, you cannot skin without it. The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's Cactus Apple Surprise, A Humble Task, Marla's Last Wish) offers Pelt Collecting for Beginners as a reward: reading it gives 2 skill, up to 15. Trade goods vendors and the junior trainers sell the Apprentice's Skinning Satchel, a four-slot bag for leather and hides (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: Skinning: hand it in to the skinning trainer it names once you reach skill 20, for the Camp Chair recipe.", section = { title = "Skinning 1-50", min = 1, max = 50, profession = "Skinning" }, zone = 1455, goals = {
					{ kind = "train", profession = "Skinning", rank = "Apprentice" },
					{ kind = "buy", item = 7005, count = 1, nearest = true },
				} },
