		{
			id = "forever/professions/tailoring", title = "Tailoring 1-300", category = "Professions", levels = { 5, 60 }, zone = 947, version = 1, revision = "aff590ee339cd242ee2ddfe106bfcd102fa21ea73c19f697a461500c81f22f3b", legacyRevision = "98dc1885e7bc8b48f156f25f945782633106b40804b3771c4098e9e666aaadcc",
			steps = {
				{ title = "Learn Tailoring", tip = "Apprentice Tailoring lets you craft up to 75 for 10c, at any character level. Any Tailoring trainer of your faction teaches it; the arrow picks the nearest. Keep every Linen Cloth you loot: humanoids of level 5-20 drop it. 1-75 takes about 50c of recipes and 7s 20c of vendor goods, plus 144 Linen Cloth to gather or buy.", section = { title = "Tailoring 1-75", min = 1, max = 75, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "train", profession = "Tailoring", rank = "Apprentice" },
					{ kind = "skill", profession = "Tailoring", value = 1 },
				} },
				{ title = "Tailoring 1-75: vendor goods", tip = "Buy the whole bracket's share in one go: 72 Coarse Thread (7s 20c); about 7s 20c in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = { title = "Tailoring 1-75", min = 1, max = 75, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "buy", item = 2320, count = 72, nearest = true },
				} },
				{ title = "Linen Cloth", tip = "144 Linen Cloth for Linen Cloak and Linen Belt: humanoids of level 5-20 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Tailoring 1-75", min = 1, max = 75, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "collect", item = 2589, count = 144, anywhere = true },
				} },
				{ title = "Linen Cloak to 15", tip = "Linen Cloak is orange at 1 (yellow 35, green 47, grey 60): about 7 crafts to 15, a point every craft. Each takes 1 Bolt of Linen Cloth and 1 Coarse Thread. Make the 7 Bolt of Linen Cloth first: it gives points too while not grey. The trainer teaches it, and it is the cheapest way through these points in the data.", section = { title = "Tailoring 1-75", min = 1, max = 75, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 2963, count = 7 },
					{ kind = "craft", spell = 2387, untilSkill = 15 },
				} },
				{ title = "Tailoring recipes at 15", tip = "Back to a Tailoring trainer: Linen Belt (from 15, 50c).", section = { title = "Tailoring 1-75", min = 1, max = 75, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 8776 },
				} },
				{ title = "Linen Belt to 75", tip = "Linen Belt is orange at 15 (yellow 50, green 67, grey 85): about 65 crafts to 75. Each takes 1 Bolt of Linen Cloth and 1 Coarse Thread. Make the 65 Bolt of Linen Cloth first: it gives points too while not grey. Each belt takes one bolt; the belts sell to vendors.", section = { title = "Tailoring 1-75", min = 1, max = 75, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 2963, count = 65 },
					{ kind = "craft", spell = 8776, untilSkill = 75 },
					{ kind = "skill", profession = "Tailoring", value = 75 },
				} },
				{ title = "Journeyman Tailoring", tip = "Journeyman raises the cap from 75 to 150 for 5s; it needs Tailoring 50 and character level 10, so you can take it on any visit from 50. Not every Tailoring trainer teaches it: Alliance Grarnik Goodstitch (Stranglethorn Vale), Jormund Stonebrow (Ironforge), Me'lynn (Darnassus), Othesia Evengale (Zephras Isle), Sellandus (Stormwind City) and Taleen Shimmerthread (Zephras Isle); Horde Grarnik Goodstitch (Stranglethorn Vale), Magar (Orgrimmar), Mahani (The Barrens), Othesia Evengale (Zephras Isle), Rhiannon Davis (Undercity), Taleen Shimmerthread (Zephras Isle) and Tepa (Thunder Bluff). The arrow picks the nearest of your faction. Learn now: Bolt of Woolen Cloth (from 55, 1s) and Woolen Cape (from 55, 2s 50c). Also learn Faction Banner (1s): Forever's Tailoring camp item, a Bolt of Linen Cloth and a Coarse Thread; each faction has its own. The Camping 101: Tailoring quest from your starting area's camping guide (after The Great Outdoors) sends you to a tailoring trainer who teaches it free. 75-150 takes about 11s of recipes and 1g 65s 50c of vendor goods, plus 567 Wool Cloth and 204 Silk Cloth to gather or buy.", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "level", level = 10 },
					{ kind = "train", profession = "Tailoring", rank = "Journeyman" },
					{ kind = "learn", spell = 2964 },
					{ kind = "learn", spell = 2402 },
					{ kind = "learn", spell = 1263425, only = { factions = { "Alliance" } } },
					{ kind = "learn", spell = 1229504, only = { factions = { "Horde" } } },
				} },
				{ title = "Tailoring 75-150: vendor goods", tip = "Buy the whole bracket's share in one go: 108 Fine Thread (1g 8s), 34 Bleach (8s 50c) and 98 Red Dye (49s); about 1g 65s 50c in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "buy", item = 2321, count = 108, nearest = true },
					{ kind = "buy", item = 2324, count = 34, nearest = true },
					{ kind = "buy", item = 2604, count = 98, nearest = true },
				} },
				{ title = "Wool Cloth", tip = "567 Wool Cloth for Woolen Cape and Stylish Red Shirt: humanoids of level 15-30 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "collect", item = 2592, count = 567, anywhere = true },
				} },
