					{ kind = "collect", item = 4306, count = 204, anywhere = true },
				} },
				{ title = "Woolen Cape to 104", tip = "Woolen Cape is orange at 75 (yellow 80, green 97, grey 115): about 42 crafts to 104. Each takes 1 Bolt of Woolen Cloth and 1 Fine Thread. Make the 42 Bolt of Woolen Cloth first: it gives points too while not grey. Bolt of Woolen Cloth is taught from 55 on Forever.", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 2964, count = 42 },
					{ kind = "craft", spell = 2402, untilSkill = 104 },
				} },
				{ title = "Tailoring recipes at 104", tip = "Back to a Tailoring trainer: Stylish Red Shirt (from 85, 2s 50c).", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 3866 },
				} },
				{ title = "Stylish Red Shirt to 135", tip = "Stylish Red Shirt is orange at 104 (yellow 110, green 127, grey 145): about 49 crafts to 135. Each takes 3 Bolt of Woolen Cloth, 2 Red Dye and 1 Fine Thread. Make the 147 Bolt of Woolen Cloth first. Three woolen bolts and two Red Dye a shirt; Wool Cloth drops from humanoids of level 15-30.", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 2964, count = 147 },
					{ kind = "craft", spell = 3866, untilSkill = 135 },
				} },
				{ title = "Tailoring recipes at 135", tip = "Back to a Tailoring trainer: Bolt of Silk Cloth (from 100, 5s) and Formal White Shirt (from 135).", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 3839 },
					{ kind = "learn", spell = 3871 },
				} },
				{ title = "Formal White Shirt to 150", tip = "Formal White Shirt is orange at 135 (yellow 145, green 150, grey 155): about 17 crafts to 150. Each takes 3 Bolt of Silk Cloth, 2 Bleach and 1 Fine Thread. Make the 51 Bolt of Silk Cloth first. Silk bolts from here on: Silk Cloth drops from humanoids of level 25-45. Bleach from tailoring and trade supplies vendors. Tailoring 150 is a Legacy System milestone.", section = { title = "Tailoring 75-150", min = 75, max = 150, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 3839, count = 51 },
					{ kind = "craft", spell = 3871, untilSkill = 150 },
					{ kind = "skill", profession = "Tailoring", value = 150 },
				} },
				{ title = "Tailoring 150-225: vendor goods", tip = "Buy the whole bracket's share in one go: 44 Fine Thread (44s), 90 Silken Thread (4g 50s), 44 Blue Dye (22s) and 80 Heavy Silken Thread (16g); about 21g 16s in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "buy", item = 2321, count = 44, nearest = true },
					{ kind = "buy", item = 4291, count = 90, nearest = true },
					{ kind = "buy", item = 6260, count = 44, nearest = true },
					{ kind = "buy", item = 8343, count = 80, nearest = true },
				} },
				{ title = "Pattern: Azure Silk Cloak", tip = "Pattern: Azure Silk Cloak teaches Azure Silk Cloak (Tailoring 140) for 15s. Sold by Alliance: Brienna Starglow (Feralas), limited stock and Norvin Alderman (Alterac Mountains); Horde: Jun'ha (Arathi Highlands), limited stock and Norvin Alderman (Alterac Mountains).", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "buy", item = 7089, nearest = true },
				} },
				{ title = "Silk Cloth", tip = "264 Silk Cloth for Azure Silk Cloak: humanoids of level 25-45 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "collect", item = 4306, count = 264, anywhere = true },
				} },
				{ title = "Mageweave Cloth", tip = "900 Mageweave Cloth for Black Mageweave Vest and Black Mageweave Headband: humanoids of level 35-50 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "collect", item = 4338, count = 900, anywhere = true },
				} },
				{ title = "Expert Tailoring", tip = "Expert raises the cap from 150 to 225; it needs Tailoring 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Georgio Bolero (Stormwind City); Horde Josef Gregorian (Undercity). The arrow picks the nearest of your faction. Learn now: Bolt of Mageweave (from 140). 150-225 takes about 15s of recipes and 21g 16s of vendor goods, plus 264 Silk Cloth and 900 Mageweave Cloth to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach Black Mageweave Vest (from 170) and Black Mageweave Headband (from 190), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3.", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "level", level = 20 },
					{ kind = "train", profession = "Tailoring", rank = "Expert" },
					{ kind = "learn", spell = 3865 },
				} },
				{ title = "Azure Silk Cloak to 170", tip = "Azure Silk Cloak is orange at 150 (yellow 160, green 175, grey 190): about 22 crafts to 170. Each takes 3 Bolt of Silk Cloth, 2 Blue Dye and 2 Fine Thread. Make the 66 Bolt of Silk Cloth first. Its recipe is the one bought above; it is the cheapest way through these points in the data.", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 8786, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 3839, count = 66 },
					{ kind = "craft", spell = 8786, untilSkill = 170 },
				} },
				{ title = "Tailoring recipes at 170", tip = "Still at the Expert trainer: Black Mageweave Vest (from 170).", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 12048 },
				} },
				{ title = "Black Mageweave Vest to 197", tip = "Black Mageweave Vest is orange at 170 (yellow 185, green 200, grey 215): about 30 crafts to 197. Each takes 2 Bolt of Mageweave and 3 Silken Thread. Make the 60 Bolt of Mageweave first. The trainer teaches it, and it is the cheapest way through these points in the data.", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 3865, count = 60 },
					{ kind = "craft", spell = 12048, untilSkill = 197 },
				} },
				{ title = "Tailoring recipes at 197", tip = "Still at the Expert trainer: Black Mageweave Headband (from 190).", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 12072 },
				} },
				{ title = "Black Mageweave Headband to 225", tip = "Black Mageweave Headband is orange at 197 (yellow 205, green 220, grey 235): about 40 crafts to 225. Each takes 3 Bolt of Mageweave and 2 Heavy Silken Thread. Make the 120 Bolt of Mageweave first. The trainer teaches it, and it is the cheapest way through these points in the data. Tailoring 225 is a Legacy System milestone.", section = { title = "Tailoring 150-225", min = 150, max = 225, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 3865, count = 120 },
					{ kind = "craft", spell = 12072, untilSkill = 225 },
					{ kind = "skill", profession = "Tailoring", value = 225 },
				} },
				{ title = "Artisan Tailoring", tip = "Artisan raises the cap from 225 to 300; it needs Tailoring 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance Timothy Worthington (Dustwallow Marsh); Horde Daryl Stack (Hillsbrad Foothills). The arrow picks the nearest of your faction. Learn now: Bolt of Runecloth (from 205) and Runecloth Belt (from 210). 225-300 takes about 1g 60s of recipes and 58g of vendor goods, plus 420 Rugged Leather, 3195 Runecloth and 124 Ironweb Spider Silk to gather or buy.", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "level", level = 35 },
					{ kind = "train", profession = "Tailoring", rank = "Artisan" },
					{ kind = "learn", spell = 18401 },
					{ kind = "learn", spell = 18402 },
				} },
				{ title = "Tailoring 225-300: vendor goods", tip = "Buy the whole bracket's share in one go: 116 Rune Thread (58g); about 58g in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "buy", item = 14341, count = 116, nearest = true },
				} },
				{ title = "Pattern: Runecloth Gloves", tip = "Pattern: Runecloth Gloves teaches Runecloth Gloves (Tailoring 230) for 1g 60s. Sold by Qia (Winterspring), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "buy", item = 14481, nearest = true },
				} },
				{ title = "Rugged Leather (Alliance)", tip = "420 Rugged Leather for Runecloth Gloves and Runecloth Shoulders: Skinning: beasts of level 48-60; or the Auction House. Skin Frenzied Plaguehound, Plaguehound and Plaguehound Runt here (level 48-60); the Skinning guide routes this.", only = { factions = { "Alliance" } }, section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 1423, goals = {
					{ kind = "collect", item = 8170, count = 420, map = 1423, x = 56, y = 46.8, frame = "live" },
				} },
				{ title = "Rugged Leather (Horde)", tip = "420 Rugged Leather for Runecloth Gloves and Runecloth Shoulders: Skinning: beasts of level 48-60; or the Auction House. Skin Coralshell Tortoise, Mosshoof Stag, Thunderhead Consort, Thunderhead Patriarch, Thunderhead Skystormer and Thunderhead Stagwing here (level 48-60); the Skinning guide routes this.", only = { factions = { "Horde" } }, section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 1447, goals = {
					{ kind = "collect", item = 8170, count = 420, map = 1447, x = 58.8, y = 21.5 },
				} },
				{ title = "Runecloth", tip = "3195 Runecloth for Runecloth Belt, Runecloth Gloves and Runecloth Shoulders: humanoids of level 45-60 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "collect", item = 14047, count = 3195, anywhere = true },
				} },
				{ title = "Ironweb Spider Silk (Alliance)", tip = "124 Ironweb Spider Silk for Runecloth Shoulders: it drops from Plague Lurker (level 54-55) at the marked spot, or buy it at the Auction House.", only = { factions = { "Alliance" } }, section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 1422, goals = {
					{ kind = "collect", item = 14227, count = 124, map = 1422, x = 57.1, y = 53.5 },
				} },
				{ title = "Ironweb Spider Silk (Horde)", tip = "124 Ironweb Spider Silk for Runecloth Shoulders: it drops from Rock Stalker (level 57-59) at the marked spot, or buy it at the Auction House.", only = { factions = { "Horde" } }, section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 1451, goals = {
					{ kind = "collect", item = 14227, count = 124, map = 1451, x = 24.7, y = 81.8 },
				} },
				{ title = "Runecloth Belt to 234", tip = "Runecloth Belt is yellow at 225 (yellow 225, green 240, grey 255): about 11 crafts to 234. Each takes 3 Bolt of Runecloth and 1 Rune Thread. Make the 33 Bolt of Runecloth first. Rune Thread from tailoring vendors.", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "craft", spell = 18401, count = 33 },
					{ kind = "craft", spell = 18402, untilSkill = 234 },
				} },
				{ title = "Runecloth Gloves to 265", tip = "Runecloth Gloves is orange at 234 (yellow 245, green 260, grey 275): about 43 crafts to 265. Each takes 4 Bolt of Runecloth, 4 Rugged Leather and 1 Rune Thread. Make the 172 Bolt of Runecloth first. Qia in Everlook keeps one pattern at a time; the Timbermaw Hold tunnel from Felwood is the road in, so never kill Timbermaw furbolgs on the way.", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 18417, note = "from the recipe in your bags" },
					{ kind = "craft", spell = 18401, count = 172 },
					{ kind = "craft", spell = 18417, untilSkill = 265 },
				} },
				{ title = "Runecloth Shoulders to 300", tip = "Runecloth Shoulders is orange at 265 (yellow 275, green 290, grey 305): about 62 crafts to 300. Each takes 7 Bolt of Runecloth, 2 Ironweb Spider Silk, 4 Rugged Leather and 1 Rune Thread. Make the 434 Bolt of Runecloth first. Its pattern (Pattern: Runecloth Shoulders) drops from mobs all over the world and does not bind: buy it at the Auction House. Seven bolts, two Ironweb Spider Silk and four Rugged Leather a craft: the dearest stretch. The spiders of Western Plaguelands and Silithus drop the silk (the marked spots), or the Auction House. No pattern on the Auction House? Runecloth Gloves still give a point now and then to 275, and Runecloth Boots (Darnall, Moonglade) to 280, at 4 bolts a craft. Mooncloth (pattern from Qia or Evie Whirlbrew in Everlook; 2 Felcloth at a Moonwell) stays orange to 270 and yellow to 285, but it can be made once every four days. The Spinning Wheel patterns (Merchant's Favor sandals and waistcords from Jim'bek or Mivin Shadowweave; the wheel's blueprint drops from the Unstable Sentinel in the City of Dalaran) and Runecloth Cuffs (Pexmit in Mount Hyjal, 10g; we could not confirm that vendor yet) are the other ways on. Tailoring 300 is a Legacy System milestone.", section = { title = "Tailoring 225-300", min = 225, max = 300, profession = "Tailoring" }, zone = 947, goals = {
					{ kind = "learn", spell = 18449, note = "from the pattern bought at the Auction House" },
					{ kind = "craft", spell = 18401, count = 434 },
					{ kind = "craft", spell = 18449, untilSkill = 300 },
					{ kind = "skill", profession = "Tailoring", value = 300 },
				} },
			},
		},
		{
			id = "forever/reputation/alterac-valley", title = "Alterac Valley Reputation", category = "Reputation", folder = "Reputation · Battlegrounds", levels = { 51, 60 }, zone = 1416, version = 1, revision = "a4d43bc0f4dc500ffd10c21fa5d29655b2a472365d6c4e6d94b147e70c944fcf", legacyRevision = "6a9e9ba748fca46efca68cd19a123153af1c247e713444b6024012b6afad8bda", keywords = { "Stormpike Guard", "Frostwolf Clan", "Alterac Valley", "Lieutenant Haggerdin", "Warmaster Laggrond", "Stormpike Insignia", "Frostwolf Insignia", "Armor Scraps", "Murgot Deepforge", "Smith Regzar", "Thanthaldis Snowgleam", "Jekyll Flandring", "Alterac Valley Mark of Honor", "Stormpike Battle Charger", "Horn of the Frostwolf Howler", "Master of Alterac Valley", "Legacy Point" }, collects = { 19032, 19031 }, rewards = { { text = "Master of Alterac Valley: a Legacy Point at Exalted" }, { item = 17904, name = "Stormpike Insignia Rank 6" }, { item = 17909, name = "Frostwolf Insignia Rank 6" }, { item = 19032 }, { item = 19031 } }, why = "One-time quests worth 2,000 and big wins make it the quickest of the four; Exalted gives a Legacy Point.",
			steps = {
				{ title = "Lieutenant Rotimer", tip = "Alterac Valley is a 40 against 40 battle for level 51 and up, and the fastest of the four battleground reputations: it has about 2,000 reputation of one-time quests, and a full win pays several hundred. The same one-time quests also pay 1,870 Ironforge reputation. Lieutenant Rotimer recruits outside the Great Forge. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Alliance" } }, zone = 1455, goals = {
					{ kind = "accept", quest = 7261, note = "The Sovereign Imperative, 100" },
				} },
				{ title = "Lieutenant Haggerdin", tip = "The Stormpike camp stands outside the Alterac Valley gate, on the Alterac Mountains side above Hillsbrad. Take every quest here: they all pay 100 or more, once.", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "turnin", quest = 7261 },
					{ kind = "accept", quest = 7162, note = "Proving Grounds: the Stormpike Banner in Icewing Cavern, 100" },
					{ kind = "accept", quest = 7081, note = "Sergeant Durgen Stormpike: assault a graveyard, 100" },
					{ kind = "accept", quest = 7102, note = "destroy a tower or bunker banner, 100" },
					{ kind = "accept", quest = 7122, note = "capture a mine, 100" },
				} },
				{ title = "Dun Baldar", tip = "Queue at the gate, at any battlemaster or from the battleground screen; you enter at Dun Baldar in the north. Before the gates open, take the quests in the town: they are done during the battle.", only = { factions = { "Alliance" } }, zone = 1459, goals = {
					{ kind = "accept", quest = 7121, note = "Mountaineer Boombellow: The Quartermaster, 10" },
					{ kind = "turnin", quest = 7121 },
					{ kind = "accept", quest = 7223, note = "Murgot Deepforge: 20 Armor Scraps, 100" },
					{ kind = "accept", quest = 7282, note = "Commander Karl Philips: Brotherly Love, 100" },
					{ kind = "accept", quest = 7301, note = "Commander Duffy: Fallen Sky Lords, 100" },
					{ kind = "accept", quest = 7367, note = "Stormpike Explosives Expert: Defusing the Threat, 100" },
				} },
				{ title = "Icewing Cavern", tip = "Icewing Cavern lies southwest of Dun Baldar. The Stormpike Banner stands at the back of the cave, past the yetis and harpies.", only = { factions = { "Alliance" } }, zone = 1459, goals = {
					{ kind = "collect", quest = 7162, objective = 1, item = 17849, note = "Stormpike Banner" },
				} },
				{ title = "The battle", tip = "Most of this happens on the way to Drek'Thar. Loot Armor Scraps from Horde players and guards you kill. Assault the Snowfall Graveyard or any Horde graveyard, burn a Horde tower (click its banner), and take Coldtooth Mine. Commander Louis Philips stands at Tower Point; the Frostwolf Explosives Expert at Frostwolf Village. Fallen Sky Lords asks you to find where the three wing commanders landed. In Classic every tower, graveyard or mine paid 12 reputation, Captain Galvangar 125 and Drek'Thar about 300.", only = { factions = { "Alliance" } }, zone = 1459, goals = {
					{ kind = "collect", quest = 7223, objective = 1, item = 17422, count = 20, note = "Armor Scraps" },
					{ kind = "kill", quest = 7081, objective = 1, npc = 13756, note = "assault a graveyard" },
					{ kind = "kill", quest = 7102, objective = 1, npc = 13778, map = 1459, x = 48.2, y = 58.7, note = "Iceblood Tower banner" },
					{ kind = "kill", quest = 7122, objective = 1, npc = 13796, map = 1459, x = 44.3, y = 67.9, note = "Coldtooth Mine" },
					{ kind = "kill", quest = 7282, objective = 1, npc = 13154, note = "Commander Louis Philips" },
					{ kind = "kill", quest = 7301, objective = 1, npc = 14029, note = "Wing Commander Ichman's spot" },
					{ kind = "kill", quest = 7301, objective = 2, npc = 14031, note = "Wing Commander Vipore's spot" },
					{ kind = "kill", quest = 7301, objective = 3, npc = 14030, note = "Wing Commander Slidore's spot" },
					{ kind = "kill", quest = 7367, objective = 1, npc = 13597, note = "Frostwolf Explosives Expert" },
				} },
				{ title = "Back in Dun Baldar", only = { factions = { "Alliance" } }, zone = 1459, goals = {
					{ kind = "turnin", quest = 7223 },
					{ kind = "turnin", quest = 7282 },
					{ kind = "turnin", quest = 7301 },
					{ kind = "turnin", quest = 7367 },
				} },
				{ title = "Back at the gate", tip = "Your first Alterac Valley Marks of Honor go to the Alliance Brigadier General beside Lieutenant Haggerdin: 150 the first time (Remember Alterac Valley!), then 100 for every 3 more. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Alterac Valley marks: hand in or spend them before you reach that.", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "turnin", quest = 7162, note = "Stormpike Insignia Rank 1" },
					{ kind = "turnin", quest = 7081 },
					{ kind = "turnin", quest = 7102 },
					{ kind = "turnin", quest = 7122 },
					{ kind = "accept", quest = 8375 },
					{ kind = "collect", quest = 8375, objective = 1, item = 20560, count = 3, map = 1416, x = 39.3, y = 82.3, note = "Alterac Valley Marks of Honor: play games" },
					{ kind = "turnin", quest = 8375 },
				} },
				{ title = "Stormpike Guard to Friendly", tip = "Prospector Stonehewer by the gate wants Drek'Thar dead: win a game in which your team kills him. Then he lets you pick a weapon (Hero of the Stormpike).", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7141, optional = true, note = "The Battle of Alterac, 200" },
					{ kind = "turnin", quest = 7141, optional = true },
					{ kind = "accept", quest = 8271, optional = true },
					{ kind = "turnin", quest = 8271, optional = true, note = "Hero of the Stormpike, 10 and a weapon" },
					{ kind = "rep", factionId = 730, standing = "Friendly" },
				} },
				{ title = "Rise and Be Recognized", tip = "Friendly lets Lieutenant Haggerdin upgrade your insignia: 100 reputation. Friendly to Honored is 6000 reputation. In Classic a full win paid 300 to 700 with its 3 marks; the Brigadier General keeps taking 3 marks for 100. Inside, Master Ryson's All Seeing Eye (75, from the Winterax caves) repeats every game; Korrak the Bloodrager (200, when he appears in the middle of the valley) goes back to Lieutenant Haggerdin here. Friendly opens the Stormpike Battle Tabard (1g) and the Superior Healing and Mana Draughts (5s) at Thanthaldis Snowgleam beside him.", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7168 },
					{ kind = "turnin", quest = 7168 },
					{ kind = "buy", npc = 13217, item = 19032, note = "Stormpike Battle Tabard, 1g" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: Remember Alterac Valley! again, 100 for 3 marks" },
					{ kind = "rep", factionId = 730, standing = "Honored" },
				} },
				{ title = "Honored Amongst the Guard", tip = "Honored: insignia rank 3, 100 reputation. Honored to Revered is 12000 reputation. Thanthaldis Snowgleam beside Lieutenant Haggerdin sells the Stormpike Soldier's and Sage's Cloaks and Pendants (about 7g each), the Stormpike belts (4g74s to 7g12s) and the Major Healing and Mana Draughts (10s).", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7169 },
					{ kind = "turnin", quest = 7169 },
					{ kind = "talk", npc = 13217, optional = true, note = "Thanthaldis Snowgleam" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 100 for 3 marks" },
					{ kind = "rep", factionId = 730, standing = "Revered" },
				} },
				{ title = "Earned Reverence", tip = "Revered: insignia rank 4, 150 reputation. Revered to Exalted is 21000 reputation, half the climb. Revered opens the weapons at Thanthaldis Snowgleam: Electrified Dagger, Crackling Staff and Stormstrike Hammer (31g65s to 39g85s), and the Stormpike Battle Standard (5g). At 51 and up Concerted Efforts (3 marks each from Alterac Valley, Arathi Basin and Warsong Gulch) pays 200 the first time and 150 after, plus reputation for the other two battlegrounds.", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7170 },
					{ kind = "turnin", quest = 7170 },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: Concerted Efforts" },
					{ kind = "talk", npc = 13217, optional = true, note = "Thanthaldis Snowgleam: Revered rewards" },
					{ kind = "rep", factionId = 730, standing = "Exalted" },
				} },
				{ title = "Legendary Heroes", tip = "Exalted gives the Legacy Point \"Master of Alterac Valley\" and the last two insignia, 400 reputation that no longer counts for anything but the insignia. Thanthaldis Snowgleam sells the Stormpike Battle Charger (200g, level 60; its own guide), Don Julio's Band and Don Rodrigo's Band (75g56s), The Unstoppable Force (156g49s), The Immovable Object (79g53s), The Lobotomizer (125g66s) and the 50g tomes and off-hands.", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7171 },
					{ kind = "turnin", quest = 7171 },
					{ kind = "accept", quest = 7172 },
					{ kind = "turnin", quest = 7172 },
					{ kind = "talk", npc = 13217, optional = true, note = "Thanthaldis Snowgleam: Exalted rewards" },
				} },
				{ title = "Frostwolf Ambassador Rokhstrom", tip = "Alterac Valley is a 40 against 40 battle for level 51 and up, and the fastest of the four battleground reputations: it has about 2,000 reputation of one-time quests, and a full win pays several hundred. The same one-time quests also pay 1,870 Orgrimmar reputation. Frostwolf Ambassador Rokhstrom stands in the Valley of Strength. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "accept", quest = 7241, note = "In Defense of Frostwolf, 100" },
				} },
				{ title = "Warmaster Laggrond", tip = "The Frostwolf camp stands outside the Alterac Valley gate in the Alterac Mountains. Take every quest here: they all pay 100 or more, once.", only = { factions = { "Horde" } }, zone = 1416, goals = {
					{ kind = "turnin", quest = 7241 },
					{ kind = "accept", quest = 7161, note = "Proving Grounds: the Frostwolf Banner in Wildpaw Cavern, 100" },
					{ kind = "accept", quest = 7082, note = "Corporal Teeka Bloodsnarl: assault a graveyard, 100" },
					{ kind = "accept", quest = 7101, note = "capture a tower or bunker, 100" },
					{ kind = "accept", quest = 7124, note = "capture a mine, 100" },
				} },
				{ title = "Frostwolf Village", tip = "Queue at the gate, at any battlemaster or from the battleground screen; you enter at Frostwolf Village in the south. Before the gates open, take the quests in the village: they are done during the battle.", only = { factions = { "Horde" } }, zone = 1459, goals = {
					{ kind = "accept", quest = 7123, note = "Jotek: Speak with our Quartermaster, 10" },
					{ kind = "turnin", quest = 7123 },
					{ kind = "accept", quest = 7224, note = "Smith Regzar: 20 Armor Scraps, 100" },
					{ kind = "accept", quest = 7281, note = "Commander Louis Philips: Brotherly Love, 100" },
					{ kind = "accept", quest = 7302, note = "Commander Mulfort: Fallen Sky Lords, 100" },
					{ kind = "accept", quest = 7368, note = "Frostwolf Explosives Expert: Defusing the Threat, 100" },
				} },
				{ title = "Wildpaw Cavern", tip = "Wildpaw Cavern lies south of Frostwolf Keep. The Frostwolf Banner stands at the back of the cave, past the gnolls.", only = { factions = { "Horde" } }, zone = 1459, goals = {
					{ kind = "collect", quest = 7161, objective = 1, item = 17850, note = "Frostwolf Banner" },
				} },
				{ title = "The battle", tip = "Most of this happens on the way to Vanndar Stormpike. Loot Armor Scraps from Alliance players and guards you kill. Assault the Snowfall Graveyard or any Alliance graveyard, burn an Alliance bunker (click its banner), and take Irondeep Mine. Commander Karl Philips stands at Icewing Bunker; the Stormpike Explosives Expert in Dun Baldar. Fallen Sky Lords asks you to find where the three wing commanders landed. In Classic every tower, graveyard or mine paid 12 reputation, Captain Balinda Stonehearth 125 and Vanndar about 300.", only = { factions = { "Horde" } }, zone = 1459, goals = {
					{ kind = "collect", quest = 7224, objective = 1, item = 17422, count = 20, note = "Armor Scraps" },
					{ kind = "kill", quest = 7082, objective = 1, npc = 13756, note = "assault a graveyard" },
					{ kind = "kill", quest = 7101, objective = 1, npc = 13778, map = 1459, x = 52.5, y = 43.8, note = "Stonehearth Bunker banner" },
					{ kind = "kill", quest = 7124, objective = 1, npc = 13796, map = 1459, x = 52.5, y = 7.6, note = "Irondeep Mine" },
					{ kind = "kill", quest = 7281, objective = 1, npc = 13320, note = "Commander Karl Philips" },
					{ kind = "kill", quest = 7302, objective = 1, npc = 14026, note = "Wing Commander Guse's spot" },
