					{ kind = "kill", quest = 7302, objective = 3, npc = 14027, note = "Wing Commander Mulverick's spot" },
					{ kind = "kill", quest = 7368, objective = 1, npc = 13598, note = "Stormpike Explosives Expert" },
				} },
				{ title = "Back in Frostwolf Village", only = { factions = { "Horde" } }, zone = 1459, goals = {
					{ kind = "turnin", quest = 7224 },
					{ kind = "turnin", quest = 7281 },
					{ kind = "turnin", quest = 7302 },
