					{ kind = "turnin", quest = 8369 },
				} },
				{ title = "Frostwolf Clan to Friendly", tip = "Voggah Deathgrip by the gate wants Vanndar Stormpike dead: win a game in which your team kills him. Then he lets you pick a weapon (Hero of the Frostwolf).", only = { factions = { "Horde" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7142, optional = true, note = "The Battle for Alterac, 200" },
					{ kind = "turnin", quest = 7142, optional = true },
					{ kind = "accept", quest = 8272, optional = true },
					{ kind = "turnin", quest = 8272, optional = true, note = "Hero of the Frostwolf, 10 and a weapon" },
					{ kind = "rep", factionId = 729, standing = "Friendly" },
				} },
				{ title = "Rise and Be Recognized", tip = "Friendly lets Warmaster Laggrond upgrade your insignia: 100 reputation. Friendly to Honored is 6000 reputation. In Classic a full win paid 300 to 700 with its 3 marks; the Warbringer keeps taking 3 marks for 100. Inside, Master Ryson's All Seeing Eye (75, from the Winterax caves) repeats every game; The Legend of Korrak (200, when he appears in the middle of the valley) goes back to Warmaster Laggrond here. Friendly opens the Frostwolf Battle Tabard (1g) and the Superior Healing and Mana Draughts (5s) at Jekyll Flandring beside him.", only = { factions = { "Horde" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7163 },
					{ kind = "turnin", quest = 7163 },
					{ kind = "buy", npc = 13219, item = 19031, note = "Frostwolf Battle Tabard, 1g" },
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: Invaders of Alterac Valley again, 100 for 3 marks" },
					{ kind = "rep", factionId = 729, standing = "Honored" },
				} },
				{ title = "Honored Amongst the Clan", tip = "Honored: insignia rank 3, 100 reputation. Honored to Revered is 12000 reputation. Jekyll Flandring beside Warmaster Laggrond sells the Frostwolf Legionnaire's and Advisor's Cloaks and Pendants (about 7g each), the Frostwolf belts (5g9s to 7g66s) and the Major Healing and Mana Draughts (10s).", only = { factions = { "Horde" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7164 },
					{ kind = "turnin", quest = 7164 },
					{ kind = "talk", npc = 13219, optional = true, note = "Jekyll Flandring" },
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: 100 for 3 marks" },
					{ kind = "rep", factionId = 729, standing = "Revered" },
				} },
				{ title = "Earned Reverence", tip = "Revered: insignia rank 4, 150 reputation. Revered to Exalted is 21000 reputation, half the climb. Revered opens the weapons at Jekyll Flandring: Glacial Blade, Whiteout Staff and Frostbite (31g53s to 39g71s), and the Frostwolf Battle Standard (5g). At 51 and up For Great Honor (3 marks each from Alterac Valley, Arathi Basin and Warsong Gulch) pays 200 the first time and 150 after, plus reputation for the other two battlegrounds.", only = { factions = { "Horde" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 7165 },
					{ kind = "turnin", quest = 7165 },
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: For Great Honor" },
					{ kind = "talk", npc = 13219, optional = true, note = "Jekyll Flandring: Revered rewards" },
					{ kind = "rep", factionId = 729, standing = "Exalted" },
				} },
				{ title = "Legendary Heroes", tip = "Exalted gives the Legacy Point \"Master of Alterac Valley\" and the last two insignia, 400 reputation that no longer counts for anything but the insignia. Jekyll Flandring sells the Horn of the Frostwolf Howler (200g, level 60; its own guide), Don Julio's Band and Don Rodrigo's Band (75g56s), The Unstoppable Force (156g49s), The Immovable Object (79g53s), The Lobotomizer (125g66s) and the 50g tomes and off-hands.", only = { factions = { "Horde" } }, zone = 1416, goals = {
