			id = "forever/reputation/arathi-basin", title = "Arathi Basin Reputation", category = "Reputation", folder = "Reputation · Battlegrounds", levels = { 20, 60 }, zone = 1417, version = 1, revision = "c8e54f5445287d2be98e491243fd03455f5e58de9759588cdbfec55af2bae344", legacyRevision = "5e57510e276f978d1df903653ba036f291e277cb9b2757989ce9799bb00b22a9", keywords = { "The League of Arathor", "The Defilers", "Arathi Basin", "Refuge Pointe", "Hammerfall", "Field Marshal Oslight", "Sergeant Maclear", "Samuel Hawke", "Deathmaster Dwire", "Deathstalker Mortis", "Rutherford Twing", "Arathi Basin Mark of Honor", "Control Five Bases", "Take Five Bases", "Arathor Battle Tabard", "Battle Tabard of the Defilers", "Ironbark Staff", "Master of Arathi Basin", "Legacy Point" }, collects = { 20132, 20131 }, rewards = { { text = "Master of Arathi Basin: a Legacy Point at Exalted" }, { item = 20069 }, { item = 20132 }, { item = 20131 } }, why = "Every 200 resources your team gathers pays it; Exalted gives a Legacy Point, epic shoulders and the tabard.",
			steps = {
				{ title = "Refuge Pointe", tip = "Arathi Basin is a 15 against 15 battle over five bases, from level 20: hold bases to gather resources, and the first team to 2000 wins. Queue at any battlemaster in the capitals or from the battleground screen. In Classic every 200 resources your team gathers pay everyone 10 reputation, so a win pays 100 and a close loss nearly as much; a game also pays 3 Arathi Basin Marks of Honor for a win, 1 for a loss. The three quests here pay 500 reputation together (200, 200 and 100), once. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Alliance" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1417, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8105, note = "Field Marshal Oslight: assault four bases, 200" },
					{ kind = "accept", quest = 8080, note = "Sergeant Maclear: one mark, 200" },
					{ kind = "accept", quest = 8395, note = "Alliance Brigadier General: three marks, 100" },
				} },
				{ title = "Arathi Basin", tip = "Assaulting a base means clicking its banner until it turns: you need not hold it. Four marks in all: one for Sergeant Maclear, three for the Brigadier General. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Arathi Basin marks: hand in or spend them before you reach that.", only = { factions = { "Alliance" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1461, goals = {
					{ kind = "interact", quest = 8105, objective = 1, object = 180091, text = "Assault the Mine banner" },
					{ kind = "interact", quest = 8105, objective = 2, object = 180090, text = "Assault the Lumber Mill banner" },
					{ kind = "interact", quest = 8105, objective = 3, object = 180088, text = "Assault the Blacksmith banner" },
					{ kind = "interact", quest = 8105, objective = 4, object = 180089, text = "Assault the Farm banner" },
					{ kind = "collect", quest = 8080, objective = 1, item = 20559, map = 1461, x = 46.2, y = 45.4, note = "one Arathi Basin Mark of Honor" },
					{ kind = "collect", quest = 8395, objective = 1, item = 20559, count = 3, map = 1461, x = 46.2, y = 45.4, note = "three more marks" },
				} },
				{ title = "Back to Refuge Pointe", only = { factions = { "Alliance" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1417, goals = {
					{ kind = "turnin", quest = 8395, note = "hand in the three marks first" },
					{ kind = "turnin", quest = 8080 },
					{ kind = "turnin", quest = 8105 },
				} },
				{ title = "League of Arathor to Friendly", tip = "Neutral to Friendly is 3000 reputation. In Classic a win paid 100 and its 3 marks bring 50 more at the Brigadier General (Claiming Arathi Basin, again and again): about 150 a win, some 20 wins. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50 the quests at Refuge Pointe come in a version for your bracket (from level 20): 200 for assaulting the bases, 200 for one mark, then 100 and 50 per 3 marks at the Brigadier General.", only = { factions = { "Alliance" } }, zone = 1417, goals = {
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: Claiming Arathi Basin again, 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 509, standing = "Friendly" },
				} },
				{ title = "Control Four Bases", tip = "At level 60 and Friendly, Field Marshal Oslight asks your team to hold four bases at the same time: 200 reputation, once. It opens Control Five Bases for Exalted.", only = { factions = { "Alliance" } }, when = { { level = 60, test = "level", op = ">=" } }, zone = 1417, goals = {
