					{ kind = "turnin", quest = 8114 },
				} },
				{ title = "League of Arathor to Honored", tip = "Friendly to Honored is 6000 reputation, about 40 wins at the Classic rate. Friendly opens the first rewards at Samuel Hawke beside Field Marshal Oslight: the Talisman of Arathor trinket for levels 28, 38, 48 and 58 (72s to 4g12s), and food and bandages that work in Arathi Basin (10s to 20s). He also gives one Arathor care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages.", only = { factions = { "Alliance" } }, zone = 1417, goals = {
					{ kind = "talk", npc = 15127, optional = true, note = "Samuel Hawke: Friendly rewards" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 509, standing = "Honored" },
				} },
				{ title = "League of Arathor to Revered", tip = "Honored to Revered is 12000 reputation, about 80 wins. Honored opens the Highlander's belts in plate, lamellar, chain, mail, leather, lizardhide and cloth for levels 28 to 58 (72s to 8g84s).", only = { factions = { "Alliance" } }, zone = 1417, goals = {
					{ kind = "talk", npc = 15127, optional = true, note = "Samuel Hawke: Honored rewards" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 509, standing = "Revered" },
				} },
				{ title = "League of Arathor to Exalted", tip = "Revered to Exalted is 21000 reputation, about 140 wins: half of the whole climb. Revered opens the Highlander's boots and greaves for levels 28 to 58 (1g7s to 13g65s), the ones with the run-speed bonus.", only = { factions = { "Alliance" } }, zone = 1417, goals = {
					{ kind = "talk", npc = 15127, optional = true, note = "Samuel Hawke: Revered rewards" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 509, standing = "Exalted" },
				} },
				{ title = "Samuel Hawke", tip = "Exalted gives the Legacy Point \"Master of Arathi Basin\" and opens the epics: the level 60 Highlander's shoulders in every armor type (12g33s to 18g50s), Cloak of the Honor Guard (12g14s), Ironbark Staff (55g10s) and Sageclaw (44g24s), both from level 55.", only = { factions = { "Alliance" } }, zone = 1417, goals = {
