		{
			id = "forever/reputation/argent-dawn", title = "Argent Dawn Reputation", category = "Reputation", folder = "Reputation · World", levels = { 50, 60 }, zone = 1422, version = 1, revision = "637b8c13a56a96717c5621e12affe753f63acea579724726ee49ac4ceb9fc274", legacyRevision = "7e3e7c527b170829974d4a5c0be815ac5f1a25006dcaebc4d76c5475128141f2", keywords = { "Argent Dawn", "Argent Dawn Commission", "Scourgestones", "Minion's Scourgestone", "Invader's Scourgestone", "Corruptor's Scourgestone", "Argent Dawn Valor Token", "Mantles of the Dawn", "Chromatic Mantle of the Dawn", "Light's Hope Chapel", "Chillwind Camp", "The Bulwark", "Quartermaster Miranda Breechlock", "Argent Quartermaster Lightspark", "Argent Quartermaster Hasana", "Scholomance", "Stratholme", "Enchant Bracer", "Argent Boots", "Gloves of the Dawn" }, rewards = { { item = 18182 }, { item = 18169, choice = true }, { item = 18170, choice = true }, { item = 18171, choice = true }, { item = 18172, choice = true }, { item = 18173, choice = true }, { text = "Recipes for Tailors, Leatherworkers, Blacksmiths, Enchanters and Alchemists from Honored and Revered" } }, why = "Scourgestones, Scholomance and Stratholme: the shoulder resistance enchants and a dozen recipes.",
			steps = {
				{ title = "Argent Dawn Commission (Alliance)", tip = "Argent Officer Pureheart stands in Chillwind Camp, in the south of the Western Plaguelands. The Argent Dawn starts at Neutral 200 for everyone. Wear the Commission trinket while you fight the Scourge: Scourgestones only drop while you wear it. Duke Nicholas Zverenhoff at Light's Hope Chapel gives the same Commission; you can only take one.", only = { factions = { "Alliance" } }, zone = 1422, goals = {
					{ kind = "accept", quest = 5401 },
					{ kind = "turnin", quest = 5401 },
				} },
				{ title = "Argent Dawn Commission (Horde)", tip = "Argent Officer Garush stands at the Bulwark, on the road from Tirisfal Glades into the Western Plaguelands. The Argent Dawn starts at Neutral 200 for everyone. Wear the Commission trinket while you fight the Scourge: Scourgestones only drop while you wear it. Duke Nicholas Zverenhoff at Light's Hope Chapel gives the same Commission; you can only take one.", only = { factions = { "Horde" } }, zone = 1420, goals = {
					{ kind = "accept", quest = 5405 },
					{ kind = "turnin", quest = 5405 },
				} },
				{ title = "Neutral to Friendly: Scourge of the Western Plaguelands", tip = "Every Scourge kill in the Plaguelands gives 5 reputation (named ones 15), from the level 50 ghouls and skeletons up; at level 60 pick the level 53 and up ones, since in Classic grey mobs give only about a fifth. Neutral to Friendly is 2,800: about 560 kills, fewer with the Plaguelands quests on the way. The densest Scourge stand around the four Scourge Cauldrons: Felstone Field west of Andorhal (skeletons, 50-53), Dalson's Tears north of Andorhal (zombies and ghouls, 52-55), the Writhing Haunt in the south (ghouls, 54-55) and Gahrron's Withering in the east (ghosts, 56-57). Keep every Scourgestone and every quest you can save: turn-ins never stop counting, kills do. Minion's Scourgestones drop from about four in ten of these Scourge, Invader's from about a third of the level 56 and up ones. If you die, take the Commission off and put it back on: it can lose its effect. Paladins (Human and Dwarf): Commander Ashlam Valorfist at Chillwind Camp asks 20 Minion's Scourgestones once for Dispelling Evil, 100 reputation instead of 25. The Legacy perk Diplomat adds up to 10% to every gain.", zone = 1422, goals = {
					{ kind = "collect", item = 12840, count = 20, nearest = true, optional = true, note = "Minion's Scourgestones: keep them" },
					{ kind = "kill", npc = 1802, map = 1422, x = 60.7, y = 58.3, optional = true, note = "Hungering Wraiths at Gahrron's Withering; any Scourge counts" },
					{ kind = "kill", npc = 1794, optional = true, note = "Soulless Ghouls at the Writhing Haunt" },
					{ kind = "rep", factionId = 529, standing = "Friendly" },
				} },
				{ title = "Plaguelands quests and the Scourge Cauldrons", tip = "The Plaguelands quests pay in full at 60 from level 55 up and never stop counting, about 1,500 in all; the leveling guides walk them. The cauldron chain from High Priestess MacDonnell at Chillwind Camp (Horde: Shadow Priestess Vandis at the Bulwark): 150 per cauldron with its return, then Mission Accomplished! 200. Alas, Andorhal 150 (Araj the Summoner, elite). At Light's Hope Chapel, Carlin Redpath's Darrowshire quests (Brother Carlin 50 from Chromie in Andorhal, Villains of Darrowshire 100, Marauders of Darrowshire 100) and Pamela Redpath's Hidden Treasures 200 at the end of the Darrowshire story; Zaeldarr the Outcast 75 from Caretaker Alen. After Mission Accomplished!, each cauldron takes a repeatable delivery: 25 reputation every time, until Exalted. Alchemist Arbington at Chillwind Camp (Horde: Apothecary Dithers at the Bulwark) gives you a Vitreous Focuser, without which the reagents never drop, and sells Arcane Quickeners for 50 silver (one per delivery; it crumbles after 30 minutes, so buy it last). Each delivery also takes 4 Runecloth. Farm Gahrron's Withering: its ghosts drop an Ectoplasmic Resonator about one time in four, so about 16 kills fill a delivery; the other cauldrons want 5 or 6 reagents that drop one time in ten or less. Once the Plaguelands Scourge stop counting, this earns about four times what their Scourgestones alone do.", zone = 1422, goals = {
					{ kind = "talk", npc = 11056, optional = true, only = { factions = { "Alliance" } }, note = "Alchemist Arbington: ask for a Vitreous Focuser" },
					{ kind = "talk", npc = 11057, mapHint = 1420, optional = true, only = { factions = { "Horde" } }, note = "Apothecary Dithers, at the Bulwark: ask for a Vitreous Focuser" },
					{ kind = "collect", item = 13354, count = 4, optional = true, note = "Ectoplasmic Resonators: the ghosts around the cauldron" },
					{ kind = "collect", item = 14047, count = 4, optional = true, note = "Runecloth" },
					{ kind = "buy", npc = 11056, item = 13320, optional = true, only = { factions = { "Alliance" } }, note = "Arcane Quickener, 50 silver" },
					{ kind = "buy", npc = 11057, item = 13320, mapHint = 1420, optional = true, only = { factions = { "Horde" } }, note = "Arcane Quickener, 50 silver" },
					{ kind = "turnin", quest = 5227, optional = true, direct = true, note = "the cauldron at Gahrron's Withering: handed in from its window, never in the log" },
				} },
				{ title = "Light's Hope Chapel quests", tip = "Light's Hope Chapel, on the east side of the Eastern Plaguelands, is the Argent Dawn's home: Duke Nicholas Zverenhoff, Betina Bigglezink and Leonid Barthalomew give its dungeon quests, 100 to 200 reputation each and about 1,700 in all. They are group quests for Stratholme and Scholomance (level 58-60, five players): take the ones your group will run. The Duke's chain ends at the Argent Hold, a chest of Argent Dawn gear.", zone = 1423, goals = {
					{ kind = "level", level = 55 },
					{ kind = "accept", quest = 5212, optional = true, note = "The Flesh Does Not Lie: Betina Bigglezink" },
					{ kind = "accept", quest = 5529, optional = true, note = "Plagued Hatchlings: Betina Bigglezink" },
					{ kind = "accept", quest = 5243, optional = true, note = "Houses of the Holy: Leonid Barthalomew" },
					{ kind = "accept", quest = 5251, optional = true, note = "The Archivist: Duke Nicholas Zverenhoff" },
				} },
				{ title = "Stratholme", tip = "Stratholme is a group of five at the north end of the Eastern Plaguelands. Its Scourge give 5 reputation a kill up to the last point of Honored, and its Scourge bosses 25 until Exalted (Baron Rivendare 50), each with a Corruptor's Scourgestone. The Black Guard Sentries by the Baron give 5 until Exalted. The Scourge side, through the service entrance, pays far more than the Scarlet side.", zone = 1423, goals = {
					{ kind = "goto", label = "Stratholme", map = 1423, x = 26.5, y = 10.4, frame = "live" },
					{ kind = "collect", quest = 5212, objective = 1, item = 13174, count = 10, map = 1423, x = 26.5, y = 10.4, frame = "live", group = 5, note = "Plagued Flesh Samples: the Scourge inside" },
					{ kind = "collect", quest = 5243, objective = 1, item = 13180, count = 5, map = 1423, x = 26.5, y = 10.4, frame = "live", group = 5, note = "Stratholme Holy Water: the supply crates" },
					{ kind = "kill", quest = 5251, objective = 1, npc = 10811, map = 1423, x = 26.5, y = 10.4, frame = "live", group = 5, note = "Archivist Galford, Scarlet side" },
				} },
				{ title = "Scholomance", tip = "Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands; your side's Scholomance quests give the Skeleton Key that opens it. It is the best Argent Dawn run: its mobs give 5 up to the last point of Honored, and its thirteen bosses about 375 reputation a full clear plus ten or so Corruptor's Scourgestones (about 250 more). Ras Frostwhisper and Darkmaster Gandling give 50 each.", zone = 1422, goals = {
					{ kind = "goto", label = "Scholomance", map = 1422, x = 69.7, y = 73.2 },
					{ kind = "kill", quest = 5529, objective = 1, npc = 10678, count = 20, map = 1422, x = 69.7, y = 73.2, group = 5, note = "Plagued Hatchlings, in the hatchery" },
				} },
				{ title = "Back at Light's Hope Chapel", tip = "The Flesh Does Not Lie leads to The Active Agent (the Scourge Data in a Stratholme ziggurat), which rewards the Seal of the Dawn or the Rune of the Dawn: better trinkets that also make Scourgestones drop, so they can replace the Commission. The Archivist leads on to the Head of Balnazzar and Baron Rivendare. A Healthy Dragon Scale, a rare drop (about 6%) from the Plagued Hatchlings once Plagued Hatchlings is done, starts a quest worth 50 each time: keep them until Revered. Tinkee Steamboil in the Burning Steppes, at the end of her Blackrock Spire quests, sends you to Leonid Barthalomew (75) and on to Betina's Dawn's Gambit in Scholomance (25 and 200).", zone = 1423, goals = {
					{ kind = "turnin", quest = 5212 },
					{ kind = "accept", quest = 5213, optional = true },
					{ kind = "turnin", quest = 5529 },
					{ kind = "turnin", quest = 5243 },
					{ kind = "turnin", quest = 5251 },
				} },
				{ title = "Friendly to Honored: stones and named Scourge", tip = "Normal Scourge outside the dungeons stop giving reputation halfway through Friendly (3,000 of 6,000); Lord Darkscythe, Hed'mush and Gish stop at the end of Friendly. After that only Araj, the Scholomance and Stratholme mobs, the cauldron deliveries and Scourgestones count. Now turn in the stones you saved: Duke Nicholas Zverenhoff at Light's Hope Chapel takes all three kinds, and so do the officers at Chillwind Camp and the Bulwark. Every turn-in pays 25 and an Argent Dawn Valor Token: keep 35 tokens for the mantles at Revered and Exalted. Invader's Scourgestones are worth twice as much per stone: the Dark Adepts, Shadowmages, Dread Weavers and Scourge Champions (level 58-60) at Northdale, just north of Light's Hope Chapel, drop them about a third of the time or more, next to the turn-in. The named Scourge below drop a Corruptor's Scourgestone half the time or more (Putridius two times in three, Araj and Hed'mush half the time) and give 15 a kill, Araj until Exalted; Putridius gives no reputation, only the stone. Friendly opens the Enriched Manna Biscuits (60 silver) at the quartermasters.", zone = 1423, goals = {
					{ kind = "collect", item = 12841, count = 10, nearest = true, optional = true, note = "Invader's Scourgestones" },
					{ kind = "collect", item = 12843, count = 1, optional = true, note = "Corruptor's Scourgestone: the named Scourge below, and dungeon bosses" },
					{ kind = "kill", npc = 8546, map = 1423, x = 73.6, y = 34.1, frame = "live", optional = true, note = "Dark Adepts and Shadowmages at Northdale" },
					{ kind = "kill", npc = 1852, optional = true, note = "Araj the Summoner, Andorhal" },
					{ kind = "kill", npc = 1850, optional = true, note = "Putridius, Western Plaguelands: the stone only" },
					{ kind = "kill", npc = 10826, optional = true, note = "Lord Darkscythe, Eastern Plaguelands" },
					{ kind = "kill", npc = 10821, optional = true, note = "Hed'mush the Rotting, Eastern Plaguelands" },
					{ kind = "kill", npc = 10825, optional = true, note = "Gish the Unmoving, Eastern Plaguelands" },
					{ kind = "turnin", quest = 5510, optional = true, direct = true, note = "Minion's Scourgestones: 20 for 25 reputation" },
					{ kind = "turnin", quest = 5509, optional = true, direct = true, note = "Invader's Scourgestones: 10 for 25 reputation" },
					{ kind = "turnin", quest = 5508, optional = true, direct = true, note = "Corruptor's Scourgestones: 1 for 25 reputation" },
					{ kind = "rep", factionId = 529, standing = "Honored" },
				} },
				{ title = "Honored to Revered: dungeons and stones", tip = "Honored to Revered is 12,000: about 2,400 Scholomance and Stratholme mobs, fewer with their bosses. Their mobs stop at 11,999 of 12,000 Honored; a boss or a turn-in takes you over. Solo, only Scourgestones, the cauldron deliveries and Araj count: 12,000 is 480 turn-ins, or 4,800 Invader's Scourgestones. Keep the stones you get in the dungeons until their mobs stop counting. Honored opens recipes at all three quartermasters: Quartermaster Miranda Breechlock at Light's Hope Chapel, Argent Quartermaster Lightspark at Chillwind Camp, Argent Quartermaster Hasana at the Bulwark. Also the Hallowed Brazier (133 gold) for the Three Kings of Flame quest.", zone = 1423, goals = {
					{ kind = "buy", npc = 11536, item = 19446, optional = true, note = "Formula: Enchant Bracer - Mana Regeneration, 3 gold" },
					{ kind = "buy", npc = 11536, item = 19216, optional = true, note = "Pattern: Argent Boots (Tailoring), 2 gold 20 silver" },
					{ kind = "buy", npc = 11536, item = 19328, optional = true, note = "Pattern: Dawn Treaders (Leatherworking), 2 gold 20 silver" },
					{ kind = "buy", npc = 11536, item = 19203, optional = true, note = "Plans: Girdle of the Dawn (Blacksmithing), 2 gold 20 silver" },
					{ kind = "buy", npc = 11536, item = 13482, optional = true, note = "Recipe: Transmute Air to Fire (Alchemy), 1 gold 50 silver" },
					{ kind = "buy", npc = 11536, item = 19442, optional = true, note = "Formula: Powerful Anti-Venom (First Aid), 10 gold" },
					{ kind = "turnin", quest = 5510, optional = true, direct = true },
					{ kind = "turnin", quest = 5509, optional = true, direct = true },
					{ kind = "turnin", quest = 5508, optional = true, direct = true },
					{ kind = "rep", factionId = 529, standing = "Revered" },
				} },
				{ title = "Mantles of the Dawn", tip = "At Revered, Quartermaster Miranda Breechlock takes 10 Argent Dawn Valor Tokens for Mantles of the Dawn (100 reputation). After it, any Argent Dawn quartermaster sells the five shoulder enchants for 10 gold each: Flame, Frost, Arcane, Nature and Shadow Mantle of the Dawn, +5 to that resistance. Revered also opens the Blessed Sunfruit and its juice (60 silver) and the Revered recipes.", zone = 1423, goals = {
					{ kind = "collect", item = 12844, count = 10, map = 1423, x = 71.6, y = 50.1, optional = true, note = "Argent Dawn Valor Tokens, from the stone turn-ins" },
					{ kind = "accept", quest = 5513 },
					{ kind = "turnin", quest = 5513 },
					{ kind = "buy", npc = 11536, item = 18170, optional = true, note = "Frost Mantle of the Dawn: pick the resistance you need, 10 gold" },
					{ kind = "buy", npc = 11536, item = 19447, optional = true, note = "Formula: Enchant Bracer - Healing, 6 gold" },
					{ kind = "buy", npc = 11536, item = 19217, optional = true, note = "Pattern: Argent Shoulders (Tailoring), 4 gold" },
					{ kind = "buy", npc = 11536, item = 19329, optional = true, note = "Pattern: Golden Mantle of the Dawn (Leatherworking), 4 gold" },
					{ kind = "buy", npc = 11536, item = 19205, optional = true, note = "Plans: Gloves of the Dawn (Blacksmithing), 4 gold" },
				} },
				{ title = "Revered to Exalted", tip = "Revered to Exalted is 21,000: 840 Scourgestone or cauldron turn-ins, or the dungeon bosses with their Corruptor's Scourgestones (a full Scholomance clear is about 600). Turn in every stone and Healthy Dragon Scale you saved.", zone = 1423, goals = {
					{ kind = "turnin", quest = 5510, optional = true, direct = true },
					{ kind = "turnin", quest = 5509, optional = true, direct = true },
					{ kind = "turnin", quest = 5508, optional = true, direct = true },
					{ kind = "rep", factionId = 529, standing = "Exalted" },
				} },
				{ title = "Chromatic Mantle of the Dawn", tip = "At Exalted, Quartermaster Miranda Breechlock takes 25 Argent Dawn Valor Tokens for the Chromatic Mantle of the Dawn (150 reputation): +5 to every resistance, on your shoulders. After it, the quartermasters sell more for 40 gold each.", zone = 1423, goals = {
					{ kind = "collect", item = 12844, count = 25, map = 1423, x = 71.6, y = 50.1, optional = true, note = "Argent Dawn Valor Tokens" },
					{ kind = "accept", quest = 5517 },
					{ kind = "turnin", quest = 5517 },
				} },
			},
		},
		{
			id = "forever/reputation/bloodsail-buccaneers", title = "Bloodsail Buccaneers Reputation", category = "Reputation", folder = "Reputation · World", levels = { 55, 60 }, zone = 1434, next = "forever/reputation/steamwheedle-cartel", version = 1, revision = "35ad1a69f5f954cc4cc6746d26624223e4e624c248a9e074c9830fadbf8edbab", keywords = { "Bloodsail Buccaneers", "pirates", "Booty Bay", "Booty Bay Bruiser", "Fleet Master Firallon", "Crimson Veil", "Pretty Boy Duncan", "Dressing the Part", "Avast Ye Scallywag", "Avast Ye Admiral", "Bloodsail Admiral's Hat", "Buccaneer's Uniform", "Bloodsail Shirt", "Baron Revilgaz", "Fleet Master Seahorn", "Steamwheedle Cartel", "at war" }, rewards = { { item = 12185 }, { item = 22746 } }, why = "The pirate outfit and the Admiral's Hat, bought with a war against Booty Bay and every goblin town.",
			steps = {
				{ title = "Before you start", tip = "Bloodsail standing goes up only by killing the people of Booty Bay, and every kill costs you Booty Bay 125 and the other goblin towns (Gadgetzan, Ratchet, Everlook, and in Forever likely Powderfuse) about 62 each. After the Bruisers this guide asks for, every goblin town is Hated: their guards attack you, and you lose their flight masters, inns, vendors and Gadgetzan's and Everlook's auction houses. Getting back takes longer than getting here (last step). Fly in, bind elsewhere, and do your goblin-town business first. The outfit and the hat need only Friendly; past that Bloodsail has nothing to give. Booty Bay's guards are not your enemies yet: tick At War for Booty Bay in your reputation panel, then attack.", zone = 1434, goals = {
					{ kind = "goto", label = "Booty Bay", map = 1434, x = 27, y = 77.1 },
				} },
				{ title = "Booty Bay Bruisers to Neutral", tip = "Look at your Bloodsail bar first. A new character starts Hated, 500 short of Hostile: 260 Bruisers to Neutral, at 25 each. But every Booty Bay quest you did while leveling took five times its Booty Bay reward off Bloodsail (An OOX of Your Own, Stranglethorn Fever and Facing Negolash 1,000 each), and every Bloodsail pirate you killed 25 more: after Booty Bay's quests you sit near the bottom of Hated, up to 1,680 Bruisers from Neutral. Divide what the bar still lacks to Hostile, plus 6,000, by 25. Bruisers (level 57) hit hard, net you and knock you back, and new ones come when a goblin calls for help. Fight on the path that turns left from the tunnel up to the blacksmith's house: two Bruisers patrol it and rarely meet. Once they are down, step into the house (or hit one of the goblins inside) and a fresh Bruiser comes running. Players manage 30 to 40 an hour. Booty Bay is Hated after about 53 Bruisers from a fresh Neutral 500. At the New Year celebration the town's goblins are drunk and do not fight back. The Blackwater crew at Faldir's Cove in the Arathi Highlands (level 37-40) are easier but pay only 5 each. Do not kill Bloodsail pirates: each costs 25.", zone = 1434, goals = {
					{ kind = "goto", label = "the path to the smithy", map = 1434, x = 29, y = 75.6 },
					{ kind = "kill", npc = 4624, optional = true, note = "Booty Bay Bruiser: +25" },
					{ kind = "rep", factionId = 87, standing = "Neutral" },
				} },
				{ title = "Dressing the Part", tip = "At Neutral the Bloodsail crew stop attacking you. Fleet Master Firallon is aboard the Crimson Veil, the pirate ship anchored south of Booty Bay, on its middle deck. Swim out; take the quest and hand it in on the spot for the Buccaneer's Uniform: the Bloodsail Shirt, Sash, Pants and Boots.", zone = 1434, goals = {
					{ kind = "accept", quest = 9272 },
					{ kind = "turnin", quest = 9272, rewards = { { item = 22746 } }, note = "Fleet Master Firallon: the Buccaneer's Uniform" },
				} },
				{ title = "Bruisers to Friendly", tip = "Neutral to Friendly is 3,000 more: 120 Bruisers. Friendly is the last standing that unlocks anything.", zone = 1434, goals = {
					{ kind = "goto", label = "the path to the smithy", map = 1434, x = 29, y = 75.6 },
					{ kind = "kill", npc = 4624, optional = true, note = "Booty Bay Bruiser: +25" },
					{ kind = "rep", factionId = 87, standing = "Friendly" },
				} },
				{ title = "Avast Ye, Scallywag", tip = "\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of Booty Bay. Booty Bay players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while Booty Bay is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with Booty Bay.", zone = 1434, goals = {
					{ kind = "accept", quest = 1036, note = "\"Pretty Boy\" Duncan" },
					{ kind = "turnin", quest = 1036, note = "Fleet Master Firallon, on the Crimson Veil: 25" },
					{ kind = "accept", quest = 4621 },
				} },
				{ title = "Avast Ye, Admiral!", tip = "Baron Revilgaz and Fleet Master Seahorn stand on the top floor of the Booty Bay inn, out on the balcony. Both are level 60 and Bruisers come to their aid: clear the stairs first and pull them one at a time. They come back, so a friend can kill them too.", zone = 1434, goals = {
					{ kind = "kill", quest = 4621, objective = 1, npc = 2496, note = "Baron Revilgaz" },
					{ kind = "kill", quest = 4621, objective = 2, npc = 2487, note = "Fleet Master Seahorn" },
				} },
				{ title = "The Admiral's Hat", tip = "Back to Firallon for the Bloodsail Admiral's Hat (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less Booty Bay. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the Badlands, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached.", zone = 1434, goals = {
					{ kind = "turnin", quest = 4621, rewards = { { item = 12185 } }, note = "Fleet Master Firallon: Bloodsail Admiral's Hat" },
				} },
				{ title = "The way back", tip = "Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside Ratchet, Booty Bay, Gadgetzan and Everlook, so the climb back is the Cartel's own: Zorbin Fandazzle in Feralas serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give Booty Bay 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did.", zone = 1444, goals = {
					{ kind = "talk", npc = 14637, optional = true, note = "Zorbin Fandazzle: Zapped Giants, open to the Hated" },
				} },
			},
		},
		{
			id = "forever/reputation/brood-of-nozdormu", title = "Brood of Nozdormu Reputation", category = "Reputation", folder = "Reputation · Raids and dungeons", levels = { 60, 60 }, zone = 1451, version = 1, revision = "1542d46d6e8d9783dd45d6ef2887aaa8a2f69f6eb3f13475cdf73ee8f6ececa6", keywords = { "Brood of Nozdormu", "Bronze Dragonflight", "Anachronos", "Caverns of Time", "Baristolth", "Scepter of the Shifting Sands", "Silithid Carapace Fragment", "Hand of the Righteous", "Signet Ring of the Bronze Dragonflight", "Path of the Protector", "Path of the Conqueror", "Path of the Invoker", "Ahn'Qiraj", "Ancient Qiraji Artifact", "Qiraji Lord's Insignia", "Mortal Champions", "Secrets of the Qiraji", "Andorgos", "Kandrostrasz", "Narain Soothfancy", "Scarab Gong" }, rewards = { { item = 21200, choice = true }, { item = 21205, choice = true }, { item = 21210, choice = true }, { text = "The Scepter of the Shifting Sands quest chain" } }, why = "The Bronze Dragonflight's ring, upgraded at every standing; a long climb from Hated, mostly in raids.",
			steps = {
				{ title = "Baristolth in Cenarion Hold", tip = "The Brood of Nozdormu is not in your reputation list until you meet Anachronos. Baristolth of the Shifting Sands, in the main building of Cenarion Hold, sends you to him. Meeting him sets you at Hated, 0 of 36,000: Neutral is 42,000 reputation away, and almost all of it comes from raids. Blackwing Lair and the Temple of Ahn'Qiraj are not among the first raids Blizzard has announced for Forever: until one of them opens, the 100 from Baristolth's first quest is all the Brood reputation there is. The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it.", zone = 1451, goals = {
					{ kind = "getfp", place = "Cenarion Hold" },
					{ kind = "accept", quest = 8286, note = "Baristolth of the Shifting Sands" },
				} },
				{ title = "Anachronos at the Caverns of Time", tip = "Anachronos, a bronze dragon in elf form, stands at the mouth of the Caverns of Time in eastern Tanaris, south-east of Gadgetzan. Walk up to him.", zone = 1446, goals = {
					{ kind = "complete", quest = 8286, map = 1446, x = 65.3, y = 50, note = "Meet Anachronos" },
				} },
				{ title = "Back to Baristolth", tip = "Only One May Rise wants the head of Broodlord Lashlayer, the third boss of Blackwing Lair (a 40-player raid in Blackrock Mountain). Everything after it needs the head, the fragment turn-ins included: until you have it, What Tomorrow Brings is all the Brood reputation there is, solo or not.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8286, note = "100" },
					{ kind = "accept", quest = 8288, optional = true },
				} },
				{ title = "Broodlord Lashlayer", tip = "Blackwing Lair is a 40-player raid at the top of Blackrock Mountain. Broodlord Lashlayer always drops his head.", zone = 1428, goals = {
					{ kind = "collect", quest = 8288, objective = 1, item = 20383, map = 1428, x = 32.5, y = 32.4, optional = true, note = "Head of the Broodlord Lashlayer: raid of 40" },
				} },
				{ title = "The Path of the Righteous", tip = "The Path of the Righteous wants 200 Silithid Carapace Fragments. Every hive silithid drops one to three on most kills: the Hive'Ashi Workers, Stingers, Swarmers and Defenders north and north-west of Cenarion Hold, and those of Hive'Zora in the west and Hive'Regal in the south. Almost all of them are elites of level 57 to 60: one at a time solo, faster in a group.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8288, optional = true, note = "200" },
					{ kind = "accept", quest = 8301, optional = true },
					{ kind = "collect", quest = 8301, objective = 1, item = 20384, count = 200, optional = true, note = "Silithid Carapace Fragment" },
					{ kind = "turnin", quest = 8301, optional = true, note = "200" },
				} },
				{ title = "Hated to Neutral", tip = "After The Path, Baristolth takes 200 more fragments for The Hand of the Righteous: 200 reputation, again and again, but only until Neutral. From Hated 500 that is 208 turn-ins, 41,600 fragments, 20,000 to 30,000 elite kills: the only way without the Temple, and a very long one. With the Temple of Ahn'Qiraj open (a 40-player raid) it is far quicker: every Temple trash mob gives 100 until 2,999 of 3,000 Neutral, about 9,500 a full clear, so four to five clears reach Neutral. Save every Ancient Qiraji Artifact and Qiraji Lord's Insignia you loot until the trash stops counting: they pay the same later.", zone = 1451, goals = {
					{ kind = "collect", item = 20384, count = 200, optional = true, note = "Silithid Carapace Fragment" },
					{ kind = "turnin", quest = 8302, optional = true, direct = true, note = "The Hand of the Righteous: 200 fragments, 200" },
					{ kind = "rep", factionId = 910, standing = "Neutral" },
				} },
				{ title = "Anachronos's quests", tip = "Neutral opens the rest of the Scepter of the Shifting Sands chain. Baristolth sends you back to Anachronos.", zone = 1451, goals = {
					{ kind = "accept", quest = 8303, note = "Baristolth of the Shifting Sands" },
				} },
				{ title = "Long Forgotten Memories", zone = 1446, goals = {
					{ kind = "turnin", quest = 8303, note = "Anachronos: 200" },
					{ kind = "accept", quest = 8305 },
				} },
				{ title = "The Crystalline Tear", tip = "The Crystalline Tear is a small red crystal on the ground just outside the gates of Ahn'Qiraj, in the far south-west of Silithus. Click it, then stay and watch the vision of the War of the Shifting Sands to its end. If it is cut short, abandon the quest and click the Tear again.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8305, note = "Crystalline Tear: 50" },
					{ kind = "accept", quest = 8519 },
					{ kind = "complete", quest = 8519, map = 1451, x = 28.7, y = 89.1, note = "Watch the vision" },
				} },
				{ title = "The Charge of the Dragonflights", tip = "Anachronos now offers the Signet Ring of the Bronze Dragonflight in three kinds: the Path of the Protector (tanks), of the Conqueror (melee fighters) or of the Invoker (casters). Take one: the other two close. Each standing from Friendly to Exalted brings an upgrade of the same ring, 100 reputation each. The Charge of the Dragonflights sends you after the three shards of the Scepter of the Shifting Sands.", zone = 1446, goals = {
					{ kind = "turnin", quest = 8519, note = "100" },
					{ kind = "accept", quest = 8555 },
					{ kind = "turnin", quest = 8555, note = "10" },
					{ kind = "talk", npc = 15192, optional = true, note = "Pick one: The Path of the Protector, the Conqueror or the Invoker, 100" },
				} },
				{ title = "The red shard: Vaelastrasz", tip = "The red shard: Vaelastrasz the Corrupt, the second boss of Blackwing Lair, gives Nefarius's Corruption before his fight; Nefarian, the last boss, drops the Red Scepter Shard for one raider on the quest each kill. The quest lasts five hours.", zone = 1428, goals = {
					{ kind = "accept", quest = 8730, map = 1428, x = 32.5, y = 32.4, optional = true, note = "Vaelastrasz the Corrupt, Blackwing Lair: raid of 40" },
					{ kind = "collect", quest = 8730, objective = 1, item = 21138, map = 1428, x = 32.5, y = 32.4, optional = true, note = "Red Scepter Shard, Nefarian" },
				} },
				{ title = "The blue shard: Azuregos's ledger", tip = "The Spirit of Azuregos stands on the south coast of Azshara. His ledger starts Narain Soothfancy's long chain in Tanaris.", zone = 1447, goals = {
					{ kind = "accept", quest = 8575, optional = true, note = "Spirit of Azuregos" },
				} },
				{ title = "Narain Soothfancy", tip = "Narain Soothfancy, a goblin seer, lives in a hut north-east of Gadgetzan. He sends you three ways at once: to Stewvul's crate in Silverpine Forest, to an island off the south coast of Tanaris, and to Dirge Quikcleave in Gadgetzan.", zone = 1446, goals = {
					{ kind = "turnin", quest = 8575, optional = true, note = "10" },
					{ kind = "accept", quest = 8576, optional = true },
					{ kind = "turnin", quest = 8576, optional = true, note = "10" },
					{ kind = "accept", quest = 8577, optional = true },
					{ kind = "accept", quest = 8597, optional = true },
					{ kind = "accept", quest = 8584, optional = true },
				} },
				{ title = "Stewvul's crate", tip = "The Inconspicuous Crate leans on the Greymane Wall at the south end of Silverpine Forest, left of the closed gate.", zone = 1421, goals = {
					{ kind = "turnin", quest = 8577, optional = true, note = "Inconspicuous Crate: 10" },
					{ kind = "accept", quest = 8578, optional = true },
					{ kind = "collect", quest = 8578, objective = 1, item = 20951, map = 1421, x = 46.2, y = 86.7, optional = true, note = "Narain's Scrying Goggles" },
				} },
				{ title = "Meridith the Mermaiden", tip = "The Freshly Dug Dirt lies on the farther of two islands south of Land's End Beach, past the fatigue line. Meridith the Mermaiden, on the sea floor south of the beach's crashed gyrocopter, gives Love Song for Narain and a three-minute swim-speed blessing that gets you across.", zone = 1446, goals = {
					{ kind = "accept", quest = 8599, optional = true, note = "Meridith the Mermaiden" },
				} },
				{ title = "The island off Land's End Beach", zone = 947, goals = {
					{ kind = "turnin", quest = 8597, optional = true, note = "Freshly Dug Dirt: 10" },
					{ kind = "accept", quest = 8598, optional = true },
				} },
				{ title = "Back to Narain", tip = "Decoy! sends you, disguised with Narain's turban, to a drop-off point south of Everlook in Winterspring. Leave the bag of gold there: Number Two, a level 61 elite, comes for it (group of 3 to 5).", zone = 1446, goals = {
					{ kind = "turnin", quest = 8578, optional = true, note = "10" },
					{ kind = "turnin", quest = 8598, optional = true, note = "10" },
					{ kind = "turnin", quest = 8599, optional = true, note = "10" },
					{ kind = "accept", quest = 8606, optional = true },
				} },
				{ title = "Decoy!", zone = 1452, goals = {
					{ kind = "kill", quest = 8606, objective = 1, npc = 15554, optional = true, note = "Number Two, elite: group of 3 to 5" },
				} },
				{ title = "Dirge Quikcleave", tip = "Dirge Quikcleave cooks in Gadgetzan. He sends you to the Isle of Dread off southern Feralas for a Chimaerok feast.", zone = 1446, goals = {
					{ kind = "turnin", quest = 8606, optional = true, note = "Narain Soothfancy: 25" },
					{ kind = "accept", quest = 8620, optional = true },
					{ kind = "turnin", quest = 8584, optional = true, note = "Dirge Quikcleave" },
					{ kind = "accept", quest = 8585, optional = true },
				} },
				{ title = "The Isle of Dread", tip = "Lord Lakmaeran and the Chimaerok on the Isle of Dread are elites of level 60 to 62 that respawn every ten minutes: a raid's work. The Chimaerok drop a tenderloin about half the time, Lakmaeran two to four now and then.", zone = 1444, goals = {
					{ kind = "collect", quest = 8585, objective = 1, item = 21027, map = 1444, x = 29.3, y = 72.6, optional = true, note = "Lakmaeran's Carcass, Lord Lakmaeran: raid" },
					{ kind = "collect", quest = 8585, objective = 2, item = 21024, count = 20, map = 1444, x = 29.5, y = 78, optional = true, note = "Chimaerok Tenderloin" },
				} },
				{ title = "Draconic for Dummies, Volume II", tip = "The Only Prescription needs the eight chapters of Draconic for Dummies, Volume II: from Doctor Weavil in his house on Alcaz Island (a level 63 elite with guards, raid), the Felguard Elites, Doomguard Commanders and Dreadlords of the Blasted Lands, the Hederine south of Everlook, and a book in the Undercity. Narain hands out the binding when you accept.", zone = 1445, goals = {
					{ kind = "collect", quest = 8620, objective = 1, item = 21111, map = 1445, x = 77.9, y = 17.1, optional = true, note = "Draconic for Dummies: Volume II" },
				} },
				{ title = "Dirge's Chops", tip = "Dirge wants 20 Goblin Rocket Fuel and 20 Deeprock Salt with the meat. Narain then wants 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds and 10 Blue Sapphires, and gives you an Arcanite Buoy: placed at the Swirling Maelstrom in Azshara's Bay of Storms, it calls up Maws, a level 63 boss for a raid. Maws drops the Blue Scepter Shard for one raider on the quest each kill.", zone = 1446, goals = {
					{ kind = "turnin", quest = 8585, optional = true, note = "Dirge Quikcleave" },
					{ kind = "accept", quest = 8586, optional = true },
					{ kind = "collect", quest = 8586, objective = 1, item = 9061, count = 20, optional = true, note = "Goblin Rocket Fuel" },
					{ kind = "collect", quest = 8586, objective = 2, item = 8150, count = 20, optional = true, note = "Deeprock Salt" },
					{ kind = "turnin", quest = 8586, optional = true },
					{ kind = "accept", quest = 8587, optional = true },
					{ kind = "turnin", quest = 8587, optional = true, note = "Narain Soothfancy: 200" },
					{ kind = "turnin", quest = 8620, optional = true, note = "75" },
					{ kind = "accept", quest = 8728, optional = true },
					{ kind = "collect", quest = 8728, objective = 1, item = 12360, count = 20, map = 1446, x = 52, y = 29.7, optional = true, note = "Arcanite Bar: Alchemists, or the auction house" },
					{ kind = "collect", quest = 8728, objective = 2, item = 18562, count = 10, map = 1446, x = 52, y = 29.7, optional = true, note = "Elementium Ore: Blackwing Lair, or the auction house" },
					{ kind = "collect", quest = 8728, objective = 3, item = 12800, count = 10, optional = true, note = "Azerothian Diamond" },
					{ kind = "collect", quest = 8728, objective = 4, item = 12361, count = 10, optional = true, note = "Blue Sapphire" },
					{ kind = "turnin", quest = 8728, optional = true, note = "100" },
					{ kind = "accept", quest = 8729, optional = true },
				} },
				{ title = "Maws", zone = 1447, goals = {
					{ kind = "collect", quest = 8729, objective = 1, item = 21137, map = 1447, x = 68, y = 52.5, optional = true, note = "Blue Scepter Shard, Maws: raid" },
				} },
				{ title = "The green shard: Eranikus", tip = "Malfurion Stormrage appears beside the Shade of Eranikus at the bottom of the Temple of Atal'Hakkar (a five-player dungeon). He sends you to a Forest Wisp outside Darnassus (Horde players walk past the city's guards), then to Keeper Remulos in Moonglade.", zone = 1435, goals = {
					{ kind = "accept", quest = 8733, map = 1435, x = 69.9, y = 53.6, optional = true, note = "Malfurion Stormrage, inside the Temple of Atal'Hakkar" },
				} },
				{ title = "The Forest Wisp", zone = 1438, goals = {
					{ kind = "turnin", quest = 8733, optional = true, note = "Forest Wisp: 25 (and 25 Cenarion Circle)" },
					{ kind = "accept", quest = 8734, optional = true },
				} },
				{ title = "Keeper Remulos", tip = "The Nightmare's Corruption wants a fragment from each of the four Dragons of Nightmare portals: elite dragonkin at the Ashenvale, Feralas and Hinterlands portals (5% each) and the Twilight Corrupter in Duskwood. Raid content.", zone = 1450, goals = {
					{ kind = "turnin", quest = 8734, optional = true, note = "10 (and 100 Cenarion Circle)" },
					{ kind = "accept", quest = 8735, optional = true },
				} },
				{ title = "The Ashenvale portal", tip = "The four dream portals sit in groves guarded by elite dragonkin of level 60 to 62 that respawn every 30 minutes; each drops the portal's fragment one time in twenty. Raid content.", zone = 1440, goals = {
					{ kind = "collect", quest = 8735, objective = 1, item = 21147, optional = true, note = "Fragment of the Nightmare's Corruption" },
				} },
				{ title = "The Duskwood portal", tip = "The Twilight Corrupter (level 63 boss) always drops its fragment.", zone = 1431, goals = {
					{ kind = "collect", quest = 8735, objective = 2, item = 21149, optional = true, note = "Twilight Corrupter" },
				} },
				{ title = "The Feralas portal", zone = 1444, goals = {
					{ kind = "collect", quest = 8735, objective = 3, item = 21148, optional = true, note = "Fragment of the Nightmare's Corruption" },
				} },
				{ title = "The Hinterlands portal", zone = 1425, goals = {
					{ kind = "collect", quest = 8735, objective = 4, item = 21146, optional = true, note = "Fragment of the Nightmare's Corruption" },
				} },
				{ title = "The Nightmare Manifests", tip = "A raid event: follow Keeper Remulos toward Nighthaven and keep him alive against Eranikus and his nightmare adds until Tyrande arrives and redeems Eranikus. Do not kill Eranikus.", zone = 1450, goals = {
					{ kind = "turnin", quest = 8735, optional = true, note = "100 (and 100 Cenarion Circle)" },
					{ kind = "accept", quest = 8736, optional = true },
					{ kind = "complete", quest = 8736, map = 1450, x = 36.2, y = 41.8, optional = true, note = "The Redemption of Eranikus: raid" },
					{ kind = "turnin", quest = 8736, optional = true, note = "200 (and 200 Cenarion Circle)" },
					{ kind = "accept", quest = 8741, optional = true },
				} },
				{ title = "The Scepter of the Shifting Sands", tip = "With the three shards, Anachronos makes the Scepter of the Shifting Sands. In Classic its first holder rings the Scarab Gong once for the whole realm, opening the gates of Ahn'Qiraj, and those who finish within ten hours earn the black qiraji crystal mount; whether Forever's realms get that event is not known.", zone = 1446, goals = {
					{ kind = "turnin", quest = 8730, optional = true, note = "Red Scepter Shard: 200" },
					{ kind = "turnin", quest = 8729, optional = true, note = "Blue Scepter Shard: 200" },
					{ kind = "turnin", quest = 8741, optional = true, note = "Green Scepter Shard: 100" },
					{ kind = "accept", quest = 8742, optional = true },
					{ kind = "turnin", quest = 8742, optional = true, note = "200 (and 200 Cenarion Circle)" },
				} },
				{ title = "The Scarab Gong", tip = "The Scarab Gong hangs before the gates of Ahn'Qiraj. Jonathan the Revelator appears beside it once the gong has been rung, with Treasure of the Timeless One: a weapon and 200 reputation.", zone = 1451, goals = {
					{ kind = "accept", quest = 8743, optional = true, note = "The Scarab Gong" },
					{ kind = "turnin", quest = 8743, optional = true, note = "200 (and 200 Cenarion Circle)" },
					{ kind = "accept", quest = 8745, optional = true, note = "Jonathan the Revelator" },
					{ kind = "turnin", quest = 8745, optional = true, note = "200" },
				} },
				{ title = "Neutral to Friendly in the Temple", tip = "Neutral to Friendly is 3,000 reputation. Every trash mob of the Temple of Ahn'Qiraj (a 40-player raid behind the Scarab Wall) gives 100, and the Twin Emperors 210 each, until 2,999 of 3,000 Neutral, one point short of Friendly; there they stop. Then hand in one saved Ancient Qiraji Artifact (1,000, to Andorgos) or Qiraji Lord's Insignia (500, to Kandrostrasz) to tip you over. The shoulder and boot exchanges of the Temple's tier set need no standing: the token, two idols and ten scarabs to Andorgos (shoulders) or Kandrostrasz (boots) pay 200 each. The Ruins of Ahn'Qiraj (20 players) give a little from bosses: Kurinnaxx, Moam, Buru and Ayamiss 50 each, Rajaxx 34, Ossirian 100, to Exalted.", zone = 1451, goals = {
					{ kind = "accept", quest = 8784, item = 21230, map = 1451, x = 29, y = 92.8, optional = true, note = "Ancient Qiraji Artifact" },
					{ kind = "turnin", quest = 8784, map = 1451, x = 29, y = 92.8, optional = true, note = "Andorgos: 1,000" },
					{ kind = "collect", item = 21229, map = 1451, x = 29, y = 92.8, optional = true, note = "Qiraji Lord's Insignia, Temple bosses" },
					{ kind = "turnin", quest = 8579, map = 1451, x = 29, y = 92.8, optional = true, direct = true, note = "Kandrostrasz: 500, handed in from his window" },
					{ kind = "rep", factionId = 910, standing = "Friendly" },
				} },
				{ title = "The ring at Friendly", tip = "At Friendly, Anachronos upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation.", zone = 1446, goals = {
					{ kind = "talk", npc = 15192, optional = true, note = "Anachronos: the Friendly ring quest of your path" },
				} },
				{ title = "Friendly to Honored: the turn-ins", tip = "Now hand in what you saved. Each Ancient Qiraji Artifact (any Temple trash, 1% to 9%) starts Secrets of the Qiraji: 1,000 reputation from Andorgos, one of the three bronze dragons inside the Temple. Each Qiraji Lord's Insignia (nearly every Temple boss) goes to Kandrostrasz for Mortal Champions: 500 here and 100 Cenarion Circle. C'Thun gives 2,500, to Exalted. Friendly to Honored is 6,000: six artifacts or twelve insignias. Friendly also opens the helm and leg exchanges of the Temple's tier set (200 reputation each) at Andorgos and Kandrostrasz.", zone = 1451, goals = {
					{ kind = "collect", item = 21230, map = 1451, x = 29, y = 92.8, optional = true, note = "Ancient Qiraji Artifact: right-click it, then Andorgos" },
					{ kind = "collect", item = 21229, map = 1451, x = 29, y = 92.8, optional = true, note = "Qiraji Lord's Insignia" },
					{ kind = "turnin", quest = 8595, map = 1451, x = 29, y = 92.8, optional = true, direct = true, note = "Mortal Champions: 1 insignia, 500" },
					{ kind = "rep", factionId = 910, standing = "Honored" },
				} },
				{ title = "The ring at Honored", tip = "At Honored, Anachronos upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation.", zone = 1446, goals = {
					{ kind = "talk", npc = 15192, optional = true, note = "Anachronos: the Honored ring quest of your path" },
				} },
				{ title = "Honored to Revered", tip = "Honored to Revered is 12,000: twelve artifacts, 24 insignias, or a mix with C'Thun (2,500). After the first, each insignia is the repeatable Mortal Champions. Every Temple boss sometimes drops an Imperial Qiraji Armaments or Regalia (about one time in twenty): Arygos and Merithra of the Dream, inside the Temple once C'Thun is dead, take it with 3 Elementium Ore for 200 and a weapon. Honored opens the chest exchange of the tier set (200).", zone = 1451, goals = {
					{ kind = "collect", item = 21229, map = 1451, x = 29, y = 92.8, optional = true, note = "Qiraji Lord's Insignia" },
					{ kind = "turnin", quest = 8595, map = 1451, x = 29, y = 92.8, optional = true, direct = true, note = "Mortal Champions: 1 insignia, 500" },
					{ kind = "collect", item = 21232, map = 1451, x = 29, y = 92.8, optional = true, note = "Imperial Qiraji Armaments" },
					{ kind = "collect", item = 21237, map = 1451, x = 29, y = 92.8, optional = true, note = "Imperial Qiraji Regalia" },
					{ kind = "collect", item = 18562, count = 3, map = 1428, x = 32.5, y = 32.4, optional = true, note = "Elementium Ore, Blackwing Lair or the auction house" },
					{ kind = "turnin", quest = 8789, map = 1451, x = 29, y = 92.8, optional = true, direct = true, note = "Arygos: Armaments and 3 Elementium Ore, 200" },
					{ kind = "turnin", quest = 8790, map = 1451, x = 29, y = 92.8, optional = true, direct = true, note = "Merithra of the Dream: Regalia and 3 Elementium Ore, 200" },
					{ kind = "rep", factionId = 910, standing = "Revered" },
				} },
				{ title = "The ring at Revered", tip = "At Revered, Anachronos upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation.", zone = 1446, goals = {
					{ kind = "talk", npc = 15192, optional = true, note = "Anachronos: the Revered ring quest of your path" },
				} },
				{ title = "Revered to Exalted", tip = "Revered to Exalted is 21,000: 21 artifacts or 42 insignias, with C'Thun's 2,500 a week. C'Thun's eye starts C'Thun's Legacy for Caelestrasz (200, and 200 Cenarion Circle). At Exalted Anachronos gives the last ring: The Protector of Kalimdor, The Qiraji Conqueror or The Grand Invoker.", zone = 1451, goals = {
					{ kind = "collect", item = 21229, map = 1451, x = 29, y = 92.8, optional = true, note = "Qiraji Lord's Insignia" },
					{ kind = "turnin", quest = 8595, map = 1451, x = 29, y = 92.8, optional = true, direct = true, note = "Mortal Champions: 1 insignia, 500" },
					{ kind = "accept", quest = 8801, item = 21221, map = 1451, x = 29, y = 92.8, optional = true, note = "Eye of C'Thun" },
					{ kind = "turnin", quest = 8801, map = 1451, x = 29, y = 92.8, optional = true, note = "Caelestrasz: 200" },
					{ kind = "rep", factionId = 910, standing = "Exalted" },
				} },
				{ title = "The Exalted ring", tip = "At Exalted, Anachronos gives the last ring of your path: The Protector of Kalimdor, The Qiraji Conqueror or The Grand Invoker. Bring the Revered ring; 100 reputation.", zone = 1446, goals = {
					{ kind = "talk", npc = 15192, optional = true, note = "Anachronos: the Exalted ring quest of your path" },
				} },
			},
		},
		{
			id = "forever/reputation/cenarion-circle", title = "Cenarion Circle Reputation", category = "Reputation", folder = "Reputation · World", levels = { 60, 60 }, zone = 1451, version = 1, revision = "edd26958dae532e5e5521c67bd29cf7e8da32750e2ce241e0e7e34ecc89e065b", legacyRevision = "7ee314f0bb4037080596ad72b964f56d352d8436d80eb67cb6e78d4b5308fb79", keywords = { "Cenarion Circle", "Cenarion Hold", "Silithus", "Encrypted Twilight Text", "Bor Wildmane", "Twilight's Hammer", "cultists", "Twilight Trappings", "Wind Stone", "Abyssal Council", "Abyssal Crest", "Abyssal Signet", "Abyssal Scepter", "Templar", "Duke", "Field Duty", "Windcaller Kaldon", "Cenarion badge", "Allegiance to Cenarion Circle", "Vargus", "Mishta", "Kania", "Gaea's Embrace", "Greater Nature Resistance", "Greater Fire Resistance", "Sylvan", "Ruins of Ahn'Qiraj" }, rewards = { { item = 20733 }, { item = 22683 }, { item = 20732 }, { item = 21187 }, { text = "Forever's new Silithus patterns for Tailors, Leatherworkers and Blacksmiths, Friendly and Honored" } }, why = "Nature resistance enchants and patterns, badge gear and Forever's new Silithus patterns, from Silithus's camps.",
			steps = {
				{ title = "The emissary in Ironforge", tip = "Optional, and needed only for the Dredge quests later: Cenarion Emissary Jademoon sends you to Silithus with Taking Back Silithus, a 10-reputation letter. Skip it if you are already in Silithus.", only = { factions = { "Alliance" } }, zone = 1455, goals = {
					{ kind = "accept", quest = 8275, optional = true },
				} },
				{ title = "The emissary in Orgrimmar", tip = "Optional, and needed only for the Dredge quests later: Cenarion Emissary Blackhoof sends you to Silithus with Taking Back Silithus, a 10-reputation letter. Skip it if you are already in Silithus.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "accept", quest = 8276, optional = true },
				} },
				{ title = "Cenarion Hold", tip = "Cenarion Hold is the walled druid camp in north-central Silithus, with flight points for both sides. Everyone starts Neutral with the Cenarion Circle (druids at 2,000 of 3,000). Bor and Huum Wildmane stand together in the main building. Secret Communication opens the Encrypted Twilight Text turn-ins for good. The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it.", zone = 1451, goals = {
					{ kind = "getfp", place = "Cenarion Hold" },
					{ kind = "turnin", quest = 8275, optional = true, only = { factions = { "Alliance" } }, note = "Windcaller Proudhorn" },
					{ kind = "turnin", quest = 8276, optional = true, only = { factions = { "Horde" } } },
					{ kind = "accept", quest = 8318, note = "Bor Wildmane" },
					{ kind = "accept", quest = 8320, optional = true, note = "Huum Wildmane, level 60" },
				} },
				{ title = "The cultist camp west of Cenarion Hold", tip = "The nearest Twilight's Hammer camp lies just south-west of the Hold. Avengers, Geolords and Stonecallers (level 57 to 59) each drop an Encrypted Twilight Text about a third of the time, and every cultist kill is 1 reputation. Twilight Keeper Havunth walks the edge of the camp. Keep every cultist robe, cowl and mantle you loot: they are the Twilight Trappings for the Wind Stones later.", zone = 1451, goals = {
					{ kind = "collect", quest = 8318, objective = 1, item = 20404, count = 10, note = "Encrypted Twilight Text" },
					{ kind = "kill", quest = 8320, objective = 1, npc = 11881, count = 10, optional = true, note = "Twilight Geolord" },
				} },
				{ title = "Back to Cenarion Hold", zone = 1451, goals = {
					{ kind = "turnin", quest = 8318 },
					{ kind = "turnin", quest = 8320, optional = true },
					{ kind = "accept", quest = 8321, optional = true, note = "Vyral the Vile" },
				} },
				{ title = "Cultists until the top of Friendly, texts saved", tip = "Neutral to Honored is 9,000 reputation (7,000 for druids). Every Twilight Avenger, Geolord, Stonecaller, Master and Overlord gives 1 reputation until 5,999 of 6,000 Friendly, one point short of Honored; there they stop. Save every Encrypted Twilight Text and leave the quests of the next steps for later: each kill below that point is a free point on top of its text, and the texts and quests pay the same at any standing. A text drops about every third kill, so 30 kills make 30 reputation and 10 texts (100 reputation later). Four camps: south-west of the Hold (39,44), the far west (26,34), the far south-west (19,84) and the north-east below Hive'Ashi (66,18: Overlords, and Flamereavers that count until the top of Honored). The Twilight Prophet (87% text) walks between 18,31 and 23,69. Texts sell on the auction house if you would rather buy. At 5,999 Friendly the last point into Honored comes from a Flamereaver, Twilight Keeper or Marauder, or from your first 10 texts at Bor Wildmane.", zone = 1451, goals = {
					{ kind = "note", text = "Kills alone to the top of Friendly is 8,999 kills (6,999 for druids), but the texts they drop (about 3,000) are worth 30,000 more: most of the way to Exalted." },
					{ kind = "note", text = "Friendly (3,000) opens Kania's Formula: Enchant Cloak - Greater Fire Resistance (10g), Mishta's Cenarion Herb Bag (2g) and Sylvan Shoulders (5g), and Forever's new Friendly gloves patterns (7g 50s)." },
					{ kind = "collect", item = 20404, count = 10, nearest = true, optional = true, note = "Encrypted Twilight Text: save them" },
					{ kind = "kill", npc = 11880, optional = true, note = "Twilight Avenger" },
					{ kind = "kill", npc = 11882, optional = true, note = "Twilight Stonecaller" },
					{ kind = "kill", npc = 15213, optional = true, note = "Twilight Overlord" },
					{ kind = "kill", npc = 15201, map = 1451, x = 69.8, y = 14.3, optional = true, note = "Twilight Flamereaver: still counts at 5,999 Friendly" },
					{ kind = "turnin", quest = 8319, optional = true, direct = true, note = "Bor Wildmane: 10 texts, 100, for the last point" },
					{ kind = "rep", factionId = 609, standing = "Honored" },
				} },
				{ title = "Vyral the Vile", tip = "Vyral the Vile (level 61, not elite) waits at the back of Twilight's Run, the cave in the north-east of Silithus. Flamereavers and Twilight Masters guard the way: the Flamereavers count until the top of Honored, the Masters stop at the top of Friendly like the other cultists.", zone = 1451, goals = {
					{ kind = "collect", quest = 8321, objective = 1, item = 20466, map = 1451, x = 72.4, y = 15.6, optional = true, note = "Vyral's Signet Ring" },
					{ kind = "turnin", quest = 8321, optional = true },
				} },
				{ title = "Silithus quests at Cenarion Hold", tip = "Now cash in the one-time quests: about 1,700 reputation alone, 2,400 with the group quests. They are level 55 to 60, so they pay in full at 60. Securing the Supply Lines needs Taking Back Silithus first. Deathclasp is an elite scorpid with two guards (group of 2 or 3). Calandrath's Desert Recipe is for Cooks: its recipe makes the Smoked Desert Dumplings he wants. Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", zone = 1451, goals = {
					{ kind = "accept", quest = 8277, note = "Beetix Ficklespragg" },
					{ kind = "accept", quest = 8280, optional = true, note = "Windcaller Proudhorn, after Taking Back Silithus" },
					{ kind = "accept", quest = 8284, note = "Geologist Larksbane" },
					{ kind = "accept", quest = 8304, note = "Commander Mar'alith" },
					{ kind = "accept", quest = 8283, optional = true, note = "Wanted poster: Deathclasp, elite" },
					{ kind = "accept", quest = 8307, optional = true, note = "Calandrath, for Cooks" },
					{ kind = "accept", quest = 9415, optional = true, only = { factions = { "Alliance" } }, note = "Rifleman Torrig: Report to Marshal Bluewall" },
					{ kind = "accept", quest = 9416, optional = true, only = { factions = { "Horde" } }, note = "Scout Bloodfist: Report to General Kirika" },
				} },
				{ title = "Around Cenarion Hold", tip = "Stonelash Scorpids and Sand Skitterers roam the sands around the Hold; Dredge Strikers dig north-east of it. The Sandy Cookbook lies in the cultist camp south-west of the Hold.", zone = 1451, goals = {
					{ kind = "collect", quest = 8277, objective = 1, item = 20373, count = 8, note = "Stonelash Scorpid Stinger" },
					{ kind = "collect", quest = 8277, objective = 2, item = 20376, count = 8, note = "Sand Skitterer Fang" },
					{ kind = "kill", quest = 8280, objective = 1, npc = 11740, count = 15, optional = true, note = "Dredge Striker" },
					{ kind = "turnin", quest = 8307, optional = true, note = "Sandy Cookbook" },
					{ kind = "accept", quest = 8313, optional = true },
				} },
				{ title = "Back at the Hold", tip = "Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8277 },
					{ kind = "accept", quest = 8278 },
					{ kind = "turnin", quest = 8280, optional = true },
					{ kind = "accept", quest = 8281, optional = true },
					{ kind = "turnin", quest = 8313, optional = true, note = "Calandrath" },
					{ kind = "accept", quest = 8317, optional = true },
				} },
				{ title = "Stonelash and Dredge Crushers", tip = "Stonelash Flayers, Pincers and Rock Stalkers live south and south-west of the Hold; their stingers and fangs drop about one time in ten. Dredge Crushers dig south and west of the Hold.", zone = 1451, goals = {
					{ kind = "collect", quest = 8278, objective = 1, item = 20375, count = 3, note = "Stonelash Flayer Stinger" },
					{ kind = "collect", quest = 8278, objective = 2, item = 20374, count = 3, note = "Stonelash Pincer Stinger" },
					{ kind = "collect", quest = 8278, objective = 3, item = 20377, count = 3, note = "Rock Stalker Fang" },
					{ kind = "kill", quest = 8281, objective = 1, npc = 11741, count = 20, optional = true, note = "Dredge Crusher" },
					{ kind = "learn", spell = 24801, optional = true, note = "Smoked Desert Dumplings, from the Sandy Cookbook" },
					{ kind = "craft", spell = 24801, count = 10, optional = true, note = "Smoked Desert Dumplings, from Sandworm Meat and Soothing Spices" },
				} },
				{ title = "Noggle and Proudhorn", tip = "Beetix and Noggle Ficklespragg stand upstairs in their building: go up inside, the arrow cannot tell the floors apart.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8278 },
					{ kind = "accept", quest = 8282, note = "Noggle Ficklespragg" },
					{ kind = "turnin", quest = 8281, optional = true },
					{ kind = "turnin", quest = 8317, optional = true },
				} },
				{ title = "The Ravaged Twilight Camp", tip = "The broken camp in the far north-west of Silithus: the Twilight Tablet Fragments lie on the ground among the ruins.", zone = 1451, goals = {
					{ kind = "collect", quest = 8284, objective = 1, item = 20378, count = 8, note = "Twilight Tablet Fragment" },
				} },
				{ title = "Larksbane", zone = 1451, goals = {
					{ kind = "turnin", quest = 8284 },
					{ kind = "accept", quest = 8285 },
				} },
				{ title = "Hermit Ortell", tip = "Hermit Ortell hides in the hills of eastern Silithus. He also decodes Encrypted Twilight Texts for a chance at a scroll of beckoning, but Bor Wildmane pays the reputation: keep the texts for Bor.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8285 },
					{ kind = "accept", quest = 8279 },
				} },
				{ title = "The three Twilight Keepers", tip = "Each Keeper is a level 60, not elite, alone at a camp edge, and always drops its chapter: Mayna in the far west camp, Havunth in the camp south-west of the Hold, Exeter in the far south-west camp beside the Twilight Lord.", zone = 1451, goals = {
					{ kind = "collect", quest = 8279, objective = 1, item = 20394, note = "Twilight Keeper Mayna" },
					{ kind = "collect", quest = 8279, objective = 2, item = 20395, note = "Twilight Keeper Havunth" },
					{ kind = "collect", quest = 8279, objective = 3, item = 20396, note = "Twilight Keeper Exeter" },
				} },
				{ title = "Back to Ortell", zone = 1451, goals = {
					{ kind = "turnin", quest = 8279 },
					{ kind = "accept", quest = 8287 },
				} },
				{ title = "Bronzebeard's Encampment", tip = "The dwarves' camp in the south of Silithus. Talk Frankal Stonebridge and Rutgar Glyphshaper through their whole stories for Dearest Natalia. Noggle's Satchel lies on the mountain south-east of the camp. Deathclasp lives up the trail east of the camp: an elite, and his Knock Away can throw you off the cliff.", zone = 1451, goals = {
					{ kind = "complete", quest = 8304, map = 1451, x = 41, y = 88.7, note = "Frankal Stonebridge and Rutgar Glyphshaper" },
					{ kind = "collect", quest = 8282, objective = 1, item = 20379, note = "Noggle's Satchel" },
					{ kind = "collect", quest = 8283, objective = 1, item = 20385, map = 1451, x = 45.1, y = 92.3, optional = true, note = "Deathclasp's Pincer, elite: group of 2 or 3" },
				} },
				{ title = "Back to Cenarion Hold with news", tip = "Noggle Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8287, note = "Commander Mar'alith" },
					{ kind = "turnin", quest = 8304 },
					{ kind = "accept", quest = 8306, optional = true, note = "Natalia, elite: group up" },
					{ kind = "turnin", quest = 8282, note = "Noggle Ficklespragg" },
					{ kind = "turnin", quest = 8283, optional = true },
				} },
				{ title = "Rubbings and brains", tip = "Rutgar and Frankal hand out the next two quests at their camp. Each hive has a Glyphed Crystal to rub with the Geologist's Transcription Kit, and its silithid drop the brains: Hive'Ashi north of the Hold, Hive'Zora in the west, Hive'Regal in the south. Inside Hive'Regal waits Mistress Natalia (level 62 elite, mind control and fear; group of 3 to 5). Now and then a hive silithid drops Brann Bronzebeard's Lost Letter: it starts a quest for Rutgar worth 100.", zone = 1451, goals = {
					{ kind = "accept", quest = 8309, note = "Rutgar Glyphshaper" },
					{ kind = "accept", quest = 8310, note = "Frankal Stonebridge" },
					{ kind = "collect", quest = 8309, objective = 1, item = 20455, note = "Hive'Ashi Rubbing" },
					{ kind = "collect", quest = 8309, objective = 2, item = 20454, note = "Hive'Zora Rubbing" },
					{ kind = "collect", quest = 8309, objective = 3, item = 20456, map = 1451, x = 52, y = 99, note = "Hive'Regal Rubbing, deep in Hive'Regal" },
					{ kind = "collect", quest = 8310, objective = 1, item = 20457, note = "Hive'Ashi Silithid Brain" },
					{ kind = "collect", quest = 8310, objective = 2, item = 20458, note = "Hive'Zora Silithid Brain" },
					{ kind = "collect", quest = 8310, objective = 3, item = 20459, note = "Hive'Regal Silithid Brain" },
					{ kind = "accept", quest = 8308, item = 20461, optional = true, note = "Brann Bronzebeard's Lost Letter, a rare drop" },
				} },
				{ title = "Mistress Natalia", tip = "Optional: Natalia waits deep in Hive'Regal, the hive in the south of Silithus. She is a level 62 elite who mind-controls, fears and heals herself below half health: bring a group of 3 to 5 and interrupt her heals.", zone = 1414, goals = {
					{ kind = "kill", quest = 8306, objective = 1, npc = 15215, optional = true, note = "Mistress Natalia: group of 3 to 5" },
				} },
				{ title = "The Calling", tip = "Unraveling the Mystery leads to The Calling: Geologist Larksbane sends you to the Bones of Grakkarond to summon Emissary Roman'khan, a level 63 boss for a raid of about 20. Take it only with a raid.", zone = 1451, goals = {
					{ kind = "turnin", quest = 8309 },
					{ kind = "turnin", quest = 8310 },
					{ kind = "accept", quest = 8314, note = "Rutgar Glyphshaper" },
					{ kind = "turnin", quest = 8308, optional = true, note = "Rutgar Glyphshaper: 100" },
					{ kind = "turnin", quest = 8314, note = "Geologist Larksbane" },
					{ kind = "accept", quest = 8315, optional = true, note = "raid of 20" },
					{ kind = "turnin", quest = 8306, optional = true, note = "Commander Mar'alith" },
					{ kind = "collect", quest = 8315, objective = 1, item = 20465, map = 1451, x = 48.8, y = 58.1, optional = true, note = "Crystal Unlocking Mechanism, Emissary Roman'khan: raid of 20" },
					{ kind = "turnin", quest = 8315, optional = true },
				} },
				{ title = "The New Frontier, Thunder Bluff", tip = "Optional: Rabine Saturna's chain pays 525 Cenarion reputation over seven quests of level 55 to 57, full at 60. Bluff Runner Windstrider sends you to Arch Druid Hamuul Runetotem on Elder Rise, who sends you to Rabine Saturna in Nighthaven, Moonglade.", only = { factions = { "Horde" } }, zone = 1456, goals = {
					{ kind = "accept", quest = 1000, optional = true, note = "Bluff Runner Windstrider" },
					{ kind = "turnin", quest = 1000, optional = true, note = "Arch Druid Hamuul Runetotem" },
					{ kind = "accept", quest = 1123, optional = true },
				} },
				{ title = "The New Frontier, Darnassus", tip = "Optional: Rabine Saturna's chain pays 525 Cenarion reputation over seven quests of level 55 to 57, full at 60. Herald Moonstalker sends you to Arch Druid Fandral Staghelm, who sends you to Mathrengyl Bearwalker, who sends you to Rabine Saturna in Nighthaven, Moonglade.", only = { factions = { "Alliance" } }, zone = 1457, goals = {
					{ kind = "accept", quest = 1047, optional = true, note = "Herald Moonstalker" },
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6, optional = true },
					{ kind = "turnin", quest = 1047, optional = true, note = "Arch Druid Fandral Staghelm" },
					{ kind = "accept", quest = 6761, optional = true },
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6, optional = true },
					{ kind = "turnin", quest = 6761, optional = true, note = "Mathrengyl Bearwalker" },
					{ kind = "accept", quest = 6762, optional = true },
				} },
				{ title = "Rabine Saturna", tip = "Rabine Saturna lives in Nighthaven. She sends you to Layo Starstrike at Valor's Rest, the camp in the north-east corner of Silithus.", zone = 1450, goals = {
					{ kind = "turnin", quest = 1123, optional = true, only = { factions = { "Horde" } } },
					{ kind = "turnin", quest = 6762, optional = true, only = { factions = { "Alliance" } } },
					{ kind = "accept", quest = 1124, optional = true },
				} },
				{ title = "Southwind Village", tip = "The Tortured Druids and Sentinels roam the ruins of Southwind Village, south-east of Cenarion Hold; the Hive'Ashi Pod sits on the top floor of its wasp-circled tower.", zone = 1451, goals = {
					{ kind = "turnin", quest = 1124, optional = true, note = "Layo Starstrike" },
					{ kind = "accept", quest = 1125, optional = true },
					{ kind = "kill", quest = 1125, objective = 1, npc = 12178, count = 8, optional = true, note = "Tortured Druid" },
					{ kind = "kill", quest = 1125, objective = 2, npc = 12179, count = 8, optional = true, note = "Tortured Sentinel" },
					{ kind = "turnin", quest = 1125, optional = true },
					{ kind = "accept", quest = 1126, optional = true },
					{ kind = "collect", quest = 1126, objective = 1, item = 17346, optional = true, note = "Encrusted Silithid Object" },
					{ kind = "turnin", quest = 1126, optional = true },
					{ kind = "accept", quest = 6844, optional = true },
				} },
				{ title = "Umber in Nighthaven", zone = 1450, goals = {
					{ kind = "turnin", quest = 6844, optional = true, note = "Umber" },
					{ kind = "accept", quest = 6845, optional = true },
					{ kind = "turnin", quest = 6845, optional = true, note = "Rabine Saturna" },
					{ kind = "accept", quest = 1185, optional = true },
					{ kind = "turnin", quest = 1185, optional = true },
				} },
				{ title = "Quests elsewhere", tip = "The Cenarion Circle's other quests are spread over Kalimdor and the Plaguelands. Forever pays them in full at any level: The Wildlife Suffers Too (Mulgris Deepriver, Western Plaguelands, levels 54 and 56) 75 and 75, Corruption of Earth and Seed (Maraudon, level 51) 150. Shards of the Felvine (Rabine Saturna, level 60, the Felvine Shard from Alzzin in Dire Maul) pays 150 and its Reliquary 100 at any level.", zone = 1450, goals = {
					{ kind = "note", text = "Do the Western Plaguelands and Maraudon quests while you level; at 60 they may pay a fraction." },
				} },
				{ title = "Encrypted Twilight Texts to Revered", tip = "Honored to Revered is 12,000 reputation. Bor Wildmane takes 10 Encrypted Twilight Texts for 100 reputation, again and again, until Exalted: 120 turn-ins (1,200 texts) to Revered without the quests, or about 950 texts after them. Hand in the texts you saved now. The cultists no longer count, but the Flamereavers, Twilight Keepers, Marauders and Templars count until 11,999 of 12,000 Honored, and the Twilight Lord Everun and Prophet until Exalted. Honored opens Kania's Formula: Enchant Cloak - Greater Nature Resistance (10g), Mishta's Pattern: Sylvan Crown (5g) and Forever's new Honored patterns (7g 50s each).", zone = 1451, goals = {
					{ kind = "collect", item = 20404, count = 10, nearest = true, optional = true, note = "Encrypted Twilight Text" },
					{ kind = "turnin", quest = 8319, optional = true, direct = true, note = "Bor Wildmane: 10 texts, 100" },
					{ kind = "rep", factionId = 609, standing = "Revered" },
				} },
				{ title = "Field Duty, level 60", tip = "Windcaller Kaldon stands by the moonwell of Cenarion Hold. Field Duty (25 reputation, repeatable) sends you with unsigned papers to your side's captain: Captain Blackanvil's Ironforge Brigade outside Hive'Zora (Alliance) or Krug Skullsplit's Orgrimmar Legion outside Hive'Regal (Horde). Use the papers first, then talk to the captain: a level 60 elite silithid attacks; keep the captain alive and he signs. Kaldon then lets you pick a Combat, Logistics or Tactical Assignment, each holding a random briefing worth 50 reputation and a badge: 30 hive silithid kills (elites), goods such as 30 Heavy Runecloth Bandages or 3 Ornate Mithril Boots, or one Templar, Twilight Marauder or scout report. One badge of each kind buys Allegiance to Cenarion Circle at Kaldon: 200 reputation, repeatable. A full round is about 375 reputation.", zone = 1451, goals = {
					{ kind = "accept", quest = 8507, optional = true, only = { factions = { "Alliance" } }, note = "Windcaller Kaldon" },
					{ kind = "accept", quest = 8731, optional = true, only = { factions = { "Horde" } } },
					{ kind = "collect", quest = 8507, objective = 1, item = 20810, map = 1451, x = 32.8, y = 52.6, optional = true, only = { factions = { "Alliance" } }, note = "Signed Field Duty Papers, Captain Blackanvil" },
					{ kind = "collect", quest = 8731, objective = 1, item = 20810, map = 1451, x = 51.4, y = 68.4, optional = true, only = { factions = { "Horde" } }, note = "Signed Field Duty Papers, Krug Skullsplit" },
					{ kind = "turnin", quest = 8507, optional = true, only = { factions = { "Alliance" } } },
					{ kind = "turnin", quest = 8731, optional = true, only = { factions = { "Horde" } } },
					{ kind = "turnin", quest = 9338, optional = true, direct = true, note = "Allegiance: one Combat, Logistics and Tactical badge, 200" },
					{ kind = "accept", quest = 8800, optional = true, note = "Cenarion Battlegear: Vargus's badge gear" },
					{ kind = "turnin", quest = 8800, optional = true },
				} },
				{ title = "Silithyst", tip = "Optional, 100 reputation once: Scouring the Desert. Your side's camp sits by a hive: Marshal Bluewall's by Hive'Zora (Alliance), General Kirika's by Hive'Regal (Horde). Silithyst rises from glowing geysers around the desert: walk through one, carry the Silithyst to your camp's Silithyst Extractor, then talk to the camp's leader. It is a world PvP objective: players of the other side can take it from you.", zone = 1451, goals = {
					{ kind = "turnin", quest = 9415, map = 1451, x = 33.3, y = 51.1, optional = true, only = { factions = { "Alliance" } }, note = "Marshal Bluewall" },
					{ kind = "accept", quest = 9419, optional = true, only = { factions = { "Alliance" } } },
					{ kind = "complete", quest = 9419, map = 1451, x = 33, y = 50.8, optional = true, only = { factions = { "Alliance" } }, note = "deliver Silithyst at the extractor" },
					{ kind = "turnin", quest = 9419, optional = true, only = { factions = { "Alliance" } }, note = "100" },
					{ kind = "turnin", quest = 9416, map = 1451, x = 50.8, y = 69.5, optional = true, only = { factions = { "Horde" } }, note = "General Kirika" },
					{ kind = "accept", quest = 9422, optional = true, only = { factions = { "Horde" } } },
					{ kind = "complete", quest = 9422, map = 1451, x = 50.9, y = 69.3, optional = true, only = { factions = { "Horde" } }, note = "deliver Silithyst at the extractor" },
					{ kind = "turnin", quest = 9422, optional = true, only = { factions = { "Horde" } }, note = "100" },
				} },
				{ title = "Templars and the Abyssal Council", tip = "Wearing a full set of Twilight Trappings (cultist Cowl, Mantle and Robe, about 8%, 8% and 6% per cultist) lets you use a Lesser Wind Stone: two stand in each of the three western camps. A random Abyssal Templar appears: a level 60 elite for 1 to 3 players, 5 reputation until the top of Honored and an Abyssal Crest 93% of the time. The summon uses up the set (and later the medallion and ring too), and if the elemental gets away they are gone: summon only when you can win. Abyssal Contacts pays 100 for the first crest; after that Bor takes 3 crests for 50. From Friendly, Huum Wildmane sends you to Aurel Goldleaf: 3 crests and a Large Brilliant Shard buy the Medallion of Station that, worn with a set, opens the larger Wind Stone for a Duke (level 62 elite, group of 5; 25 reputation, Abyssal Signet 85%).", zone = 1451, goals = {
					{ kind = "accept", quest = 8361, optional = true, note = "Bor Wildmane" },
					{ kind = "collect", quest = 8361, objective = 1, item = 20513, map = 1451, x = 24.4, y = 36, optional = true, note = "Abyssal Crest: Templar, group of 1 to 3" },
					{ kind = "turnin", quest = 8361, optional = true },
					{ kind = "turnin", quest = 8362, optional = true, direct = true, note = "3 Abyssal Crests: 50" },
