					{ kind = "collect", quest = 8352, objective = 1, item = 20515, map = 1451, x = 25.6, y = 34, optional = true, note = "Abyssal Scepter: Lord, raid of 20" },
					{ kind = "turnin", quest = 8352, optional = true },
