		{
			id = "forever/reputation/centaur-clans", title = "Gelkis and Magram Centaur Reputation", category = "Reputation", folder = "Reputation · World", levels = { 30, 60 }, zone = 1443, version = 1, revision = "96c59b0415609611158ce85cada0ec0b6a1ba153b1160e634fdf43b3888cd46e", keywords = { "Gelkis Clan Centaur", "Magram Clan Centaur", "centaur", "Desolace", "Uthek the Wise", "Warug", "Captain Pentigast", "Gurda Wildmane", "Molkar", "Gorhak", "Buying Friendship", "Economic Warfare", "Carved Centaur Totem", "Maraudine", "Valley of Bones", "Shen'dralas", "Nerlokh", "Orgrul", "Khan Jehn", "Ongeku", "Kolkar", "Centaur Banner Deployment Device", "A Conqueror's Crown", "Conqueror's Helm", "title" }, rewards = { { item = 269901 }, { text = "12 recipes for Carved Centaur Totems at the clan quartermasters, no standing needed" }, { text = "Khan Jehn's quest: a clan title and a choice of three rare level 35 weapons" } }, why = "Desolace's feuding clans, reworked in Forever: pick one, buy its friendship, and trade totems for recipes.",
			steps = {
				{ title = "Pick your clan", tip = "The Gelkis (south-west Desolace) and the Magram (south-east) are at war: every kill of one clan gives the other 20 and costs its own clan 100, so you can only climb with one. Both start Neutral. Forever's quests are worth far more than kills now, and the choice quests no longer cost the other clan anything. Alliance: Captain Pentigast at Nijel's Point offers Strange Alliance (Gelkis) and Brutal Politics (Magram). Horde: Gurda Wildmane offers Gelkis Alliance and Magram Alliance. Take the one of your clan, and Carved Centaur Totems: each clan's Buying Friendship (3,000) is offered once you bring the totems back. Then tick the task. The guide goes on with the Gelkis; take the Magram's quests instead and it goes to the Magram half. Forever pays these quests in full at any level.", zone = 1443, goals = {
					{ kind = "accept", quest = 1382, optional = true, only = { factions = { "Alliance" } }, note = "Strange Alliance: Gelkis" },
					{ kind = "accept", quest = 1368, optional = true, only = { factions = { "Horde" } }, note = "Gelkis Alliance" },
					{ kind = "accept", quest = 93224, only = { factions = { "Alliance" } }, note = "Carved Centaur Totems" },
					{ kind = "accept", quest = 93225, only = { factions = { "Horde" } }, note = "Carved Centaur Totems" },
					{ kind = "task", text = "Take the quests of one clan" },
				} },
				{ title = "Carved Centaur Totems", tip = "The Kolkar centaurs (level 30-33) in the camps along the eastern road, south of Nijel's Point, drop the totems, and so do the Magram and the Maraudine. Bring five back, then take your clan's Buying Friendship (Gelkis below; the Magram's instead for the Magram).", zone = 1443, goals = {
					{ kind = "collect", quest = 93224, objective = 1, item = 254432, count = 5, map = 1443, x = 69.5, y = 44, only = { factions = { "Alliance" } }, note = "Carved Centaur Totem: Kolkar centaurs" },
					{ kind = "collect", quest = 93225, objective = 1, item = 254432, count = 5, map = 1443, x = 69.5, y = 44, only = { factions = { "Horde" } }, note = "Carved Centaur Totem: Kolkar centaurs" },
					{ kind = "turnin", quest = 93224, only = { factions = { "Alliance" } }, note = "Captain Pentigast" },
					{ kind = "turnin", quest = 93225, only = { factions = { "Horde" } }, note = "Gurda Wildmane" },
					{ kind = "accept", quest = 93227, optional = true, only = { factions = { "Alliance" } }, note = "Buying Friendship: Gelkis" },
					{ kind = "accept", quest = 94873, optional = true, only = { factions = { "Horde" } }, note = "Buying Friendship: Gelkis" },
				} },
				{ title = "Gelkis or Magram", tip = "No clan's quests in your log: the guide goes on with the Gelkis. For the Magram, take their choice quest and Buying Friendship and the guide goes to the Magram half.", jumps = { { label = "gelkis", when = { { test = "onquest", quests = { 1382, 93227, 1368, 94873 } } } }, { label = "gelkis", when = { { quest = 1382, test = "turnedin" } } }, { label = "gelkis", when = { { quest = 93227, test = "turnedin" } } }, { label = "gelkis", when = { { quest = 1368, test = "turnedin" } } }, { label = "gelkis", when = { { quest = 94873, test = "turnedin" } } }, { label = "magram", when = { { test = "onquest", quests = { 1385, 93226, 1367, 94872 } } } }, { label = "magram", when = { { quest = 1385, test = "turnedin" } } }, { label = "magram", when = { { quest = 93226, test = "turnedin" } } }, { label = "magram", when = { { quest = 1367, test = "turnedin" } } }, { label = "magram", when = { { quest = 94872, test = "turnedin" } } } }, zone = 1443, goals = {
					{ kind = "goto", label = "Captain Pentigast", map = 1443, x = 66.7, y = 10.9, only = { factions = { "Alliance" } } },
