					{ kind = "turnin", quest = 1373, note = "Uthek the Wise: 1,000" },
				} },
				{ title = "Gelkis: totems and kills to Honored", tip = "Friendly to Honored is 6,000; after the clan's quests you are about 4,000 into it, so 2,000 to go. Molkar's Economic Warfare takes 5 Carved Centaur Totems for 750, again and again: three turn-ins, 15 totems. The Maraudine centaurs (level 36-40) of western Desolace drop them; the totems do not bind, so the auction house is the other source. Magram kills add 20 each, but Forever's kill data stops them at the end of Friendly, 1 short of Honored. At Friendly the village also has three craft orders for 1,000 each: Halea wants 3 Greater Mystic Essences, Molkar a White Bandit Mask (tailoring) and Talra a Barbaric Harness (leatherworking). Legacy Diplomat adds up to 10%.", zone = 1443, goals = {
					{ kind = "collect", item = 254432, count = 5, map = 1443, x = 29.5, y = 58, optional = true, note = "Carved Centaur Totem: Maraudine centaurs" },
					{ kind = "accept", quest = 92812, map = 1443, x = 35.6, y = 92, optional = true, note = "Economic Warfare" },
					{ kind = "turnin", quest = 92812, map = 1443, x = 35.6, y = 92, optional = true, note = "Molkar: 750" },
					{ kind = "rep", factionId = 92, standing = "Honored" },
				} },
				{ title = "Gelkis: the Valley of Bones", tip = "At Honored, Uthek sends you east to Nerlokh at the southern entrance of the Valley of Bones, in Shen'dralas. Nerlokh's quests (500 each) take you among the undead and the outcasts there: Ravaging Ravagers, Outing Outcasts and Facing the Truth, then A Cleansing Cry from Uthek, and a second line (Saving Our Own, Bone Burying, Checking Things Out) that ends with Khan Jehn: kill the Magram khan in his own village for 6,000, a title and a rare level 35 weapon. They all ask you to stay Honored or better. Honored to Revered is 12,000: the valley's quests pay about 10,600 of it, two or three Economic Warfare turn-ins the rest.", zone = 1443, goals = {
					{ kind = "level", level = 35 },
					{ kind = "accept", quest = 93034, note = "Uthek the Wise: Valley of Bones" },
					{ kind = "turnin", quest = 93034, note = "Nerlokh: 125" },
					{ kind = "accept", quest = 93035, optional = true },
					{ kind = "accept", quest = 93037, optional = true },
					{ kind = "accept", quest = 93041, optional = true },
				} },
				{ title = "Gelkis: Khan Jehn", tip = "Khan Jehn (level 37) leads the Magram from the west side of Magram Village, with his bodyguards. The kill costs the Magram 500. Uthek pays 6,000, a title, and your pick of three rare level 35 weapons: Abandoned Ferocity (two-handed axe: Strength, Stamina, Agility), Bludgeon of Betrayed Virtues (one-handed mace: Strength, Stamina, Agility) or Thrice-Damned Effigy (off-hand: Spirit, Intellect, Stamina).", when = { { quest = 93128, test = "available" } }, zone = 2652, goals = {
					{ kind = "accept", quest = 93128, note = "Nerlokh" },
					{ kind = "kill", npc = 5601, map = 1443, x = 66, y = 80.4, note = "Khan Jehn" },
					{ kind = "turnin", quest = 93128, note = "Uthek the Wise: 6,000" },
				} },
