					{ kind = "accept", quest = 92846, optional = true },
				} },
				{ title = "Magram: Khan Jehn", tip = "The ritual site is a tent by the lake in the middle of Magram Village. Orgrul pays 6,000, a title, and your pick of three rare level 35 weapons: Scavenged Magram Armament (polearm: Stamina, attack power, Agility), Greatstaff of the Necrokhans (staff: Intellect, Stamina, Spirit) or Soulsplatter Mace (main-hand mace: Intellect, Stamina, Spirit).", when = { { quest = 93196, test = "available" } }, zone = 2652, goals = {
					{ kind = "accept", quest = 93196, npc = 253136, note = "Orgrul" },
					{ kind = "turnin", quest = 93196, npc = 253136, note = "Orgrul: 6,000" },
				} },
				{ title = "Magram: totems to Exalted", tip = "From Revered on only Economic Warfare is left: Revered to Exalted is 21,000, 28 turn-ins, 140 totems.", zone = 1443, goals = {
					{ kind = "collect", item = 254432, count = 5, map = 1443, x = 29.5, y = 58, optional = true },
					{ kind = "accept", quest = 92811, npc = 253139, optional = true },
					{ kind = "turnin", quest = 92811, npc = 253139, optional = true },
					{ kind = "rep", factionId = 93, standing = "Revered" },
					{ kind = "rep", factionId = 93, standing = "Exalted", optional = true },
				} },
				{ title = "The totem recipes", tip = "Both quartermasters sell the same 12 recipes for Carved Centaur Totems, no standing needed: Enchant Bracer - Lesser Agility and - Lesser Healing Power; Greater Spellblasting and Greater Frenzy Potion; Hard Gold Gauntlet and Iron Morningstar plans; Mystic Thick Armor Kit, Silk Reagent Bag, Stormcloth Gloves and Centaur Hoofwarmers patterns; the Centaur Banner Deployment Device and Hoof-Shaped Foot Pedal schematics. Keep the totems you need for them before you hand the rest in.", label = "recipes", zone = 1443, goals = {
					{ kind = "talk", npc = 253139, optional = true, note = "Gorhak, Magram Village" },
					{ kind = "talk", npc = 253140, map = 1443, x = 35.6, y = 92, optional = true, note = "Molkar, Gelkis Village" },
				} },
			},
