		{
			id = "forever/reputation/darkspear-islands", title = "Darkspear Islands Reputation", category = "Reputation", folder = "Reputation · Battlegrounds", levels = { 30, 60 }, zone = 1413, version = 1, revision = "3bf4a3d1787c65a0e89b3ade5354fc26b2e6642953bc81277219b81c7c73f94b", keywords = { "Darkspear Raiders", "Theramore Expeditionary Force", "Darkspear Islands", "Merchant Coast", "Northwatch Hold", "Nizook Boof", "Creeg Bothunk", "Brelinda McFarry", "Bryanna Embreeze", "Darkspear Islands Mark of Honor", "Conflict at Darkspear Islands", "Darkspear Islands Clash", "The Battle for Darkspear Islands", "Darkspear Battle Tabard", "Theramore Battle Tabard", "Master of Darkspear Islands", "Legacy Point" }, rewards = { { text = "Master of Darkspear Islands: a Legacy Point at Exalted" }, { item = 272079, choice = true }, { item = 271924, choice = true }, { item = 276502 }, { item = 276504 } }, why = "Forever's new battleground: its gear comes for every bracket from 30, and Exalted gives a Legacy Point.",
			steps = {
				{ title = "Merchant Coast", tip = "The Darkspear Islands lie off the coast of Dustwallow Marsh: 15 against 15, from level 30. Hold the four capture points to gain points, faster the more you hold, and carry the flag from the middle to a base your team holds for more; the first team to 2000 points wins. The sea kills: cross on the bridges. Queue at any battlemaster or step through the portal here at the Merchant Coast, north of Ratchet. Nizook Boof pays 200 reputation for your first win. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Horde" } }, when = { { level = 40, test = "level", op = "<" } }, zone = 1413, goals = {
					{ kind = "accept", quest = 98906 },
					{ kind = "turnin", quest = 98906, note = "after a win" },
				} },
				{ title = "Merchant Coast", tip = "The Darkspear Islands lie off the coast of Dustwallow Marsh: 15 against 15, from level 30. Hold the four capture points to gain points, faster the more you hold, and carry the flag from the middle to a base your team holds for more; the first team to 2000 points wins. The sea kills: cross on the bridges. Queue at any battlemaster or step through the portal here at the Merchant Coast, north of Ratchet. Nizook Boof pays 200 reputation for your first win. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Horde" } }, when = { { level = 40, test = "level", op = ">=" }, { level = 50, test = "level", op = "<" } }, zone = 1413, goals = {
