					{ kind = "accept", quest = 98907, npc = 275276, map = 1413, x = 65, y = 35 },
					{ kind = "turnin", quest = 98907, npc = 275276, map = 1413, x = 65, y = 35, note = "after a win" },
				} },
				{ title = "Merchant Coast", tip = "The Darkspear Islands lie off the coast of Dustwallow Marsh: 15 against 15, from level 30. Hold the four capture points to gain points, faster the more you hold, and carry the flag from the middle to a base your team holds for more; the first team to 2000 points wins. The sea kills: cross on the bridges. Queue at any battlemaster or step through the portal here at the Merchant Coast, north of Ratchet. Nizook Boof pays 200 reputation for your first win. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Horde" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1413, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 98908, npc = 275276, map = 1413, x = 65, y = 35 },
					{ kind = "turnin", quest = 98908, npc = 275276, map = 1413, x = 65, y = 35, note = "after a win" },
				} },
				{ title = "Horde Warbringer", tip = "The Horde Warbringer pays 150 reputation for 3 Darkspear Islands Marks of Honor the first time (Conflict at Darkspear Islands), then 100 for every 3 more. The nearest stand at Mor'shan in the north of the Barrens and in Orgrimmar; others in Thunder Bluff and the Undercity, at Hammerfall and by the Alterac Valley gate. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Darkspear Islands marks: hand in or spend them before you reach that.", only = { factions = { "Horde" } }, when = { { level = 40, test = "level", op = "<" } }, zone = 1413, goals = {
					{ kind = "accept", quest = 98887 },
					{ kind = "collect", quest = 98887, objective = 1, item = 274895, count = 3, map = 1413, x = 65, y = 35, note = "Darkspear Islands Marks of Honor: play games" },
					{ kind = "turnin", quest = 98887 },
				} },
				{ title = "Horde Warbringer", tip = "The Horde Warbringer pays 150 reputation for 3 Darkspear Islands Marks of Honor the first time in each bracket (Conflict at Darkspear Islands), then keeps taking 3 more. The nearest stand at Mor'shan in the north of the Barrens and in Orgrimmar. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Darkspear Islands marks.", only = { factions = { "Horde" } }, when = { { level = 40, test = "level", op = ">=" }, { level = 50, test = "level", op = "<" } }, zone = 1413, goals = {
					{ kind = "level", level = 40 },
