		{
			id = "forever/reputation/darkspear-trolls", title = "Darkspear Trolls Reputation", category = "Reputation", folder = "Reputation · Cities", faction = "Horde", levels = { 12, 60 }, zone = 1454, version = 1, revision = "0fa058098a3fd20b9fb8ac3701092c7374446ea6f37d8ef02a191bfbb55624a2", legacyRevision = "ef0fa8b68ecf3efbdfb3342e0f0d1f84f63e4b06a520f45740a143ffa0ebd2ac", keywords = { "Darkspear Trolls", "Vehena", "cloth quartermaster", "cloth donation", "Runecloth", "Additional Runecloth", "Wool", "Silk", "Mageweave", "Valley of Trials", "Sen'jin Village", "Razor Hill", "Echo Isles", "raptor mount", "Zjolnir" }, rewards = { { text = "Exalted with the Darkspear Trolls" }, { item = 18788 } }, why = "Runecloth to Exalted, with the old Durotar quests as a fast extra that pays Orgrimmar too.",
			steps = {
				{ title = "Vehena: how it works", tip = "Darkspear reputation comes from quests and cloth. Vehena, the Darkspear cloth quartermaster, stands in Orgrimmar's Valley of Spirits. She takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with the Darkspear Trolls also gives a quarter as much to Orgrimmar, Thunder Bluff and the Undercity. While you level, do the Darkspear quests within 5 levels of them: Durotar at 5 to 12, Zoram Strand in Ashenvale at 19 to 27, Grom'gol in Stranglethorn at 34 to 46. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the Darkspear merchants sell to you for 10% less (the Classic rule), the raptor vendor included; at Exalted other races can buy the raptors: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60, once you have mount training. The Darkspear Trolls have no tabard or other reward.", zone = 1454, goals = {
					{ kind = "goto", label = "Vehena", map = 1454, x = 37.7, y = 87.9, note = "her donations are handed in from her window and never enter the log" },
				} },
				{ title = "Valley of Trials (optional hub)", tip = "Forever pays these old quests in full at any level. The Valley of Trials is the best of them: about 1,400 Orgrimmar and 1,400 Darkspear reputation in 25 minutes. Gornek waits in the Den, the big hut; Kaltunk stands outside it.", label = "valley", zone = 1411, goals = {
					{ kind = "accept", quest = 787, note = "Eitrigg, in Orgrimmar: The New Horde, +50" },
					{ kind = "turnin", quest = 787, note = "Gornek" },
					{ kind = "accept", quest = 4641, note = "Kaltunk: Your Place in the World, +50" },
					{ kind = "turnin", quest = 4641 },
					{ kind = "accept", quest = 788, note = "Cutting Teeth, +100" },
					{ kind = "accept", quest = 97279, note = "Wayward Weapons, +100" },
