				{ title = "The Crossroads: Sergra Darkthorn", when = { { test = "onquest", quests = { 842 } } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 842, note = "Sergra Darkthorn" },
				} },
				{ title = "Vehena: A Donation of Wool", tip = "From here it is cloth. Wool, Silk and Mageweave must all be handed in before Vehena offers the Runecloth donation, and Additional Runecloth needs the Runecloth donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, Runecloth 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey.", zone = 1440, goals = {
					{ kind = "collect", item = 2592, count = 60, map = 1440, x = 36, y = 37, note = "Wool Cloth: the Thistlefur furbolgs drop it about one kill in four" },
					{ kind = "turnin", quest = 7833, direct = true, note = "Vehena: A Donation of Wool, +150" },
				} },
				{ title = "A Donation of Silk", tip = "Silk: the Syndicate in Hillsbrad and Alterac drop it about one kill in three, or buy it.", zone = 1440, goals = {
					{ kind = "level", level = 26 },
					{ kind = "collect", item = 4306, count = 60, map = 1416, x = 57.7, y = 67.6, note = "Silk Cloth: the Syndicate" },
					{ kind = "turnin", quest = 7834, direct = true, note = "+150" },
				} },
				{ title = "A Donation of Mageweave", tip = "Mageweave: the Jadefire satyrs in southern Felwood and the Dunemaul ogres in Tanaris drop it about one kill in three, or buy it.", zone = 1416, goals = {
					{ kind = "level", level = 40 },
					{ kind = "collect", item = 4338, count = 60, map = 1448, x = 41.6, y = 85.7, note = "Mageweave Cloth: the Jadefire satyrs" },
					{ kind = "turnin", quest = 7835, direct = true, note = "+150" },
				} },
				{ title = "A Donation of Runecloth", tip = "Runecloth: the Scarlet at Tyr's Hand in the Eastern Plaguelands, the Gordok ogres outside Dire Maul in Feralas and the Twilight camps of Silithus drop it about one kill in three. The Auction House is faster if you have gold.", zone = 1448, goals = {
					{ kind = "level", level = 50 },
					{ kind = "collect", item = 14047, count = 60, map = 1423, x = 68, y = 69.5, frame = "live", note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7836, direct = true, note = "+150" },
				} },
				{ title = "Everlook: A Little Luck", tip = "Luck Be With You is level 60, so it pays in full. Harlo Wigglesworth in Everlook sends you to Witch Doctor Mau'ari, who stands in the same town. The Frostmaul Shards lie on the ground in Frostwhisper Gorge, the canyon at the south end of Winterspring, and the Frostmaul Giants there drop them too (about one in five). The giants are elite level 59 and 60 and stand close together: pick the shards at the edges, pull one giant at a time, or bring a friend.", zone = 1452, goals = {
					{ kind = "level", level = 55 },
					{ kind = "accept", quest = 6606, note = "Harlo Wigglesworth: A Little Luck" },
					{ kind = "turnin", quest = 6606, note = "Witch Doctor Mau'ari" },
					{ kind = "accept", quest = 969, note = "Luck Be With You, +100" },
					{ kind = "collect", quest = 969, objective = 1, item = 12334, count = 4, note = "Frostmaul Shards" },
					{ kind = "turnin", quest = 969 },
				} },
				{ title = "Blackrock Mountain, with a group", tip = "For The Horde! (Rend's head, Blackrock Spire) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city, the Darkspear Trolls included. Kargath in the Badlands starts the Rend chain: Warlord's Command, Eitrigg's Wisdom, then For The Horde!. Take them when your group goes. The Spider God chain of the Undercity guide (Zul'Farrak and the Hinterlands) pays 225 Darkspear on the way.", zone = 1418, goals = {
					{ kind = "accept", quest = 4903, optional = true, note = "Warlord Goretooth: Warlord's Command, a group of five" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (a troll starts at Friendly 1,000: 100 hand-ins; an Undead or Skyborne at Neutral 2,000 first needs 20 more to reach Friendly). Hand in every 20 you carry, one after another.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7837, optional = true, direct = true, note = "Vehena: Additional Runecloth, +50" },
					{ kind = "rep", factionId = 530, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth. The Auction House price of a stack decides whether to farm or buy.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7837, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "rep", factionId = 530, standing = "Revered" },
				} },
				{ title = "Additional Runecloth to Exalted", tip = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. At Exalted, Zjolnir in Sen'jin Village sells the raptors to every Horde race: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7837, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "rep", factionId = 530, standing = "Exalted" },
					{ kind = "talk", npc = 7952, optional = true, note = "Zjolnir: the raptors" },
				} },
			},
		},
		{
			id = "forever/reputation/darnassus", title = "Darnassus Reputation", category = "Reputation", folder = "Reputation · Cities", faction = "Alliance", levels = { 12, 60 }, zone = 1438, version = 1, revision = "0343b86a0b42786208cf360200671aaba51690b9df345bc245c591026c925ee1", legacyRevision = "23314e2b587646ff9468e69f66cbf4024cc6232f4b11ea8564fb052896e1f42a", keywords = { "Darnassus", "Raedon Duskstriker", "cloth quartermaster", "Craftsmen's Terrace", "Additional Runecloth", "Wool", "Silk", "Mageweave", "Runecloth", "nightsaber", "Swift Frostsaber", "grey quests", "Shadowglen", "Dolanaar", "Auberdine", "Morrowgrain", "Un'Goro Soil", "Evergreen Pouch", "Mathrengyl Bearwalker", "The True Masters" }, rewards = { { text = "Exalted with Darnassus: in Classic, other races may buy the nightsabers" }, { text = "Morrowgrain to Darnassus: 50 reputation for every 10 Morrowgrain, as often as you like" }, { text = "About 3,700 Darnassus reputation from low-level quests in Teldrassil and Darkshore" } }, why = "Cloth, Morrowgrain and the Teldrassil and Darkshore hubs: the quests pay most while you level.",
			steps = {
				{ title = "Raedon Duskstriker, the cloth quartermaster", tip = "Raedon Duskstriker takes cloth for Darnassus; he stands in the Craftsmen's Terrace, in the north-east of Darnassus, by the tailors. Each first donation of 60 Wool, Silk, Mageweave and Runecloth pays 150 reputation once; after the Runecloth one, Additional Runecloth pays 50 for every 20 Runecloth, as often as you like. The Auction House in the Tradesmen's Terrace is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do Teldrassil (levels 1-12), Darkshore (11-20) and Ashenvale (18-30) while you level through them. After the donations come The True Masters in the Burning Steppes and Morrowgrain, a second repeatable turn-in; then the optional hubs, best rate first: Shadowglen (about 35 a minute at full value), Dolanaar (28), Auberdine (23). Every Darnassus gain also gives a quarter as much to Stormwind, Ironforge and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain.", zone = 1457, goals = {
					{ kind = "level", level = 12 },
