					{ kind = "turnin", quest = 7799 },
				} },
				{ title = "A Donation of Runecloth", tip = "Runecloth drops from humanoids level 50 and up: the Deadwood furbolgs of Felwood, the Winterfall furbolgs of Winterspring, the Scourge cultists of the Plaguelands. Keep any Runecloth past the first 60 for Additional Runecloth.", zone = 1457, goals = {
					{ kind = "level", level = 50 },
					{ kind = "collect", item = 14047, count = 60, nearest = true },
					{ kind = "accept", quest = 7800 },
					{ kind = "turnin", quest = 7800 },
				} },
				{ title = "Morgan's Vigil: Dragonkin Menace", tip = "Helendis Riverhorn at Morgan's Vigil, in the south-east of the Burning Steppes, starts The True Masters: 175 Darnassus reputation for two quests (level 54: in Classic 140 at 60), and the chain goes on to Stormwind Keep for 175 Stormwind. The Black Broodlings and the Black Drake live on the slopes north of the Vigil; the Black Dragonspawn and Black Wyrmkin west of it, in the middle of the zone.", zone = 1428, goals = {
					{ kind = "level", level = 55 },
					{ kind = "accept", quest = 4182, note = "Dragonkin Menace, +100" },
					{ kind = "kill", quest = 4182, objective = 1, npc = 7047, count = 15, note = "Black Broodling" },
					{ kind = "kill", quest = 4182, objective = 2, npc = 7040, count = 10, note = "Black Dragonspawn" },
					{ kind = "kill", quest = 4182, objective = 3, npc = 7044, note = "Black Drake" },
					{ kind = "kill", quest = 4182, objective = 4, npc = 7041, count = 4, note = "Black Wyrmkin" },
					{ kind = "turnin", quest = 4182 },
					{ kind = "accept", quest = 4183, note = "The True Masters, +75" },
				} },
				{ title = "Lakeshire: Magistrate Solomon", tip = "Magistrate Solomon waits in the town hall of Lakeshire; his next quest takes you to Stormwind Keep (the Stormwind guide follows it). Other Darnassus quests at this level, for when you pass by: Erelas Ambersky in Rut'theran Village has a wildkin chain into Winterspring (325 in all, with Ranshalla's escort), Arei's escort in Felwood pays 150 after the Emerald Sanctuary's chain, Mulgris Deepriver at the Writhing Haunt in the Western Plaguelands 100 for the Glyphed Oaken Branch, and Put Her Down in Upper Blackrock Spire 100 with a group.", zone = 1433, goals = {
					{ kind = "turnin", quest = 4183 },
				} },
				{ title = "Morrowgrain (optional)", tip = "Morrowgrain to Darnassus takes 10 Morrowgrain for 50, as often as you like, and pays in full at 60. The chain before it is level 50: 220. Innkeeper Saelienne sends you to Arch Druid Fandral Staghelm in the Cenarion Enclave; he wants 20 Un'Goro Soil. (The innkeepers of Stormwind and Ironforge give the same start.)", label = "dn-morrowgrain-start", zone = 1457, goals = {
					{ kind = "accept", quest = 3763, note = "Assisting Arch Druid Staghelm, +10" },
				} },
				{ title = "Cenarion Enclave", when = { { label = "dn-morrowgrain-start", test = "done" } }, zone = 1457, goals = {
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
				} },
				{ title = "Morrowgrain (optional)", when = { { label = "dn-morrowgrain-start", test = "done" } }, label = "dn-morrowgrain", zone = 1457, goals = {
					{ kind = "turnin", quest = 3763, note = "Arch Druid Fandral Staghelm" },
					{ kind = "accept", quest = 3764, note = "Un'Goro Soil, +100" },
				} },
				{ title = "Un'Goro Crater: Un'Goro Soil", tip = "Dig Un'Goro Soil from the dirt mounds all over the crater; most of the crater's beasts and the Gorishi silithids drop it too, about one kill in three. Take far more than 20: every pouch use takes 2, about 18 for each 10 Morrowgrain.", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1449, goals = {
					{ kind = "collect", quest = 3764, objective = 1, item = 11018, count = 20, note = "Un'Goro Soil" },
				} },
				{ title = "Darnassus: Morrowgrain Research", tip = "Jenal, beside Fandral in the Cenarion Enclave, takes the soil. Mathrengyl Bearwalker sells the Evergreen Pouch and Packets of Tharlendris Seeds. With a seed packet and 2 Un'Goro Soil in your bags, use the pouch to grow an Evergreen Herb Casing and open it: about one casing in three holds Morrowgrain (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things.", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 3764, note = "Jenal" },
				} },
				{ title = "Cenarion Enclave", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1457, goals = {
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
				} },
				{ title = "Darnassus: Morrowgrain Research", tip = "Jenal, beside Fandral in the Cenarion Enclave, takes the soil. Mathrengyl Bearwalker sells the Evergreen Pouch and Packets of Tharlendris Seeds. With a seed packet and 2 Un'Goro Soil in your bags, use the pouch to grow an Evergreen Herb Casing and open it: about one casing in three holds Morrowgrain (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things.", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1457, goals = {
