				{ title = "Cenarion Enclave", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1457, goals = {
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6 },
				} },
				{ title = "Darnassus: Morrowgrain Research", tip = "Jenal, beside Fandral in the Cenarion Enclave, takes the soil. Mathrengyl Bearwalker sells the Evergreen Pouch and Packets of Tharlendris Seeds. With a seed packet and 2 Un'Goro Soil in your bags, use the pouch to grow an Evergreen Herb Casing and open it: about one casing in three holds Morrowgrain (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things.", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1457, goals = {
					{ kind = "turnin", quest = 3781, note = "Mathrengyl Bearwalker" },
					{ kind = "accept", quest = 3785, note = "Morrowgrain Research, +100" },
					{ kind = "buy", npc = 4217, item = 11020, note = "Evergreen Pouch" },
					{ kind = "buy", npc = 4217, item = 11022, count = 10, note = "Packet of Tharlendris Seeds" },
					{ kind = "collect", quest = 3785, objective = 1, item = 11040, count = 10, map = 1457, x = 35.4, y = 8.4, note = "Morrowgrain: grow it here and open the casings" },
					{ kind = "turnin", quest = 3785 },
				} },
				{ title = "Morrowgrain to Darnassus", tip = "Every 10 Morrowgrain: 50 reputation at Mathrengyl Bearwalker. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 Un'Goro Soil and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the Runecloth. Quintis Jonespyre at Feathermoon Stronghold in Feralas takes Morrowgrain at the same rate, 25 for 5, after his own quest.", when = { { label = "dn-morrowgrain", test = "done" } }, zone = 1457, goals = {
					{ kind = "goto", label = "Cenarion Enclave", map = 1457, x = 35.8, y = 11.6, optional = true },
					{ kind = "collect", item = 11040, count = 10, map = 1457, x = 35.4, y = 8.4, optional = true, note = "Morrowgrain" },
					{ kind = "turnin", quest = 3803, optional = true, direct = true, note = "Mathrengyl Bearwalker: Morrowgrain to Darnassus, +50" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). The True Masters and the Morrowgrain chain above take 8 turn-ins off, and every 10 Morrowgrain you hand in counts as one more; each hub you did takes 20 to 28 more off. More quests pay Darnassus, in full while they are no more than 5 levels below you: the rest of Darkshore (about 3,400 more), Astranaar in Ashenvale (about 3,900) and Feathermoon in Feralas (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", zone = 1457, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7801, optional = true, direct = true },
					{ kind = "rep", factionId = 69, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored: in Classic Darnassus's vendors take 10% off for you, Lelanai's nightsabers (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", zone = 1457, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7801, optional = true, direct = true },
