		{
			id = "forever/reputation/hydraxian-waterlords", title = "Hydraxian Waterlords Reputation", category = "Reputation", folder = "Reputation · Raids and dungeons", levels = { 60, 60 }, zone = 1447, version = 1, revision = "9490bee5294d4c2377cef2126217442f0071c8e683b669e9e2542da990cfdd8c", legacyRevision = "a6c5201aa5533b642a510425c175c9bc51e2505d60e4167272abeb401afddccb", keywords = { "Hydraxian Waterlords", "Duke Hydraxis", "Aqual Quintessence", "Eternal Quintessence", "Molten Core", "Majordomo Executus", "Ragnaros", "Dust Stormer", "Desert Rumbler", "Pyroguard Emberseer", "Eye of the Emberseer", "Hands of the Enemy", "A Hero's Reward", "Ocean's Breeze", "Tidal Loop", "fire resistance", "Lothos Riftwaker", "attunement" }, rewards = { { item = 22754 }, { item = 17333 }, { item = 18399, choice = true }, { item = 18398, choice = true } }, why = "Aqual Quintessence to douse the Molten Core's runes, the reusable Eternal Quintessence at Revered and a fire resistance ring.",
			steps = {
				{ title = "Duke Hydraxis", tip = "Duke Hydraxis stands on a small island off the east coast of Azshara; swim out to him. Everyone starts Neutral with the Waterlords, and nearly all of their reputation comes from killing the servants of fire, air and earth: the quests themselves pay nothing until the last one. Take both quests: the chain goes on only when both are done. Everything past Honored happens in the Molten Core, a raid of 40 that is not among the first raids Blizzard has announced for Forever; until it opens, Honored is as far as the Waterlords go. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%.", zone = 1447, goals = {
					{ kind = "accept", quest = 6804 },
					{ kind = "accept", quest = 6805 },
				} },
				{ title = "Stormers and Rumblers", tip = "Dust Stormers and Desert Rumblers drift around the Crystal Vale in the north-west of Silithus. Each kill also pays 5 reputation while you are Neutral or Friendly, so stay if you mean to farm (next steps).", zone = 1451, goals = {
					{ kind = "kill", quest = 6805, objective = 1, npc = 11744, count = 15, note = "Dust Stormer" },
					{ kind = "kill", quest = 6805, objective = 2, npc = 11746, count = 15, note = "Desert Rumbler" },
				} },
				{ title = "Poisoned Water", tip = "Use the Aspect of Neptulon on a Blighted Horror or a Plague Monstrosity: it turns into a Discordant Surge. Kill the surge and loot its Discordant Bracers. Twelve are needed, and the vial must still be in your bags at the turn-in.", zone = 1423, goals = {
					{ kind = "use", item = 17310, map = 1423, x = 44, y = 41, optional = true, note = "Aspect of Neptulon, on the poisoned elementals" },
					{ kind = "collect", quest = 6804, objective = 1, item = 17309, count = 12, note = "Discordant Bracers" },
				} },
				{ title = "Back to Duke Hydraxis", zone = 1447, goals = {
					{ kind = "turnin", quest = 6804 },
					{ kind = "turnin", quest = 6805 },
					{ kind = "accept", quest = 6821 },
				} },
				{ title = "Eye of the Emberseer", tip = "Pyroguard Emberseer is a boss in Upper Blackrock Spire, inside Blackrock Mountain: a group of up to ten, and someone needs the Seal of Ascension to open the door. He drops the Eye and pays 50 reputation per kill up to 11,999 of 12,000 Honored. Lord Incendius in Blackrock Depths pays 15 the same way.", zone = 1428, goals = {
					{ kind = "collect", quest = 6821, objective = 1, item = 17322, map = 1428, x = 26.4, y = 24.5, optional = true, note = "Eye of the Emberseer: raid of ten" },
					{ kind = "turnin", quest = 6821, optional = true },
					{ kind = "accept", quest = 6822, optional = true },
				} },
				{ title = "Attunement to the Core", tip = "Lothos Riftwaker in Blackrock Mountain attunes you to the Molten Core: bring him a Core Fragment from beside the Molten Core's portal at the bottom of Blackrock Depths. Once attuned, he can send you straight into the Molten Core.", zone = 1427, goals = {
					{ kind = "accept", quest = 7848, mapHint = 1428, optional = true },
					{ kind = "collect", quest = 7848, objective = 1, item = 18412, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Core Fragment, at the portal in Blackrock Depths" },
					{ kind = "turnin", quest = 7848, mapHint = 1428, optional = true },
				} },
				{ title = "The Molten Core", tip = "The Molten Core is a raid of 40. Kill one Molten Giant, Firelord, Ancient Core Hound and Lava Surger for Duke Hydraxis. Every elemental there pays: Firewalkers, Flameguards, Lava Elementals, Lava Reavers and Molten Destroyers 40, Firelords, Lava Surgers, Molten Giants and Ancient Core Hounds 20, up to 11,999 of 12,000 Honored; about 3,360 for a full clear of the trash. The bosses pay 100 each (Golemagg 150, Ragnaros 200).", zone = 1427, goals = {
					{ kind = "kill", quest = 6822, objective = 1, npc = 11658, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Molten Giant: raid of 40" },
					{ kind = "kill", quest = 6822, objective = 2, npc = 11668, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Firelord" },
					{ kind = "kill", quest = 6822, objective = 3, npc = 11673, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Ancient Core Hound" },
					{ kind = "kill", quest = 6822, objective = 4, npc = 12101, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Lava Surger" },
				} },
				{ title = "Elementals to Honored", tip = "Neutral to Honored is 9,000 reputation, and Agent of Hydraxis asks for Honored. One Molten Core clear pays about 4,000 of it. Without a raid it comes from the elementals: 5 per Dust Stormer, Desert Rumbler or Greater Obsidian Elemental (the Burning Steppes), about 1,800 kills from Neutral. They stop at 5,999 of 6,000 Friendly, one point short, so the last point needs a kill that still counts there: Huricanian, a rare air elemental in the Crystal Vale (25), or Lord Incendius at the Black Anvil in Blackrock Depths (15, a five-player dungeon). Those two and Pyroguard Emberseer keep paying through Honored as well.", zone = 1451, goals = {
					{ kind = "kill", npc = 11744, optional = true, note = "Dust Stormer, 5" },
					{ kind = "kill", npc = 11746, optional = true, note = "Desert Rumbler, 5" },
					{ kind = "kill", npc = 14478, optional = true, note = "Huricanian, rare, 25" },
					{ kind = "kill", npc = 9017, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Lord Incendius, Blackrock Depths: 15, group up" },
					{ kind = "rep", factionId = 749, standing = "Honored" },
				} },
				{ title = "Agent of Hydraxis", tip = "Back to Duke Hydraxis. Agent of Hydraxis is done the moment you are Honored.", zone = 1447, goals = {
					{ kind = "turnin", quest = 6822, optional = true },
					{ kind = "accept", quest = 6823, optional = true },
					{ kind = "turnin", quest = 6823, optional = true },
					{ kind = "accept", quest = 6824, optional = true },
				} },
				{ title = "Hands of the Enemy", tip = "Lucifron, Gehennas, Shazzrah and Sulfuron Harbinger are Molten Core bosses: each drops his hand for the quest.", zone = 1427, goals = {
					{ kind = "collect", quest = 6824, objective = 1, item = 17332, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Hand of Shazzrah: raid of 40" },
					{ kind = "collect", quest = 6824, objective = 2, item = 17329, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Hand of Lucifron" },
					{ kind = "collect", quest = 6824, objective = 3, item = 17331, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Hand of Gehennas" },
					{ kind = "collect", quest = 6824, objective = 4, item = 17330, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Hand of Sulfuron" },
				} },
				{ title = "A Hero's Reward", tip = "Hand in the hands, then dive under the surf at the southern foot of the island: Hydraxis' Coffer holds your ring and pays the only quest reputation the Waterlords give, 200. From now on, while you are Honored or better, the Duke hands you Aqual Quintessence: pour it on a rune in the Molten Core to douse it. With every rune doused, Majordomo Executus comes out, and after him Ragnaros.", zone = 1447, goals = {
					{ kind = "turnin", quest = 6824, optional = true },
					{ kind = "accept", quest = 7486, optional = true },
					{ kind = "turnin", quest = 7486, optional = true, choose = { { item = 18399 }, { item = 18398 } } },
					{ kind = "collect", npc = 13278, item = 17333, optional = true, note = "Aqual Quintessence, ask the Duke" },
				} },
				{ title = "Molten Core to Revered", tip = "Honored to Revered is 12,000 reputation. The trash still counts, so a full clear pays about 3,360 plus 700 from the seven bosses, 150 from Golemagg and 200 from Ragnaros: about three clears. Lord Incendius (15) and Pyroguard Emberseer (50) count too while you are Honored. The trash stops at 11,999 of 12,000 Honored; the bosses carry you over.", zone = 1427, goals = {
					{ kind = "kill", npc = 11666, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Firewalker, 40" },
					{ kind = "kill", npc = 11667, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Flameguard, 40" },
					{ kind = "kill", npc = 12076, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Lava Elemental, 40" },
					{ kind = "kill", npc = 12118, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Lucifron and the other bosses, 100: they carry you past 11,999" },
					{ kind = "kill", npc = 11988, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Golemagg the Incinerator, 150" },
					{ kind = "kill", npc = 11502, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Ragnaros, 200" },
					{ kind = "rep", factionId = 749, standing = "Revered" },
				} },
				{ title = "The Eternal Quintessence", tip = "At Revered the Duke gives you the Eternal Quintessence: it does the Aqual Quintessence's work and is not used up, so you never come back for another vial.", zone = 1447, goals = {
					{ kind = "collect", npc = 13278, item = 22754, optional = true, note = "Eternal Quintessence, ask the Duke" },
				} },
				{ title = "Molten Core to Exalted", tip = "Revered to Exalted is 21,000 reputation. The trash has stopped, but all nine bosses still pay while you are Revered: 100 each from the seven, 150 from Golemagg and 200 from Ragnaros, 1,050 a clear: about 20 clears. The seven stop at 20,999 of 21,000 Revered, so the last point comes from Golemagg or Ragnaros, and from Exalted on only those two pay.", zone = 1427, goals = {
					{ kind = "kill", npc = 12118, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Lucifron, 100" },
