		{
			id = "forever/reputation/ironforge", title = "Ironforge Reputation", category = "Reputation", folder = "Reputation · Cities", faction = "Alliance", levels = { 12, 60 }, zone = 1455, version = 1, revision = "fd6861297c5b98df7cae3c328449510bb454d78437c23723d0898fc658eea68c", legacyRevision = "4f6b55461ee65387d2c4daefb45f194a68dac130cb586600b01144ebf5961df1", keywords = { "Ironforge", "Mistina Steelshield", "cloth quartermaster", "Additional Runecloth", "Wool", "Silk", "Mageweave", "Runecloth", "ram", "Swift Gray Ram", "grey quests", "Coldridge Valley", "Kharanos", "Dun Morogh", "Oralius", "Morgan's Vigil", "Blackrock Medallion", "Enraged Wildkin", "Alterac Valley" }, rewards = { { text = "Exalted with Ironforge: in Classic, other races may buy the rams" }, { text = "About 600 Ironforge reputation from level 52-59 quests in the Burning Steppes and Winterspring; Alterac Valley's quests pay Ironforge too" }, { text = "About 2,900 Ironforge reputation from low-level quests in Dun Morogh, most of it paid to Gnomeregan too" } }, why = "Cloth, the Burning Steppes quests and the Dun Morogh hubs, which pay Gnomeregan too; Alterac Valley adds more.",
			steps = {
				{ title = "Mistina Steelshield, the cloth quartermaster", tip = "Mistina Steelshield takes cloth for Ironforge; she stands outside the clothier on the north side of the Great Forge, among the tailors. Each first donation of 60 Wool, Silk, Mageweave and Runecloth pays 150 reputation once; after the Runecloth one, Additional Runecloth pays 50 for every 20 Runecloth, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do Dun Morogh (levels 1-12), Loch Modan (10-20) and the Wetlands (20-30) while you level through them. After the donations come the level 52-59 quests of the Burning Steppes and Winterspring (about 600), then the optional Dun Morogh hubs, best rate first: Coldridge Valley (about 37 a minute at full value), Kharanos (26), the quarry (17). Every Ironforge gain also gives a quarter as much to Stormwind, Darnassus and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain.", zone = 1455, goals = {
					{ kind = "level", level = 12 },
