					{ kind = "accept", quest = 7805 },
					{ kind = "turnin", quest = 7805 },
				} },
				{ title = "Ironforge: Royal Historian Archesonus", tip = "These quests are level 52 to 59, so they pay in full at 60: about 600 Ironforge reputation. Royal Historian Archesonus stands beside King Magni in the High Seat; he sends you to the ruins of Thaurissan in the Burning Steppes.", zone = 1455, goals = {
					{ kind = "level", level = 55 },
					{ kind = "accept", quest = 3702, note = "The Smoldering Ruins of Thaurissan, +10" },
					{ kind = "kill", quest = 3702, objective = 1, npc = 8879, text = "Hear Royal Historian Archesonus out" },
					{ kind = "turnin", quest = 3702 },
					{ kind = "accept", quest = 3701, note = "The Smoldering Ruins of Thaurissan, +100" },
				} },
				{ title = "Morgan's Vigil: Oralius", tip = "Morgan's Vigil sits in the south-east of the Burning Steppes, at the top of the pass up from Redridge. Oralius wants the Firegut ogres of Dreadmaul Rock, north of the Vigil, thinned out; the Brutes keep to the rock's east side.", zone = 1428, goals = {
					{ kind = "accept", quest = 4283, note = "FIFTY! YEP!, +100" },
					{ kind = "accept", quest = 3823, note = "Extinguish the Firegut, +100" },
					{ kind = "kill", quest = 3823, objective = 1, npc = 7034, count = 15, note = "Firegut Ogre Mage" },
					{ kind = "kill", quest = 3823, objective = 2, npc = 7033, count = 15, note = "Firegut Ogre" },
