					{ kind = "turnin", quest = 3823 },
					{ kind = "accept", quest = 3824, note = "Gor'tesh the Brute Lord, +100" },
				} },
				{ title = "Thaurissan and Blackrock Stronghold", tip = "The Thaurissan relics are the carved stones in the ruins around Flame Crest, west along the road: click twelve of them. Gor'tesh and the Blackrock orcs and worgs hold the camps at the foot of Blackrock Mountain, further west; each may drop a Blackrock Medallion (about one kill in three), and Oralius wants fifty. The orcs are level 50 and up, so they drop Runecloth too: keep it for Additional Runecloth.", zone = 1428, goals = {
					{ kind = "interact", quest = 3701, objective = 1, object = 153556, note = "Thaurissan Relic" },
					{ kind = "collect", quest = 3824, objective = 1, item = 11080, note = "Gor'tesh's Lopped Off Head" },
					{ kind = "collect", quest = 4283, objective = 1, item = 11467, count = 50, note = "Blackrock Medallion" },
				} },
				{ title = "Morgan's Vigil: hand in", tip = "Plant Gor'tesh's head on the soft dirt mound at the top of Dreadmaul Rock.", zone = 1428, goals = {
					{ kind = "turnin", quest = 4283 },
					{ kind = "turnin", quest = 3824 },
					{ kind = "accept", quest = 3825, note = "Ogre Head On A Stick = Party, +100" },
					{ kind = "interact", quest = 3825, objective = 1, object = 160840, note = "Soft Dirt Mound" },
					{ kind = "turnin", quest = 3825 },
				} },
				{ title = "Ironforge: Archesonus again", tip = "With a group, Blackrock Depths pays more: Archesonus's chain goes on with Kharan Mighthammer (100) and The Fate of the Kingdom (Emperor Thaurissan, 150), and Oralius takes 20 Dark Iron Fanny Packs from the dwarves inside (The Good Stuff, 100). Alterac Valley, from level 51, pays Ironforge too: its one-time quests about 1,900 as your Stormpike standing grows (the Alterac Valley guide walks them), and inside the battle 25 for every 10 Irondeep or Coldtooth Supplies and 50 for 5 Storm Crystals, as often as you like.", zone = 1455, goals = {
					{ kind = "turnin", quest = 3701 },
				} },
				{ title = "Winterspring: Enraged Wildkin", tip = "Harlo Wigglesworth in Everlook sends you west to Jaron Stoneshaper at Starfall Village. Jaron's damaged crate and wrecked wagon lie at Mazthoril, down the valley to the south-east; his supplies lie around the wagon and the owlbeasts nearby carry his amulet. The last quest is level 59: 100 Ironforge in full.", zone = 1452, goals = {
					{ kind = "accept", quest = 6604, note = "Harlo Wigglesworth" },
					{ kind = "turnin", quest = 6604, note = "Jaron Stoneshaper" },
					{ kind = "accept", quest = 4861 },
