					{ kind = "accept", quest = 4863 },
					{ kind = "turnin", quest = 4863, note = "Jaron's Wagon" },
					{ kind = "accept", quest = 4864, note = "Enraged Wildkin, +100" },
					{ kind = "collect", quest = 4864, objective = 1, item = 12525, note = "Jaron's Supplies" },
					{ kind = "collect", quest = 4864, objective = 2, item = 12524, note = "Blue-feathered Amulet" },
					{ kind = "turnin", quest = 4864, note = "Jaron Stoneshaper" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a Human, Night Elf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Dwarves start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). The level 52-59 quests above take 12 turn-ins off; each Dun Morogh hub you did takes 10 to 26 more off. More hubs pay Ironforge, in full while they are no more than 5 levels below you: Thelsamar in Loch Modan (about 3,500 in all) and Menethil Harbor in the Wetlands (about 2,500). From level 51 Alterac Valley's one-time quests add about 1,900. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", zone = 1455, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7806, optional = true, direct = true },
					{ kind = "rep", factionId = 47, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored: in Classic Ironforge's vendors take 10% off for you, Veron Amberstill's rams (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", zone = 1455, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7806, optional = true, direct = true },
					{ kind = "rep", factionId = 47, standing = "Revered" },
				} },
				{ title = "Additional Runecloth to Exalted", tip = "Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 Runecloth. At Exalted, Veron Amberstill at Amberstill Ranch in eastern Dun Morogh sells his rams to other races in Classic; the Ram and Swift Ram guides cover them.", zone = 1455, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7806, optional = true, direct = true },
					{ kind = "rep", factionId = 47, standing = "Exalted" },
				} },
