			id = "forever/reputation/kirin-tor", title = "Kirin Tor Reputation", category = "Reputation", folder = "Reputation · World", faction = "Alliance", levels = { 28, 60 }, zone = 1416, version = 1, revision = "5f4ae60cd49dfdbe1e7155c922fae266e224e50c6ef9984981296e2a24383eee", keywords = { "Kirin Tor", "Dalaran", "City of Dalaran", "Archmage Alvareaux", "Elizabeth Ross", "Archmage Modera", "Azure Skyforged", "Azure Gustwoven", "Azure Windraveled", "Azure Stormsewn", "Kirin Tor Tabard", "Skyborne" }, rewards = { { item = 285327 }, { text = "Eight Azure helm and shoulder recipes at Friendly (Blacksmithing, Leatherworking, Tailoring)" } }, why = "New in Forever: Dalaran's mages sell Azure armour recipes at Friendly and their tabard at Exalted.",
			steps = {
				{ title = "Skyborne: the recipes now", tip = "Alliance Skyborne start Friendly with the Kirin Tor, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so Archmage Alvareaux sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the Kirin Tor banners in Dalaran, past the Sky Enclave. Buy the ones for your profession.", only = { races = { "Skyborne" } }, zone = 1416, goals = {
					{ kind = "vendor", npc = 32287 },
					{ kind = "buy", npc = 32287, item = 276984, optional = true, note = "Plans: Azure Skyforged Helm (Blacksmithing)" },
					{ kind = "buy", npc = 32287, item = 276985, optional = true, note = "Plans: Azure Skyforged Pauldrons (Blacksmithing)" },
					{ kind = "buy", npc = 32287, item = 276986, optional = true, note = "Pattern: Azure Gustwoven Hood (Leatherworking)" },
					{ kind = "buy", npc = 32287, item = 276987, optional = true, note = "Pattern: Azure Gustwoven Spaulders (Leatherworking)" },
