					{ kind = "buy", npc = 32287, item = 276989, optional = true, note = "Pattern: Azure Windraveled Drapes (Leatherworking)" },
					{ kind = "buy", npc = 32287, item = 276990, optional = true, note = "Pattern: Azure Stormsewn Cowl (Tailoring)" },
					{ kind = "buy", npc = 32287, item = 276991, optional = true, note = "Pattern: Azure Stormsewn Epaulets (Tailoring)" },
				} },
				{ title = "An Alarming Request", tip = "Emissary Jacques of the Kirin Tor waits in Southshore. He sends you to Archmage Modera's image by the shore of Lordamere Lake, outside Dalaran's walls. The Kirin Tor quests start at level 24 to 30 and pay full reputation at any level in Forever.", zone = 1424, goals = {
					{ kind = "level", level = 30 },
					{ kind = "accept", quest = 92432 },
				} },
				{ title = "Archmage Modera's image", zone = 1421, goals = {
					{ kind = "turnin", quest = 92432 },
					{ kind = "accept", quest = 92458, note = "you get the Dalaran Sewer Key with it" },
					{ kind = "accept", quest = 92457 },
				} },
				{ title = "The City of Dalaran", tip = "The City of Dalaran is a dungeon for levels 28 to 33: go in through the sewers with the key Modera gave you. The arcane elementals throughout the city count for Starving Arcane. The Shade of the Archmage, the last boss, waits in the Purple Parlor above the Violet Citadel (a portal by Archmage Modera in the Citadel takes you up) and drops the Arcane Mote. Beta players saw every kill in the dungeon pay Kirin Tor reputation, the bosses the most. Group of five advised below level 35.", zone = 1416, goals = {
					{ kind = "kill", quest = 92457, objective = 1, npc = 247003, count = 8, map = 1416, x = 8.5, y = 59.3, frame = "live", note = "Seeking Remnant" },
					{ kind = "kill", quest = 92457, objective = 2, npc = 247001, count = 8, map = 1416, x = 8.5, y = 59.3, frame = "live", note = "Saturated Remnant" },
					{ kind = "kill", quest = 92457, objective = 3, npc = 246600, count = 8, map = 1416, x = 8.5, y = 59.3, frame = "live", note = "Mana Echo" },
					{ kind = "collect", quest = 92458, objective = 1, item = 251961, map = 1416, x = 8.5, y = 59.3, frame = "live", note = "Arcane Mote, from the Shade of the Archmage" },
				} },
				{ title = "Back to Modera's image", zone = 1421, goals = {
					{ kind = "turnin", quest = 92458 },
					{ kind = "turnin", quest = 92457 },
					{ kind = "accept", quest = 92459 },
				} },
				{ title = "Archmage Celindra", tip = "Archmage Celindra waits in the Violet Citadel in Dalaran.", zone = 1416, goals = {
					{ kind = "turnin", quest = 92459 },
				} },
				{ title = "Past Due", tip = "Magus Olvek in Dalaran wants a book back from Arcanist Doan, the last boss of the Scarlet Monastery's Library (levels 33 to 41), in Tirisfal Glades.", zone = 1416, goals = {
					{ kind = "level", level = 33 },
					{ kind = "accept", quest = 96800 },
				} },
				{ title = "Arcanist Doan", tip = "The Scarlet Monastery stands in the north-east of Tirisfal Glades; Doan waits at the end of the Library wing. Group of five advised below level 40.", zone = 1420, goals = {
					{ kind = "collect", quest = 96800, objective = 1, item = 273169, map = 1420, x = 82.6, y = 33.8, frame = "live", note = "The Lost Magic of the Runemasters, from Arcanist Doan" },
				} },
				{ title = "Back to Magus Olvek", zone = 1416, goals = {
					{ kind = "turnin", quest = 96800 },
				} },
				{ title = "City of Dalaran runs to Friendly", tip = "The quests leave a non-Skyborne at about 320 of the 3,000 Friendly needs. The rest comes from kills in the City of Dalaran dungeon: run it until Friendly. How much each kill pays is not in the game's data; the bosses pay the most. At 60 you clear it alone.", zone = 1416, goals = {
					{ kind = "rep", factionId = 2740, standing = "Friendly" },
				} },
				{ title = "Archmage Alvareaux: the Azure recipes", tip = "Archmage Alvareaux sells the Azure helm and shoulder recipes at Friendly, 10g each (skill 175). He stands upstairs in the building with the Kirin Tor banners in Dalaran. Buy the ones for your profession.", zone = 1416, goals = {
					{ kind = "vendor", npc = 32287 },
