		{
			id = "forever/reputation/merchants-favor", title = "Supply Factions Reputation", category = "Reputation", folder = "Reputation · World", levels = { 10, 60 }, zone = 1433, version = 1, revision = "8f2b8931033c82b8b16ed34dc90402dcb8d16271c1dc8641558127ae4a9a79de", legacyRevision = "0a5ee7966c10ebadbe3626c03360bf5bb92403f093f0959e1eefe7f0edf81c82", keywords = { "Azeroth Commerce Authority", "Durotar Supply and Logistics", "Merchant's Favor", "Craftsman's Writ", "Shipping Label", "Crate Return", "Forged Delivery Receipt", "Forger's Quill", "Waylaid Crate", "Marcy Baker", "Dokimi", "Tamelyn Aldridge", "Gishah", "Three Corners", "Crossroads", "Pack Kodo", "Minimule", "Packmule Treat", "tabard" }, rewards = { { item = 262766 }, { item = 284664 }, { item = 262765 }, { item = 262764 }, { text = "Profession recipes at Friendly and Honored" } }, why = "Forever's trade camps: their best recipes, the Minimule and the Pack Kodo need standing, not only Merchant's Favor.",
			steps = {
				{ title = "Your first Waylaid Crate or writ", tip = "From level 10, mobs anywhere drop Waylaid Crates and sealed writs (Journeyman's, Expert's and Artisan's). Fill a crate with one of the bundles it lists (right-click it), or open a sealed writ: by beta reports, the first time you do either you also get a Shipping Label. Right-click the label to start its quest. Crates and writs can be traded, so the Auction House sells them too.", zone = 1433, goals = {
					{ kind = "accept", quest = 98247, only = { factions = { "Alliance" } } },
					{ kind = "accept", quest = 98248, only = { factions = { "Horde" } } },
				} },
				{ title = "Three Corners: the Shipping Label", tip = "The Azeroth Commerce Authority camp is at Three Corners, where the roads from Elwynn Forest, Duskwood and Lakeshire meet in western Redridge. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to Marcy Baker too, but they pay only Merchant's Favor and silver, never reputation.", only = { factions = { "Alliance" } }, zone = 1433, goals = {
					{ kind = "turnin", quest = 98247 },
				} },
				{ title = "The Crossroads camp: the Shipping Label", tip = "The Durotar Supply and Logistics camp stands just outside the west gate of the Crossroads. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to Dokimi too, but they pay only Merchant's Favor and silver, never reputation.", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 98248 },
				} },
				{ title = "Gather your writs", tip = "Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, the one its title names. Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for.", zone = 1413, goals = {
					{ kind = "task", text = "Take the quests of the writs you can fill" },
				} },
				{ title = "Duskwood writ customers", tip = "Kzixx stands about 450 yards north of Darkshire. Customers show no quest mark: right-click them anyway.", when = { { test = "onquest", quests = { 94214, 94232, 94241, 94250 } } }, zone = 1431, goals = {
