					{ kind = "collect", quest = 94243, objective = 2, item = 7371, map = 1442, x = 58.99, y = 62.6, note = "bring it: craft it or buy it at the Auction House" },
					{ kind = "turnin", quest = 94243, npc = 4201, note = "Heavy Quiver, 75 reputation" },
				} },
				{ title = "Thousand Needles writ customers again", tip = "All five stand at the Mirage Raceway on the Shimmering Flats, south-east of Freewind Post: Rizzle Brassbolts, the chicken \"Plucky\" Johnson, Razzeric, the Goblin Pit Boss and Magus Tirth. Customers show no quest mark: right-click them anyway.", when = { { test = "onquest", quests = { 94218, 94227, 94236, 94245, 94254 } } }, zone = 1441, goals = {
