					{ kind = "turnin", quest = 94218, npc = 4720, note = "Elixir of Defense, 75 reputation" },
					{ kind = "turnin", quest = 94227, npc = 6626, note = "Big Bronze Knife, 75 reputation" },
					{ kind = "turnin", quest = 94236, npc = 4706, note = "Big Bronze Bomb, 75 reputation" },
					{ kind = "turnin", quest = 94245, npc = 4496, note = "Barbaric Gloves, 75 reputation" },
					{ kind = "turnin", quest = 94254, npc = 6548, note = "Greater Adept's Robe, 75 reputation" },
				} },
				{ title = "Friendly to Honored", tip = "Friendly opens the first gated recipes at the camp's profession vendors (Tailoring 25, Leatherworking 17, Enchanting 13, Blacksmithing 10, Engineering 10, Alchemy 5, Cooking 2) and the Uncertified Scribe: Dianne Softstep at Three Corners, Kurvelk Shadowhoof at the south end of the Crossroads camp. The scribe's Forged Delivery Receipt (15 Merchant's Favor) turns an empty Waylaid Crate into a Notarized Shipping Container; hand it to Marcy Baker or Dokimi for 50 reputation (Crate Return). Any crate works, so buy the cheapest one the Auction House has. Honored is 6000 more: 80 Journeyman writs, 48 Expert, 30 Artisan, or 120 crate returns (1,800 Favor and 120 crates). Mix both: every writ you can fill, returns with spare Favor. The Legacy perk Diplomat adds up to 10% to every gain.", zone = 1441, goals = {
					{ kind = "rep", factionId = 2586, standing = "Honored", only = { factions = { "Alliance" } } },
					{ kind = "rep", factionId = 2587, standing = "Honored", only = { factions = { "Horde" } } },
					{ kind = "buy", npc = 256742, item = 262902, optional = true, only = { factions = { "Alliance" } }, note = "Forged Delivery Receipt, 15 Merchant's Favor" },
					{ kind = "buy", npc = 256672, item = 262902, optional = true, only = { factions = { "Horde" } }, note = "Forged Delivery Receipt, 15 Merchant's Favor" },
					{ kind = "turnin", quest = 93862, npc = 256390, optional = true, direct = true, only = { factions = { "Alliance" } }, note = "Crate Return: 50 reputation" },
					{ kind = "turnin", quest = 93862, npc = 256386, optional = true, direct = true, only = { factions = { "Horde" } }, note = "Crate Return: 50 reputation" },
				} },
				{ title = "Badlands writ customer", tip = "Lotwil Veriatus works about 550 yards east of Kargath. He is the only Expert customer Polestar's data knows.", when = { { test = "onquest", quests = { 94256 } } }, zone = 1418, goals = {
					{ kind = "turnin", quest = 94256, npc = 2921, note = "Frost Protection Potion, 125 reputation" },
				} },
				{ title = "Honored to Revered", tip = "Honored opens the rest of the gated recipes (Leatherworking 28, Blacksmithing 21, Enchanting 16, Alchemy 15, Engineering 9, Tailoring 6, Cooking 1), the Advertising License Application (1,200 Favor from Tamelyn Aldridge or Gishah: it starts the quest for a Tradeskill Sign toy) and the scribe's Forger's Quill (15 Favor), which swaps a writ you cannot fill for a random one of the same rank. Revered is 12000 more: 160 Journeyman writs, 96 Expert, 60 Artisan, or 240 crate returns (3,600 Favor). Forever's quest data sets no standing limit on Journeyman writs: their customers are the ones in the zone steps above.", zone = 1418, goals = {
					{ kind = "rep", factionId = 2586, standing = "Revered", only = { factions = { "Alliance" } } },
					{ kind = "rep", factionId = 2587, standing = "Revered", only = { factions = { "Horde" } } },
					{ kind = "buy", npc = 256389, item = 270888, optional = true, only = { factions = { "Alliance" } }, note = "Advertising License Application, 1,200 Merchant's Favor" },
					{ kind = "buy", npc = 256384, item = 270887, optional = true, only = { factions = { "Horde" } }, note = "Advertising License Application, 1,200 Merchant's Favor" },
					{ kind = "turnin", quest = 93862, npc = 256390, optional = true, direct = true, only = { factions = { "Alliance" } }, note = "Crate Return: 50 reputation" },
					{ kind = "turnin", quest = 93862, npc = 256386, optional = true, direct = true, only = { factions = { "Horde" } }, note = "Crate Return: 50 reputation" },
				} },
				{ title = "Revered to Exalted", tip = "Revered opens the Packmule Treat, the Minimule pet (1,500 Favor from Tamelyn Aldridge or Gishah). Exalted is 21000 more: 280 Journeyman writs, 168 Expert, 105 Artisan, or 420 crate returns (6,300 Favor). Keep 6,000 Favor for the Pack Kodo if you want it.", zone = 1418, goals = {
					{ kind = "rep", factionId = 2586, standing = "Exalted", only = { factions = { "Alliance" } } },
					{ kind = "rep", factionId = 2587, standing = "Exalted", only = { factions = { "Horde" } } },
					{ kind = "buy", npc = 256389, item = 284664, optional = true, only = { factions = { "Alliance" } }, note = "Packmule Treat, 1,500 Merchant's Favor" },
					{ kind = "buy", npc = 256384, item = 284664, optional = true, only = { factions = { "Horde" } }, note = "Packmule Treat, 1,500 Merchant's Favor" },
					{ kind = "turnin", quest = 93862, npc = 256390, optional = true, direct = true, only = { factions = { "Alliance" } }, note = "Crate Return: 50 reputation" },
					{ kind = "turnin", quest = 93862, npc = 256386, optional = true, direct = true, only = { factions = { "Horde" } }, note = "Crate Return: 50 reputation" },
				} },
				{ title = "Exalted", tip = "Exalted opens the camp's tabard (200 Favor) at Tamelyn Aldridge or Gishah, and the Reins of the Pack Kodo (6,000 Favor; the mount needs level 60 and Journeyman mount training) at Huey Sunnydale in Three Corners or Okamache at the Crossroads camp. The Pack Kodo guide under Collectibles leads you there.", zone = 1418, goals = {
					{ kind = "buy", npc = 256389, item = 262765, only = { factions = { "Alliance" } }, note = "Azeroth Commerce Authority Tabard, 200 Merchant's Favor" },
					{ kind = "buy", npc = 256384, item = 262764, only = { factions = { "Horde" } }, note = "Durotar Supply and Logistics Tabard, 200 Merchant's Favor" },
				} },
			},
