		{
			id = "forever/reputation/nightclaw-druids", title = "Nightclaw Druids Reputation", category = "Reputation", folder = "Reputation · World", levels = { 10, 18 }, zone = 2521, version = 1, revision = "7d66b1449872f95491215307e0f3e3ff37ffd17fd848e64ba1e82b712a97fd8d", keywords = { "Nightclaw Druids", "Vayn Moongaze", "Elegael Thornpaw", "Lotheluum Starbreeze", "Shadowgale Forest", "Nightfang Den", "Shrine of Akir", "Al'Aketh Cultist's Ear", "More Al'Aketh Ears", "Mercy Falls on Deaf Ears", "Shadowgale Squirrel", "Nightclaw Mantle", "Cloudy", "Azure", "Skyforged", "Gustwoven", "Windraveled", "Stormsewn", "Zephras Isle" }, collects = { 280363 }, rewards = { { item = 280363 }, { item = 280347 }, { text = "48 Blacksmithing, Leatherworking and Tailoring patterns" } }, why = "Zephras Isle's hidden druids: five cultist ears pay 1000 reputation, best done before you outlevel the isle.",
			steps = {
				{ title = "Skyboat from Dalaran", tip = "Zephras Isle is the Skyborne starting island, open to everyone. A skyboat leaves the north side of Dalaran about every five minutes; another flies from north of Thunder Bluff, and either faction may take either.", only = { factions = { "Alliance" } }, when = { { name = "Zephras Isle", test = "zone", negate = true } }, zone = 1416, goals = {
					{ kind = "goto", label = "Skyboat to Zephras Isle", map = 1416, x = 12.5, y = 51.8, frame = "live" },
				} },
				{ title = "Skyboat from Thunder Bluff", tip = "Zephras Isle is the Skyborne starting island, open to everyone. A skyboat leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes; another flies from Dalaran, and either faction may take either.", only = { factions = { "Horde" } }, when = { { name = "Zephras Isle", test = "zone", negate = true } }, zone = 1412, goals = {
					{ kind = "goto", label = "Skyboat to Zephras Isle", map = 1412, x = 34.3, y = 25.8, frame = "live" },
				} },
				{ title = "Lotheluum Starbreeze", tip = "Lotheluum stands in Valanaar, the Skyborne town in the south of the isle, and has heard nothing from the druids up north. His errand is the start of the Nightclaw storyline (level 8 and up, any race). Every quest of it pays Nightclaw reputation: 4100 in all, enough for Friendly. Players' turn-ins paid their full reputation well above these quests' level.", zone = 2521, goals = {
					{ kind = "accept", quest = 94484 },
				} },
				{ title = "Elegael Thornpaw", tip = "Head north into the Shadowgale Forest. Elegael Thornpaw holds the druids' camp in its north-east.", zone = 2521, goals = {
					{ kind = "turnin", quest = 94484 },
					{ kind = "accept", quest = 94485 },
					{ kind = "accept", quest = 94486 },
					{ kind = "accept", quest = 94487 },
				} },
				{ title = "Vayn Moongaze", tip = "Vayn Moongaze, the druids' quartermaster, waits inside their den: the cave just across the clearing north-east of Elegael (Nightclaw Cavern on the map; Elegael calls it the Nightfang Den). Take his ear quest now: the cultists you fight for Elegael drop ears for it.", zone = 2521, goals = {
					{ kind = "accept", quest = 93165 },
				} },
				{ title = "Shadowgale Forest", tip = "The Al'Aketh Footsoldiers and Stormchasers camp just north of Elegael and drop the Bloody Heirlooms (and ears, about one kill in four). The Shadowgale Shrieklings flying west of her drop the feathers; the Lady's Tear Moss grows on the trees along the stream west of her.", zone = 2521, goals = {
					{ kind = "collect", quest = 94487, objective = 1, item = 265141 },
					{ kind = "collect", quest = 94486, objective = 1, item = 265140 },
					{ kind = "collect", quest = 94485, objective = 1, item = 265105 },
					{ kind = "collect", quest = 93165, objective = 1, item = 258771, optional = true, note = "ears for Vayn: keep every one" },
				} },
				{ title = "Elegael's next tasks", zone = 2521, goals = {
					{ kind = "turnin", quest = 94485, note = "500 reputation" },
					{ kind = "turnin", quest = 94486, note = "500 reputation" },
					{ kind = "turnin", quest = 94487, note = "500 reputation" },
					{ kind = "accept", quest = 94488 },
					{ kind = "accept", quest = 94489 },
				} },
				{ title = "The Nightfang Den and Commander Haalien", tip = "The Nightfang Den is the cave north across the clearing from Elegael. Heal the seven injured druids inside (Naaleos Leafwhisper among them) and find Jorel Windsinger. Commander Haalien stands east of the den: he drops his head and a Ripped Missive; right-click the missive to start its quest.", zone = 2521, goals = {
					{ kind = "kill", quest = 94489, objective = 1, npc = 258134 },
					{ kind = "talk", quest = 94489, objective = 2, npc = 258130 },
					{ kind = "collect", quest = 94488, objective = 1, item = 265475 },
					{ kind = "accept", quest = 94490, item = 265476, note = "from Commander Haalien" },
				} },
				{ title = "Elegael, the den's fate", zone = 2521, goals = {
					{ kind = "turnin", quest = 94488, note = "1000 reputation" },
					{ kind = "turnin", quest = 94489, note = "500 reputation" },
					{ kind = "turnin", quest = 94490, note = "500 reputation" },
					{ kind = "accept", quest = 94491 },
				} },
				{ title = "Ears at the Shrine of Akir", tip = "The best ears are south of the forest at the Shrine of Akir: Skypriests drop one in more than half their kills, Guardians in four of ten, Spiritcallers and Honor Guards in a third. The Gustberry Lowlands just north-west of Valanaar are next best (Brawlers and Pillagers, about four in ten). All cultists are level 8 to 10.", zone = 2521, goals = {
					{ kind = "collect", quest = 93165, objective = 1, item = 258771 },
				} },
				{ title = "Mercy Falls on Deaf Ears", tip = "Back to Vayn inside the den. Ten ears for 1000 reputation and a green piece: leather gloves, cloth pants or mail boots. Vayn then takes ears five at a time, for 1000 each, as often as you like, up to level 18; in Classic the pay drops from level 19 and is 200 from level 22. The Legacy perk Diplomat adds up to 10% to every gain.", zone = 2521, goals = {
					{ kind = "turnin", quest = 93165, choose = { { item = 263306 }, { item = 263307 }, { item = 263308 } }, note = "1000 reputation" },
				} },
				{ title = "Back to Valanaar", tip = "Lotheluum waits in Valanaar. Hand in on your way to a skyboat or to the Gustberry Lowlands.", zone = 2521, goals = {
					{ kind = "turnin", quest = 94491, note = "500 reputation" },
				} },
				{ title = "Friendly to Honored", tip = "The storyline and Vayn's first quest leave you at Friendly with 2100 to spare. Honored is 3900 more: four turn-ins of five ears up to level 18, twenty from level 22. Friendly opens 32 of Vayn's patterns, in two colours, Cloudy and Azure: Blacksmithing Skyforged Wristguards and Chain (skill 50, 9s 50c), Gauntlets and Greaves (55, 11s); Leatherworking Gustwoven and Windraveled bracers and belts (50) and gloves and boots (55); Tailoring Stormsewn Cuffs and Cord (50), Handwraps and Shoes (55). They bind when you buy them, so buy them on the crafter.", zone = 2521, goals = {
					{ kind = "rep", factionId = 2758, standing = "Honored" },
					{ kind = "collect", item = 258771, count = 5, optional = true, note = "five ears per turn-in" },
					{ kind = "turnin", quest = 93459, optional = true, direct = true, note = "More Al'Aketh Ears: 1000 reputation, handed in from Vayn's window" },
					{ kind = "vendor", npc = 254151, optional = true, note = "Vayn's patterns" },
				} },
				{ title = "Honored to Revered", tip = "Honored opens the chest and leg patterns (skill 60, 12s 50c): Skyforged chainmail and legguards, Gustwoven harness and trousers, Windraveled jerkin and pants, Stormsewn vest and leggings. Revered is 12000 more: 12 turn-ins (60 ears, about 160 cultist kills at the Shrine) up to level 18, 60 turn-ins (300 ears) from level 22.", zone = 2521, goals = {
					{ kind = "rep", factionId = 2758, standing = "Revered" },
					{ kind = "collect", item = 258771, count = 5, optional = true, note = "five ears per turn-in" },
					{ kind = "turnin", quest = 93459, optional = true, direct = true, note = "More Al'Aketh Ears: 1000 reputation, handed in from Vayn's window" },
					{ kind = "vendor", npc = 254151, optional = true, note = "Vayn's patterns" },
				} },
				{ title = "Revered to Exalted", tip = "Revered opens the Shadowgale Squirrel, a companion pet, for 50s. Exalted is 21000 more: 21 turn-ins (105 ears, about 280 kills) up to level 18, 105 turn-ins (525 ears) from level 22.", zone = 2521, goals = {
					{ kind = "rep", factionId = 2758, standing = "Exalted" },
					{ kind = "collect", item = 258771, count = 5, optional = true, note = "five ears per turn-in" },
					{ kind = "turnin", quest = 93459, optional = true, direct = true, note = "More Al'Aketh Ears: 1000 reputation, handed in from Vayn's window" },
					{ kind = "buy", npc = 254151, item = 280347, optional = true, note = "Shadowgale Squirrel, 50s" },
				} },
				{ title = "The Nightclaw Mantle", tip = "Exalted opens the Nightclaw Mantle, green cloth shoulders for level 15, for 8s 16c.", zone = 2521, goals = {
					{ kind = "buy", npc = 254151, item = 280363, note = "Nightclaw Mantle" },
				} },
