			id = "forever/reputation/orgrimmar", title = "Orgrimmar Reputation", category = "Reputation", folder = "Reputation · Cities", faction = "Horde", levels = { 12, 60 }, zone = 1454, version = 1, revision = "5930ab25943ca27028640cb5c005556c72ea8d22b886a8f42a89c1b03dba5df6", legacyRevision = "e75827f310204c81bba37b875753f875235a37f42e4f4edaeb48483773e37aad", keywords = { "Orgrimmar", "Rashona Straglash", "cloth quartermaster", "cloth donation", "Runecloth", "Additional Runecloth", "Wool", "Silk", "Mageweave", "Wild Guardians", "Betrayed", "Valley of Trials", "Razor Hill", "Sen'jin Village", "Crossroads", "Hidden Enemies", "Chen's Empty Keg", "Brewmaster Drohn", "wolf mount", "Ogunaro Wolfrunner" }, rewards = { { text = "Exalted with Orgrimmar" }, { item = 18796 } }, why = "Durotar and Crossroads quests while you level, Felwood and Azshara quests from 55, then Runecloth to Exalted.",
			steps = {
				{ title = "Orgrimmar: how it works", tip = "Orgrimmar reputation comes from quests and cloth. Rashona Straglash, the cloth quartermaster, stands in the Drag beside the cloth and leather armor shop. She takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with Orgrimmar also gives a quarter as much to Thunder Bluff, the Undercity and the Darkspear Trolls. While you level, do Orgrimmar's quests within 5 levels of them: Durotar at 5 to 12, the Crossroads at 12 to 20, Thrall's Hidden Enemies at 12 to 16. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored Orgrimmar's merchants sell to you for 10% less (the Classic rule), the wolf vendor included; at Exalted other races can buy the wolves: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60, once you have mount training. Orgrimmar has no tabard or other reward.", zone = 1454, goals = {
					{ kind = "goto", label = "Rashona Straglash", map = 1454, x = 63.6, y = 51.2, note = "her donations are handed in from her window and never enter the log" },
				} },
				{ title = "Valley of Trials (optional hub)", tip = "Forever pays these old quests in full at any level. The Valley of Trials is the best of them: about 1,400 Orgrimmar and 1,400 Darkspear reputation in 25 minutes. Gornek waits in the Den, the big hut; Kaltunk stands outside it.", label = "valley", zone = 1411, goals = {
