					{ kind = "accept", quest = 1485, only = { classes = { "Warlock" } }, note = "Ruzan: Vile Familiars, warlocks only" },
				} },
				{ title = "Boars, weapons and peons", tip = "The training weapons lie on the ground in the Den and among the boars to the north. For the peons: target a sleeping Lazy Peon and use the Foreman's Blackjack on it.", when = { { label = "valley", test = "done" } }, zone = 1411, goals = {
