					{ kind = "turnin", quest = 3281 },
				} },
				{ title = "Prowlers, Serena and Echeyakee", tip = "Savannah Prowlers lie west and north of the Crossroads. Serena Bloodfeather leads the Witchwing harpies in the far north-west. Then Sergra gives you the Horn of Echeyakee: blow it beside the kodo bones at Echeyakee's Lair, north of the town, and kill the white lion.", when = { { label = "crossroads", test = "done" } }, zone = 1413, goals = {
					{ kind = "collect", quest = 903, objective = 1, item = 5096, count = 7, note = "Prowler Claws" },
					{ kind = "collect", quest = 876, objective = 1, item = 5067, note = "Serena's Head" },
					{ kind = "turnin", quest = 903 },
					{ kind = "accept", quest = 881, note = "Echeyakee, +150" },
					{ kind = "turnin", quest = 876 },
					{ kind = "collect", quest = 881, objective = 1, item = 5100, note = "Echeyakee's Hide" },
					{ kind = "turnin", quest = 881, note = "Sergra Darkthorn" },
				} },
				{ title = "Chen's Empty Keg (optional hub)", tip = "Forever pays it in full at any level. Chen's Empty Keg lies on the ground at one of several spots in the central and northern Barrens, most of them by the roads around the Crossroads; once someone takes it, it turns up at another. Brewmaster Drohn in Ratchet pays 250 Orgrimmar reputation for the keg and its first filling, then 50 for every filling after, as often as you like.", label = "keg", zone = 1413, goals = {
					{ kind = "collect", item = 4926, map = 1413, x = 55.7, y = 27.3, note = "Chen's Empty Keg: look for it by the roads" },
					{ kind = "accept", quest = 819, item = 4926, note = "Chen's Empty Keg, +100" },
				} },
				{ title = "Ratchet: Brewmaster Drohn", when = { { label = "keg", test = "done" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 819, note = "Brewmaster Drohn" },
					{ kind = "accept", quest = 821, note = "Chen's Empty Keg, +150" },
				} },
				{ title = "Lions, plainstriders and a thunder lizard", tip = "Savannah lions, plainstriders and thunder lizards roam the whole northern Barrens. The lions drop a tusk about every other kill, the plainstriders a kidney about two kills in five; any thunder lizard may drop the horn, about one in five.", when = { { label = "keg", test = "done" } }, zone = 1413, goals = {
					{ kind = "collect", quest = 821, objective = 1, item = 4893, count = 5, note = "Savannah Lion Tusk" },
					{ kind = "collect", quest = 821, objective = 2, item = 4894, count = 5, note = "Plainstrider Kidney" },
					{ kind = "collect", quest = 821, objective = 3, item = 4895, note = "Thunder Lizard Horn" },
				} },
				{ title = "Ratchet: the repeatable keg", tip = "From now on Drohn takes 5 Lightning Glands, a Thunderhawk Saliva Gland and a Kodo Liver for 50, as often as you like. The Stormhide thunder lizards (a gland about every other kill), the Greater Thunderhawks and the kodos south of Camp Taurajo drop them. Gather several sets before you head back to Ratchet.", when = { { label = "keg", test = "done" } }, zone = 1413, goals = {
					{ kind = "turnin", quest = 821, note = "Brewmaster Drohn" },
					{ kind = "collect", item = 4898, count = 5, optional = true, note = "Lightning Gland, from Stormhides" },
					{ kind = "collect", item = 4897, optional = true, note = "Thunderhawk Saliva Gland, from Greater Thunderhawks" },
					{ kind = "collect", item = 4896, optional = true, note = "Kodo Liver, from the kodos" },
					{ kind = "turnin", quest = 822, optional = true, direct = true, note = "Brewmaster Drohn: Chen's Empty Keg, +50" },
				} },
				{ title = "Rashona Straglash: A Donation of Wool", tip = "From here it is cloth. Wool, Silk and Mageweave must all be handed in before Rashona offers the Runecloth donation, and Additional Runecloth needs the Runecloth donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, Runecloth 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey.", zone = 1440, goals = {
					{ kind = "collect", item = 2592, count = 60, map = 1440, x = 36, y = 37, note = "Wool Cloth: the Thistlefur furbolgs drop it about one kill in four" },
					{ kind = "turnin", quest = 7826, direct = true, note = "Rashona Straglash: A Donation of Wool, +150" },
				} },
				{ title = "A Donation of Silk", tip = "Silk: the Syndicate in Hillsbrad and Alterac drop it about one kill in three, or buy it.", zone = 1440, goals = {
					{ kind = "level", level = 26 },
					{ kind = "collect", item = 4306, count = 60, map = 1416, x = 57.7, y = 67.6, note = "Silk Cloth: the Syndicate" },
					{ kind = "turnin", quest = 7827, direct = true, note = "+150" },
				} },
				{ title = "A Donation of Mageweave", tip = "Mageweave: the Jadefire satyrs in southern Felwood and the Dunemaul ogres in Tanaris drop it about one kill in three, or buy it.", zone = 1416, goals = {
					{ kind = "level", level = 40 },
					{ kind = "collect", item = 4338, count = 60, map = 1448, x = 41.6, y = 85.7, note = "Mageweave Cloth: the Jadefire satyrs" },
					{ kind = "turnin", quest = 7831, direct = true, note = "+150" },
				} },
				{ title = "A Donation of Runecloth", tip = "Runecloth: the Scarlet at Tyr's Hand in the Eastern Plaguelands, the Gordok ogres outside Dire Maul in Feralas and the Twilight camps of Silithus drop it about one kill in three. The Auction House is faster if you have gold.", zone = 1448, goals = {
					{ kind = "level", level = 50 },
					{ kind = "collect", item = 14047, count = 60, map = 1423, x = 68, y = 69.5, frame = "live", note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7824, direct = true, note = "+150" },
				} },
				{ title = "Bloodvenom Post: Wild Guardians", tip = "These quests are level 56 to 59, so they pay in full at 60. Trull Failbane stands at Bloodvenom Post; the owlbeasts live in Winterspring, through the Timbermaw tunnel north of Felwood.", zone = 1448, goals = {
					{ kind = "level", level = 55 },
					{ kind = "accept", quest = 4521, note = "Wild Guardians, +100" },
				} },
				{ title = "Winterspring: owlbeasts", tip = "Raging Owlbeasts north-west of Everlook, Ragged Owlbeasts further west.", zone = 1452, goals = {
					{ kind = "kill", quest = 4521, objective = 1, npc = 7451, count = 15, note = "Raging Owlbeast" },
					{ kind = "kill", quest = 4521, objective = 2, npc = 7450, count = 15, note = "Ragged Owlbeast" },
