				{ title = "Winterspring: Moontouched Owlbeasts", tip = "Moontouched Owlbeasts north of Everlook and south of it.", zone = 1452, goals = {
					{ kind = "kill", quest = 4741, objective = 1, npc = 7453, count = 13, note = "Moontouched Owlbeast" },
