				{ title = "Bloodvenom Post: hand in again", zone = 1448, goals = {
					{ kind = "turnin", quest = 4741 },
					{ kind = "accept", quest = 4721, note = "Wild Guardians, +100" },
				} },
				{ title = "Winterspring: Berserk Owlbeasts", tip = "Most Berserk Owlbeasts are north of Everlook. A Blue-feathered Necklace may drop from the owlbeasts now: use it to start Guarding Secrets.", zone = 1452, goals = {
					{ kind = "kill", quest = 4721, objective = 1, npc = 7454, count = 10, note = "Berserk Owlbeast" },
					{ kind = "accept", quest = 4882, item = 12558, optional = true, note = "Blue-feathered Necklace: Guarding Secrets, +50" },
