				{ title = "Bloodvenom Post: last hand-in", zone = 1448, goals = {
					{ kind = "turnin", quest = 4721 },
					{ kind = "turnin", quest = 4882, optional = true },
					{ kind = "accept", quest = 4883, optional = true, note = "Guarding Secrets, +100 Thunder Bluff: to Nara Wildmane on Elder Rise in Thunder Bluff" },
					{ kind = "note", text = "Wild Guardians: 300 Orgrimmar reputation." },
				} },
				{ title = "Belgrom Rockmaul: Betrayed", tip = "Belgrom stands in the Valley of Honor outside the Hall of the Brave. The first two Betrayed quests are level 53 and pay in full at 60 too, as every quest does in Forever.", zone = 1454, goals = {
					{ kind = "accept", quest = 3504, note = "Betrayed, +50" },
				} },
				{ title = "Valormok", tip = "Fly to Valormok in western Azshara. Ag'tor Bloodfist sends you north-east to the blood elf camp on the bluffs of the northern peninsula.", zone = 1447, goals = {
					{ kind = "turnin", quest = 3504, note = "Ag'tor Bloodfist" },
					{ kind = "accept", quest = 3505, note = "Betrayed, +75" },
				} },
				{ title = "Magus Rimtori's camp", tip = "Kill the Reclaimers and Surveyors, then walk up to the book inside the ring of stone pillars. Read the Kaldorei Tome of Summoning there to start the next quest: break the crystals around the circle, kill the guard that comes, then Magus Rimtori.", zone = 1447, goals = {
					{ kind = "kill", quest = 3505, objective = 1, npc = 6199, count = 10, note = "Blood Elf Reclaimer" },
					{ kind = "kill", quest = 3505, objective = 2, npc = 6198, count = 10, note = "Blood Elf Surveyor" },
					{ kind = "complete", quest = 3505, map = 1447, x = 59.5, y = 31.5, note = "Find Magus Rimtori's camp" },
					{ kind = "turnin", quest = 3505, note = "the Kaldorei Tome of Summoning" },
					{ kind = "accept", quest = 3506, note = "Betrayed, +75" },
					{ kind = "collect", quest = 3506, objective = 1, item = 10597, note = "Head of Magus Rimtori" },
				} },
				{ title = "Valormok and Orgrimmar", zone = 1447, goals = {
					{ kind = "turnin", quest = 3506, note = "Ag'tor Bloodfist" },
					{ kind = "accept", quest = 3507, note = "Betrayed, +150" },
					{ kind = "turnin", quest = 3507, note = "Belgrom Rockmaul, in Orgrimmar" },
					{ kind = "note", text = "Betrayed: 300 Orgrimmar reputation at 60." },
				} },
				{ title = "Blackrock Mountain, with a group", tip = "Kargath in the Badlands hands out Orgrimmar quests for Blackrock Depths and Blackrock Spire, all level 58 to 60 and paid in full: Precarious Predicament and Operation: Death to Angerforge (150 each), The Pack Mistress and Bijou's Reconnaissance Report (100 each), Warlord's Command (150), Eitrigg's Wisdom (100) and For The Horde! (Rend's head, 200 to every Horde city). These are dungeon quests: take them when your group goes.", zone = 1418, goals = {
					{ kind = "accept", quest = 4903, optional = true, note = "Warlord Goretooth: Warlord's Command, +150, a group of five" },
					{ kind = "accept", quest = 4724, optional = true, note = "Galamav the Marksman: The Pack Mistress, +100, a group of five" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (an orc starts at Friendly 1,000: 100 hand-ins; an Undead or Skyborne starts at Neutral 2,000 and first needs 20 hand-ins, 400 Runecloth, to reach Friendly). Hand in every 20 you carry, one after another.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7832, optional = true, direct = true, note = "Rashona Straglash: Additional Runecloth, +50" },
					{ kind = "rep", factionId = 76, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth. The Auction House price of a stack decides whether to farm or buy.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7832, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "rep", factionId = 76, standing = "Revered" },
				} },
				{ title = "Additional Runecloth to Exalted", tip = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. Raid heads pay too: The Lord of Blackrock (Nefarian) 200 to every Horde city and Victory for the Horde (Onyxia) 400 to Orgrimmar. At Exalted, Ogunaro Wolfrunner in the Valley of Honor sells the wolves to every Horde race: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7832, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "rep", factionId = 76, standing = "Exalted" },
					{ kind = "talk", npc = 3362, optional = true, note = "Ogunaro Wolfrunner: the wolves" },
				} },
			},
		},
		{
			id = "forever/reputation/ravenholdt", title = "Ravenholdt Reputation", category = "Reputation", folder = "Reputation · World", levels = { 24, 60 }, zone = 1416, version = 1, revision = "bebe26c0c8154df38550d8dc8831ad4e68f6332624c9ddd79a905762868e6f0d", keywords = { "Ravenholdt", "Ravenholdt Manor", "Syndicate", "Fahrad", "Myrokos Silentform", "Lord Jorach Ravenholdt", "Syndicate Emblem", "Heavy Junkbox", "Junkboxes Needed", "pickpocket", "rogue", "Lord Tomas", "Barton", "Anastasia Miller", "Stromgarde", "Strahnbrad", "Durnholde Keep" }, rewards = { { text = "Ravenholdt reputation (no vendor or reward in Forever's data)" } }, why = "The assassins' guild: Forever's new rogue quests, then Syndicate kills and Heavy Junkboxes to Exalted.",
			steps = {
				{ title = "The Manor, Ravenholdt", tip = "Rogues from level 24: ask your class trainer in a capital \"May I have it, please?\" for the Elegant Letter, and read it. The path up to the manor starts in the hills north of Durnholde Keep. In the tunnel on the way lies a chest: do not open it (an elite guard jumps out), just walk past it to earn the Rite of Cunning. Fahrad waits on the manor's balcony.", only = { classes = { "Rogue" } }, zone = 1424, goals = {
					{ kind = "accept", quest = 6681, item = 17126, note = "Elegant Letter, from your class trainer" },
					{ kind = "kill", quest = 6681, objective = 1, npc = 13936, note = "walk past the trapped chest in the tunnel" },
					{ kind = "turnin", quest = 6681, note = "Fahrad: 100 reputation" },
				} },
				{ title = "Myrokos Silentform", tip = "Myrokos Silentform, in the manor, has Forever's new rogue quests: 100 reputation each for Syndicate Sabotage, What's the Big Idea? and Covert Extraction, which follows it, and 300 for The Syndicate Sting at the end of the Stromgarde chain (A Way In and the two quests after it pay nothing). All can be done solo with stealth from level 30; below that, the Master of Deception talent and a Flash Powder for Vanish help.", only = { classes = { "Rogue" } }, zone = 1416, goals = {
					{ kind = "accept", quest = 96779 },
					{ kind = "accept", quest = 96781 },
					{ kind = "accept", quest = 96783 },
				} },
				{ title = "Durnholde Keep: Lord Tomas", tip = "Lord Tomas is inside Durnholde Keep, the Syndicate fortress east of Southshore. Stealth past the guards in the courtyard.", only = { classes = { "Rogue" } }, zone = 1424, goals = {
					{ kind = "kill", quest = 96779, objective = 1, npc = 266216, note = "Lord Tomas" },
				} },
				{ title = "Strahnbrad: Barton", tip = "Barton hides in a house in Strahnbrad, among stealthed Syndicate. Pick his pocket for the report; Distract turns him around if you are under his level.", only = { classes = { "Rogue" } }, zone = 1416, goals = {
					{ kind = "collect", quest = 96781, objective = 1, item = 275482, map = 1416, x = 62.6, y = 46.9, note = "Barton's Scouting Report: pickpocket Barton" },
				} },
				{ title = "Northfold Manor: a uniform", tip = "The Syndicate Footlocker stands among the Syndicate camps of Northfold Manor, north of Stromgarde. Open it to finish A Way In and take the Syndicate Uniform.", only = { classes = { "Rogue" } }, zone = 1417, goals = {
					{ kind = "turnin", quest = 96783, object = 656157, map = 1417, x = 32.3, y = 26.6, note = "Syndicate Footlocker" },
					{ kind = "accept", quest = 96784, object = 656157, map = 1417, x = 32.3, y = 26.6 },
				} },
				{ title = "Stromgarde: Anastasia Miller", tip = "Put on the Syndicate Uniform and go into Stromgarde. Anastasia Miller waits on a ledge just outside the castle; players reach her by jumping from the roof of the house beside the ledge. Her stash is upstairs in a house near the keep.", only = { classes = { "Rogue" } }, zone = 1417, goals = {
					{ kind = "turnin", quest = 96784, npc = 266847, map = 1417, x = 26.8, y = 64.4, note = "Anastasia Miller" },
					{ kind = "accept", quest = 96785, npc = 266847, map = 1417, x = 26.8, y = 64.4 },
					{ kind = "collect", quest = 96785, objective = 1, item = 275709, map = 1417, x = 29.5, y = 65.1, note = "Stolen Funds, in Anastasia's Stash upstairs" },
					{ kind = "turnin", quest = 96785, npc = 266847, map = 1417, x = 26.8, y = 64.4 },
					{ kind = "accept", quest = 96786, npc = 266847, map = 1417, x = 26.8, y = 64.4 },
				} },
				{ title = "Thoradin's Wall: the shipment", tip = "The hand-off is at the southern end of Thoradin's Wall, in the west of the Arathi Highlands: two Syndicate guard the box. Kill them or lure them off, then take the Intercepted Shipment. Keep the uniform: Myrokos wants it back.", only = { classes = { "Rogue" } }, zone = 1417, goals = {
					{ kind = "collect", quest = 96786, objective = 1, item = 275882, map = 1417, x = 15.5, y = 43, note = "Intercepted Shipment" },
				} },
				{ title = "Back to Myrokos", only = { classes = { "Rogue" } }, zone = 1416, goals = {
					{ kind = "turnin", quest = 96779, note = "100" },
					{ kind = "turnin", quest = 96781, note = "100" },
					{ kind = "turnin", quest = 96786, note = "300" },
					{ kind = "accept", quest = 96782, npc = 13085, optional = true, note = "Covert Extraction, after What's the Big Idea?" },
				} },
				{ title = "Ruins of Alterac: the Perenolde heirlooms", tip = "The two heirlooms lie in two towers of the Ruins of Alterac, the ogre-held ruin in the middle of the Alterac Mountains. The tower with the sword is ringed by elite ogres: stay in stealth. Neither item is guarded once you are inside.", only = { classes = { "Rogue" } }, when = { { test = "onquest", quests = { 96782 } } }, zone = 1416, goals = {
					{ kind = "collect", quest = 96782, objective = 2, item = 275636, map = 1416, x = 41.4, y = 40.2, note = "Royal Aegis of Perenolde, the shield" },
					{ kind = "collect", quest = 96782, objective = 1, item = 275635, map = 1416, x = 38.5, y = 58, note = "Blade of House Perenolde, the sword" },
					{ kind = "turnin", quest = 96782, note = "Myrokos Silentform: 100" },
				} },
				{ title = "Syndicate Emblems to Friendly", tip = "Neutral to Friendly is 3,000 reputation; the quests above pay 700 of it. Any Ravenholdt Guard on the path takes Syndicate Emblems, 100 reputation each, until you reach Friendly: 23 emblems after the quests. Pick the pockets of Syndicate humans; they never drop emblems when killed. The Arathi camps pay best: Syndicate Prowlers and Conjurors carry one about a quarter of the time. Kill what you have robbed so the next ones respawn fresh.", only = { classes = { "Rogue" } }, zone = 1417, goals = {
					{ kind = "collect", item = 17124, count = 5, map = 1417, x = 30, y = 27, optional = true, note = "Syndicate Emblem: pickpocket Syndicate" },
					{ kind = "turnin", quest = 6701, optional = true, direct = true, note = "a Ravenholdt Guard: 100 per emblem, handed in from his window" },
					{ kind = "rep", factionId = 349, standing = "Friendly" },
				} },
				{ title = "Syndicate kills to the end of Honored", tip = "Everyone, not only rogues: in Classic every Syndicate human gave Ravenholdt 5 reputation up to the end of Honored (11,999 of 12,000) and not one point more, so 0 to there is 4,200 kills (3,600 after a rogue's quests and emblems). This step ticks at Honored; keep killing until the bar stops moving, then go on to the junkboxes. The highest Syndicate are in the north-west of the Alterac Mountains, Syndicate Assassins and Enforcers (level 38-40), with Syndicate Sentries (36-37) nearer the middle. At 60 all Syndicate are grey, and in Classic grey kills gave about a fifth: farm them before 48 if you can. Legacy Diplomat adds up to 10%.", loop = true, zone = 1416, goals = {
					{ kind = "goto", label = "Syndicate Assassins and Enforcers", map = 1416, x = 38.3, y = 15.4 },
					{ kind = "goto", label = "Syndicate Sentries", map = 1416, x = 47.4, y = 17.5 },
					{ kind = "kill", npc = 2246, optional = true, note = "Syndicate Assassin, level 38-39" },
					{ kind = "kill", npc = 2247, optional = true, note = "Syndicate Enforcer, level 39-40" },
					{ kind = "kill", npc = 2243, optional = true, note = "Syndicate Sentry, level 36-37" },
					{ kind = "rep", factionId = 349, standing = "Honored" },
				} },
				{ title = "A Simple Request, rogues 50+", tip = "At level 50 your class trainer has another letter for you, and Lord Jorach Ravenholdt a short chain: 360 reputation in all. The Sealed Azure Bag drops from Timbermaw Shamans in northern Azshara (about 1 in 27, or pick their pockets); the Encoded Fragments from Forest Oozes in Azshara (4 in 5). The Azure Key comes from Morphaz, an elite drake deep in the Temple of Atal'Hakkar: a five-player dungeon, group up.", only = { classes = { "Rogue" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1416, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8233, npc = 918, only = { factions = { "Alliance" } }, note = "Osborne the Night Man, Stormwind" },
					{ kind = "accept", quest = 8233, npc = 3328, only = { factions = { "Horde" } }, note = "Ormok, Orgrimmar" },
					{ kind = "turnin", quest = 8233, note = "Lord Jorach Ravenholdt" },
					{ kind = "accept", quest = 8234 },
					{ kind = "collect", quest = 8234, objective = 1, item = 19775, note = "Sealed Azure Bag: Timbermaw Shamans" },
					{ kind = "turnin", quest = 8234, note = "Archmage Xylem" },
					{ kind = "accept", quest = 8235 },
					{ kind = "collect", quest = 8235, objective = 1, item = 20023, count = 10, note = "Encoded Fragment: Forest Oozes" },
					{ kind = "turnin", quest = 8235 },
					{ kind = "accept", quest = 8236 },
					{ kind = "collect", quest = 8236, objective = 1, item = 20022, map = 1435, x = 70.2, y = 45.2, optional = true, note = "Azure Key: Morphaz, Temple of Atal'Hakkar (group)" },
					{ kind = "turnin", quest = 8236, optional = true, note = "Lord Jorach Ravenholdt: 150" },
				} },
				{ title = "Heavy Junkboxes to Exalted", tip = "From the top of Honored to Exalted is 21,001 reputation, and Junkboxes Needed is the only way: Fahrad pays 50 and a Dusksteel Throwing Knife for every five Heavy Junkboxes (Classic Era paid 75), 421 turn-ins and 2,105 boxes. Boxes count at any standing, so take the cheap kills to their cap first. Any class can hand them in. Rogues get them by picking the pockets of humanoids around level 50 and up: Lower Blackrock Spire and Blackrock Depths are the classic spots, pick every pocket, reset and go again. The boxes do not bind, so everyone else buys them from rogues or at the auction house. Hand them in unopened; an opened box you empty vanishes, so leave one item in it.", zone = 1416, goals = {
					{ kind = "level", level = 50 },
					{ kind = "collect", item = 16885, count = 5, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Heavy Junkbox: pickpocket level 50+ humanoids, Blackrock Mountain" },
					{ kind = "turnin", quest = 8249, optional = true, direct = true, note = "Fahrad: 50 per five boxes, handed in from his window" },
					{ kind = "rep", factionId = 349, standing = "Exalted" },
				} },
