		{
			id = "forever/reputation/steamwheedle-cartel", title = "Steamwheedle Cartel Reputation", category = "Reputation", folder = "Reputation · World", levels = { 50, 60 }, zone = 1444, version = 1, revision = "9d3f6478d2ea42681aaa4a2341f7955746dd51aa6688afbc42f41e059333b1a4", keywords = { "Steamwheedle Cartel", "goblin", "Booty Bay", "Gadgetzan", "Ratchet", "Everlook", "Powderfuse", "Riverglades", "Zorbin Fandazzle", "Zapped Giants", "Again With the Zapped Giants", "Refuel for the Zapping", "Miniaturization Residue", "Water Elemental Core", "Free Knot", "Knot Thimblejack", "Gordok Shackle Key", "Gordok Ogre Suit", "Dire Maul", "Tinkee Steamboil", "Southsea", "Lost Rigger Cove", "Winklespark", "Gezzy Gunkgear", "Rettrick", "Zippie Fizzbolt", "Friz Frazzlespark", "quartermaster", "Tough Guy's Eyepatch", "Fizzbolt's Fashionable Fedora", "Stolen Wastewander Cowl", "Barrens Headband", "Haughty Fellow's Monocle" }, collects = { 274024, 274022, 274023, 274021, 276199 }, rewards = { { item = 274024 }, { item = 274022 }, { item = 274023 }, { item = 274021 }, { item = 276199 }, { text = "Forever's goblin quartermasters: gear for levels 20 to 50 at Friendly and Honored" } }, why = "Every goblin town at once: Zorbin's zapped giants and Knot's shackles, then five new quartermasters and their hats.",
			steps = {
				{ title = "Zorbin Fandazzle", tip = "Five goblin towns share one reputation family, the Steamwheedle Cartel: Ratchet, Booty Bay, Gadgetzan, Everlook and Forever's new Powderfuse in the Riverglades. Everyone starts each at Neutral (500 into it). A gain with one town gives the others half as much; a quest for the Cartel itself, like Zorbin's, pays every town in full. Losses spread the same way: a Booty Bay Bruiser or any goblin of the towns costs 125 (half that with the other towns), and Bloodsail Buccaneers reputation is earned only that way. Zorbin camps on the road through central Feralas and works for anyone, even players the goblins hate. His first two quests are level 48 and open his repeatables (level 55); Forever pays all of them in full at any level.", zone = 1444, goals = {
					{ kind = "accept", quest = 7003, note = "Zapped Giants: 150 to every town" },
					{ kind = "accept", quest = 7721, note = "Fuel for the Zapping: 150 to every town" },
				} },
				{ title = "Zapped giants", tip = "Use Zorbin's Ultra-Shrinker on a living giant (Land Walker, Cliff Giant, or a Shore, Deep or Wave Strider, level 47-50) and it shrinks into a zapped version; kill that for its Miniaturization Residue, one every time. The Land Walkers and Cliff Giants in the north-west hills are the thickest; the striders walk the coast and the shallows. The shrinker lasts two hours: if it runs out, abandon the quest and take it again.", loop = true, zone = 1444, goals = {
					{ kind = "goto", label = "Land Walkers and Cliff Giants", map = 1444, x = 37.8, y = 22 },
					{ kind = "goto", label = "Shore and Deep Striders", map = 1444, x = 36.4, y = 34 },
					{ kind = "goto", label = "Wave Striders", map = 1444, x = 44.3, y = 46.6 },
					{ kind = "goto", label = "Striders on the south coast", map = 1444, x = 45.1, y = 58 },
					{ kind = "use", item = 18904, map = 1444, x = 37.8, y = 22, optional = true, note = "Zorbin's Ultra-Shrinker, on a living giant" },
					{ kind = "collect", quest = 7003, objective = 1, item = 18956, count = 15, note = "Miniaturization Residue, from the zapped giants" },
				} },
				{ title = "Sea Elementals and Sea Sprays", tip = "The Sea Elementals and Sea Sprays (level 47-49) drift along the Forgotten Coast and in the shallows below the giants: about half drop a Water Elemental Core.", loop = true, zone = 1444, goals = {
					{ kind = "goto", label = "Forgotten Coast", map = 1444, x = 34.4, y = 35.6 },
					{ kind = "goto", label = "the south coast", map = 1444, x = 44.5, y = 52.5 },
					{ kind = "collect", quest = 7721, objective = 1, item = 18958, count = 10, note = "Water Elemental Core: Sea Elementals and Sea Sprays" },
				} },
				{ title = "Back to Zorbin", tip = "From now on Zorbin offers Again With the Zapped Giants (10 residue) and Refuel for the Zapping (6 cores), again and again: 25 reputation with every town each time.", zone = 1444, goals = {
					{ kind = "turnin", quest = 7003 },
					{ kind = "turnin", quest = 7721 },
				} },
				{ title = "Lost Rigger Cove, below 56", tip = "The Southsea pirates of Lost Rigger Cove (level 44-45) on the east coast of Tanaris give Gadgetzan 5 each up to the end of Honored, and the other towns half. Two quests at Steamwheedle Port pay 100 Gadgetzan each: Southsea Shakedown (10 of each pirate) and Pirate Hats Ahoy! (20 Southsea Pirate Hats, one in ten pirates). From level 56 the pirates are grey and pay little: skip this step then.", when = { { level = 56, test = "level", op = "<" } }, zone = 1446, goals = {
					{ kind = "accept", quest = 8366, note = "Security Chief Bilgewhizzle, Steamwheedle Port" },
					{ kind = "accept", quest = 8365, note = "Haughty Modiste" },
					{ kind = "kill", quest = 8366, objective = 1, npc = 7855, count = 10 },
					{ kind = "kill", quest = 8366, objective = 2, npc = 7856, count = 10 },
					{ kind = "kill", quest = 8366, objective = 3, npc = 7857, count = 10 },
					{ kind = "kill", quest = 8366, objective = 4, npc = 7858, count = 10 },
					{ kind = "collect", quest = 8365, objective = 1, item = 20519, count = 20, note = "Southsea Pirate Hat" },
					{ kind = "turnin", quest = 8366 },
					{ kind = "turnin", quest = 8365 },
				} },
				{ title = "Tinkee Steamboil", tip = "Tinkee Steamboil, a goblin at Flame Crest in the north of the Burning Steppes, has a chain that pays every town 150 and Everlook 150 more. Use her Draco-Incarcinatrix 900 on a broodling, kill it while the device holds it, and pick up the Broodling Essence it leaves. The device takes only Black and Scalding Broodlings, not the Flamescale Broodlings of the west: Scalding Broodlings (level 53-54) roam just west and east of Flame Crest, Black Broodlings (51-52) the north-east corner of the zone, the thickest group. They are few and spread out: the path passes both and ends among the Black Broodlings.", zone = 1428, goals = {
					{ kind = "accept", quest = 4726, note = "Tinkee Steamboil" },
					{ kind = "goto", label = "Scalding Broodlings west of Flame Crest", map = 1428, x = 59.2, y = 32.3 },
					{ kind = "goto", label = "Scalding Broodlings east of Flame Crest", map = 1428, x = 73.2, y = 27.1 },
					{ kind = "goto", label = "Black Broodlings in the north-east", map = 1428, x = 87.8, y = 33.5 },
					{ kind = "use", item = 12284, map = 1428, x = 87.8, y = 33.5, optional = true, note = "Draco-Incarcinatrix 900, on a Black or Scalding Broodling" },
					{ kind = "collect", quest = 4726, objective = 1, item = 12283, count = 8, map = 1428, x = 87.8, y = 33.5, note = "Broodling Essence, left by the broodlings" },
					{ kind = "turnin", quest = 4726, note = "100 to every town" },
					{ kind = "accept", quest = 4808 },
				} },
				{ title = "Everlook: Felnok Steelspring", tip = "Felnok Steelspring is in Everlook. The Chillwind Chimaeras (level 55-57) south-west of Everlook drop the horns one time in five.", zone = 1452, goals = {
					{ kind = "turnin", quest = 4808, note = "50 Everlook" },
					{ kind = "accept", quest = 4809 },
					{ kind = "collect", quest = 4809, objective = 1, item = 12444, count = 8, map = 1452, x = 55.4, y = 47.5, note = "Uncracked Chillwind Horn: Chillwind Chimaeras" },
					{ kind = "turnin", quest = 4809, note = "100 Everlook" },
					{ kind = "accept", quest = 4810 },
				} },
				{ title = "Back to Tinkee", tip = "Return to Tinkee gives 50 to every town. Her later quests, Egg Freezing (150 to every town) and Egg Collection (200), are done in the Rookery of Upper Blackrock Spire, a ten-player dungeon: take them up with your group.", zone = 1428, goals = {
					{ kind = "turnin", quest = 4810 },
				} },
				{ title = "Dire Maul North: Knot Thimblejack", tip = "Knot Thimblejack sits shackled in Dire Maul North, the Gordok ogres' wing (a five-player dungeon from level 57: group up). Every Gordok Shackle Key frees him once: 150 to every town, and he is shackled again on your next run. Gordok ogres drop the keys (about one in fifteen; Guard Fengus one in seven): a full run of the wing usually brings one. His Gordok Ogre Suit pays 100 the first time and 50 after, for 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Thread and the Ogre Tannin from the basket in the wing. Under 57 when you get here? Unskip this step later.", when = { { level = 57, test = "level", op = ">=" } }, zone = 1444, goals = {
					{ kind = "level", level = 57 },
					{ kind = "goto", label = "Dire Maul", map = 1444, x = 59.2, y = 45.1 },
					{ kind = "collect", item = 18250, map = 1444, x = 59.2, y = 45.1, optional = true, note = "Gordok Shackle Key, Gordok ogres" },
					{ kind = "turnin", quest = 5525, map = 1444, x = 59.2, y = 45.1, optional = true, direct = true, note = "Free Knot!: 150 to every town, handed in from Knot's window" },
					{ kind = "turnin", quest = 7429, map = 1444, x = 59.2, y = 45.1, optional = true, direct = true, note = "Free Knot!, again on every later run: 150" },
				} },
				{ title = "Every town to Friendly", tip = "Neutral 500 to Friendly is 2,500 with each town. The quests above pay every town up to 700 (Zorbin's two 300, Tinkee's 150, the first Free Knot 150 and the first Ogre Suit 100); Zorbin's repeatables do the rest, 25 to every town each: 10 residue (ten giants) or 6 cores (about twelve elementals). The towns' own quests count too, each giving the other towns half: Ratchet's in the Barrens (levels 10-25, about 4,300: the Samophlange chain 625, Mebok Mizzyrix's errands, the Wizzlecrank and Gilthares escorts 150 each), Booty Bay's in Stranglethorn, Arathi and the Badlands (30-50, about 6,500: the three OOX robot rescues 250 each, An OOX of Your Own 200, Stranglethorn Fever 200, Facing Negolash 200, the Sunken Treasure chain at Faldir's Cove), Gadgetzan's in Tanaris (43-55, about 3,000: the Divino-matic Rod 200, Wastewander Justice 100 each, the WANTED posters) and Everlook's in Winterspring (52-60, about 1,450: Donova Snowden's Winterfall chain, Umi's yeti quests). Forever adds a few low ones: A Simmering Storm and Stormy Potential in Durotar and WANTED: Bruuz (Ratchet 100 each), Important Heirlooms in Ironforge (Gadgetzan 100). Forever pays them in full at any level. Kills help while they are not grey, 5 each: Southsea pirates in the Barrens for Ratchet and in Tanaris for Gadgetzan and Stranglethorn's Venture Co. camps for Booty Bay, up to the end of Honored; Wastewander bandits for Gadgetzan and Bloodsail pirates for Booty Bay only up to the end of Neutral. Friendly opens each quartermaster's first gear.", zone = 1444, goals = {
					{ kind = "accept", quest = 7725, optional = true, note = "Again With the Zapped Giants: 10 residue" },
					{ kind = "collect", item = 18956, count = 10, optional = true, note = "Miniaturization Residue" },
					{ kind = "turnin", quest = 7725, optional = true, note = "25 to every town" },
					{ kind = "accept", quest = 7726, optional = true, note = "Refuel for the Zapping: 6 cores" },
					{ kind = "collect", item = 18958, count = 6, optional = true, note = "Water Elemental Core" },
					{ kind = "turnin", quest = 7726, optional = true, note = "25 to every town" },
					{ kind = "rep", factionId = 470, standing = "Friendly", note = "Ratchet" },
					{ kind = "rep", factionId = 21, standing = "Friendly", note = "Booty Bay" },
					{ kind = "rep", factionId = 369, standing = "Friendly", note = "Gadgetzan" },
					{ kind = "rep", factionId = 577, standing = "Friendly", note = "Everlook" },
					{ kind = "rep", factionId = 2827, standing = "Friendly", optional = true, note = "Powderfuse" },
				} },
				{ title = "Every town to Honored", tip = "Friendly to Honored is 6,000: 240 of Zorbin's turn-ins, or 40 Free Knot runs, or a mix. Nothing can be saved up: residue and cores drop only while their quest is in your log, and you can carry one Gordok Shackle Key at a time, so hand each in before the next run. Honored opens each quartermaster's blue items.", zone = 1444, goals = {
					{ kind = "accept", quest = 7725, optional = true },
					{ kind = "collect", item = 18956, count = 10, optional = true },
					{ kind = "turnin", quest = 7725, optional = true },
					{ kind = "accept", quest = 7726, optional = true },
					{ kind = "collect", item = 18958, count = 6, optional = true },
					{ kind = "turnin", quest = 7726, optional = true },
					{ kind = "rep", factionId = 470, standing = "Honored" },
