					{ kind = "rep", factionId = 369, standing = "Honored" },
					{ kind = "rep", factionId = 577, standing = "Honored" },
					{ kind = "rep", factionId = 2827, standing = "Honored", optional = true },
				} },
				{ title = "Every town to Revered", tip = "Honored to Revered is 12,000 more: 480 of Zorbin's turn-ins (4,800 residue) or 80 Free Knot runs. Revered opens the five cosmetic hats, the reason most players do this. Legacy Diplomat adds up to 10%.", zone = 1444, goals = {
