					{ kind = "rep", factionId = 577, standing = "Revered" },
					{ kind = "rep", factionId = 2827, standing = "Revered", optional = true },
				} },
				{ title = "Ratchet: Winklespark", tip = "Winklespark, Ratchet's quartermaster, by the docks. Friendly, level 20 gear: Quilted Cloak 41s (Stamina, Agility), Rumpled Kilt 54s (Stamina, spell power), Ratchet Wristwraps 34s (Intellect, Agility). Honored: Defective Samophlange, an off-hand, 66s (Intellect, Spirit); Barrens Basher, a one-handed mace, 1g 65s (Stamina, Strength). Revered: the Barrens Headband, a cosmetic hat, 2g.", zone = 1413, goals = {
					{ kind = "buy", item = 274740, optional = true, note = "Quilted Cloak, Friendly" },
					{ kind = "buy", item = 274741, optional = true, note = "Rumpled Kilt, Friendly" },
					{ kind = "buy", item = 274742, optional = true, note = "Ratchet Wristwraps, Friendly" },
					{ kind = "buy", item = 274743, optional = true, note = "Defective Samophlange, Honored" },
					{ kind = "buy", item = 274744, optional = true, note = "Barrens Basher, Honored" },
					{ kind = "buy", item = 274021, optional = true, note = "Barrens Headband, Revered" },
				} },
				{ title = "Booty Bay: Gezzy Gunkgear", tip = "Gezzy Gunkgear, Booty Bay's quartermaster. Friendly, level 30 gear: Deckswabber's Mitts 1g 10s (Strength, Agility), Sea Giant's Toe Ring 1g 48s (healing and spell damage), Soggy Boots 1g 3s (Intellect, Spirit). Honored: Booty Bay Bruiser's Buckshot, a gun, 3g 11s (attack power, Stamina); Souvenir Sea Shell, a necklace, 1g 66s (health regeneration, Stamina). Revered: Tough Guy's Eyepatch, 5g.", zone = 1434, goals = {
					{ kind = "buy", item = 274745, optional = true, note = "Deckswabber's Mitts, Friendly" },
					{ kind = "buy", item = 274746, optional = true, note = "Sea Giant's Toe Ring, Friendly" },
					{ kind = "buy", item = 274747, optional = true, note = "Soggy Boots, Friendly" },
					{ kind = "buy", item = 274748, optional = true, note = "Booty Bay Bruiser's Buckshot, Honored" },
					{ kind = "buy", item = 274749, optional = true, note = "Souvenir Sea Shell, Honored" },
					{ kind = "buy", item = 274022, optional = true, note = "Tough Guy's Eyepatch, Revered" },
				} },
				{ title = "Gadgetzan: Rettrick", tip = "Rettrick, Gadgetzan's quartermaster. Friendly, level 40 gear: Reflective Wristguards 2g 74s (Intellect, healing, spell damage), Sunburn Spaulders 2g 94s (Agility, attack power), Sandstorm Cover, a cloak, 2g 36s (Spirit, spell power). Honored: Jhordy's Misplaced Screwdriver, a one-handed weapon, 9g 46s (Strength, Agility); Suspicious Spare Part, a ring, 3g 80s (Strength, Stamina). Revered: the Stolen Wastewander Cowl, 10g.", zone = 1446, goals = {
					{ kind = "buy", item = 274750, optional = true, note = "Reflective Wristguards, Friendly" },
					{ kind = "buy", item = 274751, optional = true, note = "Sunburn Spaulders, Friendly" },
					{ kind = "buy", item = 274752, optional = true, note = "Sandstorm Cover, Friendly" },
					{ kind = "buy", item = 274753, optional = true, note = "Jhordy's Misplaced Screwdriver, Honored" },
					{ kind = "buy", item = 274754, optional = true, note = "Suspicious Spare Part, Honored" },
					{ kind = "buy", item = 274023, optional = true, note = "Stolen Wastewander Cowl, Revered" },
				} },
				{ title = "Everlook: Zippie Fizzbolt", tip = "Zippie Fizzbolt, Everlook's quartermaster. Friendly, level 50 gear: Steamwheedle Grips 3g 10s (Spirit, Intellect), Impractical Headwarmer 5g 84s (Agility, Stamina, frost resistance), Substandard Belt Chain 4g 68s (Agility, attack power), Coldmetal Guard, a chest, 10g 96s (Strength, Stamina). Honored, three trinkets at about 7g 55s: Everlook Pathcarver (nature resistance), Everlook Delivery Bot (frost resistance) and Parachute-Priest Pager (shadow resistance), the last two with a use. Revered: Fizzbolt's Fashionable Fedora, 25g.", zone = 1452, goals = {
					{ kind = "buy", item = 274755, optional = true, note = "Steamwheedle Grips, Friendly" },
					{ kind = "buy", item = 274756, optional = true, note = "Impractical Headwarmer, Friendly" },
