					{ kind = "buy", item = 274758, optional = true, note = "Coldmetal Guard, Friendly" },
					{ kind = "buy", item = 274759, optional = true, note = "Everlook Pathcarver, Honored" },
					{ kind = "buy", item = 274760, optional = true, note = "Everlook Delivery Bot, Honored" },
					{ kind = "buy", item = 274761, optional = true, note = "Parachute-Priest Pager, Honored" },
					{ kind = "buy", item = 274024, optional = true, note = "Fizzbolt's Fashionable Fedora, Revered" },
				} },
				{ title = "Powderfuse: Friz Frazzlespark", tip = "Friz Frazzlespark sells Powderfuse's rewards in Powderfuse Port, on the east coast of the Riverglades, alongside general goods. Friendly, level 40 gear: Crawler's Clackers 2g 74s (Stamina, attack power), Misplaced Pantaloons 2g 94s (Intellect, Spirit), Disengagement Ring 2g 36s (Agility, Spirit). Honored: Primitive Fishing Pole, a two-handed weapon, 9g 46s (Stamina, Strength, Agility); Thrash's Trash, a shield, 3g 80s (Stamina, spell damage, healing). Revered: Haughty Fellow's Monocle, 10g.", zone = 2548, goals = {
