				{ title = "Gahrron's Withering", tip = "Cauldron Lord Soulwrath guards the cauldron at Gahrron's Withering, in the east of the zone.", zone = 1422, goals = {
					{ kind = "collect", quest = 5225, objective = 1, item = 13196, note = "Gahrron's Withering Cauldron Key" },
					{ kind = "turnin", quest = 5225, note = "the Scourge Cauldron" },
					{ kind = "accept", quest = 5226, note = "Return to Chillwind Camp, +50" },
				} },
				{ title = "Chillwind Camp: done", tip = "Alchemist Arbington in the camp also ends The Key to Scholomance (200), after a longer chain that needs a Scholomance group.", zone = 1422, goals = {
					{ kind = "turnin", quest = 5226 },
				} },
				{ title = "Stormwind: Janice's parcel", tip = "Royal Factor Bathrilor stands in the city hall on Cathedral Square, beside Baros Alexston; Ol' Emma walks the canals.", zone = 1453, goals = {
					{ kind = "turnin", quest = 5022, note = "Royal Factor Bathrilor" },
					{ kind = "accept", quest = 5048, note = "Good Natured Emma, +100" },
					{ kind = "turnin", quest = 5048, note = "Ol' Emma" },
				} },
				{ title = "Morgan's Vigil: Dragonkin Menace", tip = "Helendis Riverhorn at Morgan's Vigil, in the south-east of the Burning Steppes, starts The True Masters: a chain to Lakeshire and Stormwind Keep, 175 Stormwind and 175 Darnassus reputation (level 54). The Black Broodlings and the Black Drake live on the slopes north of the Vigil; the Black Dragonspawn and Black Wyrmkin west of it, in the middle of the zone.", zone = 1428, goals = {
					{ kind = "accept", quest = 4182, note = "Dragonkin Menace, +100 Darnassus" },
					{ kind = "kill", quest = 4182, objective = 1, npc = 7047, count = 15, note = "Black Broodling" },
					{ kind = "kill", quest = 4182, objective = 2, npc = 7040, count = 10, note = "Black Dragonspawn" },
					{ kind = "kill", quest = 4182, objective = 3, npc = 7044, note = "Black Drake" },
					{ kind = "kill", quest = 4182, objective = 4, npc = 7041, count = 4, note = "Black Wyrmkin" },
					{ kind = "turnin", quest = 4182 },
					{ kind = "accept", quest = 4183, note = "The True Masters, +75 Darnassus" },
				} },
				{ title = "Lakeshire: Magistrate Solomon", tip = "Magistrate Solomon waits in the town hall of Lakeshire.", zone = 1433, goals = {
					{ kind = "turnin", quest = 4183 },
					{ kind = "accept", quest = 4184, note = "The True Masters, +75" },
				} },
				{ title = "Stormwind Keep", tip = "Highlord Bolvar Fordragon holds court in Stormwind Keep with Lady Katrana Prestor at his side: speak with her for the second of his quests.", zone = 1453, goals = {
					{ kind = "turnin", quest = 4184, note = "Highlord Bolvar Fordragon" },
					{ kind = "accept", quest = 4185 },
					{ kind = "kill", quest = 4185, objective = 1, npc = 1749, text = "Speak with Lady Katrana Prestor" },
					{ kind = "turnin", quest = 4185 },
					{ kind = "accept", quest = 4186, note = "The True Masters, +100" },
				} },
				{ title = "Lakeshire: Solomon again", tip = "With a group the chain goes on into Blackrock Depths: Marshal Windsor, Jail Break! and The Great Masquerade back in Stormwind pay about 750 Stormwind more, Maxwell's Mission (Lower Blackrock Spire) 250, Delivery to Ridgewell 135. Order Must Be Restored (Nathanos Blightcaller in the Eastern Plaguelands) pays 200, The Key to Scholomance 200; Onyxia's head 400 and Nefarian's 200 when the raids open.", zone = 1433, goals = {
					{ kind = "turnin", quest = 4186, note = "Magistrate Solomon" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a non-Human stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Humans start 900 higher: 88 turn-ins; a Skyborne's Exploring the Alliance paid 100, two fewer). The level 52-58 quests above take 23 turn-ins off; every Elwynn hub you did takes 20 to 30 more off. More quest hubs pay Stormwind, in full while they are no more than 5 levels below you: Westfall (about 2,500 in all), Redridge's Lakeshire (about 3,000) and Duskwood's Darkshire (about 2,900). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", zone = 1453, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7796, optional = true, direct = true },
					{ kind = "rep", factionId = 72, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored: in Classic Stormwind's vendors take 10% off for you, Katie Hunter's horses (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", zone = 1453, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7796, optional = true, direct = true },
					{ kind = "rep", factionId = 72, standing = "Revered" },
				} },
				{ title = "Additional Runecloth to Exalted", tip = "Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 Runecloth. At Exalted, Katie Hunter at Eastvale Logging Camp sells her horses to other races in Classic; the Horse and Swift Horse guides cover them.", zone = 1453, goals = {
					{ kind = "collect", item = 14047, count = 20, nearest = true, optional = true },
					{ kind = "turnin", quest = 7796, optional = true, direct = true },
					{ kind = "rep", factionId = 72, standing = "Exalted" },
				} },
			},
		},
		{
			id = "forever/reputation/thorium-brotherhood", title = "Thorium Brotherhood Reputation", category = "Reputation", folder = "Reputation · Raids and dungeons", levels = { 48, 60 }, zone = 1427, version = 1, revision = "2b279f40e2066f177f4c99b04247dad42f912990768f71e5cf65ba562c557a43", legacyRevision = "ebf02e2a72ddf42a7feff534e8e9abeb6e387b9338aa3ffbb6b8f9f72dc30b89", keywords = { "Thorium Brotherhood", "Thorium Point", "Master Smith Burninate", "Hansel Heavyhands", "Lokhtos Darkbargainer", "Grim Guzzler", "Blackrock Depths", "Shadowforge Key", "Fiery Flux", "Incendosaur Scale", "Coal", "Dark Iron Residue", "Dark Iron Ore", "Fiery Core", "Lava Core", "Core Leather", "Blood of the Mountain", "Molten Core", "fire resistance", "Flarecore", "Dark Iron", "Imperial Plate", "Sulfuron" }, rewards = { { text = "Lokhtos Darkbargainer's 29 recipes, from Friendly to Exalted" }, { item = 17051 }, { item = 17018 }, { item = 19212 }, { item = 19210 }, { item = 19211 } }, why = "Lokhtos's Molten Core recipes: fire resistance gear, Dark Iron armour and the Exalted epic weapon plans.",
			steps = {
				{ title = "Thorium Point", tip = "Thorium Point is the scaffolded camp on the north-west rim of the Cauldron, with a flight point. Everyone starts Neutral with the Brotherhood. These seven quests (level 48 to 50) pay 100 reputation each: 700 in all, 800 with the pillow below. Forever pays them in full at any level. Master Smith Burninate's What the Flux? also opens his Fiery Flux turn-ins, so it is needed at any level. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%.", zone = 1427, goals = {
					{ kind = "accept", quest = 7722, note = "Master Smith Burninate" },
					{ kind = "accept", quest = 7723, note = "Hansel Heavyhands" },
					{ kind = "accept", quest = 7724 },
					{ kind = "accept", quest = 7727 },
					{ kind = "accept", quest = 7728, object = 179827, note = "The Wanted/Missing/Lost & Found board" },
					{ kind = "accept", quest = 7729, object = 179827 },
					{ kind = "accept", quest = 7701, object = 179827, optional = true, note = "Overseer Maltorius is elite" },
				} },
				{ title = "Golems and Dark Iron dwarves", tip = "Heavy War Golems and the Dark Iron Taskmasters and Slavers work all over the floor of the Cauldron below Thorium Point. The Smithing Tuyere drops from Dark Iron Steamsmiths at the furnaces in the middle, the Lookout's Spyglass from Dark Iron Lookouts on the southern ridges: about one in ten of each.", zone = 1427, goals = {
					{ kind = "kill", quest = 7723, objective = 1, npc = 5854, count = 20, note = "Heavy War Golem" },
					{ kind = "kill", quest = 7729, objective = 1, npc = 5846, count = 15, note = "Dark Iron Taskmaster" },
					{ kind = "kill", quest = 7729, objective = 2, npc = 5844, count = 15, note = "Dark Iron Slaver" },
					{ kind = "collect", quest = 7728, objective = 1, item = 18959, note = "Smithing Tuyere, Dark Iron Steamsmiths" },
					{ kind = "collect", quest = 7728, objective = 2, item = 18960, note = "Lookout's Spyglass, Dark Iron Lookouts" },
				} },
				{ title = "Greater Lava Spiders", tip = "The spiders roam the lava pools and plateaus of the south-west.", zone = 1427, goals = {
					{ kind = "kill", quest = 7724, objective = 1, npc = 5858, count = 20 },
				} },
				{ title = "The Slag Pit", tip = "The Slag Pit is the cave in the north of the Cauldron. The Secret Plans: Fiery Flux lie on a bench on its upper ledge, beside Overseer Maltorius: a level 50 elite with guards, easy at 60, worth a group below 55. Incendosaurs swim in the lava pools inside and around the north rim; every one drops two to four Incendosaur Scales. Keep every scale: Burninate's turn-ins take two each. If you find Chambermaid Pillaclencher's ornate pillow in the dwarves' sleeping quarters, take it to Evonice Sootsmoker at Thorium Point for 100 more.", zone = 1427, goals = {
					{ kind = "collect", quest = 7722, objective = 1, item = 18922, note = "Secret Plans: Fiery Flux" },
					{ kind = "kill", quest = 7727, objective = 1, npc = 9318, count = 20, note = "Incendosaur" },
					{ kind = "collect", quest = 7701, objective = 1, item = 18946, optional = true, note = "Head of Overseer Maltorius, elite: group up below 55" },
					{ kind = "accept", quest = 7704, optional = true, note = "Chambermaid Pillaclencher's Pillow, if you find it" },
				} },
				{ title = "Back to Thorium Point", zone = 1427, goals = {
					{ kind = "turnin", quest = 7722, note = "Master Smith Burninate" },
					{ kind = "turnin", quest = 7723, note = "Hansel Heavyhands" },
					{ kind = "turnin", quest = 7724 },
					{ kind = "turnin", quest = 7727 },
					{ kind = "turnin", quest = 7728, note = "Taskmaster Scrange" },
					{ kind = "turnin", quest = 7729 },
					{ kind = "turnin", quest = 7701, optional = true, note = "Lookout Captain Lolo Longstriker" },
					{ kind = "turnin", quest = 7704, optional = true, note = "Evonice Sootsmoker" },
				} },
				{ title = "Imperial Plate, for Blacksmiths", tip = "Blacksmiths with 265 skill can buy their way up with Thorium Bars: Derotain Mudsipper in Gadgetzan trades the Imperial Plate plans for bars, and each pays Brotherhood reputation. A Blue Light Bargain opens them (100). Belt 20 bars (100), Bracer 20 (100), Shoulders 20 (100), Boots 40 (150), Helm 50 (200), Chest 60 (200), Leggings 60 (200): 1,150 reputation for 270 Thorium Bars. They count at any standing, so do them before Burninate's turn-ins.", when = { { profession = "Blacksmithing", value = 265, test = "skill" }, { level = 50, test = "level", op = ">=" } }, zone = 1446, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 7652, optional = true },
					{ kind = "turnin", quest = 7652, optional = true },
					{ kind = "accept", quest = 7653, optional = true },
					{ kind = "turnin", quest = 7653, optional = true, note = "Belt, 20 Thorium Bars" },
					{ kind = "accept", quest = 7655, optional = true },
					{ kind = "turnin", quest = 7655, optional = true, note = "Bracer, 20 Thorium Bars" },
					{ kind = "accept", quest = 7659, optional = true },
					{ kind = "turnin", quest = 7659, optional = true, note = "Shoulders, 20 Thorium Bars" },
					{ kind = "accept", quest = 7654, optional = true },
					{ kind = "turnin", quest = 7654, optional = true, note = "Boots, 40 Thorium Bars" },
					{ kind = "accept", quest = 7657, optional = true },
					{ kind = "turnin", quest = 7657, optional = true, note = "Helm, 50 Thorium Bars" },
					{ kind = "accept", quest = 7656, optional = true },
					{ kind = "turnin", quest = 7656, optional = true, note = "Chest, 60 Thorium Bars" },
					{ kind = "accept", quest = 7658, optional = true },
					{ kind = "turnin", quest = 7658, optional = true, note = "Leggings, 60 Thorium Bars" },
				} },
				{ title = "Heavy Leather, if you skin (Alliance)", tip = "Only if you take the Heavy Leather turn-in below and skin it yourself: the yetis and mountain lions here (level 28 to 40) yield it. Ten per turn-in.", only = { factions = { "Alliance" } }, zone = 1416, goals = {
					{ kind = "collect", item = 4234, count = 10, map = 1416, x = 38.2, y = 91.9, optional = true, note = "Heavy Leather" },
				} },
				{ title = "Heavy Leather, if you skin (Horde)", tip = "Only if you take the Heavy Leather turn-in below and skin it yourself: the wyverns, basilisks and scorpids here (level 28 to 40) yield it. Ten per turn-in.", only = { factions = { "Horde" } }, zone = 1441, goals = {
					{ kind = "collect", item = 4234, count = 10, map = 1441, x = 78.5, y = 59, optional = true, note = "Heavy Leather" },
				} },
				{ title = "Fiery Flux to Friendly", tip = "Neutral to Friendly is 3,000 reputation. Burninate takes Restoring Fiery Flux Supplies only while you are Neutral: 25 reputation for 2 Incendosaur Scales, 1 Coal and either 4 Iron Bars, 4 Kingsblood or 10 Heavy Leather. These are level 60 quests, so they always pay in full. After the 700 from the Thorium Point quests that is 92 turn-ins: 184 scales (about 60 Incendosaurs), 92 Coal (Burninate sells it at 5 silver: 4g 60s) and 368 Iron Bars, 368 Kingsblood or 920 Heavy Leather. If those quests paid you only 140 at 60, it is 115 turn-ins: 230 scales, 115 Coal (5g 75s) and 460 bars or Kingsblood or 1,150 Heavy Leather. Miners smelt the bars from Iron Ore, herbalists pick Kingsblood, skinners get Heavy Leather from beasts of level 28 to 40; all three sell on the Auction House. Pick whichever is cheapest for you, or mix them. Blacksmiths who did the Imperial Plate quests need 46 fewer turn-ins.", zone = 1427, goals = {
					{ kind = "collect", item = 18944, count = 20, optional = true, note = "Incendosaur Scale, 2 per turn-in" },
					{ kind = "buy", npc = 14624, item = 3857, count = 10, optional = true, note = "Coal, 1 per turn-in" },
					{ kind = "turnin", quest = 8241, optional = true, direct = true, note = "via Iron: 4 Iron Bars" },
					{ kind = "collect", item = 3356, count = 4, optional = true, note = "Kingsblood, 4 per turn-in" },
					{ kind = "turnin", quest = 7736, optional = true, direct = true, note = "via Kingsblood: 4 Kingsblood" },
					{ kind = "turnin", quest = 8242, optional = true, direct = true, note = "via Heavy Leather: 10 Heavy Leather" },
					{ kind = "rep", factionId = 59, standing = "Friendly" },
				} },
				{ title = "Gaining Acceptance to Honored", tip = "Friendly to Honored is 6,000 reputation. While you are Friendly Burninate takes Gaining Acceptance instead: 25 reputation for 4 Dark Iron Residue, 240 turn-ins and 960 residue in all. About a third of the Dark Iron dwarves in Blackrock Depths drop residue, sometimes several at once; it also sells on the Auction House. Dark Iron Ore or Molten Core materials at Lokhtos (next steps) count here too. Lokhtos's shop opens at Friendly: Flarecore Gloves 8g, Corehound Boots 15g, Molten Helm 16g, Dark Iron Bracers 7g, Enchant Weapon - Strength 3g, Transmute Elemental Fire 12g.", zone = 1427, goals = {
					{ kind = "collect", item = 18945, count = 40, optional = true, note = "Dark Iron Residue, 4 per turn-in" },
					{ kind = "turnin", quest = 7737, optional = true, direct = true },
					{ kind = "rep", factionId = 59, standing = "Honored" },
				} },
				{ title = "The Shadowforge Key", tip = "Optional, and it saves every later trip to Lokhtos the Ring of Law fight. Franclorn Forgewright is a ghost in the middle of Blackrock Mountain: only the dead see him, so die in the mountain and walk to his tomb as a spirit. He sends you after Fineous Darkvire in Blackrock Depths, who always drops Ironfel; place it on Franclorn's monument in the Shrine of Thaurissan and the Shadowforge Key falls out. Blackrock Depths is a five-player dungeon: group up.", zone = 1428, goals = {
					{ kind = "accept", quest = 3801, optional = true, note = "Franclorn Forgewright, as a ghost" },
					{ kind = "turnin", quest = 3801, optional = true },
					{ kind = "accept", quest = 3802, optional = true },
					{ kind = "collect", quest = 3802, objective = 1, item = 10999, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Ironfel, Fineous Darkvire inside Blackrock Depths" },
					{ kind = "turnin", quest = 3802, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Monument of Franclorn Forgewright, Shrine of Thaurissan in Blackrock Depths" },
				} },
				{ title = "Lokhtos Darkbargainer to Revered", tip = "Honored to Revered is 12,000 reputation, all of it from Lokhtos Darkbargainer in the Grim Guzzler, the tavern deep in Blackrock Depths. The way there: with the Shadowforge Key, open the East Garrison door near the entrance; without it, win the Ring of Law and climb to the East Garrison. Pull the Shadowforge Lock there to lower the bridge to the Manufactory, the only way to the Guzzler. His Favor Amongst the Brotherhood turn-ins never stop counting: 1 Fiery Core, 1 Lava Core or 1 Blood of the Mountain for 200, 2 Core Leather for 150, 10 Dark Iron Ore for 50. To Revered that is 60 cores, 160 Core Leather or 2,400 Dark Iron Ore. The cores and the leather come only from the Molten Core, which is not among the first raids Blizzard has announced for Forever; until it opens, Dark Iron Ore is the way. Miners with 230 skill find Dark Iron Deposits around the Cauldron in Searing Gorge, across the Burning Steppes and inside Blackrock Depths, and a deposit now and then gives a Blood of the Mountain; the ore also sells on the Auction House. Honored opens Flarecore Mantle 18g, Flarecore Robe 6g, Lava Belt 6g, Black Dragonscale Boots 16g, Fiery Chain Girdle 9g, Dark Iron Helm 6g, Dark Iron Reaver 22g, Dark Iron Destroyer 22g and Enchant Weapon - Mighty Spirit 8g.", zone = 1427, goals = {
					{ kind = "goto", label = "Blackrock Mountain", map = 1427, x = 32.1, y = 94.7 },
					{ kind = "collect", item = 17010, count = 5, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Fiery Core: Firewalkers, Flameguards and Firelords in the Molten Core" },
					{ kind = "collect", item = 17011, count = 5, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Lava Core: Lava Elementals, Lava Reavers and Molten Destroyers" },
					{ kind = "collect", item = 17012, count = 2, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Core Leather: skin Ancient Core Hounds and Magmadar" },
					{ kind = "collect", item = 11382, count = 1, optional = true, note = "Blood of the Mountain: Molten Destroyers, sometimes a Dark Iron Deposit" },
					{ kind = "collect", item = 11370, count = 10, optional = true, note = "Dark Iron Ore: Dark Iron Deposits, Mining 230" },
					{ kind = "turnin", quest = 6643, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "Fiery Core: 200" },
					{ kind = "turnin", quest = 6644, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "Lava Core: 200" },
					{ kind = "turnin", quest = 6646, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "Blood of the Mountain: 200" },
					{ kind = "turnin", quest = 6645, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "2 Core Leather: 150" },
					{ kind = "turnin", quest = 6642, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "10 Dark Iron Ore: 50" },
					{ kind = "rep", factionId = 59, standing = "Revered" },
				} },
				{ title = "A Binding Contract", tip = "Carry a Sulfuron Ingot (Golemagg the Incinerator, the Molten Core) to Lokhtos and he offers you a contract: ask about the offer and take it. Handing in the contract with the ingot pays 200 reputation and Plans: Sulfuron Hammer, the hammer Blacksmiths later join with the Eye of Sulfuras into Sulfuras, Hand of Ragnaros.", when = { { item = 17203, test = "has" }, { level = 60, test = "level", op = ">=" } }, zone = 1427, goals = {
					{ kind = "level", level = 60 },
					{ kind = "accept", quest = 7604, optional = true, note = "Thorium Brotherhood Contract, from Lokhtos" },
					{ kind = "collect", quest = 7604, objective = 1, item = 17203, map = 1427, x = 32.1, y = 94.7, optional = true, note = "Sulfuron Ingot, already in your bags" },
					{ kind = "turnin", quest = 7604, map = 1427, x = 32.1, y = 94.7, optional = true },
				} },
				{ title = "Lokhtos Darkbargainer to Exalted", tip = "Revered to Exalted is 21,000 more: 105 cores or Bloods, 280 Core Leather or 4,200 Dark Iron Ore. The Molten Core materials come from the raid, so a guild or the auction house does most of the work. Revered opens Flarecore Leggings 9g, Chromatic Gauntlets 9g, Corehound Belt 9g, Molten Belt 9g, Dark Iron Leggings 18g, Dark Iron Gauntlets 8g, Fiery Chain Shoulders 20g, Black Amnesty 7g, Blackfury 7g and Enchant Weapon - Mighty Intellect 10g. Exalted opens the epic weapon plans Ebon Hand, Blackguard and Nightfall (12g each) and Dark Iron Boots 8g.", zone = 1427, goals = {
					{ kind = "turnin", quest = 6643, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "Fiery Core: 200" },
					{ kind = "turnin", quest = 6644, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "Lava Core: 200" },
					{ kind = "turnin", quest = 6646, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "Blood of the Mountain: 200" },
					{ kind = "turnin", quest = 6645, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "2 Core Leather: 150" },
					{ kind = "turnin", quest = 6642, map = 1427, x = 32.1, y = 94.7, optional = true, direct = true, note = "10 Dark Iron Ore: 50" },
					{ kind = "rep", factionId = 59, standing = "Exalted" },
				} },
			},
		},
		{
			id = "forever/reputation/thunder-bluff", title = "Thunder Bluff Reputation", category = "Reputation", folder = "Reputation · Cities", faction = "Horde", levels = { 12, 60 }, zone = 1456, version = 1, revision = "7ae28a844c93ad695479ae17149524cccc892ba1e27f5320ef1cd829c79c0aa8", legacyRevision = "3cd6044cecc0f01152af0eeda9036b72c75cdb50a378e53713865dcdaf7a7347", keywords = { "Thunder Bluff", "Rumstag Proudstrider", "cloth quartermaster", "cloth donation", "Runecloth", "Additional Runecloth", "Wool", "Silk", "Mageweave", "Morrowgrain", "Evergreen Pouch", "Bashana Runetotem", "Storm Shadowhoof", "Shy-Rotam", "Guarding Secrets", "Camp Narache", "Bloodhoof Village", "Gloomrise", "kodo mount", "Harb Clawhoof" }, rewards = { { text = "Exalted with Thunder Bluff" }, { item = 18793 } }, why = "Mulgore quests while you level, Winterspring quests and Morrowgrain from 55, then Runecloth to Exalted.",
			steps = {
				{ title = "Thunder Bluff: how it works", tip = "Thunder Bluff reputation comes from quests, Morrowgrain and cloth. Rumstag Proudstrider, the cloth quartermaster, stands on the central rise among the leatherworkers' and tailors' tents. He takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with Thunder Bluff also gives a quarter as much to Orgrimmar, the Undercity and the Darkspear Trolls. While you level, do Thunder Bluff's quests within 5 levels of them: Mulgore at 1 to 12, Camp Taurajo and the Crossroads at 13 to 22, Thousand Needles at 25 to 30. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored Thunder Bluff's merchants sell to you for 10% less (the Classic rule), the kodo vendor included; at Exalted other races can buy the kodos: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60, once you have mount training. Thunder Bluff has no tabard or other reward.", zone = 1456, goals = {
					{ kind = "goto", label = "Rumstag Proudstrider", map = 1456, x = 43.1, y = 42.7, note = "his donations are handed in from his window and never enter the log" },
				} },
				{ title = "Camp Narache (optional hub)", tip = "Forever pays these old quests in full at any level. Camp Narache, at the south end of Mulgore: about 1,100 Thunder Bluff reputation in 25 minutes. Starting-zone quests give the other cities no share. Grull Hawkwind and Chief Hawkwind stand in the camp, Brave Windfeather at its edge.", label = "narache", zone = 1456, goals = {
					{ kind = "accept", quest = 747, note = "Grull Hawkwind: The Hunt Begins, +100" },
					{ kind = "accept", quest = 752, note = "Chief Hawkwind: A Humble Task, +50" },
					{ kind = "accept", quest = 3376, note = "Brave Windfeather: Break Sharptusk!, +200" },
				} },
