				{ title = "Rumstag Proudstrider: A Donation of Wool", tip = "From here it is cloth. Wool, Silk and Mageweave must all be handed in before Rumstag offers the Runecloth donation, and Additional Runecloth needs the Runecloth donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, Runecloth 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey.", zone = 1440, goals = {
					{ kind = "collect", item = 2592, count = 60, map = 1440, x = 36, y = 37, note = "Wool Cloth: the Thistlefur furbolgs drop it about one kill in four" },
					{ kind = "turnin", quest = 7820, direct = true, note = "Rumstag Proudstrider: A Donation of Wool, +150" },
				} },
				{ title = "A Donation of Silk", tip = "Silk: the Syndicate in Hillsbrad and Alterac drop it about one kill in three, or buy it.", zone = 1456, goals = {
