					{ kind = "turnin", quest = 7822, direct = true, note = "+150" },
				} },
				{ title = "A Donation of Runecloth", tip = "Runecloth: the Scarlet at Tyr's Hand in the Eastern Plaguelands, the Gordok ogres outside Dire Maul in Feralas and the Twilight camps of Silithus drop it about one kill in three. The Auction House is faster if you have gold.", zone = 1456, goals = {
					{ kind = "level", level = 50 },
					{ kind = "collect", item = 14047, count = 60, map = 1423, x = 68, y = 69.5, frame = "live", note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7823, direct = true, note = "+150" },
				} },
				{ title = "Everlook: Storm Shadowhoof", tip = "Storm Shadowhoof's four quests are level 56 to 60, so they pay in full: 400 Thunder Bluff reputation. Ursius, an elite bear, walks a loop over the four hills north of Everlook: wait on a hilltop for him.", zone = 1452, goals = {
					{ kind = "level", level = 55 },
					{ kind = "accept", quest = 5054, note = "Ursius of the Shardtooth, +100" },
					{ kind = "kill", quest = 5054, objective = 1, npc = 10806, note = "Ursius, elite" },
					{ kind = "turnin", quest = 5054 },
					{ kind = "accept", quest = 5055, note = "Brumeran of the Chillwind, +100" },
				} },
				{ title = "Brumeran and Shy-Rotam", tip = "Brumeran, an elite chimera, spawns south of Everlook. For Shy-Rotam, kill frostsabers north of Everlook until one drops Sacred Frostsaber Meat (about one in ten), then use the meat at the Stone of Shy-Rotam, far to the north, and kill the great cat that comes. If you have done Trull Failbane's Wild Guardians quests (the Orgrimmar guide), the Crazed, Moontouched and Berserk owlbeasts around Everlook sometimes drop a Blue-feathered Necklace: it starts Guarding Secrets, 50 Orgrimmar and then 100 Thunder Bluff reputation in full.", zone = 1452, goals = {
					{ kind = "kill", quest = 5055, objective = 1, npc = 10807, note = "Brumeran, elite" },
					{ kind = "turnin", quest = 5055, note = "Storm Shadowhoof" },
					{ kind = "accept", quest = 5056, note = "Shy-Rotam, +150" },
					{ kind = "collect", item = 12733, optional = true, note = "Sacred Frostsaber Meat, from the frostsabers" },
					{ kind = "kill", quest = 5056, objective = 1, npc = 10737, note = "Shy-Rotam" },
					{ kind = "turnin", quest = 5056, note = "Storm Shadowhoof" },
					{ kind = "accept", quest = 5057, note = "Past Endeavors, +50" },
					{ kind = "turnin", quest = 5057 },
				} },
				{ title = "Bloodvenom Post: Trull Failbane", tip = "Trull Failbane stands at Bloodvenom Post, through the Timbermaw tunnel south of Winterspring.", when = { { test = "onquest", quests = { 4882 } } }, zone = 1448, goals = {
					{ kind = "turnin", quest = 4882, note = "Trull Failbane" },
					{ kind = "accept", quest = 4883, note = "Guarding Secrets, +100: to Nara Wildmane in Thunder Bluff" },
				} },
				{ title = "Thunder Bluff: Nara Wildmane", tip = "Nara Wildmane stands on Elder Rise, beside Arch Druid Hamuul Runetotem.", when = { { test = "onquest", quests = { 4883 } } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 4883, note = "Nara Wildmane" },
				} },
				{ title = "Morrowgrain (optional)", tip = "Morrowgrain to Thunder Bluff takes 10 Morrowgrain for 50, as often as you like, and pays in full at 60, but it is slow: the Evergreen Pouch grows one casing every 10 minutes and a casing holds about one Morrowgrain on average, so each hand-in takes about 90 minutes of waiting, 18 Un'Goro Soil and 9 seed packets (90 silver). It runs beside whatever else you do: a little over 30 reputation an hour. The chain before it is level 50. Innkeeper Pala sends you to Arch Druid Hamuul Runetotem on Elder Rise; he wants 20 Un'Goro Soil.", label = "morrowgrain", zone = 1456, goals = {
					{ kind = "accept", quest = 3762, note = "Innkeeper Pala: Assisting Arch Druid Runetotem" },
					{ kind = "turnin", quest = 3762, note = "Arch Druid Hamuul Runetotem" },
					{ kind = "accept", quest = 3761, note = "Un'Goro Soil, +100" },
				} },
				{ title = "Un'Goro Crater: Un'Goro Soil", tip = "Nearly every beast, plant and silithid in the crater drops Un'Goro Soil, about one kill in three (the Bloodpetals and the Gorishi wasps about one in two), and the dirt mounds give it too. Take far more than 20: every casing uses 2, about 18 for each Morrowgrain hand-in.", when = { { label = "morrowgrain", test = "done" } }, zone = 1449, goals = {
					{ kind = "collect", quest = 3761, objective = 1, item = 11018, count = 20, note = "Un'Goro Soil" },
				} },
				{ title = "Thunder Bluff: Morrowgrain Research", tip = "Ghede takes the soil. Bashana Runetotem sells the Evergreen Pouch (1 gold) and Packets of Tharlendris Seeds (10 silver each). With a seed packet and 2 Un'Goro Soil in your bags, use the pouch: it grows an Evergreen Herb Casing, once every 10 minutes. Open each casing: about one in three holds 1 to 5 Morrowgrain, the rest common herbs. Use the pouch whenever it is ready while you follow the rest of this guide.", when = { { label = "morrowgrain", test = "done" } }, zone = 1456, goals = {
					{ kind = "turnin", quest = 3761, note = "Ghede" },
					{ kind = "accept", quest = 3782, note = "Arch Druid Hamuul Runetotem: Morrowgrain Research" },
					{ kind = "turnin", quest = 3782, note = "Bashana Runetotem" },
					{ kind = "accept", quest = 3786, note = "Morrowgrain Research, +100" },
					{ kind = "buy", npc = 9087, item = 11020, note = "Evergreen Pouch, 1 gold" },
					{ kind = "buy", npc = 9087, item = 11022, count = 10, note = "Packet of Tharlendris Seeds, 10 silver each" },
				} },
				{ title = "Morrowgrain as you go", when = { { label = "morrowgrain", test = "done" } }, along = true, alongUntil = "morrowgrain-in", zone = 1456, goals = {
					{ kind = "collect", quest = 3786, objective = 1, item = 11040, count = 10, map = 1456, x = 71.1, y = 34.2, note = "Morrowgrain: use the pouch every 10 minutes and open the casings; Bashana takes it" },
				} },
				{ title = "Bashana Runetotem: Morrowgrain Research", tip = "Bashana Runetotem stands on Elder Rise. If your 10 Morrowgrain are not ready yet, skip this step and go on with the cloth: the cloth steps below list the Morrowgrain hand-in too.", when = { { label = "morrowgrain", test = "done" } }, label = "morrowgrain-in", zone = 1456, goals = {
