					{ kind = "turnin", quest = 3804, optional = true, direct = true, note = "Morrowgrain to Thunder Bluff, +50" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (a tauren starts at Friendly 1,000: 100 hand-ins; an Undead at Neutral 500 first needs 50 more to reach Friendly). Hand in every 20 you carry, one after another.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7825, optional = true, direct = true, note = "Rumstag Proudstrider: Additional Runecloth, +50" },
					{ kind = "collect", item = 11040, count = 10, map = 1456, x = 71.1, y = 34.2, optional = true, note = "Morrowgrain, if you grow it: Bashana takes it" },
					{ kind = "turnin", quest = 3804, optional = true, direct = true, note = "Bashana Runetotem: Morrowgrain to Thunder Bluff, +50" },
					{ kind = "rep", factionId = 81, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth, fewer if you also hand in Morrowgrain. Blackrock Depths pays too: Disharmony of Flame and Disharmony of Fire from Thunderheart at Kargath (Lord Incendius, 150 in full).", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7825, optional = true, direct = true, note = "Additional Runecloth, +50" },
