					{ kind = "rep", factionId = 81, standing = "Revered" },
				} },
				{ title = "Additional Runecloth to Exalted", tip = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, Harb Clawhoof in Bloodhoof Village sells the kodos to every Horde race: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7825, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "collect", item = 11040, count = 10, map = 1456, x = 71.1, y = 34.2, optional = true, note = "Morrowgrain, if you grow it" },
