		{
			id = "forever/reputation/timbermaw-hold", title = "Timbermaw Hold Reputation", category = "Reputation", folder = "Reputation · World", levels = { 48, 60 }, zone = 1448, version = 1, revision = "4145f46020015bdfa2cd62fc4627061594114d63d8ad8b8f420f385bbd8b03f4", legacyRevision = "1b60eb0d237c3eaae0d4ac88352f73d250220476d1c3426b917d158335e3be46", keywords = { "Timbermaw Hold", "furbolg", "Grazle", "Nafien", "Salfa", "Meilosh", "Gorn One Eye", "Kernda", "Deadwood Headdress Feather", "Winterfall Spirit Beads", "Deadwood Ritual Totem", "Winterfall Ritual Totem", "Defender of the Timbermaw", "The Root of All Evil", "Enchant Weapon - Agility", "Warbear Harness", "Mantle of the Timbermaw", "Wintersaber Trainers" }, rewards = { { item = 21326 }, { item = 19445 }, { text = "Recipes for Leatherworkers, Tailors, Enchanters and Alchemists from Friendly to Revered" } }, why = "Safe passage through the tunnels, agility enchants and furbolg recipes; the trinket at Exalted.",
			steps = {
				{ title = "Grazle", tip = "Timbermaw Hold starts at Hostile (2,500 of 3,000), so its furbolgs attack you in their tunnels; Grazle, Nafien and Salfa talk to everyone. Grazle waits by the road in the south of Felwood, near the Emerald Sanctuary. Every Deadwood and Winterfall furbolg you kill gives 5 reputation up to the last point of Honored, so the quests below pay twice. The Legacy perk Diplomat adds up to 10% to every gain.", zone = 1448, goals = {
					{ kind = "accept", quest = 8460 },
				} },
				{ title = "Deadwood Village", tip = "The Deadwood furbolgs (level 48-50) hold the village at the south end of Felwood. Keep every Deadwood Headdress Feather: they are worth 10 reputation each later and never stop counting. Overlord Ror (15 reputation) and the rare Ragepaw (25) live here and count until Exalted. Forever pays quests in full at any level; in Classic grey mobs gave about a fifth, about 1 a kill for these furbolgs at 60. Do it while leveling if you can.", zone = 1448, goals = {
					{ kind = "kill", quest = 8460, objective = 1, npc = 7153 },
					{ kind = "kill", quest = 8460, objective = 2, npc = 7155 },
					{ kind = "kill", quest = 8460, objective = 3, npc = 7154 },
					{ kind = "kill", npc = 9464, optional = true, note = "Overlord Ror" },
					{ kind = "kill", npc = 14342, optional = true, note = "Ragepaw, rare" },
				} },
				{ title = "Back to Grazle", zone = 1448, goals = {
					{ kind = "turnin", quest = 8460 },
					{ kind = "accept", quest = 8462 },
				} },
				{ title = "Nafien", tip = "Nafien stands at the Felwood mouth of the Timbermaw tunnel, at the top of the road in the north of Felwood.", zone = 1448, goals = {
					{ kind = "turnin", quest = 8462 },
					{ kind = "accept", quest = 8461 },
				} },
				{ title = "Felpaw Village", tip = "The northern Deadwood (level 53-55) camp just south of the tunnel. They drop feathers about half the time: the best feather spot. Chieftain Bloodmaw gives 15 until Exalted.", zone = 1448, goals = {
					{ kind = "kill", quest = 8461, objective = 1, npc = 7156 },
					{ kind = "kill", quest = 8461, objective = 2, npc = 7157 },
					{ kind = "kill", quest = 8461, objective = 3, npc = 7158 },
					{ kind = "kill", npc = 9462, optional = true, note = "Chieftain Bloodmaw" },
				} },
				{ title = "Back to Nafien", tip = "These quests and their kills bring you just past Unfriendly (500 from the start). If Timbermaw Ally paid you less (at level 60 in Classic: 30), kill about 40 more northern Deadwood. From Unfriendly the Timbermaw in the tunnel leave you alone.", zone = 1448, goals = {
					{ kind = "turnin", quest = 8461 },
					{ kind = "accept", quest = 8465 },
					{ kind = "rep", factionId = 576, standing = "Unfriendly" },
				} },
				{ title = "Salfa", tip = "Walk through the tunnel to its Winterspring mouth; Salfa stands just outside. Do not attack any Timbermaw: each one costs 25 reputation.", zone = 1452, goals = {
					{ kind = "turnin", quest = 8465 },
					{ kind = "accept", quest = 8464 },
				} },
				{ title = "Winterfall Village", tip = "Winterfall Village lies in the east of Winterspring, just past Everlook. Keep every Winterfall Spirit Beads you loot (10 reputation each later). The Shamans, Den Watchers and Ursas share their spawn points, so kill every furbolg in the village to make the ones you need appear; more Ursas walk the ridge just south-west of the village. Grizzle Snowpaw (rare) and High Chief Winterfall, in the cave at the back, give 25 until Exalted. Alliance: the Wintersaber Trainers' Winterfall Intrusion asks for the same Shamans and Ursas.", zone = 1452, goals = {
					{ kind = "kill", quest = 8464, objective = 1, npc = 7439 },
					{ kind = "kill", quest = 8464, objective = 2, npc = 7440 },
					{ kind = "kill", quest = 8464, objective = 3, npc = 7438 },
					{ kind = "kill", npc = 10199, optional = true, note = "Grizzle Snowpaw, rare" },
					{ kind = "kill", npc = 10738, optional = true, note = "High Chief Winterfall, elite" },
				} },
				{ title = "Back to Salfa", tip = "Feathers for Grazle, Feathers for Nafien and Beads for Salfa are open now: 50 reputation for 5 feathers or 5 beads, as often as you like. Do not hand them in yet.", zone = 1452, goals = {
					{ kind = "turnin", quest = 8464 },
				} },
				{ title = "Unfriendly to Neutral", tip = "Unfriendly to Neutral is 3,000: about 540 more kills after these quests. Three camps: the northern Deadwood by the Felwood mouth of the tunnel; the Winterfall camps around Frostfire Hot Springs and Timbermaw Post, just south and south-east of Salfa (Pathfinders give 6 a kill, Den Watchers and Totemics 5, the shortest walk to a turn-in); and Winterfall Village in the east. Pick the least crowded. Keep all feathers and beads.", zone = 1452, goals = {
					{ kind = "level", level = 52 },
					{ kind = "collect", item = 21377, count = 5, nearest = true, optional = true, note = "Deadwood Headdress Feathers: keep them" },
					{ kind = "collect", item = 21383, count = 5, nearest = true, optional = true, note = "Winterfall Spirit Beads: keep them" },
					{ kind = "kill", npc = 7442, map = 1452, x = 31.5, y = 36, optional = true, note = "Winterfall Pathfinders, Frostfire Hot Springs" },
					{ kind = "rep", factionId = 576, standing = "Neutral" },
				} },
				{ title = "Deadwood Ritual Totem", tip = "The northern Deadwood rarely drop a Deadwood Ritual Totem (about 3%). From Neutral, Kernda takes it in the tunnel, on the Felwood side: 150 reputation and two Major Healing and Mana Potions.", when = { { item = 20741, test = "has" } }, zone = 1448, goals = {
					{ kind = "accept", quest = 8470 },
					{ kind = "turnin", quest = 8470 },
				} },
				{ title = "Winterfall Ritual Totem", tip = "The Winterfall furbolgs rarely drop a Winterfall Ritual Totem (3-4%). Kernda takes it in the tunnel too: 150 reputation and three Major Healing and Mana Potions.", when = { { item = 20742, test = "has" } }, zone = 1448, goals = {
					{ kind = "accept", quest = 8471 },
					{ kind = "turnin", quest = 8471 },
				} },
				{ title = "Neutral to Friendly", tip = "Neutral to Friendly is 3,000: 600 kills. Keep all feathers and beads.", zone = 1448, goals = {
					{ kind = "collect", item = 21377, count = 5, nearest = true, optional = true },
					{ kind = "collect", item = 21383, count = 5, nearest = true, optional = true },
					{ kind = "rep", factionId = 576, standing = "Friendly" },
				} },
				{ title = "Meilosh", tip = "Meilosh stands in the tunnel, near its Felwood mouth. From Friendly he sells: Recipe: Transmute Earth to Water (1 gold 50 silver), Formula: Enchant 2H Weapon - Agility (2 gold 50 silver), Pattern: Warbear Harness (1 gold 60 silver) and Warbear Woolies (2 gold). He also takes 30 Runecloth once for 100 reputation and a choice of shoulders or gauntlets, and Tailors with skill 290 can bring him 2 Mooncloth for 100 more and the Mooncloth Boots pattern.", zone = 1448, goals = {
					{ kind = "talk", npc = 11557 },
					{ kind = "accept", quest = 6031, optional = true, note = "Runecloth: 30 Runecloth" },
					{ kind = "buy", npc = 11557, item = 22392, optional = true, note = "Formula: Enchant 2H Weapon - Agility (Enchanting)" },
					{ kind = "buy", npc = 11557, item = 20253, optional = true, note = "Pattern: Warbear Harness (Leatherworking)" },
					{ kind = "buy", npc = 11557, item = 20254, optional = true, note = "Pattern: Warbear Woolies (Leatherworking)" },
					{ kind = "buy", npc = 11557, item = 13484, optional = true, note = "Recipe: Transmute Earth to Water (Alchemy)" },
				} },
				{ title = "Runecloth for Meilosh", tip = "Runecloth drops from the humanoids of the level 50-60 zones, the Deadwood and Winterfall furbolgs among them.", zone = 1448, goals = {
					{ kind = "collect", quest = 6031, objective = 1, item = 14047, count = 30 },
					{ kind = "turnin", quest = 6031 },
				} },
				{ title = "Sacred Cloth", tip = "Tailors with skill 290: Meilosh takes 2 Mooncloth once for 100 reputation and teaches the Mooncloth Boots.", when = { { profession = "Tailoring", value = 290, test = "skill" } }, zone = 1448, goals = {
					{ kind = "accept", quest = 6032, optional = true },
					{ kind = "turnin", quest = 6032, optional = true },
				} },
				{ title = "Friendly to Honored", tip = "Friendly to Honored is 6,000: 1,200 kills. Keep all feathers and beads. Honored opens at Meilosh: Formula: Enchant Weapon - Agility (3 gold), and for 2 gold 20 silver each Pattern: Heavy Timbermaw Belt and Might of the Timbermaw (Leatherworking) and Wisdom of the Timbermaw (Tailoring).", zone = 1448, goals = {
					{ kind = "collect", item = 21377, count = 5, nearest = true, optional = true },
					{ kind = "collect", item = 21383, count = 5, nearest = true, optional = true },
					{ kind = "rep", factionId = 576, standing = "Honored" },
				} },
				{ title = "Honored to Revered", tip = "Honored to Revered is 12,000: 2,400 kills, the last ones that count. Kills stop at 11,999 of 12,000 Honored and never tip you into Revered: when they stop, hand in one set of 5 feathers or beads to cross over. Saving every feather and bead pays off now: about 4,800 kills from the start to the end of Honored leave you with about 2,100 feathers and beads, and that is all of Revered to Exalted. Turning them in early would cost you about 2,400 more kills.", zone = 1448, goals = {
					{ kind = "buy", npc = 11557, item = 19445, optional = true, note = "Formula: Enchant Weapon - Agility (Enchanting), 3 gold" },
					{ kind = "collect", item = 21377, count = 5, nearest = true, optional = true },
					{ kind = "collect", item = 21383, count = 5, nearest = true, optional = true },
					{ kind = "turnin", quest = 8467, optional = true, direct = true, note = "Feathers for Nafien: once your kills stop, 5 feathers into Revered" },
					{ kind = "turnin", quest = 8469, mapHint = 1452, optional = true, direct = true, note = "Beads for Salfa: or 5 beads" },
					{ kind = "rep", factionId = 576, standing = "Revered" },
				} },
				{ title = "Revered to Exalted", tip = "Kills stopped at the end of Honored. Revered to Exalted is 21,000: 420 turn-ins, 2,100 feathers and beads. Hand in the feathers to Nafien at the tunnel or Grazle in the south, the beads to Salfa, five at a time. The named furbolgs (Ror, Bloodmaw, Ragepaw, Grizzle Snowpaw, High Chief Winterfall) still count. Revered opens at Meilosh, for 4 gold each: Pattern: Heavy Timbermaw Boots and Timbermaw Brawlers (Leatherworking) and Mantle of the Timbermaw (Tailoring).", zone = 1448, goals = {
					{ kind = "turnin", quest = 8467, optional = true, direct = true, note = "Feathers for Nafien: 5 feathers, 50 reputation" },
					{ kind = "turnin", quest = 8466, optional = true, direct = true, note = "Feathers for Grazle: 5 feathers, 50 reputation" },
					{ kind = "turnin", quest = 8469, mapHint = 1452, optional = true, direct = true, note = "Beads for Salfa: 5 beads, 50 reputation" },
					{ kind = "collect", item = 21377, count = 5, nearest = true, optional = true },
					{ kind = "collect", item = 21383, count = 5, nearest = true, optional = true },
					{ kind = "rep", factionId = 576, standing = "Exalted" },
				} },
				{ title = "The Root of All Evil", tip = "At Exalted, Gorn One Eye, in the tunnel by Meilosh, gives The Root of All Evil: plant his Demon Summoning Torch in the mouth of High Chief Winterfall's cave and defeat the demon Xandivious (level 62, elite: bring a group). The reward is Defender of the Timbermaw, a trinket that calls a Timbermaw ally, and 200 reputation.", when = { { quest = 8481, test = "group" } }, zone = 1448, goals = {
					{ kind = "accept", quest = 8481 },
				} },
				{ title = "Xandivious", tip = "Winterfall Village, the cave at the back. Clear the furbolgs around the mouth first, plant the torch, kill Xandivious and loot the Essence from his Demon Bag.", when = { { test = "onquest", quests = { 8481 } } }, zone = 1452, goals = {
					{ kind = "collect", quest = 8481, objective = 1, item = 21145, map = 1452, x = 69.8, y = 38.2, group = 5, note = "Essence of Xandivious" },
					{ kind = "kill", npc = 15623, map = 1452, x = 69.8, y = 38.2, group = 5, optional = true, note = "Xandivious, 25 reputation" },
				} },
				{ title = "Gorn One Eye", when = { { test = "onquest", quests = { 8481 } } }, zone = 1448, goals = {
					{ kind = "turnin", quest = 8481, rewards = { { item = 21326 } } },
				} },
