		{
			id = "forever/reputation/undercity", title = "Undercity Reputation", category = "Reputation", folder = "Reputation · Cities", faction = "Horde", levels = { 12, 60 }, zone = 1458, version = 1, revision = "6f13f5cd8541925b0c7253dc6cd1720a3953db71d8fe35492ab346ce2cd79d2c", legacyRevision = "7eaba02a78ef1b51b590ee34f31583e606892efd16ab8db3aaca9d0f85949c5b", keywords = { "Undercity", "Ralston Farnsley", "cloth quartermaster", "cloth donation", "Runecloth", "Additional Runecloth", "Wool", "Silk", "Mageweave", "Nathanos Blightcaller", "The Bulwark", "Scourge Cauldrons", "The Spider God", "Shadra", "Venom to the Undercity", "Deathknell", "Brill", "skeletal horse", "Zachariah Post" }, rewards = { { text = "Exalted with the Undercity" }, { item = 18791 } }, why = "Tirisfal quests while you level, the Plaguelands quests from 55, then Runecloth to Exalted.",
			steps = {
				{ title = "Undercity: how it works", tip = "Undercity reputation comes from quests and cloth. Ralston Farnsley, the cloth quartermaster, stands in the Magic Quarter beside the tailors. He takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with the Undercity also gives a quarter as much to Orgrimmar, Thunder Bluff and the Darkspear Trolls. While you level, do the Undercity's quests within 5 levels of them: Tirisfal at 1 to 12, Silverpine at 10 to 20, Hillsbrad and Tarren Mill at 20 to 33. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the Undercity's merchants sell to you for 10% less (the Classic rule), the horse vendor included; at Exalted other races can buy the skeletal horses: 20 gold for a level 40 horse, 200 gold for a level 60 warhorse, once you have mount training. The Undercity has no tabard or other reward.", zone = 1458, goals = {
					{ kind = "goto", label = "Ralston Farnsley", map = 1458, x = 71.7, y = 29.2, note = "his donations are handed in from his window and never enter the log" },
				} },
				{ title = "Deathknell (optional hub)", tip = "Forever pays these old quests in full at any level. Deathknell, the Forsaken start at the west end of Tirisfal: about 900 Undercity reputation in 25 minutes. Starting-zone quests give the other cities no share. Novice Elreth, Executor Arren and Deathguard Saltain stand in the village.", label = "deathknell", zone = 1420, goals = {
					{ kind = "accept", quest = 376, note = "Novice Elreth: The Damned, +100" },
					{ kind = "collect", quest = 376, objective = 1, item = 3265, count = 6, note = "Scavenger Paw" },
					{ kind = "collect", quest = 376, objective = 2, item = 3264, count = 6, note = "Duskbat Wing" },
					{ kind = "turnin", quest = 376 },
				} },
				{ title = "Deathknell: the next quests", when = { { label = "deathknell", test = "done" } }, zone = 1420, goals = {
					{ kind = "accept", quest = 3902, note = "Deathguard Saltain: Scavenging Deathknell, +150" },
					{ kind = "accept", quest = 380, note = "Executor Arren: Night Web's Hollow, +100" },
					{ kind = "accept", quest = 6395, note = "Novice Elreth: Marla's Last Wish, +100" },
					{ kind = "accept", quest = 98389, note = "A Light in the Darkness, +100" },
				} },
				{ title = "Around Deathknell", tip = "The Equipment Boxes are all around the village. Night Web's Hollow is the mine north-west; the Webbed Forsaken hang inside. Samuel Fipps waits at the ruined camp by the road north-east: bury his remains at Marla's Grave, in the front row of the village graveyard.", when = { { label = "deathknell", test = "done" } }, zone = 1420, goals = {
					{ kind = "collect", quest = 3902, objective = 1, item = 11127, count = 6, note = "Scavenged Goods" },
					{ kind = "kill", quest = 380, objective = 1, npc = 1504, count = 10, note = "Young Night Web Spider" },
					{ kind = "kill", quest = 380, objective = 2, npc = 1505, count = 8, note = "Night Web Spider" },
					{ kind = "kill", quest = 98389, objective = 1, npc = 271961, count = 6, note = "Webbed Forsaken freed" },
					{ kind = "interact", quest = 6395, objective = 1, object = 178090, note = "Marla's Grave, with Samuel's Remains" },
				} },
				{ title = "Deathknell: hand in", when = { { label = "deathknell", test = "done" } }, zone = 1420, goals = {
					{ kind = "turnin", quest = 3902 },
					{ kind = "turnin", quest = 380 },
					{ kind = "accept", quest = 381, note = "The Scarlet Crusade, +100" },
