				} },
				{ title = "Ralston Farnsley: A Donation of Wool", tip = "From here it is cloth. Wool, Silk and Mageweave must all be handed in before Ralston offers the Runecloth donation, and Additional Runecloth needs the Runecloth donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, Runecloth 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey.", zone = 1440, goals = {
					{ kind = "collect", item = 2592, count = 60, map = 1440, x = 36, y = 37, note = "Wool Cloth: the Thistlefur furbolgs drop it about one kill in four" },
					{ kind = "turnin", quest = 7813, direct = true, note = "Ralston Farnsley: A Donation of Wool, +150" },
				} },
				{ title = "A Donation of Silk", tip = "Silk: the Syndicate in Hillsbrad and Alterac drop it about one kill in three, or buy it.", zone = 1440, goals = {
					{ kind = "level", level = 26 },
					{ kind = "collect", item = 4306, count = 60, map = 1416, x = 57.7, y = 67.6, note = "Silk Cloth: the Syndicate" },
					{ kind = "turnin", quest = 7814, direct = true, note = "+150" },
				} },
				{ title = "A Donation of Mageweave", tip = "Mageweave: the Jadefire satyrs in southern Felwood and the Dunemaul ogres in Tanaris drop it about one kill in three, or buy it.", zone = 1416, goals = {
					{ kind = "level", level = 40 },
