				{ title = "Felstone Field and the Andorhal towers", tip = "Cauldron Lord Bilemaw guards the cauldron at Felstone Field. Click the cauldron after the kill to start Return to the Bulwark. Mark the four towers of Andorhal with the Beacon Torch at their doors.", zone = 1422, goals = {
					{ kind = "collect", quest = 5229, objective = 1, item = 13194, note = "Felstone Field Cauldron Key" },
