					{ kind = "kill", quest = 5098, objective = 1, npc = 10902, text = "Mark Andorhal Tower One with the Beacon Torch", map = 1422, x = 40.05, y = 71.6, note = "Andorhal Tower One: use the Beacon Torch at the door" },
					{ kind = "kill", quest = 5098, objective = 2, npc = 10903, text = "Mark Andorhal Tower Two with the Beacon Torch", map = 1422, x = 42.33, y = 66.24, note = "Andorhal Tower Two" },
