				} },
				{ title = "Nathanos Blightcaller", tip = "Nathanos Blightcaller, the Ranger Lord, keeps his camp on the western edge of the Eastern Plaguelands. His quests are level 58 to 60 and pay in full: 500 Undercity reputation.", zone = 1423, goals = {
					{ kind = "level", level = 56 },
					{ kind = "accept", quest = 6042, note = "Un-Life's Little Annoyances, +100" },
					{ kind = "accept", quest = 6022, note = "To Kill With Purpose, +100" },
					{ kind = "accept", quest = 6133, note = "The Ranger Lord's Behest, +100" },
				} },
				{ title = "Plaguebats, Quel'Lithien Lodge and Corin's Crossing", tip = "The Noxious Plaguebats fly in the south of the zone, the Monstrous Plaguebats further north-west. Quel'Lithien Lodge is north-west of Light's Hope Chapel; the Quel'Thalas Registry lies inside. Do Corin's Crossing last: its Scourge drop Living Rot, which lasts only 10 minutes. With 7 in your bags, use the Mortar and Pestle at once for the Coagulated Rot.", zone = 1423, goals = {
					{ kind = "kill", quest = 6042, objective = 1, npc = 8601, count = 20, note = "Noxious Plaguebat" },
					{ kind = "kill", quest = 6042, objective = 2, npc = 8602, count = 10, note = "Monstrous Plaguebat" },
					{ kind = "kill", quest = 6133, objective = 2, npc = 8564, count = 8, note = "Ranger" },
					{ kind = "kill", quest = 6133, objective = 1, npc = 8565, count = 8, note = "Pathstrider" },
