					{ kind = "collect", quest = 6022, objective = 1, item = 15448, map = 1423, x = 52.6, y = 58.6, note = "Coagulated Rot: 7 Living Rot and the Mortar and Pestle" },
				} },
				{ title = "Nathanos: hand in", zone = 1423, goals = {
					{ kind = "turnin", quest = 6042 },
					{ kind = "turnin", quest = 6022 },
					{ kind = "turnin", quest = 6133 },
					{ kind = "accept", quest = 6135, note = "Duskwing, Oh How I Hate Thee..., +100" },
