				{ title = "Duskwing and Borelgore", tip = "Duskwing, an elite bat, roams the fields north of Marris Stead. Borelgore paces a long valley west of Northdale.", zone = 1423, goals = {
					{ kind = "collect", quest = 6135, objective = 1, item = 15850, note = "Patch of Duskwing's Fur" },
					{ kind = "kill", quest = 6136, objective = 1, npc = 11896, note = "Borelgore" },
					{ kind = "turnin", quest = 6135, note = "Nathanos Blightcaller" },
					{ kind = "turnin", quest = 6136 },
					{ kind = "note", text = "Nathanos: 500 Undercity reputation. His Stratholme quests (The Crimson Courier, The Scarlet Oracle, Demetria, Ramstein) need a group." },
				} },
				{ title = "The Spider God (optional chain)", tip = "Six quests across the Hinterlands, Tarren Mill, Sen'jin Village, Zul'Farrak and the Undercity: 600 Undercity and 225 Darkspear reputation. Summoning Shadra and Venom to the Undercity are level 55 and pay 400 in full at 60; the four before them are level 43 to 45 and pay in full too. Allow about 90 minutes with the travel. The Venom Bottles stand on the tables of the Witherbark village in the west of the Hinterlands: click one to start.", label = "shadra", zone = 1425, goals = {
					{ kind = "accept", quest = 2933, object = 142702, note = "Venom Bottle: Venom Bottles, +100" },
				} },
				{ title = "Tarren Mill: Apothecary Lydon", when = { { label = "shadra", test = "done" } }, zone = 1424, goals = {
					{ kind = "turnin", quest = 2933, note = "Apothecary Lydon" },
					{ kind = "accept", quest = 2934, note = "Undamaged Venom Sac, +100" },
				} },
				{ title = "Shadra'Alor: an Undamaged Venom Sac", tip = "The Witherbark Broodguards crawl around Shadra'Alor in the south-west of the Hinterlands; about one in ten carries an undamaged sac.", when = { { label = "shadra", test = "done" } }, zone = 1425, goals = {
					{ kind = "collect", quest = 2934, objective = 1, item = 9322, note = "Undamaged Venom Sac, from Witherbark Broodguards" },
				} },
				{ title = "Tarren Mill, then Sen'jin Village", when = { { label = "shadra", test = "done" } }, zone = 1425, goals = {
					{ kind = "turnin", quest = 2934, note = "Apothecary Lydon" },
					{ kind = "accept", quest = 2935, note = "Consult Master Gadrin, +75 Darkspear" },
					{ kind = "turnin", quest = 2935, note = "Master Gadrin, in Sen'jin Village" },
					{ kind = "accept", quest = 2936, note = "The Spider God, +150 Darkspear" },
				} },
				{ title = "Zul'Farrak: the Tablet of Theka", tip = "Zul'Farrak is a level 44 to 54 dungeon in northern Tanaris; a level 60 can clear the way alone, or bring a group. Theka the Martyr, an elite troll, guards his tomb in the instance: kill him and read the Tablet of Theka there.", when = { { label = "shadra", test = "done" } }, zone = 1446, goals = {
					{ kind = "goto", label = "Zul'Farrak", map = 1446, x = 38.7, y = 20 },
					{ kind = "complete", quest = 2936, note = "read the Tablet of Theka" },
