				{ title = "Sen'jin Village: Gadrin's Parchment", when = { { label = "shadra", test = "done" } }, zone = 1411, goals = {
					{ kind = "turnin", quest = 2936, note = "Master Gadrin" },
					{ kind = "accept", quest = 2937, note = "Summoning Shadra, +200" },
				} },
				{ title = "Shadra'Alor: Shadra", tip = "Read Gadrin's Parchment at the altar of Shadra'Alor to call Shadra, an elite level 55 spider: she drops her venom every time.", when = { { label = "shadra", test = "done" } }, zone = 1425, goals = {
					{ kind = "collect", quest = 2937, objective = 1, item = 9324, map = 1425, x = 33.8, y = 73, note = "Shadra's Venom, from Shadra" },
				} },
				{ title = "Tarren Mill and the Undercity", when = { { label = "shadra", test = "done" } }, zone = 1425, goals = {
					{ kind = "turnin", quest = 2937, note = "Apothecary Lydon" },
					{ kind = "accept", quest = 2938, note = "Venom to the Undercity, +200" },
					{ kind = "turnin", quest = 2938, note = "Master Apothecary Faranell, in the Apothecarium" },
				} },
				{ title = "Additional Runecloth to Honored", tip = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (an Undead starts at Friendly 1,000: 100 hand-ins; every other race starts at Neutral 500 and first needs 50 hand-ins, 1,000 Runecloth, to reach Friendly). Hand in every 20 you carry, one after another.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
					{ kind = "turnin", quest = 7819, optional = true, direct = true, note = "Ralston Farnsley: Additional Runecloth, +50" },
					{ kind = "rep", factionId = 68, standing = "Honored" },
				} },
				{ title = "Additional Runecloth to Revered", tip = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth. The Darkstone Tablet (Blackrock Depths) pays 150 in full.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7819, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "rep", factionId = 68, standing = "Revered" },
				} },
				{ title = "Additional Runecloth to Exalted", tip = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, Zachariah Post in Brill sells the skeletal horses to every Horde race: 20 gold for a level 40 horse, 200 gold for a level 60 warhorse (Forever's prices); in Classic other races needed Exalted to buy them.", zone = 1423, goals = {
					{ kind = "collect", item = 14047, count = 20, map = 1423, x = 68, y = 69.5, frame = "live", optional = true, note = "Runecloth" },
					{ kind = "turnin", quest = 7819, optional = true, direct = true, note = "Additional Runecloth, +50" },
					{ kind = "rep", factionId = 68, standing = "Exalted" },
					{ kind = "talk", npc = 4731, optional = true, note = "Zachariah Post: the skeletal horses" },
				} },
			},
		},
		{
			id = "forever/reputation/warsong-gulch", title = "Warsong Gulch Reputation", category = "Reputation", folder = "Reputation · Battlegrounds", levels = { 10, 60 }, zone = 1440, version = 1, revision = "b14d8bb3756dd2b6d94127185c345046ef36e82e35e18020b56c0649e833f231", legacyRevision = "2bab2dfde29e7ac23e7ed19e2ba35f437ac53cba46dcccbc95af6dc1408fe51c", keywords = { "Silverwing Sentinels", "Warsong Outriders", "Warsong Gulch", "Sentinel Farsong", "Captain Shatterskull", "Illiyana Moonblaze", "Kelm Hargunth", "Warsong Gulch Mark of Honor", "Vanquish the Invaders", "Quell the Silverwing Usurpers", "Fight for Warsong Gulch", "Battle of Warsong Gulch", "Berserker Bracers", "Silverwing Battle Tabard", "Warsong Battle Tabard", "Master of Warsong Gulch", "Legacy Point" }, collects = { 19506, 19505 }, rewards = { { text = "Master of Warsong Gulch: a Legacy Point at Exalted" }, { item = 19578, choice = true }, { item = 19582, choice = true }, { item = 19587, choice = true }, { item = 19595, choice = true }, { item = 19506 }, { item = 19505 } }, why = "Flag captures and Marks of Honor raise it; Exalted gives a Legacy Point and epic bracers and legs.",
			steps = {
				{ title = "Sentinel Farsong", tip = "Warsong Gulch is a 10 against 10 capture-the-flag battle, from level 10. Queue at any battlemaster in the capitals or from the battleground screen. In Classic every flag your team captures pays everyone 35 reputation (45 on the Warsong Gulch holiday weekend), and a game pays 3 Warsong Gulch Marks of Honor for a win, 1 for a loss. Sentinel Farsong pays 200 reputation for one mark, once per character: the best mark you will ever turn in. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Alliance" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1440, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 7873 },
					{ kind = "collect", quest = 7873, objective = 1, item = 20558, map = 1440, x = 61.9, y = 83.9, note = "one Warsong Gulch Mark of Honor: play a game" },
					{ kind = "turnin", quest = 7873 },
				} },
				{ title = "Alliance Brigadier General", tip = "The Alliance Brigadier General pays 100 reputation for 3 Warsong Gulch Marks of Honor the first time, then 50 for every 3 more (Fight for Warsong Gulch). One stands right here at Silverwing Grove beside Sentinel Farsong; others in Stormwind, Ironforge and Darnassus, at Refuge Pointe in the Arathi Highlands and at both gates of Alterac Valley. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Warsong Gulch marks: hand in or spend them before you reach that.", only = { factions = { "Alliance" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1440, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8402 },
					{ kind = "collect", quest = 8402, objective = 1, item = 20558, count = 3, map = 1440, x = 61.9, y = 83.9, note = "three Warsong Gulch Marks of Honor" },
					{ kind = "turnin", quest = 8402 },
				} },
				{ title = "Silverwing Sentinels to Friendly", tip = "Neutral to Friendly is 3000 reputation. In Classic a 3-capture win paid 105, and its 3 marks bring 50 more at the Brigadier General: about 155 a win, so some 20 wins. Losses still pay 35 for each flag your team captured. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50, Sentinel Farsong's one-mark quest and the Brigadier General's Fight for Warsong Gulch come in a version for your bracket (from 20 and from 10): 200 once, then 100 and 50 per 3 marks.", only = { factions = { "Alliance" } }, zone = 1440, goals = {
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: Fight for Warsong Gulch again, 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 890, standing = "Friendly" },
				} },
				{ title = "Silverwing Sentinels to Honored", tip = "Friendly to Honored is 6000 reputation, about 39 wins at the Classic rate. Friendly opens the first rewards at Illiyana Moonblaze beside Sentinel Farsong: the Rune of Duty and Rune of Perfection trinkets (2g at level 20, 4g at level 40) and food, bandages and draughts that work in the battleground (5s to 20s). She also gives one Sentinel care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages.", only = { factions = { "Alliance" } }, zone = 1440, goals = {
					{ kind = "talk", npc = 14753, optional = true, note = "Illiyana Moonblaze: Friendly rewards" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 890, standing = "Honored" },
				} },
				{ title = "Silverwing Sentinels to Revered", tip = "Honored to Revered is 12000 reputation, about 78 wins. Honored opens the Caretaker's Cape (cloak), Sentinel's Medallion (neck), Lorekeeper's Ring and Protector's Band, each sold for levels 18, 28, 38, 48 and 58 (cloak 36s50c to 8g55s, the rest 2g to 7g50s), and the Major Healing and Mana Draughts (10s).", only = { factions = { "Alliance" } }, zone = 1440, goals = {
					{ kind = "talk", npc = 14753, optional = true, note = "Illiyana Moonblaze: Honored rewards" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 890, standing = "Revered" },
				} },
				{ title = "Silverwing Sentinels to Exalted", tip = "Revered to Exalted is 21000 reputation, about 136 wins: half of the whole climb. Revered opens the weapons for levels 18 to 58: Sentinel's Blade (dagger), Protector's Sword, Outrunner's Bow and Lorekeeper's Staff (91s to 35g61s). Forever's quartermaster also sells level-25 versions of the four weapons, Resilient helms for level 20 (2g50s) and the Trainee's Sentinel Nightsaber mount (level 25, 10g) with no standing listed.", only = { factions = { "Alliance" } }, zone = 1440, goals = {
					{ kind = "talk", npc = 14753, optional = true, note = "Illiyana Moonblaze: Revered rewards" },
					{ kind = "talk", npc = 15351, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 890, standing = "Exalted" },
				} },
				{ title = "Illiyana Moonblaze", tip = "Exalted gives the Legacy Point \"Master of Warsong Gulch\" and opens the epics: Berserker Bracers (plate), Windtalker's Wristguards (mail), Forest Stalker's Bracers (leather) and Dryad's Wrist Bindings (cloth) for levels 40, 50 and 60 (2g47s to 12g11s), and the level 60 Sentinel's legs in plate, lamellar, chain, leather, lizardhide and silk (16g63s to 24g22s). The Silverwing Battle Tabard is 5g.", only = { factions = { "Alliance" } }, zone = 1440, goals = {
					{ kind = "buy", item = 19506, note = "Silverwing Battle Tabard, 5g" },
				} },
				{ title = "Captain Shatterskull", tip = "Warsong Gulch is a 10 against 10 capture-the-flag battle, from level 10. Queue at any battlemaster in the capitals or from the battleground screen; the Horde gate is here at Mor'shan Base Camp. In Classic every flag your team captures pays everyone 35 reputation (45 on the Warsong Gulch holiday weekend), and a game pays 3 Warsong Gulch Marks of Honor for a win, 1 for a loss. Captain Shatterskull pays 200 reputation for one mark, once per character: the best mark you will ever turn in. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = { "Horde" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1413, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 7876 },
					{ kind = "collect", quest = 7876, objective = 1, item = 20558, map = 1413, x = 46.6, y = 8.4, note = "one Warsong Gulch Mark of Honor: play a game" },
					{ kind = "turnin", quest = 7876 },
				} },
				{ title = "Horde Warbringer", tip = "The Horde Warbringer pays 100 reputation for 3 Warsong Gulch Marks of Honor the first time, then 50 for every 3 more (Battle of Warsong Gulch). One stands right here at Mor'shan; others in Orgrimmar, Thunder Bluff (and on the plain below it) and the Undercity, at Hammerfall in the Arathi Highlands and at the Alterac Valley gate in the Alterac Mountains. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Warsong Gulch marks: hand in or spend them before you reach that.", only = { factions = { "Horde" } }, when = { { level = 50, test = "level", op = ">=" } }, zone = 1413, goals = {
					{ kind = "level", level = 50 },
					{ kind = "accept", quest = 8429 },
					{ kind = "collect", quest = 8429, objective = 1, item = 20558, count = 3, map = 1413, x = 46.6, y = 8.4, note = "three Warsong Gulch Marks of Honor" },
					{ kind = "turnin", quest = 8429 },
				} },
				{ title = "Warsong Outriders to Friendly", tip = "Neutral to Friendly is 3000 reputation. In Classic a 3-capture win paid 105, and its 3 marks bring 50 more at the Warbringer: about 155 a win, so some 20 wins. Losses still pay 35 for each flag your team captured. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50, Captain Shatterskull's one-mark quest and the Warbringer's Battle of Warsong Gulch come in a version for your bracket (from 20 and from 10): 200 once, then 100 and 50 per 3 marks.", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: Battle of Warsong Gulch again, 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 889, standing = "Friendly" },
				} },
				{ title = "Warsong Outriders to Honored", tip = "Friendly to Honored is 6000 reputation, about 39 wins at the Classic rate. Friendly opens the first rewards at Kelm Hargunth beside Captain Shatterskull: the Rune of Duty and Rune of Perfection trinkets (2g at level 20, 4g at level 40) and food, bandages and draughts that work in the battleground (5s to 20s). He also gives one Outrider care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages.", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "talk", npc = 14754, optional = true, note = "Kelm Hargunth: Friendly rewards" },
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 889, standing = "Honored" },
				} },
				{ title = "Warsong Outriders to Revered", tip = "Honored to Revered is 12000 reputation, about 78 wins. Honored opens the Battle Healer's Cloak, Scout's Medallion (neck), Advisor's Ring and Legionnaire's Band, each sold for levels 18, 28, 38, 48 and 58 (cloak 36s50c to 9g6s, the rest 2g to 7g50s), and the Major Healing and Mana Draughts (10s).", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "talk", npc = 14754, optional = true, note = "Kelm Hargunth: Honored rewards" },
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 889, standing = "Revered" },
				} },
				{ title = "Warsong Outriders to Exalted", tip = "Revered to Exalted is 21000 reputation, about 136 wins: half of the whole climb. Revered opens the weapons for levels 18 to 58: Scout's Blade (dagger), Legionnaire's Sword, Outrider's Bow and Advisor's Gnarled Staff (91s to 35g9s). Forever's quartermaster also sells level-25 versions of the four weapons, Resilient helms for level 20 (2g50s) and the Trainee's Outrider Wolf mount (level 25, 10g) with no standing listed.", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "talk", npc = 14754, optional = true, note = "Kelm Hargunth: Revered rewards" },
					{ kind = "talk", npc = 15350, optional = true, note = "Horde Warbringer: 50 reputation for 3 marks" },
					{ kind = "rep", factionId = 889, standing = "Exalted" },
				} },
				{ title = "Kelm Hargunth", tip = "Exalted gives the Legacy Point \"Master of Warsong Gulch\" and opens the epics: Berserker Bracers (plate), Windtalker's Wristguards (mail), Forest Stalker's Bracers (leather) and Dryad's Wrist Bindings (cloth) for levels 40, 50 and 60 (2g47s to 12g11s), and the level 60 Outrider's legs in plate, chain, mail, leather, lizardhide and silk (16g57s to 25g33s). The Warsong Battle Tabard is 5g.", only = { factions = { "Horde" } }, zone = 1413, goals = {
					{ kind = "buy", item = 19505, note = "Warsong Battle Tabard, 5g" },
				} },
			},
