		{
			id = "forever/reputation/wintersaber-trainers", title = "Wintersaber Trainers Reputation", category = "Reputation", folder = "Reputation · World", faction = "Alliance", levels = { 58, 60 }, zone = 1452, next = "forever/collectibles/mounts/alliance/winterspring-frostsaber", version = 1, revision = "7b651a867b4c5bed2e0011fdc1a8265e4680ad4278bc711c7ae4581855c2c356", keywords = { "Wintersaber Trainers", "Rivern Frostwind", "Frostsaber Rock", "Frostsaber Provisions", "Winterfall Intrusion", "Rampaging Giants", "Shardtooth Meat", "Chillwind Meat", "Winterfall Village", "Frostmaul giants", "Reins of the Winterspring Frostsaber", "saber mount", "Timbermaw Hold" }, rewards = { { item = 13086 }, { text = "Timbermaw Hold reputation on the side: 50 and about 4 Winterfall Spirit Beads per Winterfall Intrusion" } }, why = "The Winterspring Frostsaber: 840 quest turn-ins in Winterspring, with Timbermaw reputation on the side.",
			steps = {
				{ title = "Rivern Frostwind", tip = "Rivern Frostwind stands on top of Frostsaber Rock, in the far north of Winterspring; the path winds up from the east side. Only the Alliance can earn the Wintersaber Trainers' favour, from Neutral, at level 58. All three of her quests pay 50 and repeat as often as you like: 840 turn-ins from Neutral to Exalted. The first one, Frostsaber Provisions, is the only one open at the start.", zone = 1452, goals = {
					{ kind = "accept", quest = 4970 },
				} },
				{ title = "Shardtooth and Chillwind meat", tip = "The meat only drops while the quest is in your log, and a group shares no loot: farm it alone. The best droppers live right below the rock: Elder Shardtooth bears (about half the time) and Chillwind Ravagers (half the time) roam the snowfields east and south-east of it. Around Everlook the Chillwind Chimaeras drop it as often and the Shardtooth Bears a little less; the Rabid Shardtooth by the giants' gorge in the south drop it most often (six in ten).", zone = 1452, goals = {
					{ kind = "collect", quest = 4970, objective = 1, item = 12622, count = 5, note = "Shardtooth Meat: the bears" },
					{ kind = "collect", quest = 4970, objective = 2, item = 12623, count = 5, note = "Chillwind Meat: the chimaeras" },
				} },
				{ title = "Back to Rivern Frostwind", zone = 1452, goals = {
					{ kind = "turnin", quest = 4970 },
				} },
				{ title = "Neutral to Friendly: Frostsaber Provisions, then Winterfall Intrusion", tip = "Repeat Frostsaber Provisions: 30 turn-ins reach Neutral 1,500, and then Winterfall Intrusion opens: 5 Winterfall Shamans and 5 Winterfall Ursas in Winterfall Village, just east of Everlook. The village has only a few Shamans, but every furbolg there shares their spawn points: kill all of them, not just the ones you need, and more Shamans and Ursas appear; more Ursas walk the ridge just south-west of the village. Take both quests on every trip: kill the furbolgs, pick up meat on the way back. Neutral to Friendly is 60 turn-ins.", zone = 1452, goals = {
					{ kind = "accept", quest = 4970, optional = true },
					{ kind = "accept", quest = 5201, optional = true },
					{ kind = "collect", quest = 4970, objective = 1, item = 12622, count = 5, optional = true },
					{ kind = "collect", quest = 4970, objective = 2, item = 12623, count = 5, optional = true },
					{ kind = "kill", quest = 5201, objective = 1, npc = 7439, optional = true, note = "Winterfall Shaman" },
					{ kind = "kill", quest = 5201, objective = 2, npc = 7438, optional = true, note = "Winterfall Ursa" },
					{ kind = "turnin", quest = 4970, optional = true },
					{ kind = "turnin", quest = 5201, optional = true },
					{ kind = "rep", factionId = 589, standing = "Friendly" },
				} },
				{ title = "Friendly to Honored", tip = "Friendly to Honored is 6,000: 120 turn-ins. Winterfall Intrusion is the quickest; do Frostsaber Provisions when the village is crowded or you pass the bears and chimaeras anyway. Every Winterfall furbolg you kill counts for Timbermaw Hold too: 50 Timbermaw reputation per Winterfall Intrusion up to the end of Honored with them, and about four Winterfall Spirit Beads. Take Salfa's Winterfall Activity (the Timbermaw guide) the first time you are in the village, and keep the beads until your Timbermaw kills stop counting: then each 5 pay 50. You will reach Exalted with the Timbermaw long before the Wintersaber Trainers.", zone = 1452, goals = {
					{ kind = "accept", quest = 4970, optional = true },
					{ kind = "accept", quest = 5201, optional = true },
					{ kind = "collect", quest = 4970, objective = 1, item = 12622, count = 5, optional = true },
					{ kind = "collect", quest = 4970, objective = 2, item = 12623, count = 5, optional = true },
					{ kind = "kill", quest = 5201, objective = 1, npc = 7439, optional = true },
					{ kind = "kill", quest = 5201, objective = 2, npc = 7438, optional = true },
					{ kind = "turnin", quest = 4970, optional = true },
					{ kind = "turnin", quest = 5201, optional = true },
					{ kind = "rep", factionId = 589, standing = "Honored" },
				} },
				{ title = "Honored to Exalted: Rampaging Giants too", tip = "At Honored Rivern Frostwind adds Rampaging Giants: 4 Frostmaul Giants and 4 Frostmaul Preservers, elite giants in Frostwhisper Gorge in the south-east of Winterspring; the path down into the gorge starts at its north-west end. Take it on a trip south with a friend or two, or when Winterfall Village is crowded; the Rabid Shardtooth by the gorge drop Shardtooth Meat most often. Honored to Exalted is 33,000: 660 turn-ins.", zone = 1452, goals = {
					{ kind = "accept", quest = 4970, optional = true },
					{ kind = "accept", quest = 5201, optional = true },
					{ kind = "accept", quest = 5981, optional = true },
					{ kind = "kill", quest = 5201, objective = 1, npc = 7439, optional = true },
					{ kind = "kill", quest = 5201, objective = 2, npc = 7438, optional = true },
					{ kind = "kill", quest = 5981, objective = 1, npc = 7428, group = 3, optional = true, note = "Frostmaul Giant, elite" },
					{ kind = "kill", quest = 5981, objective = 2, npc = 7429, group = 3, optional = true, note = "Frostmaul Preserver, elite" },
					{ kind = "collect", quest = 4970, objective = 1, item = 12622, count = 5, optional = true },
					{ kind = "collect", quest = 4970, objective = 2, item = 12623, count = 5, optional = true },
