		{
			id = "forever/reputation/zandalar-tribe", title = "Zandalar Tribe Reputation", category = "Reputation", folder = "Reputation · Raids and dungeons", levels = { 60, 60 }, zone = 1434, version = 1, revision = "421e7ae064f7d7bcdf98209560fa4d522b65885f37a1dca9eb116782b29a3105", keywords = { "Zandalar Tribe", "Yojamba Isle", "Zul'Gurub", "Vinchaxa", "Rin'wosho the Trader", "Zanza the Restless", "Zandalar Honor Token", "Hakkari Bijou", "Zulian Coin", "Razzashi Coin", "Hakkari Coin", "Gurubashi Coin", "Primal Hakkari Idol", "Paragons of Power", "Zandalar Signet of Might", "Zandalar Signet of Mojo", "Zandalar Signet of Serenity", "shoulder enchant", "Savage Guard", "Arcanum", "class necklace", "Hakkar" }, rewards = { { item = 20077, choice = true }, { item = 20076, choice = true }, { item = 20078, choice = true }, { text = "Your class's necklace at Friendly, upgraded at Honored, Revered and Exalted" }, { text = "Zanza's head and leg enchants, from Friendly" } }, why = "Shoulder and head enchants, a class necklace upgraded at every standing, and Zul'Gurub's set pieces.",
			steps = {
				{ title = "Yojamba Isle", tip = "Yojamba Isle is the small island off the north-west coast of Stranglethorn Vale, west of the Zuuldaia Ruins: swim over from the coast. Everyone starts Neutral with the Zandalar Tribe. Vinchaxa takes coins and bijous, Rin'wosho the Trader sells the recipes and trades Honor Tokens, and Jin'rokh, Al'tabim, Maywiki and Falthir hand out the class necklaces and the set pieces. Almost all Zandalar reputation comes from Zul'Gurub, a 20-player raid, and Zul'Gurub is not among the first raids Blizzard has announced for Forever: until it opens there is no Zandalar reputation to earn, and no coins or bijous on the auction house either. Once it is open, the only solo way is buying coins and bijous on the auction house (75 per bijou, 25 per set of three coins). The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it.", zone = 1434, goals = {
					{ kind = "accept", quest = 8240, note = "Vinchaxa: A Bijou for Zanza" },
				} },
				{ title = "Zul'Gurub to Friendly", tip = "Zul'Gurub is the troll city in the north-east of Stranglethorn Vale: a 20-player raid. Trash pays 3 to 5 each until 11,999 of 12,000 Honored, one point short of Revered; the Speakers 15, Ohgan 15, the Edge of Madness boss 25, Gahz'ranka and the five High Priests 100, Bloodlord Mandokir and Jin'do 200 and Hakkar 400, all the way to Exalted. A full clear is about 4,050: one clear reaches Friendly (3,000). Loot every coin, bijou, Primal Hakkari Idol, Channeler's Head and Primal Hakkari set piece. Coins and bijous pay the same at any standing: save them until the trash stops counting, except one bijou for A Bijou for Zanza.", zone = 1434, goals = {
					{ kind = "collect", item = 19707, optional = true, note = "Red Hakkari Bijou; any of the nine colours does" },
					{ kind = "rep", factionId = 270, standing = "Friendly" },
				} },
				{ title = "A Bijou for Zanza", tip = "Destroy one bijou at the Altar of Zanza, the stone altar on the west side of Yojamba Isle (right-click the bijou there), then tell Vinchaxa: 150 reputation and an extra Zandalar Honor Token, once. From then on every bijou you destroy at the altar pays 75 reputation and a token, and every set of three coins Vinchaxa takes pays 25 and a token. They never stop counting.", zone = 1434, goals = {
					{ kind = "turnin", quest = 8240, optional = true, note = "Vinchaxa: 150" },
				} },
				{ title = "Friendly: your class necklace", tip = "At Friendly your class's trainer on the isle gives a necklace for free (100 reputation); the same NPC upgrades it at Honored, Revered and Exalted (100 each) with no raid item needed. Friendly also opens Rin'wosho's first recipes (Pattern: Bloodvine Boots, Primal Batskin Bracers, Plans: Bloodsoul Gauntlets, Darksoul Shoulders, Schematic: Bloodvine Lens, Recipe: Greater Dreamless Sleep, 5g each; Formula: Brilliant Mana Oil, 4g) and the Paragons of Power bracers (150 for the Primal Hakkari bracer token of your class).", zone = 1434, goals = {
					{ kind = "accept", quest = 8041, optional = true, only = { classes = { "Warrior" } }, note = "Jin'rokh the Breaker: Strength of Mugamba, Friendly" },
					{ kind = "turnin", quest = 8041, optional = true, only = { classes = { "Warrior" } }, note = "100" },
					{ kind = "accept", quest = 8045, optional = true, only = { classes = { "Paladin" } }, note = "Jin'rokh the Breaker: Heathen's Brand, Friendly" },
					{ kind = "turnin", quest = 8045, optional = true, only = { classes = { "Paladin" } }, note = "100" },
					{ kind = "accept", quest = 8049, optional = true, only = { classes = { "Priest" } }, note = "Al'tabim the All-Seeing: The Eye of Zuldazar, Friendly" },
					{ kind = "turnin", quest = 8049, optional = true, only = { classes = { "Priest" } }, note = "100" },
